           Subscript[q, 13]*(8*(-1 + D)*Subscript[m, Hp]^2 + 
             D*(-Subscript[m, Z]^2 + 2*Subscript[q, 13] + Subscript[q, 
                23])) - Subscript[m, h0]^2*(8*(-1 + D)*Subscript[m, Hp]^2 + 
             D*(5*Subscript[m, Z]^2 + 2*Subscript[q, 12] + 5*Subscript[q, 
                 13] + Subscript[q, 23])))))/(32*D*Pi^2), 
     "f2Hbox" -> (Subscript[g, H0HH]*Subscript[g, hHH]*
