              Subscript[q, 13], Subscript[m, Hp]^2, Subscript[m, Hp]^2, 
             Subscript[m, Hp]^2, Subscript[m, Hp]^2]*Subscript[m, Hp]^2)*
          (Subscript[m, h0]^2 + Subscript[m, Z]^2 - Subscript[q, 23])))/
