      OptionValue[BReduce] && FCPatternFreeQ[
       {FeynCalc`PaVeIntegrals`Private`pp, 
        FeynCalc`PaVeIntegrals`Private`mm1, 
        FeynCalc`PaVeIntegrals`Private`mm2}] && 
       !MatchQ[{FeynCalc`PaVeIntegrals`Private`pp, 
         FeynCalc`PaVeIntegrals`Private`mm1, 
         FeynCalc`PaVeIntegrals`Private`mm2}, {0, 0, 0}]
 
B00[FeynCalc`PaVeIntegrals`Private`pp_, FeynCalc`PaVeIntegrals`Private`mm1_, 
     FeynCalc`PaVeIntegrals`Private`mm2_, OptionsPattern[]] := 
    PaVeReduce[PaVe[0, 0, {FeynCalc`PaVeIntegrals`Private`pp}, 
       {FeynCalc`PaVeIntegrals`Private`mm1, 
        FeynCalc`PaVeIntegrals`Private`mm2}], PaVeAutoReduce -> True] /; 
      !$LimitTo4 && OptionValue[BReduce] && FCPatternFreeQ[
       {FeynCalc`PaVeIntegrals`Private`pp, 
        FeynCalc`PaVeIntegrals`Private`mm1, 
        FeynCalc`PaVeIntegrals`Private`mm2}]
 
B00 /: MakeBoxes[B00[FeynCalc`PaVeIntegrals`Private`p10_, 
       FeynCalc`PaVeIntegrals`Private`m02_, 
       FeynCalc`PaVeIntegrals`Private`m12_, OptionsPattern[]], 
      TraditionalForm] := ToBoxes[HoldForm[PaVe[0, 0, 
