Options[B00] = {BReduce -> True}
 
B00 /: B00::usage = "B00[pp, ma^2, mb^2] is the Passarino-Veltman \
$B_{00}$-function, i.e., the\ncoefficient function of the metric tensor. All \
arguments are scalars and have\ndimension mass squared."
 
FeynCalc`PaVeIntegrals`Private`b00[0, SmallVariable[
      FeynCalc`PaVeIntegrals`Private`mm_], SmallVariable[
      FeynCalc`PaVeIntegrals`Private`mm_]] := 0
 
FeynCalc`PaVeIntegrals`Private`b00[0, FeynCalc`PaVeIntegrals`Private`mm:
      Except[_SmallVariable | 0], FeynCalc`PaVeIntegrals`Private`mm:
      Except[_SmallVariable | 0]] := (FeynCalc`PaVeIntegrals`Private`mm/2)*
     (B0[0, FeynCalc`PaVeIntegrals`Private`mm, 
       FeynCalc`PaVeIntegrals`Private`mm] + 1)
 
FeynCalc`PaVeIntegrals`Private`b00[
     SmallVariable[FeynCalc`PaVeIntegrals`Private`em_]^
      (FeynCalc`PaVeIntegrals`Private`n_.), FeynCalc`PaVeIntegrals`Private`mm:
      Except[_SmallVariable | 0], FeynCalc`PaVeIntegrals`Private`mm:
      Except[_SmallVariable | 0]] := (FeynCalc`PaVeIntegrals`Private`mm/2)*
     (B0[FeynCalc`PaVeIntegrals`Private`em^FeynCalc`PaVeIntegrals`Private`n, 
       FeynCalc`PaVeIntegrals`Private`mm, 
       FeynCalc`PaVeIntegrals`Private`mm] + 1)
 
FeynCalc`PaVeIntegrals`Private`b00[FeynCalc`PaVeIntegrals`Private`pp:
      Except[_SmallVariable | 0], FeynCalc`PaVeIntegrals`Private`mm_, 
     FeynCalc`PaVeIntegrals`Private`mm_] := 
    (1/6)*(A0[FeynCalc`PaVeIntegrals`Private`mm] + 
      B0[FeynCalc`PaVeIntegrals`Private`pp, 
        FeynCalc`PaVeIntegrals`Private`mm, FeynCalc`PaVeIntegrals`Private`mm]*
       FeynCalc`PaVeIntegrals`Private`smad[
        2*FeynCalc`PaVeIntegrals`Private`mm - 
         FeynCalc`PaVeIntegrals`Private`pp/2] + 
      FeynCalc`PaVeIntegrals`Private`smad[
       2*FeynCalc`PaVeIntegrals`Private`mm - 
        FeynCalc`PaVeIntegrals`Private`pp/3])
 
FeynCalc`PaVeIntegrals`Private`b00[FeynCalc`PaVeIntegrals`Private`pp_, 
     FeynCalc`PaVeIntegrals`Private`mm1_, 
     FeynCalc`PaVeIntegrals`Private`mm2_] := 
    (1/6)*(A0[FeynCalc`PaVeIntegrals`Private`mm2] + 
        B1[FeynCalc`PaVeIntegrals`Private`pp, 
          FeynCalc`PaVeIntegrals`Private`mm1, 
          FeynCalc`PaVeIntegrals`Private`mm2]*
         FeynCalc`PaVeIntegrals`Private`smad[
          FeynCalc`PaVeIntegrals`Private`pp - 
           FeynCalc`PaVeIntegrals`Private`mm2 + 
           FeynCalc`PaVeIntegrals`Private`mm1]) + 
      FeynCalc`PaVeIntegrals`Private`smad[FeynCalc`PaVeIntegrals`Private`mm1/
         3]*B0[FeynCalc`PaVeIntegrals`Private`pp, 
        FeynCalc`PaVeIntegrals`Private`mm1, 
        FeynCalc`PaVeIntegrals`Private`mm2] + 
      FeynCalc`PaVeIntegrals`Private`smad[
       (1/6)*(FeynCalc`PaVeIntegrals`Private`mm1 + 
         FeynCalc`PaVeIntegrals`Private`mm2 - 
         FeynCalc`PaVeIntegrals`Private`pp/3)] /; 
     FeynCalc`PaVeIntegrals`Private`mm1 =!= FeynCalc`PaVeIntegrals`Private`mm2
 
B11[0, 0, 0, OptionsPattern[]] := 0 /;  !$KeepLogDivergentScalelessIntegrals
 
B11[FeynCalc`PaVeIntegrals`Private`pp_, FeynCalc`PaVeIntegrals`Private`mm1_, 
