Options[B11] = {BReduce -> True}
 
B11 /: B11::usage = "B11[pp, ma^2, mb^2] is the Passarino-Veltman \
$B_{11}$-function, i.e. the\ncoefficient function of $p^{\\mu } p^{\\nu }$. \
All arguments are scalars and\nhave dimension mass squared."
 
FeynCalc`PaVeIntegrals`Private`b11[0, FeynCalc`PaVeIntegrals`Private`mm1_, 
     FeynCalc`PaVeIntegrals`Private`mm1_] := 
    (1/3)*B0[0, FeynCalc`PaVeIntegrals`Private`mm1, 
      FeynCalc`PaVeIntegrals`Private`mm1]
 
FeynCalc`PaVeIntegrals`Private`b11[
     SmallVariable[FeynCalc`PaVeIntegrals`Private`em_]^
      (FeynCalc`PaVeIntegrals`Private`n_.), 
     FeynCalc`PaVeIntegrals`Private`mm1_, 
     FeynCalc`PaVeIntegrals`Private`mm1_] := 
    (1/3)*B0[SmallVariable[FeynCalc`PaVeIntegrals`Private`em]^
       FeynCalc`PaVeIntegrals`Private`n, FeynCalc`PaVeIntegrals`Private`mm1, 
      FeynCalc`PaVeIntegrals`Private`mm1]
 
FeynCalc`PaVeIntegrals`Private`b11[FeynCalc`PaVeIntegrals`Private`pp:
      Except[_SmallVariable | 0], FeynCalc`PaVeIntegrals`Private`mm_, 
     FeynCalc`PaVeIntegrals`Private`mm_] := 
