       FeynCalc`SharedObjectsTypesetting`Private`dim_:4], TraditionalForm] := 
     If[FeynCalc`SharedObjectsTypesetting`Private`p === Subscript, 
      SubscriptBox[TBox[Momentum[FeynCalc`SharedObjectsTypesetting`Private`x, 
         FeynCalc`SharedObjectsTypesetting`Private`dim]], 
       ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`y, 
        TraditionalForm]], SuperscriptBox[
       TBox[Momentum[FeynCalc`SharedObjectsTypesetting`Private`x, 
         FeynCalc`SharedObjectsTypesetting`Private`dim]], 
       ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`y, TraditionalForm]]]
 
Momentum /: MakeBoxes[Momentum[
       FeynCalc`SharedObjectsTypesetting`Private`p_Plus, 
       FeynCalc`SharedObjectsTypesetting`Private`dim_:4], TraditionalForm] := 
     TBox[(Momentum[#1, FeynCalc`SharedObjectsTypesetting`Private`dim] & ) /@ 
       Expand[FeynCalc`SharedObjectsTypesetting`Private`p]]
 
Momentum /: Momentum::lorentzhead = "`1` is forbidden in FeynCalc. Momentum \
cannot be the head of a LorentzIndex!"
 
Momentum /: Momentum::usage = "Momentum[p] is the head of a four momentum \
p.\n\nThe internal representation of a $4$-dimensional $p$ is \
Momentum[p].\n\nFor other than $4$ dimensions: Momentum[p, \
dim].\n\nMomentum[p, 4] simplifies to Momentum[p]."
 
GaugeXi /: MakeBoxes[GaugeXi, TraditionalForm] := 
     TagBox["\[Xi]", TraditionalForm]
 
GaugeXi /: MakeBoxes[GaugeXi[FeynCalc`SharedObjectsTypesetting`Private`a_], 
      TraditionalForm] := SubscriptBox["\[Xi]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`a]]
 
GaugeXi /: GaugeXi::usage = "GaugeXi is a head for gauge parameters."
 
DataType /: HoldPattern[DataType[FeynCalc`DataType`Private`exp_, 
        FeynCalc`DataType`Private`type_, FeynCalc`DataType`Private`opts:
         OptionsPattern[]] = FeynCalc`DataType`Private`bool:True | False] := 
     Block[{FeynCalc`DataType`Private`dtVerbose}, 
      If[OptionValue[DataType, {FeynCalc`DataType`Private`opts}, 
          FCVerbose] === False, FeynCalc`DataType`Private`dtVerbose = 
         $VeryVerbose, If[MatchQ[OptionValue[DataType, 
            {FeynCalc`DataType`Private`opts}, FCVerbose], _Integer], 
          FeynCalc`DataType`Private`dtVerbose = OptionValue[DataType, 
            {FeynCalc`DataType`Private`opts}, FCVerbose]]; ]; 
       If[$ParallelizeFeynCalc && OptionValue[DataType, 
          {FeynCalc`DataType`Private`opts}, FCParallelize], 
        FCPrint[1, "DataType: Setting DataType value on subkernels. ", 
          FCDoControl -> FeynCalc`DataType`Private`dtVerbose]; 
         Switch[FeynCalc`DataType`Private`type, NonCommutative, 
          With[{FeynCalc`DataType`Private`xxx = 
             FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`zzz = 
             FeynCalc`DataType`Private`bool}, ParallelEvaluate[
            FeynCalc`DataType`Private`setDataTypeNonCommutative[
              FeynCalc`DataType`Private`xxx, 
              FeynCalc`DataType`Private`zzz]; , DistributedContexts -> 
             None]], FCTensor, With[{FeynCalc`DataType`Private`xxx = 
             FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`zzz = 
             FeynCalc`DataType`Private`bool}, ParallelEvaluate[
            FeynCalc`DataType`Private`setDataTypeFCTensor[
              FeynCalc`DataType`Private`xxx, 
              FeynCalc`DataType`Private`zzz]; , DistributedContexts -> 
             None]], _, With[{FeynCalc`DataType`Private`xxx = 
              FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`yyy = 
              FeynCalc`DataType`Private`type, FeynCalc`DataType`Private`zzz = 
              FeynCalc`DataType`Private`bool}, ParallelEvaluate[
             FeynCalc`DataType`Private`setDataType[
               FeynCalc`DataType`Private`xxx, FeynCalc`DataType`Private`yyy, 
               FeynCalc`DataType`Private`zzz]; , DistributedContexts -> 
              None]]; ]; FCPrint[1, 
          "DataType: Done setting DataType value on subkernels. ", 
          FCDoControl -> FeynCalc`DataType`Private`dtVerbose]]; 
       FCPrint[1, "DataType: Setting DataType value on the main kernel. ", 
        FCDoControl -> FeynCalc`DataType`Private`dtVerbose]; 
       Switch[FeynCalc`DataType`Private`type, NonCommutative, 
        FeynCalc`DataType`Private`setDataTypeNonCommutative[
         FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`bool], 
        FCTensor, FeynCalc`DataType`Private`setDataTypeFCTensor[
         FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`bool], _, 
        FeynCalc`DataType`Private`setDataType[FeynCalc`DataType`Private`exp, 
         FeynCalc`DataType`Private`type, FeynCalc`DataType`Private`bool]]; 
       FeynCalc`DataType`Private`setDataType[FeynCalc`DataType`Private`exp, 
        FeynCalc`DataType`Private`type, FeynCalc`DataType`Private`bool]; 
       FCPrint[1, 
        "DataType: Setting DataType value on value on the main kernel. ", 
        FCDoControl -> FeynCalc`DataType`Private`dtVerbose]; 
       FeynCalc`DataType`Private`bool]
 
HoldPattern[DataType[FeynCalc`DataType`Private`a_, 
       FeynCalc`DataType`Private`b__, FeynCalc`DataType`Private`type_, 
       FeynCalc`DataType`Private`opts:OptionsPattern[]] = 
      FeynCalc`DataType`Private`bool_] ^:= 
    (FeynCalc`DataType`Private`set[FeynCalc`DataType`Private`dt[#1, 
         FeynCalc`DataType`Private`type, FeynCalc`DataType`Private`opts], 
        FeynCalc`DataType`Private`bool] & ) /@ {FeynCalc`DataType`Private`a, 
       FeynCalc`DataType`Private`b} /. {FeynCalc`DataType`Private`set :> Set, 
      FeynCalc`DataType`Private`dt :> DataType}
 
