DataType /: DataType::notsync = "You are using FeynCalc in the parallel mode, \
but the DataType values are not synchronized between the master kernel and \
subkernels. This usually happens if such definitions have been set before \
activating the parallel mode. Please clear the existing definitions with \
FCClearDataTypes[] and redefine your DataType."
 
DataType /: DataType::usage = "DataType[exp, type] = True defines the object \
exp to have data-type type.\n\nDataType[exp1, exp2, ..., type] defines the \
objects exp1, exp2, ... to have\ndata-type type.\n\nThe default setting is \
DataType[__, _] := False.\n\nTo assign a certain data-type, do, e.g., \
DataType[x, FCVariable] = True.\nCurrently used DataTypes: \n\n- \
NonCommutative\n\n- FreeIndex\n\n- FCTensor\n\n- FCVariable\n\n- \
ImplicitDiracIndex\n\n- ImplicitPauliIndex\n\n- ImplicitSUNFIndex"
 
FCParallelize /: FCParallelize::usage = "FCParallelize is an option for \
various FeynCalc functions that support\nparallelization. When set to True \
the function will try to parallelize its\nwork, while False disables any \
parallelization."
 
NonCommutative /: NonCommutative::usage = "NonCommutative is a data type \
which may be used, e.g.,  as DataType[x,\nNonCommutative] = True."
 
FeynCalc`DataType`Private`setDataTypeNonCommutative[
     FeynCalc`DataType`Private`exp_, FeynCalc`DataType`Private`bool_] := 
    Block[{FeynCalc`DataType`Private`ndt, FeynCalc`DataType`Private`ndf, 
      FeynCalc`DataType`Private`dt, FeynCalc`DataType`Private`ncq, 
      FeynCalc`DataType`Private`nnt, FeynCalc`DataType`Private`nnf, 
      FeynCalc`DataType`Private`downvalues, FeynCalc`DataType`Private`hp, 
      FeynCalc`DataType`Private`dvals, FeynCalc`DataType`Private`tmp}, 
     If[FeynCalc`DataType`Private`bool, 
       If[ !MemberQ[$NonComm, FeynCalc`DataType`Private`exp], 
        AppendTo[$NonComm, FeynCalc`DataType`Private`exp]], 
       If[MemberQ[$NonComm, FeynCalc`DataType`Private`exp], 
         $NonComm = SelectFree[$NonComm, 
            FeynCalc`DataType`Private`exp]; ]; ]; 
      FeynCalc`DataType`Private`dvals = DownValues[DataType] /. 
        {DataType -> FeynCalc`DataType`Private`dt, HoldPattern -> 
          FeynCalc`DataType`Private`hp}; FeynCalc`DataType`Private`ndt = 
       RuleDelayed @@ {FeynCalc`DataType`Private`hp @@ 
          {FeynCalc`DataType`Private`dt[FeynCalc`DataType`Private`exp, 
            NonCommutative]}, True}; FeynCalc`DataType`Private`ndf = 
       RuleDelayed @@ {FeynCalc`DataType`Private`hp @@ 
          {FeynCalc`DataType`Private`dt[FeynCalc`DataType`Private`exp, 
            NonCommutative]}, False}; If[FeynCalc`DataType`Private`bool, 
       If[FreeQ[FeynCalc`DataType`Private`dvals, 
         FeynCalc`DataType`Private`ndt], 
        If[ !FreeQ[FeynCalc`DataType`Private`dvals, 
            FeynCalc`DataType`Private`ndf], FeynCalc`DataType`Private`tmp = 
           SelectFree[FeynCalc`DataType`Private`dvals, 
            FeynCalc`DataType`Private`ndf], FeynCalc`DataType`Private`tmp = 
           FeynCalc`DataType`Private`dvals]; DownValues[DataType] = 
          Flatten[{FeynCalc`DataType`Private`tmp, 
              FeynCalc`DataType`Private`ndt}] /. 
            FeynCalc`DataType`Private`hp -> HoldPattern /. 
           FeynCalc`DataType`Private`dt -> DataType; ], 
       If[FreeQ[FeynCalc`DataType`Private`dvals, 
         FeynCalc`DataType`Private`ndf], 
        If[ !FreeQ[FeynCalc`DataType`Private`dvals, 
            FeynCalc`DataType`Private`ndt], FeynCalc`DataType`Private`tmp = 
           SelectFree[FeynCalc`DataType`Private`dvals, 
            FeynCalc`DataType`Private`ndt], FeynCalc`DataType`Private`tmp = 
           FeynCalc`DataType`Private`dvals]; DownValues[DataType] = 
          Flatten[{FeynCalc`DataType`Private`tmp, 
              FeynCalc`DataType`Private`ndf}] /. 
            FeynCalc`DataType`Private`hp -> HoldPattern /. 
           FeynCalc`DataType`Private`dt -> DataType; ]]; 
      FeynCalc`DataType`Private`nnt = 
       RuleDelayed @@ {FeynCalc`DataType`Private`hp[
           FeynCalc`DataType`Private`ncq[FeynCalc`DataType`Private`exp]], 
          True} /. FeynCalc`DataType`Private`ncq -> NonCommFreeQ; 
      FeynCalc`DataType`Private`nnf = 
       RuleDelayed @@ {HoldPattern @@ {FeynCalc`DataType`Private`ncq[
             FeynCalc`DataType`Private`exp]}, False} /. 
        FeynCalc`DataType`Private`ncq -> NonCommQ; 
      If[ !FreeQ[DownValues[NonCommFreeQ], FeynCalc`DataType`Private`exp], 
       FeynCalc`DataType`Private`dvals = DownValues[NonCommFreeQ]; 
        If[FeynCalc`DataType`Private`bool, FeynCalc`DataType`Private`set[
           FeynCalc`DataType`Private`downvalues[NonCommFreeQ], 
           Prepend[SelectFree[FeynCalc`DataType`Private`dvals, 
             FeynCalc`DataType`Private`exp], 
            FeynCalc`DataType`Private`nnf]] /. 
          {FeynCalc`DataType`Private`set :> Set, 
           FeynCalc`DataType`Private`downvalues :> DownValues}, 
         FeynCalc`DataType`Private`set[FeynCalc`DataType`Private`downvalues[
            NonCommFreeQ], Prepend[SelectFree[
             FeynCalc`DataType`Private`dvals, FeynCalc`DataType`Private`exp], 
            FeynCalc`DataType`Private`nnt]] /. 
          {FeynCalc`DataType`Private`set :> Set, 
           FeynCalc`DataType`Private`downvalues :> DownValues}]]; 
      If[ !FreeQ[DownValues[NonCommQ], FeynCalc`DataType`Private`exp], 
       FeynCalc`DataType`Private`dvals = DownValues[NonCommQ]; 
        If[FeynCalc`DataType`Private`bool, FeynCalc`DataType`Private`set[
           FeynCalc`DataType`Private`downvalues[NonCommQ], 
           Prepend[SelectFree[FeynCalc`DataType`Private`dvals, 
             FeynCalc`DataType`Private`exp], 
            FeynCalc`DataType`Private`nnt]] /. 
          {FeynCalc`DataType`Private`set :> Set, 
           FeynCalc`DataType`Private`downvalues :> DownValues}, 
         FeynCalc`DataType`Private`set[FeynCalc`DataType`Private`downvalues[
            NonCommQ], Prepend[SelectFree[FeynCalc`DataType`Private`dvals, 
             FeynCalc`DataType`Private`exp], 
            FeynCalc`DataType`Private`nnf]] /. 
          {FeynCalc`DataType`Private`set :> Set, 
           FeynCalc`DataType`Private`downvalues :> DownValues}]]; 
      If[$ParallelizeFeynCalc && $KernelID === 0, 
       If[ !FCValuesSynchronizedQ[{DataType}, DownValues], 
        Message[ScalarProduct::notsync]]]; FeynCalc`DataType`Private`bool]
 
$NonComm := {DiracGamma, DiracSigma, GA, GAD, GAE, GS, GSD, GSE, GSLP, GSLN, 
     GSLR, GSLPD, GSLND, GSLRD, GALP, GALN, GALR, GALPD, GALND, GALRD, 
     LeftPartialD, LeftRightPartialD, LeftRightPartialD2, LeftNablaD, 
     LeftRightNablaD, LeftRightNablaD2, FCPartialD, QuantumField, 
     RightPartialD, RightNablaD, Spinor, SpinorU, SpinorUBar, SpinorV, 
     SpinorVBar, SUNT, PauliSigma, PauliXi, PauliEta, PauliEtaC, TGA, CGA, 
     CGAD, CGAE, CGS, CGSD, CGSE, SI, SID, SIE, CSI, CSID, CSIE, 
     FeynCalc`Package`dotsimpHold, FCChargeConjugateTransposed, CovariantD, 
     FieldStrength, QuarkPropagator, QuarkGluonVertex, ChiralityProjector, 
     DiracSpinor, DiracMatrix, DiracSlash}
 
($NonComm = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$NonComm] = {HoldPattern[$NonComm] :> 
             FeynCalc`Private`xxx}; , DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$NonComm] = {HoldPattern[$NonComm] :> FeynCalc`Private`xxx}]; 
     FeynCalc`Private`val)
 
$NonComm /: $NonComm::usage = 
     "$NonComm contains a list of all noncommutative heads present."
 
DiracGamma[_, 0] := 0
 
DiracGamma[0, ___] := 0
 
DiracGamma[FeynCalc`SharedObjects`Private`x_, 
      FeynCalc`SharedObjects`Private`y_, 
      FeynCalc`SharedObjects`Private`z__] /; 
      !MemberQ[{1, 2}, Length[{FeynCalc`SharedObjects`Private`x, 
          FeynCalc`SharedObjects`Private`y, 
          FeynCalc`SharedObjects`Private`z}]] && FCPatternFreeQ[
       {FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y, 
        FeynCalc`SharedObjects`Private`z}] := 
    (Message[DiracGamma::argrx, StringJoin["DiracGamma[", 
       ToString[{FeynCalc`SharedObjects`Private`x, 
         FeynCalc`SharedObjects`Private`y, 
         FeynCalc`SharedObjects`Private`z}], "]"], 
      Length[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`z}], 
      "1 or 2"]; Abort[])
 
DiracGamma[FeynCalc`SharedObjects`Private`a_Plus, 
     FeynCalc`SharedObjects`Private`dim_:4] := 
    (DiracGamma[#1, FeynCalc`SharedObjects`Private`dim] & ) /@ 
     FeynCalc`SharedObjects`Private`a
 
DiracGamma[FeynCalc`SharedObjects`Private`x_, 4] := 
    DiracGamma[FeynCalc`SharedObjects`Private`x]
 
DiracGamma[(FeynCalc`SharedObjects`Private`x_)*
      (FeynCalc`SharedObjects`Private`h:TemporalMomentum | 
         CartesianMomentum | Momentum | LightConePerpendicularComponent)[
       FeynCalc`SharedObjects`Private`p_, 
       FeynCalc`SharedObjects`Private`dim1___], 
     FeynCalc`SharedObjects`Private`dim2___] := 
    FeynCalc`SharedObjects`Private`x*DiracGamma[
      FeynCalc`SharedObjects`Private`h[FeynCalc`SharedObjects`Private`p, 
       FeynCalc`SharedObjects`Private`dim1], 
      FeynCalc`SharedObjects`Private`dim2]
 
DiracGamma[(LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
       CartesianMomentum)[_], -4 + _Symbol] := 0
 
DiracGamma[_TemporalMomentum, -4 + _Symbol] := 0
 
DiracGamma[(LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
       CartesianMomentum)[_, -4 + _Symbol]] := 0
 
DiracGamma[(FeynCalc`SharedObjects`Private`h:LorentzIndex | 
        ExplicitLorentzIndex | Momentum)[FeynCalc`SharedObjects`Private`x_, 
      FeynCalc`SharedObjects`Private`dim_Symbol], 
     -4 + (FeynCalc`SharedObjects`Private`dim_Symbol)] := 
    DiracGamma[FeynCalc`SharedObjects`Private`h[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim - 
       4], FeynCalc`SharedObjects`Private`dim - 4]
 
DiracGamma[(FeynCalc`SharedObjects`Private`h:CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`i_, 
      -1 + (FeynCalc`SharedObjects`Private`dim_Symbol)], 
     -4 + (FeynCalc`SharedObjects`Private`dim_Symbol)] := 
    DiracGamma[FeynCalc`SharedObjects`Private`h[
      FeynCalc`SharedObjects`Private`i, FeynCalc`SharedObjects`Private`dim - 
       4], FeynCalc`SharedObjects`Private`dim - 4]
 
DiracGamma[(FeynCalc`SharedObjects`Private`h:LorentzIndex | 
        ExplicitLorentzIndex | Momentum | CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`x_, 
      -4 + (FeynCalc`SharedObjects`Private`dim_Symbol)], 
     FeynCalc`SharedObjects`Private`dim_Symbol] := 
    DiracGamma[FeynCalc`SharedObjects`Private`h[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim - 
       4], FeynCalc`SharedObjects`Private`dim - 4]
 
DiracGamma[(FeynCalc`SharedObjects`Private`h:LorentzIndex | 
        ExplicitLorentzIndex | Momentum | CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`x_], _Symbol] := 
    DiracGamma[FeynCalc`SharedObjects`Private`h[
      FeynCalc`SharedObjects`Private`x]]
 
DiracGamma[(FeynCalc`SharedObjects`Private`h:LorentzIndex | 
        ExplicitLorentzIndex | Momentum)[FeynCalc`SharedObjects`Private`x_, 
      _Symbol]] := DiracGamma[FeynCalc`SharedObjects`Private`h[
      FeynCalc`SharedObjects`Private`x]]
 
DiracGamma[(FeynCalc`SharedObjects`Private`h:CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`i_, 
      -1 + _Symbol]] := DiracGamma[FeynCalc`SharedObjects`Private`h[
      FeynCalc`SharedObjects`Private`i]]
 
DiracGamma[FeynCalc`SharedObjects`Private`m_TemporalMomentum, _Symbol] := 
    DiracGamma[FeynCalc`SharedObjects`Private`m]
 
DiracGamma[FeynCalc`SharedObjects`Private`m_TemporalMomentum] := 
    FeynCalc`Package`MetricT*DiracGamma[ExplicitLorentzIndex[0]]*
     TemporalPair[FeynCalc`SharedObjects`Private`m, ExplicitLorentzIndex[0]]
 
DiracGamma[(FeynCalc`SharedObjects`Private`n_)*
       (FeynCalc`SharedObjects`Private`x_) /; 
      DataType[FeynCalc`SharedObjects`Private`n, FCVariable], 
     FeynCalc`SharedObjects`Private`dim_:4] := 
    FeynCalc`SharedObjects`Private`n*DiracGamma[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim]
 
DiracGamma[(FeynCalc`SharedObjects`Private`x_)?NumberQ, ___] := 
    (Message[DiracGamma::noint, FeynCalc`SharedObjects`Private`x]; 
      Abort[]) /; FeynCalc`SharedObjects`Private`x =!= 0 && 
      FeynCalc`SharedObjects`Private`x =!= 5 && 
      FeynCalc`SharedObjects`Private`x =!= 6 && 
      FeynCalc`SharedObjects`Private`x =!= 7
 
DiracGamma[FeynCalc`SharedObjects`Private`n:5 | 6 | 7, _Symbol] := 
    DiracGamma[FeynCalc`SharedObjects`Private`n]
 
DiracGamma[5 | 6 | 7, -4 + _Symbol] := (Message[SharedObjects::failmsg, 
      "D-4 dimensional g^5 or chiral projectors do not exist!"]; Abort[])
 
DiracGamma /: MakeBoxes[DiracGamma[LightConePerpendicularComponent[
        FeynCalc`SharedObjectsTypesetting`Private`a_, __], 
       FeynCalc`SharedObjectsTypesetting`Private`dim___], TraditionalForm] := 
     SubscriptBox[ToBoxes[DiracGamma[
        FeynCalc`SharedObjectsTypesetting`Private`a, 
        FeynCalc`SharedObjectsTypesetting`Private`dim], TraditionalForm], 
      "\[Perpendicular]"]
 
DiracGamma /: MakeBoxes[DiracGamma[
       (FeynCalc`SharedObjectsTypesetting`Private`h:
         Momentum | TemporalMomentum)[
        FeynCalc`SharedObjectsTypesetting`Private`x_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1_:4], 
       FeynCalc`SharedObjectsTypesetting`Private`dim2_:4], 
      TraditionalForm] := 
     If[Head[FeynCalc`SharedObjectsTypesetting`Private`x] === Plus, 
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`gammaRep[
         FeynCalc`SharedObjectsTypesetting`Private`dim2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1, "\[Gamma]"], 
        "\[CenterDot]", "(", TBox[FeynCalc`SharedObjectsTypesetting`Private`h[
          FeynCalc`SharedObjectsTypesetting`Private`x, 
          FeynCalc`SharedObjectsTypesetting`Private`dim1]], ")"}], 
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`gammaRep[
         FeynCalc`SharedObjectsTypesetting`Private`dim2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1, "\[Gamma]"], 
        "\[CenterDot]", TBox[FeynCalc`SharedObjectsTypesetting`Private`h[
          FeynCalc`SharedObjectsTypesetting`Private`x, 
          FeynCalc`SharedObjectsTypesetting`Private`dim1]]}]]
 
DiracGamma /: MakeBoxes[DiracGamma[CartesianMomentum[
        FeynCalc`SharedObjectsTypesetting`Private`x_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1_:3], 
       FeynCalc`SharedObjectsTypesetting`Private`dim2_:4], 
      TraditionalForm] := 
     If[Head[FeynCalc`SharedObjectsTypesetting`Private`x] === Plus, 
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`cgammaSigmaRep[
         FeynCalc`SharedObjectsTypesetting`Private`dim1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2, "\[Gamma]"], 
        "\[CenterDot]", "(", TBox[CartesianMomentum[
          FeynCalc`SharedObjectsTypesetting`Private`x, 
          FeynCalc`SharedObjectsTypesetting`Private`dim1]], ")"}], 
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`cgammaSigmaRep[
         FeynCalc`SharedObjectsTypesetting`Private`dim1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2, "\[Gamma]"], 
        "\[CenterDot]", TBox[CartesianMomentum[
          FeynCalc`SharedObjectsTypesetting`Private`x, 
          FeynCalc`SharedObjectsTypesetting`Private`dim1]]}]]
 
DiracGamma /: MakeBoxes[DiracGamma[
       (FeynCalc`SharedObjectsTypesetting`Private`lo:LorentzIndex | 
          ExplicitLorentzIndex)[
        FeynCalc`SharedObjectsTypesetting`Private`in_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1_:4], 
       FeynCalc`SharedObjectsTypesetting`Private`dim2_:4], 
      TraditionalForm] := SuperscriptBox[
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`gammaRep[
         FeynCalc`SharedObjectsTypesetting`Private`dim2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1, "\[Gamma]"]}], 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`lo[
        FeynCalc`SharedObjectsTypesetting`Private`in, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1]]]
 
DiracGamma /: MakeBoxes[DiracGamma[CartesianIndex[
        FeynCalc`SharedObjectsTypesetting`Private`in_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1_:3], 
       FeynCalc`SharedObjectsTypesetting`Private`dim2_:4], 
      TraditionalForm] := SuperscriptBox[
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`cgammaSigmaRep[
         FeynCalc`SharedObjectsTypesetting`Private`dim1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2, "\[Gamma]"]}], 
      TBox[CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`in, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1]]]
 
DiracGamma /: MakeBoxes[DiracGamma[
       FeynCalc`SharedObjectsTypesetting`Private`a:5 | 6 | 7], 
      TraditionalForm] := SuperscriptBox[
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`gammaRep[4, 4, 
         "\[Gamma]"]}], TBox[FeynCalc`SharedObjectsTypesetting`Private`a]]
 
DiracGamma /: DiracGamma::gamma5fail = "`1` is forbidden in FeynCalc. You \
should always use 4-dimensional Gamma^5 or chiral projectors. This is fine \
for all dimensional regularization schemes supported by FeynCalc including \
NDR. Evaluation aborted!"
 
DiracGamma /: DiracGamma::noint = "DiracGamma[`1`] is forbidden in FeynCalc. \
If you want to specify an explicit Lorentz index, please use \
DiracGamma[ExplicitLorentzIndex[`1`]]. Evaluation aborted!"
 
DiracGamma /: DiracGamma::usage = "DiracGamma[x, dim] is the head of all \
Dirac matrices and slashes (in the\ninternal representation). Use GA, GAD, GS \
or GSD for manual (short) input.\n\nDiracGamma[x, 4] simplifies to \
DiracGamma[x].\n\nDiracGamma[5]  is $\\gamma ^5$.\n\nDiracGamma[6] is \
$(1+\\gamma ^5)/2$.\n\nDiracGamma[7] is $(1-\\gamma ^5)/2$."
 
TemporalMomentum[0] := 0
 
TemporalMomentum[FeynCalc`SharedObjects`Private`x_, 4] := 
    TemporalMomentum[FeynCalc`SharedObjects`Private`x, 4] = 
     TemporalMomentum[FeynCalc`SharedObjects`Private`x]
 
TemporalMomentum[FeynCalc`SharedObjects`Private`x_, 
     FeynCalc`SharedObjects`Private`dim_Symbol] := 
    TemporalMomentum[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`dim] = TemporalMomentum[
      FeynCalc`SharedObjects`Private`x]
 
TemporalMomentum[FeynCalc`SharedObjects`Private`x_, 
     -4 + (FeynCalc`SharedObjects`Private`dim_Symbol)] := 
    TemporalMomentum[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`dim - 4] = 0
 
TemporalMomentum[(FeynCalc`SharedObjects`Private`x_)*
      (FeynCalc`SharedObjects`Private`n_)?NumberQ] := 
    FeynCalc`SharedObjects`Private`n*TemporalMomentum[
      FeynCalc`SharedObjects`Private`x]
 
TemporalMomentum[(FeynCalc`SharedObjects`Private`n_)*
       (FeynCalc`SharedObjects`Private`x_) /; 
      DataType[FeynCalc`SharedObjects`Private`n, FCVariable]] := 
    FeynCalc`SharedObjects`Private`n*TemporalMomentum[
      FeynCalc`SharedObjects`Private`x]
 
TemporalMomentum /: MakeBoxes[TemporalMomentum[
       FeynCalc`SharedObjectsTypesetting`Private`x_], TraditionalForm] := 
     ToBoxes[Momentum[FeynCalc`SharedObjectsTypesetting`Private`x, D], 
      TraditionalForm]
 
TemporalMomentum /: TemporalMomentum::usage = "TemporalMomentum[p]  is the \
head of the temporal component of a $4$-momentum\n$p^0$. The internal \
representation of the temporal component $p^0$ \
is\nTemporalMomentum[p].\n\nTemporalMomentum may appear only inside \
TemporalPairs."
 
FCVariable /: FCVariable::usage = 
     "FCVariable  is a data type. E.g. DataType[z, FCVariable] = True."
 
CartesianMomentum[(FeynCalc`SharedObjects`Private`x_)*
      (FeynCalc`SharedObjects`Private`n_)?NumberQ, 
     FeynCalc`SharedObjects`Private`dim_:3] := 
    FeynCalc`SharedObjects`Private`n*CartesianMomentum[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim]
 
CartesianMomentum[(FeynCalc`SharedObjects`Private`a_ /; 
        DataType[FeynCalc`SharedObjects`Private`a, FCVariable])^
       (FeynCalc`SharedObjects`Private`n_)*
      (FeynCalc`SharedObjects`Private`x_), 
     FeynCalc`SharedObjects`Private`dim_:3] := 
    FeynCalc`SharedObjects`Private`a^FeynCalc`SharedObjects`Private`n*
     CartesianMomentum[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`dim]
 
CartesianMomentum[((FeynCalc`SharedObjects`Private`c_.)*
          (FeynCalc`SharedObjects`Private`a_)^
           (FeynCalc`SharedObjects`Private`m_.) + 
         (FeynCalc`SharedObjects`Private`b_) /; 
        DataType[FeynCalc`SharedObjects`Private`a, FCVariable])^
       (FeynCalc`SharedObjects`Private`n_)*
      (FeynCalc`SharedObjects`Private`x_), 
     FeynCalc`SharedObjects`Private`dim_:3] := 
    (FeynCalc`SharedObjects`Private`c*FeynCalc`SharedObjects`Private`a^
         FeynCalc`SharedObjects`Private`m + FeynCalc`SharedObjects`Private`b)^
      FeynCalc`SharedObjects`Private`n*CartesianMomentum[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim]
 
CartesianMomentum[(FeynCalc`SharedObjects`Private`n_)*
       (FeynCalc`SharedObjects`Private`x_) /; 
      DataType[FeynCalc`SharedObjects`Private`n, FCVariable], 
     FeynCalc`SharedObjects`Private`dim_:3] := 
    FeynCalc`SharedObjects`Private`n*CartesianMomentum[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim]
 
CartesianMomentum[FeynCalc`SharedObjects`Private`x:Except[_Pattern], 3] := 
    CartesianMomentum[FeynCalc`SharedObjects`Private`x, 3] = 
     CartesianMomentum[FeynCalc`SharedObjects`Private`x]
 
CartesianMomentum[0, _:3] := 0
 
CartesianMomentum[_, 0] := 0
 
CartesianMomentum[(FeynCalc`SharedObjects`Private`h:
       LorentzIndex | ExplicitLorentzIndex | CartesianIndex | Momentum | 
        TemporalMomentum)[___], _:3] := 
    (Message[SharedObjects::failmsg, StringJoin[
       ToString[FeynCalc`SharedObjects`Private`h, InputForm], 
       " is not allowed inside CartesianMomentum"]]; Abort[])
 
CartesianMomentum[CartesianMomentum[FeynCalc`SharedObjects`Private`x_, 
      FeynCalc`SharedObjects`Private`dim1_:3], 
     FeynCalc`SharedObjects`Private`dim2_:3] := 
    If[FeynCalc`SharedObjects`Private`dim1 === 
      FeynCalc`SharedObjects`Private`dim2, CartesianMomentum[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim1], 
     CartesianMomentum[FeynCalc`SharedObjects`Private`x, 
      {FeynCalc`SharedObjects`Private`dim1, 
       FeynCalc`SharedObjects`Private`dim2}]]
 
CartesianMomentum[LightConePerpendicularComponent[
      FeynCalc`SharedObjects`Private`mu_, 
      FeynCalc`SharedObjects`Private`rest__], 
     FeynCalc`SharedObjects`Private`dim___] := 
    LightConePerpendicularComponent[CartesianMomentum[
      FeynCalc`SharedObjects`Private`mu, FeynCalc`SharedObjects`Private`dim], 
     FeynCalc`SharedObjects`Private`rest]
 
CartesianMomentum /: MakeBoxes[CartesianMomentum[Polarization[
        FeynCalc`SharedObjectsTypesetting`Private`a_, 
        FeynCalc`SharedObjectsTypesetting`Private`b:Except[_?OptionQ], 
        OptionsPattern[]], FeynCalc`SharedObjectsTypesetting`Private`dim_:3], 
      TraditionalForm] := 
     RowBox[{FeynCalc`SharedObjectsTypesetting`Private`cpolarizationRep[
        FeynCalc`SharedObjectsTypesetting`Private`b, 
        FeynCalc`SharedObjectsTypesetting`Private`dim], "(", 
       TBox[FeynCalc`SharedObjectsTypesetting`Private`a], ")"}]
 
CartesianMomentum /: MakeBoxes[CartesianMomentum[
       FeynCalc`SharedObjectsTypesetting`Private`p:
        Except[Blank[Subscript] | Blank[Superscript] | _Plus], 
       FeynCalc`SharedObjectsTypesetting`Private`dim_:3], TraditionalForm] := 
     FeynCalc`SharedObjectsTypesetting`Private`CartesianMomentumRep[
      Style[FeynCalc`SharedObjectsTypesetting`Private`p, Bold], 
      FeynCalc`SharedObjectsTypesetting`Private`dim]
 
CartesianMomentum /: MakeBoxes[CartesianMomentum[
       (FeynCalc`SharedObjectsTypesetting`Private`p:Subscript | Superscript)[
        FeynCalc`SharedObjectsTypesetting`Private`x_, 
        FeynCalc`SharedObjectsTypesetting`Private`y_], 
       FeynCalc`SharedObjectsTypesetting`Private`dim_:3], TraditionalForm] := 
     If[FeynCalc`SharedObjectsTypesetting`Private`p === Subscript, 
      SubscriptBox[TBox[CartesianMomentum[
         Style[FeynCalc`SharedObjectsTypesetting`Private`x, Bold], 
         FeynCalc`SharedObjectsTypesetting`Private`dim]], 
       ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`y, 
        TraditionalForm]], SuperscriptBox[TBox[CartesianMomentum[
         Style[FeynCalc`SharedObjectsTypesetting`Private`x, Bold], 
         FeynCalc`SharedObjectsTypesetting`Private`dim]], 
       ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`y, TraditionalForm]]]
 
CartesianMomentum /: MakeBoxes[CartesianMomentum[
       FeynCalc`SharedObjectsTypesetting`Private`p_Plus, 
       FeynCalc`SharedObjectsTypesetting`Private`dim_:3], TraditionalForm] := 
     TBox[(CartesianMomentum[#1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim] & ) /@ 
       Expand[FeynCalc`SharedObjectsTypesetting`Private`p]]
 
CartesianMomentum /: CartesianMomentum::usage = "CartesianMomentum[p] is the \
head of a 3-momentum p. The internal\nrepresentation of a $3$-dimensional p \
is CartesianMomentum[p]. For other than\nthree dimensions: \
CartesianMomentum[p, Dimension]. CartesianMomentum[p, 3]\nsimplifies to \
CartesianMomentum[p]."
 
Attributes[LorentzIndex] = {Constant}
 
LorentzIndex[Momentum[FeynCalc`SharedObjects`Private`x_], 
     FeynCalc`SharedObjects`Private`dim_:4] := 
    (Message[LorentzIndex::momentumhead, 
      ToString[LorentzIndex[FCGV["Momentum"][
         FeynCalc`SharedObjects`Private`x], 
        FeynCalc`SharedObjects`Private`dim], InputForm]]; 
     LorentzIndex[FCGV["Momentum"][FeynCalc`SharedObjects`Private`x], 
      FeynCalc`SharedObjects`Private`dim])
 
LorentzIndex[ExplicitLorentzIndex[FeynCalc`SharedObjects`Private`x_], 
     FeynCalc`SharedObjects`Private`dim_:4] := 
    (Message[LorentzIndex::explicitlorentzhead, 
      ToString[LorentzIndex[FCGV["ExplicitLorentzIndex"][
         FeynCalc`SharedObjects`Private`x], 
        FeynCalc`SharedObjects`Private`dim], InputForm]]; 
     LorentzIndex[FCGV["ExplicitLorentzIndex"][
       FeynCalc`SharedObjects`Private`x], FeynCalc`SharedObjects`Private`dim])
 
LorentzIndex[LorentzIndex[FeynCalc`SharedObjects`Private`in_, 
      FeynCalc`SharedObjects`Private`dim_:4], 
     FeynCalc`SharedObjects`Private`dim_:4] := 
    LorentzIndex[FeynCalc`SharedObjects`Private`in, 
     FeynCalc`SharedObjects`Private`dim]
 
LorentzIndex[FeynCalc`SharedObjects`Private`x:Except[_Pattern], 4] := 
    LorentzIndex[FeynCalc`SharedObjects`Private`x, 4] = 
     LorentzIndex[FeynCalc`SharedObjects`Private`x]
 
LorentzIndex[_, 0] := 0
 
LorentzIndex[(FeynCalc`SharedObjects`Private`in_Integer)?NonNegative, 
     FeynCalc`SharedObjects`Private`dim_:4] := ExplicitLorentzIndex[
     FeynCalc`SharedObjects`Private`in, FeynCalc`SharedObjects`Private`dim]
 
LorentzIndex[CartesianIndex[FeynCalc`SharedObjects`Private`i_]] := 
    CartesianIndex[FeynCalc`SharedObjects`Private`i]
 
LorentzIndex[CartesianIndex[FeynCalc`SharedObjects`Private`i_, 
      -1 + (FeynCalc`SharedObjects`Private`dim_)], 
     FeynCalc`SharedObjects`Private`dim_] := CartesianIndex[
     FeynCalc`SharedObjects`Private`i, FeynCalc`SharedObjects`Private`dim - 1]
 
LorentzIndex[LightConePerpendicularComponent[
      FeynCalc`SharedObjects`Private`mu_, 
      FeynCalc`SharedObjects`Private`rest__], 
     FeynCalc`SharedObjects`Private`dim___] := 
    LightConePerpendicularComponent[LorentzIndex[
      FeynCalc`SharedObjects`Private`mu, FeynCalc`SharedObjects`Private`dim], 
     FeynCalc`SharedObjects`Private`rest]
 
LorentzIndex /: MakeBoxes[LorentzIndex[
       FeynCalc`SharedObjectsTypesetting`Private`p_, ___], 
      TraditionalForm] := ToBoxes[
      FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm]
 
LorentzIndex /: LorentzIndex::explicitlorentzhead = "`1` is forbidden in \
FeynCalc. LorentzIndex cannot be the head of an ExplicitLorentzIndex!"
 
LorentzIndex /: LorentzIndex::momentumhead = "`1` is forbidden in FeynCalc. \
LorentzIndex cannot be the head of a Momentum !"
 
LorentzIndex /: LorentzIndex::usage = "LorentzIndex[mu] denotes a \
$4$-dimensional Lorentz index.\n\nFor other than $4$ dimensions: \
LorentzIndex[mu, D] or LorentzIndex[mu] etc.\n\nLorentzIndex[mu, 4] \
simplifies to LorentzIndex[mu]."
 
Options[FCGV] = {}
 
FCGV /: FCGV::usage = "FCGV[x] is a FeynCalc global variable, i.e. a \
container for string variables\nthat allows to introduce new variables \
without polluting the Global context of\nMathematica.\n\nUse the rule \
FCGV[s_] :> ToExpression[s] if you want to convert the string x\nto a symbol \
with the name x."
 
CartesianIndex[FeynCalc`SharedObjects`Private`x_ /; 
      FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x}], 3] := 
    CartesianIndex[FeynCalc`SharedObjects`Private`x, 3] = 
     CartesianIndex[FeynCalc`SharedObjects`Private`x]
 
CartesianIndex[_, 0] := 0
 
CartesianIndex[CartesianIndex[FeynCalc`SharedObjects`Private`in_, 
      FeynCalc`SharedObjects`Private`dim_:3], 
     FeynCalc`SharedObjects`Private`dim_:3] := 
    CartesianIndex[FeynCalc`SharedObjects`Private`in, 
     FeynCalc`SharedObjects`Private`dim]
 
CartesianIndex[_Integer, ___] := (Message[SharedObjects::failmsg, 
      "Explicit cartesian indices are not supported"]; Abort[])
 
CartesianIndex[LightConePerpendicularComponent[
      FeynCalc`SharedObjects`Private`mu_, 
      FeynCalc`SharedObjects`Private`rest__], 
     FeynCalc`SharedObjects`Private`dim___] := 
    LightConePerpendicularComponent[CartesianIndex[
      FeynCalc`SharedObjects`Private`mu, FeynCalc`SharedObjects`Private`dim], 
     FeynCalc`SharedObjects`Private`rest]
 
CartesianIndex /: MakeBoxes[CartesianIndex[
       FeynCalc`SharedObjectsTypesetting`Private`p_, ___], 
      TraditionalForm] := ToBoxes[
      Style[FeynCalc`SharedObjectsTypesetting`Private`p, Bold], 
      TraditionalForm]
 
CartesianIndex /: CartesianIndex::usage = "CartesianIndex is the head of \
Cartesian indices. The internal representation\nof a $3$-dimensional i is \
CartesianIndex[i].\n\nFor other than three dimensions: CartesianIndex[i, \
Dimension].\n\nCartesianIndex[i, 3] simplifies to CartesianIndex[i]. The \
first argument\ncannot be an integer."
 
SharedObjects /: SharedObjects::failmsg = "Error! FeynCalc has encountered a \
fatal problem and must abort the computation. The problem reads: `1`"
 
Options[Polarization] = {Transversality -> False}
 
Polarization /: Polarization::usage = "Polarization[k] is the head of a \
polarization momentum with momentum k.\n\nA slashed polarization vector \
($\\varepsilon_{\\mu}(k) \\gamma^\\mu)$ has to be\nentered as \
GS[Polarization[k]].\n\nUnless the option Transversality is set to True, all \
polarization vectors are\nnot transverse by default.\n\nThe internal \
representation for a polarization vector corresponding to a boson\nwith four \
momentum $k$ is: Momentum[Polarization[k, I ]].\n\nPolarization[k,-I] denotes \
the complex conjugate polarization.\n\nPolarization is also an option of \
various functions related to the operator\nproduct expansion. The setting 0 \
denotes the unpolarized and 1 the polarized\ncase.\n\nPolarization may appear \
only inside Momentum. Outside of Momentum it is\nmeaningless in \
FeynCalc.\n\nThe imaginary unit in the second argument of Polarization is \
used to\ndistinguish between incoming and outgoing polarization vectors.\n\n- \
Pair[Momentum[k], Momentum[Polarization[k, I]]] corresponds \
to\n$\\varepsilon^{\\mu}(k)$, i.e. an ingoing polarization vector\n\n- \
Pair[Momentum[k], Momentum[Polarization[k, -I]]] corresponds \
to\n$\\varepsilon^{\\ast \\mu}(k)$, i.e. an outgoing polarization vector"
 
Transversality /: Transversality::usage = "Transversality is an option for \
Polarization and PolarizationVector. Setting\nit to True will make all scalar \
products of a polarization vector with its\nmomentum vanish."
 
FeynCalc`SharedObjectsTypesetting`Private`cpolarizationRep[
     FeynCalc`SharedObjectsTypesetting`Private`pol_, 
     FeynCalc`SharedObjectsTypesetting`Private`dim_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, 1] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim === 3, 
     OverscriptBox[TBox[Style["\[CurlyEpsilon]", Bold]], $TypesettingDim4], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, 1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 1], 
     If[$TypesettingDimD === "", TBox[Style["\[CurlyEpsilon]", Bold]], 
      OverscriptBox[TBox[Style["\[CurlyEpsilon]", Bold]], $TypesettingDimD]], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, 1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 4], 
     OverscriptBox[TBox[Style["\[CurlyEpsilon]", Bold]], $TypesettingDimE], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, -1] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim === 3, 
     SuperscriptBox[OverscriptBox[TBox[Style["\[CurlyEpsilon]", Bold]], 
       $TypesettingDim4], "*"], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, -1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 1], 
     If[$TypesettingDimD === "", SuperscriptBox[
       TBox[Style["\[CurlyEpsilon]", Bold]], "*"], 
      SuperscriptBox[OverscriptBox[TBox[Style["\[CurlyEpsilon]", Bold]], 
        $TypesettingDimD], "*"]], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, -1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 4], 
     SuperscriptBox[OverscriptBox[TBox[Style["\[CurlyEpsilon]", Bold]], 
       $TypesettingDimE], "*"], True, SuperscriptBox[
      TBox[Style["\[CurlyEpsilon]", Bold]], 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`pol, 
       FeynCalc`SharedObjectsTypesetting`Private`dim]]]
 
$TypesettingDim4 = "_"
 
$TypesettingDim4 /: $TypesettingDim4::usage = "The string value of \
$TypesettingDim4 determines which symbols will be\ndisplayed above \
$4$-dimensional momenta, Dirac matrices, metric tensors and\npolarization \
vectors. This concerns only typesetting in the TraditionalForm\noutput and \
doesn't change the physical behavior of those objects."
 
$TypesettingDimD = ""
 
$TypesettingDimD /: $TypesettingDimD::usage = "The string value of \
$TypesettingDimD determines which symbols will be\ndisplayed above \
$D$-dimensional momenta, Dirac matrices, metric tensors and\npolarization \
vectors. This concerns only typesetting in the TraditionalForm\noutput and \
doesn't change the physical behavior of those objects."
 
$TypesettingDimE = "^"
 
$TypesettingDimE /: $TypesettingDimE::usage = "The string value of \
$TypesettingDimE determines which symbols will be\ndisplayed above \
$(D-4)$-dimensional momenta, Dirac matrices, metric tensors\nand polarization \
vectors. This concerns only typesetting in the\nTraditionalForm output and \
doesn't change the physical behavior of those\nobjects."
 
FeynCalc`SharedObjectsTypesetting`Private`CartesianMomentumRep[
     FeynCalc`SharedObjectsTypesetting`Private`p_, 
     FeynCalc`SharedObjectsTypesetting`Private`dim_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`dim === 3, 
     OverscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
       TraditionalForm], $TypesettingDim4], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 1], 
     If[$TypesettingDimD === "", ToBoxes[
       FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm], 
      OverscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
        TraditionalForm], $TypesettingDimD]], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 4], 
     OverscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
       TraditionalForm], $TypesettingDimE], True, 
     SubscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
       TraditionalForm], ToBoxes[
       FeynCalc`SharedObjectsTypesetting`Private`dim, TraditionalForm]]]
 
FeynCalc`Package`MetricT = 1
 
Attributes[TemporalPair] = {Orderless}
 
TemporalPair[0, _] := 0
 
TemporalPair[_, (FeynCalc`SharedObjects`Private`h:CartesianMomentum | 
        Momentum | LorentzIndex | CartesianIndex)[__]] := 
    (Message[SharedObjects::failmsg, StringJoin[
       ToString[FeynCalc`SharedObjects`Private`h, InputForm], 
       " is not allowed inside TemporalPair"]]; Abort[])
 
TemporalPair[_, ExplicitLorentzIndex[FeynCalc`SharedObjects`Private`x_ /; 
       FeynCalc`SharedObjects`Private`x =!= 0]] := 
    (Message[SharedObjects::failmsg, StringJoin[
       ToString[ExplicitLorentzIndex[FeynCalc`SharedObjects`Private`x], 
        InputForm], " is not allowed inside TemporalPair"]]; Abort[])
 
TemporalPair[(FeynCalc`SharedObjects`Private`n_)*
      (FeynCalc`SharedObjects`Private`x_TemporalMomentum), 
     FeynCalc`SharedObjects`Private`y_] := FeynCalc`SharedObjects`Private`n*
     TemporalPair[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
TemporalPair /: MakeBoxes[TemporalPair[ExplicitLorentzIndex[0], 
       (FeynCalc`SharedObjectsTypesetting`Private`c0:
         (_.)*TemporalMomentum[
           FeynCalc`SharedObjectsTypesetting`Private`b_]) + 
        (FeynCalc`SharedObjectsTypesetting`Private`c1_:0)], 
      TraditionalForm] := 
     If[Head[FeynCalc`SharedObjectsTypesetting`Private`b] === Plus || 
       FeynCalc`SharedObjectsTypesetting`Private`c1 =!= 0, 
      SuperscriptBox[RowBox[{"(", TBox[TemporalMomentum[
           FeynCalc`SharedObjectsTypesetting`Private`c0 + 
            FeynCalc`SharedObjectsTypesetting`Private`c1]], ")"}], 0], 
      SuperscriptBox[RowBox[
        {TBox[FeynCalc`SharedObjectsTypesetting`Private`c0 + 
           FeynCalc`SharedObjectsTypesetting`Private`c1]}], 0]]
 
TemporalPair /: TemporalPair::invalid = 
     "`1` does not represent a valid TemporalPair object!"
 
TemporalPair /: TemporalPair::usage = "TemporalPair[ExplicitLorentzIndex[0], \
TemporalMomentum[p]] is a special\npairing used in the internal \
representation to denote $p^0$, the temporal\ncomponent of a 4-momentum $p$."
 
FeynCalc`SharedObjectsTypesetting`Private`gammaRep[
     FeynCalc`SharedObjectsTypesetting`Private`dim1_, 
     FeynCalc`SharedObjectsTypesetting`Private`dim2_, 
     FeynCalc`SharedObjectsTypesetting`Private`sym_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`dim1 === 4 && 
      FeynCalc`SharedObjectsTypesetting`Private`dim1 === 
       FeynCalc`SharedObjectsTypesetting`Private`dim2, 
     OverscriptBox[FeynCalc`SharedObjectsTypesetting`Private`sym, 
      $TypesettingDim4], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim1, _Symbol] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim1 === 
       FeynCalc`SharedObjectsTypesetting`Private`dim2, 
     If[$TypesettingDimD === "", 
      FeynCalc`SharedObjectsTypesetting`Private`sym, 
      OverscriptBox[FeynCalc`SharedObjectsTypesetting`Private`sym, 
       $TypesettingDimD]], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim1, _Symbol - 4] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim1 === 
       FeynCalc`SharedObjectsTypesetting`Private`dim2, 
     OverscriptBox[FeynCalc`SharedObjectsTypesetting`Private`sym, 
      $TypesettingDimE], True, SubscriptBox[
      FeynCalc`SharedObjectsTypesetting`Private`sym, 
      ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`dim1, 
       TraditionalForm]]]
 
FeynCalc`SharedObjectsTypesetting`Private`cgammaSigmaRep[
     FeynCalc`SharedObjectsTypesetting`Private`dim1_, 
     FeynCalc`SharedObjectsTypesetting`Private`dim2_, 
     FeynCalc`SharedObjectsTypesetting`Private`sym_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`dim1 === 3 && 
      FeynCalc`SharedObjectsTypesetting`Private`dim2 === 4, 
     OverscriptBox[TBox[Style[FeynCalc`SharedObjectsTypesetting`Private`sym, 
        Bold]], $TypesettingDim4], 
     MatchQ[{FeynCalc`SharedObjectsTypesetting`Private`dim1, 
       FeynCalc`SharedObjectsTypesetting`Private`dim2}, 
      {(FeynCalc`SharedObjectsTypesetting`Private`dim_Symbol) - 1, 
       FeynCalc`SharedObjectsTypesetting`Private`dim_Symbol}], 
     If[$TypesettingDimD === "", 
      TBox[Style[FeynCalc`SharedObjectsTypesetting`Private`sym, Bold]], 
      OverscriptBox[TBox[Style[FeynCalc`SharedObjectsTypesetting`Private`sym, 
         Bold]], $TypesettingDimD]], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim1, _Symbol - 4] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim1 === 
       FeynCalc`SharedObjectsTypesetting`Private`dim2, 
     OverscriptBox[TBox[Style[FeynCalc`SharedObjectsTypesetting`Private`sym, 
        Bold]], $TypesettingDimE], True, SubscriptBox[
      TBox[Style[FeynCalc`SharedObjectsTypesetting`Private`sym, Bold]], 
      ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`dim1, 
       TraditionalForm]]]
 
DiracSigma[(FeynCalc`SharedObjects`Private`a_) . 
      (FeynCalc`SharedObjects`Private`b_)] := 
    DiracSigma[FeynCalc`SharedObjects`Private`a, 
     FeynCalc`SharedObjects`Private`b]
 
DiracSigma[___, 0, ___] = 0
 
DiracSigma[FeynCalc`SharedObjects`Private`a_, 
     FeynCalc`SharedObjects`Private`a_] := 
    0 /; FCPatternFreeQ[{FeynCalc`SharedObjects`Private`a}]
 
DiracSigma[FeynCalc`SharedObjects`Private`a_, 
     FeynCalc`SharedObjects`Private`b_] := 
    -DiracSigma[FeynCalc`SharedObjects`Private`b, 
       FeynCalc`SharedObjects`Private`a] /; 
      !OrderedQ[{FeynCalc`SharedObjects`Private`a, 
         FeynCalc`SharedObjects`Private`b}] && FCPatternFreeQ[
       {FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`b}]
 
DiracSigma[DiracGamma[FeynCalc`SharedObjects`Private`b__]*
      (FeynCalc`SharedObjects`Private`a_), 
     DiracGamma[FeynCalc`SharedObjects`Private`d__]*
      (FeynCalc`SharedObjects`Private`c_.)] := 
    FeynCalc`SharedObjects`Private`a*FeynCalc`SharedObjects`Private`c*
     DiracSigma[DiracGamma[FeynCalc`SharedObjects`Private`b], 
      DiracGamma[FeynCalc`SharedObjects`Private`d]]
 
DiracSigma[DiracGamma[FeynCalc`SharedObjects`Private`b__]*
      (FeynCalc`SharedObjects`Private`a_.), 
     DiracGamma[FeynCalc`SharedObjects`Private`d__]*
      (FeynCalc`SharedObjects`Private`c_)] := 
    FeynCalc`SharedObjects`Private`a*FeynCalc`SharedObjects`Private`c*
     DiracSigma[DiracGamma[FeynCalc`SharedObjects`Private`b], 
      DiracGamma[FeynCalc`SharedObjects`Private`d]]
 
DiracSigma /: MakeBoxes[DiracSigma[(DiracGamma | GA | GAD | GS | GSD | CGA | 
         CGAD | CGS | CGSD | TGA)[
        FeynCalc`SharedObjectsTypesetting`Private`x_, ___], 
       (DiracGamma | GA | GAD | GS | GSD | CGA | CGAD | CGS | CGSD | TGA)[
        FeynCalc`SharedObjectsTypesetting`Private`y_, ___]], 
      TraditionalForm] := SuperscriptBox["\[Sigma]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`x, 
       FeynCalc`SharedObjectsTypesetting`Private`y]]
 
DiracSigma /: DiracSigma::usage = "DiracSigma[a, b] stands for $I/2(a.b-b.a)$ \
in 4 dimensions.\n\na and b must have head DiracGamma, GA or GS. Only \
antisymmetry is implemented."
 
GA[(FeynCalc`SharedObjects`Private`x_)?NumberQ] := 
    (Message[GA::noint, FeynCalc`SharedObjects`Private`x]; Abort[]) /; 
      !MemberQ[{0, 1, 2, 3, 5, 6, 7}, FeynCalc`SharedObjects`Private`x]
 
GA[(FeynCalc`SharedObjects`Private`x_) . 
      (FeynCalc`SharedObjects`Private`y__)] := 
    GA /@ DOT[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
GA[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ GA /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
GA /: MakeBoxes[GA[FeynCalc`SharedObjectsTypesetting`Private`x_ /; 
         !MemberQ[{5, 6, 7}, FeynCalc`SharedObjectsTypesetting`Private`x]], 
      TraditionalForm] := ToBoxes[DiracGamma[LorentzIndex[
        FeynCalc`SharedObjectsTypesetting`Private`x]], TraditionalForm]
 
GA /: MakeBoxes[GA[FeynCalc`SharedObjectsTypesetting`Private`x_ /; 
        MemberQ[{5, 6, 7}, FeynCalc`SharedObjectsTypesetting`Private`x]], 
      TraditionalForm] := ToBoxes[DiracGamma[
       FeynCalc`SharedObjectsTypesetting`Private`x], TraditionalForm]
 
GA /: GA::noint = "GA[`1`] is forbidden in FeynCalc. For consistency reasons, \
the only allowed integer arguments can be 0, 1, 2, 3, 5, 6 and 7. Evaluation \
aborted!"
 
GA /: GA::usage = "GA[mu] can be used as input for a 4-dimensional \
$\\gamma^{\\mu }$ and is\ntransformed into DiracGamma[LorentzIndex[mu]] by \
FeynCalcInternal (=FCI).\n\nGA[mu , nu , ...] is a short form for \
GA[mu].GA[nu]."
 
DOT = Dot
 
DOT /: DOT::usage = "DOT[a, b, ...] is the FeynCalc function for \
non-commutative multiplication. By\ndefault it is set to the Mathematica Dot \
function. This can in principle be\ndisabled by setting DOT=., but then \
non-commutative products should to be\nentered like DOT[ GA[mu], m + GS[p], \
GA[mu] ] etc."
 
GAD[(FeynCalc`SharedObjects`Private`x_)?NumberQ] := 
    (Message[GAD::noint, FeynCalc`SharedObjects`Private`x]; Abort[]) /; 
      !MemberQ[{0, 1, 2, 3, 5, 6, 7}, FeynCalc`SharedObjects`Private`x]
 
GAD[FeynCalc`SharedObjects`Private`n:5 | 6 | 7] := 
    GA[FeynCalc`SharedObjects`Private`n]
 
GAD[(FeynCalc`SharedObjects`Private`x_) . 
      (FeynCalc`SharedObjects`Private`y__)] := 
    GAD /@ DOT[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
GAD[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ GAD /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
GAD /: MakeBoxes[GAD[FeynCalc`SharedObjectsTypesetting`Private`x_], 
      TraditionalForm] := ToBoxes[DiracGamma[LorentzIndex[
        FeynCalc`SharedObjectsTypesetting`Private`x, D], D], TraditionalForm]
 
GAD /: GAD::noint = "GAD[`1`] is forbidden in FeynCalc. For consistency \
reasons, the only allowed integer arguments can be 0, 1, 2 and 3. Evaluation \
aborted!"
 
GAD /: GAD::usage = "GAD[mu] can be used as input for a $D$-dimensional \
$\\gamma ^{\\mu }$ and is\ntransformed into DiracGamma[LorentzIndex[mu,D],D] \
by FeynCalcInternal (=FCI).\n\nGAD[mu , nu , ...] is a short form for \
GAD[mu].GAD[nu]."
 
GS[0] := 0
 
GS[(FeynCalc`SharedObjects`Private`x_)?NumberQ] := 
    (Message[GS::noint, FeynCalc`SharedObjects`Private`x]; Abort[]) /; 
     FeynCalc`SharedObjects`Private`x =!= 0
 
GS[(FeynCalc`SharedObjects`Private`x_) . 
      (FeynCalc`SharedObjects`Private`y__)] := 
    GS /@ DOT[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
GS[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ GS /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
GS /: MakeBoxes[GS[FeynCalc`SharedObjectsTypesetting`Private`a_], 
      TraditionalForm] := ToBoxes[DiracGamma[
       Momentum[FeynCalc`SharedObjectsTypesetting`Private`a]], 
      TraditionalForm]
 
GS /: GS::noint = "GS[`1`] is forbidden in FeynCalc. For consistency reasons, \
the only allowed integer argument can be 0. Evaluation aborted!"
 
GS /: GS::usage = "GS[p] can be used as input for a 4-dimensional $p^\\mu \
\\gamma_\\mu$ and is\ntransformed into DiracGamma[Momentum[p]] by \
FeynCalcInternal (=FCI).\n\nGS[p,q, ...] is a short form for GS[p].GS[q]."
 
GSD[0] := 0
 
GSD[(FeynCalc`SharedObjects`Private`x_)?NumberQ] := 
    (Message[GSD::noint, FeynCalc`SharedObjects`Private`x]; Abort[]) /; 
     FeynCalc`SharedObjects`Private`x =!= 0
 
GSD[(FeynCalc`SharedObjects`Private`x_) . 
      (FeynCalc`SharedObjects`Private`y__)] := 
    GSD /@ DOT[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
GSD[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ GSD /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
GSD /: MakeBoxes[GSD[FeynCalc`SharedObjectsTypesetting`Private`a_], 
      TraditionalForm] := ToBoxes[DiracGamma[
       Momentum[FeynCalc`SharedObjectsTypesetting`Private`a, D], D], 
      TraditionalForm]
 
GSD /: GSD::noint = "GSD[`1`] is forbidden in FeynCalc. For consistency \
reasons, the only allowed integer argument can be 0. Evaluation aborted!"
 
GSD /: GSD::usage = "GSD[p] can be used as input for a $D$-dimensional \
$p^\\mu \\gamma_\\mu$ and is\ntransformed into DiracGamma[Momentum[p,D],D] by \
FeynCalcInternal (=FCI).\n\nGSD[p,q, ...] is a short form for GSD[p].GSD[q]."
 
CGA[_?NumberQ] := (Message[SharedObjects::failmsg, 
      "Explicit indices are not supported inside Cartesian objects."]; 
     Abort[])
 
CGA[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ CGA /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
CGA /: MakeBoxes[CGA[FeynCalc`SharedObjectsTypesetting`Private`x_], 
      TraditionalForm] := ToBoxes[DiracGamma[CartesianIndex[
        FeynCalc`SharedObjectsTypesetting`Private`x]], TraditionalForm]
 
CGA /: CGA::usage = "CGA[i] can be used as input for $\\gamma^i$ in 4 \
dimensions, where i is a\nCartesian index, and is transformed into \
DiracGamma[CartesianIndex[i]] by\nFeynCalcInternal."
 
CGAD[_?NumberQ] := (Message[SharedObjects::failmsg, 
      "Explicit indices are not supported inside Cartesian objects."]; 
     Abort[])
 
CGAD[FeynCalc`SharedObjects`Private`x_, 
     FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ CGAD /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
CGAD /: MakeBoxes[CGAD[FeynCalc`SharedObjectsTypesetting`Private`x_], 
      TraditionalForm] := ToBoxes[DiracGamma[CartesianIndex[
        FeynCalc`SharedObjectsTypesetting`Private`x, D - 1], D], 
      TraditionalForm]
 
CGAD /: CGAD::usage = "CGAD[i] can be used as input for $\\gamma ^i$ in $D$ \
dimensions, where i is a\nCartesian index, and is transformed into \
DiracGamma[CartesianIndex[i,D-1],D]\nby FeynCalcInternal."
 
CGS[0] = 0
 
CGS[_?NumberQ] := (Message[SharedObjects::failmsg, 
      "Explicit indices are not supported inside Cartesian objects."]; 
     Abort[])
 
CGS[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ CGS /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
CGS /: MakeBoxes[CGS[FeynCalc`SharedObjectsTypesetting`Private`x_], 
      TraditionalForm] := ToBoxes[DiracGamma[CartesianMomentum[
        FeynCalc`SharedObjectsTypesetting`Private`x]], TraditionalForm]
 
CGS /: CGS::usage = "CGS[p] is transformed into \
DiracGamma[CartesianMomentum[p]] by\nFeynCalcInternal.\n\nCGS[p,q, ...] is \
equivalent to CGS[p].CGS[q]."
 
CGSD[0] = 0
 
CGSD[_?NumberQ] := (Message[SharedObjects::failmsg, 
      "Explicit indices are not supported inside Cartesian objects."]; 
     Abort[])
 
CGSD[FeynCalc`SharedObjects`Private`x_, 
     FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ CGSD /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
CGSD /: MakeBoxes[CGSD[FeynCalc`SharedObjectsTypesetting`Private`x_], 
      TraditionalForm] := ToBoxes[DiracGamma[CartesianMomentum[
        FeynCalc`SharedObjectsTypesetting`Private`x, D - 1], D], 
      TraditionalForm]
 
CGSD /: CGSD::usage = "CGSD[p] is transformed into \
DiracGamma[CartesianMomentum[p, D-1], D] by\nFeynCalcInternal.\n\nCGSD[p,q, \
...] is equivalent to CGSD[p].CGSD[q]."
 
TGA /: MakeBoxes[TGA[], TraditionalForm] := 
     ToBoxes[DiracGamma[ExplicitLorentzIndex[0]], TraditionalForm]
 
TGA /: TGA::usage = "TGA[]  can be used as input for $\\gamma^0$ in $4$ \
dimensions and is\ntransformed into DiracGamma[ExplicitLorentzIndex[0]] by \
FeynCalcInternal."
 
GAE[(FeynCalc`SharedObjects`Private`x_)?NumberQ] := 
    (Message[GAE::noint, FeynCalc`SharedObjects`Private`x]; Abort[]) /; 
      !MemberQ[{0, 1, 2, 3, 5, 6, 7}, FeynCalc`SharedObjects`Private`x]
 
GAE[5 | 6 | 7] := (Message[SharedObjects::failmsg, 
      "D-4 dimensional g^5 or chiral projectors do not exist!"]; Abort[])
 
GAE[(FeynCalc`SharedObjects`Private`x_) . 
      (FeynCalc`SharedObjects`Private`y__)] := 
    GAE /@ DOT[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
GAE[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ GAE /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
GAE /: MakeBoxes[GAE[FeynCalc`SharedObjectsTypesetting`Private`x_], 
      TraditionalForm] := ToBoxes[DiracGamma[LorentzIndex[
        FeynCalc`SharedObjectsTypesetting`Private`x, D - 4], D - 4], 
      TraditionalForm]
 
GAE /: GAE::noint = "GAE[`1`] is forbidden in FeynCalc. For consistency \
reasons, the only allowed integer arguments can be 0, 1, 2 and 3. Evaluation \
aborted!"
 
GAE /: GAE::usage = "GAE[mu] can be used as input for a D-4-dimensional \
$\\gamma^{\\mu }$and is\ntransformed into DiracGamma[LorentzIndex[mu, D-4], \
D-4] by FeynCalcInternal\n(FCI).\n\nGAE[mu, nu , ...] is a short form for \
GAE[mu].GAE[nu] ...."
 
GSE[0] := 0
 
GSE[(FeynCalc`SharedObjects`Private`x_)?NumberQ] := 
    (Message[GSE::noint, FeynCalc`SharedObjects`Private`x]; Abort[]) /; 
     FeynCalc`SharedObjects`Private`x =!= 0
 
GSE[(FeynCalc`SharedObjects`Private`x_) . 
      (FeynCalc`SharedObjects`Private`y__)] := 
    GSE /@ DOT[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
GSE[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y__] := 
    DOT @@ GSE /@ {FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}
 
GSE /: MakeBoxes[GSE[FeynCalc`SharedObjectsTypesetting`Private`a_], 
      TraditionalForm] := ToBoxes[DiracGamma[
       Momentum[FeynCalc`SharedObjectsTypesetting`Private`a, D - 4], D - 4], 
      TraditionalForm]
 
GSE /: GSE::noint = "GSE[`1`] is forbidden in FeynCalc. For consistency \
reasons, the only allowed integer argument can be 0. Evaluation aborted!"
 
GSE /: GSE::usage = "GSE[p] can be used as input for a $D-4$-dimensional \
$\\gamma \\cdot p =\n\\gamma^\\mu p_\\mu$ and is transformed into \
DiracGamma[Momentum[p,D-4],D-4] by\nFeynCalcInternal (FCI). GSE[p,q, ...] is \
a short form for GSE[p].GSE[q]. ...."
 
GSLP[0, ___] := 0
 
GSLP[FeynCalc`SharedObjects`Private`x_] := 
    GSLP[FeynCalc`SharedObjects`Private`x, $FCDefaultLightconeVectorN, 
      $FCDefaultLightconeVectorNB] /; FCPatternFreeQ[
      {FeynCalc`SharedObjects`Private`x}]
 
GSLP /: MakeBoxes[GSLP[FeynCalc`SharedObjectsTypesetting`Private`x_, 
       FeynCalc`SharedObjectsTypesetting`Private`n_, 
       FeynCalc`SharedObjectsTypesetting`Private`nb_], TraditionalForm] := 
     ToBoxes[(1/2)*Pair[Momentum[
         FeynCalc`SharedObjectsTypesetting`Private`nb], 
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`x]]*
       DiracGamma[Momentum[FeynCalc`SharedObjectsTypesetting`Private`n]], 
      TraditionalForm]
 
GSLP /: GSLP::usage = "GSLP[p,n,nb] denotes the positive component in the \
lightcone decomposition of\nthe slashed Dirac matrix $(\\gamma \\cdot p)$  \
along the vectors n and nb. It\ncorresponds to $\\frac{1}{2} (\\bar{n} \\cdot \
p) (\\gamma \\cdot n)$.\n\nIf one omits n and nb, the program will use \
default vectors specified via\n$FCDefaultLightconeVectorN and \
$FCDefaultLightconeVectorNB."
 
$FCDefaultLightconeVectorN := FCGV["n"]
 
($FCDefaultLightconeVectorN = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$FCDefaultLightconeVectorN] = 
           {HoldPattern[$FCDefaultLightconeVectorN] :> 
             FeynCalc`Private`xxx}; , DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$FCDefaultLightconeVectorN] = 
       {HoldPattern[$FCDefaultLightconeVectorN] :> FeynCalc`Private`xxx}]; 
     FeynCalc`Private`val)
 
$FCDefaultLightconeVectorN /: $FCDefaultLightconeVectorN::usage = "$FCDefault\
LightconeVectorN is  a global variable which is set to FCGV[\"n\"].\nIt \
denotes the default name for the vector $n$ in the lightcone \
decomposition\nfor Lorentz tensors."
 
$FCDefaultLightconeVectorNB := FCGV["nb"]
 
($FCDefaultLightconeVectorNB = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$FCDefaultLightconeVectorNB] = 
           {HoldPattern[$FCDefaultLightconeVectorNB] :> 
             FeynCalc`Private`xxx}; , DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$FCDefaultLightconeVectorNB] = 
       {HoldPattern[$FCDefaultLightconeVectorNB] :> FeynCalc`Private`xxx}]; 
     FeynCalc`Private`val)
 
$FCDefaultLightconeVectorNB /: $FCDefaultLightconeVectorNB::usage = "$FCDefau\
ltLightconeVectorNB is  a global variable which is set to\nFCGV[\"nb\"]. It \
denotes the default name for the vector $\\bar{n}$ in the\nlightcone \
decomposition for Lorentz tensors."
 
GSLN[0, ___] := 0
 
GSLN[FeynCalc`SharedObjects`Private`x_] := 
    GSLN[FeynCalc`SharedObjects`Private`x, $FCDefaultLightconeVectorN, 
      $FCDefaultLightconeVectorNB] /; FCPatternFreeQ[
      {FeynCalc`SharedObjects`Private`x}]
 
GSLN /: MakeBoxes[GSLN[FeynCalc`SharedObjectsTypesetting`Private`x_, 
       FeynCalc`SharedObjectsTypesetting`Private`n_, 
       FeynCalc`SharedObjectsTypesetting`Private`nb_], TraditionalForm] := 
     ToBoxes[(1/2)*Pair[Momentum[
         FeynCalc`SharedObjectsTypesetting`Private`n], 
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`x]]*
