PauliSigma[ExplicitLorentzIndex[0]] = 1
 
PauliSigma[_, 0] := 0
 
PauliSigma[0, ___] := 0
 
PauliSigma[FeynCalc`SharedObjects`Private`x_, 
      FeynCalc`SharedObjects`Private`y_, 
      FeynCalc`SharedObjects`Private`z__] /; 
      !MemberQ[{1, 2}, Length[{FeynCalc`SharedObjects`Private`x, 
          FeynCalc`SharedObjects`Private`y, 
          FeynCalc`SharedObjects`Private`z}]] && FCPatternFreeQ[
       {FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y, 
        FeynCalc`SharedObjects`Private`z}] := 
    (Message[PauliSigma::argrx, StringJoin["PauliSigma[", 
       ToString[{FeynCalc`SharedObjects`Private`x, 
         FeynCalc`SharedObjects`Private`y, 
         FeynCalc`SharedObjects`Private`z}], "]"], 
      Length[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`z}], 
      "1 or 2"]; Abort[])
 
