     FeynCalc`SharedObjects`Private`dim___] := 
    (PauliSigma[#1, FeynCalc`SharedObjects`Private`dim] & ) /@ 
     FeynCalc`SharedObjects`Private`a
 
PauliSigma[FeynCalc`SharedObjects`Private`x_, 3] := 
    PauliSigma[FeynCalc`SharedObjects`Private`x]
 
PauliSigma[(FeynCalc`SharedObjects`Private`x_)*
      (FeynCalc`SharedObjects`Private`h:TemporalMomentum | 
