       FeynCalc`SharedObjects`Private`dim1], 
      FeynCalc`SharedObjects`Private`dim2]
 
PauliSigma[(LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
       CartesianMomentum)[_], -4 + _Symbol] := 0
 
PauliSigma[_TemporalMomentum | ExplicitLorentzIndex[0], -4 + _Symbol] := 0
 
