      (Pair[LorentzIndex[\[Mu], D], Momentum[k1, D]]*
        Pair[LorentzIndex[\[Nu], D], Momentum[k1, D]] + 
       (Pair[LorentzIndex[\[Mu], D], Momentum[k1, D]]*
         Pair[LorentzIndex[\[Nu], D], Momentum[k2, D]]*Pair[Momentum[k1, D], 
          Momentum[k3, D]])/Pair[Momentum[k2, D], Momentum[k3, D]])] = True
 
NonCommFreeQ[Pair[LorentzIndex[\[Mu], D], Momentum[k2 + 2*l, D]]*
      Pair[LorentzIndex[\[Nu], D], Momentum[k3 - 2*l, D]]*
      (Pair[LorentzIndex[\[Mu], D], Momentum[k1, D]]*
