        Pair[Momentum[k2, D], Momentum[k3, D]])] = True
 
NonCommFreeQ[Pair[LorentzIndex[\[Mu], D], Momentum[2*k1 + k2 + 2*k3 - 2*l, 
        D]]*Pair[LorentzIndex[\[Nu], D], Momentum[2*k1 + k3 - 2*l, D]]*
      (Pair[LorentzIndex[\[Mu], D], Momentum[k3, D]]*
        Pair[LorentzIndex[\[Nu], D], Momentum[k2, D]] - 
       Pair[LorentzIndex[\[Mu], D], LorentzIndex[\[Nu], D]]*
        Pair[Momentum[k2, D], Momentum[k3, D]])] = True
 
NonCommFreeQ[Pair[LorentzIndex[\[Mu], D], Momentum[k2 - 2*l, D]]*
      Pair[LorentzIndex[\[Nu], D], Momentum[2*k1 + 2*k2 + k3 - 2*l, D]]*
      (Pair[LorentzIndex[\[Mu], D], Momentum[k3, D]]*
        Pair[LorentzIndex[\[Nu], D], Momentum[k2, D]] - 
       Pair[LorentzIndex[\[Mu], D], LorentzIndex[\[Nu], D]]*
        Pair[Momentum[k2, D], Momentum[k3, D]])] = True
 
NonCommFreeQ[Pair[LorentzIndex[\[Mu], D], Momentum[2*k1 + k2 - 2*l, D]]*
      Pair[LorentzIndex[\[Nu], D], Momentum[2*k1 + 2*k2 + k3 - 2*l, D]]*
      (Pair[LorentzIndex[\[Mu], D], Momentum[k3, D]]*
        Pair[LorentzIndex[\[Nu], D], Momentum[k2, D]] - 
       Pair[LorentzIndex[\[Mu], D], LorentzIndex[\[Nu], D]]*
        Pair[Momentum[k2, D], Momentum[k3, D]])] = True
 
