NonCommFreeQ[_?NumberQ] := True
 
NonCommFreeQ[FeynCalc`NonCommutative`Private`x_] := 
    MemSet[NonCommFreeQ[FeynCalc`NonCommutative`Private`x], 
     If[ !FreeQ2[FeynCalc`NonCommutative`Private`x, {DiracTrace, PauliTrace, 
         SUNTrace}], FreeQ2[FeynCalc`NonCommutative`Private`x /. 
        FeynCalc`NonCommutative`Private`excludeTraces, $NonComm], 
      FreeQ2[FeynCalc`NonCommutative`Private`x, $NonComm]]]
 
NonCommFreeQ /: NonCommFreeQ::usage = "NonCommFreeQ[exp] yields True if exp \
contains no non-commutative objects (i.e.\nthose objects which are listed in \
$NonComm) or only non-commutative objects\ninside DiracTraces or SUNTraces."
 
NonCommQ[_?NumberQ] := False
 
NonCommQ[FeynCalc`NonCommutative`Private`x_] := 
    MemSet[NonCommQ[FeynCalc`NonCommutative`Private`x], 
     If[ !FreeQ2[FeynCalc`NonCommutative`Private`x, {DiracTrace, PauliTrace, 
         SUNTrace}],  !FreeQ2[FeynCalc`NonCommutative`Private`x /. 
         FeynCalc`NonCommutative`Private`excludeTraces, $NonComm], 
       !FreeQ2[FeynCalc`NonCommutative`Private`x, $NonComm]]]
 
NonCommQ /: NonCommQ::usage = "NonCommQ[exp] yields True if exp contains \
non-commutative objects (i.e. those\nobjects which are listed in $NonComm) \
not inside DiracTraces or SUNTraces."
 
Attributes[MemSet] = {HoldFirst}
 
MemSet[FeynCalc`SharedTools`Private`x_, FeynCalc`SharedTools`Private`y_, 
     OptionsPattern[]] := 
    If[OptionValue[FCMemoryAvailable] - MemoryInUse[]/1.*^6 < 1. || 
       $DisableMemSet, FeynCalc`SharedTools`Private`y, 
      FeynCalc`SharedTools`Private`x = FeynCalc`SharedTools`Private`y] /; 
     MatchQ[OptionValue[FCMemoryAvailable], _Integer?NonNegative]
 
MemSet[_, _, OptionsPattern[]] := 
    (Message[FeynCalc::failmsg, 
       "The value of $FCMemoryAvailable must be a nonnegative integer."]; 
      Abort[]) /;  !MatchQ[OptionValue[FCMemoryAvailable], 
       _Integer?NonNegative]
 
Options[MemSet] = {FCMemoryAvailable :> $FCMemoryAvailable}
 
MemSet /: MemSet::usage = "MemSet[f[x_], body] is like f[x_] := f[x] = body, \
but depending on the value\nof the setting of FCMemoryAvailable -> memorycut \
(memorycut -\nMemoryInUse[]/10^6)\n\nMemSet[f[x_], body] may evaluate as \
f[x_] := body."
 
FCMemoryAvailable /: FCMemoryAvailable::usage = "FCMemoryAvailable is an \
option of MemSet. It can be set to an integer n, where\nn is the available \
amount of main memory in MiB. The default setting is\n$FCMemoryAvailable."
 
$DisableMemSet := False
 
($DisableMemSet = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$DisableMemSet] = 
           {HoldPattern[$DisableMemSet] :> FeynCalc`Private`xxx}; , 
         DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$DisableMemSet] = {HoldPattern[$DisableMemSet] :> 
         FeynCalc`Private`xxx}]; FeynCalc`Private`val)
 
$DisableMemSet /: $DisableMemSet::usage = "The boolean setting of \
$DisableMemSet allows to disable memoization that is\nactivated via MemSet. \
This can be useful for debugging purposes."
 
$FCMemoryAvailable := 4294
 
($FCMemoryAvailable = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$FCMemoryAvailable] = 
           {HoldPattern[$FCMemoryAvailable] :> FeynCalc`Private`xxx}; , 
         DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$FCMemoryAvailable] = {HoldPattern[$FCMemoryAvailable] :> 
         FeynCalc`Private`xxx}]; FeynCalc`Private`val)
 
$FCMemoryAvailable /: $FCMemoryAvailable::usage = "$FCMemoryAvailable is  a \
global variable which is set to an integer n, where n\nis the available \
amount of main memory in MB. The default is 1/4 of\n$SystemMemory. It should \
be increased if possible. The higher\n$FCMemoryAvailable can be, the more \
intermediate steps do not have to be\nrepeated by FeynCalc."
 
DiracTrace[0, OptionsPattern[]] := 0
 
DiracTrace[FeynCalc`DiracTrace`Private`a:Except[_HoldAll]..., 
     FeynCalc`DiracTrace`Private`x_, FeynCalc`DiracTrace`Private`y_, 
     FeynCalc`DiracTrace`Private`z___] := 
    DiracTrace[FeynCalc`DiracTrace`Private`a, FeynCalc`DiracTrace`Private`x . 
       FeynCalc`DiracTrace`Private`y, FeynCalc`DiracTrace`Private`z] /; 
     FCPatternFreeQ[{FeynCalc`DiracTrace`Private`x, 
       FeynCalc`DiracTrace`Private`y}, {Rule}]
 
DiracTrace[FeynCalc`DiracTrace`Private`expr_, FeynCalc`DiracTrace`Private`op:
      OptionsPattern[]] := Block[{FeynCalc`DiracTrace`Private`ex, 
       FeynCalc`DiracTrace`Private`res, FeynCalc`DiracTrace`Private`time, 
       FeynCalc`DiracTrace`Private`dsHead, 
       FeynCalc`DiracTrace`Private`diracObjects, 
       FeynCalc`DiracTrace`Private`diracObjectsEval, 
       FeynCalc`DiracTrace`Private`null1, FeynCalc`DiracTrace`Private`null2, 
       FeynCalc`DiracTrace`Private`freePart, 
       FeynCalc`DiracTrace`Private`dsPart, 
       FeynCalc`DiracTrace`Private`repRule, FeynCalc`DiracTrace`Private`diTr, 
       FeynCalc`DiracTrace`Private`holdDOT, 
       FeynCalc`DiracTrace`Private`insideDiracTrace}, 
      If[OptionValue[FCVerbose] === False, 
        FeynCalc`DiracTrace`Private`diTrVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[FCVerbose], _Integer], 
          FeynCalc`DiracTrace`Private`diTrVerbose = OptionValue[
            FCVerbose]]; ]; FeynCalc`DiracTrace`Private`unitMatrixTrace = 
        OptionValue[TraceOfOne]; FeynCalc`DiracTrace`Private`optSort = 
        OptionValue[Sort]; FCPrint[1, "DiracTrace: Entering.", 
        FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
       FCPrint[3, "DiracTrace: Entering with ", 
        FeynCalc`DiracTrace`Private`expr, FCDoControl -> 
         FeynCalc`DiracTrace`Private`diTrVerbose]; If[OptionValue[FCI], 
        FeynCalc`DiracTrace`Private`ex = FeynCalc`DiracTrace`Private`expr, 
        FeynCalc`DiracTrace`Private`ex = 
         FCI[FeynCalc`DiracTrace`Private`expr]]; 
       FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
       If[OptionValue[Contract] =!= False && 
          !DummyIndexFreeQ[FeynCalc`DiracTrace`Private`ex, 
           {LorentzIndex, CartesianIndex}], 
        FCPrint[1, "DiracTrace. Applying Contract.", FCDoControl -> 
           FeynCalc`DiracTrace`Private`diTrVerbose]; 
         FeynCalc`DiracTrace`Private`ex = Contract[
           FeynCalc`DiracTrace`Private`ex, Expanding -> True, 
           EpsContract -> OptionValue[EpsContract], Factoring -> False]; 
         FCPrint[1, "DiracTrace: Contract done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
          FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]]; 
       If[OptionValue[FCDiracIsolate], 
        FCPrint[1, "DiracTrace: Standard mode.", FCDoControl -> 
           FeynCalc`DiracTrace`Private`diTrVerbose]; 
         FeynCalc`DiracTrace`Private`ex = FCDiracIsolate[
           FeynCalc`DiracTrace`Private`ex, FCI -> True, 
           Head -> FeynCalc`DiracTrace`Private`dsHead, Spinor -> False, 
           DiracTrace -> False, DiracSigmaExplicit -> True]; 
         FeynCalc`DiracTrace`Private`ex = FeynCalc`DiracTrace`Private`ex /. 
           DiracTrace -> FeynCalc`DiracTrace`Private`diTr; 
         {FeynCalc`DiracTrace`Private`freePart, 
           FeynCalc`DiracTrace`Private`dsPart} = 
          FCSplit[FeynCalc`DiracTrace`Private`ex, 
           {FeynCalc`DiracTrace`Private`dsHead}]; FCPrint[3, 
          "DiracTrace: dsPart: ", FeynCalc`DiracTrace`Private`dsPart, 
          FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
         FCPrint[3, "DiracTrace: freePart: ", 
          FeynCalc`DiracTrace`Private`freePart, FCDoControl -> 
           FeynCalc`DiracTrace`Private`diTrVerbose]; 
         If[FeynCalc`DiracTrace`Private`dsPart =!= 0, 
          Scan[If[ !MatchQ[#1, (FeynCalc`DiracTrace`Private`a_.)*
                  FeynCalc`DiracTrace`Private`dsHead[
                   FeynCalc`DiracTrace`Private`b_] /; 
                 FreeQ[{FeynCalc`DiracTrace`Private`a, 
                    FeynCalc`DiracTrace`Private`b}, 
                   FeynCalc`DiracTrace`Private`dsHead] && 
                   !FreeQ[FeynCalc`DiracTrace`Private`b, DiracGamma]], 
              Message[DiracTrace::failmsg, "Irregular trace structure in", 
                InputForm[#1]]; Print[#1]; Abort[]] & , 
            FeynCalc`DiracTrace`Private`dsPart + 
             FeynCalc`DiracTrace`Private`dsHead[DiracGamma]]; ]; 
         FeynCalc`DiracTrace`Private`diracObjects = 
          Union[Cases[FeynCalc`DiracTrace`Private`dsPart + 
             FeynCalc`DiracTrace`Private`null1 + 
             FeynCalc`DiracTrace`Private`null2, 
            FeynCalc`DiracTrace`Private`dsHead[_], Infinity]], 
        FCPrint[1, "DiracTrace: Fast mode.", FCDoControl -> 
           FeynCalc`DiracTrace`Private`diTrVerbose]; 
         If[ !FreeQ[FeynCalc`DiracTrace`Private`ex, DiracGamma], 
          FeynCalc`DiracTrace`Private`freePart = 0; 
           If[ !FreeQ[FeynCalc`DiracTrace`Private`ex, DiracSigma], 
            FeynCalc`DiracTrace`Private`ex = DiracSigmaExplicit[
              FeynCalc`DiracTrace`Private`ex, FCI -> True]]; 
           FeynCalc`DiracTrace`Private`dsPart = 
            FeynCalc`DiracTrace`Private`dsHead[
              FeynCalc`DiracTrace`Private`ex] /. DiracTrace -> 
              FeynCalc`DiracTrace`Private`diTr; 
           FeynCalc`DiracTrace`Private`diracObjects = 
            {FeynCalc`DiracTrace`Private`dsPart}, 
          FeynCalc`DiracTrace`Private`freePart = 
            FeynCalc`DiracTrace`Private`ex; 
           FeynCalc`DiracTrace`Private`dsPart = 0; 
           FeynCalc`DiracTrace`Private`diracObjects = {}]; ]; 
       FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
       FCPrint[1, "DiracTrace. Applying diracTrickEvalFast.", 
        FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
       FeynCalc`DiracTrace`Private`insideDiracTrace = 
        FeynCalc`DiracTrick`Private`insideDiracTrace; 
       FeynCalc`DiracTrick`Private`insideDiracTrace = True; 
       FeynCalc`DiracTrace`Private`diracObjectsEval = 
        (FeynCalc`DiracTrick`Private`diracTrickEvalFast[#1] & ) /@ 
          (FeynCalc`DiracTrace`Private`diracObjects /. 
           FeynCalc`DiracTrace`Private`dsHead -> Identity) /. 
         FeynCalc`DiracTrick`Private`diracTrickEvalFast -> Identity; 
       FeynCalc`DiracTrick`Private`insideDiracTrace = 
        FeynCalc`DiracTrace`Private`insideDiracTrace; 
       FCPrint[1, "DiracTrace: After diracTrickEvalFast: ", 
        FeynCalc`DiracTrace`Private`diracObjectsEval, 
        FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
       FeynCalc`DiracTrace`Private`diracObjectsEval = 
        (FeynCalc`DiracTrace`Private`diracTraceEvaluate[#1, 
           Flatten[Join[{FeynCalc`DiracTrace`Private`op}, FilterRules[
              Options[DiracTrace], Except[{
                FeynCalc`DiracTrace`Private`op}]]]]] & ) /@ 
         FeynCalc`DiracTrace`Private`diracObjectsEval; 
       FeynCalc`DiracTrace`Private`diracObjectsEval = 
        FeynCalc`DiracTrace`Private`diracObjectsEval /. 
         FeynCalc`DiracTrace`Private`noSpur[
           FeynCalc`DiracTrace`Private`x__] :> 
          FeynCalc`DiracTrace`Private`diTr[
            DOT[FeynCalc`DiracTrace`Private`x]]/
           FeynCalc`DiracTrace`Private`unitMatrixTrace; 
       FCPrint[1, "DiracTrace: diracTraceEvaluate finished, timing: ", 
        N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
        FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
       FeynCalc`DiracTrace`Private`repRule = 
        Thread[FeynCalc`DiracTrace`Private`diracObjects -> 
          FeynCalc`DiracTrace`Private`diracObjectsEval]; 
       FCPrint[3, "DiracTrace: repRule: ", 
        FeynCalc`DiracTrace`Private`repRule, FCDoControl -> 
         FeynCalc`DiracTrace`Private`diTrVerbose]; 
       If[ !FreeQ[FeynCalc`DiracTrace`Private`freePart, DOT], 
        FeynCalc`DiracTrace`Private`freePart = 
         FeynCalc`DiracTrace`Private`freePart /. DOT -> 
             FeynCalc`DiracTrace`Private`holdDOT /. 
           FeynCalc`DiracTrace`Private`holdDOT[
              FeynCalc`DiracTrace`Private`a__] /; NonCommFreeQ[
              {FeynCalc`DiracTrace`Private`a}] :> 
            Times[FeynCalc`DiracTrace`Private`a] /. 
          FeynCalc`DiracTrace`Private`holdDOT -> DOT]; 
       FeynCalc`DiracTrace`Private`res = 
        FeynCalc`DiracTrace`Private`unitMatrixTrace*
          FeynCalc`DiracTrace`Private`freePart + 
         (FeynCalc`DiracTrace`Private`dsPart /. Dispatch[
           FeynCalc`DiracTrace`Private`repRule]); 
       FCPrint[3, "DiracTrace: Preliminary result: ", 
        FeynCalc`DiracTrace`Private`res, FCDoControl -> 
         FeynCalc`DiracTrace`Private`diTrVerbose]; 
       If[Length[OptionValue[Mandelstam]] > 0, 
        FeynCalc`DiracTrace`Private`res = TrickMandelstam @@ 
           Prepend[{OptionValue[Mandelstam]}, 
            FeynCalc`DiracTrace`Private`res]; FCPrint[3, 
          "DiracTrace: After TrickMandelstam: ", 
          FeynCalc`DiracTrace`Private`res, FCDoControl -> 
           FeynCalc`DiracTrace`Private`diTrVerbose]]; 
       If[OptionValue[FeynCalcExternal], FeynCalc`DiracTrace`Private`res = 
         FCE[FeynCalc`DiracTrace`Private`res]]; 
       If[ !FreeQ[FeynCalc`DiracTrace`Private`res /. 
           FeynCalc`DiracTrace`Private`diTr[_] :> 1, DiracGamma], 
        Message[DiracTrace::failmsg, 
          "The output still contains Dirac matrices"]; Abort[]]; 
       FeynCalc`DiracTrace`Private`res = FeynCalc`DiracTrace`Private`res /. 
         FeynCalc`DiracTrace`Private`diTr -> DiracTrace; 
       FCPrint[1, "DiracTrace: Leaving.", FCDoControl -> 
         FeynCalc`DiracTrace`Private`diTrVerbose]; 
       FCPrint[3, "DiracTrace: Leaving with", 
        FeynCalc`DiracTrace`Private`res, FCDoControl -> 
         FeynCalc`DiracTrace`Private`diTrVerbose]; 
       FeynCalc`DiracTrace`Private`res] /; OptionValue[DiracTraceEvaluate]
 
DiracTrace /: MakeBoxes[DiracTrace[FeynCalc`DiracTrace`Private`expr__, 
       OptionsPattern[]], TraditionalForm] := 
     RowBox[{"tr", "(", TBox[FeynCalc`DiracTrace`Private`expr], ")"}]
 
Options[DiracTrace] = {Contract -> True, DiracTraceEvaluate -> False, 
     EpsContract -> False, EpsExpand -> True, EpsEvaluate -> True, 
     Expand -> True, FCVerbose -> False, Factoring -> Automatic, 
     FCDiracIsolate -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, LarinMVV -> True, Mandelstam -> {}, 
     PairCollect -> False, Sort -> True, TraceOfOne -> 4, West -> True}
 
DiracTrace /: DiracTrace::failmsg = "Error! DiracTrace has encountered a \
fatal problem and must abort the computation. The problem reads: `1`"
 
DiracTrace /: DiracTrace::larinmultiple = "Detected string of Dirac matrices \
containing more than two g^5 matrices in the Larin scheme. Since the pairing \
of the resulting Eps-tensors depends on their physical origin, FeynCalc will \
disable all such contractions in this calculation by wrapping their heads \
with Hold. The correct order of contractions cannot be determined \
automatically and must be specified by the user. The Hold head can be removed \
using FRH."
 
DiracTrace /: DiracTrace::mixmsg = "Expressions that mix D-, 4- and \
D-4-dimensional quantities are forbidden in Dirac matrix chains unless you \
are using the t'Hooft-Veltman scheme. For every other scheme, please recheck \
your input expressions and ensure that all matrices, spinors and tensors are \
purely D-dimensional. You might want to use FCGetDimensions[exp] to find the \
offending terms and fix them by hand or employ ChangeDimension[exp,D] to \
convert the whole expression to D-dimensions. If you explicitly intend to use \
the t'Hooft-Veltman scheme, please activate it via \
FCSetDiracGammaScheme[\"BMHV\"]."
 
DiracTrace /: DiracTrace::usage = "DiracTrace[exp] is the head of Dirac \
traces. By default the trace is not\nevaluated. The evaluation occurs only \
when the option DiracTraceEvaluate is\nset to True. It is recommended to use \
DiracSimplify, which will automatically\nevaluate all Dirac traces in the \
input expression."
 
FeynCalc`DiracTrace`Private`diTrVerbose /: 
    FeynCalc`DiracTrace`Private`diTrVerbose::usage = ""
 
FeynCalc`DiracTrace`Private`unitMatrixTrace /: 
    FeynCalc`DiracTrace`Private`unitMatrixTrace::usage = ""
 
TraceOfOne /: TraceOfOne::usage = "TraceOfOne is an option for TR and \
DiracTrace. Its setting determines the\nvalue of the unit trace."
 
FeynCalc`DiracTrace`Private`optSort /: 
    FeynCalc`DiracTrace`Private`optSort::usage = ""
 
FCI = FeynCalcInternal
 
FCI /: FCI::usage = "FCI[exp] translates exp into the internal FeynCalc \
(datatype-)representation.\n\nFCI is equivalent to FeynCalcInternal."
 
Attributes[FeynCalcInternal] = {HoldFirst}
 
FeynCalcInternal[FeynCalc`FeynCalcInternal`Private`x_, 
     FeynCalc`FeynCalcInternal`Private`opts___Rule] := 
    Block[{FeynCalc`FeynCalcInternal`Private`ru, 
      FeynCalc`FeynCalcInternal`Private`revru, 
      FeynCalc`FeynCalcInternal`Private`uru}, 
     FeynCalc`FeynCalcInternal`Private`uru = 
       FinalSubstitutions /. {FeynCalc`FeynCalcInternal`Private`opts} /. 
        Options[FeynCalcInternal]; FeynCalc`FeynCalcInternal`Private`uru = 
       Flatten[{FeynCalc`FeynCalcInternal`Private`uru}]; 
