Options[FeynCalcInternal] = {FinalSubstitutions -> {}}
 
FeynCalcInternal /: FeynCalcInternal::usage = "FeynCalcInternal[exp] \
translates exp into the internal FeynCalc (abstract\ndata-type) \
representation."
 
FinalSubstitutions /: FinalSubstitutions::usage = "FinalSubstitutions is an \
option for various functions. All substitutions\nindicated hereby are done at \
the end of the calculation."
 
FeynCalc`FeynCalcInternal`Private`tospinor[
     FeynCalc`FeynCalcInternal`Private`p_, 
     FeynCalc`FeynCalcInternal`Private`m_:0, 
     FeynCalc`FeynCalcInternal`Private`c_:1] := 
    Spinor[Momentum[FeynCalc`FeynCalcInternal`Private`p], 
     FeynCalc`FeynCalcInternal`Private`m, FeynCalc`FeynCalcInternal`Private`c]
 
