HoldPattern[SUNF[FeynCalc`SharedObjects`Private`a___, 
      FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`b___, 
      FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`c___, 
      OptionsPattern[]]] := 0 /; Head[FeynCalc`SharedObjects`Private`x] === 
       SUNIndex && FreeQ[FeynCalc`SharedObjects`Private`x, Pattern] && 
      Length[{FeynCalc`SharedObjects`Private`a, 
         FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`b, 
         FeynCalc`SharedObjects`Private`x, 
         FeynCalc`SharedObjects`Private`c}] == 3
 
HoldPattern[SUNF[FeynCalc`SharedObjects`Private`a___, 
      FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y_, 
      FeynCalc`SharedObjects`Private`b___, OptionsPattern[]]] := 
    -SUNF[FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`y, 
       FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`b] /; 
     FCPatternFreeQ[{FeynCalc`SharedObjects`Private`a, 
        FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y, 
        FeynCalc`SharedObjects`Private`b}] && 
      Length[{FeynCalc`SharedObjects`Private`a, 
         FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y, 
         FeynCalc`SharedObjects`Private`b}] === 3 && 
       !OrderedQ[{FeynCalc`SharedObjects`Private`x, 
         FeynCalc`SharedObjects`Private`y}] && 
      Head[FeynCalc`SharedObjects`Private`x] === SUNIndex && 
      Head[FeynCalc`SharedObjects`Private`y] === SUNIndex
 
SUNF[FeynCalc`SharedObjects`Private`i_, FeynCalc`SharedObjects`Private`j_, 
     FeynCalc`SharedObjects`Private`k_, Explicit -> False] := 
    SUNF[FeynCalc`SharedObjects`Private`i, FeynCalc`SharedObjects`Private`j, 
     FeynCalc`SharedObjects`Private`k]
 
HoldPattern[SUNF[FeynCalc`SharedObjects`Private`i_, 
      FeynCalc`SharedObjects`Private`j_, FeynCalc`SharedObjects`Private`k_, 
      (FeynCalc`SharedObjects`Private`op___Rule) | 
       (FeynCalc`SharedObjects`Private`op___List)]] := 
    2*I*(SUNTrace[FCI[SUNT[FeynCalc`SharedObjects`Private`i, 
          FeynCalc`SharedObjects`Private`k, 
          FeynCalc`SharedObjects`Private`j]]] - 
       SUNTrace[FCI[SUNT[FeynCalc`SharedObjects`Private`i, 
          FeynCalc`SharedObjects`Private`j, 
          FeynCalc`SharedObjects`Private`k]]]) /; 
     (Explicit /. Flatten[Join[{FeynCalc`SharedObjects`Private`op}, 
         Options[SUNF]]]) === True
 
HoldPattern[SUNF[FeynCalc`SharedObjects`Private`i_, 
      FeynCalc`SharedObjects`Private`j_, FeynCalc`SharedObjects`Private`k_, 
      FeynCalc`SharedObjects`Private`l_, OptionsPattern[]]] := 
    With[{FeynCalc`SharedObjects`Private`sui = FCGV[ToString[Unique["s"]]]}, 
      SUNF[FeynCalc`SharedObjects`Private`i, 
        FeynCalc`SharedObjects`Private`j, SUNIndex[
         FeynCalc`SharedObjects`Private`sui]]*
       SUNF[SUNIndex[FeynCalc`SharedObjects`Private`sui], 
        FeynCalc`SharedObjects`Private`k, 
        FeynCalc`SharedObjects`Private`l]] /; OptionValue[Explicit]
 
SUNF /: MakeBoxes[SUNF[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b_, 
       FeynCalc`SharedObjectsTypesetting`Private`c:Except[_?OptionQ], 
       OptionsPattern[]], TraditionalForm] := SuperscriptBox["f", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`a, 
       FeynCalc`SharedObjectsTypesetting`Private`b, 
       FeynCalc`SharedObjectsTypesetting`Private`c]]
 
Options[SUNF] = {Explicit -> False}
 
SUNF /: SUNF::usage = "SUNF[a, b, c] are the structure constants of $SU(N)$. \
The arguments a, b, c\nshould be of symbolic type."
 
Explicit[FeynCalc`Explicit`Private`expr_, FeynCalc`Explicit`Private`opts:
      OptionsPattern[]] := Block[{FeynCalc`Explicit`Private`heads, 
      FeynCalc`Explicit`Private`ex, FeynCalc`Explicit`Private`res, 
      FeynCalc`Explicit`Private`rule, FeynCalc`Explicit`Private`list, 
      FeynCalc`Explicit`Private`listEval, 
      FeynCalc`Explicit`Private`repRules}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`Explicit`Private`exVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`Explicit`Private`exVerbose = OptionValue[FCVerbose]]; ]; 
      FCPrint[1, "Explicit: Entering.", FCDoControl -> 
        FeynCalc`Explicit`Private`exVerbose]; 
      FCPrint[3, "Explicit: Entering with ", FeynCalc`Explicit`Private`expr, 
       FCDoControl -> FeynCalc`Explicit`Private`exVerbose]; 
      If[OptionValue[FCI], FeynCalc`Explicit`Private`ex = 
        FeynCalc`Explicit`Private`expr, FeynCalc`Explicit`Private`ex = 
        FCI[FeynCalc`Explicit`Private`expr]]; 
      FeynCalc`Explicit`Private`heads = 
       Head /@ Union[Flatten[Function[FeynCalc`Explicit`Private`x, 
            {First /@ FeynCalc`Explicit`Private`x[{}]}] /@ 
           FeynCalc`Package`RulesForSymbolsWithExplicitOption]]; 
      FCPrint[3, "Explicit: Relevant heads: ", 
       FeynCalc`Explicit`Private`heads, FCDoControl -> 
        FeynCalc`Explicit`Private`exVerbose]; If[ !OptionValue[SUND], 
       FeynCalc`Explicit`Private`heads = SelectFree[
         FeynCalc`Explicit`Private`heads, SUND]]; If[ !OptionValue[SUNF], 
       FeynCalc`Explicit`Private`heads = SelectFree[
         FeynCalc`Explicit`Private`heads, SUNF]]; 
      FeynCalc`Explicit`Private`list = Cases2[FeynCalc`Explicit`Private`ex, 
        FeynCalc`Explicit`Private`heads]; FCPrint[3, 
       "Explicit: Relevant symbols in the expression: ", 
       FeynCalc`Explicit`Private`list, FCDoControl -> 
        FeynCalc`Explicit`Private`exVerbose]; 
      FeynCalc`Explicit`Private`repRules = 
       Flatten[(#1[FeynCalc`Explicit`Private`opts] & ) /@ 
         FeynCalc`Package`RulesForSymbolsWithExplicitOption]; 
      FeynCalc`Explicit`Private`listEval = FeynCalc`Explicit`Private`list /. 
        FeynCalc`Explicit`Private`repRules; FCPrint[3, 
       "Explicit: Explicit form of the relevant symbols: ", 
       FeynCalc`Explicit`Private`listEval, FCDoControl -> 
        FeynCalc`Explicit`Private`exVerbose]; 
      If[OptionValue[ExpandScalarProduct], 
       FeynCalc`Explicit`Private`listEval = ExpandScalarProduct[
         FeynCalc`Explicit`Private`listEval]]; 
      FeynCalc`Explicit`Private`rule = 
       Thread[FeynCalc`Explicit`Private`list -> 
         FeynCalc`Explicit`Private`listEval]; FeynCalc`Explicit`Private`res = 
       FeynCalc`Explicit`Private`ex /. Dispatch[
         FeynCalc`Explicit`Private`rule]; If[OptionValue[FCE], 
       FeynCalc`Explicit`Private`res = FCE[FeynCalc`Explicit`Private`res]]; 
      FCPrint[1, "Explicit: Leaving.", FCDoControl -> 
        FeynCalc`Explicit`Private`exVerbose]; 
      FCPrint[3, "Explicit: Leaving with ", FeynCalc`Explicit`Private`res, 
       FCDoControl -> FeynCalc`Explicit`Private`exVerbose]; 
      FeynCalc`Explicit`Private`res]
 
Options[Explicit] = {CouplingConstant -> SMP["g_s"], Dimension -> D, 
     ExpandScalarProduct -> True, FCE -> False, FCI -> False, 
     FCVerbose -> False, Gauge -> 1, SUND -> False, SUNF -> False}
 
Explicit /: Explicit::usage = "Explicit[exp] inserts explicit expressions of \
GluonVertex, SUNF etc. in exp.\n\nTo rewrite the $SU(N)$ structure constants \
in terms of traces, please set the\ncorresponding options SUNF or SUND to \
True.\n\nExplicit is also an option for FieldStrength, GluonVertex, SUNF  \
etc. If set\nto True the full form of the operator is inserted."
 
FeynCalc`Explicit`Private`exVerbose /: 
    FeynCalc`Explicit`Private`exVerbose::usage = ""
 
FeynCalc`Package`RulesForSymbolsWithExplicitOption = 
    {FeynCalc`Explicit`Private`BuiltInSymbolsWithExplicitOption}
 
FeynCalc`Explicit`Private`BuiltInSymbolsWithExplicitOption[
     FeynCalc`Explicit`Private`optsExplicit___] := 
    {FCTripleProduct[FeynCalc`Explicit`Private`xx__, 
       FeynCalc`Explicit`Private`op:OptionsPattern[]] :> 
      FCTripleProduct[FeynCalc`Explicit`Private`xx, Explicit -> True, 
       Sequence @@ FilterRules[{FeynCalc`Explicit`Private`optsExplicit}, 
         Options[FCTripleProduct]], FeynCalc`Explicit`Private`op], 
     SUNF[FeynCalc`Explicit`Private`xx__, FeynCalc`Explicit`Private`op:
        OptionsPattern[]] :> SUNF[FeynCalc`Explicit`Private`xx, 
       Explicit -> True, Sequence @@ FilterRules[
         {FeynCalc`Explicit`Private`optsExplicit}, Options[SUNF]], 
       FeynCalc`Explicit`Private`op], SUND[FeynCalc`Explicit`Private`xx__, 
       FeynCalc`Explicit`Private`op:OptionsPattern[]] :> 
      SUND[FeynCalc`Explicit`Private`xx, Explicit -> True, 
       Sequence @@ FilterRules[{FeynCalc`Explicit`Private`optsExplicit}, 
         Options[SUND]], FeynCalc`Explicit`Private`op], 
     GluonVertex[FeynCalc`Explicit`Private`xx__, FeynCalc`Explicit`Private`op:
        OptionsPattern[]] :> GluonVertex[FeynCalc`Explicit`Private`xx, 
       Explicit -> True, Sequence @@ FilterRules[
         {FeynCalc`Explicit`Private`optsExplicit}, Options[GluonVertex]], 
       FeynCalc`Explicit`Private`op], 
     GluonPropagator[FeynCalc`Explicit`Private`xx__, 
       FeynCalc`Explicit`Private`op:OptionsPattern[]] :> 
