FCTripleProduct[FeynCalc`FCTripleProduct`Private`a_, 
     FeynCalc`FCTripleProduct`Private`b_, 
     FeynCalc`FCTripleProduct`Private`c_, OptionsPattern[]] := 
    Block[{FeynCalc`FCTripleProduct`Private`dummyI, 
       FeynCalc`FCTripleProduct`Private`dummyJ, 
       FeynCalc`FCTripleProduct`Private`dummyK, 
       FeynCalc`FCTripleProduct`Private`vecA, 
       FeynCalc`FCTripleProduct`Private`vecB, 
       FeynCalc`FCTripleProduct`Private`vecC, 
       FeynCalc`FCTripleProduct`Private`tmp, 
       FeynCalc`FCTripleProduct`Private`optAtomQ, 
       FeynCalc`FCTripleProduct`Private`holdDOT, 
       FeynCalc`FCTripleProduct`Private`res, 
       FeynCalc`FCTripleProduct`Private`optCartesianIndexNames, 
       FeynCalc`FCTripleProduct`Private`dim, 
       FeynCalc`FCTripleProduct`Private`optNonCommutative}, 
      {FeynCalc`FCTripleProduct`Private`dummyI, 
         FeynCalc`FCTripleProduct`Private`dummyJ, 
         FeynCalc`FCTripleProduct`Private`dummyK} = {Unique[$AL], 
         Unique[$AL], Unique[$AL]}; 
       FeynCalc`FCTripleProduct`Private`optCartesianIndexNames = 
        OptionValue[CartesianIndexNames]; 
       FeynCalc`FCTripleProduct`Private`optNonCommutative = 
        OptionValue[NonCommutative]; FeynCalc`FCTripleProduct`Private`dim = 
        OptionValue[Dimension]; 
       If[FeynCalc`FCTripleProduct`Private`optCartesianIndexNames =!= {}, 
        Switch[Length[
          FeynCalc`FCTripleProduct`Private`optCartesianIndexNames], 1, 
         {FeynCalc`FCTripleProduct`Private`dummyI} = 
          FeynCalc`FCTripleProduct`Private`optCartesianIndexNames, 2, 
         {FeynCalc`FCTripleProduct`Private`dummyI, 
           FeynCalc`FCTripleProduct`Private`dummyJ} = 
          FeynCalc`FCTripleProduct`Private`optCartesianIndexNames, _, 
         {FeynCalc`FCTripleProduct`Private`dummyI, 
           FeynCalc`FCTripleProduct`Private`dummyJ, 
           FeynCalc`FCTripleProduct`Private`dummyK} = 
          FeynCalc`FCTripleProduct`Private`optCartesianIndexNames[[
           1 ;; 3]]]]; If[TrueQ[Head[FeynCalc`FCTripleProduct`Private`a] =!= 
          CartesianIndex], FeynCalc`FCTripleProduct`Private`tmp = 
          FeynCalc`FCTripleProduct`Private`getFirstFreeCartesianIndex[
           FeynCalc`FCTripleProduct`Private`a]; 
         If[TrueQ[Length[FeynCalc`FCTripleProduct`Private`tmp] === 1], 
          FeynCalc`FCTripleProduct`Private`dummyI = 
            First[First[First[FeynCalc`FCTripleProduct`Private`tmp]]]; 
           FeynCalc`FCTripleProduct`Private`vecA = 
            FeynCalc`FCTripleProduct`Private`a, 
          FeynCalc`FCTripleProduct`Private`vecA = CartesianPair[
            CartesianMomentum[FeynCalc`FCTripleProduct`Private`a, 
             FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
             FeynCalc`FCTripleProduct`Private`dummyI, 
             FeynCalc`FCTripleProduct`Private`dim]]], 
        FeynCalc`FCTripleProduct`Private`vecA = CartesianPair[
          CartesianIndex[First[FeynCalc`FCTripleProduct`Private`a], 
           FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
           FeynCalc`FCTripleProduct`Private`dummyI, 
           FeynCalc`FCTripleProduct`Private`dim]]]; 
       If[TrueQ[Head[FeynCalc`FCTripleProduct`Private`b] =!= CartesianIndex], 
        FeynCalc`FCTripleProduct`Private`tmp = 
          FeynCalc`FCTripleProduct`Private`getFirstFreeCartesianIndex[
           FeynCalc`FCTripleProduct`Private`b]; 
         If[TrueQ[Length[FeynCalc`FCTripleProduct`Private`tmp] === 1], 
          FeynCalc`FCTripleProduct`Private`dummyJ = 
            First[First[First[FeynCalc`FCTripleProduct`Private`tmp]]]; 
           FeynCalc`FCTripleProduct`Private`vecB = 
            FeynCalc`FCTripleProduct`Private`b, 
          FeynCalc`FCTripleProduct`Private`vecB = CartesianPair[
            CartesianMomentum[FeynCalc`FCTripleProduct`Private`b, 
             FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
             FeynCalc`FCTripleProduct`Private`dummyJ, 
             FeynCalc`FCTripleProduct`Private`dim]]], 
        FeynCalc`FCTripleProduct`Private`vecB = CartesianPair[
          CartesianIndex[First[FeynCalc`FCTripleProduct`Private`b], 
           FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
           FeynCalc`FCTripleProduct`Private`dummyJ, 
           FeynCalc`FCTripleProduct`Private`dim]]]; 
       If[TrueQ[Head[FeynCalc`FCTripleProduct`Private`c] =!= CartesianIndex], 
        FeynCalc`FCTripleProduct`Private`tmp = 
          FeynCalc`FCTripleProduct`Private`getFirstFreeCartesianIndex[
           FeynCalc`FCTripleProduct`Private`c]; 
         If[TrueQ[Length[FeynCalc`FCTripleProduct`Private`tmp] === 1], 
          FeynCalc`FCTripleProduct`Private`dummyK = 
            First[First[First[FeynCalc`FCTripleProduct`Private`tmp]]]; 
           FeynCalc`FCTripleProduct`Private`vecC = 
            FeynCalc`FCTripleProduct`Private`c, 
          FeynCalc`FCTripleProduct`Private`vecC = CartesianPair[
            CartesianMomentum[FeynCalc`FCTripleProduct`Private`c, 
             FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
             FeynCalc`FCTripleProduct`Private`dummyK, 
             FeynCalc`FCTripleProduct`Private`dim]]], 
        FeynCalc`FCTripleProduct`Private`vecC = CartesianPair[
          CartesianIndex[First[FeynCalc`FCTripleProduct`Private`c], 
           FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
           FeynCalc`FCTripleProduct`Private`dummyK, 
           FeynCalc`FCTripleProduct`Private`dim]]]; 
       FeynCalc`FCTripleProduct`Private`res = 
        Eps[CartesianIndex[FeynCalc`FCTripleProduct`Private`dummyI, 
           FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
           FeynCalc`FCTripleProduct`Private`dummyJ, 
           FeynCalc`FCTripleProduct`Private`dim], CartesianIndex[
           FeynCalc`FCTripleProduct`Private`dummyK, 
           FeynCalc`FCTripleProduct`Private`dim]]*
         FeynCalc`FCTripleProduct`Private`holdDOT[
          FeynCalc`FCTripleProduct`Private`vecA, 
          FeynCalc`FCTripleProduct`Private`vecB, 
          FeynCalc`FCTripleProduct`Private`vecC]; 
       Switch[FeynCalc`FCTripleProduct`Private`optNonCommutative, Automatic, 
        If[NonCommFreeQ[FeynCalc`FCTripleProduct`Private`res], 
         FeynCalc`FCTripleProduct`Private`res = 
          FeynCalc`FCTripleProduct`Private`res /. 
           FeynCalc`FCTripleProduct`Private`holdDOT -> Times, 
         FeynCalc`FCTripleProduct`Private`res = 
          FeynCalc`FCTripleProduct`Private`res /. 
           FeynCalc`FCTripleProduct`Private`holdDOT -> DOT], True, 
        FeynCalc`FCTripleProduct`Private`res = 
         FeynCalc`FCTripleProduct`Private`res /. 
          FeynCalc`FCTripleProduct`Private`holdDOT -> DOT, False, 
        FeynCalc`FCTripleProduct`Private`res = 
         FeynCalc`FCTripleProduct`Private`res /. 
          FeynCalc`FCTripleProduct`Private`holdDOT -> Times, _, 
        Message[FCTripleProduct::failmsg, 
          "Unrecognized value for the NonCommutative option."]; Abort[]]; 
       FeynCalc`FCTripleProduct`Private`res = 
        FeynCalc`FCTripleProduct`Private`res /. CartesianPair -> 
           CartesianPairContract /. CartesianPairContract -> CartesianPair; 
       If[OptionValue[FCE], FeynCalc`FCTripleProduct`Private`res = 
         FCE[FeynCalc`FCTripleProduct`Private`res]]; 
       FeynCalc`FCTripleProduct`Private`res] /; OptionValue[Explicit]
 
FCTripleProduct /: 
    MakeBoxes[FCTripleProduct[FeynCalc`FCTripleProduct`Private`a_, 
        FeynCalc`FCTripleProduct`Private`b_, 
        FeynCalc`FCTripleProduct`Private`c_, OptionsPattern[]], 
       TraditionalForm] /; Head[FeynCalc`FCTripleProduct`Private`a] =!= 
        CartesianIndex && Head[FeynCalc`FCTripleProduct`Private`b] =!= 
        CartesianIndex && Head[FeynCalc`FCTripleProduct`Private`c] =!= 
        CartesianIndex := 
     RowBox[{TBox[CartesianMomentum[FeynCalc`FCTripleProduct`Private`a]], 
       "\[CenterDot]", "(", TBox[CartesianMomentum[
         FeynCalc`FCTripleProduct`Private`b]], "\[Cross]", 
       TBox[CartesianMomentum[FeynCalc`FCTripleProduct`Private`c]], ")"}]
 
FCTripleProduct /: 
    MakeBoxes[FCTripleProduct[
        FeynCalc`FCTripleProduct`Private`a_CartesianIndex, 
        FeynCalc`FCTripleProduct`Private`b_, 
        FeynCalc`FCTripleProduct`Private`c_, OptionsPattern[]], 
       TraditionalForm] /; Head[FeynCalc`FCTripleProduct`Private`b] =!= 
        CartesianIndex && Head[FeynCalc`FCTripleProduct`Private`c] =!= 
        CartesianIndex := SuperscriptBox[
      RowBox[{"(", TBox[CartesianMomentum[
          FeynCalc`FCTripleProduct`Private`b]], "\[Cross]", 
        TBox[CartesianMomentum[FeynCalc`FCTripleProduct`Private`c]], ")"}], 
      TBox[FeynCalc`FCTripleProduct`Private`a]]
 
FCTripleProduct /: 
    MakeBoxes[FCTripleProduct[FeynCalc`FCTripleProduct`Private`a_, 
        FeynCalc`FCTripleProduct`Private`b_CartesianIndex, 
        FeynCalc`FCTripleProduct`Private`c_, OptionsPattern[]], 
