      RowBox[{"-(", TBox[CartesianMomentum[
          FeynCalc`FCTripleProduct`Private`a]], "\[Cross]", 
        TBox[CartesianMomentum[FeynCalc`FCTripleProduct`Private`c]], ")"}], 
      TBox[FeynCalc`FCTripleProduct`Private`b]]
 
FCTripleProduct /: 
