        FeynCalc`FCTripleProduct`Private`c_CartesianIndex, OptionsPattern[]], 
       TraditionalForm] /; Head[FeynCalc`FCTripleProduct`Private`a] =!= 
       CartesianIndex := ToBoxes[Eps[FeynCalc`FCTripleProduct`Private`a, 
       FeynCalc`FCTripleProduct`Private`b, 
       FeynCalc`FCTripleProduct`Private`c], TraditionalForm]
 
FCTripleProduct /: MakeBoxes[FCTripleProduct[
       FeynCalc`FCTripleProduct`Private`a_CartesianIndex, 
       FeynCalc`FCTripleProduct`Private`b_CartesianIndex, 
       FeynCalc`FCTripleProduct`Private`c_CartesianIndex, OptionsPattern[]], 
      TraditionalForm] := ToBoxes[Eps[FeynCalc`FCTripleProduct`Private`a, 
       FeynCalc`FCTripleProduct`Private`b, 
       FeynCalc`FCTripleProduct`Private`c], TraditionalForm]
 
Options[FCTripleProduct] = {FeynCalcExternal -> False, 
     CartesianIndexNames -> {}, Dimension -> 3, Explicit -> False, 
     NonCommutative -> Automatic}
 
FCTripleProduct /: FCTripleProduct::failmsg = "Error! ExpandPartialD has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCTripleProduct /: FCTripleProduct::usage = "FCTripleProduct[a,b,c] returns \
the triple product $a \\cdot (b \\times c)$. By\ndefault a,b and c are \
assumed to be Cartesian vectors. Wrapping the arguments\nwith CartesianIndex \
will create an expression with open indices.\n\nIf any of the arguments is \
noncommutative, DOT will be used instead of Times\nand the function will \
introduce dummy indices. To give those indices some\nspecific names, use the \
option CartesianIndexNames.\n\nIf the arguments already contain free \
CartesianIndices, the first such index\nwill be used for the \
contraction.\n\nTo obtain an explicit expression you need to set the option \
Explicit to True\nor apply the function Explicit"
 
$AL /: $AL::usage = "$AL is the head for dummy indices which may be \
introduced by different\nfunctions. By default it is unset, but may be set to \
anything."
 
CartesianIndexNames /: CartesianIndexNames::usage = "CartesianIndexNames is \
an option for FCFAConvert, FCCanonicalizeDummyIndices\nand other functions. \
It renames the generic dummy Cartesian indices to the\nindices in the \
supplied list."
 
Dimension /: Dimension::usage = "Dimension is an option of several functions \
and denotes the number of\nspace-time dimensions. Possible settings are: 4, \
n, d, D, ... , the variable\ndoes not matter, but it should have head \
Symbol."
 
FeynCalc`FCTripleProduct`Private`getFirstFreeCartesianIndex[
     FeynCalc`FCTripleProduct`Private`x_] := 
    Select[Tally[Cases[FeynCalc`FCTripleProduct`Private`x, 
       CartesianIndex[__], Infinity]], Last[#1] === 1 & ]
 
Attributes[CartesianPair] = {Orderless}
 
CartesianPair[0, _] := 0
 
CartesianPair[(CartesianIndex | CartesianMomentum)[_], 
     (CartesianIndex | CartesianMomentum)[_, -4 + _Symbol]] := 0
 
CartesianPair[_, (FeynCalc`SharedObjects`Private`h:LorentzIndex | 
        ExplicitLorentzIndex | Momentum | TemporalMomentum)[___]] := 
    (Message[SharedObjects::failmsg, StringJoin[
       ToString[FeynCalc`SharedObjects`Private`h, InputForm], 
       " is not allowed inside CartesianPair"]]; Abort[])
 
CartesianPair[(FeynCalc`SharedObjects`Private`n_)*
      (FeynCalc`SharedObjects`Private`x_CartesianMomentum), 
     FeynCalc`SharedObjects`Private`y_] := FeynCalc`SharedObjects`Private`n*
     CartesianPair[FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`y]
 
CartesianPair[(FeynCalc`SharedObjects`Private`n_Integer)*
      (FeynCalc`SharedObjects`Private`x_), 
     FeynCalc`SharedObjects`Private`y_] := 
    FeynCalc`SharedObjects`Private`n*CartesianPair[
       FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y] /; 
      !MemberQ[{CartesianIndex, ExplicitLorentzIndex}, 
       FeynCalc`SharedObjects`Private`x]
 
CartesianPair[(FeynCalc`SharedObjects`Private`n_Complex)*
      (FeynCalc`SharedObjects`Private`x_), 
     FeynCalc`SharedObjects`Private`y_] := 
    FeynCalc`SharedObjects`Private`n*CartesianPair[
       FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y] /; 
      !MemberQ[{CartesianIndex, ExplicitLorentzIndex}, 
       FeynCalc`SharedObjects`Private`x]
 
CartesianPair[(FeynCalc`SharedObjects`Private`a:CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`x_, -1 + _Symbol], 
     (FeynCalc`SharedObjects`Private`b:CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`y_]] := 
    CartesianPair[FeynCalc`SharedObjects`Private`a[
      FeynCalc`SharedObjects`Private`x], FeynCalc`SharedObjects`Private`b[
      FeynCalc`SharedObjects`Private`y]]
 
CartesianPair[(FeynCalc`SharedObjects`Private`a:CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`x_, 
      -1 + (FeynCalc`SharedObjects`Private`dim_Symbol)], 
     (FeynCalc`SharedObjects`Private`b:CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`y_, 
      -4 + (FeynCalc`SharedObjects`Private`dim_Symbol)]] := 
    CartesianPair[FeynCalc`SharedObjects`Private`a[
      FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`dim - 
       4], FeynCalc`SharedObjects`Private`b[FeynCalc`SharedObjects`Private`y, 
      FeynCalc`SharedObjects`Private`dim - 4]]
 
CartesianPair /: MakeBoxes[CartesianPair[LightConePerpendicularComponent[
        FeynCalc`SharedObjectsTypesetting`Private`a_, __], 
       LightConePerpendicularComponent[
        FeynCalc`SharedObjectsTypesetting`Private`b_, __]], 
      TraditionalForm] := SubscriptBox[ToBoxes[CartesianPair[
        FeynCalc`SharedObjectsTypesetting`Private`a, 
        FeynCalc`SharedObjectsTypesetting`Private`b], TraditionalForm], 
      "\[Perpendicular]"]
 
CartesianPair /: MakeBoxes[CartesianPair[CartesianIndex[
        FeynCalc`SharedObjectsTypesetting`Private`a_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1_:3], 
       CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`b_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim2_:3]], 
      TraditionalForm] := SuperscriptBox[
      RowBox[{FeynCalc`SharedObjectsTypesetting`Private`kroneckerRep[
         {FeynCalc`SharedObjectsTypesetting`Private`dim1, 
          FeynCalc`SharedObjectsTypesetting`Private`dim2}]}], 
      TBox[CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`a, 
        FeynCalc`SharedObjectsTypesetting`Private`dim1], 
       CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`b, 
        FeynCalc`SharedObjectsTypesetting`Private`dim2]]]
 
CartesianPair /: MakeBoxes[CartesianPair[
       (FeynCalc`SharedObjectsTypesetting`Private`c1_.)*
         CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`a_, 
          FeynCalc`SharedObjectsTypesetting`Private`dim1_:3] + 
        (FeynCalc`SharedObjectsTypesetting`Private`a1_:0), 
       (FeynCalc`SharedObjectsTypesetting`Private`c2_.)*
         CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`b_, 
          FeynCalc`SharedObjectsTypesetting`Private`dim2_:3] + 
        (FeynCalc`SharedObjectsTypesetting`Private`b1_:0)], 
      TraditionalForm] := 
     Block[{FeynCalc`SharedObjectsTypesetting`Private`m1 = 
        Expand[FeynCalc`SharedObjectsTypesetting`Private`c1*
            FeynCalc`SharedObjectsTypesetting`Private`a + 
           FeynCalc`SharedObjectsTypesetting`Private`a1 /. 
          CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`z_, 
            ___] :> FeynCalc`SharedObjectsTypesetting`Private`z], 
       FeynCalc`SharedObjectsTypesetting`Private`m2 = 
        Expand[FeynCalc`SharedObjectsTypesetting`Private`c2*
            FeynCalc`SharedObjectsTypesetting`Private`b + 
           FeynCalc`SharedObjectsTypesetting`Private`b1 /. 
          CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`z_, 
            ___] :> FeynCalc`SharedObjectsTypesetting`Private`z]}, 
      Which[FeynCalc`SharedObjectsTypesetting`Private`m1 === 
        FeynCalc`SharedObjectsTypesetting`Private`m2, 
       If[Head[FeynCalc`SharedObjectsTypesetting`Private`m1] === Plus, 
        RowBox[{SuperscriptBox[TBox["(", CartesianMomentum[
             FeynCalc`SharedObjectsTypesetting`Private`m1, 
             FeynCalc`SharedObjectsTypesetting`Private`dim1], ")"], 2]}], 
        SuperscriptBox[TBox[CartesianMomentum[
           FeynCalc`SharedObjectsTypesetting`Private`m1, 
           FeynCalc`SharedObjectsTypesetting`Private`dim1]], 2]], 
       Head[FeynCalc`SharedObjectsTypesetting`Private`m1] =!= Plus && 
        Head[FeynCalc`SharedObjectsTypesetting`Private`m2] =!= Plus, 
       TBox[CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`m1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1], "\[CenterDot]", 
        CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`m2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2]], 
       Head[FeynCalc`SharedObjectsTypesetting`Private`m1] =!= Plus && 
        Head[FeynCalc`SharedObjectsTypesetting`Private`m2] === Plus, 
       TBox[CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`m1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1], "\[CenterDot]", 
        "(", CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`m2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2], ")"], 
       Head[FeynCalc`SharedObjectsTypesetting`Private`m1] === Plus && 
        Head[FeynCalc`SharedObjectsTypesetting`Private`m2] =!= Plus, 
       TBox["(", CartesianMomentum[
         FeynCalc`SharedObjectsTypesetting`Private`m1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1], ")", 
        "\[CenterDot]", CartesianMomentum[
         FeynCalc`SharedObjectsTypesetting`Private`m2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2]], 
       Head[FeynCalc`SharedObjectsTypesetting`Private`m1] === Plus && 
        Head[FeynCalc`SharedObjectsTypesetting`Private`m2] === Plus, 
       TBox["(", CartesianMomentum[
         FeynCalc`SharedObjectsTypesetting`Private`m1, 
         FeynCalc`SharedObjectsTypesetting`Private`dim1], ")", 
        "\[CenterDot]", "(", CartesianMomentum[
         FeynCalc`SharedObjectsTypesetting`Private`m2, 
         FeynCalc`SharedObjectsTypesetting`Private`dim2], ")"]]]
 
CartesianPair /: MakeBoxes[CartesianPair[CartesianIndex[
        FeynCalc`SharedObjectsTypesetting`Private`a_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim_:3], 
       CartesianMomentum[Polarization[
         FeynCalc`SharedObjectsTypesetting`Private`b_, 
         FeynCalc`SharedObjectsTypesetting`Private`c:Except[_?OptionQ], 
         OptionsPattern[]], FeynCalc`SharedObjectsTypesetting`Private`dim_:
         3]], TraditionalForm] := 
     RowBox[{SuperscriptBox[
        FeynCalc`SharedObjectsTypesetting`Private`cpolarizationRep[
         FeynCalc`SharedObjectsTypesetting`Private`c, 
         FeynCalc`SharedObjectsTypesetting`Private`dim], 
        TBox[CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`a]]], 
       "(", TBox[FeynCalc`SharedObjectsTypesetting`Private`b], ")"}]
 
CartesianPair /: MakeBoxes[CartesianPair[CartesianIndex[
        FeynCalc`SharedObjectsTypesetting`Private`a_, 
        FeynCalc`SharedObjectsTypesetting`Private`dim_:3], 
       (FeynCalc`SharedObjectsTypesetting`Private`c0:
         (_.)*CartesianMomentum[_, 
           FeynCalc`SharedObjectsTypesetting`Private`dim_:3]) + 
        (FeynCalc`SharedObjectsTypesetting`Private`c1_:0)], 
      TraditionalForm] := 
     If[ !FreeQ2[{FeynCalc`SharedObjectsTypesetting`Private`c0 + 
           FeynCalc`SharedObjectsTypesetting`Private`c1 /. 
          FeynCalc`SharedObjectsTypesetting`Private`dim -> Identity}, 
        {Plus, Times}], SuperscriptBox[
       RowBox[{"(", TBox[FeynCalc`SharedObjectsTypesetting`Private`c0 + 
           FeynCalc`SharedObjectsTypesetting`Private`c1], ")"}], 
       TBox[CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`a, 
         FeynCalc`SharedObjectsTypesetting`Private`dim]]], 
      SuperscriptBox[RowBox[
        {TBox[FeynCalc`SharedObjectsTypesetting`Private`c0 + 
           FeynCalc`SharedObjectsTypesetting`Private`c1]}], 
       TBox[CartesianIndex[FeynCalc`SharedObjectsTypesetting`Private`a, 
         FeynCalc`SharedObjectsTypesetting`Private`dim]]]]
 
CartesianPair /: CartesianPair::invalid = 
     "`1` does not represent a valid CartesianPair object!"
 
CartesianPair /: CartesianPair::usage = "CartesianPair[a, b] is a special \
pairing used in the internal representation.\na and b may have heads \
CartesianIndex or CartesianMomentum. If both a and b\nhave head \
CartesianIndex, the Kronecker delta is understood. If a and b have\nhead \
CartesianMomentum, a Cartesian scalar product is meant. If one of a and \
b\nhas head CartesianIndex and the other CartesianMomentum, a Cartesian \
vector\n$p^i$ is understood."
 
FeynCalc`SharedObjectsTypesetting`Private`kroneckerRep[
     FeynCalc`SharedObjectsTypesetting`Private`dim_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`dim === {3, 3}, 
     OverscriptBox["\[Delta]", $TypesettingDim4], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, 
       {_Symbol - 1, _Symbol - 1}] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim[[1]] === 
       FeynCalc`SharedObjectsTypesetting`Private`dim[[2]], 
     If[$TypesettingDimD === "", "\[Delta]", OverscriptBox["\[Delta]", 
       $TypesettingDimD]], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, 
       {_Symbol - 4, _Symbol - 4}] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim[[1]] === 
       FeynCalc`SharedObjectsTypesetting`Private`dim[[2]], 
     OverscriptBox["\[Delta]", $TypesettingDimE], True, 
     SubscriptBox["\[Delta]", ToBoxes[
       FeynCalc`SharedObjectsTypesetting`Private`dim, TraditionalForm]]]
 
Eps[___, 0, ___] := 0
 
Eps[FeynCalc`SharedObjects`Private`x__] := 
    0 /; Signature[{FeynCalc`SharedObjects`Private`x}] === 0 && 
      FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x}]
 
Eps[FeynCalc`SharedObjects`Private`x___, FeynCalc`SharedObjects`Private`a:
      (CartesianMomentum | Momentum | LorentzIndex | CartesianIndex)[_, 
       -4 + _Symbol], FeynCalc`SharedObjects`Private`y___] := 
    0 /; FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`y}]
 
Eps[FeynCalc`SharedObjects`Private`x___, ExplicitLorentzIndex[0] | 
      _TemporalMomentum, FeynCalc`SharedObjects`Private`y___] := 
    0 /; Length[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}] === 2
 
Eps[_CartesianMomentum | _CartesianIndex, _CartesianMomentum | 
      _CartesianIndex, _CartesianMomentum | _CartesianIndex, 
     _CartesianMomentum | _CartesianIndex] := 0
 
Eps[FeynCalc`SharedObjects`Private`x__] /; 
      !MemberQ[{3, 4}, Length[{FeynCalc`SharedObjects`Private`x}]] && 
      FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x}] := 
    (Message[Eps::argrx, StringJoin["Eps[", 
       ToString[{FeynCalc`SharedObjects`Private`x}], "]"], 
      Length[{FeynCalc`SharedObjects`Private`x}], "3 or 4"]; Abort[])
 
Eps[FeynCalc`SharedObjects`Private`x___, (FeynCalc`SharedObjects`Private`a:
       _Momentum | _CartesianMomentum)*(FeynCalc`SharedObjects`Private`n_), 
     FeynCalc`SharedObjects`Private`y___] := FeynCalc`SharedObjects`Private`n*
     Eps[FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`a, 
      FeynCalc`SharedObjects`Private`y]
 
Eps[FeynCalc`SharedObjects`Private`x___, (FeynCalc`SharedObjects`Private`h1:
       LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`a_], 
     FeynCalc`SharedObjects`Private`y___, 
     (FeynCalc`SharedObjects`Private`h2:LorentzIndex | ExplicitLorentzIndex | 
        Momentum | CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`b_, _Symbol], 
     FeynCalc`SharedObjects`Private`z___] := 
    Eps @@ (Take[#1, 1] & ) /@ {FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z} /; 
     FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z}] && 
      FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a] =!= 
       ExplicitLorentzIndex[0]
 
Eps[FeynCalc`SharedObjects`Private`x___, (FeynCalc`SharedObjects`Private`h1:
       LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`a_], 
     FeynCalc`SharedObjects`Private`y___, 
     (FeynCalc`SharedObjects`Private`h2:CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`b_, -1 + _Symbol], 
     FeynCalc`SharedObjects`Private`z___] := 
    Eps @@ (Take[#1, 1] & ) /@ {FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z} /; 
     FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z}] && 
      FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a] =!= 
       ExplicitLorentzIndex[0]
 
Eps[FeynCalc`SharedObjects`Private`x___, (FeynCalc`SharedObjects`Private`h1:
       LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`a_, _Symbol], 
     FeynCalc`SharedObjects`Private`y___, 
     (FeynCalc`SharedObjects`Private`h2:LorentzIndex | ExplicitLorentzIndex | 
        Momentum | CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`b_], 
     FeynCalc`SharedObjects`Private`z___] := 
    Eps @@ (Take[#1, 1] & ) /@ {FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z} /; 
     FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z}] && 
      FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a] =!= 
       ExplicitLorentzIndex[0]
 
Eps[FeynCalc`SharedObjects`Private`x___, (FeynCalc`SharedObjects`Private`h1:
       LorentzIndex | ExplicitLorentzIndex | Momentum | CartesianIndex | 
        CartesianMomentum)[FeynCalc`SharedObjects`Private`a_, -1 + _Symbol], 
     FeynCalc`SharedObjects`Private`y___, 
     (FeynCalc`SharedObjects`Private`h2:CartesianIndex | CartesianMomentum)[
      FeynCalc`SharedObjects`Private`b_], 
     FeynCalc`SharedObjects`Private`z___] := 
    Eps @@ (Take[#1, 1] & ) /@ {FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z} /; 
     FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a], 
        FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`h2[
         FeynCalc`SharedObjects`Private`b], 
        FeynCalc`SharedObjects`Private`z}] && 
      FeynCalc`SharedObjects`Private`h1[FeynCalc`SharedObjects`Private`a] =!= 
       ExplicitLorentzIndex[0]
 
Eps[FeynCalc`SharedObjects`Private`x___, 
     FeynCalc`SharedObjects`Private`m_TemporalMomentum, 
     FeynCalc`SharedObjects`Private`y___] := 
    TemporalPair[ExplicitLorentzIndex[0], FeynCalc`SharedObjects`Private`m]*
     Eps[FeynCalc`SharedObjects`Private`x, ExplicitLorentzIndex[0], 
      FeynCalc`SharedObjects`Private`y]
 
Eps[FeynCalc`SharedObjects`Private`x___, 
     Momentum[FeynCalc`SharedObjects`Private`p_], 
     FeynCalc`SharedObjects`Private`y___] := 
    FeynCalc`Package`MetricS*Eps[FeynCalc`SharedObjects`Private`x, 
       CartesianMomentum[FeynCalc`SharedObjects`Private`p], 
       FeynCalc`SharedObjects`Private`y] /; 
     Length[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}] === 2
 
Eps[FeynCalc`SharedObjects`Private`x___, 
     Momentum[FeynCalc`SharedObjects`Private`p_, 
      FeynCalc`SharedObjects`Private`dim_Symbol], 
     FeynCalc`SharedObjects`Private`y___] := 
    FeynCalc`Package`MetricS*Eps[FeynCalc`SharedObjects`Private`x, 
       CartesianMomentum[FeynCalc`SharedObjects`Private`p, 
        FeynCalc`SharedObjects`Private`dim - 1], 
       FeynCalc`SharedObjects`Private`y] /; 
     Length[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}] === 2
 
Eps[FeynCalc`SharedObjects`Private`x1:_Momentum | _CartesianMomentum | 
       _CartesianIndex, FeynCalc`SharedObjects`Private`x2:
      _Momentum | _CartesianMomentum | _CartesianIndex, 
     FeynCalc`SharedObjects`Private`x3:_Momentum | _CartesianMomentum | 
       _CartesianIndex, ExplicitLorentzIndex[0]] := 
    $LeviCivitaSign*Eps[FeynCalc`SharedObjects`Private`x1, 
      FeynCalc`SharedObjects`Private`x2, FeynCalc`SharedObjects`Private`x3]
 
Eps[ExplicitLorentzIndex[0], FeynCalc`SharedObjects`Private`x1:
      _Momentum | _CartesianMomentum | _CartesianIndex, 
     FeynCalc`SharedObjects`Private`x2:_Momentum | _CartesianMomentum | 
       _CartesianIndex, FeynCalc`SharedObjects`Private`x3:
      _Momentum | _CartesianMomentum | _CartesianIndex] := 
    (-$LeviCivitaSign)*Eps[FeynCalc`SharedObjects`Private`x1, 
      FeynCalc`SharedObjects`Private`x2, FeynCalc`SharedObjects`Private`x3]
 
Eps /: MakeBoxes[Eps[FeynCalc`SharedObjectsTypesetting`Private`a__], 
      TraditionalForm] := SuperscriptBox[OverscriptBox["\[Epsilon]", 
        $TypesettingDimD], 
       TBox[FeynCalc`SharedObjectsTypesetting`Private`a]] /; 
      Length[First[{FeynCalc`SharedObjectsTypesetting`Private`a}]] === 2 && 
       FreeQ[{FeynCalc`SharedObjectsTypesetting`Private`a}, 
        LightConePerpendicularComponent]
 
Eps /: MakeBoxes[Eps[FeynCalc`SharedObjectsTypesetting`Private`a___, 
       FeynCalc`SharedObjectsTypesetting`Private`b_LightConePerpendicularComp\
onent, FeynCalc`SharedObjectsTypesetting`Private`c___], TraditionalForm] := 
     SuperscriptBox[OverscriptBox["\[Epsilon]", $TypesettingDimD], 
       TBox[FeynCalc`SharedObjectsTypesetting`Private`a, 
        FeynCalc`SharedObjectsTypesetting`Private`b, 
        FeynCalc`SharedObjectsTypesetting`Private`c]] /; 
      Length[First[FeynCalc`SharedObjectsTypesetting`Private`b]] === 2
 
Eps /: MakeBoxes[Eps[FeynCalc`SharedObjectsTypesetting`Private`a__], 
      TraditionalForm] := SuperscriptBox[OverscriptBox["\[Epsilon]", 
        $TypesettingDim4], 
       TBox[FeynCalc`SharedObjectsTypesetting`Private`a]] /; 
      MatchQ[Length[First[{FeynCalc`SharedObjectsTypesetting`Private`a}]], 
        1 | 0] && FreeQ[{FeynCalc`SharedObjectsTypesetting`Private`a}, 
        LightConePerpendicularComponent]
 
Eps /: MakeBoxes[Eps[FeynCalc`SharedObjectsTypesetting`Private`a___, 
       FeynCalc`SharedObjectsTypesetting`Private`b_LightConePerpendicularComp\
onent, FeynCalc`SharedObjectsTypesetting`Private`c___], TraditionalForm] := 
     SuperscriptBox[OverscriptBox["\[Epsilon]", $TypesettingDim4], 
       TBox[FeynCalc`SharedObjectsTypesetting`Private`a, 
        FeynCalc`SharedObjectsTypesetting`Private`b, 
        FeynCalc`SharedObjectsTypesetting`Private`c]] /; 
      MatchQ[Length[First[FeynCalc`SharedObjectsTypesetting`Private`b]], 
       1 | 0]
 
Eps /: Eps::usage = "Eps[a, b, c, d] is the head of the totally antisymmetric \
$\\epsilon$\n(Levi-Civita) tensor. The a,b, ... may have head LorentzIndex or \
Momentum.\n\nWhen some indices of a Levi-Civita-tensor are contracted with \
4-vectors,\nFeynCalc suppresses explicit dummy indices by putting those \
vectors into the\ncorresponding index slots. For example,  $\\varepsilon^{p_1 \
p_2 p_3 p_4}$\n(accessible via LC[][p1,p2,p3,p4]) correspond to \
$\\varepsilon_{\\mu \\nu \\rho\n\\sigma} p_1^\\mu p_2^\\nu p_3^\\rho \
p_4^\\sigma$."
 
FeynCalc`Package`MetricS = -1
 
$LeviCivitaSign := -1
 
($LeviCivitaSign = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$LeviCivitaSign] = 
           {HoldPattern[$LeviCivitaSign] :> FeynCalc`Private`xxx}; , 
         DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$LeviCivitaSign] = {HoldPattern[$LeviCivitaSign] :> 
         FeynCalc`Private`xxx}]; FeynCalc`Private`val)
 
$LeviCivitaSign /: $LeviCivitaSign::usage = "$LeviCivitaSign is a global \
variable that determines the sign in the result of\na Dirac trace of four \
gamma matrices and $\\gamma^5$.  $LeviCivitaSign is by\ndefault set to -1 \
which corresponds to the convention TR[GA[a,b,c,d,5]] =\n-4*I*Eps[a,b,c,d]. \
Setting $LeviCivitaSign=-I will switch to the\nFORM-convention."
 
Attributes[CartesianPairContract] = {Orderless}
 
CartesianPairContract /: CartesianPairContract[_CartesianIndex, 
       FeynCalc`PairContract`Private`x_]^2 := CartesianPairContract[
      FeynCalc`PairContract`Private`x, FeynCalc`PairContract`Private`x]
 
CartesianPairContract[FeynCalc`PairContract`Private`a_, 
      FeynCalc`PairContract`Private`b_CartesianIndex]^
     (FeynCalc`PairContract`Private`n_ /; FeynCalc`PairContract`Private`n > 
       2) ^:= (Message[CartesianPairContract::failmsg, 
       StringJoin["The expression ", ToString[
         CartesianPair[FeynCalc`PairContract`Private`a, 
           FeynCalc`PairContract`Private`b]^FeynCalc`PairContract`Private`n, 
         InputForm], " violates Einstein summation."]]; Abort[]) /; 
     FeynCalc`PairContract`Private`a =!= FeynCalc`PairContract`Private`b
 
CartesianPairContract[CartesianIndex[FeynCalc`PairContract`Private`z_, 
       FeynCalc`PairContract`Private`dim___], 
      (FeynCalc`PairContract`Private`h:CartesianIndex | CartesianMomentum)[
       FeynCalc`PairContract`Private`x_, 
       FeynCalc`PairContract`Private`dim___]]*
     (FeynCalc`PairContract`Private`f_)[
      FeynCalc`PairContract`Private`a__] ^:= 
    (FeynCalc`PairContract`Private`f[FeynCalc`PairContract`Private`a] /. 
      CartesianIndex[FeynCalc`PairContract`Private`z, ___] -> 
       FeynCalc`PairContract`Private`h[FeynCalc`PairContract`Private`x, 
        FeynCalc`PairContract`Private`dim]) /; 
      !FreeQ[FeynCalc`PairContract`Private`f[
        FeynCalc`PairContract`Private`a], CartesianIndex[
        FeynCalc`PairContract`Private`z, ___]]
 
CartesianPairContract[0, _] := 0
 
CartesianPairContract[CartesianIndex[FeynCalc`PairContract`Private`x_, 
      FeynCalc`PairContract`Private`dim1_:3], CartesianIndex[
      FeynCalc`PairContract`Private`x_, FeynCalc`PairContract`Private`dim2_:
       3]] := FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`dim1, 
      FeynCalc`PairContract`Private`dim2] /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
CartesianPairContract[(FeynCalc`PairContract`Private`h1:
        CartesianIndex | CartesianMomentum)[FeynCalc`PairContract`Private`x_, 
       FeynCalc`PairContract`Private`dim1_:3], 
      (FeynCalc`PairContract`Private`h2:CartesianIndex | CartesianMomentum)[
       FeynCalc`PairContract`Private`y_, FeynCalc`PairContract`Private`dim2_:
        3]] /; {FeynCalc`PairContract`Private`dim1} =!= 
      {FeynCalc`PairContract`Private`dim2} := 
    CartesianPairContract[FeynCalc`PairContract`Private`h1[
       FeynCalc`PairContract`Private`x, FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]], 
      FeynCalc`PairContract`Private`h2[FeynCalc`PairContract`Private`y, 
       FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]]] /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
CartesianPairContract[FeynCalc`PairContract`Private`a_, 
     FeynCalc`PairContract`Private`b_] := 
    Block[{FeynCalc`PairContract`Private`pairExpanded = 
        FCUseCache[ExpandScalarProduct, {CartesianPair[
           FeynCalc`PairContract`Private`a, 
           FeynCalc`PairContract`Private`b]}, {FCI -> True}]}, 
      If[FreeQ2[FeynCalc`PairContract`Private`pairExpanded, 
         {Pair, CartesianPair}] || 
        Head[FeynCalc`PairContract`Private`pairExpanded] =!= Plus, 
       FeynCalc`PairContract`Private`pairExpanded, 
       CartesianPair[FeynCalc`PairContract`Private`a, 
        FeynCalc`PairContract`Private`b]]] /; 
     FreeQ2[{FeynCalc`PairContract`Private`a, 
       FeynCalc`PairContract`Private`b}, {LorentzIndex, CartesianIndex}]
 
CartesianPairContract /: CartesianPairContract::failmsg = "Error! \
CartesianPairContract has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
CartesianPairContract /: CartesianPairContract::usage = "CartesianPairContrac\
t is like CartesianPair, but with (local) contraction\nproperties.  The \
function fully supports the BMHV algebra and will not expand\nmomenta inside \
scalar products.\n\nCartesianPairContract is an auxiliary function used in \
higher level FeynCalc\nfunctions that require fast contractions between \
multiple expressions, where\nContract would be too slow."
 
Attributes[FeynCalc`PairContract`Private`dimEval] = {Orderless}
 
FeynCalc`PairContract`Private`dimEval[D, D] = D
 
FeynCalc`PairContract`Private`dimEval[FeynCalc`PairContract`Private`d_, 
     FeynCalc`PairContract`Private`d_] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d, FeynCalc`PairContract`Private`d], 
     FeynCalc`PairContract`Private`d]
 
FeynCalc`PairContract`Private`dimEval[4, 
     FeynCalc`PairContract`Private`d_Symbol] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d, 4], 4]
 
FeynCalc`PairContract`Private`dimEval[4, 
     -4 + (FeynCalc`PairContract`Private`d_Symbol)] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d - 4, 4], 0]
 
FeynCalc`PairContract`Private`dimEval[
     -4 + (FeynCalc`PairContract`Private`d_Symbol), 
     FeynCalc`PairContract`Private`d_Symbol] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d - 4, FeynCalc`PairContract`Private`d], 
     FeynCalc`PairContract`Private`d - 4]
 
FeynCalc`PairContract`Private`dimEval[3, 
     -1 + (FeynCalc`PairContract`Private`d_Symbol)] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d - 1, 3], 3]
 
FeynCalc`PairContract`Private`dimEval[3, 
     -4 + (FeynCalc`PairContract`Private`d_Symbol)] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d - 4, 3], 0]
 
FeynCalc`PairContract`Private`dimEval[
     -4 + (FeynCalc`PairContract`Private`d_Symbol), 
     -1 + (FeynCalc`PairContract`Private`d_Symbol)] := 
    MemSet[FeynCalc`PairContract`Private`dimEval[
      FeynCalc`PairContract`Private`d - 4, FeynCalc`PairContract`Private`d - 
       1], FeynCalc`PairContract`Private`d - 4]
 
FCUseCache[FeynCalc`CacheManagement`Private`fcFunc_, 
     FeynCalc`CacheManagement`Private`args_List, 
     FeynCalc`CacheManagement`Private`opts_List:{}] := 
    Block[{FeynCalc`CacheManagement`Private`fullOpts, 
      FeynCalc`CacheManagement`Private`cachedHead, 
      FeynCalc`CacheManagement`Private`hashValue, 
      FeynCalc`CacheManagement`Private`standardDownValues, 
      FeynCalc`CacheManagement`Private`currentDownValues, 
      FeynCalc`CacheManagement`Private`hashedDownValues}, 
     FeynCalc`CacheManagement`Private`fullOpts = 
       Sort[Flatten[Join[FeynCalc`CacheManagement`Private`opts, 
          FilterRules[Options[FeynCalc`CacheManagement`Private`fcFunc], 
           Except[FeynCalc`CacheManagement`Private`opts]]]]]; 
      FeynCalc`CacheManagement`Private`cachedHead = 
       ToExpression[StringJoin["cacheFunc", ToString[
          FeynCalc`CacheManagement`Private`fcFunc]]]; 
      If[MemberQ[FeynCalc`CacheManagement`Private`whiteListNames, 
        FeynCalc`CacheManagement`Private`fcFunc], 
       FeynCalc`CacheManagement`Private`cachedHead[
         FeynCalc`CacheManagement`Private`arg_, 
         FeynCalc`CacheManagement`Private`cargs_, 
         FeynCalc`CacheManagement`Private`ops_] := 
        MemSet[FeynCalc`CacheManagement`Private`cachedHead[
          FeynCalc`CacheManagement`Private`arg, 
          FeynCalc`CacheManagement`Private`cargs, 
          FeynCalc`CacheManagement`Private`ops], 
         FeynCalc`CacheManagement`Private`fcFunc[Sequence @@ 
           FeynCalc`CacheManagement`Private`arg, 
          FeynCalc`CacheManagement`Private`ops]], 
       Message[FCUseCache::blacklist, 
         FeynCalc`CacheManagement`Private`fcFunc]; Abort[]]; 
      FeynCalc`CacheManagement`Private`standardDownValues = 
       (DownValues[#1] & ) /@ {Pair, CartesianPair, TemporalPair, 
         ScalarProduct, CartesianScalarProduct, Momentum, CartesianMomentum, 
         TemporalMomentum, SP, SPD, SPE, CSP, CSPD, CSPE, TC}; 
      FeynCalc`CacheManagement`Private`standardDownValues = 
       Join[FeynCalc`CacheManagement`Private`standardDownValues, 
        {FeynCalc`Package`DiracGammaScheme, 
         FeynCalc`Package`PauliSigmaScheme}]; 
      Which[FeynCalc`CacheManagement`Private`fcFunc === FactorList2, 
       FeynCalc`CacheManagement`Private`currentDownValues = {}, 
       MemberQ[{ExpandScalarProduct, PairContract, 
         FeynCalc`Package`FCFastContract, 
         FeynCalc`NPointTo4Point`Private`getDet, 
         FeynCalc`SimplifyPolyLog`Private`simplifyArgument, 
         FeynCalc`FCApart`Private`pfracRaw, 
         FeynCalc`Package`momentumRoutingDenner, 
         FeynCalc`FCLoopFindIntegralMappings`Private`makeMappingRules}, 
        FeynCalc`CacheManagement`Private`fcFunc], 
       FeynCalc`CacheManagement`Private`currentDownValues = 
        FeynCalc`CacheManagement`Private`standardDownValues, True, 
       Message[FCUseCache::blacklist, 
         FeynCalc`CacheManagement`Private`fcFunc]; Abort[]]; 
      FeynCalc`CacheManagement`Private`hashValue = 
       Hash[FeynCalc`CacheManagement`Private`currentDownValues]; 
      If[$VersionNumber >= 10., 
       FeynCalc`CacheManagement`Private`hashedDownValues = 
         Key[FeynCalc`CacheManagement`Private`hashValue][
          FeynCalc`CacheManagement`Private`relevantDownValuesAssociation]; 
        If[MissingQ[FeynCalc`CacheManagement`Private`hashedDownValues], 
         FeynCalc`CacheManagement`Private`relevantDownValuesAssociation = 
          Append[
           FeynCalc`CacheManagement`Private`relevantDownValuesAssociation, 
           {FeynCalc`CacheManagement`Private`hashValue -> 
             FeynCalc`CacheManagement`Private`currentDownValues}], 
         If[FeynCalc`CacheManagement`Private`hashedDownValues =!= 
            FeynCalc`CacheManagement`Private`currentDownValues, 
           Message[FCUseCache::fail, StringJoin[
              "Detected a hash collision for ", 
              FeynCalc`CacheManagement`Private`fcFunc]]; Abort[]]; ]; ]; 
      FeynCalc`CacheManagement`Private`cachedHead[
       FeynCalc`CacheManagement`Private`args, 
       FeynCalc`CacheManagement`Private`hashValue, 
       FeynCalc`CacheManagement`Private`fullOpts]]
 
FCUseCache /: FCUseCache::blacklist = 
     "The function `1` is not whitelisted for FCUseCache. Evaluation \
aborted!"
 
FCUseCache /: FCUseCache::fail = "Error! FCUseCache has encountered a fatal \
problem and must abort the computation. The problem reads: `1`"
 
FCUseCache /: FCUseCache::usage = "FCUseCache[func,{arg1,...},{opt1...}] \
evaluates func[arg1,...,opt1,...] and\ncaches the result such that the next \
evaluation of same expressions occurs\nalmost immediately. This caching also \
takes into account DownValues and global\nvariables that enter into \
evaluation of func.\n\nFor example, ExpandScalarProduct can't be naively \
cached, because its result\ndepends on the DownValues of Pair and \
ScalarProduct, which may be changed\nmultiple times during the session by \
setting and erasing values of scalar\nproducts. With FCUseCache, however, \
caching will work properly, as FCUseCache\nknows the dependence on \
ExpandScalarProduct on those DownValues. For all this\nto work, a function \
should be explicitly white-listed in FCUseCache."
 
FeynCalc`CacheManagement`Private`whiteListNames = 
    {ExpandScalarProduct, FactorList2, PairContract, 
     FeynCalc`Package`FCFastContract, FeynCalc`NPointTo4Point`Private`getDet, 
     FeynCalc`SimplifyPolyLog`Private`simplifyArgument, 
     FeynCalc`FCApart`Private`pfracRaw, 
     FeynCalc`Package`momentumRoutingDenner, 
     FeynCalc`FCLoopFindIntegralMappings`Private`makeMappingRules}
 
ExpandScalarProduct[FeynCalc`ExpandScalarProduct`Private`expr_, 
     OptionsPattern[]] := Block[{FeynCalc`ExpandScalarProduct`Private`ex, 
      FeynCalc`ExpandScalarProduct`Private`pairList, 
      FeynCalc`ExpandScalarProduct`Private`pairListExpanded, 
      FeynCalc`ExpandScalarProduct`Private`protect, 
      FeynCalc`ExpandScalarProduct`Private`momentum, 
      FeynCalc`ExpandScalarProduct`Private`relevant, 
      FeynCalc`ExpandScalarProduct`Private`null1, 
      FeynCalc`ExpandScalarProduct`Private`null2}, 
     FeynCalc`ExpandScalarProduct`Private`optMomentum = 
       OptionValue[Momentum]; 
      If[FeynCalc`ExpandScalarProduct`Private`optMomentum =!= All && 
        Head[FeynCalc`ExpandScalarProduct`Private`optMomentum] =!= List, 
       FeynCalc`ExpandScalarProduct`Private`optMomentum = 
        {FeynCalc`ExpandScalarProduct`Private`optMomentum}]; 
      FeynCalc`ExpandScalarProduct`Private`objects = Join[$FCTensorList, 
        {TemporalPair}]; If[ !OptionValue[FCI], 
       FeynCalc`ExpandScalarProduct`Private`ex = 
        FCI[FeynCalc`ExpandScalarProduct`Private`expr], 
       FeynCalc`ExpandScalarProduct`Private`ex = 
        FeynCalc`ExpandScalarProduct`Private`expr]; 
      If[MatchQ[FeynCalc`ExpandScalarProduct`Private`ex, 
         Pair[Momentum[_, ___], Momentum[_, ___]] | CartesianPair[
           CartesianMomentum[_, ___], CartesianMomentum[_, ___]]] && 
        FreeQ[FeynCalc`ExpandScalarProduct`Private`ex, Plus], 
       Return[FeynCalc`ExpandScalarProduct`Private`ex]]; 
      If[FreeQ2[FeynCalc`ExpandScalarProduct`Private`ex, 
        FeynCalc`ExpandScalarProduct`Private`objects], 
       Return[FeynCalc`ExpandScalarProduct`Private`ex]]; 
      FeynCalc`ExpandScalarProduct`Private`relevant = 
       Cases[FeynCalc`ExpandScalarProduct`Private`ex + 
         FeynCalc`ExpandScalarProduct`Private`null1 + 
         FeynCalc`ExpandScalarProduct`Private`null2, 
        (Alternatives @@ FeynCalc`ExpandScalarProduct`Private`objects)[
          FeynCalc`ExpandScalarProduct`Private`a_, 
          FeynCalc`ExpandScalarProduct`Private`b___] /; 
          !FreeQ[{FeynCalc`ExpandScalarProduct`Private`a, 
            FeynCalc`ExpandScalarProduct`Private`b}, Plus], Infinity]; 
      If[FeynCalc`ExpandScalarProduct`Private`relevant === {}, 
       Return[FeynCalc`ExpandScalarProduct`Private`ex], 
       FeynCalc`ExpandScalarProduct`Private`relevant = 
        DeleteDuplicates[Sort[
          FeynCalc`ExpandScalarProduct`Private`relevant]]]; 
      If[FeynCalc`ExpandScalarProduct`Private`optMomentum === All, 
       FeynCalc`ExpandScalarProduct`Private`pairList = 
         Select[Cases2[FeynCalc`ExpandScalarProduct`Private`relevant, 
           FeynCalc`ExpandScalarProduct`Private`objects], 
           !FreeQ2[#1, FeynCalc`Package`TensorArgsList] & ]; 
        FeynCalc`ExpandScalarProduct`Private`pairListExpanded = 
         FeynCalc`ExpandScalarProduct`Private`pairList, 
       FeynCalc`ExpandScalarProduct`Private`pairList = 
         Select[Cases2[FeynCalc`ExpandScalarProduct`Private`relevant, 
           FeynCalc`ExpandScalarProduct`Private`objects], 
           !FreeQ2[#1, FeynCalc`Package`TensorArgsList] && 
             !FreeQ2[#1, 
              FeynCalc`ExpandScalarProduct`Private`optMomentum] & ]; 
        If[TrueQ[ !OptionValue[Full]], 
         FeynCalc`ExpandScalarProduct`Private`pairListExpanded = 
          FeynCalc`ExpandScalarProduct`Private`pairList //. 
            {Momentum[(FeynCalc`ExpandScalarProduct`Private`c_.)*
                  (FeynCalc`ExpandScalarProduct`Private`mom_) + 
                 (FeynCalc`ExpandScalarProduct`Private`rest_:0), 
                FeynCalc`ExpandScalarProduct`Private`dim___] /; MemberQ[
                FeynCalc`ExpandScalarProduct`Private`optMomentum, 
                FeynCalc`ExpandScalarProduct`Private`mom] :> 
              FeynCalc`ExpandScalarProduct`Private`momentum[
               FeynCalc`ExpandScalarProduct`Private`c*
                 FeynCalc`ExpandScalarProduct`Private`mom + 
                FeynCalc`ExpandScalarProduct`Private`protect[
                 FeynCalc`ExpandScalarProduct`Private`rest], 
               FeynCalc`ExpandScalarProduct`Private`dim], 
             Momentum[FeynCalc`ExpandScalarProduct`Private`rest_, 
                FeynCalc`ExpandScalarProduct`Private`dim___] /; FreeQ[
                FeynCalc`ExpandScalarProduct`Private`rest, 
                FeynCalc`ExpandScalarProduct`Private`optMomentum] :> 
              FeynCalc`ExpandScalarProduct`Private`momentum[
               FeynCalc`ExpandScalarProduct`Private`protect[
                FeynCalc`ExpandScalarProduct`Private`rest], 
               FeynCalc`ExpandScalarProduct`Private`dim]} /. 
           FeynCalc`ExpandScalarProduct`Private`momentum -> Momentum, 
         FeynCalc`ExpandScalarProduct`Private`pairListExpanded = 
          FeynCalc`ExpandScalarProduct`Private`pairList]]; 
      If[FeynCalc`ExpandScalarProduct`Private`pairList =!= {}, 
       FeynCalc`ExpandScalarProduct`Private`pairListExpanded = 
         FeynCalc`ExpandScalarProduct`Private`pairexpand /@ 
           FeynCalc`ExpandScalarProduct`Private`pairListExpanded /. 
          FeynCalc`ExpandScalarProduct`Private`protect -> Identity; 
        FeynCalc`ExpandScalarProduct`Private`ex = 
         FeynCalc`ExpandScalarProduct`Private`ex /. 
          Dispatch[Thread[FeynCalc`ExpandScalarProduct`Private`pairList -> 
             FeynCalc`ExpandScalarProduct`Private`pairListExpanded]]]; 
      If[OptionValue[EpsEvaluate] && 
         !FreeQ[FeynCalc`ExpandScalarProduct`Private`ex, Eps], 
       FeynCalc`ExpandScalarProduct`Private`ex = EpsEvaluate[
         FeynCalc`ExpandScalarProduct`Private`ex, FCI -> True, 
         Momentum -> OptionValue[Momentum], EpsExpand -> 
          OptionValue[EpsExpand]]]; If[OptionValue[FCE], 
       FeynCalc`ExpandScalarProduct`Private`ex = 
        FCE[FeynCalc`ExpandScalarProduct`Private`ex]]; 
      FeynCalc`ExpandScalarProduct`Private`ex]
 
Options[ExpandScalarProduct] = {EpsEvaluate -> False, EpsExpand -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, Full -> True, 
     Momentum -> All}
 
ExpandScalarProduct /: ExpandScalarProduct::usage = "ExpandScalarProduct[expr\
] expands scalar products of sums of momenta in expr.\n\nExpandScalarProduct \
does not use Expand on expr."
 
FeynCalc`ExpandScalarProduct`Private`optMomentum = All
 
FeynCalc`ExpandScalarProduct`Private`optMomentum /: 
    FeynCalc`ExpandScalarProduct`Private`optMomentum::usage = ""
 
FeynCalc`ExpandScalarProduct`Private`objects = {Pair, Eps, CartesianPair, 
     TemporalPair}
 
FeynCalc`ExpandScalarProduct`Private`objects /: 
    FeynCalc`ExpandScalarProduct`Private`objects::usage = ""
 
$FCTensorList := {Pair, Eps, CartesianPair}
 
($FCTensorList = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$FCTensorList] = 
           {HoldPattern[$FCTensorList] :> FeynCalc`Private`xxx}; , 
         DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$FCTensorList] = {HoldPattern[$FCTensorList] :> 
         FeynCalc`Private`xxx}]; FeynCalc`Private`val)
 
$FCTensorList /: $FCTensorList::usage = 
     "$FCTensorList contains a list of all tensor heads present."
 
Cases2[FeynCalc`SharedTools`Private`expr_, 
     {FeynCalc`SharedTools`Private`f___}, FeynCalc`SharedTools`Private`opts:
      OptionsPattern[]] := Cases2 @@ Prepend[{FeynCalc`SharedTools`Private`f, 
       FeynCalc`SharedTools`Private`opts}, FeynCalc`SharedTools`Private`expr]
 
Cases2[FeynCalc`SharedTools`Private`expr_, FeynCalc`SharedTools`Private`f_, 
     FeynCalc`SharedTools`Private`opts:OptionsPattern[]] := 
    Union[Cases[{FeynCalc`SharedTools`Private`expr}, 
      HoldPattern[FeynCalc`SharedTools`Private`f[___]], Infinity, 
      FeynCalc`SharedTools`Private`opts]]
 
Cases2[FeynCalc`SharedTools`Private`expr_, FeynCalc`SharedTools`Private`f_, 
     FeynCalc`SharedTools`Private`g__, FeynCalc`SharedTools`Private`opts:
      OptionsPattern[]] := Union[Cases[{FeynCalc`SharedTools`Private`expr}, 
      Alternatives @@ (HoldPattern[#1[___]] & ) /@ 
        {FeynCalc`SharedTools`Private`f, FeynCalc`SharedTools`Private`g}, 
      Infinity, FilterRules[{FeynCalc`SharedTools`Private`opts}, 
       Options[Cases]]]]
 
Options[Cases2] = {Heads -> False}
 
Cases2 /: Cases2::usage = "Cases2[expr, f] returns a list of all objects in \
expr with head f.\n\nCases2[expr,f] is equivalent to \
Cases2[{expr},f[___],Infinity]//Union.\n\nCases2[expr, f, g, ...] or \
Cases2[expr, {f,g, ...}] is equivalent to\nCases[{expr},f[___] | g[___] \
...]."
 
FeynCalc`Package`TensorArgsList = {LorentzIndex, ExplicitLorentzIndex, 
     Momentum, CartesianIndex, CartesianMomentum, TemporalMomentum}
 
FeynCalc`ExpandScalarProduct`Private`pairexpand[
     FeynCalc`ExpandScalarProduct`Private`x_] := 
    FeynCalc`ExpandScalarProduct`Private`x /. 
      (FeynCalc`ExpandScalarProduct`Private`head:Alternatives @@ 
           FeynCalc`ExpandScalarProduct`Private`objects)[
         FeynCalc`ExpandScalarProduct`Private`arg__] /; 
        FeynCalc`ExpandScalarProduct`Private`head =!= Eps :> 
       FeynCalc`ExpandScalarProduct`Private`scevdoit[
        FeynCalc`ExpandScalarProduct`Private`head, 
        FeynCalc`ExpandScalarProduct`Private`arg] //. 
     {(FeynCalc`ExpandScalarProduct`Private`head:Alternatives @@ 
           FeynCalc`ExpandScalarProduct`Private`objects)[
         FeynCalc`ExpandScalarProduct`Private`arg1___, 
         (FeynCalc`ExpandScalarProduct`Private`z_)*
          (FeynCalc`ExpandScalarProduct`Private`n_)?NumberQ, 
         FeynCalc`ExpandScalarProduct`Private`arg2___] /; 
        FeynCalc`ExpandScalarProduct`Private`head =!= Eps :> 
       FeynCalc`ExpandScalarProduct`Private`n*
        FeynCalc`ExpandScalarProduct`Private`head[
         FeynCalc`ExpandScalarProduct`Private`arg1, 
         FeynCalc`ExpandScalarProduct`Private`z, 
         FeynCalc`ExpandScalarProduct`Private`arg2], 
      (FeynCalc`ExpandScalarProduct`Private`head:Alternatives @@ 
           FeynCalc`ExpandScalarProduct`Private`objects)[
         FeynCalc`ExpandScalarProduct`Private`arg1___, 
         (FeynCalc`ExpandScalarProduct`Private`z_)*
           (FeynCalc`ExpandScalarProduct`Private`n_) /; 
          DataType[FeynCalc`ExpandScalarProduct`Private`n, FCVariable], 
         FeynCalc`ExpandScalarProduct`Private`arg2___] /; 
        FeynCalc`ExpandScalarProduct`Private`head =!= Eps :> 
       FeynCalc`ExpandScalarProduct`Private`n*
        FeynCalc`ExpandScalarProduct`Private`head[
         FeynCalc`ExpandScalarProduct`Private`arg1, 
         FeynCalc`ExpandScalarProduct`Private`z, 
         FeynCalc`ExpandScalarProduct`Private`arg2]}
 
FeynCalc`ExpandScalarProduct`Private`scevdoit[
     FeynCalc`ExpandScalarProduct`Private`head_, 
     FeynCalc`ExpandScalarProduct`Private`arg__] := 
    Distribute[FeynCalc`ExpandScalarProduct`Private`tmpHead @@ 
       Expand[MomentumExpand[{FeynCalc`ExpandScalarProduct`Private`arg}, 
         Momentum -> FeynCalc`ExpandScalarProduct`Private`optMomentum]]] /. 
     FeynCalc`ExpandScalarProduct`Private`tmpHead -> 
      FeynCalc`ExpandScalarProduct`Private`head
 
FeynCalc`ExpandScalarProduct`Private`tmpHead /: 
    FeynCalc`ExpandScalarProduct`Private`tmpHead::usage = ""
 
MomentumExpand[(FeynCalc`MomentumExpand`Private`head:
       Momentum | CartesianMomentum | TemporalMomentum)[
      FeynCalc`MomentumExpand`Private`args__], OptionsPattern[]] := 
    FeynCalc`MomentumExpand`Private`momSplit[
         FeynCalc`MomentumExpand`Private`head, OptionValue[Momentum]][
        FeynCalc`MomentumExpand`Private`args] /. 
       FeynCalc`MomentumExpand`Private`head -> 
        FeynCalc`MomentumExpand`Private`expandVec[
         FeynCalc`MomentumExpand`Private`head] /. 
      FeynCalc`MomentumExpand`Private`linearizeVec -> 
       FeynCalc`MomentumExpand`Private`head /. 
     FeynCalc`MomentumExpand`Private`noexpand -> Identity
 
MomentumExpand[FeynCalc`MomentumExpand`Private`expr_List, 
     FeynCalc`MomentumExpand`Private`opts:OptionsPattern[]] := 
    (MomentumExpand[#1, FeynCalc`MomentumExpand`Private`opts] & ) /@ 
     FeynCalc`MomentumExpand`Private`expr
 
MomentumExpand[FeynCalc`MomentumExpand`Private`expr_ /; 
       !MemberQ[{Momentum, CartesianMomentum, TemporalMomentum, List}, 
        Head[FeynCalc`MomentumExpand`Private`expr]], OptionsPattern[]] := 
    Block[{FeynCalc`MomentumExpand`Private`aux, 
      FeynCalc`MomentumExpand`Private`res, 
      FeynCalc`MomentumExpand`Private`hold1, 
      FeynCalc`MomentumExpand`Private`hold2, 
      FeynCalc`MomentumExpand`Private`listOrig, 
      FeynCalc`MomentumExpand`Private`listEval, 
      FeynCalc`MomentumExpand`Private`repRule, 
      FeynCalc`MomentumExpand`Private`optMomentum, 
      FeynCalc`MomentumExpand`Private`optVerbose}, 
     FeynCalc`MomentumExpand`Private`optMomentum = OptionValue[Momentum]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`MomentumExpand`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`MomentumExpand`Private`optVerbose = OptionValue[
           FCVerbose]]; ]; FCPrint[1, "MomentumExpand: Entering.", 
       FCDoControl -> FeynCalc`MomentumExpand`Private`optVerbose]; 
      FCPrint[3, "MomentumExpand: Entering with: ", 
       FeynCalc`MomentumExpand`Private`expr, FCDoControl -> 
        FeynCalc`MomentumExpand`Private`optVerbose]; 
      FeynCalc`MomentumExpand`Private`aux = 
       FeynCalc`MomentumExpand`Private`expr /. 
         FeynCalc`MomentumExpand`Private`hd:Spinor | FeynAmpDenominator | 
            PropagatorDenominator :> FeynCalc`MomentumExpand`Private`hold1[
           FeynCalc`MomentumExpand`Private`hd] /. 
        FeynCalc`MomentumExpand`Private`hd:Pair | CartesianPair | 
           TemporalPair :> FeynCalc`MomentumExpand`Private`hold2[
          FeynCalc`MomentumExpand`Private`hd]; 
      FCPrint[3, "MomentumExpand: After applying holds: ", 
       FeynCalc`MomentumExpand`Private`aux, FCDoControl -> 
        FeynCalc`MomentumExpand`Private`optVerbose]; 
      If[ !FreeQ[FeynCalc`MomentumExpand`Private`aux, Momentum], 
       FeynCalc`MomentumExpand`Private`aux = 
         FeynCalc`MomentumExpand`Private`momExpand[
          FeynCalc`MomentumExpand`Private`aux, Momentum, 
          FeynCalc`MomentumExpand`Private`optMomentum]; 
        If[ !FreeQ2[FeynCalc`MomentumExpand`Private`aux, 
           {FeynCalc`MomentumExpand`Private`expandVec, 
            FeynCalc`MomentumExpand`Private`linearizeVec, 
            FeynCalc`MomentumExpand`Private`noexpand}], 
         Message[MomentumExpand::failmsg, 
           "Something went wrong during the expansion of 4-momenta."]; 
          Abort[]]; FCPrint[3, 
         "MomentumExpand: After momExpand for Momentum: ", 
         FeynCalc`MomentumExpand`Private`aux, FCDoControl -> 
          FeynCalc`MomentumExpand`Private`optVerbose]; ]; 
      If[ !FreeQ[FeynCalc`MomentumExpand`Private`aux, CartesianMomentum], 
       FeynCalc`MomentumExpand`Private`aux = 
         FeynCalc`MomentumExpand`Private`momExpand[
          FeynCalc`MomentumExpand`Private`aux, CartesianMomentum, 
          FeynCalc`MomentumExpand`Private`optMomentum]; 
        If[ !FreeQ2[FeynCalc`MomentumExpand`Private`aux, 
           {FeynCalc`MomentumExpand`Private`expandVec, 
            FeynCalc`MomentumExpand`Private`linearizeVec, 
            FeynCalc`MomentumExpand`Private`noexpand}], 
         Message[MomentumExpand::failmsg, 
           "Something went wrong during the expansion of 3-momenta."]; 
          Abort[]]]; If[ !FreeQ[FeynCalc`MomentumExpand`Private`aux, 
         TemporalMomentum], FeynCalc`MomentumExpand`Private`aux = 
         FeynCalc`MomentumExpand`Private`momExpand[
          FeynCalc`MomentumExpand`Private`aux, TemporalMomentum, 
          FeynCalc`MomentumExpand`Private`optMomentum]; 
        If[ !FreeQ2[FeynCalc`MomentumExpand`Private`aux, 
           {FeynCalc`MomentumExpand`Private`expandVec, 
            FeynCalc`MomentumExpand`Private`linearizeVec, 
            FeynCalc`MomentumExpand`Private`noexpand}], 
         Message[MomentumExpand::failmsg, "Something went wrong during the \
expansion of 0th momentum components."]; Abort[]]]; 
      If[ !FreeQ[FeynCalc`MomentumExpand`Private`aux, 
         LightConePerpendicularComponent], 
       FeynCalc`MomentumExpand`Private`aux = 
         FeynCalc`MomentumExpand`Private`momExpand[
          FeynCalc`MomentumExpand`Private`aux, 
          LightConePerpendicularComponent, All]; 
        If[ !FreeQ2[FeynCalc`MomentumExpand`Private`aux, 
           {FeynCalc`MomentumExpand`Private`expandVec, 
            FeynCalc`MomentumExpand`Private`linearizeVec, 
            FeynCalc`MomentumExpand`Private`noexpand}], 
         Message[MomentumExpand::failmsg, 
           "Something went wrong during the expansion of 4-momenta."]; 
          Abort[]]]; FeynCalc`MomentumExpand`Private`res = 
       FeynCalc`MomentumExpand`Private`aux /. 
         FeynCalc`MomentumExpand`Private`hold2 -> Identity /. 
        FeynCalc`MomentumExpand`Private`hold1 -> Identity; 
      FCPrint[1, "MomentumExpand: Leaving.", FCDoControl -> 
        FeynCalc`MomentumExpand`Private`optVerbose]; 
      FCPrint[3, "MomentumExpand Leaving with: ", 
       FeynCalc`MomentumExpand`Private`res, FCDoControl -> 
        FeynCalc`MomentumExpand`Private`optVerbose]; 
      FeynCalc`MomentumExpand`Private`res]
 
Options[MomentumExpand] = {FCVerbose -> False, Momentum -> All}
 
MomentumExpand /: MomentumExpand::failmsg = "Error! MomentumExpand has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
MomentumExpand /: MomentumExpand::usage = "MomentumExpand[expr] expands \
Momentum[a+b+ ...] in expr into Momentum[a] +\nMomentum[b] + ...."
 
FeynCalc`MomentumExpand`Private`momSplit[
      FeynCalc`MomentumExpand`Private`head_, All][
     FeynCalc`MomentumExpand`Private`a__] := 
    FeynCalc`MomentumExpand`Private`head[FeynCalc`MomentumExpand`Private`a]
 
FeynCalc`MomentumExpand`Private`momSplit[
      FeynCalc`MomentumExpand`Private`head_, 
      FeynCalc`MomentumExpand`Private`moms_List][
     FeynCalc`MomentumExpand`Private`a_, 
     FeynCalc`MomentumExpand`Private`dim___] := 
    Function[{FeynCalc`MomentumExpand`Private`x, 
       FeynCalc`MomentumExpand`Private`y}, 
      FeynCalc`MomentumExpand`Private`head[
       FeynCalc`MomentumExpand`Private`noexpand[
         FeynCalc`MomentumExpand`Private`x] + 
        FeynCalc`MomentumExpand`Private`y, 
       FeynCalc`MomentumExpand`Private`dim]] @@ 
     FCSplit[FeynCalc`MomentumExpand`Private`a, 
      FeynCalc`MomentumExpand`Private`moms]
 
FeynCalc`MomentumExpand`Private`noexpand /: 
    FeynCalc`MomentumExpand`Private`noexpand::usage = ""
 
FCSplit[FeynCalc`SharedTools`Private`expr_, 
     FeynCalc`SharedTools`Private`vars_List /; 
      FeynCalc`SharedTools`Private`vars =!= {}, OptionsPattern[]] := 
    Block[{FeynCalc`SharedTools`Private`free, 
       FeynCalc`SharedTools`Private`notfree, 
       FeynCalc`SharedTools`Private`tmp, FeynCalc`SharedTools`Private`time}, 
      If[OptionValue[Expanding], FeynCalc`SharedTools`Private`tmp = 
         Expand2[FeynCalc`SharedTools`Private`expr, 
          FeynCalc`SharedTools`Private`vars], 
        FeynCalc`SharedTools`Private`tmp = 
         FeynCalc`SharedTools`Private`expr]; 
       FeynCalc`SharedTools`Private`time = AbsoluteTime[]; 
       If[Head[FeynCalc`SharedTools`Private`tmp] === Plus, 
        FeynCalc`SharedTools`Private`free = SelectFree[
           FeynCalc`SharedTools`Private`tmp, 
           FeynCalc`SharedTools`Private`vars]; 
         FeynCalc`SharedTools`Private`notfree = SelectNotFree[
           FeynCalc`SharedTools`Private`tmp, 
           FeynCalc`SharedTools`Private`vars], 
        If[FreeQ2[FeynCalc`SharedTools`Private`tmp, 
          FeynCalc`SharedTools`Private`vars], 
         FeynCalc`SharedTools`Private`free = 
           FeynCalc`SharedTools`Private`tmp; 
          FeynCalc`SharedTools`Private`notfree = 0, 
         FeynCalc`SharedTools`Private`notfree = 
           FeynCalc`SharedTools`Private`tmp; 
          FeynCalc`SharedTools`Private`free = 0]]; 
       FCPrint[1, "FCSplit: Splitting, timing: ", 
        N[AbsoluteTime[] - FeynCalc`SharedTools`Private`time, 4]]; 
       If[FeynCalc`SharedTools`Private`free + 
           FeynCalc`SharedTools`Private`notfree =!= 
          FeynCalc`SharedTools`Private`tmp || 
          !FreeQ2[FeynCalc`SharedTools`Private`free, 
           FeynCalc`SharedTools`Private`vars], 
        Message[FCSplit::failmsg, StringJoin["Error! Splitting", 
           ToString[FeynCalc`SharedTools`Private`expr, InputForm], " w.r.t ", 
           ToString[FeynCalc`SharedTools`Private`vars, InputForm], 
           " failed!"]]; Abort[]]; {FeynCalc`SharedTools`Private`free, 
        FeynCalc`SharedTools`Private`notfree}] /; 
     Head[FeynCalc`SharedTools`Private`expr] =!= List
 
FCSplit[FeynCalc`SharedTools`Private`expr_List, 
     FeynCalc`SharedTools`Private`vars_List /; 
      FeynCalc`SharedTools`Private`vars =!= {}, 
     FeynCalc`SharedTools`Private`opts:OptionsPattern[]] := 
    (FCSplit[#1, FeynCalc`SharedTools`Private`vars, 
       FeynCalc`SharedTools`Private`opts] & ) /@ 
     FeynCalc`SharedTools`Private`expr
 
FCSplit[_, FeynCalc`SharedTools`Private`vars_, OptionsPattern[]] := 
    (Message[FCSplit::failmsg, "The second argument must be a list."]; 
      Abort[]) /; Head[FeynCalc`SharedTools`Private`vars] =!= List
 
Options[FCSplit] = {Expanding -> True}
 
FCSplit /: FCSplit::failmsg = "Error! FCSplit has encountered a fatal problem \
and must abort the computation. \n\nThe problem reads: `1`"
 
FCSplit /: FCSplit::usage = "FCSplit[exp, {v1, v2, ...}] splits expr into \
pieces that are free of any\noccurrence of v1, v2, ... and pieces that \
contain those variables. This works\nboth on sums and products. The output is \
provided in the form of a two element\nlist. One can recover the original \
expression by applying Total to that list."
 
Expanding /: Expanding::usage = "Expanding is an option for Contract, \
DiracSimplify, DotSimplify, SUNSimplify\netc. \n\nAs option for Contract it \
specifies whether expansion w.r.t. LorentzIndex is\ndone _before_ \
contraction. If set to False in DiracSimplify or SUNSimplify,\nonly a limited \
set of simplifications (multiplicative linearity etc.) is\nperformed."
 
SelectFree[0, __] := 0
 
SelectFree[FeynCalc`SharedTools`Private`a_, 
     FeynCalc`SharedTools`Private`b__] := 
    Block[{FeynCalc`SharedTools`Private`dum1, 
      FeynCalc`SharedTools`Private`dum2, 
      FeynCalc`SharedTools`Private`select}, 
     FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`x_, 
        FeynCalc`SharedTools`Private`y_ /; 
         Head[FeynCalc`SharedTools`Private`y] =!= List] := 
       Select[FeynCalc`SharedTools`Private`x, 
        FreeQ[#1, FeynCalc`SharedTools`Private`y] & ]; 
      FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`x_, 
        FeynCalc`SharedTools`Private`y_List] := 
       Select[FeynCalc`SharedTools`Private`x, 
        FreeQ2[#1, FeynCalc`SharedTools`Private`y] & ]; 
      FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`x_, 
        FeynCalc`SharedTools`Private`y_, FeynCalc`SharedTools`Private`z__] := 
       Select[FeynCalc`SharedTools`Private`x, 
        FreeQ2[#1, Flatten[{FeynCalc`SharedTools`Private`y, 
            FeynCalc`SharedTools`Private`z}]] & ]; 
      If[Head[FeynCalc`SharedTools`Private`a] === Plus || 
        Head[FeynCalc`SharedTools`Private`a] === Times || 
        Head[FeynCalc`SharedTools`Private`a] === List, 
       FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`a, 
        FeynCalc`SharedTools`Private`b], FeynCalc`SharedTools`Private`select[
         FeynCalc`SharedTools`Private`a*FeynCalc`SharedTools`Private`dum1*
          FeynCalc`SharedTools`Private`dum2, 
         FeynCalc`SharedTools`Private`b] /. 
        {FeynCalc`SharedTools`Private`dum1 :> 1, 
         FeynCalc`SharedTools`Private`dum2 :> 1}]]
 
SelectFree /: SelectFree::usage = "SelectFree[expr, a, b, ...] is equivalent \
to Select[expr, FreeQ2[#, {a,b,\n...}]&], except the special cases: \
SelectFree[a, b] returns a and\nSelectFree[a,a] returns 1 (where a is not a \
product or a sum)."
 
SelectNotFree[0, __] := 0
 
SelectNotFree[FeynCalc`SharedTools`Private`a_, 
     FeynCalc`SharedTools`Private`b__] := 
    Block[{FeynCalc`SharedTools`Private`dum1, 
      FeynCalc`SharedTools`Private`dum2, 
      FeynCalc`SharedTools`Private`select}, 
     FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`x_, 
        FeynCalc`SharedTools`Private`y_ /; 
         Head[FeynCalc`SharedTools`Private`y] =!= List] := 
       Select[FeynCalc`SharedTools`Private`x, 
         !FreeQ[#1, FeynCalc`SharedTools`Private`y] & ]; 
      FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`x_, 
        FeynCalc`SharedTools`Private`y_List] := 
       Select[FeynCalc`SharedTools`Private`x, 
         !FreeQ2[#1, FeynCalc`SharedTools`Private`y] & ]; 
      FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`x_, 
        FeynCalc`SharedTools`Private`y_, FeynCalc`SharedTools`Private`z__] := 
       Select[FeynCalc`SharedTools`Private`x, 
         !FreeQ2[#1, Flatten[{FeynCalc`SharedTools`Private`y, 
             FeynCalc`SharedTools`Private`z}]] & ]; 
      If[Head[FeynCalc`SharedTools`Private`a] === Plus || 
        Head[FeynCalc`SharedTools`Private`a] === Times || 
        Head[FeynCalc`SharedTools`Private`a] === List, 
       FeynCalc`SharedTools`Private`select[FeynCalc`SharedTools`Private`a, 
        FeynCalc`SharedTools`Private`b], FeynCalc`SharedTools`Private`select[
         FeynCalc`SharedTools`Private`a*FeynCalc`SharedTools`Private`dum1*
          FeynCalc`SharedTools`Private`dum2, 
         FeynCalc`SharedTools`Private`b] /. 
        {FeynCalc`SharedTools`Private`dum1 :> 1, 
         FeynCalc`SharedTools`Private`dum2 :> 1}]]
 
SelectNotFree /: SelectNotFree::usage = "SelectNotFree[expr, x] returns that \
part of expr which is not free of any\noccurrence of \
x.\n\nSelectNotFree[expr, a, b, ...] is equivalent to Select[expr, !FreeQ2[#, \
{a, b,\n...}]&], except the special cases:\nSelectNotFree[a, b] returns 1 and \
SelectNotFree[a, a] returns a (where a is\nnot a product or a sum)."
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k1, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k1, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k3, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k3, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2 - 2*l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] - 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][2*k1 + k2 - 2*l, D] = 
    2*FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] - 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k3 - 2*l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][2*k1 + k3 - 2*l, D] = 
    2*FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][2*k1 + 2*k2 + k3 - 2*l, 
     D] = 2*FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][2*k1 + k2 + 2*k3 - 2*l, 
     D] = 2*FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k1 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k1 + k2 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k3 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k1 + k3 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2 + k3 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k1 + k2 + k3 - l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k1 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k1 + l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k2 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k1 - k2 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2 + l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k3 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k1 - k3 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k2 - k3 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][-k1 - k2 - k3 + l, D] = 
    -FeynCalc`MomentumExpand`Private`linearizeVec[k1, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] - 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k3 + l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2 + k3 + l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[k3, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][k2 + 2*l, D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[k2, D] + 
     2*FeynCalc`MomentumExpand`Private`linearizeVec[l, D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][
     l + FeynCalc`MomentumExpand`Private`noexpand[
       FeynCalc`ExpandScalarProduct`Private`protect[0]], D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[l, D] + 
     FeynCalc`MomentumExpand`Private`linearizeVec[
      FeynCalc`MomentumExpand`Private`noexpand[
       FeynCalc`ExpandScalarProduct`Private`protect[0]], D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][
     FeynCalc`MomentumExpand`Private`noexpand[
      FeynCalc`ExpandScalarProduct`Private`protect[k1]], D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[
     FeynCalc`MomentumExpand`Private`noexpand[
      FeynCalc`ExpandScalarProduct`Private`protect[k1]], D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][
     FeynCalc`MomentumExpand`Private`noexpand[
      FeynCalc`ExpandScalarProduct`Private`protect[k2]], D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[
     FeynCalc`MomentumExpand`Private`noexpand[
      FeynCalc`ExpandScalarProduct`Private`protect[k2]], D]
 
FeynCalc`MomentumExpand`Private`expandVec[Momentum][
     FeynCalc`MomentumExpand`Private`noexpand[
      FeynCalc`ExpandScalarProduct`Private`protect[k3]], D] = 
    FeynCalc`MomentumExpand`Private`linearizeVec[
     FeynCalc`MomentumExpand`Private`noexpand[
      FeynCalc`ExpandScalarProduct`Private`protect[k3]], D]
 
FeynCalc`MomentumExpand`Private`expandVec[
      FeynCalc`MomentumExpand`Private`head_][
     FeynCalc`MomentumExpand`Private`y_, 
     FeynCalc`MomentumExpand`Private`dim___] := 
    FeynCalc`MomentumExpand`Private`expandVec[
       FeynCalc`MomentumExpand`Private`head][
      FeynCalc`MomentumExpand`Private`y, 
      FeynCalc`MomentumExpand`Private`dim] = 
     Distribute[FeynCalc`MomentumExpand`Private`linearizeVec[
        Expand[ExpandAll[FeynCalc`MomentumExpand`Private`y], 
         FeynCalc`MomentumExpand`Private`head], 
        FeynCalc`MomentumExpand`Private`hold[
         FeynCalc`MomentumExpand`Private`dim]]] /. 
      FeynCalc`MomentumExpand`Private`hold -> Sequence
 
FeynCalc`MomentumExpand`Private`linearizeVec[
     (FeynCalc`MomentumExpand`Private`z_)*
      (FeynCalc`MomentumExpand`Private`n_)?NumberQ, 
     FeynCalc`MomentumExpand`Private`dim___] := 
    FeynCalc`MomentumExpand`Private`n*
     FeynCalc`MomentumExpand`Private`linearizeVec[
      FeynCalc`MomentumExpand`Private`z, FeynCalc`MomentumExpand`Private`dim]
 
FeynCalc`MomentumExpand`Private`hold[] := Sequence[]
 
FeynAmpDenominator /: FeynAmpDenominator::usage = "FeynAmpDenominator[...] \
represents the inverse denominators of the\npropagators, i.e. \
FeynAmpDenominator[x] is $1/x$. Different propagator\ndenominators are \
represented using special heads such as\nPropagatorDenominator, \
StandardPropagatorDenominator,\nCartesianPropagatorDenominator etc."
 
PropagatorDenominator[FeynCalc`SharedObjects`Private`a_ /; 
      FCPatternFreeQ[{FeynCalc`SharedObjects`Private`a}]] := 
    PropagatorDenominator[FeynCalc`SharedObjects`Private`a, 0]
 
PropagatorDenominator /: PropagatorDenominator::usage = "PropagatorDenominato\
r[Momentum[q], m]  is a factor of the denominator of a\npropagator. If q is \
supposed to be $D$-dimensional, use\nPropagatorDenominator[Momentum[q, D], \
m]. What is meant is $1/(q^2-m^2)$.\n\nPropagatorDenominator must appear \
inside FeynAmpDenominator, it is not a\nstandalone object."
 
FeynCalc`MomentumExpand`Private`momExpand[
     FeynCalc`MomentumExpand`Private`ex_, 
     FeynCalc`MomentumExpand`Private`head_, 
     FeynCalc`MomentumExpand`Private`optMomentum_] := 
    Block[{FeynCalc`MomentumExpand`Private`listOrig, 
      FeynCalc`MomentumExpand`Private`listEval, 
      FeynCalc`MomentumExpand`Private`repRule}, 
     FeynCalc`MomentumExpand`Private`listOrig = 
       Cases2[FeynCalc`MomentumExpand`Private`ex, 
        FeynCalc`MomentumExpand`Private`head]; 
      FeynCalc`MomentumExpand`Private`listEval = 
       FeynCalc`MomentumExpand`Private`listOrig /. 
           FeynCalc`MomentumExpand`Private`head -> 
            FeynCalc`MomentumExpand`Private`momSplit[
             FeynCalc`MomentumExpand`Private`head, 
             FeynCalc`MomentumExpand`Private`optMomentum] /. 
          FeynCalc`MomentumExpand`Private`head -> 
           FeynCalc`MomentumExpand`Private`expandVec[
            FeynCalc`MomentumExpand`Private`head] /. 
         FeynCalc`MomentumExpand`Private`linearizeVec -> 
          FeynCalc`MomentumExpand`Private`head /. 
        FeynCalc`MomentumExpand`Private`noexpand -> Identity; 
      FeynCalc`MomentumExpand`Private`repRule = 
       Thread[FeynCalc`MomentumExpand`Private`listOrig -> 
         FeynCalc`MomentumExpand`Private`listEval]; 
      FeynCalc`MomentumExpand`Private`ex /. 
       Dispatch[FeynCalc`MomentumExpand`Private`repRule]]
 
EpsEvaluate[FeynCalc`EpsEvaluate`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`EpsEvaluate`Private`ex, 
      FeynCalc`EpsEvaluate`Private`uniqList, 
      FeynCalc`EpsEvaluate`Private`rud, FeynCalc`EpsEvaluate`Private`repRule, 
      FeynCalc`EpsEvaluate`Private`null1, FeynCalc`EpsEvaluate`Private`null2, 
      FeynCalc`EpsEvaluate`Private`res, 
      FeynCalc`EpsEvaluate`Private`epsEval}, 
     FeynCalc`EpsEvaluate`Private`optMomentum = OptionValue[Momentum]; 
      If[ !OptionValue[FCI], FeynCalc`EpsEvaluate`Private`ex = 
        FCI[FeynCalc`EpsEvaluate`Private`expr], 
       FeynCalc`EpsEvaluate`Private`ex = FeynCalc`EpsEvaluate`Private`expr]; 
      If[FreeQ[FeynCalc`EpsEvaluate`Private`ex, Eps], 
       Return[FeynCalc`EpsEvaluate`Private`ex]]; 
      FeynCalc`EpsEvaluate`Private`uniqList = 
       Sort[DeleteDuplicates[Cases[FeynCalc`EpsEvaluate`Private`ex + 
           FeynCalc`EpsEvaluate`Private`null1 + 
           FeynCalc`EpsEvaluate`Private`null2, _Eps, Infinity]]]; 
      If[FeynCalc`EpsEvaluate`Private`optMomentum =!= All && 
        Head[FeynCalc`EpsEvaluate`Private`optMomentum] === List, 
       FeynCalc`EpsEvaluate`Private`uniqList = 
        Select[FeynCalc`EpsEvaluate`Private`uniqList, 
          !FreeQ2[#1, FeynCalc`EpsEvaluate`Private`optMomentum] & ]]; 
      If[OptionValue[EpsExpand], FeynCalc`EpsEvaluate`Private`epsEval = 
        FeynCalc`EpsEvaluate`Private`epsEvalMomExpand, 
       FeynCalc`EpsEvaluate`Private`epsEval = 
        FeynCalc`EpsEvaluate`Private`epsEvalMomCombine]; 
      FeynCalc`EpsEvaluate`Private`repRule = 
       Thread[FeynCalc`EpsEvaluate`Private`rud[
         FeynCalc`EpsEvaluate`Private`uniqList, 
         FeynCalc`EpsEvaluate`Private`uniqList /. 
          Eps -> FeynCalc`EpsEvaluate`Private`epsEval]]; 
      FeynCalc`EpsEvaluate`Private`repRule = 
       FeynCalc`EpsEvaluate`Private`repRule /. 
         FeynCalc`EpsEvaluate`Private`rud[FeynCalc`EpsEvaluate`Private`a_, 
           FeynCalc`EpsEvaluate`Private`a_] :> Unevaluated[Sequence[]] /. 
        FeynCalc`EpsEvaluate`Private`rud -> RuleDelayed; 
      If[ !FreeQ2[FeynCalc`EpsEvaluate`Private`repRule, 
         {FeynCalc`EpsEvaluate`Private`epsEvalMomExpand, 
          FeynCalc`EpsEvaluate`Private`epsEvalMomCombine, 
          FeynCalc`EpsEvaluate`Private`epsEvalLinearity, 
          FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm}], 
       Message[EpsEvaluate::failmsg, 
         "Some expressions could not be evaluated."]; Abort[]]; 
      FeynCalc`EpsEvaluate`Private`res = FeynCalc`EpsEvaluate`Private`ex /. 
        Dispatch[FeynCalc`EpsEvaluate`Private`repRule]; 
      If[OptionValue[FCE], FeynCalc`EpsEvaluate`Private`res = 
        FCE[FeynCalc`EpsEvaluate`Private`res]]; 
      FeynCalc`EpsEvaluate`Private`res]
 
Options[EpsEvaluate] = {EpsExpand -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, Momentum -> All}
 
EpsEvaluate /: EpsEvaluate::failmsg = "Error! EpsEvaluate has encountered a \
fatal problem and must abort the computation. The problem reads: `1`"
 
EpsEvaluate /: EpsEvaluate::usage = "EpsEvaluate[expr] applies total \
antisymmetry and linearity (w.r.t. momenta) to\nall Levi-Civita tensors (Eps) \
in expr."
 
FeynCalc`EpsEvaluate`Private`optMomentum = All
 
FeynCalc`EpsEvaluate`Private`optMomentum /: 
    FeynCalc`EpsEvaluate`Private`optMomentum::usage = ""
 
EpsExpand /: EpsExpand::usage = "EpsExpand is an option for EpsEvaluate and \
other functions that use\nEpsEvaluate internally. When set to False, sums of \
momenta in the Eps tensor\nwill not be rewritten as a sum of Eps tensors."
 
FeynCalc`EpsEvaluate`Private`epsEvalMomExpand[
     FeynCalc`EpsEvaluate`Private`a_, FeynCalc`EpsEvaluate`Private`b_, 
     FeynCalc`EpsEvaluate`Private`c__] := 
    Expand /@ Distribute[MomentumExpand[DOT[FeynCalc`EpsEvaluate`Private`a, 
            FeynCalc`EpsEvaluate`Private`b, FeynCalc`EpsEvaluate`Private`c], 
           Momentum -> FeynCalc`EpsEvaluate`Private`optMomentum]] /. 
        DOT -> FeynCalc`EpsEvaluate`Private`epsEvalLinearity /. 
       FeynCalc`EpsEvaluate`Private`epsEvalLinearity -> 
        FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm /. 
      FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm -> 
       FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm2 /. 
     FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm2 -> Eps
 
FeynCalc`EpsEvaluate`Private`epsEvalLinearity[
     FeynCalc`EpsEvaluate`Private`a___, (FeynCalc`EpsEvaluate`Private`b_)*
      (FeynCalc`EpsEvaluate`Private`c:(LorentzIndex | ExplicitLorentzIndex | 
         Momentum | CartesianIndex | CartesianMomentum | TemporalMomentum)[
        __]), FeynCalc`EpsEvaluate`Private`d___] := 
    FeynCalc`EpsEvaluate`Private`b*
     FeynCalc`EpsEvaluate`Private`epsEvalLinearity[
      FeynCalc`EpsEvaluate`Private`a, FeynCalc`EpsEvaluate`Private`c, 
      FeynCalc`EpsEvaluate`Private`d]
 
FeynCalc`EpsEvaluate`Private`epsEvalLinearity[___, 0, ___] := 0
 
FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm[
     FeynCalc`EpsEvaluate`Private`x__] := 
    0 /; Signature[{FeynCalc`EpsEvaluate`Private`x}] === 0 && 
      MemberQ[{3, 4}, Length[{FeynCalc`EpsEvaluate`Private`x}]]
 
FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm[
     FeynCalc`EpsEvaluate`Private`x__] := 
    Signature[{FeynCalc`EpsEvaluate`Private`x}]*
      FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm @@ 
       Sort[{FeynCalc`EpsEvaluate`Private`x}] /; 
      !OrderedQ[{FeynCalc`EpsEvaluate`Private`x}] && 
      MemberQ[{3, 4}, Length[{FeynCalc`EpsEvaluate`Private`x}]]
 
FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm2[
     FeynCalc`EpsEvaluate`Private`x___, ExplicitLorentzIndex[0], 
     FeynCalc`EpsEvaluate`Private`y__] := 
    (-1)^Length[{FeynCalc`EpsEvaluate`Private`y}]*
     FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm2[
      FeynCalc`EpsEvaluate`Private`x, FeynCalc`EpsEvaluate`Private`y, 
      ExplicitLorentzIndex[0]]
 
FeynCalc`EpsEvaluate`Private`epsEvalMomCombine[
     FeynCalc`EpsEvaluate`Private`a_, FeynCalc`EpsEvaluate`Private`b_, 
     FeynCalc`EpsEvaluate`Private`c__] := 
    Expand /@ Distribute[MomentumCombine[DOT[FeynCalc`EpsEvaluate`Private`a, 
            FeynCalc`EpsEvaluate`Private`b, 
            FeynCalc`EpsEvaluate`Private`c]]] /. 
        DOT -> FeynCalc`EpsEvaluate`Private`epsEvalLinearity /. 
       FeynCalc`EpsEvaluate`Private`epsEvalLinearity -> 
        FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm /. 
      FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm -> 
       FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm2 /. 
     FeynCalc`EpsEvaluate`Private`epsEvalAntiSymm2 -> Eps
 
MomentumCombine[FeynCalc`MomentumCombine`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`MomentumCombine`Private`ex, 
      FeynCalc`MomentumCombine`Private`res, 
      FeynCalc`MomentumCombine`Private`rules, 
      FeynCalc`MomentumCombine`Private`optFactoring, 
      FeynCalc`MomentumCombine`Private`moms, 
      FeynCalc`MomentumCombine`Private`momsFac, 
      FeynCalc`MomentumCombine`Private`optSelect, 
      FeynCalc`MomentumCombine`Private`mcVerbose, 
      FeynCalc`MomentumCombine`Private`time, 
      FeynCalc`MomentumCombine`Private`optExcept, 
      FeynCalc`MomentumCombine`Private`optExcludeScalarProducts, 
      FeynCalc`MomentumCombine`Private`optQuadratic, 
      FeynCalc`MomentumCombine`Private`optNumberQ}, 
     FeynCalc`MomentumCombine`Private`optNumberQ = OptionValue[NumberQ]; 
      FeynCalc`MomentumCombine`Private`optQuadratic = 
       OptionValue["Quadratic"]; 
      FeynCalc`MomentumCombine`Private`optExcludeScalarProducts = 
       OptionValue["ExcludeScalarProducts"]; 
      FeynCalc`MomentumCombine`Private`optExcept = OptionValue[Except]; 
      FeynCalc`MomentumCombine`Private`optFactoring = OptionValue[Factoring]; 
      FeynCalc`MomentumCombine`Private`optSelect = OptionValue[Select]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`MomentumCombine`Private`mcVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`MomentumCombine`Private`mcVerbose = OptionValue[
           FCVerbose]]; ]; FCPrint[1, "MomentumCombine: Entering.", 
       FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
      FCPrint[3, "MomentumCombine: Entering with ", 
       FeynCalc`MomentumCombine`Private`expr, FCDoControl -> 
        FeynCalc`MomentumCombine`Private`mcVerbose]; 
      FeynCalc`MomentumCombine`Private`time = AbsoluteTime[]; 
      FCPrint[1, "MomentumCombine: Applying FCI.", FCDoControl -> 
        FeynCalc`MomentumCombine`Private`mcVerbose]; 
      If[OptionValue[FCI], FeynCalc`MomentumCombine`Private`ex = 
        FeynCalc`MomentumCombine`Private`expr, 
       FeynCalc`MomentumCombine`Private`ex = 
        FCI[FeynCalc`MomentumCombine`Private`expr]]; 
      FCPrint[1, "MomentumCombine: Done applying FCI, timing: ", 
       N[AbsoluteTime[] - FeynCalc`MomentumCombine`Private`time, 4], 
       FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
      If[Head[FeynCalc`MomentumCombine`Private`expr] =!= List, 
       FeynCalc`MomentumCombine`Private`ex = 
        {FeynCalc`MomentumCombine`Private`ex}]; 
      If[LeafCount[FeynCalc`MomentumCombine`Private`ex] < 
        OptionValue[LeafCount], 
       FCPrint[1, 
         "MomentumCombine: Leaving due to the LeafCount being too small.", 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
        If[Head[FeynCalc`MomentumCombine`Private`expr] =!= List, 
         Return[First[FeynCalc`MomentumCombine`Private`ex]], 
         Return[FeynCalc`MomentumCombine`Private`ex]]; ]; 
      FeynCalc`MomentumCombine`Private`time = AbsoluteTime[]; 
      FCPrint[1, "MomentumCombine: Building up the ruleset.", 
       FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
      FeynCalc`MomentumCombine`Private`rules = 
       FeynCalc`MomentumCombine`Private`rulesMain[
        FeynCalc`MomentumCombine`Private`optNumberQ]; 
      If[OptionValue[FV], FeynCalc`MomentumCombine`Private`rules = 
        Join[FeynCalc`MomentumCombine`Private`rules, 
         FeynCalc`MomentumCombine`Private`rulesFV[
          FeynCalc`MomentumCombine`Private`optExcept]]]; 
      If[OptionValue[SP], FeynCalc`MomentumCombine`Private`rules = 
        Join[FeynCalc`MomentumCombine`Private`rules, 
         FeynCalc`MomentumCombine`Private`rulesSP[
          FeynCalc`MomentumCombine`Private`optQuadratic, 
          FeynCalc`MomentumCombine`Private`optExcept, 
          FeynCalc`MomentumCombine`Private`optExcludeScalarProducts, 
          FeynCalc`MomentumCombine`Private`optNumberQ]]]; 
      If[OptionValue[LC], FeynCalc`MomentumCombine`Private`rules = 
        Join[FeynCalc`MomentumCombine`Private`rules, 
         FeynCalc`MomentumCombine`Private`rulesLC]]; 
      FCPrint[1, "MomentumCombine: Done building up the ruleset, timing: ", 
       N[AbsoluteTime[] - FeynCalc`MomentumCombine`Private`time, 4], 
       FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
      If[FeynCalc`MomentumCombine`Private`optSelect =!= {}, 
       FeynCalc`MomentumCombine`Private`time = AbsoluteTime[]; 
        FCPrint[1, "MomentumCombine: Evaluating the Select option.", 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
        FeynCalc`MomentumCombine`Private`ex = 
         Fold[#1 //. FeynCalc`MomentumCombine`Private`rulesSpecificSP[#2, 
             FeynCalc`MomentumCombine`Private`optQuadratic, 
             FeynCalc`MomentumCombine`Private`optExcept, 
             FeynCalc`MomentumCombine`Private`optExcludeScalarProducts, 
             FeynCalc`MomentumCombine`Private`optNumberQ] & , 
          FeynCalc`MomentumCombine`Private`ex, 
          FeynCalc`MomentumCombine`Private`optSelect]; 
        If[FeynCalc`MomentumCombine`Private`optFactoring =!= False, 
         FeynCalc`MomentumCombine`Private`moms = 
           Cases2[FeynCalc`MomentumCombine`Private`ex, Momentum]; 
          FeynCalc`MomentumCombine`Private`momsFac = 
           FeynCalc`MomentumCombine`Private`moms /. 
            Momentum[FeynCalc`MomentumCombine`Private`a_, 
              FeynCalc`MomentumCombine`Private`dim___] :> 
             Momentum[FeynCalc`MomentumCombine`Private`optFactoring[
               FeynCalc`MomentumCombine`Private`a], 
              FeynCalc`MomentumCombine`Private`dim]; 
          FeynCalc`MomentumCombine`Private`ex = 
           FeynCalc`MomentumCombine`Private`ex /. Dispatch[
             Thread[FeynCalc`MomentumCombine`Private`moms -> 
               FeynCalc`MomentumCombine`Private`momsFac]]]; 
        FCPrint[1, 
         "MomentumCombine: Done evaluating the select option, timing: ", 
         N[AbsoluteTime[] - FeynCalc`MomentumCombine`Private`time, 4], 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; ]; 
      FeynCalc`MomentumCombine`Private`time = AbsoluteTime[]; 
      If[$ParallelizeFeynCalc && OptionValue[FCParallelize] && 
        Length[FeynCalc`MomentumCombine`Private`ex] > 1, 
       FCPrint[1, "MomentumCombine: Applying the ruleset to the input \
expression in parallel.", FCDoControl -> 
          FeynCalc`MomentumCombine`Private`mcVerbose]; 
        With[{FeynCalc`MomentumCombine`Private`xxx = 
           FeynCalc`MomentumCombine`Private`rules}, ParallelEvaluate[
          FCParallelContext`MomentumCombine`rules = Dispatch[
             FeynCalc`MomentumCombine`Private`xxx]; , DistributedContexts -> 
           None]]; FeynCalc`MomentumCombine`Private`res = 
         ParallelMap[#1 //. FCParallelContext`MomentumCombine`rules & , 
          FeynCalc`MomentumCombine`Private`ex, DistributedContexts -> None, 
          Method -> "ItemsPerEvaluation" -> Ceiling[
             N[Length[FeynCalc`MomentumCombine`Private`ex]/$KernelCount]/
              10]], FCPrint[1, "MomentumCombine: Applying the ruleset to the \
input expression.", FCDoControl -> 
          FeynCalc`MomentumCombine`Private`mcVerbose]; 
        FeynCalc`MomentumCombine`Private`res = 
         FeynCalc`MomentumCombine`Private`ex //. Dispatch[
           FeynCalc`MomentumCombine`Private`rules]]; 
      FCPrint[1, "MomentumCombine: Done applying the ruleset to the input \
expression, timing: ", N[AbsoluteTime[] - 
         FeynCalc`MomentumCombine`Private`time, 4], 
       FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
      If[OptionValue[Complex] && 
         !FreeQ[FeynCalc`MomentumCombine`Private`res, Complex], 
       FeynCalc`MomentumCombine`Private`time = AbsoluteTime[]; 
        FCPrint[1, "MomentumCombine: Handling complex momenta.", 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
        FeynCalc`MomentumCombine`Private`res = 
         FeynCalc`MomentumCombine`Private`res /. 
          {(FeynCalc`MomentumCombine`Private`h:Momentum | CartesianMomentum | 
                TemporalMomentum)[FeynCalc`MomentumCombine`Private`a_, 
              FeynCalc`MomentumCombine`Private`dim___] /; 
              !FreeQ[FeynCalc`MomentumCombine`Private`a, Complex] :> 
            FeynCalc`MomentumCombine`Private`factorIm[
             FeynCalc`MomentumCombine`Private`h[
              FeynCalc`MomentumCombine`Private`a, 
              FeynCalc`MomentumCombine`Private`dim]]}; 
        FCPrint[1, 
         "MomentumCombine: Done handling complex momenta, timing: ", 
         N[AbsoluteTime[] - FeynCalc`MomentumCombine`Private`time, 4], 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; ]; 
      If[FeynCalc`MomentumCombine`Private`optFactoring =!= False, 
       FeynCalc`MomentumCombine`Private`time = AbsoluteTime[]; 
        FCPrint[1, "MomentumCombine: Factoring the arguments.", 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; 
        FeynCalc`MomentumCombine`Private`moms = 
         Cases2[FeynCalc`MomentumCombine`Private`res, Momentum]; 
        FeynCalc`MomentumCombine`Private`momsFac = 
         FeynCalc`MomentumCombine`Private`moms /. 
          Momentum[FeynCalc`MomentumCombine`Private`a_, 
            FeynCalc`MomentumCombine`Private`dim___] :> 
           Momentum[FeynCalc`MomentumCombine`Private`optFactoring[
             FeynCalc`MomentumCombine`Private`a], 
            FeynCalc`MomentumCombine`Private`dim]; 
        FeynCalc`MomentumCombine`Private`res = 
         FeynCalc`MomentumCombine`Private`res /. Dispatch[
           Thread[FeynCalc`MomentumCombine`Private`moms -> 
             FeynCalc`MomentumCombine`Private`momsFac]]; 
        FCPrint[1, "MomentumCombine: Done factoring the arguments, timing: ", 
         N[AbsoluteTime[] - FeynCalc`MomentumCombine`Private`time, 4], 
         FCDoControl -> FeynCalc`MomentumCombine`Private`mcVerbose]; ]; 
      If[OptionValue[FCE], FeynCalc`MomentumCombine`Private`res = 
        FCE[FeynCalc`MomentumCombine`Private`res]]; 
      If[Head[FeynCalc`MomentumCombine`Private`expr] =!= List, 
       FeynCalc`MomentumCombine`Private`res = 
        First[FeynCalc`MomentumCombine`Private`res]]; 
      FCPrint[1, "MomentumCombine: Leaving.", FCDoControl -> 
        FeynCalc`MomentumCombine`Private`mcVerbose]; 
      FCPrint[3, "MomentumCombine: Leaving with ", 
       FeynCalc`MomentumCombine`Private`expr, FCDoControl -> 
        FeynCalc`MomentumCombine`Private`mcVerbose]; 
      FeynCalc`MomentumCombine`Private`res]
 
Options[MomentumCombine] = {"ExcludeScalarProducts" -> {}, 
     "Quadratic" -> True, Complex -> True, Except -> {}, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCVerbose -> False, FV -> True, Factoring -> False, 
     FCParallelize -> False, LC -> True, LeafCount -> 1, NumberQ -> True, 
     Select -> {}, SP -> True}
 
MomentumCombine /: MomentumCombine::usage = "MomentumCombine[expr] is the \
inverse operation to MomentumExpand and\nExpandScalarProduct. MomentumCombine \
combines also Pairs.\nNotice, that MomentumCombine cannot complete squares. \
It can, however, bring\nexpressions containing scalar products to a suitable \
form that allows for a\nsquare completion using other means.\n\nThis function \
offers multiple options.\n\nThe option NumberQ (default is True) specifies \
whether one should only merge\nquantities with numerical prefactors or not. \
Setting it to False allows for\nsymbolic prefactors.\n\nSetting the option \
\"Quadratic\" to False (default is True) effectively means\nthat momenta \
squared will not be combined with anything else.\n\nWith the option \
\"ExcludeScalarProducts\" we can ensure that scalar products\ncontaining any \
of the momenta listed are not merged with anything else. So a.x\n+ a.y can be \
merged either if a contains no such momenta, or if both x and y\nare free of \
them.\n\nThe option Except forbids merging the listed momenta with anything \
else. It is\nmuch more restrictive than \"ExcludeScalarProducts\" that allows \
for merging\nterms linear in the listed momenta.\n\nThe option Select allows \
for gathering all terms linear in the given momenta\nbefore applying any \
other combining rules."
 
Factoring /: Factoring::usage = "Factoring is an option for Collect2, \
Contract and more functions. If set to\nTrue, the result will be factored, \
using Factor2. If set to any function f,\nthis function will be used."
 
FeynCalc`MomentumCombine`Private`rulesMain[
     FeynCalc`MomentumCombine`Private`optNumberQ_] := 
    {(FeynCalc`MomentumCombine`Private`n3_.)*
        Momentum[FeynCalc`MomentumCombine`Private`x_, 
         FeynCalc`MomentumCombine`Private`dim_:4] + 
       (FeynCalc`MomentumCombine`Private`n4_.)*
        Momentum[FeynCalc`MomentumCombine`Private`y_, 
         FeynCalc`MomentumCombine`Private`dim_:4] :> 
      Momentum[Expand[FeynCalc`MomentumCombine`Private`n3*
           FeynCalc`MomentumCombine`Private`x + 
          FeynCalc`MomentumCombine`Private`n4*
           FeynCalc`MomentumCombine`Private`y], 
        FeynCalc`MomentumCombine`Private`dim] /; 
       NumberQ[FeynCalc`MomentumCombine`Private`n3] && 
        NumberQ[FeynCalc`MomentumCombine`Private`n4], 
     (FeynCalc`MomentumCombine`Private`n3_.)*
        Momentum[FeynCalc`MomentumCombine`Private`x_, 
         FeynCalc`MomentumCombine`Private`dim_:4] + 
       (FeynCalc`MomentumCombine`Private`n4_.)*
        Momentum[FeynCalc`MomentumCombine`Private`y_, 
         FeynCalc`MomentumCombine`Private`dim_:4] :> 
      Momentum[Expand[FeynCalc`MomentumCombine`Private`n3*
           FeynCalc`MomentumCombine`Private`x + 
          FeynCalc`MomentumCombine`Private`n4*
           FeynCalc`MomentumCombine`Private`y], 
        FeynCalc`MomentumCombine`Private`dim] /; 
        !FeynCalc`MomentumCombine`Private`optNumberQ && 
        FreeQ2[{FeynCalc`MomentumCombine`Private`n3, 
          FeynCalc`MomentumCombine`Private`n4}, {Pair, CartesianPair, 
          TemporalPair, FeynAmpDenominator, DOT}], 
     (FeynCalc`MomentumCombine`Private`n3_.)*LightConePerpendicularComponent[
         Momentum[FeynCalc`MomentumCombine`Private`x_, 
          FeynCalc`MomentumCombine`Private`dim_:4], 
         FeynCalc`MomentumCombine`Private`n_, 
         FeynCalc`MomentumCombine`Private`nb_] + 
       (FeynCalc`MomentumCombine`Private`n4_.)*
        LightConePerpendicularComponent[Momentum[
          FeynCalc`MomentumCombine`Private`y_, 
          FeynCalc`MomentumCombine`Private`dim_:4], 
         FeynCalc`MomentumCombine`Private`n_, 
         FeynCalc`MomentumCombine`Private`nb_] :> 
      LightConePerpendicularComponent[Momentum[
         Expand[FeynCalc`MomentumCombine`Private`n3*
            FeynCalc`MomentumCombine`Private`x + 
