      If[ !MemberQ[$ScalarProducts, FeynCalc`ScalarProduct`Private`entry], 
       AppendTo[$ScalarProducts, FeynCalc`ScalarProduct`Private`entry]]; 
      FeynCalc`ScalarProduct`Private`setval]
 
Attributes[SPD] = {Orderless}
 
(SPD[FeynCalc`SharedObjects`Private`a_, FeynCalc`SharedObjects`Private`b_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
    ScalarProduct[FeynCalc`SharedObjects`Private`a, 
      FeynCalc`SharedObjects`Private`b, Dimension -> D, 
      SetDimensions -> {D}] = FeynCalc`SharedObjects`Private`c
 
(SPD[FeynCalc`SharedObjects`Private`a_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
