     FeynCalc`ScalarProduct`Private`c2*FeynCalc`ScalarProduct`Private`b, 
     FeynCalc`ScalarProduct`Private`n, FeynCalc`ScalarProduct`Private`nb]
 
(SPLRD[FeynCalc`SharedObjects`Private`a_, FeynCalc`SharedObjects`Private`b_, 
      FeynCalc`SharedObjects`Private`n_, 
      FeynCalc`SharedObjects`Private`nb_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
    ScalarProduct[LightConePerpendicularComponent[
       Momentum[FeynCalc`SharedObjects`Private`a, D], 
       Momentum[FeynCalc`SharedObjects`Private`n, D], 
       Momentum[FeynCalc`SharedObjects`Private`nb, D]], 
      LightConePerpendicularComponent[Momentum[
        FeynCalc`SharedObjects`Private`b, D], 
       Momentum[FeynCalc`SharedObjects`Private`n, D], 
       Momentum[FeynCalc`SharedObjects`Private`nb, D]]] = 
     FeynCalc`SharedObjects`Private`c
 
SPLRD[FeynCalc`SharedObjects`Private`a_] := 
    SPLRD[FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`a]
 
SPLRD[FeynCalc`SharedObjects`Private`a_, FeynCalc`SharedObjects`Private`n_, 
     FeynCalc`SharedObjects`Private`nb_] := 
    SPLRD[FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`a, 
     FeynCalc`SharedObjects`Private`n, FeynCalc`SharedObjects`Private`nb]
 
SPLRD[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y_, 
     FeynCalc`SharedObjects`Private`r___] := 
    SPLRD[FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`r] /; 
      !OrderedQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}]
 
SPLRD[0, __] := 0
 
SPLRD[_, 0, ___] := 0
 
SPLRD[FeynCalc`SharedObjects`Private`x_, 
     FeynCalc`SharedObjects`Private`y_] := 
    SPLRD[FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`y, 
     $FCDefaultLightconeVectorN, $FCDefaultLightconeVectorNB]
 
SPLRD /: MakeBoxes[SPLRD[FeynCalc`SharedObjectsTypesetting`Private`x_, 
       FeynCalc`SharedObjectsTypesetting`Private`y_, 
       FeynCalc`SharedObjectsTypesetting`Private`n_, 
       FeynCalc`SharedObjectsTypesetting`Private`nb_], TraditionalForm] := 
     ToBoxes[Pair[LightConePerpendicularComponent[
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`x, D], 
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`n, D], 
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`nb, D]], 
       LightConePerpendicularComponent[Momentum[
         FeynCalc`SharedObjectsTypesetting`Private`y, D], 
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`n, D], 
        Momentum[FeynCalc`SharedObjectsTypesetting`Private`nb, D]]], 
      TraditionalForm]
 
SPLRD /: SPLRD::usage = "SPLRD[p,q,n,nb] denotes the perpendicular component \
in the lightcone\ndecomposition of the scalar product $p \\cdot q$  along the \
vectors n and nb.\nIt corresponds to $(p \\cdot q)_{\\perp}$.\n\nIf one omits \
n and nb, the program will use default vectors specified \
via\n$FCDefaultLightconeVectorN and $FCDefaultLightconeVectorNB."
 
$ScalarProducts := {}
 
($ScalarProducts = FeynCalc`Private`val_) ^:= 
    (If[$ParallelizeFeynCalc && $KernelID === 0, 
      With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
        ParallelEvaluate[OwnValues[$ScalarProducts] = 
           {HoldPattern[$ScalarProducts] :> FeynCalc`Private`xxx}; , 
         DistributedContexts -> None]]; ]; 
     With[{FeynCalc`Private`xxx = FeynCalc`Private`val}, 
      OwnValues[$ScalarProducts] = {HoldPattern[$ScalarProducts] :> 
         FeynCalc`Private`xxx}]; FeynCalc`Private`val)
 
$ScalarProducts /: $ScalarProducts::usage = "$ScalarProducts contains a list \
of all vector pairs for which a scalar product\nvalue has been defined."
 
FCScalarProductsSynchronizedQ[OptionsPattern[]] := 
    Block[{FeynCalc`FCScalarProductsSynchronizedQ`Private`currentKernel, 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`parallelKernels, 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`res, 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose, 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`lensPK}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose = 
        $VeryVerbose, If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose = 
          OptionValue[FCVerbose]]; ]; FCPrint[1, 
       "FCScalarProductsSynchronizedQ: Comparing downvalues for Pair."*
         FCDoControl -> 
        FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose]; 
      If[$ParallelizeFeynCalc, 
       FeynCalc`FCScalarProductsSynchronizedQ`Private`res = 
        Catch[Join[
          (FeynCalc`FCScalarProductsSynchronizedQ`Private`compareValues[#1, 
             DownValues, 
             FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose] & ) \
/@ {Pair, CartesianPair, TemporalPair, ScalarProduct, CartesianScalarProduct, 
            SP, SPD, SPLR, SPLRD, SPE, CSP, CSPD, CSPE, TC, TemporalMomentum, 
            CartesianMomentum, LightConePerpendicularComponent}, 
          (FeynCalc`FCScalarProductsSynchronizedQ`Private`compareValues[#1, 
             UpValues, 
             FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose] & ) \
/@ {ScalarProduct, CartesianScalarProduct}]], 
       Message[FCScalarProductsSynchronizedQ::nokernels]; Return[True]]; 
      If[MatchQ[FeynCalc`FCScalarProductsSynchronizedQ`Private`res, 
        {True..}], FeynCalc`FCScalarProductsSynchronizedQ`Private`res = True, 
       FeynCalc`FCScalarProductsSynchronizedQ`Private`res = False]; 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`res]
 
Options[FCScalarProductsSynchronizedQ] = {FCVerbose -> False}
 
FCScalarProductsSynchronizedQ /: FCScalarProductsSynchronizedQ::nokernels = "\
FeynCalc is currently not in the parallel mode, so no checks are being done."
 
FCScalarProductsSynchronizedQ /: FCScalarProductsSynchronizedQ::usage = "FCSc\
alarProductsSynchronizedQ[] compares up and down values of scalar \
products\nand other kinematic-related symbols such as Momentum, \
CartesianMomentum, TC\netc.\nbetween the master kernel and the subkernels and \
returns True if all of them\nidentical.\n\nThis routine is only relevant in \
the parallel mode of FeynCalc. It helps to\navoid inconsistencies through \
definitions that were introduced before\nactivating the parallel mode and not \
correctly propagated to the subkernels"
 
FeynCalc`FCScalarProductsSynchronizedQ`Private`compareValues[
     FeynCalc`FCScalarProductsSynchronizedQ`Private`head_, 
     FeynCalc`FCScalarProductsSynchronizedQ`Private`vtype_, 
     FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose_] := 
    Block[{FeynCalc`FCScalarProductsSynchronizedQ`Private`currentKernel, 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`parallelKernels}, 
     FeynCalc`FCScalarProductsSynchronizedQ`Private`currentKernel = 
       FeynCalc`FCScalarProductsSynchronizedQ`Private`vtype[
        FeynCalc`FCScalarProductsSynchronizedQ`Private`head]; 
      FeynCalc`FCScalarProductsSynchronizedQ`Private`parallelKernels = 
       With[{FeynCalc`FCScalarProductsSynchronizedQ`Private`xxx = 
          FeynCalc`FCScalarProductsSynchronizedQ`Private`head, 
         FeynCalc`FCScalarProductsSynchronizedQ`Private`yyy = 
          FeynCalc`FCScalarProductsSynchronizedQ`Private`vtype}, 
        ParallelEvaluate[FeynCalc`FCScalarProductsSynchronizedQ`Private`yyy[
          FeynCalc`FCScalarProductsSynchronizedQ`Private`xxx], 
         DistributedContexts -> None]]; 
      Table[
       If[Length[
           FeynCalc`FCScalarProductsSynchronizedQ`Private`currentKernel] =!= 
          Length[
           FeynCalc`FCScalarProductsSynchronizedQ`Private`parallelKernels[[
            FeynCalc`FCScalarProductsSynchronizedQ`Private`i]]], 
         FCPrint[1, StringJoin["FCScalarProductsSynchronizedQ: Length \
missmatch between downvalues for ", ToString[
             FeynCalc`FCScalarProductsSynchronizedQ`Private`head], 
            " on the master kernel and the subkernel "], 
           FeynCalc`FCScalarProductsSynchronizedQ`Private`i, ": ", 
           Length[FeynCalc`FCScalarProductsSynchronizedQ`Private`currentKerne\
l], " vs ", Length[
            FeynCalc`FCScalarProductsSynchronizedQ`Private`parallelKernels[[
             FeynCalc`FCScalarProductsSynchronizedQ`Private`i]]], 
           FCDoControl -> 
            FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose]; 
          Throw[False]]; 
        If[FeynCalc`FCScalarProductsSynchronizedQ`Private`currentKernel =!= 
          FeynCalc`FCScalarProductsSynchronizedQ`Private`parallelKernels[[
           FeynCalc`FCScalarProductsSynchronizedQ`Private`i]], 
         FCPrint[1, StringJoin["FCScalarProductsSynchronizedQ: Value \
missmatch between downvalues for ", ToString[
             FeynCalc`FCScalarProductsSynchronizedQ`Private`head], 
            " on the master kernel and a subkernel."], FCDoControl -> 
            FeynCalc`FCScalarProductsSynchronizedQ`Private`spsVerbose]; 
          Throw[False]]; , {FeynCalc`FCScalarProductsSynchronizedQ`Private`i, 
        1, $KernelCount}]; True]
 
(CartesianScalarProduct[FeynCalc`ScalarProduct`Private`araw_, 
      FeynCalc`ScalarProduct`Private`c:OptionsPattern[]] = 
     FeynCalc`ScalarProduct`Private`z_) ^:= 
    CartesianScalarProduct[FeynCalc`ScalarProduct`Private`araw, 
      FeynCalc`ScalarProduct`Private`araw, 
      FeynCalc`ScalarProduct`Private`c] = FeynCalc`ScalarProduct`Private`z
 
(CartesianScalarProduct[FeynCalc`ScalarProduct`Private`araw_, 
      FeynCalc`ScalarProduct`Private`braw_, FeynCalc`ScalarProduct`Private`c:
       OptionsPattern[]] = FeynCalc`ScalarProduct`Private`z_) ^:= 
    Block[{FeynCalc`ScalarProduct`Private`dims, 
       FeynCalc`ScalarProduct`Private`setval, 
       FeynCalc`ScalarProduct`Private`cspVerbose}, 
      FeynCalc`ScalarProduct`Private`dims = OptionValue[
         CartesianScalarProduct, {FeynCalc`ScalarProduct`Private`c}, 
         SetDimensions]; If[OptionValue[CartesianScalarProduct, 
          {FeynCalc`ScalarProduct`Private`c}, FCVerbose] === False, 
        FeynCalc`ScalarProduct`Private`cspVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[CartesianScalarProduct, 
            {FeynCalc`ScalarProduct`Private`c}, FCVerbose], _Integer], 
          FeynCalc`ScalarProduct`Private`cspVerbose = OptionValue[
            CartesianScalarProduct, {FeynCalc`ScalarProduct`Private`c}, 
            FCVerbose]]; ]; If[$ParallelizeFeynCalc && 
         OptionValue[CartesianScalarProduct, 
          {FeynCalc`ScalarProduct`Private`c}, FCParallelize], 
        FCPrint[1, "CartesianScalarProduct: Setting Cartesian scalar product \
value on subkernels. ", FCDoControl -> 
           FeynCalc`ScalarProduct`Private`cspVerbose]; 
         With[{FeynCalc`ScalarProduct`Private`xxx = 
            FeynCalc`ScalarProduct`Private`dims, 
           FeynCalc`ScalarProduct`Private`yyy = 
            FeynCalc`ScalarProduct`Private`z}, ParallelEvaluate[
           FeynCalc`ScalarProduct`Private`setCartesianScalarProduct[
             FeynCalc`ScalarProduct`Private`araw, 
             FeynCalc`ScalarProduct`Private`braw, 
             FeynCalc`ScalarProduct`Private`yyy, 
             FeynCalc`ScalarProduct`Private`xxx, 
             FeynCalc`ScalarProduct`Private`cspVerbose]; , 
           DistributedContexts -> None]]; FCPrint[1, "CartesianScalarProduct: \
Done setting Cartesian scalar product value on subkernels. ", 
          FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]]; 
       FCPrint[1, "CartesianScalarProduct: Setting Cartesian scalar product \
value on the main kernel. ", FCDoControl -> 
         FeynCalc`ScalarProduct`Private`cspVerbose]; 
       FeynCalc`ScalarProduct`Private`setval = 
        FeynCalc`ScalarProduct`Private`setCartesianScalarProduct[
         FeynCalc`ScalarProduct`Private`araw, 
         FeynCalc`ScalarProduct`Private`braw, 
         FeynCalc`ScalarProduct`Private`z, 
         FeynCalc`ScalarProduct`Private`dims, 
         FeynCalc`ScalarProduct`Private`cspVerbose]; FCPrint[1, "CartesianSca\
larProduct: Done setting Cartesian scalar product value on the main kernel. "\
, FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
       FeynCalc`ScalarProduct`Private`setval] /; 
     FeynCalc`ScalarProduct`Private`araw =!= 0 && 
      FeynCalc`ScalarProduct`Private`braw =!= 0 && 
      FCPatternFreeQ[{FeynCalc`ScalarProduct`Private`araw, 
        FeynCalc`ScalarProduct`Private`braw}]
 
CartesianScalarProduct[FeynCalc`ScalarProduct`Private`a_, 
     FeynCalc`ScalarProduct`Private`b_, FeynCalc`ScalarProduct`Private`opts:
      OptionsPattern[]] := CartesianScalarProduct[
      FeynCalc`ScalarProduct`Private`b, FeynCalc`ScalarProduct`Private`a, 
      FeynCalc`ScalarProduct`Private`opts] /; 
      !OrderedQ[{FeynCalc`ScalarProduct`Private`a, 
        FeynCalc`ScalarProduct`Private`b}]
 
CartesianScalarProduct[FeynCalc`ScalarProduct`Private`x_, 
     FeynCalc`ScalarProduct`Private`opts:OptionsPattern[]] := 
    CartesianScalarProduct[FeynCalc`ScalarProduct`Private`x, 
     FeynCalc`ScalarProduct`Private`x, FeynCalc`ScalarProduct`Private`opts]
 
CartesianScalarProduct[FeynCalc`ScalarProduct`Private`a_, 
     FeynCalc`ScalarProduct`Private`b_, OptionsPattern[]] := 
    CartesianPair[CartesianMomentum[FeynCalc`ScalarProduct`Private`a, 
       OptionValue[Dimension]], CartesianMomentum[
       FeynCalc`ScalarProduct`Private`b, OptionValue[Dimension]]] /; 
     FreeQ[{FeynCalc`ScalarProduct`Private`a, 
        FeynCalc`ScalarProduct`Private`b}, CartesianMomentum] && 
      OptionValue[FCI]
 
CartesianScalarProduct /: MakeBoxes[CartesianScalarProduct[
       FeynCalc`ScalarProduct`Private`a_, FeynCalc`ScalarProduct`Private`b_, 
       FeynCalc`ScalarProduct`Private`opts:OptionsPattern[]], 
      TraditionalForm] := ToBoxes[FCI[CartesianScalarProduct[
         FeynCalc`ScalarProduct`Private`a, FeynCalc`ScalarProduct`Private`b, 
         FeynCalc`ScalarProduct`Private`opts]], TraditionalForm] /; 
       !OptionValue[CartesianScalarProduct, 
        {FeynCalc`ScalarProduct`Private`opts}, FCI]
 
Options[CartesianScalarProduct] = {Dimension -> 3, FeynCalcInternal -> True, 
     FCParallelize -> True, FCVerbose -> False, SetDimensions -> {3, -1 + D}}
 
CartesianScalarProduct /: CartesianScalarProduct::emptydim = "If you want to \
set scalar products via CartesianScalarProduct[a, b] = m^2, you must specify \
at least one dimension via the option SetDimensions->{dims...}! Evaluation \
aborted."
 
CartesianScalarProduct /: CartesianScalarProduct::fail = 
     "Something went wrong while setting scalar products! Evaluation \
aborted."
 
CartesianScalarProduct /: CartesianScalarProduct::usage = "CartesianScalarPro\
duct[p, q]  is the input for the scalar product of two\nCartesian vectors p \
and q.\n\nCartesianScalarProduct[p] is equivalent to \
CartesianScalarProduct[p, p].\n\nExpansion of sums of momenta in \
CartesianScalarProduct is done with\nExpandScalarProduct.\n\nScalar products \
may be set, e.g. via CartesianScalarProduct[a, b] = m^2; but a\nand b may not \
contain sums.\n\nCartesianScalarProduct[a] corresponds to \
CartesianScalarProduct[a,a]\n\nNote that ScalarProduct[a, b] = m^2 actually \
sets Cartesian scalar products in\ndifferent dimensions specified by the \
value of the SetDimensions option.\n\nIt is highly recommended to set \
CartesianScalarProducts before any\ncalculation. This improves the \
performance of FeynCalc."
 
FeynCalc`ScalarProduct`Private`setCartesianScalarProduct[
     FeynCalc`ScalarProduct`Private`araw_, 
     FeynCalc`ScalarProduct`Private`braw_, FeynCalc`ScalarProduct`Private`z_, 
     FeynCalc`ScalarProduct`Private`dims_, 
     FeynCalc`ScalarProduct`Private`cspVerbose_] := 
    Block[{FeynCalc`ScalarProduct`Private`downv, 
      FeynCalc`ScalarProduct`Private`cpair, 
      FeynCalc`ScalarProduct`Private`ruleClearCSP, 
      FeynCalc`ScalarProduct`Private`ruleClearCartesianPair, 
      FeynCalc`ScalarProduct`Private`a, FeynCalc`ScalarProduct`Private`b, 
      FeynCalc`ScalarProduct`Private`ruleClearFCECSP, 
      FeynCalc`ScalarProduct`Private`ruleClearFCECSPD, 
      FeynCalc`ScalarProduct`Private`ruleClearFCECSPE, 
      FeynCalc`ScalarProduct`Private`cspList, 
      FeynCalc`ScalarProduct`Private`cpairList, 
      FeynCalc`ScalarProduct`Private`fceList, 
      FeynCalc`ScalarProduct`Private`valsListOrig, 
      FeynCalc`ScalarProduct`Private`valsList, 
      FeynCalc`ScalarProduct`Private`slot, 
      FeynCalc`ScalarProduct`Private`setval, 
      FeynCalc`ScalarProduct`Private`dummy, 
      FeynCalc`ScalarProduct`Private`tuples, 
      FeynCalc`ScalarProduct`Private`hp, FeynCalc`ScalarProduct`Private`cpr, 
      FeynCalc`ScalarProduct`Private`csp, 
      FeynCalc`ScalarProduct`Private`entry, 
      FeynCalc`ScalarProduct`Private`ruleClearCartesianMomentum, 
      FeynCalc`ScalarProduct`Private`cmomList}, 
     {FeynCalc`ScalarProduct`Private`a, FeynCalc`ScalarProduct`Private`b} = 
       Sort[{FeynCalc`ScalarProduct`Private`araw, 
         FeynCalc`ScalarProduct`Private`braw}]; 
      FeynCalc`ScalarProduct`Private`tuples = 
       {{FeynCalc`ScalarProduct`Private`a/NumericalFactor[
           FeynCalc`ScalarProduct`Private`a], 
         Expand[FeynCalc`ScalarProduct`Private`a/NumericalFactor[
            FeynCalc`ScalarProduct`Private`a]], 
         Expand[-(FeynCalc`ScalarProduct`Private`a/NumericalFactor[
             FeynCalc`ScalarProduct`Private`a])]}, 
        {FeynCalc`ScalarProduct`Private`b/NumericalFactor[
           FeynCalc`ScalarProduct`Private`b], 
         Expand[FeynCalc`ScalarProduct`Private`b/NumericalFactor[
            FeynCalc`ScalarProduct`Private`b]], 
         Expand[-(FeynCalc`ScalarProduct`Private`b/NumericalFactor[
             FeynCalc`ScalarProduct`Private`b])]}}; 
      FeynCalc`ScalarProduct`Private`valsListOrig = 
       {FeynCalc`ScalarProduct`Private`setval, 
        FeynCalc`ScalarProduct`Private`setval, 
        -FeynCalc`ScalarProduct`Private`setval, 
        FeynCalc`ScalarProduct`Private`setval, 
        FeynCalc`ScalarProduct`Private`setval, 
        -FeynCalc`ScalarProduct`Private`setval, 
        -FeynCalc`ScalarProduct`Private`setval, 
        -FeynCalc`ScalarProduct`Private`setval, 
        FeynCalc`ScalarProduct`Private`setval}; 
      FeynCalc`ScalarProduct`Private`setval = 
       FCI[FeynCalc`ScalarProduct`Private`z]/
        (NumericalFactor[FeynCalc`ScalarProduct`Private`a]*
         NumericalFactor[FeynCalc`ScalarProduct`Private`b]); 
      If[FeynCalc`ScalarProduct`Private`dims === {}, 
       Message[CartesianScalarProduct::emptydim]; Abort[]]; 
      FeynCalc`ScalarProduct`Private`cspList = 
       Flatten[(Flatten[Outer[HoldPattern[FeynCalc`ScalarProduct`Private`csp[
                   #1, #2, FeynCalc`ScalarProduct`Private`dummy[Dimension, 
                    FeynCalc`ScalarProduct`Private`slot]]] & , Sequence @@ 
                 FeynCalc`ScalarProduct`Private`tuples]] /. 
              FeynCalc`ScalarProduct`Private`slot -> #1 & ) /@ 
            FeynCalc`ScalarProduct`Private`dims /. 
           FeynCalc`ScalarProduct`Private`dummy -> Rule] /. 
         FeynCalc`ScalarProduct`Private`csp[
           FeynCalc`ScalarProduct`Private`j__, Dimension -> 3] :> 
          FeynCalc`ScalarProduct`Private`csp[
           FeynCalc`ScalarProduct`Private`j] /. 
        FeynCalc`ScalarProduct`Private`csp -> CartesianScalarProduct; 
      FeynCalc`ScalarProduct`Private`cpairList = 
       Flatten[(Flatten[Outer[FeynCalc`ScalarProduct`Private`hp[
                FeynCalc`ScalarProduct`Private`cpair[CartesianMomentum[#1, 
                  FeynCalc`ScalarProduct`Private`slot], CartesianMomentum[#2, 
                  FeynCalc`ScalarProduct`Private`slot]]] & , 
              Sequence @@ FeynCalc`ScalarProduct`Private`tuples]] /. 
            FeynCalc`ScalarProduct`Private`slot -> #1 & ) /@ 
          FeynCalc`ScalarProduct`Private`dims] /. 
        FeynCalc`ScalarProduct`Private`hp -> HoldPattern; 
      FeynCalc`ScalarProduct`Private`fceList = 
       Flatten[Outer[HoldPattern[FeynCalc`ScalarProduct`Private`cpair[#1, 
            #2]] & , Sequence @@ FeynCalc`ScalarProduct`Private`tuples]]; 
      FeynCalc`ScalarProduct`Private`cmomList = 
       DeleteDuplicates[Flatten[((FeynCalc`ScalarProduct`Private`dummy[
                 FeynCalc`ScalarProduct`Private`hp[
                  FeynCalc`ScalarProduct`Private`cm[#1, 
                   FeynCalc`ScalarProduct`Private`slot]], 0] & ) /@ 
               FeynCalc`ScalarProduct`Private`tuples[[1]] /. 
              FeynCalc`ScalarProduct`Private`slot -> #1 & ) /@ 
            FeynCalc`ScalarProduct`Private`dims]] /. 
         FeynCalc`ScalarProduct`Private`cm[FeynCalc`ScalarProduct`Private`x_, 
           3] :> FeynCalc`ScalarProduct`Private`cm[
           FeynCalc`ScalarProduct`Private`x] /. 
        FeynCalc`ScalarProduct`Private`hp -> HoldPattern; 
      FeynCalc`ScalarProduct`Private`valsList = 
       Flatten[Table[FeynCalc`ScalarProduct`Private`valsListOrig, 
         {FeynCalc`ScalarProduct`Private`i, 1, 
          Length[FeynCalc`ScalarProduct`Private`dims]}]]; 
      If[Length[FeynCalc`ScalarProduct`Private`cspList] =!= 
         Length[FeynCalc`ScalarProduct`Private`cpairList] || 
        Length[FeynCalc`ScalarProduct`Private`cspList] =!= 
         Length[FeynCalc`ScalarProduct`Private`valsList], 
       Message[CartesianScalarProduct::fail]; Abort[]]; 
      FeynCalc`ScalarProduct`Private`ruleClearCSP = DeleteDuplicates[
        Flatten[(Flatten[Outer[FeynCalc`ScalarProduct`Private`dummy[
                    HoldPattern[FeynCalc`ScalarProduct`Private`csp[#1, #2, 
                      Dimension -> FeynCalc`ScalarProduct`Private`slot]], 
                    FeynCalc`ScalarProduct`Private`cpair[#1, #2, Dimension -> 
                      FeynCalc`ScalarProduct`Private`slot]] & , Sequence @@ 
                   FeynCalc`ScalarProduct`Private`tuples]] /. 
                FeynCalc`ScalarProduct`Private`slot -> #1 & ) /@ 
              FeynCalc`ScalarProduct`Private`dims /. 
             FeynCalc`ScalarProduct`Private`cpair -> 
              CartesianScalarProduct /. 
            FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed /. 
           FeynCalc`ScalarProduct`Private`csp[
             FeynCalc`ScalarProduct`Private`j__, Dimension -> 3] :> 
            FeynCalc`ScalarProduct`Private`csp[
             FeynCalc`ScalarProduct`Private`j] /. 
          FeynCalc`ScalarProduct`Private`csp -> CartesianScalarProduct]]; 
      FeynCalc`ScalarProduct`Private`ruleClearCartesianPair = 
       DeleteDuplicates[Flatten[
           (Flatten[Outer[FeynCalc`ScalarProduct`Private`dummy[
                    FeynCalc`ScalarProduct`Private`hp[
                     FeynCalc`ScalarProduct`Private`cpr[CartesianMomentum[#1, 
                       FeynCalc`ScalarProduct`Private`slot], 
                      CartesianMomentum[#2, 
                       FeynCalc`ScalarProduct`Private`slot]]], 
                    FeynCalc`ScalarProduct`Private`cpair[#1, #2, Dimension -> 
                      FeynCalc`ScalarProduct`Private`slot]] & , Sequence @@ 
                   FeynCalc`ScalarProduct`Private`tuples]] /. 
                FeynCalc`ScalarProduct`Private`slot -> #1 & ) /@ 
              FeynCalc`ScalarProduct`Private`dims /. 
             FeynCalc`ScalarProduct`Private`cpair -> 
              CartesianScalarProduct /. 
            FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed]] /. 
         FeynCalc`ScalarProduct`Private`hp -> HoldPattern /. 
        FeynCalc`ScalarProduct`Private`cpr -> CartesianPair; 
      If[FeynCalc`ScalarProduct`Private`setval === 0 && 
        FeynCalc`ScalarProduct`Private`a === 
         FeynCalc`ScalarProduct`Private`b, 
       FeynCalc`ScalarProduct`Private`ruleClearCartesianMomentum = 
         DeleteDuplicates[Flatten[(Flatten[Outer[
                     FeynCalc`ScalarProduct`Private`dummy[
                       FeynCalc`ScalarProduct`Private`hp[
                        FeynCalc`ScalarProduct`Private`cm[#1, 
                         FeynCalc`ScalarProduct`Private`slot]], 
                       CartesianMomentum[#1, 
                        FeynCalc`ScalarProduct`Private`slot]] & , Sequence @@ 
                      FeynCalc`ScalarProduct`Private`tuples]] /. 
                   FeynCalc`ScalarProduct`Private`slot -> #1 & ) /@ 
                 FeynCalc`ScalarProduct`Private`dims /. 
                FeynCalc`ScalarProduct`Private`cpair -> 
                 CartesianScalarProduct /. 
               FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed]] /. 
            FeynCalc`ScalarProduct`Private`cm[
              FeynCalc`ScalarProduct`Private`x_, 3] :> 
             FeynCalc`ScalarProduct`Private`cm[
              FeynCalc`ScalarProduct`Private`x] /. 
           FeynCalc`ScalarProduct`Private`hp -> HoldPattern /. 
          FeynCalc`ScalarProduct`Private`cm -> CartesianMomentum; ]; 
      FeynCalc`ScalarProduct`Private`ruleClearFCECSP = 
       DeleteDuplicates[Flatten[
         Outer[FeynCalc`ScalarProduct`Private`dummy[HoldPattern[CSP[#1, #2]], 
               FeynCalc`ScalarProduct`Private`cpair[#1, #2, Dimension -> 
                 3]] & , Sequence @@ 
              FeynCalc`ScalarProduct`Private`tuples] /. 
            FeynCalc`ScalarProduct`Private`slot -> #1 /. 
           FeynCalc`ScalarProduct`Private`cpair -> CartesianScalarProduct /. 
          FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed]]; 
      FeynCalc`ScalarProduct`Private`ruleClearFCECSPD = 
       DeleteDuplicates[Flatten[
         Outer[FeynCalc`ScalarProduct`Private`dummy[HoldPattern[
                CSPD[#1, #2]], FeynCalc`ScalarProduct`Private`cpair[#1, #2, 
                Dimension -> D - 1]] & , Sequence @@ 
              FeynCalc`ScalarProduct`Private`tuples] /. 
            FeynCalc`ScalarProduct`Private`slot -> #1 /. 
           FeynCalc`ScalarProduct`Private`cpair -> CartesianScalarProduct /. 
          FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed]]; 
      FeynCalc`ScalarProduct`Private`ruleClearFCECSPE = 
       DeleteDuplicates[Flatten[
         Outer[FeynCalc`ScalarProduct`Private`dummy[HoldPattern[
                CSPE[#1, #2]], FeynCalc`ScalarProduct`Private`cpair[#1, #2, 
                Dimension -> D - 4]] & , Sequence @@ 
              FeynCalc`ScalarProduct`Private`tuples] /. 
            FeynCalc`ScalarProduct`Private`slot -> #1 /. 
           FeynCalc`ScalarProduct`Private`cpair -> CartesianScalarProduct /. 
          FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed]]; 
      If[(FeynCalc`ScalarProduct`Private`cspList /. HoldPattern -> 
            Identity /. CartesianPair -> 
           FeynCalc`ScalarProduct`Private`cpair) =!= 
         FeynCalc`ScalarProduct`Private`cpairList /. HoldPattern -> Identity, 
       FCPrint[1, "CartesianScalarProduct: Removing old values for Cartesian \
scalar product of ", {FeynCalc`ScalarProduct`Private`a, 
          FeynCalc`ScalarProduct`Private`b}, " and it variations ", 
         FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
        FeynCalc`ScalarProduct`Private`downv = DownValues[
          CartesianScalarProduct]; FeynCalc`ScalarProduct`Private`downv = 
         Complement[FeynCalc`ScalarProduct`Private`downv, 
          FeynCalc`ScalarProduct`Private`ruleClearCSP]; 
        DownValues[CartesianScalarProduct] = 
         FeynCalc`ScalarProduct`Private`downv; 
        FeynCalc`ScalarProduct`Private`downv = DownValues[CartesianPair]; 
        FeynCalc`ScalarProduct`Private`downv = Complement[
          FeynCalc`ScalarProduct`Private`downv, 
          FeynCalc`ScalarProduct`Private`ruleClearCartesianPair]; 
        DownValues[CartesianPair] = FeynCalc`ScalarProduct`Private`downv; 
        If[ !FreeQ[FeynCalc`ScalarProduct`Private`dims, 3], 
         FeynCalc`ScalarProduct`Private`downv = DownValues[CSP]; 
          FeynCalc`ScalarProduct`Private`downv = Complement[
            FeynCalc`ScalarProduct`Private`downv, 
            FeynCalc`ScalarProduct`Private`ruleClearFCECSP]; 
          DownValues[CSP] = FeynCalc`ScalarProduct`Private`downv]; 
        If[ !FreeQ[FeynCalc`ScalarProduct`Private`dims, D - 1], 
         FeynCalc`ScalarProduct`Private`downv = DownValues[CSPD]; 
          FeynCalc`ScalarProduct`Private`downv = Complement[
            FeynCalc`ScalarProduct`Private`downv, 
            FeynCalc`ScalarProduct`Private`ruleClearFCECSPD]; 
          DownValues[CSPD] = FeynCalc`ScalarProduct`Private`downv; ]; 
        FeynCalc`ScalarProduct`Private`downv = DownValues[CSPE]; 
        If[ !FreeQ[FeynCalc`ScalarProduct`Private`dims, D - 4], 
         FeynCalc`ScalarProduct`Private`downv = Complement[
            FeynCalc`ScalarProduct`Private`downv, 
            FeynCalc`ScalarProduct`Private`ruleClearFCECSPE]; 
          DownValues[CSPE] = FeynCalc`ScalarProduct`Private`downv; ]; 
        If[FeynCalc`ScalarProduct`Private`setval === 0 && 
          FeynCalc`ScalarProduct`Private`a === 
           FeynCalc`ScalarProduct`Private`b, 
         FeynCalc`ScalarProduct`Private`downv = DownValues[
            CartesianMomentum]; FeynCalc`ScalarProduct`Private`downv = 
           Complement[FeynCalc`ScalarProduct`Private`downv, 
            FeynCalc`ScalarProduct`Private`ruleClearCartesianMomentum]; 
          DownValues[CartesianMomentum] = 
           FeynCalc`ScalarProduct`Private`downv; ]; FCPrint[3, "CartesianScal\
arProduct: Downvalues for CartesianScalarProduct after removal ", 
         DownValues[CartesianScalarProduct], FCDoControl -> 
          FeynCalc`ScalarProduct`Private`cspVerbose]; FCPrint[3, "CartesianSc\
alarProduct: Downvalues for CartesianPair after removal ", 
         DownValues[CartesianPair], FCDoControl -> 
          FeynCalc`ScalarProduct`Private`cspVerbose]; 
        FCPrint[3, "CartesianScalarProduct: Downvalues for CSP after removal \
", DownValues[CSP], FCDoControl -> 
          FeynCalc`ScalarProduct`Private`cspVerbose]; 
        FCPrint[3, 
         "CartesianScalarProduct: Downvalues for CSPD after removal ", 
         DownValues[CSPD], FCDoControl -> 
          FeynCalc`ScalarProduct`Private`cspVerbose]; 
        FCPrint[3, 
         "CartesianScalarProduct: Downvalues for CSPE after removal ", 
         DownValues[CSPE], FCDoControl -> 
          FeynCalc`ScalarProduct`Private`cspVerbose]; ]; 
      FCPrint[1, 
       "CartesianScalarProduct: Setting DownValues for \
CartesianScalarProduct", FCDoControl -> 
        FeynCalc`ScalarProduct`Private`cspVerbose]; 
      DownValues[CartesianScalarProduct] = 
       Join[DeleteDuplicates[Thread[FeynCalc`ScalarProduct`Private`dummy[
            FeynCalc`ScalarProduct`Private`cspList, 
            FeynCalc`ScalarProduct`Private`valsList]]] /. 
         FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed, 
        DownValues[CartesianScalarProduct]]; 
      FCPrint[1, 
       "CartesianScalarProduct: Setting DownValues for CartesianPair", 
       FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
      DownValues[CartesianPair] = 
       Join[DeleteDuplicates[Thread[FeynCalc`ScalarProduct`Private`dummy[
            FeynCalc`ScalarProduct`Private`cpairList /. 
             FeynCalc`ScalarProduct`Private`cpair -> CartesianPair, 
            FeynCalc`ScalarProduct`Private`valsList]]] /. 
         FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed, 
        DownValues[CartesianPair]]; FCPrint[1, 
       "CartesianScalarProduct: Setting DownValues for CSPD", 
       FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
      If[MemberQ[FeynCalc`ScalarProduct`Private`dims, D - 1], 
       DownValues[CSPD] = Join[DeleteDuplicates[
           Thread[FeynCalc`ScalarProduct`Private`dummy[
             FeynCalc`ScalarProduct`Private`fceList /. 
              FeynCalc`ScalarProduct`Private`cpair -> CSPD, 
             FeynCalc`ScalarProduct`Private`valsListOrig]]] /. 
          FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed, 
         DownValues[CSPD]]]; FCPrint[1, 
       "CartesianScalarProduct: Setting DownValues for CSPE", 
       FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
      If[MemberQ[FeynCalc`ScalarProduct`Private`dims, D - 4], 
       DownValues[CSPE] = Join[DeleteDuplicates[
           Thread[FeynCalc`ScalarProduct`Private`dummy[
             FeynCalc`ScalarProduct`Private`fceList /. 
              FeynCalc`ScalarProduct`Private`cpair -> CSPE, 
             FeynCalc`ScalarProduct`Private`valsListOrig]]] /. 
          FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed, 
         DownValues[CSPE]]]; FCPrint[1, 
       "CartesianScalarProduct: Setting DownValues for CSP", 
       FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
      If[MemberQ[FeynCalc`ScalarProduct`Private`dims, 3], 
       DownValues[CSP] = Join[DeleteDuplicates[
           Thread[FeynCalc`ScalarProduct`Private`dummy[
             FeynCalc`ScalarProduct`Private`fceList /. 
              FeynCalc`ScalarProduct`Private`cpair -> CSP, 
             FeynCalc`ScalarProduct`Private`valsListOrig]]] /. 
          FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed, 
         DownValues[CSP]]]; If[FeynCalc`ScalarProduct`Private`setval === 0 && 
        FeynCalc`ScalarProduct`Private`a === 
         FeynCalc`ScalarProduct`Private`b, 
       FCPrint[1, 
         "CartesianScalarProduct: Setting DownValues for CartesianMomentum", 
         FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
        DownValues[CartesianMomentum] = 
         Join[FeynCalc`ScalarProduct`Private`cmomList /. 
            FeynCalc`ScalarProduct`Private`cm -> CartesianMomentum /. 
           FeynCalc`ScalarProduct`Private`dummy -> RuleDelayed, 
          DownValues[CartesianMomentum]]; ]; FCPrint[1, "CartesianScalarProdu\
ct: Adding vectors to the list of set scalar products", 
       FCDoControl -> FeynCalc`ScalarProduct`Private`cspVerbose]; 
      FeynCalc`ScalarProduct`Private`entry = 
       Sort[{CartesianMomentum[FeynCalc`ScalarProduct`Private`araw], 
         CartesianMomentum[FeynCalc`ScalarProduct`Private`braw]}]; 
      If[ !MemberQ[$ScalarProducts, FeynCalc`ScalarProduct`Private`entry], 
       AppendTo[$ScalarProducts, FeynCalc`ScalarProduct`Private`entry]]; 
      If[$ParallelizeFeynCalc && $KernelID === 0, 
       If[ !FCScalarProductsSynchronizedQ[], 
        Message[ScalarProduct::notsync]]]; 
      FeynCalc`ScalarProduct`Private`setval]
 
Attributes[CSP] = {Orderless}
 
(CSP[FeynCalc`SharedObjects`Private`a_, FeynCalc`SharedObjects`Private`b_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
    CartesianScalarProduct[FeynCalc`SharedObjects`Private`a, 
      FeynCalc`SharedObjects`Private`b, Dimension -> 3, 
      SetDimensions -> {3}] = FeynCalc`SharedObjects`Private`c
 
(CSP[FeynCalc`SharedObjects`Private`a_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
    CartesianScalarProduct[FeynCalc`SharedObjects`Private`a, 
      FeynCalc`SharedObjects`Private`a, Dimension -> 3, 
      SetDimensions -> {3}] = FeynCalc`SharedObjects`Private`c
 
CSP[0, _] := 0
 
CSP[FeynCalc`SharedObjects`Private`a_] := 
    CSP[FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`a]
 
CSP /: MakeBoxes[CSP[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b_], TraditionalForm] := 
     ToBoxes[CartesianPair[CartesianMomentum[
        FeynCalc`SharedObjectsTypesetting`Private`a], 
       CartesianMomentum[FeynCalc`SharedObjectsTypesetting`Private`b]], 
      TraditionalForm]
 
CSP /: CSP::usage = "CSP[p, q] is the 3-dimensional scalar product of p with \
q and is transformed\ninto \
CartesianPair[CartesianMomentum[p],CartesianMomentum[q]] \
by\nFeynCalcInternal.\n\nCSP[p] is the same as CSP[p,p] ($=p^2$)."
 
Attributes[CSPD] = {Orderless}
 
(CSPD[FeynCalc`SharedObjects`Private`a_, FeynCalc`SharedObjects`Private`b_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
    CartesianScalarProduct[FeynCalc`SharedObjects`Private`a, 
      FeynCalc`SharedObjects`Private`b, Dimension -> D - 1, 
      SetDimensions -> {D - 1}] = FeynCalc`SharedObjects`Private`c
 
(CSPD[FeynCalc`SharedObjects`Private`a_] = 
     FeynCalc`SharedObjects`Private`c_) ^:= 
    CartesianScalarProduct[FeynCalc`SharedObjects`Private`a, 
      FeynCalc`SharedObjects`Private`a, Dimension -> D - 1, 
      SetDimensions -> {D - 1}] = FeynCalc`SharedObjects`Private`c
 
CSPD[0, _] := 0
 
