LC[FeynCalc`SharedObjects`Private`x___][
      FeynCalc`SharedObjects`Private`y___] /; 
     Length[{FeynCalc`SharedObjects`Private`x, 
         FeynCalc`SharedObjects`Private`y}] =!= 4 && 
      FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}] := Message[LC::argrx, 
     StringJoin["LC[", ToString[{FeynCalc`SharedObjects`Private`x}], "][", 
      ToString[{FeynCalc`SharedObjects`Private`y}], "]"], 
     Length[{FeynCalc`SharedObjects`Private`x, 
       FeynCalc`SharedObjects`Private`y}], 4]
 
LC[___, FeynCalc`SharedObjects`Private`mu_, ___, 
      FeynCalc`SharedObjects`Private`mu_, ___][___] := 0
 
LC[___][___, FeynCalc`SharedObjects`Private`p_, ___, 
     FeynCalc`SharedObjects`Private`p_, ___] := 0
 
LC[FeynCalc`SharedObjects`Private`x___] /; 
     Length[{FeynCalc`SharedObjects`Private`x}] > 4 && 
      FCPatternFreeQ[{FeynCalc`SharedObjects`Private`x}] := 
    Message[LC::argrx, StringJoin["LC[", 
      ToString[{FeynCalc`SharedObjects`Private`x}], "]"], 
     Length[{FeynCalc`SharedObjects`Private`x}], 4]
 
LC /: MakeBoxes[LC[FeynCalc`SharedObjectsTypesetting`Private`x___][
       FeynCalc`SharedObjectsTypesetting`Private`y___], TraditionalForm] := 
     ToBoxes[Eps[Sequence @@ LorentzIndex /@ 
          {FeynCalc`SharedObjectsTypesetting`Private`x}, 
        Sequence @@ Momentum /@ 
          {FeynCalc`SharedObjectsTypesetting`Private`y}], TraditionalForm] /; 
      Length[{FeynCalc`SharedObjectsTypesetting`Private`x, 
         FeynCalc`SharedObjectsTypesetting`Private`y}] === 4
 
LC /: MakeBoxes[LC[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b_, 
       FeynCalc`SharedObjectsTypesetting`Private`c_, 
       FeynCalc`SharedObjectsTypesetting`Private`d_], TraditionalForm] := 
     ToBoxes[Eps[LorentzIndex[FeynCalc`SharedObjectsTypesetting`Private`a], 
       LorentzIndex[FeynCalc`SharedObjectsTypesetting`Private`b], 
       LorentzIndex[FeynCalc`SharedObjectsTypesetting`Private`c], 
       LorentzIndex[FeynCalc`SharedObjectsTypesetting`Private`d]], 
      TraditionalForm]
 
LC /: LC::usage = "LC[m, n, r, s] evaluates to 4-dimensional $\\varepsilon^{m \
n r s}$ by virtue of\napplying FeynCalcInternal.\n\nLC[m,...][p, ...] \
evaluates to 4-dimensional $\\epsilon ^{m \\ldots \\mu\n\\ldots}p_{\\mu \
\\ldots}$ applying FeynCalcInternal.\n\nWhen some indices of a \
Levi-Civita-tensor are contracted with 4-vectors,\nFeynCalc suppresses \
explicit dummy indices by putting those vectors into the\ncorresponding index \
slots. For example,  $\\varepsilon^{p_1 p_2 p_3 p_4}$\n(accessible via \
LC[][p1,p2,p3,p4]) correspond to $\\varepsilon_{\\mu \\nu \\rho\n\\sigma} \
p_1^\\mu p_2^\\nu p_3^\\rho p_4^\\sigma$."
 
FeynCalc`MomentumCombine`Private`rulesLC = 
    {Eps[FeynCalc`MomentumCombine`Private`a___, 
         (FeynCalc`MomentumCombine`Private`h:CartesianMomentum | Momentum)[
          FeynCalc`MomentumCombine`Private`x_, 
          FeynCalc`MomentumCombine`Private`dim___], 
         FeynCalc`MomentumCombine`Private`b___]*
        (FeynCalc`MomentumCombine`Private`n3_.) + 
       Eps[FeynCalc`MomentumCombine`Private`a___, 
         (FeynCalc`MomentumCombine`Private`h:CartesianMomentum | Momentum)[
          FeynCalc`MomentumCombine`Private`y_, 
          FeynCalc`MomentumCombine`Private`dim___], 
         FeynCalc`MomentumCombine`Private`b___]*
        (FeynCalc`MomentumCombine`Private`n4_.) :> 
      Eps[FeynCalc`MomentumCombine`Private`a, 
        FeynCalc`MomentumCombine`Private`h[
         Expand[FeynCalc`MomentumCombine`Private`n3*
            FeynCalc`MomentumCombine`Private`x + 
           FeynCalc`MomentumCombine`Private`n4*
            FeynCalc`MomentumCombine`Private`y], 
         FeynCalc`MomentumCombine`Private`dim], 
        FeynCalc`MomentumCombine`Private`b] /; 
       NumberQ[FeynCalc`MomentumCombine`Private`n3] && 
        NumberQ[FeynCalc`MomentumCombine`Private`n4] && 
        FeynCalc`MomentumCombine`Private`n3 =!= 
         FeynCalc`MomentumCombine`Private`n4, 
     Eps[FeynCalc`MomentumCombine`Private`a___, 
         (FeynCalc`MomentumCombine`Private`h:CartesianMomentum | Momentum)[
          FeynCalc`MomentumCombine`Private`x_, 
          FeynCalc`MomentumCombine`Private`dim___], 
         FeynCalc`MomentumCombine`Private`b___]*
        (FeynCalc`MomentumCombine`Private`n3_.) + 
       Eps[FeynCalc`MomentumCombine`Private`a___, 
         (FeynCalc`MomentumCombine`Private`h:CartesianMomentum | Momentum)[
          FeynCalc`MomentumCombine`Private`y_, 
          FeynCalc`MomentumCombine`Private`dim___], 
         FeynCalc`MomentumCombine`Private`b___]*
        (FeynCalc`MomentumCombine`Private`n3_.) :> 
      FeynCalc`MomentumCombine`Private`n3*
       Eps[FeynCalc`MomentumCombine`Private`a, 
        FeynCalc`MomentumCombine`Private`h[
         Expand[FeynCalc`MomentumCombine`Private`x + 
           FeynCalc`MomentumCombine`Private`y], 
         FeynCalc`MomentumCombine`Private`dim], 
        FeynCalc`MomentumCombine`Private`b], 
     Eps[FeynCalc`MomentumCombine`Private`a___, 
         (FeynCalc`MomentumCombine`Private`h:CartesianMomentum | Momentum)[
          FeynCalc`MomentumCombine`Private`x_, 
          FeynCalc`MomentumCombine`Private`dim___], 
         FeynCalc`MomentumCombine`Private`b___]*
        (FeynCalc`MomentumCombine`Private`n3_.) - 
       Eps[FeynCalc`MomentumCombine`Private`a___, 
         (FeynCalc`MomentumCombine`Private`h:CartesianMomentum | Momentum)[
          FeynCalc`MomentumCombine`Private`y_, 
          FeynCalc`MomentumCombine`Private`dim___], 
         FeynCalc`MomentumCombine`Private`b___]*
        (FeynCalc`MomentumCombine`Private`n3_.) :> 
      FeynCalc`MomentumCombine`Private`n3*
       Eps[FeynCalc`MomentumCombine`Private`a, 
        FeynCalc`MomentumCombine`Private`h[
         Expand[FeynCalc`MomentumCombine`Private`x - 
           FeynCalc`MomentumCombine`Private`y], 
         FeynCalc`MomentumCombine`Private`dim], 
        FeynCalc`MomentumCombine`Private`b]}
 
FeynCalc`MomentumCombine`Private`rulesSpecificSP[
     FeynCalc`MomentumCombine`Private`chosenMom_, 
     FeynCalc`MomentumCombine`Private`optQuadratic_, 
     FeynCalc`MomentumCombine`Private`optExcept_, 
     FeynCalc`MomentumCombine`Private`optExcludeScalarProducts_, 
