FeynCalc`MomentumCombine`Private`factorIm[
     (FeynCalc`MomentumCombine`Private`h:Momentum | CartesianMomentum | 
        TemporalMomentum)[FeynCalc`MomentumCombine`Private`a_, 
      FeynCalc`MomentumCombine`Private`dim___]] := 
    FeynCalc`MomentumCombine`Private`h[
     Factor2[FeynCalc`MomentumCombine`Private`a /. 
        HoldPattern[Complex[FeynCalc`MomentumCombine`Private`b__]] -> 
         FeynCalc`MomentumCombine`Private`complex[
          FeynCalc`MomentumCombine`Private`b]] /. 
      FeynCalc`MomentumCombine`Private`im -> I, 
     FeynCalc`MomentumCombine`Private`dim]
 
FeynCalc`MomentumCombine`Private`complex[FeynCalc`MomentumCombine`Private`a_, 
     FeynCalc`MomentumCombine`Private`b_] := 
    FeynCalc`MomentumCombine`Private`a + FeynCalc`MomentumCombine`Private`im*
      FeynCalc`MomentumCombine`Private`b
 
FeynCalc`MomentumCombine`Private`im /: 
    FeynCalc`MomentumCombine`Private`im::usage = ""
 
FCE = FeynCalcExternal
 
FCE /: FCE::feynamp = "Warning! FeynAmpDenominator `1` contains momenta with \
different dimensions and thus cannot be converted to the FCE form."
 
FCE /: FCE::usage = "FCE[exp] translates exp from the internal FeynCalc \
representation to a short\nform.\n\nFCE is equivalent to FeynCalcExternal."
 
Attributes[FeynCalcExternal] = {HoldFirst}
 
FeynCalcExternal[FeynCalc`FeynCalcExternal`Private`x_, OptionsPattern[]] := 
    Block[{FeynCalc`FeynCalcExternal`Private`ru, 
      FeynCalc`FeynCalcExternal`Private`ti, 
      FeynCalc`FeynCalcExternal`Private`r, 
      FeynCalc`FeynCalcExternal`Private`vv, 
      FeynCalc`FeynCalcExternal`Private`rv, 
      FeynCalc`FeynCalcExternal`Private`optFinalSubstitutions, 
      FeynCalc`FeynCalcExternal`Private`revru}, 
     FeynCalc`FeynCalcExternal`Private`optFinalSubstitutions = 
       OptionValue[FinalSubstitutions]; 
      FeynCalc`FeynCalcExternal`Private`ru = 
       {DiracIndexDelta :> FeynCalc`FeynCalcExternal`Private`diracdelta, 
           DiracChain :> FeynCalc`FeynCalcExternal`Private`diracchain, 
           PauliIndexDelta :> FeynCalc`FeynCalcExternal`Private`paulidelta, 
           PauliChain :> FeynCalc`FeynCalcExternal`Private`paulichain, 
           PauliSigma :> FeynCalc`FeynCalcExternal`Private`sigmaback, 
           DiracGamma :> FeynCalc`FeynCalcExternal`Private`diracback, 
           DiracSigma :> FeynCalc`FeynCalcExternal`Private`dirsig, 
           Eps :> FeynCalc`FeynCalcExternal`Private`eps, 
           FeynAmpDenominator :> 
            FeynCalc`FeynCalcExternal`Private`feynampback, 
           Pair :> FeynCalc`FeynCalcExternal`Private`pairback, 
           CartesianPair :> FeynCalc`FeynCalcExternal`Private`cpairback, 
           TemporalPair :> FeynCalc`FeynCalcExternal`Private`tpairback, 
           SUND :> FeynCalc`FeynCalcExternal`Private`sundback, 
           SUNDelta :> FeynCalc`FeynCalcExternal`Private`sundeltanoi, 
           SUNFDelta :> FeynCalc`FeynCalcExternal`Private`sunfdeltanoi, 
           SUNF :> FeynCalc`FeynCalcExternal`Private`SUNFback, 
           SUNT :> FeynCalc`FeynCalcExternal`Private`suntback, 
           SUNTF :> FeynCalc`FeynCalcExternal`Private`suntfback, 
           SUNDeltaContract :> FeynCalc`FeynCalcExternal`Private`sundeltanoi, 
           SUNFDeltaContract :> 
            FeynCalc`FeynCalcExternal`Private`sunfdeltanoi, 
           ScalarProduct :> FeynCalc`FeynCalcExternal`Private`scalarmul} /. 
          LorentzIndex -> FeynCalc`FeynCalcExternal`Private`iDent /. 
         SUNIndex -> FeynCalc`FeynCalcExternal`Private`iDent /. 
        SUNFIndex -> FeynCalc`FeynCalcExternal`Private`iDent; 
      If[FeynCalc`FeynCalcExternal`Private`optFinalSubstitutions =!= {}, 
       FeynCalc`FeynCalcExternal`Private`ru = 
         Join[FeynCalc`FeynCalcExternal`Private`ru, 
          Flatten[
           FeynCalc`FeynCalcExternal`Private`optFinalSubstitutions]]; ]; 
      FeynCalc`FeynCalcExternal`Private`vv[
        FeynCalc`FeynCalcExternal`Private`x2_] := 
       Cases2[FeynCalc`FeynCalcExternal`Private`x2, 
        {DiracChain, DiracIndexDelta, PauliChain, PauliIndexDelta, 
          CartesianPair, DiracGamma, DiracSigma, Eps, FeynAmpDenominator, 
          Pair, PropagatorDenominator, PauliSigma, SUND, SUNDelta, SUNFDelta, 
          SUNF, SUNT, SUNTF, SUNDeltaContract, SUNFDeltaContract, 
          ScalarProduct, TemporalPair} /. 
         FeynCalc`FeynCalcExternal`Private`sequence -> Sequence]; 
      FeynCalc`FeynCalcExternal`Private`rv[
        FeynCalc`FeynCalcExternal`Private`x2_] := 
       FeynCalc`FeynCalcExternal`Private`x2 /. 
        Dispatch[(#1 -> (FeynCalc`FeynCalcExternal`Private`momentumCombine[
              #1] /. FeynCalc`FeynCalcExternal`Private`ru) & ) /@ 
          FeynCalc`FeynCalcExternal`Private`vv[
           FeynCalc`FeynCalcExternal`Private`x2]]; 
      FeynCalc`FeynCalcExternal`Private`revru = 
       Reverse /@ SelectFree[FeynCalc`FeynCalcExternal`Private`ru, Power]; 
      FeynCalc`FeynCalcExternal`Private`rv[
        FeynCalc`FeynCalcExternal`Private`x] /. 
       Dispatch[FeynCalc`FeynCalcExternal`Private`revru]]
 
Options[FeynCalcExternal] = {FinalSubstitutions -> {}}
 
FeynCalcExternal /: FeynCalcExternal::usage = "FeynCalcExternal[exp] \
translates exp from the internal FeynCalc representation\nto a shorthand \
form."
 
Attributes[DiracIndexDelta] = {Orderless}
 
DiracIndexDelta /: MakeBoxes[DiracIndexDelta[
       (FeynCalc`SharedObjectsTypesetting`Private`ind1:
         DiracIndex | ExplicitDiracIndex)[
        FeynCalc`SharedObjectsTypesetting`Private`i_], 
       (FeynCalc`SharedObjectsTypesetting`Private`ind2:
         DiracIndex | ExplicitDiracIndex)[
        FeynCalc`SharedObjectsTypesetting`Private`j_]], TraditionalForm] := 
     SubscriptBox["\[Delta]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`ind1[
        FeynCalc`SharedObjectsTypesetting`Private`i], 
       FeynCalc`SharedObjectsTypesetting`Private`ind2[
        FeynCalc`SharedObjectsTypesetting`Private`j]]]
 
DiracIndexDelta /: DiracIndexDelta::usage = "DiracIndexDelta[DiracIndex[i], \
DiracIndex[j]] is the Kronecker-delta in the\nDirac space with two explicit \
Dirac indices i and j."
 
DiracIndex[FeynCalc`SharedObjects`Private`i_Integer] := 
    ExplicitDiracIndex[FeynCalc`SharedObjects`Private`i]
 
DiracIndex /: MakeBoxes[DiracIndex[
       FeynCalc`SharedObjectsTypesetting`Private`p_], TraditionalForm] := 
     ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm]
 
DiracIndex /: DiracIndex::usage = "DiracIndex is the head of Dirac indices. \
The internal representation of a\nfour-dimensional spinorial index i is \
DiracIndex[i].\n\nIf the first argument is an integer, DiracIndex[i] turns \
into\nExplicitDiracIndex[i].\n\nDirac indices are the indices that denote the \
components of Dirac matrices or\nspinors. They should not be confused with \
the Lorentz indices attached to the\nDirac matrices. For example in the case \
of $\\gamma_{ij}^{\\mu}$,  $\\mu$ is a\nLorentz index, while $i$ and $j$ are \
Dirac (spinorial) indices."
 
Attributes[ExplicitDiracIndex] = {Constant}
 
ExplicitDiracIndex /: MakeBoxes[ExplicitDiracIndex[
       FeynCalc`SharedObjectsTypesetting`Private`p_], TraditionalForm] := 
     ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm]
 
ExplicitDiracIndex /: ExplicitDiracIndex::usage = "ExplicitDiracIndex[ind] is \
an explicit Dirac index, i.e., ind is an integer."
 
FeynCalc`FeynCalcExternal`Private`diracdelta[
     FeynCalc`FeynCalcExternal`Private`i_, 
     FeynCalc`FeynCalcExternal`Private`j_] := 
    DIDelta[FeynCalc`FeynCalcExternal`Private`i, 
      FeynCalc`FeynCalcExternal`Private`j] /. 
     DiracIndex | ExplicitDiracIndex -> 
      FeynCalc`FeynCalcExternal`Private`iDent
 
Attributes[DIDelta] = {Orderless}
 
DIDelta /: MakeBoxes[DIDelta[FeynCalc`SharedObjectsTypesetting`Private`i_, 
       FeynCalc`SharedObjectsTypesetting`Private`j_], TraditionalForm] := 
     SubscriptBox["\[Delta]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`i, 
       FeynCalc`SharedObjectsTypesetting`Private`j]]
 
DIDelta /: DIDelta::usage = "DIDelta[i, j] is the Kronecker-delta in the \
Dirac space.\n\nDIDelta[i,j] is transformed into \
DiracDelta[DiracIndex[i],DiracIndex[j]] by\nFeynCalcInternal."
 
FeynCalc`FeynCalcExternal`Private`iDent[FeynCalc`FeynCalcExternal`Private`a_, 
     ___] := FeynCalc`FeynCalcExternal`Private`a
 
DiracChain[0, __] := 0
 
DiracChain[_, 0] := 0
 
DiracChain[1, FeynCalc`SharedObjects`Private`i_Spinor, 
     FeynCalc`SharedObjects`Private`j:_DiracIndex | _ExplicitDiracIndex] := 
    DiracChain[FeynCalc`SharedObjects`Private`i, 
     FeynCalc`SharedObjects`Private`j]
 
DiracChain[FeynCalc`SharedObjects`Private`x_ /; 
       FeynCalc`SharedObjects`Private`x =!= 1, 
      FeynCalc`SharedObjects`Private`i_, 
      FeynCalc`SharedObjects`Private`j_] /; 
     FreeQ2[{FCI[FeynCalc`SharedObjects`Private`x]}, 
       FeynCalc`Package`DiracHeadsList] && FCPatternFreeQ[
       {FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`i, 
        FeynCalc`SharedObjects`Private`j}] := 
    FeynCalc`SharedObjects`Private`x*DiracChain[1, 
      FeynCalc`SharedObjects`Private`i, FeynCalc`SharedObjects`Private`j]
 
DiracChain[1, FeynCalc`SharedObjects`Private`a_Spinor, 
     FeynCalc`SharedObjects`Private`b_Spinor] := 
    DiracChain[FeynCalc`SharedObjects`Private`a, 
     FeynCalc`SharedObjects`Private`b]
 
DiracChain[(FeynCalc`SharedObjects`Private`b_Dot)*
      (FeynCalc`SharedObjects`Private`a_)?NumberQ, 
     FeynCalc`SharedObjects`Private`i_, FeynCalc`SharedObjects`Private`j_] := 
    FeynCalc`SharedObjects`Private`a*DiracChain[
      FeynCalc`SharedObjects`Private`b, FeynCalc`SharedObjects`Private`i, 
      FeynCalc`SharedObjects`Private`j]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorUBar | 
         _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _DiracIndex | _ExplicitDiracIndex], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`b, TraditionalForm], ".", 
        ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`a, 
         TraditionalForm], ")"}], 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _DiracIndex | _ExplicitDiracIndex, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], ".", 
        ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`b, 
         TraditionalForm], ")"}], 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorUBar | 
         _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`c:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     RowBox[{"(", ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`b, 
        TraditionalForm], ".", ToBoxes[
        FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], ".", 
       ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`c, TraditionalForm], 
       ")"}]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`ind1:
        _DiracIndex | _ExplicitDiracIndex, 
       FeynCalc`SharedObjectsTypesetting`Private`ind2:
        _DiracIndex | _ExplicitDiracIndex], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], 
        ")"}], TBox[FeynCalc`SharedObjectsTypesetting`Private`ind1, 
       FeynCalc`SharedObjectsTypesetting`Private`ind2]]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a:_Spinor | _SpinorUBar | 
         _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _DiracIndex | _ExplicitDiracIndex], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], 
        ")"}], TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _DiracIndex | _ExplicitDiracIndex, 
       FeynCalc`SharedObjectsTypesetting`Private`a:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], 
        ")"}], TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
DiracChain /: MakeBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a:_Spinor | _SpinorUBar | 
         _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     RowBox[{"(", ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`a, 
        TraditionalForm], ".", ToBoxes[
        FeynCalc`SharedObjectsTypesetting`Private`b, TraditionalForm], ")"}]
 
DiracChain /: DiracChain::usage = "DiracChain[x, i, j] denotes a chain of \
Dirac matrices x, where the Dirac\nindices i and j are explicit."
 
FeynCalc`Package`DiracHeadsList = {DiracGamma, Spinor, DiracSigma, 
     DiracChain, DiracIndexDelta, DiracTrace}
 
FeynCalc`FeynCalcExternal`Private`diracchain[
     FeynCalc`FeynCalcExternal`Private`a_, 
     FeynCalc`FeynCalcExternal`Private`b_] := 
    DCHN[FCE[FeynCalc`FeynCalcExternal`Private`a], 
      FeynCalc`FeynCalcExternal`Private`b] /. 
     DiracIndex | ExplicitDiracIndex -> 
      FeynCalc`FeynCalcExternal`Private`iDent
 
FeynCalc`FeynCalcExternal`Private`diracchain[
     FeynCalc`FeynCalcExternal`Private`a_, 
     FeynCalc`FeynCalcExternal`Private`b_, 
     FeynCalc`FeynCalcExternal`Private`c_] := 
    (FeynCalc`FeynCalcExternal`Private`fermtmp = 
      FCE[{FeynCalc`FeynCalcExternal`Private`a, 
        FeynCalc`FeynCalcExternal`Private`b, 
        FeynCalc`FeynCalcExternal`Private`c}]; 
     DCHN @@ FeynCalc`FeynCalcExternal`Private`fermtmp /. 
      DiracIndex | ExplicitDiracIndex -> 
       FeynCalc`FeynCalcExternal`Private`iDent)
 
DCHN[0, __] := 0
 
DCHN[_, 0] := 0
 
DCHN[1, FeynCalc`SharedObjects`Private`a_Spinor, 
     FeynCalc`SharedObjects`Private`b_Spinor] := 
    DCHN[FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`b]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorUBar | 
         _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`ind_ /; 
         !MemberQ[{Spinor, SpinorU, SpinorV, SpinorUD, SpinorVD, SpinorUBar, 
           SpinorVBar, SpinorUBarD, SpinorVBarD}, 
          Head[FeynCalc`SharedObjectsTypesetting`Private`ind]]], 
      TraditionalForm] := ToBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a, 
       FeynCalc`SharedObjectsTypesetting`Private`b, 
       DiracIndex[FeynCalc`SharedObjectsTypesetting`Private`ind]], 
      TraditionalForm]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`ind_ /; 
         !MemberQ[{Spinor, SpinorU, SpinorV, SpinorUD, SpinorVD, SpinorUBar, 
           SpinorVBar, SpinorUBarD, SpinorVBarD}, 
          Head[FeynCalc`SharedObjectsTypesetting`Private`ind]], 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     ToBoxes[DiracChain[FeynCalc`SharedObjectsTypesetting`Private`a, 
       DiracIndex[FeynCalc`SharedObjectsTypesetting`Private`ind], 
       FeynCalc`SharedObjectsTypesetting`Private`b], TraditionalForm]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorUBar | 
         _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`c:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     ToBoxes[DiracChain[FeynCalc`SharedObjectsTypesetting`Private`a, 
       FeynCalc`SharedObjectsTypesetting`Private`b, 
       FeynCalc`SharedObjectsTypesetting`Private`c], TraditionalForm]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`ind1_ /; 
         !MemberQ[{Spinor, SpinorU, SpinorV, SpinorUD, SpinorVD, SpinorUBar, 
           SpinorVBar, SpinorUBarD, SpinorVBarD}, 
          Head[FeynCalc`SharedObjectsTypesetting`Private`ind1]], 
       FeynCalc`SharedObjectsTypesetting`Private`ind2_ /; 
         !MemberQ[{Spinor, SpinorU, SpinorV, SpinorUD, SpinorVD, SpinorUBar, 
           SpinorVBar, SpinorUBarD, SpinorVBarD}, 
          Head[FeynCalc`SharedObjectsTypesetting`Private`ind2]]], 
      TraditionalForm] := ToBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a, 
       DiracIndex[FeynCalc`SharedObjectsTypesetting`Private`ind1], 
       DiracIndex[FeynCalc`SharedObjectsTypesetting`Private`ind2]], 
      TraditionalForm]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a:
        _Spinor | _SpinorUBar | _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`b_ /; 
         !MemberQ[{Spinor, SpinorU, SpinorV, SpinorUD, SpinorVD, SpinorUBar, 
           SpinorVBar, SpinorUBarD, SpinorVBarD}, 
          Head[FeynCalc`SharedObjectsTypesetting`Private`b]]], 
      TraditionalForm] := ToBoxes[DiracChain[
       FeynCalc`SharedObjectsTypesetting`Private`a, 
       DiracIndex[FeynCalc`SharedObjectsTypesetting`Private`b]], 
      TraditionalForm]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a_ /; 
         !MemberQ[{Spinor, SpinorU, SpinorV, SpinorUD, SpinorVD, SpinorUBar, 
           SpinorVBar, SpinorUBarD, SpinorVBarD}, 
          Head[FeynCalc`SharedObjectsTypesetting`Private`a]], 
       FeynCalc`SharedObjectsTypesetting`Private`b_], TraditionalForm] := 
     ToBoxes[DiracChain[DiracIndex[
        FeynCalc`SharedObjectsTypesetting`Private`a], 
       FeynCalc`SharedObjectsTypesetting`Private`b], TraditionalForm]
 
DCHN /: MakeBoxes[DCHN[FeynCalc`SharedObjectsTypesetting`Private`a:
        _Spinor | _SpinorUBar | _SpinorVBar | _SpinorUBarD | _SpinorVBarD, 
       FeynCalc`SharedObjectsTypesetting`Private`b:_Spinor | _SpinorU | 
         _SpinorV | _SpinorUD | _SpinorVD], TraditionalForm] := 
     ToBoxes[DiracChain[FeynCalc`SharedObjectsTypesetting`Private`a, 
       FeynCalc`SharedObjectsTypesetting`Private`b], TraditionalForm]
 
DCHN /: DCHN::usage = "DCHN[x, i, j] is a chain of Dirac matrices x and is \
transformed into\nDiracChain[FCI[x],DiracIndex[i],DiracIndex[j]] by \
FeynCalcInternal."
 
FeynCalc`FeynCalcExternal`Private`fermtmp /: 
    FeynCalc`FeynCalcExternal`Private`fermtmp::usage = ""
 
Attributes[PauliIndexDelta] = {Orderless}
 
PauliIndexDelta /: MakeBoxes[PauliIndexDelta[
       (FeynCalc`SharedObjectsTypesetting`Private`ind1:
         PauliIndex | ExplicitPauliIndex)[
        FeynCalc`SharedObjectsTypesetting`Private`i_], 
       (FeynCalc`SharedObjectsTypesetting`Private`ind2:
         PauliIndex | ExplicitPauliIndex)[
        FeynCalc`SharedObjectsTypesetting`Private`j_]], TraditionalForm] := 
     SubscriptBox["\[Delta]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`ind1[
        FeynCalc`SharedObjectsTypesetting`Private`i], 
       FeynCalc`SharedObjectsTypesetting`Private`ind2[
        FeynCalc`SharedObjectsTypesetting`Private`j]]]
 
PauliIndexDelta /: PauliIndexDelta::usage = "PauliIndexDelta[PauliIndex[i], \
PauliIndex[j]] is the Kronecker-delta in the\nPauli space with two explicit \
Pauli indices i and j."
 
PauliIndex[FeynCalc`SharedObjects`Private`i_Integer] := 
    ExplicitPauliIndex[FeynCalc`SharedObjects`Private`i]
 
PauliIndex /: MakeBoxes[PauliIndex[
       FeynCalc`SharedObjectsTypesetting`Private`p_], TraditionalForm] := 
     ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm]
 
PauliIndex /: PauliIndex::usage = "PauliIndex is the head of Pauli indices. \
The internal representation of a\ntwo-dimensional spinorial index i is \
PauliIndex[i].\n\nIf the first argument is an integer, PauliIndex[i] turns \
into\nExplicitPauliIndex[i].\n\nPauli indices are the indices that denote the \
components of Pauli matrices or\nspinors. They should not be confused with \
the Cartesian indices attached to\nthe Pauli matrices. For example in the \
case of $\\sigma_{ij}^{k}$,  $k$ is a\nLorentz index, while $i$ and $j$ are \
Pauli (spinorial) indices."
 
Attributes[ExplicitPauliIndex] = {Constant}
 
ExplicitPauliIndex /: MakeBoxes[ExplicitPauliIndex[
       FeynCalc`SharedObjectsTypesetting`Private`p_], TraditionalForm] := 
     ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm]
 
ExplicitPauliIndex /: ExplicitPauliIndex::usage = "ExplicitPauliIndex[ind] is \
an explicit Pauli index, i.e., ind is an integer."
 
FeynCalc`FeynCalcExternal`Private`paulidelta[
     FeynCalc`FeynCalcExternal`Private`i_, 
     FeynCalc`FeynCalcExternal`Private`j_] := 
    PIDelta[FeynCalc`FeynCalcExternal`Private`i, 
      FeynCalc`FeynCalcExternal`Private`j] /. 
     PauliIndex | ExplicitPauliIndex -> 
      FeynCalc`FeynCalcExternal`Private`iDent
 
Attributes[PIDelta] = {Orderless}
 
PIDelta /: MakeBoxes[PIDelta[FeynCalc`SharedObjectsTypesetting`Private`i_, 
       FeynCalc`SharedObjectsTypesetting`Private`j_], TraditionalForm] := 
     SubscriptBox["\[Delta]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`i, 
       FeynCalc`SharedObjectsTypesetting`Private`j]]
 
PIDelta /: PIDelta::usage = "PIDelta[i,j] is the Kronecker-delta in the Pauli \
space. PIDelta[i,j] is\ntransformed into \
PauliIndexDelta[PauliIndex[i],PauliIndex[j]] by\nFeynCalcInternal."
 
PauliChain[0, __] := 0
 
PauliChain[_, 0] := 0
 
PauliChain[1, FeynCalc`SharedObjects`Private`i:_PauliEta | _PauliEtaC | 
       _PauliXi, FeynCalc`SharedObjects`Private`j:
      _PauliIndex | _ExplicitPauliIndex] := 
    PauliChain[FeynCalc`SharedObjects`Private`i, 
     FeynCalc`SharedObjects`Private`j]
 
PauliChain[FeynCalc`SharedObjects`Private`x_ /; 
       FeynCalc`SharedObjects`Private`x =!= 1, 
      FeynCalc`SharedObjects`Private`i_, 
      FeynCalc`SharedObjects`Private`j_] /; 
     FreeQ2[{FCI[FeynCalc`SharedObjects`Private`x]}, 
       FeynCalc`Package`PauliHeadsList] && FCPatternFreeQ[
       {FeynCalc`SharedObjects`Private`x, FeynCalc`SharedObjects`Private`i, 
        FeynCalc`SharedObjects`Private`j}] := 
    FeynCalc`SharedObjects`Private`x*PauliChain[1, 
      FeynCalc`SharedObjects`Private`i, FeynCalc`SharedObjects`Private`j]
 
PauliChain[1, FeynCalc`SharedObjects`Private`a:_PauliEta | _PauliEtaC | 
       _PauliXi, FeynCalc`SharedObjects`Private`b:_PauliEta | _PauliEtaC | 
       _PauliXi] := PauliChain[FeynCalc`SharedObjects`Private`a, 
     FeynCalc`SharedObjects`Private`b]
 
PauliChain[(FeynCalc`SharedObjects`Private`b_Dot)*
      (FeynCalc`SharedObjects`Private`a_)?NumberQ, 
     FeynCalc`SharedObjects`Private`i_, FeynCalc`SharedObjects`Private`j_] := 
    FeynCalc`SharedObjects`Private`a*PauliChain[
      FeynCalc`SharedObjects`Private`b, FeynCalc`SharedObjects`Private`i, 
      FeynCalc`SharedObjects`Private`j]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b:PauliXi[Complex[0, -1]] | 
         PauliEta[Complex[0, -1]] | PauliEtaC[Complex[0, -1]], 
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _PauliIndex | _ExplicitPauliIndex], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`b, TraditionalForm], ".", 
        ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`a, 
         TraditionalForm], ")"}], 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _PauliIndex | _ExplicitPauliIndex, 
       FeynCalc`SharedObjectsTypesetting`Private`b:PauliXi[Complex[0, 1]] | 
         PauliEta[Complex[0, 1]] | PauliEtaC[Complex[0, 1]]], 
      TraditionalForm] := SubscriptBox[
      RowBox[{"(", ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`a, 
         TraditionalForm], ".", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`b, TraditionalForm], 
        ")"}], TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b:PauliXi[Complex[0, -1]] | 
         PauliEta[Complex[0, -1]] | PauliEtaC[Complex[0, -1]], 
       FeynCalc`SharedObjectsTypesetting`Private`c:PauliXi[Complex[0, 1]] | 
         PauliEta[Complex[0, 1]] | PauliEtaC[Complex[0, 1]]], 
      TraditionalForm] := 
     RowBox[{"(", ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`b, 
        TraditionalForm], ".", ToBoxes[
        FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], ".", 
       ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`c, TraditionalForm], 
       ")"}]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`ind1:
        _PauliIndex | _ExplicitPauliIndex, 
       FeynCalc`SharedObjectsTypesetting`Private`ind2:
        _PauliIndex | _ExplicitPauliIndex], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], 
        ")"}], TBox[FeynCalc`SharedObjectsTypesetting`Private`ind1, 
       FeynCalc`SharedObjectsTypesetting`Private`ind2]]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`a:PauliXi[Complex[0, -1]] | 
         PauliEta[Complex[0, -1]] | PauliEtaC[Complex[0, -1]], 
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _PauliIndex | _ExplicitPauliIndex], TraditionalForm] := 
     SubscriptBox[RowBox[{"(", ToBoxes[
         FeynCalc`SharedObjectsTypesetting`Private`a, TraditionalForm], 
        ")"}], TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`ind:
        _PauliIndex | _ExplicitPauliIndex, 
       FeynCalc`SharedObjectsTypesetting`Private`a:PauliXi[Complex[0, 1]] | 
         PauliEta[Complex[0, 1]] | PauliEtaC[Complex[0, 1]]], 
      TraditionalForm] := SubscriptBox[
      RowBox[{"(", ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`a, 
         TraditionalForm], ")"}], 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`ind]]
 
PauliChain /: MakeBoxes[PauliChain[
       FeynCalc`SharedObjectsTypesetting`Private`a:_PauliXi | _PauliEta | 
         _PauliEtaC, FeynCalc`SharedObjectsTypesetting`Private`b:
        _PauliXi | _PauliEta | _PauliEtaC], TraditionalForm] := 
     RowBox[{"(", ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`a, 
        TraditionalForm], ".", ToBoxes[
        FeynCalc`SharedObjectsTypesetting`Private`b, TraditionalForm], ")"}]
 
PauliChain /: PauliChain::usage = "PauliChain[x, i, j] denotes a chain of \
Pauli matrices x, where the Pauli\nindices i and j are explicit."
 
FeynCalc`Package`PauliHeadsList = {PauliSigma, PauliXi, PauliEta, PauliEtaC, 
     PauliChain, PauliIndexDelta, PauliTrace}
 
PauliTrace[0, OptionsPattern[]] := 0
 
PauliTrace[FeynCalc`PauliTrace`Private`expr_, FeynCalc`PauliTrace`Private`op:
      OptionsPattern[]] := Block[{FeynCalc`PauliTrace`Private`paTres, 
       FeynCalc`PauliTrace`Private`ex, FeynCalc`PauliTrace`Private`tr1, 
       FeynCalc`PauliTrace`Private`tr2, FeynCalc`PauliTrace`Private`tr3, 
       FeynCalc`PauliTrace`Private`time, FeynCalc`PauliTrace`Private`psHead, 
       FeynCalc`PauliTrace`Private`pauliObjects, 
       FeynCalc`PauliTrace`Private`pauliObjectsEval, 
       FeynCalc`PauliTrace`Private`null1, FeynCalc`PauliTrace`Private`null2, 
       FeynCalc`PauliTrace`Private`freePart, 
       FeynCalc`PauliTrace`Private`psPart, 
       FeynCalc`PauliTrace`Private`repRule, FeynCalc`PauliTrace`Private`paTr, 
       FeynCalc`PauliTrace`Private`holdDOT, 
       FeynCalc`PauliTrace`Private`insidePauliTrace}, 
      If[OptionValue[FCVerbose] === False, 
        FeynCalc`PauliTrace`Private`paTrVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[FCVerbose], _Integer], 
          FeynCalc`PauliTrace`Private`paTrVerbose = OptionValue[
            FCVerbose]]; ]; FeynCalc`PauliTrace`Private`unitMatrixTrace = 
        OptionValue[TraceOfOne]; FeynCalc`PauliTrace`Private`optSort = 
        OptionValue[Sort]; FCPrint[1, "PauliTrace. Entering.", 
        FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
       FCPrint[3, "PauliTrace: Entering with ", 
        FeynCalc`PauliTrace`Private`expr, FCDoControl -> 
         FeynCalc`PauliTrace`Private`paTrVerbose]; If[OptionValue[FCI], 
        FeynCalc`PauliTrace`Private`ex = FeynCalc`PauliTrace`Private`expr, 
        FeynCalc`PauliTrace`Private`ex = 
         FCI[FeynCalc`PauliTrace`Private`expr]]; 
       FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
       If[OptionValue[Contract] =!= False && 
          !DummyIndexFreeQ[FeynCalc`PauliTrace`Private`ex, 
           {LorentzIndex, CartesianIndex}], 
        FCPrint[1, "PauliTrace. Applying Contract.", FCDoControl -> 
           FeynCalc`PauliTrace`Private`paTrVerbose]; 
         FeynCalc`PauliTrace`Private`ex = Contract[
           FeynCalc`PauliTrace`Private`ex, Expanding -> True, 
           EpsContract -> OptionValue[EpsContract], Factoring -> False]; 
         FCPrint[1, "PauliTrace: Contract done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
          FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]]; 
       If[OptionValue[FCPauliIsolate], 
        FCPrint[1, "PauliTrace: Standard mode.", FCDoControl -> 
           FeynCalc`PauliTrace`Private`paTrVerbose]; 
         FeynCalc`PauliTrace`Private`ex = FCPauliIsolate[
           FeynCalc`PauliTrace`Private`ex, FCI -> True, 
           Head -> FeynCalc`PauliTrace`Private`psHead, PauliTrace -> False]; 
         FeynCalc`PauliTrace`Private`ex = FeynCalc`PauliTrace`Private`ex /. 
           PauliTrace -> FeynCalc`PauliTrace`Private`paTr; 
         {FeynCalc`PauliTrace`Private`freePart, 
           FeynCalc`PauliTrace`Private`psPart} = 
          FCSplit[FeynCalc`PauliTrace`Private`ex, 
           {FeynCalc`PauliTrace`Private`psHead}]; FCPrint[3, 
          "PauliTrace: psPart: ", FeynCalc`PauliTrace`Private`psPart, 
          FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
         FCPrint[3, "PauliTrace: freePart: ", 
          FeynCalc`PauliTrace`Private`freePart, FCDoControl -> 
           FeynCalc`PauliTrace`Private`paTrVerbose]; 
         If[FeynCalc`PauliTrace`Private`psPart =!= 0, 
          Scan[If[ !MatchQ[#1, (FeynCalc`PauliTrace`Private`a_.)*
                  FeynCalc`PauliTrace`Private`psHead[
                   FeynCalc`PauliTrace`Private`b_] /; 
                 FreeQ[{FeynCalc`PauliTrace`Private`a, 
                    FeynCalc`PauliTrace`Private`b}, 
                   FeynCalc`PauliTrace`Private`psHead] && 
                   !FreeQ[FeynCalc`PauliTrace`Private`b, PauliSigma]], 
              Message[PauliTrace::failmsg, "Irregular trace structure in", 
                InputForm[#1]]; Print[#1]; Abort[]] & , 
            FeynCalc`PauliTrace`Private`psPart + 
             FeynCalc`PauliTrace`Private`psHead[PauliSigma]]; ]; 
         FeynCalc`PauliTrace`Private`pauliObjects = 
          Union[Cases[FeynCalc`PauliTrace`Private`psPart + 
             FeynCalc`PauliTrace`Private`null1 + 
             FeynCalc`PauliTrace`Private`null2, 
            FeynCalc`PauliTrace`Private`psHead[_], Infinity]], 
        FCPrint[1, "PauliTrace: Fast mode.", FCDoControl -> 
           FeynCalc`PauliTrace`Private`paTrVerbose]; 
         If[ !FreeQ[FeynCalc`PauliTrace`Private`ex, PauliSigma], 
          FeynCalc`PauliTrace`Private`freePart = 0; 
           FeynCalc`PauliTrace`Private`psPart = 
            FeynCalc`PauliTrace`Private`psHead[
              FeynCalc`PauliTrace`Private`ex] /. PauliTrace -> 
              FeynCalc`PauliTrace`Private`paTr; 
           FeynCalc`PauliTrace`Private`pauliObjects = 
            {FeynCalc`PauliTrace`Private`psPart}, 
          FeynCalc`PauliTrace`Private`freePart = 
            FeynCalc`PauliTrace`Private`ex; 
           FeynCalc`PauliTrace`Private`psPart = 0; 
           FeynCalc`PauliTrace`Private`pauliObjects = {}]; ]; 
       FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
       FCPrint[1, "PauliTrace. Applying pauliTrickEvalFast.", 
        FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
       FeynCalc`PauliTrace`Private`insidePauliTrace = 
        FeynCalc`PauliTrick`Private`insidePauliTrace; 
       FeynCalc`PauliTrick`Private`insidePauliTrace = True; 
       FeynCalc`PauliTrace`Private`pauliObjectsEval = 
        (FeynCalc`PauliTrick`Private`pauliTrickEvalFast[#1] & ) /@ 
          (FeynCalc`PauliTrace`Private`pauliObjects /. 
           FeynCalc`PauliTrace`Private`psHead -> Identity) /. 
         FeynCalc`PauliTrick`Private`pauliTrickEvalFast -> Identity; 
       FeynCalc`PauliTrick`Private`insidePauliTrace = 
        FeynCalc`PauliTrace`Private`insidePauliTrace; 
       FCPrint[1, "PauliTrace: After pauliTrickEvalFast: ", 
        FeynCalc`PauliTrace`Private`pauliObjectsEval, 
        FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
       FeynCalc`PauliTrace`Private`pauliObjectsEval = 
        (FeynCalc`PauliTrace`Private`pauliTraceEvaluate[#1, 
           Flatten[Join[{FeynCalc`PauliTrace`Private`op}, FilterRules[
              Options[PauliTrace], Except[{
                FeynCalc`PauliTrace`Private`op}]]]]] & ) /@ 
         FeynCalc`PauliTrace`Private`pauliObjectsEval; 
       FeynCalc`PauliTrace`Private`pauliObjectsEval = 
        FeynCalc`PauliTrace`Private`pauliObjectsEval /. 
         FeynCalc`PauliTrace`Private`noSpur[
           FeynCalc`PauliTrace`Private`x__] :> 
          FeynCalc`PauliTrace`Private`paTr[
            DOT[FeynCalc`PauliTrace`Private`x]]/
           FeynCalc`PauliTrace`Private`unitMatrixTrace; 
       FCPrint[1, "PauliTrace: pauliTraceEvaluate finished, timing: ", 
        N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
        FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
       FeynCalc`PauliTrace`Private`repRule = 
        Thread[FeynCalc`PauliTrace`Private`pauliObjects -> 
          FeynCalc`PauliTrace`Private`pauliObjectsEval]; 
       FCPrint[3, "PauliTrace: repRule: ", 
        FeynCalc`PauliTrace`Private`repRule, FCDoControl -> 
         FeynCalc`PauliTrace`Private`paTrVerbose]; 
       If[ !FreeQ[FeynCalc`PauliTrace`Private`freePart, DOT], 
        FeynCalc`PauliTrace`Private`freePart = 
         FeynCalc`PauliTrace`Private`freePart /. DOT -> 
             FeynCalc`PauliTrace`Private`holdDOT /. 
           FeynCalc`PauliTrace`Private`holdDOT[
              FeynCalc`PauliTrace`Private`a__] /; NonCommFreeQ[
              {FeynCalc`PauliTrace`Private`a}] :> 
            Times[FeynCalc`PauliTrace`Private`a] /. 
          FeynCalc`PauliTrace`Private`holdDOT -> DOT]; 
       FeynCalc`PauliTrace`Private`tr3 = 
        FeynCalc`PauliTrace`Private`unitMatrixTrace*
          FeynCalc`PauliTrace`Private`freePart + 
         (FeynCalc`PauliTrace`Private`psPart /. Dispatch[
           FeynCalc`PauliTrace`Private`repRule]); 
       If[OptionValue[FeynCalcExternal], FeynCalc`PauliTrace`Private`paTres = 
         FCE[FeynCalc`PauliTrace`Private`tr3], 
        FeynCalc`PauliTrace`Private`paTres = 
         FeynCalc`PauliTrace`Private`tr3]; 
       If[ !FreeQ[FeynCalc`PauliTrace`Private`paTres /. 
           FeynCalc`PauliTrace`Private`paTr[_] :> 1, PauliSigma], 
        Message[PauliTrace::failmsg, 
          "The output still contains Pauli matrices"]; Abort[]]; 
       FeynCalc`PauliTrace`Private`paTres = 
        FeynCalc`PauliTrace`Private`paTres /. 
         FeynCalc`PauliTrace`Private`paTr -> PauliTrace; 
       FeynCalc`PauliTrace`Private`paTrVerbose = $VeryVerbose; 
       FCPrint[1, "PauliTrace: Leaving.", FCDoControl -> 
         FeynCalc`PauliTrace`Private`paTrVerbose]; 
       FCPrint[3, "PauliTrace: Leaving with", 
        FeynCalc`PauliTrace`Private`paTres, FCDoControl -> 
         FeynCalc`PauliTrace`Private`paTrVerbose]; 
       FeynCalc`PauliTrace`Private`paTres] /; OptionValue[PauliTraceEvaluate]
 
PauliTrace /: MakeBoxes[PauliTrace[FeynCalc`PauliTrace`Private`expr__, 
       OptionsPattern[]], TraditionalForm] := 
     RowBox[{"tr", "(", TBox[FeynCalc`PauliTrace`Private`expr], ")"}]
 
Options[PauliTrace] = {Contract -> True, EpsContract -> False, 
     EpsExpand -> True, Expand -> True, FCDiracIsolate -> True, 
     FCPauliIsolate -> True, FCVerbose -> False, Factoring -> Automatic, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     PairCollect -> False, PauliTraceEvaluate -> False, Sort -> True, 
     TraceOfOne -> 2}
 
PauliTrace /: PauliTrace::failmsg = "Error! PauliTrace has encountered a \
fatal problem and must abort the computation. The problem reads: `1`"
 
PauliTrace /: PauliTrace::mixmsg = "Expressions that mix D-, 4- and \
D-4-dimensional quantities are currently\nunsupported."
 
PauliTrace /: PauliTrace::usage = "PauliTrace[exp] is the head of Pauli \
traces. By default the trace is not\nevaluated. The evaluation occurs only \
when the option PauliTraceEvaluate is\nset to True. It is recommended to use \
PauliSimplify, which will automatically\nevaluate all Pauli traces in the \
input expression."
 
FeynCalc`PauliTrace`Private`paTrVerbose /: 
    FeynCalc`PauliTrace`Private`paTrVerbose::usage = ""
 
FeynCalc`PauliTrace`Private`unitMatrixTrace /: 
    FeynCalc`PauliTrace`Private`unitMatrixTrace::usage = ""
 
FeynCalc`PauliTrace`Private`optSort /: 
    FeynCalc`PauliTrace`Private`optSort::usage = ""
 
Contract[FeynCalc`Contract`Private`expr_List, FeynCalc`Contract`Private`opts:
      OptionsPattern[]] := Block[{FeynCalc`Contract`Private`optVerbose, 
      FeynCalc`Contract`Private`res, FeynCalc`Contract`Private`time}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`Contract`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`Contract`Private`optVerbose = OptionValue[FCVerbose]]; ]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Contract: Entering.", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      If[$ParallelizeFeynCalc && OptionValue[FCParallelize], 
       FCPrint[1, "Contract: Applying Contract in parallel.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`res = ParallelMap[
          Contract[#1, FilterRules[{FeynCalc`Contract`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & , 
          FeynCalc`Contract`Private`expr, DistributedContexts -> None, 
          Method -> "ItemsPerEvaluation" -> Ceiling[
             N[Length[FeynCalc`Contract`Private`expr]/$KernelCount]/10]]; 
        FCPrint[1, "Contract: Done applying Contract in parallel, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose], 
       FCPrint[1, "Contract: Applying Contract.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`res = 
         (Contract[#1, FilterRules[{FeynCalc`Contract`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & ) /@ 
          FeynCalc`Contract`Private`expr; FCPrint[1, 
         "Contract: Done applying Contract, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]]; 
      FCPrint[1, "Contract: Leaving.", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; FeynCalc`Contract`Private`res]
 
Contract[(FeynCalc`Contract`Private`a_) == (FeynCalc`Contract`Private`b_), 
     FeynCalc`Contract`Private`opts:OptionsPattern[]] := 
    Contract[FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`opts] == 
     Contract[FeynCalc`Contract`Private`b, FeynCalc`Contract`Private`opts]
 
Contract[FeynCalc`Contract`Private`expr_ /; 
      Head[FeynCalc`Contract`Private`expr] =!= List, 
     FeynCalc`Contract`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`Contract`Private`ex, FeynCalc`Contract`Private`tmp, 
      FeynCalc`Contract`Private`rest1 = 0, FeynCalc`Contract`Private`rest2 = 
       0, FeynCalc`Contract`Private`rest3 = 0, 
      FeynCalc`Contract`Private`noDummy = 0, FeynCalc`Contract`Private`nodot, 
      FeynCalc`Contract`Private`null1, FeynCalc`Contract`Private`null2, 
      FeynCalc`Contract`Private`freeIndList, 
      FeynCalc`Contract`Private`freeHead, FeynCalc`Contract`Private`tmpFin, 
      FeynCalc`Contract`Private`res, FeynCalc`Contract`Private`expandOpt, 
      FeynCalc`Contract`Private`epsContractOpt, 
      FeynCalc`Contract`Private`times, FeynCalc`Contract`Private`tmpList, 
      FeynCalc`Contract`Private`time, FeynCalc`Contract`Private`tmpCheck, 
      FeynCalc`Contract`Private`epsExpandOpt, 
      FeynCalc`Contract`Private`optVerbose, 
      FeynCalc`Contract`Private`factor}, 
     FeynCalc`Contract`Private`expandOpt = OptionValue[Expanding]; 
      FeynCalc`Contract`Private`epsContractOpt = OptionValue[EpsContract]; 
      FeynCalc`Contract`Private`epsExpandOpt = OptionValue[EpsExpand]; 
      FeynCalc`Contract`Private`optExpandScalarProduct = 
       OptionValue[ExpandScalarProduct]; 
      FeynCalc`Contract`Private`optFactoring = OptionValue[Factoring]; 
      FeynCalc`Contract`Private`optTimeConstrained = 
       OptionValue[TimeConstrained]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`Contract`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`Contract`Private`optVerbose = OptionValue[FCVerbose]]; ]; 
      If[ !OptionValue[FCI], FeynCalc`Contract`Private`ex = 
        FCI[FeynCalc`Contract`Private`expr], FeynCalc`Contract`Private`ex = 
        FeynCalc`Contract`Private`expr]; FCPrint[1, 
       "Contract: Entering main contract", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Entering with", FeynCalc`Contract`Private`ex, 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      If[FreeQ2[FeynCalc`Contract`Private`ex, {CartesianIndex, LorentzIndex, 
         Eps}], Return[FeynCalc`Contract`Private`ex]]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Contract: Separating terms that contain Lorentz indices \
from those that don't.", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      {FeynCalc`Contract`Private`rest1, FeynCalc`Contract`Private`tmp} = 
       FCSplit[FeynCalc`Contract`Private`ex, {CartesianIndex, LorentzIndex, 
         Eps}, Expanding -> False]; FCPrint[1, 
       "Contract: Splitting done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Terms that contain LorentzIndex or Eps: ", 
       FeynCalc`Contract`Private`tmp, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Other terms: ", FeynCalc`Contract`Private`rest1, 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmp, PairContract], 
       FCPrint[1, "Contract: Replacing PairContract with Pair.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`rest1 = FeynCalc`Contract`Private`rest1 /. 
          PairContract -> Pair; FeynCalc`Contract`Private`tmp = 
         FeynCalc`Contract`Private`tmp /. PairContract -> Pair; ]; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmp, CartesianPairContract], 
       FCPrint[1, 
         "Contract: Replacing CartesianPairContract with CartesianPair.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`rest1 = FeynCalc`Contract`Private`rest1 /. 
          CartesianPairContract -> CartesianPair; 
        FeynCalc`Contract`Private`tmp = FeynCalc`Contract`Private`tmp /. 
          CartesianPairContract -> CartesianPair; ]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Contract: Separating terms that contain Lorentz indices \
with a FreeIndex DataType", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`freeIndList = 
       Sort[DeleteDuplicates[
         (Cases[#1, LorentzIndex[FeynCalc`Contract`Private`i_, ___] /; 
              DataType[FeynCalc`Contract`Private`i, FreeIndex] :> 
             {FeynCalc`Contract`Private`i, FeynCalc`Contract`Private`freeHead[
               FeynCalc`Contract`Private`i]}, Infinity] & )[
          Sort[DeleteDuplicates[Cases[FeynCalc`Contract`Private`res, 
             _LorentzIndex, Infinity]]]]]]; 
      If[FeynCalc`Contract`Private`freeIndList =!= {}, 
       FCPrint[3, "Contract: List of indices that should not be summed over", 
         FeynCalc`Contract`Private`freeIndList, FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`tmp /. (Rule @@ #1 & ) /@ 
          FeynCalc`Contract`Private`freeIndList; 
        {FeynCalc`Contract`Private`tmp, FeynCalc`Contract`Private`rest2} = 
         FCSplit[FeynCalc`Contract`Private`tmp, 
          {FeynCalc`Contract`Private`freeHead}, Expanding -> False]; ]; 
      FCPrint[1, "Contract: Splitting done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Terms that contain Lorentz indices with a \
FreeIndex DataType: ", FeynCalc`Contract`Private`rest2, 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Other terms: ", FeynCalc`Contract`Private`tmp, 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, 
       "Contract: Separating terms that contain dummy Lorentz indices", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`tmpCheck = FeynCalc`Contract`Private`tmp; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmp, Power], 
       FeynCalc`Contract`Private`tmp = FeynCalc`Contract`Private`tmp /. 
          (FeynCalc`Contract`Private`a_)^
             (FeynCalc`Contract`Private`b_Integer)?Positive /; 
             !FreeQ2[FeynCalc`Contract`Private`a, {CartesianIndex, 
               LorentzIndex}] :> FeynCalc`Contract`Private`times @@ 
            Table[FeynCalc`Contract`Private`a, {FeynCalc`Contract`Private`i, 
              FeynCalc`Contract`Private`b}]; ]; 
      If[ !DummyIndexFreeQ[FeynCalc`Contract`Private`tmp, 
         {CartesianIndex, LorentzIndex}], FeynCalc`Contract`Private`tmpList = 
         List @@ (FeynCalc`Contract`Private`tmp + 
           FeynCalc`Contract`Private`null1 + 
           FeynCalc`Contract`Private`null2); FeynCalc`Contract`Private`tmp = 
         Select[FeynCalc`Contract`Private`tmpList, 
          FeynCalc`Contract`Private`hasDummyIndices]; 
        FeynCalc`Contract`Private`noDummy = Complement[
          FeynCalc`Contract`Private`tmpList, FeynCalc`Contract`Private`tmp]; 
        FeynCalc`Contract`Private`tmp = 
         Total[FeynCalc`Contract`Private`tmp] /. 
           FeynCalc`Contract`Private`times -> Times /. 
          FeynCalc`Contract`Private`null1 | 
            FeynCalc`Contract`Private`null2 -> 0; 
        FeynCalc`Contract`Private`noDummy = 
         Total[FeynCalc`Contract`Private`noDummy] /. 
           FeynCalc`Contract`Private`times -> Times /. 
          FeynCalc`Contract`Private`null1 | 
            FeynCalc`Contract`Private`null2 -> 0, 
       If[ !FreeQ[FeynCalc`Contract`Private`tmp, 
           FeynCalc`Contract`Private`times], FeynCalc`Contract`Private`tmp = 
           FeynCalc`Contract`Private`tmp /. 
            FeynCalc`Contract`Private`times -> Times; ]; 
        FeynCalc`Contract`Private`noDummy = FeynCalc`Contract`Private`tmp; 
        FeynCalc`Contract`Private`tmp = 0]; 
      If[FeynCalc`Contract`Private`tmp + 
         FeynCalc`Contract`Private`noDummy =!= 
        FeynCalc`Contract`Private`tmpCheck, 
       Message[Contract::fail, "Extraction of dummy indices failed!"]; 
        Abort[]]; FCPrint[1, "Contract: Splitting done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Terms that contain dummy Lorentz indices: ", 
       FeynCalc`Contract`Private`tmp, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Other terms: ", 
       FeynCalc`Contract`Private`noDummy, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Contract: Applying DotSimplify where it is needed.", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmp, DOT], 
       {FeynCalc`Contract`Private`nodot, FeynCalc`Contract`Private`tmp} = 
         FCSplit[FeynCalc`Contract`Private`tmp, {DOT}, Expanding -> False]; 
        FCPrint[4, "Contract: Terms that contain DOT: ", 
         FeynCalc`Contract`Private`tmp, FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; FCPrint[4, 
         "Contract: Other terms: ", FeynCalc`Contract`Private`nodot, 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`tmp = FeynCalc`Contract`Private`nodot + 
          DotSimplify[FeynCalc`Contract`Private`tmp, Expanding -> False]]; 
      If[ !FreeQ[FeynCalc`Contract`Private`noDummy, DOT] && 
         !FreeQ[FeynCalc`Contract`Private`noDummy, Eps], 
       {FeynCalc`Contract`Private`nodot, FeynCalc`Contract`Private`noDummy} = 
         FCSplit[FeynCalc`Contract`Private`noDummy, {DOT}, 
          Expanding -> False]; FCPrint[4, 
         "Contract: Rest Terms that contain DOT: ", 
         FeynCalc`Contract`Private`noDummy, FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; FCPrint[4, 
         "Contract: Rest Other terms: ", FeynCalc`Contract`Private`nodot, 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`noDummy = FeynCalc`Contract`Private`nodot + 
          DotSimplify[FeynCalc`Contract`Private`noDummy, 
           Expanding -> False]]; FCPrint[1, 
       "Contract: DotSimplify done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Terms to be processed further: ", 
       FeynCalc`Contract`Private`tmp, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      If[OptionValue[MomentumCombine] && 
        LeafCount[FeynCalc`Contract`Private`tmp] < 1000, 
       FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Contract: Applying MometumCombine.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`tmp = MomentumCombine[
          FeynCalc`Contract`Private`tmp, FCI -> True]; 
        FCPrint[1, "Contract: MometumCombine done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; ]; 
      FCPrint[3, "Contract: After MometumCombine: ", 
       FeynCalc`Contract`Private`tmp, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      If[ !DummyIndexFreeQ[FeynCalc`Contract`Private`tmp, 
         {LorentzIndex, CartesianIndex}], FeynCalc`Contract`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "Contract: mainContract: Applying PairContract.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[TrueQ[FeynCalc`Contract`Private`optExpandScalarProduct], 
         FeynCalc`Contract`Private`tmp = FeynCalc`Contract`Private`tmp /. 
             Pair -> PairContract3 /. PairContract3 -> PairContract /. 
           PairContract -> Pair, FeynCalc`Contract`Private`tmp = 
          FeynCalc`Contract`Private`tmp /. Pair -> PairContract /. 
           PairContract -> Pair]; FCPrint[1, 
         "Contract: mainContract: PairContract done. Timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FCPrint[3, "Contract: mainContract: After PairContract: ", 
         FeynCalc`Contract`Private`tmp, FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]]; 
      If[ !DummyIndexFreeQ[FeynCalc`Contract`Private`tmp, 
         {LorentzIndex, CartesianIndex}], 
       If[MemberQ[{Plus, Times}, Head[FeynCalc`Contract`Private`tmp]] && 
          !FreeQ2[FeynCalc`Contract`Private`tmp, {Pair, CartesianPair}], 
        FeynCalc`Contract`Private`time = AbsoluteTime[]; 
         FCPrint[1, 
          "Contract: mainContract: Applying prepareProductContractions.", 
          FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
         FeynCalc`Contract`Private`tmp = 
          FeynCalc`Contract`Private`prepareProductContractions[
           FeynCalc`Contract`Private`tmp, 
           FeynCalc`Contract`Private`optVerbose]; FCPrint[1, "Contract: \
mainContract: prepareProductContractions done. Timing: ", 
          N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
          FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
         FCPrint[3, 
          "Contract: mainContract: After prepareProductContractions: ", 
          FeynCalc`Contract`Private`tmp, FCDoControl -> 
           FeynCalc`Contract`Private`optVerbose]; 
         If[ !FreeQ2[FeynCalc`Contract`Private`tmp, 
            {FeynCalc`Contract`Private`prepareProductContractions, 
             FeynCalc`Contract`Private`reduceSumsToProducts, 
             FeynCalc`Contract`Private`contractWithProductOfPairs, 
             FeynCalc`Contract`Private`contractWithSinglePair}], 
          Message[Contract::fail, 
            "Something went wrong during prepareProductContractions."]; 
           Abort[]]]]; If[ !FreeQ[FeynCalc`Contract`Private`tmp, 
         CartesianIndex], FCPrint[1, "Contract: Applying cartesianContract.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        Which[Head[FeynCalc`Contract`Private`tmp] === Plus, 
         FeynCalc`Contract`Private`tmpFin = 
          (FeynCalc`Contract`Private`cartesianContract[#1, 
             FeynCalc`Contract`Private`opts] & ) /@ 
           FeynCalc`Contract`Private`tmp, 
         Head[FeynCalc`Contract`Private`tmp] === Times, 
         FeynCalc`Contract`Private`tmpFin = 
          FeynCalc`Contract`Private`cartesianContract[
           FeynCalc`Contract`Private`tmp, FeynCalc`Contract`Private`opts], 
         True, FeynCalc`Contract`Private`tmpFin = 
          FeynCalc`Contract`Private`cartesianContract[
           FeynCalc`Contract`Private`tmp, FeynCalc`Contract`Private`opts]]; 
        FCPrint[1, "Contract: cartesianContract done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FCPrint[3, "Contract: After cartesianContract: ", 
         FeynCalc`Contract`Private`tmpFin, FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose], 
       FeynCalc`Contract`Private`tmpFin = FeynCalc`Contract`Private`tmp]; 
      If[FeynCalc`Contract`Private`expandOpt, 
       FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "Contract: Expanding w.r.t Lorentz and Cartesian indices.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, LorentzIndex], 
         FeynCalc`Contract`Private`tmpFin = Expand[
           FeynCalc`Contract`Private`tmpFin, CartesianIndex]]; 
        If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, CartesianIndex], 
         FeynCalc`Contract`Private`tmpFin = Expand[
           FeynCalc`Contract`Private`tmpFin, CartesianIndex]]; 
        If[ !FreeQ[FeynCalc`Contract`Private`noDummy, LorentzIndex], 
         FeynCalc`Contract`Private`noDummy = 
          Expand[FeynCalc`Contract`Private`noDummy, LorentzIndex]]; 
        If[ !FreeQ[FeynCalc`Contract`Private`noDummy, CartesianIndex], 
         FeynCalc`Contract`Private`noDummy = 
          Expand[FeynCalc`Contract`Private`noDummy, CartesianIndex]]; 
        FCPrint[1, "Contract: Expansion done: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; ]; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, Eps], 
       FCPrint[1, "Contract: Applying EpsEvaluate.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`tmpFin = EpsEvaluate[
          FeynCalc`Contract`Private`tmpFin, FCI -> True, 
          EpsExpand -> FeynCalc`Contract`Private`epsExpandOpt]; 
        FCPrint[3, "Contract: After EpsEvaluate: ", 
         FeynCalc`Contract`Private`tmpFin, FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; ]; 
      If[FeynCalc`Contract`Private`epsContractOpt, 
       FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Contract: Contracting epsilon tensors.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[ !EpsContractFreeQ[FeynCalc`Contract`Private`tmpFin], 
         FeynCalc`Contract`Private`tmpFin = EpsContract[
           FeynCalc`Contract`Private`tmpFin, FCI -> True]]; 
        If[ !EpsContractFreeQ[FeynCalc`Contract`Private`noDummy], 
         FeynCalc`Contract`Private`noDummy = EpsContract[
           FeynCalc`Contract`Private`noDummy, FCI -> True]]; 
        FCPrint[1, "Contract: Epsilon contractions done: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; ]; 
      If[FeynCalc`Contract`Private`expandOpt, 
       FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Contract: Expanding in Lorentz and Cartesian indices.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, LorentzIndex], 
         FeynCalc`Contract`Private`tmpFin = Expand[
           FeynCalc`Contract`Private`tmpFin, LorentzIndex]]; 
        If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, CartesianIndex], 
         FeynCalc`Contract`Private`tmpFin = Expand[
           FeynCalc`Contract`Private`tmpFin, CartesianIndex]]; 
        If[ !FreeQ[FeynCalc`Contract`Private`noDummy, LorentzIndex], 
         FeynCalc`Contract`Private`noDummy = 
          Expand[FeynCalc`Contract`Private`noDummy, LorentzIndex]]; 
        If[ !FreeQ[FeynCalc`Contract`Private`noDummy, CartesianIndex], 
         FeynCalc`Contract`Private`noDummy = 
          Expand[FeynCalc`Contract`Private`noDummy, CartesianIndex]]; 
        FCPrint[1, "Contract: Expansions done: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[FeynCalc`Contract`Private`epsContractOpt, 
         FeynCalc`Contract`Private`time = AbsoluteTime[]; 
          FCPrint[1, "Contract: Expanding in Epsilon.", FCDoControl -> 
            FeynCalc`Contract`Private`optVerbose]; 
          If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, Eps], 
           FeynCalc`Contract`Private`tmpFin = Expand[
             FeynCalc`Contract`Private`tmpFin, Eps]]; 
          If[ !FreeQ[FeynCalc`Contract`Private`noDummy, Eps], 
           FeynCalc`Contract`Private`noDummy = Expand[
             FeynCalc`Contract`Private`noDummy, Eps]]; 
          FCPrint[1, "Contract: Expansions done: ", 
           N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
           FCDoControl -> FeynCalc`Contract`Private`optVerbose]]; ]; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, Pair] && 
         !DummyIndexFreeQ[FeynCalc`Contract`Private`tmpFin, 
          {LorentzIndex, CartesianIndex}], FeynCalc`Contract`Private`time = 
         AbsoluteTime[]; FCPrint[1, "Contract: Applying PairContract.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[TrueQ[FeynCalc`Contract`Private`optExpandScalarProduct], 
         FeynCalc`Contract`Private`tmpFin = 
          FeynCalc`Contract`Private`tmpFin /. Pair -> PairContract3 /. 
            PairContract3 -> PairContract /. PairContract -> Pair, 
         FeynCalc`Contract`Private`tmpFin = 
           FeynCalc`Contract`Private`tmpFin /. Pair -> PairContract /. 
            PairContract -> Pair; ]; FCPrint[1, 
         "Contract: PairContract done: ", N[AbsoluteTime[] - 
           FeynCalc`Contract`Private`time, 4], FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]]; 
      If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, CartesianPair] && 
         !DummyIndexFreeQ[FeynCalc`Contract`Private`tmpFin, 
          {LorentzIndex, CartesianIndex}], FeynCalc`Contract`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "Contract: Applying CartesianPairContract.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`tmpFin = 
         FeynCalc`Contract`Private`tmpFin /. CartesianPair -> 
            CartesianPairContract /. CartesianPairContract -> CartesianPair; 
        FCPrint[1, "Contract: CartesianPairContract done: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; ]; 
      If[FeynCalc`Contract`Private`epsContractOpt, 
       FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Contract: Applying EpsEvaluate.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        If[ !FreeQ[FeynCalc`Contract`Private`tmpFin, Eps], 
         FeynCalc`Contract`Private`tmpFin = EpsEvaluate[
            FeynCalc`Contract`Private`tmpFin, FCI -> True, 
            EpsExpand -> FeynCalc`Contract`Private`epsExpandOpt]; 
          FCPrint[3, "Contract: After EpsEvaluate: ", 
           FeynCalc`Contract`Private`tmpFin, FCDoControl -> 
            FeynCalc`Contract`Private`optVerbose]; ]; 
        If[ !FreeQ[FeynCalc`Contract`Private`noDummy, Eps], 
         FeynCalc`Contract`Private`noDummy = EpsEvaluate[
            FeynCalc`Contract`Private`noDummy, FCI -> True, 
            EpsExpand -> FeynCalc`Contract`Private`epsExpandOpt]; 
          FCPrint[3, "Contract: After EpsEvaluate: ", 
           FeynCalc`Contract`Private`noDummy, FCDoControl -> 
            FeynCalc`Contract`Private`optVerbose]; ]; 
        FCPrint[1, "Contract: EpsEvaluate done: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; ]; 
      FeynCalc`Contract`Private`tmpFin = FeynCalc`Contract`Private`tmpFin + 
        FeynCalc`Contract`Private`noDummy; FCPrint[3, 
       "Contract: After additional manipulations: ", 
       FeynCalc`Contract`Private`tmpFin, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`res = FeynCalc`Contract`Private`rest1 + 
        FeynCalc`Contract`Private`rest2 + FeynCalc`Contract`Private`rest3 + 
        FeynCalc`Contract`Private`tmpFin; FCPrint[3, 
       "Contract: Preliminary result: ", FeynCalc`Contract`Private`tmpFin, 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      Switch[FeynCalc`Contract`Private`optFactoring, False, 
       FeynCalc`Contract`Private`factor = Identity, True | Factor2, 
       FeynCalc`Contract`Private`factor = Function[
         FeynCalc`Contract`Private`fuArg, TimeConstrained[
          Factor2[FeynCalc`Contract`Private`fuArg], 
          FeynCalc`Contract`Private`optTimeConstrained, 
          FeynCalc`Contract`Private`fuArg]], {_, _Integer}, 
       FeynCalc`Contract`Private`factor = Function[
         FeynCalc`Contract`Private`fuArg, 
         If[TrueQ[LeafCount[FeynCalc`Contract`Private`fuArg] < 
            FeynCalc`Contract`Private`optFactoring[[2]]], 
          TimeConstrained[FeynCalc`Contract`Private`optFactoring[[1]][
            FeynCalc`Contract`Private`fuArg], 
           FeynCalc`Contract`Private`optTimeConstrained, 
           FeynCalc`Contract`Private`fuArg], 
          FeynCalc`Contract`Private`fuArg]], _, 
       FeynCalc`Contract`Private`factor = 
        FeynCalc`Contract`Private`optFactoring]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Contract: Factoring the result.", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`res = FeynCalc`Contract`Private`factor[
        FeynCalc`Contract`Private`res]; FCPrint[1, 
       "Contract: Factoring done: ", N[AbsoluteTime[] - 
         FeynCalc`Contract`Private`time, 4], FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; If[OptionValue[FCE], 
       FeynCalc`Contract`Private`res = FCE[FeynCalc`Contract`Private`res]]; 
      FCPrint[1, "Contract: Leaving. ", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: Leaving with : ", FeynCalc`Contract`Private`res, 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`res]
 
Options[Contract] = {EpsContract -> True, EpsExpand -> True, 
     Expanding -> True, ExpandScalarProduct -> True, 
     Factoring -> {Factor2, 5000}, FCParallelize -> False, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCVerbose -> False, MomentumCombine -> True, TimeConstrained -> 3}
 
Contract /: Contract::fail = "Error! Contract has encountered a fatal problem \
and must abort the computation. The problem reads: `1`"
 
Contract /: Contract::usage = "Contract[expr] contracts pairs of Lorentz or \
Cartesian indices of metric\ntensors, vectors and (depending on the value of \
the option EpsContract) of\nLevi-Civita tensors in expr.\n\nFor contractions \
of Dirac matrices with each other use DiracSimplify.\n\nContract[exp1, exp2] \
contracts (exp1*exp2), where exp1 and exp2 may be larger\nproducts of sums of \
metric tensors and 4-vectors. This can be also useful when\nevaluating \
polarization sums, where exp2 should be the product (or expanded\nsum) of the \
polarization sums for the vector bosons."
 
EpsContract[FeynCalc`EpsContract`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`EpsContract`Private`ex, FeynCalc`EpsContract`Private`tmp, 
      FeynCalc`EpsContract`Private`res, FeynCalc`EpsContract`Private`epsList, 
      FeynCalc`EpsContract`Private`epsListEval, 
      FeynCalc`EpsContract`Private`repRule, 
      FeynCalc`EpsContract`Private`epsHead, 
      FeynCalc`EpsContract`Private`null1, FeynCalc`EpsContract`Private`null2, 
      FeynCalc`EpsContract`Private`epsIsolate}, 
     If[ !OptionValue[FCI], FeynCalc`EpsContract`Private`ex = 
        FCI[FeynCalc`EpsContract`Private`expr], 
       FeynCalc`EpsContract`Private`ex = FeynCalc`EpsContract`Private`expr]; 
      If[FreeQ[FeynCalc`EpsContract`Private`ex, Eps], 
       Return[FeynCalc`EpsContract`Private`ex]]; If[OptionValue[Collecting], 
       FeynCalc`EpsContract`Private`ex = Collect2[
         FeynCalc`EpsContract`Private`ex, Eps, Factoring -> 
          OptionValue[Factoring], IsolateNames -> 
          FeynCalc`EpsContract`Private`epsIsolate]]; 
      If[Head[FeynCalc`EpsContract`Private`ex] === Plus, 
       FeynCalc`EpsContract`Private`res = 
        (SelectFree[#1, Eps]*FeynCalc`EpsContract`Private`epsHead[
            SelectNotFree[#1, Eps]] & ) /@ FeynCalc`EpsContract`Private`ex, 
       FeynCalc`EpsContract`Private`res = 
        SelectFree[FeynCalc`EpsContract`Private`ex, Eps]*
         FeynCalc`EpsContract`Private`epsHead[SelectNotFree[
           FeynCalc`EpsContract`Private`ex, Eps]]]; 
      If[Together[(FeynCalc`EpsContract`Private`res /. 
           FeynCalc`EpsContract`Private`epsHead -> Identity) - 
          FeynCalc`EpsContract`Private`ex] =!= 0, 
       Message[EpsContract::failmsg, "Failed to isolate epsilon tensors"]; 
