      FeynCalc`Collect2`Private`ex = 
       (SelectFree[#1, FeynCalc`Collect2`Private`monomList]*
           FeynCalc`Collect2`Private`monomialHead[SelectNotFree[#1, 
             FeynCalc`Collect2`Private`monomList]] & ) /@ 
         (FeynCalc`Collect2`Private`ex + FeynCalc`Collect2`Private`null1 + 
          FeynCalc`Collect2`Private`null2) /. 
        {FeynCalc`Collect2`Private`null1 | FeynCalc`Collect2`Private`null2 -> 
          0}; FeynCalc`Collect2`Private`tv = 
       Cases2[FeynCalc`Collect2`Private`ex, 
        FeynCalc`Collect2`Private`monomialHead]; 
      FCPrint[1, "Collect2: Wrapping done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FCPrint[3, "Collect2: ex: ", FeynCalc`Collect2`Private`ex, 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FCPrint[3, "Collect2: tv: ", FeynCalc`Collect2`Private`tv, 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      If[FeynCalc`Collect2`Private`dde === True, 
       FCPrint[1, 
         "Collect2: Also denominators containing variables will be collected"\
, FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
        FeynCalc`Collect2`Private`cd[FeynCalc`Collect2`Private`x_] := 
         (Numerator[#1]/(FeynCalc`Collect2`Private`factor[Denominator[#1]] /. 
              Plus -> (Collect2[Plus[##1], 
                 FeynCalc`Collect2`Private`monomList, 
                 FeynCalc`Collect2`Private`opts] & )) & )[
           FeynCalc`Collect2`Private`x] /; 
           !FreeQ[Denominator[FeynCalc`Collect2`Private`x], Plus] && 
            !FreeQ2[Denominator[FeynCalc`Collect2`Private`x], 
             FeynCalc`Collect2`Private`monomList]]; 
      FCPrint[1, "Collect2: There are ", 
       Length[FeynCalc`Collect2`Private`tv], " momomials to collect", 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Collect2: Computing CoefficientArrays.", 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FeynCalc`Collect2`Private`coeffArray = CoefficientArrays[
        FeynCalc`Collect2`Private`ex, FeynCalc`Collect2`Private`tv]; 
      FCPrint[1, "Collect2: CoefficientArrays ready, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FCPrint[3, "Collect2: CoefficientArrays: ", 
       FeynCalc`Collect2`Private`coeffArray, FCDoControl -> 
        FeynCalc`Collect2`Private`optVerbose]; 
      If[FeynCalc`Collect2`Private`coeffArray =!= {0}, 
       If[Length[FeynCalc`Collect2`Private`coeffArray] > 2 || 
          Head[FeynCalc`Collect2`Private`coeffArray[[2]]] =!= SparseArray, 
         Message[Collect2::failmsg, 
           "Something went wrong when applying CoefficientArrays."]; 
          Abort[]]; If[FeynCalc`Collect2`Private`coeffArray[[1]] =!= 0, 
         Message[Collect2::failmsg, "There is another linear part!"]; 
          Abort[]]; FeynCalc`Collect2`Private`sparseArray = 
         FeynCalc`Collect2`Private`coeffArray[[2]]; 
        FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Collect2: Collecting the monomials.", 
         FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
        FeynCalc`Collect2`Private`tvm = 
         (FeynCalc`Collect2`Private`frh[#1] /. 
             FeynCalc`Collect2`Private`monomialHead -> 
              FeynCalc`Collect2`Private`cd /. FeynCalc`Collect2`Private`cd -> 
             FeynCalc`Collect2`Private`firstHead & ) /@ 
          FeynCalc`Collect2`Private`tv; FCPrint[3, "Collect2: tvm: ", 
         FeynCalc`Collect2`Private`tvm, FCDoControl -> 
          FeynCalc`Collect2`Private`optVerbose]; FCPrint[1, 
         "Collect2: Done collecting the monomials, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
         FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
        FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
        If[$ParallelizeFeynCalc && 
          FeynCalc`Collect2`Private`optFCParallelize, 
         FCPrint[1, 
           "Collect2: Factoring coefficients of the monomials in parallel.", 
           FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
          With[{FeynCalc`Collect2`Private`xxx = 
             FeynCalc`Collect2`Private`unity, FeynCalc`Collect2`Private`yyy = 
             FeynCalc`Collect2`Private`factor}, ParallelEvaluate[
            FCParallelContext`Collect2`unity = FeynCalc`Collect2`Private`xxx; 
             FCParallelContext`Collect2`factor = 
              FeynCalc`Collect2`Private`yyy; , DistributedContexts -> None]]; 
          DistributeDefinitions[FeynCalc`Collect2`Private`factor, 
           FeynCalc`Collect2`Private`factoring, 
           FeynCalc`Collect2`Private`optTimeConstrained]; 
          FeynCalc`Collect2`Private`coeffs = FeynCalc`Collect2`Private`frh /@ 
            Normal[FeynCalc`Collect2`Private`sparseArray]; 
          FeynCalc`Collect2`Private`coeffs = ParallelMap[
            FeynCalc`Collect2`Private`factor[FCParallelContext`Collect2`unity*
               #1] & , FeynCalc`Collect2`Private`coeffs, 
            DistributedContexts -> None, Method -> "ItemsPerEvaluation" -> 
              Ceiling[N[Length[FeynCalc`Collect2`Private`coeffs]/
                  $KernelCount]/10]]; FeynCalc`Collect2`Private`coeffs = 
           FeynCalc`Collect2`Private`coeffs /. 
            FCParallelContext`Collect2`unity -> 
             FeynCalc`Collect2`Private`unity; , 
         FCPrint[1, "Collect2: Factoring coefficients of the monomials.", 
           FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
          FeynCalc`Collect2`Private`coeffs = (FeynCalc`Collect2`Private`tog[
              FeynCalc`Collect2`Private`unity*#1] & ) /@ 
            FeynCalc`Collect2`Private`sparseArray]; FCPrint[1, "Collect2: \
Done factoring coefficients of the monomials, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
         FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
        If[FeynCalc`Collect2`Private`optIsolateNames =!= False, 
         FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
          FCPrint[1, "Collect2: Isolating coefficients of the monomials.", 
           FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
          FeynCalc`Collect2`Private`coeffs = 
           (Isolate[#1 /. {FeynCalc`Collect2`Private`unity -> 1, 
                FeynCalc`Collect2`Private`holdForm2[
                   FeynCalc`Collect2`Private`ka_][
                  FeynCalc`Collect2`Private`j_] :> 
                 FeynCalc`Collect2`Private`holdForm[
                  FeynCalc`Collect2`Private`ka[
                   FeynCalc`Collect2`Private`j]]}, IsolateNames -> 
               FeynCalc`Collect2`Private`optIsolateNames, IsolateFast -> 
               FeynCalc`Collect2`Private`optIsolateFast] & ) /@ 
            FeynCalc`Collect2`Private`coeffs; FCPrint[1, "Collect2: Done \
isolating coefficients of the monomials, timing: ", 
           N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
           FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; ]; 
        FeynCalc`Collect2`Private`new = FeynCalc`Collect2`Private`coeffs . 
          FeynCalc`Collect2`Private`tvm, FeynCalc`Collect2`Private`new = 0]; 
      FCPrint[3, "Collect2: new: ", FeynCalc`Collect2`Private`new, 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      If[ !FreeQ2[FeynCalc`Collect2`Private`lin, 
         FeynCalc`Collect2`Private`monomList], 
       Message[Collect2::failmsg, "Linear part contains monomials!"]; 
        Print[FeynCalc`Collect2`Private`lin]; Abort[]]; 
      FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Collect2: Releasing tempIso.", FCDoControl -> 
        FeynCalc`Collect2`Private`optVerbose]; 
      If[FeynCalc`Collect2`Private`optIsolateNames =!= False, 
       FeynCalc`Collect2`Private`lin = Isolate[FeynCalc`Collect2`Private`frh[
          FeynCalc`Collect2`Private`lin], IsolateNames -> 
          FeynCalc`Collect2`Private`optIsolateNames, IsolateFast -> 
          FeynCalc`Collect2`Private`optIsolateFast], 
       FeynCalc`Collect2`Private`lin = FeynCalc`Collect2`Private`frh[
         FeynCalc`Collect2`Private`lin /. 
          FeynCalc`Collect2`Private`holdForm -> Identity]]; 
      FCPrint[1, "Collect2: Done releasing tempIso, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      If[FeynCalc`Collect2`Private`secondHead =!= Null, 
       FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Collect2: Applying secondHead.", FCDoControl -> 
          FeynCalc`Collect2`Private`optVerbose]; 
        FeynCalc`Collect2`Private`lin = FeynCalc`Collect2`Private`secondHead[
           FeynCalc`Collect2`Private`lin, 1] /. 
          FeynCalc`Collect2`Private`secondHead[0, _] -> 0; 
        FeynCalc`Collect2`Private`new = 
         FeynCalc`Collect2`Private`secondHead /@ 
             (FeynCalc`Collect2`Private`new + 
              FeynCalc`Collect2`Private`null1 + 
              FeynCalc`Collect2`Private`null2) /. 
            FeynCalc`Collect2`Private`secondHead[
              FeynCalc`Collect2`Private`null1 | 
               FeynCalc`Collect2`Private`null2] -> 0 /. 
           FeynCalc`Collect2`Private`secondHead[
             (
               FeynCalc`Collect2`Private`a_FeynCalc`Collect2`Private`firstHead)\
*(FeynCalc`Collect2`Private`b_)] :> FeynCalc`Collect2`Private`secondHead[
             FeynCalc`Collect2`Private`b, FeynCalc`Collect2`Private`a] /. 
          FeynCalc`Collect2`Private`ident -> Identity; 
        FCPrint[1, "Collect2: Done applying secondHead, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
         FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; ]; 
      FeynCalc`Collect2`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Collect2: Putting res togehter.", 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FeynCalc`Collect2`Private`res = 
       FeynCalc`Collect2`Private`new + FeynCalc`Collect2`Private`lin /. 
         FeynCalc`Collect2`Private`holdForm2[FeynCalc`Collect2`Private`ka_][
           FeynCalc`Collect2`Private`j_] -> 
          FeynCalc`Collect2`Private`holdForm[FeynCalc`Collect2`Private`ka[
            FeynCalc`Collect2`Private`j]] /. FeynCalc`Collect2`Private`frx -> 
         Plus; FCPrint[1, "Collect2: Done putting res togehter, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FCPrint[1, "Collect2: Done releasing tempIso, timing: ", 
       N[AbsoluteTime[] - FeynCalc`Collect2`Private`time, 4], 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      If[FeynCalc`Collect2`Private`ccflag, FeynCalc`Collect2`Private`res = 
        FeynCalc`Collect2`Private`res /. FeynCalc`Collect2`Private`compCON -> 
          ComplexConjugate]; FeynCalc`Collect2`Private`unity = 1; 
      FeynCalc`Collect2`Private`res = FeynCalc`Collect2`Private`factorOut*
         (FeynCalc`Collect2`Private`res/
          FeynCalc`Collect2`Private`denominator) /. 
        FeynCalc`Collect2`Private`monomRepRule; 
      FCPrint[1, "Collect2: Leaving.", FCDoControl -> 
        FeynCalc`Collect2`Private`optVerbose]; 
      FCPrint[3, "Collect2: Leaving with ", FeynCalc`Collect2`Private`res, 
       FCDoControl -> FeynCalc`Collect2`Private`optVerbose]; 
      FeynCalc`Collect2`Private`res]
 
Options[Collect2] = {Denominator -> False, Dot -> False, Expanding -> True, 
     FCFactorOut -> 1, FCVerbose -> False, Factoring -> Factor, 
     FCParallelize -> False, FactoringDenominator -> False, Head -> Identity, 
     InitialFunction -> Identity, IntermediateSubstitutions -> {}, 
     IsolateFast -> False, IsolateNames -> False, Numerator -> False, 
     FeynCalc`Collect2`Private`ParallelKernels -> False, 
     TimeConstrained -> Infinity}
 
Collect2 /: Collect2::failmsg = "Error! Collect2 has encountered a fatal \
problem and must abort the computation. The problem reads: `1`"
 
Collect2 /: Collect2::usage = "Collect2[expr, x] collects together terms \
which are not free of any occurrence\nof x.\n\nCollect2[expr, {x1, x2, ...}] \
(or also Collect2[expr, x1, x2, ...]) collects\ntogether terms which are not \
free of any occurrence of x1, x2, ....\n\nThe coefficients are put over a \
common denominator. If expr is expanded before\ncollecting depends on the \
option Factoring, which may be set to Factor,\nFactor2, or any other \
function, which is applied to the coefficients. If expr\nis already expanded \
with respect to x (x1, x2, ...), the option Expanding can\nbe set to False."
 
IsolateNames /: IsolateNames::usage = "IsolateNames is an option for Isolate \
and Collect2. Its default setting is KK.\nInstead of a symbol the setting may \
also be a list with the names of the\nabbreviations."
 
IsolateFast /: IsolateFast::usage = "IsolateFast is an option of Isolate and \
other functions using Isolate. When\nset to True and when varlist is empty, \
Isolate will not attempt to recognize\nexisting abbreviations, but will \
immediately abbreviate the whole expression\ninstead. This is useful for very \
large expressions or prefactors, where\nIsolate would otherwise require a lot \
of time to finish."
 
InitialFunction /: InitialFunction::usage = "InitialFunction is an option of \
FeynRule the setting of which is applied to\nthe first argument of FeynRule \
before anything else."
 
FactoringDenominator /: FactoringDenominator::usage = "FactoringDenominator \
is an option for Collect2. It is taken into account only\nwhen the option \
Numerator is set to True. If FactoringDenominator is set to\nany function f, \
this function will be applied to the denominator of the\nfraction. The \
default value is False, i.e. the denominator will be left\nunchanged."
 
FCFactorOut[(FeynCalc`SharedTools`Private`a_) == 
      (FeynCalc`SharedTools`Private`b_), FeynCalc`SharedTools`Private`y__] := 
    FCFactorOut[FeynCalc`SharedTools`Private`a, 
      FeynCalc`SharedTools`Private`y] == FCFactorOut[
      FeynCalc`SharedTools`Private`b, FeynCalc`SharedTools`Private`y]
 
FCFactorOut[(FeynCalc`SharedTools`Private`h:Rule | RuleDelayed)[
      FeynCalc`SharedTools`Private`a_, FeynCalc`SharedTools`Private`b_], 
     FeynCalc`SharedTools`Private`y__] := 
    With[{FeynCalc`SharedTools`Private`zz = FCFactorOut[
        FeynCalc`SharedTools`Private`b, FeynCalc`SharedTools`Private`y]}, 
     FeynCalc`SharedTools`Private`h[FeynCalc`SharedTools`Private`a, 
      FeynCalc`SharedTools`Private`zz]]
 
FCFactorOut[FeynCalc`SharedTools`Private`x_List, 
     FeynCalc`SharedTools`Private`y__] := 
    (FCFactorOut[#1, FeynCalc`SharedTools`Private`y] & ) /@ 
     FeynCalc`SharedTools`Private`x
 
FCFactorOut[FeynCalc`SharedTools`Private`expr_, 
     FeynCalc`SharedTools`Private`pref_, OptionsPattern[]] := 
    FeynCalc`SharedTools`Private`pref*OptionValue[Head][
      OptionValue[Factoring][FeynCalc`SharedTools`Private`expr/
        FeynCalc`SharedTools`Private`pref]]
 
Options[FCFactorOut] = {Factoring -> Simplify, Head -> Identity}
 
FCFactorOut /: FCFactorOut::usage = "FCFactorOut[exp, pref] factors out pref \
out of exp. This is often needed to\nbring exp into a particular form that \
Mathematica refuses to give."
 
IntermediateSubstitutions /: IntermediateSubstitutions::usage = "Intermediate\
Substitutions is an option of various FeynCalc functions. All\nsubstitutions \
indicated hereby are done at an intermediate stage of the\ncalculation."
 
Isolate[OptionsPattern[]] := (Message[Isolate::argt, Isolate, 0, 1, 2]; 
     Abort[])
 
Isolate[_, _, FeynCalc`Isolate`Private`a___, FeynCalc`Isolate`Private`z:
      Except[_?OptionQ], OptionsPattern[]] := 
    (Message[Isolate::argt, Isolate, Length[{FeynCalc`Isolate`Private`a}] + 
        3, 1, 2]; Abort[]) /;  !OptionQ[FeynCalc`Isolate`Private`z]
 
Isolate[(FeynCalc`Isolate`Private`y:Blank[HoldForm])^
      (FeynCalc`Isolate`Private`n_.), _, OptionsPattern[]] := 
    FeynCalc`Isolate`Private`y^FeynCalc`Isolate`Private`n
 
Isolate[(FeynCalc`Isolate`Private`x_)?NumberQ, _, OptionsPattern[]] := 
    FeynCalc`Isolate`Private`x
 
Isolate[FeynCalc`Isolate`Private`x_Symbol, _, OptionsPattern[]] := 
    FeynCalc`Isolate`Private`x
 
Isolate[FeynCalc`Isolate`Private`x_ /; (#1 =!= 1 && ExactNumberQ[#1] & ) @@ 
       {NumericalFactor[FeynCalc`Isolate`Private`x]}, 
     FeynCalc`Isolate`Private`z_, FeynCalc`Isolate`Private`opts:
      OptionsPattern[]] := NumericalFactor[FeynCalc`Isolate`Private`x]*
      Isolate[FeynCalc`Isolate`Private`x/NumericalFactor[
         FeynCalc`Isolate`Private`x], FeynCalc`Isolate`Private`z, 
       FeynCalc`Isolate`Private`opts] /; FeynCalc`Isolate`Private`x =!= 0 && 
      ( !OptionQ[FeynCalc`Isolate`Private`z] || 
       FeynCalc`Isolate`Private`z === {})
 
Isolate[FeynCalc`Isolate`Private`ex_, FeynCalc`Isolate`Private`opts:
       OptionsPattern[] /; FeynCalc`Isolate`Private`opts =!= {}] := 
    Isolate[FeynCalc`Isolate`Private`ex, {}, FeynCalc`Isolate`Private`opts]
 
Isolate[FeynCalc`Isolate`Private`ex_, FeynCalc`Isolate`Private`var:
      Except[_?OptionQ], FeynCalc`Isolate`Private`opts:OptionsPattern[]] := 
    Isolate[FeynCalc`Isolate`Private`ex, {FeynCalc`Isolate`Private`var}, 
      FeynCalc`Isolate`Private`opts] /; 
     Head[FeynCalc`Isolate`Private`var] =!= List
 
Isolate[FeynCalc`Isolate`Private`exp_ /; 
      (#1 === 1 || #1 === 0 || InexactNumberQ[#1] & ) @@ 
       {NumericalFactor[FeynCalc`Isolate`Private`exp]}, 
     FeynCalc`Isolate`Private`vars_List, FeynCalc`Isolate`Private`opts:
      OptionsPattern[]] := Block[{FeynCalc`Isolate`Private`plush, 
      FeynCalc`Isolate`Private`vlist, FeynCalc`Isolate`Private`res, 
      FeynCalc`Isolate`Private`split, FeynCalc`Isolate`Private`kk, 
      FeynCalc`Isolate`Private`di = 1, FeynCalc`Isolate`Private`defhead, 
      FeynCalc`Isolate`Private`abbprint, 
      FeynCalc`Isolate`Private`holdformlist = {}, 
      FeynCalc`Isolate`Private`hres, FeynCalc`Isolate`Private`nhres, 
      FeynCalc`Isolate`Private`remche, FeynCalc`Isolate`Private`timesSplit, 
      FeynCalc`Isolate`Private`plusSplit, FeynCalc`Isolate`Private`tmpIso, 
      FeynCalc`Isolate`Private`tmpKeep, FeynCalc`Isolate`Private`isoIgnore, 
      FeynCalc`Isolate`Private`repRule}, FeynCalc`Isolate`Private`kk = 
       OptionValue[IsolateNames]; FeynCalc`Isolate`Private`abbprint = 
       OptionValue[IsolatePrint]; FeynCalc`Isolate`Private`split = 
       OptionValue[IsolateSplit]; FeynCalc`Isolate`Private`vlist = 
       Flatten[{FeynCalc`Isolate`Private`vars}]; 
      If[Head[FeynCalc`Isolate`Private`kk] === List, 
       FeynCalc`Isolate`Private`kk = Flatten[FeynCalc`Isolate`Private`kk]; 
        If[Length[Union[FeynCalc`Isolate`Private`kk]] =!= 
          Length[FeynCalc`Isolate`Private`kk], FeynCalc`Isolate`Private`kk = 
          Union[FeynCalc`Isolate`Private`kk]]; ]; 
      If[FeynCalc`Isolate`Private`abbprint === True, 
       FeynCalc`Isolate`Private`abbprint = OutputForm]; 
      FeynCalc`Isolate`Private`plush[FeynCalc`Isolate`Private`x__] := 
       If[ !FreeQ2[{FeynCalc`Isolate`Private`x}, 
          FeynCalc`Isolate`Private`vlist], If[OptionValue[IsolatePlus], 
         FeynCalc`Isolate`Private`plusSplit[FeynCalc`Isolate`Private`x], 
         Plus[FeynCalc`Isolate`Private`x]], 
        If[FeynCalc`Isolate`Private`checkIsolate[FeynCalc`Isolate`Private`x, 
            FeynCalc`Isolate`Private`split] === True && 
          Length[{FeynCalc`Isolate`Private`x}] > 4 && 
          FeynCalc`Isolate`Private`split =!= Infinity, 
         Isolate[Drop[Plus[FeynCalc`Isolate`Private`x], 
            Round[Length[Plus[FeynCalc`Isolate`Private`x]]/2]] + 
           Isolate[Take[Plus[FeynCalc`Isolate`Private`x], 
             Round[Length[Plus[FeynCalc`Isolate`Private`x]]/2]], 
            FeynCalc`Isolate`Private`vars, IsolatePrint -> False, 
            FeynCalc`Isolate`Private`opts], FeynCalc`Isolate`Private`vars, 
          IsolatePrint -> False, FeynCalc`Isolate`Private`opts], 
         If[Head[FeynCalc`Isolate`Private`kk] === List, 
          If[Union[Head /@ FeynCalc`Isolate`Private`kk] === {Plus}, 
            FeynCalc`Isolate`Private`kk = {}]; 
           FeynCalc`Isolate`Private`remIsolatesave[
             Plus[FeynCalc`Isolate`Private`x], 
             FeynCalc`Isolate`Private`kk] /. 
            FeynCalc`Isolate`Private`remIsolatesave -> 
             FeynCalc`Isolate`Private`remIsolate, 
          FeynCalc`Isolate`Private`remIsolate[
           Plus[FeynCalc`Isolate`Private`x], FeynCalc`Isolate`Private`kk]]]]; 
      FeynCalc`Isolate`Private`timesSplit[FeynCalc`Isolate`Private`x__] := 
       If[ !FreeQ2[{FeynCalc`Isolate`Private`x}, 
          Join[FeynCalc`Isolate`Private`vlist, 
           {FeynCalc`Isolate`Private`isoIgnore}]], 
        FeynCalc`Isolate`Private`tmpIso = SelectFree[
           {FeynCalc`Isolate`Private`x}, FeynCalc`Isolate`Private`isoIgnore, 
           Sequence @@ FeynCalc`Isolate`Private`vlist]; 
         FeynCalc`Isolate`Private`tmpKeep = SelectNotFree[
           {FeynCalc`Isolate`Private`x}, Sequence @@ 
            FeynCalc`Isolate`Private`vlist]; 
         If[FeynCalc`Isolate`Private`tmpIso === {} || 
            MatchQ[FeynCalc`Isolate`Private`tmpIso, {_?NumericQ}], 
           Times[Sequence @@ FeynCalc`Isolate`Private`tmpIso], 
           FeynCalc`Isolate`Private`remIsolate[Times[Sequence @@ 
              SelectFree[{FeynCalc`Isolate`Private`x}, 
               FeynCalc`Isolate`Private`isoIgnore, Sequence @@ 
                FeynCalc`Isolate`Private`vlist]], 
            FeynCalc`Isolate`Private`kk]]*(Times[Sequence @@ 
            SelectNotFree[{FeynCalc`Isolate`Private`x}, 
             FeynCalc`Isolate`Private`isoIgnore, Sequence @@ 
              FeynCalc`Isolate`Private`vlist]]), 
        FeynCalc`Isolate`Private`remIsolate[
         Times[FeynCalc`Isolate`Private`x], FeynCalc`Isolate`Private`kk]]; 
      FeynCalc`Isolate`Private`plusSplit[FeynCalc`Isolate`Private`x__] := 
       (FeynCalc`Isolate`Private`tmpIso = SelectFree[
          {FeynCalc`Isolate`Private`x}, Sequence @@ 
           FeynCalc`Isolate`Private`vlist, FeynCalc`Isolate`Private`kk]; 
        FeynCalc`Isolate`Private`tmpKeep = SelectNotFree[
          {FeynCalc`Isolate`Private`x}, Sequence @@ 
           FeynCalc`Isolate`Private`vlist, FeynCalc`Isolate`Private`kk]; 
        If[FeynCalc`Isolate`Private`tmpIso === {}, 0, 
          FeynCalc`Isolate`Private`remIsolate[Plus[Sequence @@ 
             FeynCalc`Isolate`Private`tmpIso], 
           FeynCalc`Isolate`Private`kk]] + (Plus[Sequence @@ 
           FeynCalc`Isolate`Private`tmpKeep])); 
      FeynCalc`Isolate`Private`res = FeynCalc`Isolate`Private`exp; 
      If[ !OptionValue[IsolateFast] || FeynCalc`Isolate`Private`vlist =!= {}, 
       FeynCalc`Isolate`Private`res = FeynCalc`Isolate`Private`exp /. 
          Plus -> FeynCalc`Isolate`Private`plush /. 
         FeynCalc`Isolate`Private`plush -> Plus]; 
      If[OptionValue[IsolateTimes], FeynCalc`Isolate`Private`repRule = 
         (#1 -> FeynCalc`Isolate`Private`isoIgnore[Unique[
              "isoIgnore"]] & ) /@ Union[Cases[FeynCalc`Isolate`Private`res, 
            HoldForm[__], Infinity]]; FeynCalc`Isolate`Private`res = 
         FeynCalc`Isolate`Private`res /. FeynCalc`Isolate`Private`repRule /. 
           Times -> FeynCalc`Isolate`Private`timesSplit /. 
          Reverse /@ FeynCalc`Isolate`Private`repRule]; 
      If[Head[FeynCalc`Isolate`Private`res] =!= HoldForm && 
        FeynCalc`Isolate`Private`vlist === {}, FeynCalc`Isolate`Private`res = 
        FeynCalc`Isolate`Private`remIsolate[FeynCalc`Isolate`Private`res, 
         FeynCalc`Isolate`Private`kk]]; 
      If[FeynCalc`Isolate`Private`abbprint =!= False, 
       FeynCalc`Isolate`Private`holdformlist = 
         Cases2[FeynCalc`Isolate`Private`res, HoldForm]; 
        FeynCalc`Isolate`Private`hres = ReleaseHold[
          FeynCalc`Isolate`Private`res]; 
        FeynCalc`Isolate`Private`holdformlist = 
         Join[FeynCalc`Isolate`Private`holdformlist, 
          Cases2[FeynCalc`Isolate`Private`hres, HoldForm]]; 
        While[(FeynCalc`Isolate`Private`nhres = ReleaseHold[
            FeynCalc`Isolate`Private`hres]) =!= 
          FeynCalc`Isolate`Private`hres, FeynCalc`Isolate`Private`hres = 
           FeynCalc`Isolate`Private`nhres; 
          FeynCalc`Isolate`Private`holdformlist = 
           Join[FeynCalc`Isolate`Private`holdformlist, 
            Cases2[FeynCalc`Isolate`Private`hres, HoldForm]]; ]; 
        FeynCalc`Isolate`Private`holdformlist = 
         Union[FeynCalc`Isolate`Private`holdformlist]; 
        FCPrint[0, "\n", UseWriteString -> True]; 
        For[FeynCalc`Isolate`Private`i = 1, FeynCalc`Isolate`Private`i <= 
          Length[FeynCalc`Isolate`Private`holdformlist], 
         FeynCalc`Isolate`Private`i++, FCPrint[0, "       ", 
           FeynCalc`Isolate`Private`holdformlist[[
            FeynCalc`Isolate`Private`i]], " = ", 
           FeynCalc`Isolate`Private`abbprint[ReleaseHold[
             FeynCalc`Isolate`Private`holdformlist[[
              FeynCalc`Isolate`Private`i]]]]]; FCPrint[0, "\n", 
           UseWriteString -> True]; ]; ]; FeynCalc`Isolate`Private`res]
 
Options[Isolate] = {IsolateFast -> False, IsolateNames -> KK, 
     IsolatePlus -> False, IsolatePrint -> False, IsolateSplit -> Infinity, 
     IsolateTimes -> False}
 
Isolate /: Isolate::usage = "Isolate[expr] substitutes abbreviations KK[i] \
for all Plus[...] (sub-sums) in\nexpr. The inserted KK[i] have head HoldForm. \
Isolate[expr, varlist]\nsubstitutes KK[i] for all subsums in expr which are \
free of any occurrence of\na member of the list varlist. Instead of KK any \
other head or a list of names\nof the abbreviations may be specified with the \
option IsolateNames."
 
IsolatePrint /: IsolatePrint::usage = "IsolatePrint is an option of Isolate. \
If it is set to OutputForm (or any other\n*Form) the definitions of the \
abbreviations are printed during the operation\nof Isolate.\n\nThe setting \
IsolatePrint -> False suppresses printing."
 
IsolateSplit /: IsolateSplit::usage = "IsolateSplit is an option for Isolate. \
Its setting determines the maximum\nnumber of characters of FortranForm[expr] \
which are abbreviated by Isolate. If\nthe expression is larger than the \
indicated number, it is split into smaller\npieces and onto each subsum \
Isolate is applied.\n\nWith the default setting IsolateSplit -> Infinity no \
splitting is done."
 
IsolatePlus /: IsolatePlus::usage = "IsolatePlus is an option for Isolate and \
other functions using Isolate. If it\nis set to True, Isolate will split sums \
that contain elements from vlist, to\nbe able to abbreviate the vlist-free \
part."
 
FeynCalc`Isolate`Private`checkIsolate[FeynCalc`Isolate`Private`x__, 
     FeynCalc`Isolate`Private`i_] := If[Head[FeynCalc`Isolate`Private`i] === 
      Integer, If[Length[Characters[ToString[FortranForm[
           Plus[FeynCalc`Isolate`Private`x]]]]] > FeynCalc`Isolate`Private`i, 
      True, False], If[Head[FeynCalc`Isolate`Private`i] === Complex, 
      If[Length[{FeynCalc`Isolate`Private`x}] > 
        Im[FeynCalc`Isolate`Private`i], True, False, False], False]]
 
FeynCalc`Isolate`Private`remIsolate[FeynCalc`Isolate`Private`x_, {}] := 
    FeynCalc`Isolate`Private`remIsolate[FeynCalc`Isolate`Private`x, 
     If[Head[IsolateNames /. Options[Isolate]] === List, KK, 
      IsolateNames /. Options[Isolate]]]
 
FeynCalc`Isolate`Private`remIsolate[FeynCalc`Isolate`Private`x_, 
     {___Times, FeynCalc`Isolate`Private`abb_ /; 
       Head[FeynCalc`Isolate`Private`abb] =!= Times, ___}] := 
    Block[{FeynCalc`Isolate`Private`re}, FeynCalc`Isolate`Private`re = 
       HoldForm @@ {FeynCalc`Isolate`Private`abb}; 
      Set @@ {FeynCalc`Isolate`Private`abb, FeynCalc`Isolate`Private`x}; 
      Set @@ {FeynCalc`Isolate`Private`remIsolatesave[
         FeynCalc`Isolate`Private`x, _], FeynCalc`Isolate`Private`re}; 
      FeynCalc`Isolate`Private`re]
 
FeynCalc`Isolate`Private`remIsolate[FeynCalc`Isolate`Private`x_, 
     {___Plus, FeynCalc`Isolate`Private`abb_ /; 
       Head[FeynCalc`Isolate`Private`abb] =!= Plus, ___}] := 
    Block[{FeynCalc`Isolate`Private`re}, FeynCalc`Isolate`Private`re = 
       HoldForm @@ {FeynCalc`Isolate`Private`abb}; 
      Set @@ {FeynCalc`Isolate`Private`abb, FeynCalc`Isolate`Private`x}; 
      Set @@ {FeynCalc`Isolate`Private`remIsolatesave[
         FeynCalc`Isolate`Private`x, _], FeynCalc`Isolate`Private`re}; 
      FeynCalc`Isolate`Private`re]
 
FeynCalc`Isolate`Private`remIsolate[FeynCalc`Isolate`Private`x_, 
     FeynCalc`Isolate`Private`abb_ /; Head[FeynCalc`Isolate`Private`abb] =!= 
       List] := Block[{FeynCalc`Isolate`Private`re, 
      FeynCalc`Isolate`Private`h, FeynCalc`Isolate`Private`temp}, 
     If[Length[FeynCalc`Isolate`Private`re = Select[DownValues @@ 
            {FeynCalc`Isolate`Private`abb}, 
           #1[[2]] === FeynCalc`Isolate`Private`x & ]] > 0, 
       FeynCalc`Isolate`Private`re = FeynCalc`Isolate`Private`re[[1,1]] /. 
         {Literal :> HoldForm, HoldPattern :> HoldForm}, 
       If[Head[FeynCalc`Isolate`Private`abb] === Symbol, 
         FeynCalc`Isolate`Private`temp = FeynCalc`Isolate`Private`tokIsolate[
           FeynCalc`Isolate`Private`uni[ToString[
              FeynCalc`Isolate`Private`abb]] /. 
            FeynCalc`Isolate`Private`uni -> Unique, 
           FeynCalc`Isolate`Private`abb, FeynCalc`Isolate`Private`abb], 
         FeynCalc`Isolate`Private`temp = FeynCalc`Isolate`Private`tokIsolate[
           Unique["dude"], FeynCalc`Isolate`Private`abb, "dude"]]; 
        FeynCalc`Isolate`Private`re = HoldForm @@ 
          {FeynCalc`Isolate`Private`temp}; 
        Set @@ {FeynCalc`Isolate`Private`temp, FeynCalc`Isolate`Private`x}]; 
      FeynCalc`Isolate`Private`re]
 
KK /: KK::usage = "KK[i] is the default setting of IsolateNames, which is the \
head of\nabbreviations used by Isolate. A KK[i] returned by Isolate is given \
in\nHoldForm and can be recovered by ReleaseHold[KK[i]]."
 
FeynCalc`Isolate`Private`tokIsolate[FeynCalc`Isolate`Private`y_, 
     FeynCalc`Isolate`Private`ab_, FeynCalc`Isolate`Private`uh_] := 
    FeynCalc`Isolate`Private`ab[ToExpression[StringJoin @@ 
       Drop[Characters[ToString[FeynCalc`Isolate`Private`y]], 
        Length[Characters[ToString[FeynCalc`Isolate`Private`uh]]]]]]
 
IsolateTimes /: IsolateTimes::usage = "IsolateTimes is an option for Isolate \
and other functions using Isolate. If it\nis set to True, Isolate will be \
applied also to pure products."
 
ComplexConjugate[FeynCalc`ComplexConjugate`Private`expr_List, 
     FeynCalc`ComplexConjugate`Private`opts:OptionsPattern[]] := 
    (ComplexConjugate[#1, FeynCalc`ComplexConjugate`Private`opts] & ) /@ 
     FeynCalc`ComplexConjugate`Private`expr
 
ComplexConjugate[(FeynCalc`ComplexConjugate`Private`a_) == 
      (FeynCalc`ComplexConjugate`Private`b_), 
     FeynCalc`ComplexConjugate`Private`opts:OptionsPattern[]] := 
    ComplexConjugate[FeynCalc`ComplexConjugate`Private`a, 
      FeynCalc`ComplexConjugate`Private`opts] == ComplexConjugate[
      FeynCalc`ComplexConjugate`Private`b, 
      FeynCalc`ComplexConjugate`Private`opts]
 
ComplexConjugate[(FeynCalc`ComplexConjugate`Private`h:Rule | RuleDelayed)[
      FeynCalc`ComplexConjugate`Private`a_, 
      FeynCalc`ComplexConjugate`Private`b_], 
     FeynCalc`ComplexConjugate`Private`opts:OptionsPattern[]] := 
    FeynCalc`ComplexConjugate`Private`hold[ComplexConjugate[
       FeynCalc`ComplexConjugate`Private`a, 
       FeynCalc`ComplexConjugate`Private`opts], ComplexConjugate[
       FeynCalc`ComplexConjugate`Private`b, 
       FeynCalc`ComplexConjugate`Private`opts]] /. 
     FeynCalc`ComplexConjugate`Private`hold -> 
      FeynCalc`ComplexConjugate`Private`h
 
ComplexConjugate[FeynCalc`ComplexConjugate`Private`expr_ /; 
       !MemberQ[{List, Equal, Rule, RuleDelayed}, 
        Head[FeynCalc`ComplexConjugate`Private`expr]], OptionsPattern[]] := 
    Block[{FeynCalc`ComplexConjugate`Private`ex, 
      FeynCalc`ComplexConjugate`Private`res, 
      FeynCalc`ComplexConjugate`Private`optConjugate, 
      FeynCalc`ComplexConjugate`Private`ruleConjugate, 
      FeynCalc`ComplexConjugate`Private`ru, 
      FeynCalc`ComplexConjugate`Private`time, 
      FeynCalc`ComplexConjugate`Private`prefList, 
      FeynCalc`ComplexConjugate`Private`diracList, 
      FeynCalc`ComplexConjugate`Private`sunList, 
      FeynCalc`ComplexConjugate`Private`pauliList, 
      FeynCalc`ComplexConjugate`Private`prefHead, 
      FeynCalc`ComplexConjugate`Private`pauliHead, 
      FeynCalc`ComplexConjugate`Private`sunHead, 
      FeynCalc`ComplexConjugate`Private`diracHead, 
      FeynCalc`ComplexConjugate`Private`prefListEval, 
      FeynCalc`ComplexConjugate`Private`diracListEval, 
      FeynCalc`ComplexConjugate`Private`sunListEval, 
      FeynCalc`ComplexConjugate`Private`pauliListEval, 
      FeynCalc`ComplexConjugate`Private`repRule, 
      FeynCalc`ComplexConjugate`Private`ccRules, 
      FeynCalc`ComplexConjugate`Private`pattern, 
      FeynCalc`ComplexConjugate`Private`blank}, 
     FeynCalc`ComplexConjugate`Private`optConjugate = OptionValue[Conjugate]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`ComplexConjugate`Private`ccjVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`ComplexConjugate`Private`ccjVerbose = 
          OptionValue[FCVerbose]]; ]; FCPrint[1, 
       "ComplexConjugate: Entering.", FCDoControl -> 
        FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FCPrint[3, "ComplexConjugate: Entering with: ", 
       FeynCalc`ComplexConjugate`Private`expr, FCDoControl -> 
        FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      If[ !OptionValue[FCI], FeynCalc`ComplexConjugate`Private`ex = 
        FCI[FeynCalc`ComplexConjugate`Private`expr], 
       FeynCalc`ComplexConjugate`Private`ex = 
        FeynCalc`ComplexConjugate`Private`expr]; 
      FeynCalc`ComplexConjugate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "ComplexConjugate: Applying FCMatrixIsolate.", 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`ex = FCMatrixIsolate[
        FeynCalc`ComplexConjugate`Private`ex, FCI -> True, 
        FCColorIsolate -> {FeynCalc`ComplexConjugate`Private`sunHead}, 
        FCDiracIsolate -> {FeynCalc`ComplexConjugate`Private`diracHead, 
          {FCI -> True, DiracChain -> True, Expanding -> False, 
           FCJoinDOTs -> False, DiracSigmaExplicit -> True, 
           DiracGammaCombine -> False}}, FCPauliIsolate -> 
         {FeynCalc`ComplexConjugate`Private`pauliHead, PauliChain -> True}, 
        Head -> FeynCalc`ComplexConjugate`Private`prefHead]; 
      FCPrint[1, "ComplexConjugate: Done applying FCMatrixIsolate, timing: ", 
       N[AbsoluteTime[] - FeynCalc`ComplexConjugate`Private`time, 4], 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FCPrint[3, "ComplexConjugate: After FCMatrixIsolate: ", 
       FeynCalc`ComplexConjugate`Private`ex, FCDoControl -> 
        FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "ComplexConjugate: Checking the spinor syntax.", 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      If[FeynCalc`Package`spinorSyntaxCorrectQ[
         FeynCalc`ComplexConjugate`Private`ex] =!= True, 
       Message[FermionSpinSum::failmsg, 
         "The input contains Spinor objects with incorrect syntax."]; 
        Abort[]]; FeynCalc`ComplexConjugate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "ComplexConjugate: Applying additional isolations.", 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`ex = 
       FeynCalc`ComplexConjugate`Private`ex /. 
           {FeynCalc`ComplexConjugate`Private`diracHead[
               FeynCalc`ComplexConjugate`Private`z_] /;  !FreeQ2[
                FeynCalc`ComplexConjugate`Private`z, Join[
                 FeynCalc`Package`PauliHeadsList, 
                 FeynCalc`Package`SUNHeadsList]] :> FCMatrixIsolate[
              DotSimplify[FeynCalc`ComplexConjugate`Private`z, FCI -> True], 
              FCI -> True, FCColorIsolate -> {
                FeynCalc`ComplexConjugate`Private`sunHead}, FCDiracIsolate -> 
               {FeynCalc`ComplexConjugate`Private`diracHead, {FCI -> True, 
                 DiracChain -> True, Expanding -> False, FCJoinDOTs -> False, 
                 DiracSigmaExplicit -> True, DiracGammaCombine -> False}}, 
              FCPauliIsolate -> {FeynCalc`ComplexConjugate`Private`pauliHead, 
                PauliChain -> True}, Head -> 
               FeynCalc`ComplexConjugate`Private`prefHead]} /. 
          {FeynCalc`ComplexConjugate`Private`pauliHead[
              FeynCalc`ComplexConjugate`Private`z_] /; 
              !FreeQ2[FeynCalc`ComplexConjugate`Private`z, Join[
                FeynCalc`Package`DiracHeadsList, 
                FeynCalc`Package`SUNHeadsList, 
                {FCChargeConjugateTransposed}]] :> FCMatrixIsolate[
             DotSimplify[FeynCalc`ComplexConjugate`Private`z, FCI -> True], 
             FCI -> True, FCColorIsolate -> 
              {FeynCalc`ComplexConjugate`Private`sunHead}, FCDiracIsolate -> 
              {FeynCalc`ComplexConjugate`Private`diracHead, {FCI -> True, 
                DiracChain -> True, Expanding -> False, FCJoinDOTs -> False, 
                DiracSigmaExplicit -> True, DiracGammaCombine -> False}}, 
             FCPauliIsolate -> {FeynCalc`ComplexConjugate`Private`pauliHead, 
               PauliChain -> True}, Head -> 
              FeynCalc`ComplexConjugate`Private`prefHead]} /. 
         {FeynCalc`ComplexConjugate`Private`sunHead[
             FeynCalc`ComplexConjugate`Private`z_] /; 
             !FreeQ2[FeynCalc`ComplexConjugate`Private`z, 
              Join[FeynCalc`Package`DiracHeadsList, 
               FeynCalc`Package`PauliHeadsList]] :> FCMatrixIsolate[
            DotSimplify[FeynCalc`ComplexConjugate`Private`z, FCI -> True], 
            FCI -> True, FCColorIsolate -> 
             {FeynCalc`ComplexConjugate`Private`sunHead}, FCDiracIsolate -> 
             {FeynCalc`ComplexConjugate`Private`diracHead, {FCI -> True, 
               DiracChain -> True, Expanding -> False, FCJoinDOTs -> False, 
               DiracSigmaExplicit -> True, DiracGammaCombine -> False}}, 
            FCPauliIsolate -> {FeynCalc`ComplexConjugate`Private`pauliHead, 
              PauliChain -> True}, Head -> 
             FeynCalc`ComplexConjugate`Private`prefHead]} /. 
        {FeynCalc`ComplexConjugate`Private`prefHead[
            FeynCalc`ComplexConjugate`Private`z_] /; 
            !FreeQ2[FeynCalc`ComplexConjugate`Private`z, 
             Join[FeynCalc`Package`DiracHeadsList, 
              FeynCalc`Package`PauliHeadsList, FeynCalc`Package`SUNHeadsList, 
              {DOT}]] :> FCMatrixIsolate[DotSimplify[
            FeynCalc`ComplexConjugate`Private`z, FCI -> True], FCI -> True, 
           FCColorIsolate -> {FeynCalc`ComplexConjugate`Private`sunHead}, 
           FCDiracIsolate -> {FeynCalc`ComplexConjugate`Private`diracHead, 
             {FCI -> True, DiracChain -> True, Expanding -> False, 
              FCJoinDOTs -> False, DiracSigmaExplicit -> True, 
              DiracGammaCombine -> False}}, FCPauliIsolate -> 
            {FeynCalc`ComplexConjugate`Private`pauliHead, PauliChain -> 
              True}, Head -> FeynCalc`ComplexConjugate`Private`prefHead]}; 
      FCPrint[1, 
       "ComplexConjugate: Done applying additional isolations, timing: ", 
       N[AbsoluteTime[] - FeynCalc`ComplexConjugate`Private`time, 4], 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FCPrint[3, "ComplexConjugate: After additional isolations: ", 
       FeynCalc`ComplexConjugate`Private`ex, FCDoControl -> 
        FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`prefList = 
       Cases2[FeynCalc`ComplexConjugate`Private`ex, 
        FeynCalc`ComplexConjugate`Private`prefHead]; 
      FeynCalc`ComplexConjugate`Private`diracList = 
       Cases2[FeynCalc`ComplexConjugate`Private`ex, 
        FeynCalc`ComplexConjugate`Private`diracHead]; 
      FeynCalc`ComplexConjugate`Private`pauliList = 
       Cases2[FeynCalc`ComplexConjugate`Private`ex, 
        FeynCalc`ComplexConjugate`Private`pauliHead]; 
      FeynCalc`ComplexConjugate`Private`sunList = 
       Cases2[FeynCalc`ComplexConjugate`Private`ex, 
        FeynCalc`ComplexConjugate`Private`sunHead]; 
      If[ !FreeQ2[FeynCalc`ComplexConjugate`Private`prefList, 
         Join[FeynCalc`Package`DiracHeadsList, 
          FeynCalc`Package`PauliHeadsList, FeynCalc`Package`SUNHeadsList, 
          {DOT}]], Message[ComplexConjugate::warnmsg, "The list of prefactors \
contains Dirac, Pauli or SU(N) symbols. Their correct complex conjugation is \
not guaranteed."]]; If[ !FreeQ2[FeynCalc`ComplexConjugate`Private`diracList, 
         Join[FeynCalc`Package`PauliHeadsList, 
          FeynCalc`Package`SUNHeadsList]], Message[ComplexConjugate::warnmsg, 
        "The list of Dirac chains contains Pauli or SU(N) symbols. Their \
correct complex conjugation is not guaranteed."]]; 
      If[ !FreeQ2[FeynCalc`ComplexConjugate`Private`pauliList, 
         Join[FeynCalc`Package`DiracHeadsList, FeynCalc`Package`SUNHeadsList, 
          {FCChargeConjugateTransposed}]], Message[ComplexConjugate::warnmsg, 
        "The list of Pauli chains contains Dirac or SU(N) symbols. Their \
correct complex conjugation is not guaranteed."]]; 
      If[ !FreeQ2[FeynCalc`ComplexConjugate`Private`sunList, 
         Join[FeynCalc`Package`DiracHeadsList, 
          FeynCalc`Package`PauliHeadsList]], 
       Message[ComplexConjugate::warnmsg, "The list of SU(N) chains contains \
Dirac or Pauli symbols. Their correct complex conjugation is not guaranteed."]\
]; FeynCalc`ComplexConjugate`Private`diracListEval = 
       FeynCalc`ComplexConjugate`Private`diracChainCC /@ 
         (FeynCalc`ComplexConjugate`Private`diracList /. 
           DOT -> FeynCalc`ComplexConjugate`Private`holdDOT /. 
          FeynCalc`ComplexConjugate`Private`diracHead -> Identity) /. 
        {FeynCalc`ComplexConjugate`Private`holdDOTReversed -> DOT, 
         FeynCalc`ComplexConjugate`Private`diracGammaHold -> DiracGamma}; 
      FCPrint[3, "ComplexConjugate: After diracChainCC: ", 
       FeynCalc`ComplexConjugate`Private`diracListEval, 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`pauliListEval = 
       FeynCalc`ComplexConjugate`Private`pauliChainCC /@ 
         (FeynCalc`ComplexConjugate`Private`pauliList /. 
           DOT -> FeynCalc`ComplexConjugate`Private`holdDOT /. 
          FeynCalc`ComplexConjugate`Private`pauliHead -> Identity) /. 
        FeynCalc`ComplexConjugate`Private`holdDOTReversed -> DOT; 
      FCPrint[3, "ComplexConjugate: After pauliChainCC: ", 
       FeynCalc`ComplexConjugate`Private`pauliListEval, 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`sunListEval = 
       FeynCalc`ComplexConjugate`Private`sunChainCC /@ 
         (FeynCalc`ComplexConjugate`Private`sunList /. 
           DOT -> FeynCalc`ComplexConjugate`Private`holdDOT /. 
          FeynCalc`ComplexConjugate`Private`sunHead -> Identity) /. 
        FeynCalc`ComplexConjugate`Private`holdDOTReversed -> DOT; 
      FCPrint[3, "ComplexConjugate: After sunChainCC: ", 
       FeynCalc`ComplexConjugate`Private`sunListEval, 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      FeynCalc`ComplexConjugate`Private`prefListEval = 
       FeynCalc`ComplexConjugate`Private`prefCC /@ 
        (FeynCalc`ComplexConjugate`Private`prefList /. 
         FeynCalc`ComplexConjugate`Private`prefHead -> Identity); 
      FCPrint[3, "ComplexConjugate: After prefCC: ", 
       FeynCalc`ComplexConjugate`Private`prefListEval, 
       FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
      If[OptionValue[DotSimplify], FeynCalc`ComplexConjugate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "ComplexConjugate: Applying DotSimplify.", FCDoControl -> 
          FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
        FeynCalc`ComplexConjugate`Private`diracListEval = 
         (DotSimplify[#1, FCI -> True, Expanding -> False] & ) /@ 
          FeynCalc`ComplexConjugate`Private`diracListEval; 
        FeynCalc`ComplexConjugate`Private`pauliListEval = 
         (DotSimplify[#1, FCI -> True, Expanding -> False] & ) /@ 
          FeynCalc`ComplexConjugate`Private`pauliListEval; 
        FeynCalc`ComplexConjugate`Private`sunListEval = 
         (DotSimplify[#1, FCI -> True, Expanding -> False] & ) /@ 
          FeynCalc`ComplexConjugate`Private`sunListEval; 
        FCPrint[1, "ComplexConjugate: Done applying DotSimplify, timing: ", 
         N[AbsoluteTime[] - FeynCalc`ComplexConjugate`Private`time, 4], 
         FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
        FCPrint[3, "ComplexConjugate: Dirac list after DotSimplify: ", 
         FeynCalc`ComplexConjugate`Private`diracListEval, 
         FCDoControl -> FeynCalc`ComplexConjugate`Private`ccjVerbose]; 
        FCPrint[3, "ComplexConjugate: Pauli list after DotSimplify: ", 
         FeynCalc`ComplexConjugate`Private`pauliListEval, 
