      FeynCalc`ComplexConjugate`Private`repRule = 
       Join[Thread[FeynCalc`ComplexConjugate`Private`diracList -> 
           FeynCalc`ComplexConjugate`Private`diracListEval], 
         Thread[FeynCalc`ComplexConjugate`Private`pauliList -> 
           FeynCalc`ComplexConjugate`Private`pauliListEval], 
         Thread[FeynCalc`ComplexConjugate`Private`sunList -> 
           FeynCalc`ComplexConjugate`Private`sunListEval], 
         Thread[FeynCalc`ComplexConjugate`Private`prefList -> 
           FeynCalc`ComplexConjugate`Private`prefListEval]] /. 
        {Pattern -> FeynCalc`ComplexConjugate`Private`pattern, 
         Blank -> FeynCalc`ComplexConjugate`Private`blank}; 
      FeynCalc`ComplexConjugate`Private`res = 
       FeynCalc`ComplexConjugate`Private`ex /. 
          {Pattern -> FeynCalc`ComplexConjugate`Private`pattern, 
           Blank -> FeynCalc`ComplexConjugate`Private`blank} /. 
         Dispatch[FeynCalc`ComplexConjugate`Private`repRule] /. 
        {FeynCalc`ComplexConjugate`Private`pattern -> Pattern, 
         FeynCalc`ComplexConjugate`Private`blank -> Blank}; 
