    FeynCalc`ComplexConjugate`Private`hold::usage = ""
 
FeynCalc`ComplexConjugate`Private`ccjVerbose /: 
    FeynCalc`ComplexConjugate`Private`ccjVerbose::usage = ""
 
FCMatrixIsolate[FeynCalc`FCMatrixIsolate`Private`expr_List, 
     FeynCalc`FCMatrixIsolate`Private`opts:OptionsPattern[]] := 
    (FCMatrixIsolate[#1, FeynCalc`FCMatrixIsolate`Private`opts] & ) /@ 
     FeynCalc`FCMatrixIsolate`Private`expr
 
FCMatrixIsolate[FeynCalc`FCMatrixIsolate`Private`expr_ /; 
      Head[FeynCalc`FCMatrixIsolate`Private`expr] =!= List, 
     OptionsPattern[]] := Block[{FeynCalc`FCMatrixIsolate`Private`res, 
      FeynCalc`FCMatrixIsolate`Private`ex, 
      FeynCalc`FCMatrixIsolate`Private`optHead, 
      FeynCalc`FCMatrixIsolate`Private`optOrdering, 
      FeynCalc`FCMatrixIsolate`Private`time, 
      FeynCalc`FCMatrixIsolate`Private`optFCDiracIsolate, 
      FeynCalc`FCMatrixIsolate`Private`optFCPauliIsolate, 
      FeynCalc`FCMatrixIsolate`Private`optFCColorIsolate}, 
     FeynCalc`FCMatrixIsolate`Private`optHead = OptionValue[Head]; 
      FeynCalc`FCMatrixIsolate`Private`optOrdering = OptionValue[Ordering]; 
      FeynCalc`FCMatrixIsolate`Private`optFCDiracIsolate = 
       OptionValue[FCDiracIsolate]; 
      FeynCalc`FCMatrixIsolate`Private`optFCPauliIsolate = 
       OptionValue[FCPauliIsolate]; 
      FeynCalc`FCMatrixIsolate`Private`optFCColorIsolate = 
       OptionValue[FCColorIsolate]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCMatrixIsolate`Private`fcmiVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCMatrixIsolate`Private`fcmiVerbose = 
          OptionValue[FCVerbose]]; ]; 
      If[ !MatchQ[FeynCalc`FCMatrixIsolate`Private`optOrdering, {__}] || 
         !SubsetQ[{FCDiracIsolate, FCColorIsolate, FCPauliIsolate}, 
          Union[FeynCalc`FCMatrixIsolate`Private`optOrdering]], 
       Message[FCMatrixIsolate::failmsg, 
         "The value of the Ordering option is incorrect."]; Abort[]]; 
      If[Head[FeynCalc`FCMatrixIsolate`Private`optFCDiracIsolate] =!= List || 
        Head[FeynCalc`FCMatrixIsolate`Private`optFCPauliIsolate] =!= List || 
        Head[FeynCalc`FCMatrixIsolate`Private`optFCColorIsolate] =!= List, 
       Message[FCMatrixIsolate::failmsg, 
         "The option values of the isolating function must be given as \
lists."]; Abort[]]; If[OptionValue[FCI], 
       FeynCalc`FCMatrixIsolate`Private`ex = 
        FeynCalc`FCMatrixIsolate`Private`expr, 
       FeynCalc`FCMatrixIsolate`Private`ex = 
        FCI[FeynCalc`FCMatrixIsolate`Private`expr]]; 
      FCPrint[1, "FCMatrixIsolate: Entering.", FCDoControl -> 
        FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FCPrint[3, "FCMatrixIsolate: Entering with: ", 
       FeynCalc`FCMatrixIsolate`Private`expr, FCDoControl -> 
        FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FeynCalc`FCMatrixIsolate`Private`diracHead = 
       FeynCalc`FCMatrixIsolate`Private`optFCDiracIsolate[[1]]; 
      FeynCalc`FCMatrixIsolate`Private`pauliHead = 
       FeynCalc`FCMatrixIsolate`Private`optFCPauliIsolate[[1]]; 
      FeynCalc`FCMatrixIsolate`Private`sunHead = 
       FeynCalc`FCMatrixIsolate`Private`optFCColorIsolate[[1]]; 
      If[Length[FeynCalc`FCMatrixIsolate`Private`optFCDiracIsolate] === 1, 
       FeynCalc`FCMatrixIsolate`Private`optsDirac = 
        FilterRules[Options[FCMatrixIsolate], FCDiracIsolate][[1]][[2]][[2]], 
       FeynCalc`FCMatrixIsolate`Private`optsDirac = 
        FilterRules[FeynCalc`FCMatrixIsolate`Private`optFCDiracIsolate[[2]], 
         Except[Head]]]; 
      If[Length[FeynCalc`FCMatrixIsolate`Private`optFCPauliIsolate] === 1, 
       FeynCalc`FCMatrixIsolate`Private`optsPauli = 
