       FeynCalc`FCMatrixIsolate`Private`optsPauli = 
        FilterRules[FeynCalc`FCMatrixIsolate`Private`optFCPauliIsolate[[2]], 
         Except[Head]]]; 
      If[Length[FeynCalc`FCMatrixIsolate`Private`optFCColorIsolate] === 1, 
       FeynCalc`FCMatrixIsolate`Private`optsSUN = 
        FilterRules[Options[FCMatrixIsolate], FCColorIsolate][[1]][[2]][[2]], 
       FeynCalc`FCMatrixIsolate`Private`optsSUN = FilterRules[
         FeynCalc`FCMatrixIsolate`Private`optFCColorIsolate[[2]], 
         Except[Head]]]; FCPrint[1, 
       "FCMatrixIsolate: Ordering of isolations: ", 
       FeynCalc`FCMatrixIsolate`Private`optOrdering, 
       FCDoControl -> FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FeynCalc`FCMatrixIsolate`Private`optOrdering = 
       FeynCalc`FCMatrixIsolate`Private`optOrdering /. 
        {FCDiracIsolate -> FeynCalc`FCMatrixIsolate`Private`isolateDirac, 
         FCPauliIsolate -> FeynCalc`FCMatrixIsolate`Private`isolatePauli, 
         FCColorIsolate -> FeynCalc`FCMatrixIsolate`Private`isolateSUN}; 
      FeynCalc`FCMatrixIsolate`Private`ex = 
       FeynCalc`FCMatrixIsolate`Private`relevantPart[
        FeynCalc`FCMatrixIsolate`Private`ex]; 
      FeynCalc`FCMatrixIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCMatrixIsolate: Applying isolating functions.", 
       FCDoControl -> FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FeynCalc`FCMatrixIsolate`Private`ex = Fold[#2[#1] & , 
        FeynCalc`FCMatrixIsolate`Private`ex, 
        FeynCalc`FCMatrixIsolate`Private`optOrdering]; 
      FCPrint[1, 
       "FCMatrixIsolate: Done applying isolating functions, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCMatrixIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FCPrint[3, "FCMatrixIsolate: After applying isolating functions: ", 
       FeynCalc`FCMatrixIsolate`Private`ex, FCDoControl -> 
        FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FeynCalc`FCMatrixIsolate`Private`res = 
       FeynCalc`FCMatrixIsolate`Private`ex /. 
        FeynCalc`FCMatrixIsolate`Private`relevantPart -> OptionValue[Head]; 
