FCDiracIsolate[FeynCalc`FCDiracIsolate`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`FCDiracIsolate`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`FCDiracIsolate`Private`res, 
      FeynCalc`FCDiracIsolate`Private`null1, 
      FeynCalc`FCDiracIsolate`Private`null2, 
      FeynCalc`FCDiracIsolate`Private`ex, 
      FeynCalc`FCDiracIsolate`Private`tmp, 
      FeynCalc`FCDiracIsolate`Private`head, 
      FeynCalc`FCDiracIsolate`Private`selectionList, 
      FeynCalc`FCDiracIsolate`Private`time, 
      FeynCalc`FCDiracIsolate`Private`fcdiVerbose, 
      FeynCalc`FCDiracIsolate`Private`headsList, 
      FeynCalc`FCDiracIsolate`Private`headsOrig, 
      FeynCalc`FCDiracIsolate`Private`optTimeConstrained, 
      FeynCalc`FCDiracIsolate`Private`optHead, 
      FeynCalc`FCDiracIsolate`Private`headR, 
      FeynCalc`FCDiracIsolate`Private`allHeads, 
      FeynCalc`FCDiracIsolate`Private`allHeadsEval, 
      FeynCalc`FCDiracIsolate`Private`headNoMatrix, 
      FeynCalc`FCDiracIsolate`Private`collectList, 
      FeynCalc`FCDiracIsolate`Private`optSplit, 
      FeynCalc`FCDiracIsolate`Private`aux}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCDiracIsolate`Private`fcdiVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCDiracIsolate`Private`fcdiVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCDiracIsolate`Private`optTimeConstrained = 
       OptionValue[TimeConstrained]; 
      FeynCalc`FCDiracIsolate`Private`optSplit = OptionValue[Split]; 
      FeynCalc`FCDiracIsolate`Private`headsOrig = 
       Complement[FeynCalc`Package`DiracHeadsList, OptionValue[ExceptHeads]]; 
      FeynCalc`FCDiracIsolate`Private`headsList = 
       FeynCalc`FCDiracIsolate`Private`headsOrig; 
      FeynCalc`FCDiracIsolate`Private`collectList = 
       FeynCalc`FCDiracIsolate`Private`headsList; 
      If[OptionValue[Polarization], 
       FeynCalc`FCDiracIsolate`Private`headsList = 
         Join[FeynCalc`FCDiracIsolate`Private`headsList, {Polarization}]; ]; 
      If[OptionValue[LorentzIndex] === All, 
       FeynCalc`FCDiracIsolate`Private`headsList = 
         Join[FeynCalc`FCDiracIsolate`Private`headsList, {LorentzIndex}]; ]; 
      If[OptionValue[CartesianIndex] === All, 
       FeynCalc`FCDiracIsolate`Private`headsList = 
         Join[FeynCalc`FCDiracIsolate`Private`headsList, 
          {CartesianIndex}]; ]; If[OptionValue[Polarization] =!= False, 
       FeynCalc`FCDiracIsolate`Private`collectList = 
        Join[FeynCalc`FCDiracIsolate`Private`collectList, {Polarization}]]; 
      If[OptionValue[LorentzIndex] =!= False, 
       FeynCalc`FCDiracIsolate`Private`collectList = 
        Join[FeynCalc`FCDiracIsolate`Private`collectList, {LorentzIndex}]]; 
      If[OptionValue[CartesianIndex] =!= False, 
       FeynCalc`FCDiracIsolate`Private`collectList = 
        Join[FeynCalc`FCDiracIsolate`Private`collectList, {CartesianIndex}]]; 
      FeynCalc`FCDiracIsolate`Private`optHead = OptionValue[Head]; 
