       FeynCalc`FCDiracIsolate`Private`head = 
         FeynCalc`FCDiracIsolate`Private`optHead; 
        FeynCalc`FCDiracIsolate`Private`headR = Identity]; 
      If[OptionValue[FCI], FeynCalc`FCDiracIsolate`Private`ex = 
        FeynCalc`FCDiracIsolate`Private`expr /. (#1 -> Identity & ) /@ 
          OptionValue[ClearHeads], FeynCalc`FCDiracIsolate`Private`ex = 
        FCI[FeynCalc`FCDiracIsolate`Private`expr] /. (#1 -> Identity & ) /@ 
          OptionValue[ClearHeads]]; FCPrint[3, 
       "FCDiracIsolate: Entering with: ", FeynCalc`FCDiracIsolate`Private`ex, 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      If[FreeQ2[FeynCalc`FCDiracIsolate`Private`ex, 
        FeynCalc`FCDiracIsolate`Private`headsList], 
       Return[FeynCalc`FCDiracIsolate`Private`restHead[
          FeynCalc`FCDiracIsolate`Private`ex] /. 
         FeynCalc`FCDiracIsolate`Private`restHead -> 
          FeynCalc`FCDiracIsolate`Private`headR]]; 
      If[OptionValue[DiracSigmaExplicit], 
       FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCDiracIsolate: Applying DiracSigmaExplicit.", 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FeynCalc`FCDiracIsolate`Private`ex = DiracSigmaExplicit[
          FeynCalc`FCDiracIsolate`Private`ex, FCI -> True]; 
        FCPrint[1, "FCDiracIsolate: Done applying DiracSigmaExplicit timing: \
", N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After DiracSigmaExplicit: ", 
         FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      If[OptionValue[ToDiracGamma67], FeynCalc`FCDiracIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
