        FCPrint[1, "FCDiracIsolate: Done applying ToDiracGamma67 timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After ToDiracGamma67: ", 
         FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      If[OptionValue[DiracGammaCombine], 
       FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCDiracIsolate: Applying DiracGammaCombine.", 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FeynCalc`FCDiracIsolate`Private`ex = DiracGammaCombine[
          FeynCalc`FCDiracIsolate`Private`ex, FCI -> True]; 
        FCPrint[1, "FCDiracIsolate: Done applying DiracGammaCombine, timing: \
", N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After DiracGammaCombine: ", 
         FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      If[OptionValue[Expanding], FeynCalc`FCDiracIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCDiracIsolate: Applying Expand2.", 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FeynCalc`FCDiracIsolate`Private`ex = 
         Expand2[FeynCalc`FCDiracIsolate`Private`ex, 
          FeynCalc`FCDiracIsolate`Private`headsList]; 
        FCPrint[1, "FCDiracIsolate: Done applying Expand2, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After Expand2: ", 
         FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      If[OptionValue[DotSimplify] && 
         !FreeQ[FeynCalc`FCDiracIsolate`Private`ex, DOT], 
       FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCDiracIsolate: Applying DotSimplify.", 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FeynCalc`FCDiracIsolate`Private`tmp = 
         FCSplit[FeynCalc`FCDiracIsolate`Private`ex, 
          FeynCalc`FCDiracIsolate`Private`headsList, Expanding -> 
           OptionValue[Expanding]]; FeynCalc`FCDiracIsolate`Private`aux = 
         DotSimplify[FeynCalc`FCDiracIsolate`Private`tmp[[2]], 
          Expanding -> False, FCI -> True, FCJoinDOTs -> 
           OptionValue[FCJoinDOTs]]; FCPrint[1, 
         "FCDiracIsolate: Done applying DotSimplify, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After DotSimplify: ", 
         FeynCalc`FCDiracIsolate`Private`aux, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        If[OptionValue["ExpandNestedDOTs"], 
         If[FeynCalc`Package`containsNestedDOTsQ[
            FeynCalc`FCDiracIsolate`Private`aux, DOT], 
           FCPrint[1, "FCDiracIsolate: Nested DOTs detected. Rerunning \
DotSimplify with Expanding set to True.", FCDoControl -> 
              FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
            FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
            FeynCalc`FCDiracIsolate`Private`aux = DotSimplify[
              FeynCalc`FCDiracIsolate`Private`aux, Expanding -> True, 
              FCI -> True, FCJoinDOTs -> OptionValue[FCJoinDOTs]]; 
            FCPrint[1, "FCDiracIsolate: Done applying DotSimplify, timing: ", 
             N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
             FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
            FCPrint[3, "FCDiracIsolate: After DotSimplify: ", 
             FeynCalc`FCDiracIsolate`Private`aux, FCDoControl -> 
              FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; ]; ]; 
        FeynCalc`FCDiracIsolate`Private`ex = 
         FeynCalc`FCDiracIsolate`Private`tmp[[1]] + 
          FeynCalc`FCDiracIsolate`Private`aux; ]; 
      If[OptionValue[FCTraceExpand], FeynCalc`FCDiracIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCDiracIsolate: Applying FCTraceExpand.", FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FeynCalc`FCDiracIsolate`Private`ex = FCTraceExpand[
          FeynCalc`FCDiracIsolate`Private`ex, FCI -> True, 
          SUNTrace -> False]; FCPrint[1, 
         "FCDiracIsolate: Done applying FCTraceExpand, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After FCTraceExpand: ", 
         FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      If[OptionValue[Collecting], FeynCalc`FCDiracIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCDiracIsolate: Applying Collect2.", 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FeynCalc`FCDiracIsolate`Private`ex = Collect2[
          FeynCalc`FCDiracIsolate`Private`ex, 
          FeynCalc`FCDiracIsolate`Private`collectList, Factoring -> 
           OptionValue[Factoring], TimeConstrained -> 
           FeynCalc`FCDiracIsolate`Private`optTimeConstrained]; 
        FCPrint[1, "FCDiracIsolate: Done applying Collect2, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        FCPrint[3, "FCDiracIsolate: After Collect2: ", 
         FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCDiracIsolate: Isolating heads.", 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      If[OptionValue[LorentzIndex] === True || 
        OptionValue[CartesianIndex] === True, 
       FeynCalc`FCDiracIsolate`Private`res = 
        ((FeynCalc`FCDiracIsolate`Private`selectionList = 
              FeynCalc`FCDiracIsolate`Private`makeSelectionList[#1, 
               FeynCalc`FCDiracIsolate`Private`headsList]; 
             FeynCalc`FCDiracIsolate`Private`restHead[SelectFree[#1, 
                FeynCalc`FCDiracIsolate`Private`selectionList]]*
              FeynCalc`FCDiracIsolate`Private`head[SelectNotFree[#1, 
                FeynCalc`FCDiracIsolate`Private`selectionList]]) & ) /@ 
           (FeynCalc`FCDiracIsolate`Private`ex + 
            FeynCalc`FCDiracIsolate`Private`null1 + 
            FeynCalc`FCDiracIsolate`Private`null2) /. 
          {FeynCalc`FCDiracIsolate`Private`null1 | 
             FeynCalc`FCDiracIsolate`Private`null2 -> 0} /. 
         FeynCalc`FCDiracIsolate`Private`head[1] -> 1, 
       FeynCalc`FCDiracIsolate`Private`res = 
        (FeynCalc`FCDiracIsolate`Private`restHead[SelectFree[#1, 
               FeynCalc`FCDiracIsolate`Private`headsList]]*
             FeynCalc`FCDiracIsolate`Private`head[SelectNotFree[#1, 
               FeynCalc`FCDiracIsolate`Private`headsList]] & ) /@ 
           (FeynCalc`FCDiracIsolate`Private`ex + 
            FeynCalc`FCDiracIsolate`Private`null1 + 
            FeynCalc`FCDiracIsolate`Private`null2) /. 
          {FeynCalc`FCDiracIsolate`Private`null1 | 
             FeynCalc`FCDiracIsolate`Private`null2 -> 0} /. 
         FeynCalc`FCDiracIsolate`Private`head[1] -> 1]; 
      FCPrint[1, "FCDiracIsolate: Done isolating heads, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      FCPrint[3, "FCDiracIsolate: After isolating heads: ", 
       FeynCalc`FCDiracIsolate`Private`ex, FCDoControl -> 
        FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      If[Together[(FeynCalc`FCDiracIsolate`Private`res /. 
           FeynCalc`FCDiracIsolate`Private`restHead | 
             FeynCalc`FCDiracIsolate`Private`head -> Identity) - 
          FeynCalc`FCDiracIsolate`Private`ex] =!= 0, 
       Message[FCDiracIsolate::fail, FeynCalc`FCDiracIsolate`Private`ex]; 
        Abort[]]; FeynCalc`FCDiracIsolate`Private`allHeads = 
       Cases2[FeynCalc`FCDiracIsolate`Private`res, 
        FeynCalc`FCDiracIsolate`Private`head]; 
      FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
       FeynCalc`FCDiracIsolate`Private`allHeads /. 
        DOT -> FeynCalc`FCDiracIsolate`Private`holdDOT; 
      FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
       FeynCalc`FCDiracIsolate`Private`allHeadsEval /. 
        {FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`x_] /; 
            !FreeQ2[FeynCalc`FCDiracIsolate`Private`x, OptionValue[
              ExceptHeads]] :> FeynCalc`FCDiracIsolate`Private`x}; 
      If[FeynCalc`FCDiracIsolate`Private`optSplit =!= False, 
       FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCDiracIsolate: Doing splittings.", 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
        Switch[FeynCalc`FCDiracIsolate`Private`optSplit, True, 
         FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
          FeynCalc`FCDiracIsolate`Private`chainSplit[
           FeynCalc`FCDiracIsolate`Private`allHeadsEval, 
           FeynCalc`FCDiracIsolate`Private`head], _Symbol, 
         FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
          FeynCalc`FCDiracIsolate`Private`allHeadsEval /. 
           FeynCalc`FCDiracIsolate`Private`head[
             FeynCalc`FCDiracIsolate`Private`x_] :> 
            FeynCalc`FCDiracIsolate`Private`optSplit[
             FeynCalc`FCDiracIsolate`Private`chainSplit[
              FeynCalc`FCDiracIsolate`Private`head[
               FeynCalc`FCDiracIsolate`Private`x], 
              FeynCalc`FCDiracIsolate`Private`head]], _, Null]; 
        FCPrint[1, "FCDiracIsolate: Splittings done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]]; 
      FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCDiracIsolate: Removing unneeded isolations.", 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      If[ !OptionValue[DiracTrace] && 
         !FreeQ[FeynCalc`FCDiracIsolate`Private`allHeadsEval, DiracTrace], 
       FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
        FeynCalc`FCDiracIsolate`Private`allHeadsEval //. 
         FeynCalc`FCDiracIsolate`Private`head[
           (FeynCalc`FCDiracIsolate`Private`x_DiracTrace)*
            (FeynCalc`FCDiracIsolate`Private`y_.)] :> 
          FeynCalc`FCDiracIsolate`Private`x*
           FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`y]]; 
      If[ !OptionValue[DiracChain] && 
         !FreeQ[FeynCalc`FCDiracIsolate`Private`allHeadsEval, DiracChain], 
       FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
        FeynCalc`FCDiracIsolate`Private`allHeadsEval //. 
          FeynCalc`FCDiracIsolate`Private`head[
            (FeynCalc`FCDiracIsolate`Private`x_DiracChain)*
             (FeynCalc`FCDiracIsolate`Private`y_.)] :> 
           FeynCalc`FCDiracIsolate`Private`x*
            FeynCalc`FCDiracIsolate`Private`head[
             FeynCalc`FCDiracIsolate`Private`y] //. 
         FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
              FeynCalc`FCDiracIsolate`Private`x__]*
             (FeynCalc`FCDiracIsolate`Private`y_.)] /; 
            !FreeQ[{FeynCalc`FCDiracIsolate`Private`x}, DiracChain] :> 
          FeynCalc`FCDiracIsolate`Private`holdDOT[
            FeynCalc`FCDiracIsolate`Private`x]*
           FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`y]]; 
      If[ !OptionValue[DiracGamma] && 
         !FreeQ[FeynCalc`FCDiracIsolate`Private`allHeadsEval /. 
           _DiracChain :> Unique["dch"], DiracGamma], 
       FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
        FeynCalc`FCDiracIsolate`Private`allHeadsEval //. 
          FeynCalc`FCDiracIsolate`Private`head[
            (FeynCalc`FCDiracIsolate`Private`x_DiracGamma)*
             (FeynCalc`FCDiracIsolate`Private`y_.)] :> 
           FeynCalc`FCDiracIsolate`Private`x*
            FeynCalc`FCDiracIsolate`Private`head[
             FeynCalc`FCDiracIsolate`Private`y] //. 
         FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
              FeynCalc`FCDiracIsolate`Private`x__]*
             (FeynCalc`FCDiracIsolate`Private`y_.)] /; 
           FreeQ[{FeynCalc`FCDiracIsolate`Private`x}, Spinor] && 
             !FreeQ[{FeynCalc`FCDiracIsolate`Private`x}, DiracGamma] :> 
          FeynCalc`FCDiracIsolate`Private`holdDOT[
            FeynCalc`FCDiracIsolate`Private`x]*
           FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`y]]; 
      If[OptionValue[Spinor] === False && 
         !FreeQ[FeynCalc`FCDiracIsolate`Private`allHeadsEval, Spinor], 
       FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
        FeynCalc`FCDiracIsolate`Private`allHeadsEval //. 
         FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
              FeynCalc`FCDiracIsolate`Private`x__]*
             (FeynCalc`FCDiracIsolate`Private`y_.)] /; 
            !FreeQ[{FeynCalc`FCDiracIsolate`Private`x}, Spinor] :> 
          FeynCalc`FCDiracIsolate`Private`holdDOT[
            FeynCalc`FCDiracIsolate`Private`x]*
           FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`y]]; 
      FCPrint[1, "FCDiracIsolate: Done removing unneeded isolations, timing: \
", N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      FeynCalc`FCDiracIsolate`Private`allHeadsEval = 
       FeynCalc`FCDiracIsolate`Private`allHeadsEval /. 
         FeynCalc`FCDiracIsolate`Private`holdDOT -> DOT //. 
        FeynCalc`FCDiracIsolate`Private`head[
           FeynCalc`FCDiracIsolate`Private`x_] /; 
          FreeQ2[FeynCalc`FCDiracIsolate`Private`x, 
           FeynCalc`FCDiracIsolate`Private`headsList] :> 
         FeynCalc`FCDiracIsolate`Private`x; 
      FeynCalc`FCDiracIsolate`Private`res = 
       FeynCalc`FCDiracIsolate`Private`res /. 
        Dispatch[Thread[FeynCalc`FCDiracIsolate`Private`allHeads -> 
           FeynCalc`FCDiracIsolate`Private`allHeadsEval]]; 
      FCPrint[1, "FCDiracIsolate: Handling nondirac pieces.", 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      FeynCalc`FCDiracIsolate`Private`time = AbsoluteTime[]; 
      If[OptionValue[Isolate], FeynCalc`FCDiracIsolate`Private`res = 
        FeynCalc`FCDiracIsolate`Private`res /. 
         FeynCalc`FCDiracIsolate`Private`restHead[
           FeynCalc`FCDiracIsolate`Private`x_] :> 
          Isolate[FeynCalc`FCDiracIsolate`Private`x, IsolateNames -> 
            OptionValue[IsolateNames], IsolateFast -> OptionValue[
             IsolateFast]], FeynCalc`FCDiracIsolate`Private`res = 
         FeynCalc`FCDiracIsolate`Private`res /. 
           FeynCalc`FCDiracIsolate`Private`restHead[0] -> 0 /. 
          FeynCalc`FCDiracIsolate`Private`restHead -> 
           FeynCalc`FCDiracIsolate`Private`headR; ]; 
      FCPrint[1, "FCDiracIsolate: Done handling nondirac pieces, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCDiracIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      FeynCalc`FCDiracIsolate`Private`tmp = 
       FeynCalc`FCDiracIsolate`Private`headsList; 
      If[OptionValue[LorentzIndex] === True, 
       FeynCalc`FCDiracIsolate`Private`tmp = 
        Join[FeynCalc`FCDiracIsolate`Private`tmp, {LorentzIndex}]]; 
      If[OptionValue[CartesianIndex] === True, 
       FeynCalc`FCDiracIsolate`Private`tmp = 
        Join[FeynCalc`FCDiracIsolate`Private`tmp, {CartesianIndex}]]; 
      If[( !FreeQ2[FeynCalc`FCDiracIsolate`Private`res /. 
            FeynCalc`FCDiracIsolate`Private`head[__] :> 1, 
           FeynCalc`FCDiracIsolate`Private`tmp] & ) || 
         !FreeQ[FeynCalc`FCDiracIsolate`Private`res, 
          FeynCalc`FCDiracIsolate`Private`head[]], 
       Message[FCDiracIsolate::fail, FeynCalc`FCDiracIsolate`Private`ex]; 
        Abort[]]; If[OptionValue[FCE], FeynCalc`FCDiracIsolate`Private`res = 
        FCE[FeynCalc`FCDiracIsolate`Private`res]]; 
      FCPrint[1, "FCDiracIsolate: Leaving.", FCDoControl -> 
        FeynCalc`FCDiracIsolate`Private`fcdiVerbose]; 
      FeynCalc`FCDiracIsolate`Private`res]
 
Options[FCDiracIsolate] = {CartesianIndex -> False, 
     ClearHeads -> {FCGV["DiracChain"]}, Collecting -> True, 
     DiracChain -> False, DiracGamma -> True, DiracGammaCombine -> True, 
     DiracSigmaExplicit -> False, DiracTrace -> True, DotSimplify -> True, 
     ExceptHeads -> {}, Expanding -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCJoinDOTs -> True, FCTraceExpand -> False, 
     FCVerbose -> False, Factoring -> {Factor2, 5000}, 
     Head -> FCGV["DiracChain"], Isolate -> False, IsolateFast -> False, 
     IsolateNames -> KK, LorentzIndex -> False, Polarization -> False, 
     "ExpandNestedDOTs" -> False, Spinor -> True, Split -> True, 
     TimeConstrained -> 3, ToDiracGamma67 -> False}
 
FCDiracIsolate /: FCDiracIsolate::fail = 
     "FCDiracIsolate failed to isolate Dirac structures in `1`!"
 
FCDiracIsolate /: FCDiracIsolate::usage = "FCDiracIsolate[exp] wraps chains \
of Dirac matrices into heads specified by the\nuser."
 
FeynCalc`FCDiracIsolate`Private`tmp /: 
    FeynCalc`FCDiracIsolate`Private`tmp::usage = ""
 
ExceptHeads /: ExceptHeads::usage = "ExceptHeads is an option of \
FCLoopIsolate, FCDiracIsolate and other functions.\nIt takes a list of heads \
that are not allowed to appear inside isolated\nexpression.\n\nFor example, \
ExceptHeads -> {DiracGamma} in FCLoopIsolate blocks loop\nintegrals where \
loop momenta are contracted with Dirac matrices."
 
ClearHeads /: ClearHeads::usage = "ClearHeads is an option of FCLoopIsolate, \
FCDiracIsolate and other functions.\nIt takes a list of heads that will be \
replaced by Identity in the isolating\nfunction. This is useful for cases \
when we first apply the isolating function\nto an expression, then simplify \
the isolated expression and finally want to\napply the isolating function \
again to pull out the simplified expressions out\nof the old heads."
 
FeynCalc`FCDiracIsolate`Private`restHead[0] = 0
 
DiracSigmaExplicit[(FeynCalc`DiracSigmaExplicit`Private`a_) == 
      (FeynCalc`DiracSigmaExplicit`Private`b_), 
     FeynCalc`DiracSigmaExplicit`Private`opts:OptionsPattern[]] := 
    DiracSigmaExplicit[FeynCalc`DiracSigmaExplicit`Private`a, 
      FeynCalc`DiracSigmaExplicit`Private`opts] == 
     DiracSigmaExplicit[FeynCalc`DiracSigmaExplicit`Private`b, 
      FeynCalc`DiracSigmaExplicit`Private`opts]
 
DiracSigmaExplicit[FeynCalc`DiracSigmaExplicit`Private`expr_List, 
     FeynCalc`DiracSigmaExplicit`Private`opts:OptionsPattern[]] := 
    (DiracSigmaExplicit[#1, FeynCalc`DiracSigmaExplicit`Private`opts] & ) /@ 
     FeynCalc`DiracSigmaExplicit`Private`expr
 
DiracSigmaExplicit[FeynCalc`DiracSigmaExplicit`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`DiracSigmaExplicit`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`DiracSigmaExplicit`Private`ex, 
      FeynCalc`DiracSigmaExplicit`Private`res, 
      FeynCalc`DiracSigmaExplicit`Private`holdDOT, 
      FeynCalc`DiracSigmaExplicit`Private`tmp}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`DiracSigmaExplicit`Private`dsiVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`DiracSigmaExplicit`Private`dsiVerbose = 
          OptionValue[FCVerbose]]; ]; FCPrint[1, 
       "DiracSigmaExplicit: Entering. ", FCDoControl -> 
        FeynCalc`DiracSigmaExplicit`Private`dsiVerbose]; 
      FCPrint[3, "DiracSigmaExplicit: Entering DiracSigmaExplicit with: ", 
       FeynCalc`DiracSigmaExplicit`Private`ex, FCDoControl -> 
        FeynCalc`DiracSigmaExplicit`Private`dsiVerbose]; 
      If[OptionValue[FCI], FeynCalc`DiracSigmaExplicit`Private`ex = 
        FeynCalc`DiracSigmaExplicit`Private`expr, 
       FeynCalc`DiracSigmaExplicit`Private`ex = 
        FCI[FeynCalc`DiracSigmaExplicit`Private`expr]]; 
      If[FreeQ[FeynCalc`DiracSigmaExplicit`Private`ex, DiracSigma], 
       Return[FeynCalc`DiracSigmaExplicit`Private`ex]]; 
      FeynCalc`DiracSigmaExplicit`Private`tmp = 
       FeynCalc`DiracSigmaExplicit`Private`ex /. 
        DOT -> FeynCalc`DiracSigmaExplicit`Private`holdDOT; 
      FeynCalc`DiracSigmaExplicit`Private`tmp = 
       FeynCalc`DiracSigmaExplicit`Private`tmp //. 
        {FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            FeynCalc`DiracSigmaExplicit`Private`x___, 
            (FeynCalc`DiracSigmaExplicit`Private`c_.)*DiracSigma[
              DiracGamma[ExplicitLorentzIndex[0]], 
              FeynCalc`DiracSigmaExplicit`Private`a:DiracGamma[
                _CartesianIndex | _CartesianMomentum, ___]], 
            FeynCalc`DiracSigmaExplicit`Private`y___] /; 
           NonCommFreeQ[FeynCalc`DiracSigmaExplicit`Private`c] :> 
          I*FeynCalc`DiracSigmaExplicit`Private`c*
           FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            FeynCalc`DiracSigmaExplicit`Private`x, DiracGamma[
             ExplicitLorentzIndex[0]], FeynCalc`DiracSigmaExplicit`Private`a, 
            FeynCalc`DiracSigmaExplicit`Private`y], 
         FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            FeynCalc`DiracSigmaExplicit`Private`x___, 
            (FeynCalc`DiracSigmaExplicit`Private`c_.)*DiracSigma[
              FeynCalc`DiracSigmaExplicit`Private`a:DiracGamma[
                _CartesianIndex | _CartesianMomentum, ___], 
              DiracGamma[ExplicitLorentzIndex[0]]], 
            FeynCalc`DiracSigmaExplicit`Private`y___] /; 
           NonCommFreeQ[FeynCalc`DiracSigmaExplicit`Private`c] :> 
          (-I)*FeynCalc`DiracSigmaExplicit`Private`c*
           FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            FeynCalc`DiracSigmaExplicit`Private`x, DiracGamma[
             ExplicitLorentzIndex[0]], FeynCalc`DiracSigmaExplicit`Private`a, 
            FeynCalc`DiracSigmaExplicit`Private`y], 
         FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            FeynCalc`DiracSigmaExplicit`Private`x___, 
            (FeynCalc`DiracSigmaExplicit`Private`c_.)*DiracSigma[
              FeynCalc`DiracSigmaExplicit`Private`a:DiracGamma[
                _CartesianIndex | _CartesianMomentum, ___], 
              FeynCalc`DiracSigmaExplicit`Private`b:DiracGamma[
                _CartesianIndex | _CartesianMomentum, ___]], 
            FeynCalc`DiracSigmaExplicit`Private`y___] /; 
           NonCommFreeQ[FeynCalc`DiracSigmaExplicit`Private`c] :> 
          I*FeynCalc`DiracSigmaExplicit`Private`c*
           (FeynCalc`DiracSigmaExplicit`Private`holdDOT[
             FeynCalc`DiracSigmaExplicit`Private`x, 
             FeynCalc`DiracSigmaExplicit`Private`a, 
             FeynCalc`DiracSigmaExplicit`Private`b, 
             FeynCalc`DiracSigmaExplicit`Private`y] + 
            CartesianPair[First[FeynCalc`DiracSigmaExplicit`Private`a], 
              First[FeynCalc`DiracSigmaExplicit`Private`b]]*
             FeynCalc`DiracSigmaExplicit`Private`holdDOT[
              FeynCalc`DiracSigmaExplicit`Private`x, 
              FeynCalc`DiracSigmaExplicit`Private`y])}; 
      FCPrint[3, "DiracSigmaExplicit: After applying the 1st set of rules: ", 
       FeynCalc`DiracSigmaExplicit`Private`tmp, FCDoControl -> 
        FeynCalc`DiracSigmaExplicit`Private`dsiVerbose]; 
      FeynCalc`DiracSigmaExplicit`Private`tmp = 
       FeynCalc`DiracSigmaExplicit`Private`tmp //. 
        {DiracSigma[DiracGamma[ExplicitLorentzIndex[0]], 
           FeynCalc`DiracSigmaExplicit`Private`a:DiracGamma[_CartesianIndex | 
              _CartesianMomentum, ___]] :> 
          I*FeynCalc`DiracSigmaExplicit`Private`holdDOT[DiracGamma[
             ExplicitLorentzIndex[0]], 
            FeynCalc`DiracSigmaExplicit`Private`a], 
         DiracSigma[FeynCalc`DiracSigmaExplicit`Private`a:
            DiracGamma[_CartesianIndex | _CartesianMomentum, ___], 
           DiracGamma[ExplicitLorentzIndex[0]]] :> 
          (-I)*FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            DiracGamma[ExplicitLorentzIndex[0]], 
            FeynCalc`DiracSigmaExplicit`Private`a], 
         DiracSigma[FeynCalc`DiracSigmaExplicit`Private`a:
            DiracGamma[_CartesianIndex | _CartesianMomentum, ___], 
           FeynCalc`DiracSigmaExplicit`Private`b:DiracGamma[_CartesianIndex | 
              _CartesianMomentum, ___]] :> 
          I*(FeynCalc`DiracSigmaExplicit`Private`holdDOT[
             FeynCalc`DiracSigmaExplicit`Private`a, 
             FeynCalc`DiracSigmaExplicit`Private`b] + CartesianPair[
             First[FeynCalc`DiracSigmaExplicit`Private`a], 
             First[FeynCalc`DiracSigmaExplicit`Private`b]])}; 
      FCPrint[3, "DiracSigmaExplicit: After applying the 2nd set of rules: ", 
       FeynCalc`DiracSigmaExplicit`Private`tmp, FCDoControl -> 
        FeynCalc`DiracSigmaExplicit`Private`dsiVerbose]; 
      FeynCalc`DiracSigmaExplicit`Private`tmp = 
       FeynCalc`DiracSigmaExplicit`Private`tmp //. 
        {FeynCalc`DiracSigmaExplicit`Private`holdDOT[
            FeynCalc`DiracSigmaExplicit`Private`x___, 
            (FeynCalc`DiracSigmaExplicit`Private`c_.)*DiracSigma[
              FeynCalc`DiracSigmaExplicit`Private`a_DiracGamma, 
              FeynCalc`DiracSigmaExplicit`Private`b_DiracGamma], 
            FeynCalc`DiracSigmaExplicit`Private`y___] /; 
           NonCommFreeQ[FeynCalc`DiracSigmaExplicit`Private`c] :> 
          (I/2)*FeynCalc`DiracSigmaExplicit`Private`c*
           (FeynCalc`DiracSigmaExplicit`Private`holdDOT[
             FeynCalc`DiracSigmaExplicit`Private`x, 
             FeynCalc`DiracSigmaExplicit`Private`a, 
             FeynCalc`DiracSigmaExplicit`Private`b, 
             FeynCalc`DiracSigmaExplicit`Private`y] - 
            FeynCalc`DiracSigmaExplicit`Private`holdDOT[
             FeynCalc`DiracSigmaExplicit`Private`x, 
             FeynCalc`DiracSigmaExplicit`Private`b, 
             FeynCalc`DiracSigmaExplicit`Private`a, 
             FeynCalc`DiracSigmaExplicit`Private`y])}; 
      FCPrint[3, "DiracSigmaExplicit: After applying the 3rd set of rules: ", 
       FeynCalc`DiracSigmaExplicit`Private`tmp, FCDoControl -> 
        FeynCalc`DiracSigmaExplicit`Private`dsiVerbose]; 
      FeynCalc`DiracSigmaExplicit`Private`tmp = 
       FeynCalc`DiracSigmaExplicit`Private`tmp //. 
         {DiracSigma[FeynCalc`DiracSigmaExplicit`Private`a_DiracGamma, 
            FeynCalc`DiracSigmaExplicit`Private`b_DiracGamma] :> 
           (I/2)*(DOT[FeynCalc`DiracSigmaExplicit`Private`a, 
              FeynCalc`DiracSigmaExplicit`Private`b] - 
             DOT[FeynCalc`DiracSigmaExplicit`Private`b, 
              FeynCalc`DiracSigmaExplicit`Private`a])} /. 
        FeynCalc`DiracSigmaExplicit`Private`holdDOT -> DOT; 
      FCPrint[3, "DiracSigmaExplicit: After applying the final set of rules: \
", FeynCalc`DiracSigmaExplicit`Private`tmp, FCDoControl -> 
        FeynCalc`DiracSigmaExplicit`Private`dsiVerbose]; 
      FeynCalc`DiracSigmaExplicit`Private`res = 
       FeynCalc`DiracSigmaExplicit`Private`tmp; 
      If[ !FreeQ[FeynCalc`DiracSigmaExplicit`Private`res, DiracSigma], 
       Message[DiracSigmaExplicit::failmsg, 
         "Failed to eliminate all occurences of DiracSigma."]; Abort[]]; 
      If[OptionValue[FCE], FeynCalc`DiracSigmaExplicit`Private`res = 
        FCE[FeynCalc`DiracSigmaExplicit`Private`res]]; 
      FeynCalc`DiracSigmaExplicit`Private`res]
 
Options[DiracSigmaExplicit] = {FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCVerbose -> False}
 
DiracSigmaExplicit /: DiracSigmaExplicit::failmsg = "Error! \
DiracSigmaExplicit has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
DiracSigmaExplicit /: DiracSigmaExplicit::usage = "DiracSigmaExplicit[exp] \
inserts in exp for all DiracSigma its definition.\nDiracSigmaExplict is also \
an option of DiracSimplify. DiracSigmaExplict is\nalso an option of various \
FeynCalc functions that handle the Dirac algebra."
 
FeynCalc`DiracSigmaExplicit`Private`dsiVerbose /: 
    FeynCalc`DiracSigmaExplicit`Private`dsiVerbose::usage = ""
 
ToDiracGamma67[(FeynCalc`ToDiracGamma67`Private`a_) == 
      (FeynCalc`ToDiracGamma67`Private`b_), 
     FeynCalc`ToDiracGamma67`Private`opts:OptionsPattern[]] := 
    ToDiracGamma67[FeynCalc`ToDiracGamma67`Private`a, 
      FeynCalc`ToDiracGamma67`Private`opts] == ToDiracGamma67[
      FeynCalc`ToDiracGamma67`Private`b, FeynCalc`ToDiracGamma67`Private`opts]
 
ToDiracGamma67[FeynCalc`ToDiracGamma67`Private`expr_List, 
     FeynCalc`ToDiracGamma67`Private`opts:OptionsPattern[]] := 
    (ToDiracGamma67[#1, FeynCalc`ToDiracGamma67`Private`opts] & ) /@ 
     FeynCalc`ToDiracGamma67`Private`expr
 
ToDiracGamma67[FeynCalc`ToDiracGamma67`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`ToDiracGamma67`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`ToDiracGamma67`Private`ex}, 
     If[OptionValue[FCI], FeynCalc`ToDiracGamma67`Private`ex = 
        FeynCalc`ToDiracGamma67`Private`expr, 
       FeynCalc`ToDiracGamma67`Private`ex = 
        FCI[FeynCalc`ToDiracGamma67`Private`expr]]; 
      FeynCalc`ToDiracGamma67`Private`ex = 
       FeynCalc`ToDiracGamma67`Private`ex /. {1/2 + DiracGamma[5]/2 -> 
          DiracGamma[6], 1/2 - DiracGamma[5]/2 -> DiracGamma[7], 
         1 + DiracGamma[5] -> 2*DiracGamma[6], 1 - DiracGamma[5] -> 
          2*DiracGamma[7]}; If[OptionValue[All], 
       FeynCalc`ToDiracGamma67`Private`ex = 
        FeynCalc`ToDiracGamma67`Private`ex /. DiracGamma[5] -> 
          DiracGamma[6] - DiracGamma[7]]; If[OptionValue[DotSimplify], 
       FeynCalc`ToDiracGamma67`Private`ex = DotSimplify[
         FeynCalc`ToDiracGamma67`Private`ex, FCI -> True]]; 
      If[OptionValue[FCE], FeynCalc`ToDiracGamma67`Private`ex = 
        FCE[FeynCalc`ToDiracGamma67`Private`ex]]; 
      FeynCalc`ToDiracGamma67`Private`ex]
 
Options[ToDiracGamma67] = {All -> False, DotSimplify -> False, 
     FeynCalcExternal -> False, FeynCalcInternal -> False}
 
ToDiracGamma67 /: ToDiracGamma67::usage = "ToDiracGamma67[exp] substitutes \
$\\frac{1}{2} \\left(1 + \\gamma^5\\right)$ \
and\n$\\frac{1}{2}\\left(1-\\gamma^5\\right)$ by the chirality projectors \
$\\gamma^6$\nand $\\gamma^7$."
 
DotSimplify[FeynCalc`DotSimplify`Private`expr_List, 
     FeynCalc`DotSimplify`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`DotSimplify`Private`optVerbose, 
      FeynCalc`DotSimplify`Private`res, FeynCalc`DotSimplify`Private`time}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`DotSimplify`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`DotSimplify`Private`optVerbose = OptionValue[
           FCVerbose]]; ]; FeynCalc`DotSimplify`Private`time = 
       AbsoluteTime[]; FCPrint[1, "DotSimplify: Entering.", 
       FCDoControl -> FeynCalc`DotSimplify`Private`optVerbose]; 
      If[$ParallelizeFeynCalc && OptionValue[FCParallelize], 
       FCPrint[1, "DotSimplify: Applying DotSimplify in parallel.", 
         FCDoControl -> FeynCalc`DotSimplify`Private`optVerbose]; 
        FeynCalc`DotSimplify`Private`res = ParallelMap[
          DotSimplify[#1, FilterRules[{FeynCalc`DotSimplify`Private`opts}, 
             Except[FCParallelize | FCVerbose]], 
            FeynCalc`DotSimplify`Private`ParallelKernels -> True] & , 
          FeynCalc`DotSimplify`Private`expr, DistributedContexts -> None, 
          Method -> "ItemsPerEvaluation" -> Ceiling[
             N[Length[FeynCalc`DotSimplify`Private`expr]/$KernelCount]/10]]; 
        FCPrint[1, 
         "DotSimplify: Done applying DotSimplify in parallel, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
         FCDoControl -> FeynCalc`DotSimplify`Private`optVerbose], 
       FCPrint[1, "DotSimplify: Applying Contract.", FCDoControl -> 
          FeynCalc`DotSimplify`Private`optVerbose]; 
        FeynCalc`DotSimplify`Private`res = 
         (DotSimplify[#1, FilterRules[{FeynCalc`DotSimplify`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & ) /@ 
          FeynCalc`DotSimplify`Private`expr; FCPrint[1, 
         "DotSimplify: Done applying DotSimplify, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
         FCDoControl -> FeynCalc`DotSimplify`Private`optVerbose]]; 
      FCPrint[1, "DotSimplify: Leaving.", FCDoControl -> 
        FeynCalc`DotSimplify`Private`optVerbose]; 
      FeynCalc`DotSimplify`Private`res]
 
DotSimplify[(FeynCalc`DotSimplify`Private`a_) == 
      (FeynCalc`DotSimplify`Private`b_), FeynCalc`DotSimplify`Private`opts:
      OptionsPattern[]] := DotSimplify[FeynCalc`DotSimplify`Private`a, 
      FeynCalc`DotSimplify`Private`opts] == 
     DotSimplify[FeynCalc`DotSimplify`Private`b, 
      FeynCalc`DotSimplify`Private`opts]
 
DotSimplify[FeynCalc`DotSimplify`Private`expr_ /; 
      Head[FeynCalc`DotSimplify`Private`expr] =!= List, OptionsPattern[]] := 
    Block[{FeynCalc`DotSimplify`Private`ne, FeynCalc`DotSimplify`Private`x, 
      FeynCalc`DotSimplify`Private`ruleCommutator, 
      FeynCalc`DotSimplify`Private`ruleAntiCommutator, 
      FeynCalc`DotSimplify`Private`commm, 
      FeynCalc`DotSimplify`Private`acommm, 
      FeynCalc`DotSimplify`Private`sdoot, 
      FeynCalc`DotSimplify`Private`actorules, 
      FeynCalc`DotSimplify`Private`cotorules, 
      FeynCalc`DotSimplify`Private`vars, FeynCalc`DotSimplify`Private`rest1, 
      FeynCalc`DotSimplify`Private`rest2, 
      FeynCalc`DotSimplify`Private`condition, 
      FeynCalc`DotSimplify`Private`sameQ, FeynCalc`DotSimplify`Private`hold, 
      FeynCalc`DotSimplify`Private`ex, FeynCalc`Package`sunTrace, 
      FeynCalc`DotSimplify`Private`tmpDOT, FeynCalc`Package`holdDOTColor, 
      FeynCalc`DotSimplify`Private`holdDOTDirac, 
      FeynCalc`DotSimplify`Private`holdDOTPauli, 
      FeynCalc`DotSimplify`Private`holdDOTRest1, 
      FeynCalc`DotSimplify`Private`holdDOTRest2, 
      FeynCalc`DotSimplify`Private`holdDOTRest3, 
      FeynCalc`DotSimplify`Private`nvar, FeynCalc`DotSimplify`Private`time, 
      FeynCalc`DotSimplify`Private`time0, 
      FeynCalc`DotSimplify`Private`momList, 
      FeynCalc`DotSimplify`Private`momListEval, 
      FeynCalc`DotSimplify`Private`momRule, 
      FeynCalc`DotSimplify`Private`optSortBy, 
      FeynCalc`DotSimplify`Private`commSortBy, 
      FeynCalc`DotSimplify`Private`acommSortBy, 
      FeynCalc`DotSimplify`Private`dsVerbose}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`DotSimplify`Private`dsVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`DotSimplify`Private`dsVerbose = OptionValue[FCVerbose]]; ]; 
      If[OptionValue[FeynCalc`DotSimplify`Private`ParallelKernels] && 
        $KernelID === 0, Message[DotSimplify::failmsg, 
         "Tasks for parallel kernels are being executed on the main kernel."]\
; Abort[]]; FeynCalc`DotSimplify`Private`optExpanding = 
       OptionValue[Expanding]; 
      FeynCalc`DotSimplify`Private`optDotSimplifyRelations = 
       OptionValue[DotSimplifyRelations]; 
      FeynCalc`DotSimplify`Private`optMaxIterations = 
       OptionValue[MaxIterations]; FeynCalc`DotSimplify`Private`optSortBy = 
       OptionValue[SortBy]; FCPrint[1, "DotSimplify: Entering.", 
       FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
      If[FreeQ[FeynCalc`DotSimplify`Private`expr, DOT] && 
        NonCommFreeQ[FeynCalc`DotSimplify`Private`expr], 
       Return[FeynCalc`DotSimplify`Private`expr]]; If[OptionValue[FCI], 
       FeynCalc`DotSimplify`Private`ex = FeynCalc`DotSimplify`Private`expr, 
       FeynCalc`DotSimplify`Private`ex = 
        FCI[FeynCalc`DotSimplify`Private`expr]]; 
      FCPrint[3, "DotSimplify: Entering with", FCDoControl -> 
        FeynCalc`DotSimplify`Private`dsVerbose]; 
      FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
      FCPrint[1, 
       "DotSimplify: Applying FactorTerms to the arguments of momenta.", 
       FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
      If[ !FreeQ[FeynCalc`DotSimplify`Private`ex, Momentum], 
       FeynCalc`DotSimplify`Private`momList = 
         Cases2[FeynCalc`DotSimplify`Private`ex, Momentum]; 
        FeynCalc`DotSimplify`Private`momListEval = 
         FeynCalc`DotSimplify`Private`momList /. 
          Momentum[FeynCalc`DotSimplify`Private`a_, 
            FeynCalc`DotSimplify`Private`dim___] :> 
           Momentum[FactorTerms[FeynCalc`DotSimplify`Private`a], 
            FeynCalc`DotSimplify`Private`dim]; 
        FeynCalc`DotSimplify`Private`momRule = 
         Thread[FeynCalc`DotSimplify`Private`momList -> 
           FeynCalc`DotSimplify`Private`momListEval]; 
        FeynCalc`DotSimplify`Private`ex = FeynCalc`DotSimplify`Private`ex /. 
          Dispatch[FeynCalc`DotSimplify`Private`momRule]]; 
      If[ !FreeQ[FeynCalc`DotSimplify`Private`ex, CartesianMomentum], 
       FeynCalc`DotSimplify`Private`momList = 
         Cases2[FeynCalc`DotSimplify`Private`ex, CartesianMomentum]; 
        FeynCalc`DotSimplify`Private`momListEval = 
         FeynCalc`DotSimplify`Private`momList /. 
          CartesianMomentum[FeynCalc`DotSimplify`Private`a_, 
            FeynCalc`DotSimplify`Private`dim___] :> CartesianMomentum[
            FactorTerms[FeynCalc`DotSimplify`Private`a], 
            FeynCalc`DotSimplify`Private`dim]; 
        FeynCalc`DotSimplify`Private`momRule = 
         Thread[FeynCalc`DotSimplify`Private`momList -> 
           FeynCalc`DotSimplify`Private`momListEval]; 
        FeynCalc`DotSimplify`Private`ex = FeynCalc`DotSimplify`Private`ex /. 
          Dispatch[FeynCalc`DotSimplify`Private`momRule]]; 
      If[ !FreeQ[FeynCalc`DotSimplify`Private`ex, TemporalMomentum], 
       FeynCalc`DotSimplify`Private`momList = 
         Cases2[FeynCalc`DotSimplify`Private`ex, TemporalMomentum]; 
        FeynCalc`DotSimplify`Private`momListEval = 
         FeynCalc`DotSimplify`Private`momList /. 
          TemporalMomentum[FeynCalc`DotSimplify`Private`a_, 
            FeynCalc`DotSimplify`Private`dim___] :> TemporalMomentum[
            FactorTerms[FeynCalc`DotSimplify`Private`a], 
            FeynCalc`DotSimplify`Private`dim]; 
        FeynCalc`DotSimplify`Private`momRule = 
         Thread[FeynCalc`DotSimplify`Private`momList -> 
           FeynCalc`DotSimplify`Private`momListEval]; 
        FeynCalc`DotSimplify`Private`ex = FeynCalc`DotSimplify`Private`ex /. 
          Dispatch[FeynCalc`DotSimplify`Private`momRule]]; 
      FCPrint[1, "DotSimplify: Done applying FactorTerms, timing: ", 
       N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
       FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
      FeynCalc`DotSimplify`Private`time0 = AbsoluteTime[]; 
      FCPrint[1, "DotSimplify: Entering the main loop.", 
       FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
      FeynCalc`DotSimplify`Private`x = 
       Catch[FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
         FCPrint[1, "DotSimplify: Applying DotSimplifyRelations.", 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[FeynCalc`DotSimplify`Private`optDotSimplifyRelations =!= {}, 
          FeynCalc`DotSimplify`Private`sru[
             FeynCalc`DotSimplify`Private`aa_ :> 
              FeynCalc`DotSimplify`Private`bb_] := 
            DOT[FeynCalc`DotSimplify`Private`xxXX___, Sequence @@ If[
                Head[FeynCalc`DotSimplify`Private`aa] === DOT, List @@ 
                 FeynCalc`DotSimplify`Private`aa, 
                {FeynCalc`DotSimplify`Private`aa}], 
              FeynCalc`DotSimplify`Private`yyYY___] :> 
             (FeynCalc`DotSimplify`Private`sdoot[
                FeynCalc`DotSimplify`Private`xxXX, 
                FeynCalc`DotSimplify`Private`bb, 
                FeynCalc`DotSimplify`Private`yyYY] /. 
               FeynCalc`DotSimplify`Private`sdoot[] :> Sequence[] /. 
              FeynCalc`DotSimplify`Private`sdoot -> DOT); 
           FeynCalc`DotSimplify`Private`sru[
             FeynCalc`DotSimplify`Private`aa_ -> 
              FeynCalc`DotSimplify`Private`bb_] := 
            FeynCalc`DotSimplify`Private`sru[
             FeynCalc`DotSimplify`Private`aa :> 
              FeynCalc`DotSimplify`Private`bb]; 
           FeynCalc`DotSimplify`Private`optDotSimplifyRelations = 
            FeynCalc`DotSimplify`Private`sru /@ 
             FeynCalc`DotSimplify`Private`optDotSimplifyRelations; ]; 
         FCPrint[1, 
          "DotSimplify: Done applying DotSimplifyRelations, timing: ", 
          N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FCPrint[3, "DotSimplify: After DotSimplifyRelations: ", 
          FeynCalc`DotSimplify`Private`ex, FCDoControl -> 
           FeynCalc`DotSimplify`Private`dsVerbose]; 
         FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
         FCPrint[1, 
          "DotSimplify: Writing out commutators and anticommutators.", 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[ !FreeQ[FeynCalc`DotSimplify`Private`ex, FCCommutator] || 
            !FreeQ[FeynCalc`DotSimplify`Private`ex, FCAntiCommutator], 
          FeynCalc`DotSimplify`Private`x = CommutatorExplicit[
            FeynCalc`DotSimplify`Private`ex], 
          FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`ex]; 
         FCPrint[1, "DotSimplify: Done writing out commutators and \
anticommutators, timing: ", N[AbsoluteTime[] - 
            FeynCalc`DotSimplify`Private`time, 4], FCDoControl -> 
           FeynCalc`DotSimplify`Private`dsVerbose]; 
         FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
         FCPrint[1, 
          "DotSimplify: Writing out non-commutative objects explicitly.", 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[ !FreeQ[FeynCalc`DotSimplify`Private`x, 
            (FeynCalc`DotSimplify`Private`a_ /; NonCommQ[
               FeynCalc`DotSimplify`Private`a])^
             (FeynCalc`DotSimplify`Private`n_Integer)?Positive], 
          FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
             {(FeynCalc`DotSimplify`Private`a_ /; NonCommQ[
                  FeynCalc`DotSimplify`Private`a])^
                (FeynCalc`DotSimplify`Private`n_Integer)?Positive :> DOT @@ 
                Table[FeynCalc`DotSimplify`Private`a, 
                 {FeynCalc`DotSimplify`Private`n}]}; ]; FCPrint[1, "DotSimpli\
fy: Done writing out non-commutative objects explicitly, timing: ", 
          N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FCPrint[3, 
          "DotSimplify: After writing out non-commutuative objects: ", 
          FeynCalc`DotSimplify`Private`x, FCDoControl -> 
           FeynCalc`DotSimplify`Private`dsVerbose]; 
         FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
         FCPrint[1, 
          "DotSimplify: Working out user-defined non-commutative objects.", 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[FeynCalc`DotSimplify`Private`optDotSimplifyRelations === {}, 
          FeynCalc`DotSimplify`Private`vars = Union[Variables[
              Cases[Cases2[FeynCalc`DotSimplify`Private`ex, DOT] //. 
                DOT[FeynCalc`DotSimplify`Private`a___, 
                  (FeynCalc`DotSimplify`Private`n_)?NumberQ*
                    (FeynCalc`DotSimplify`Private`o1_.) + 
                   (FeynCalc`DotSimplify`Private`o2_:0), 
                  FeynCalc`DotSimplify`Private`b___] :> DOT[
                  FeynCalc`DotSimplify`Private`a, 
                  FeynCalc`DotSimplify`Private`o1*
                    FeynCalc`DotSimplify`Private`nvar[
                     FeynCalc`DotSimplify`Private`n] + 
                   FeynCalc`DotSimplify`Private`o2, 
                  FeynCalc`DotSimplify`Private`b], _, Infinity]]]; 
           If[Union[(DataType[#1, NonCommutative] & ) /@ 
               FeynCalc`DotSimplify`Private`vars] === {True}, 
            If[FreeQ2[{DownValues[FCCommutator], DownValues[
                FCAntiCommutator]}, FeynCalc`DotSimplify`Private`vars], 
             FeynCalc`DotSimplify`Private`x = Distribute[
                 FeynCalc`DotSimplify`Private`x /. DOT -> 
                   FeynCalc`DotSimplify`Private`doot] //. 
                FeynCalc`DotSimplify`Private`doot[
                  FeynCalc`DotSimplify`Private`a___, 
                  (FeynCalc`DotSimplify`Private`n_)?NumberQ*
                   (FeynCalc`DotSimplify`Private`b_), 
                  FeynCalc`DotSimplify`Private`c___] :> 
                 FeynCalc`DotSimplify`Private`n*
                  FeynCalc`DotSimplify`Private`doot[
                   FeynCalc`DotSimplify`Private`a, 
                   FeynCalc`DotSimplify`Private`b, 
                   FeynCalc`DotSimplify`Private`c]; 
              Throw[FeynCalc`DotSimplify`Private`x /. 
                FeynCalc`DotSimplify`Private`doot -> 
                 FeynCalc`Package`dootpow]]]]; FCPrint[1, "DotSimplify: Done \
working out user-defined non-commutative objects, timing: ", 
          N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FCPrint[3, "DotSimplify: After checking simrel: ", 
          FeynCalc`DotSimplify`Private`x, FCDoControl -> 
           FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[OptionValue[PreservePropagatorStructures], 
          FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
           FCPrint[1, "DotSimplify: Preserving propagator structures.", 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
                 SUNTrace -> FeynCalc`Package`sunTrace //. DOT -> 
                 FeynCalc`DotSimplify`Private`holdDOT //. 
               FeynCalc`DotSimplify`Private`holdDOT[
                  FeynCalc`DotSimplify`Private`a___, 
                  (FeynCalc`DotSimplify`Private`ee_.)*
                   ((FeynCalc`DotSimplify`Private`c_) + 
                    (FeynCalc`DotSimplify`Private`d_DiracGamma)), 
                  FeynCalc`DotSimplify`Private`b___] /; FreeQ2[
                  {FeynCalc`DotSimplify`Private`c}, {DiracGamma, 
                   FeynCalc`DotSimplify`Private`holdDOT}] :> 
                FeynCalc`DotSimplify`Private`holdDOT[
                 FeynCalc`DotSimplify`Private`a, 
                 FeynCalc`DotSimplify`Private`ee*FeynCalc`Package`dotsimpHold[
                   FeynCalc`DotSimplify`Private`c + 
                    FeynCalc`DotSimplify`Private`d], 
                 FeynCalc`DotSimplify`Private`b] //. 
              FeynCalc`DotSimplify`Private`holdDOT -> DOT /. 
             FeynCalc`Package`sunTrace -> SUNTrace; FCPrint[3, 
            "DotSimplify: Done preserving propagator structures, timing: ", 
            N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FCPrint[3, 
            "DotSimplify: After preserving propagator structures: ", 
            FeynCalc`DotSimplify`Private`x, FCDoControl -> 
             FeynCalc`DotSimplify`Private`dsVerbose]; ]; 
         {FeynCalc`DotSimplify`Private`commSortBy, 
           FeynCalc`DotSimplify`Private`acommSortBy} = 
          FeynCalc`DotSimplify`Private`optSortBy; 
         FeynCalc`DotSimplify`Private`ruleCommutator[
            {FeynCalc`DotSimplify`Private`commm[
              FeynCalc`DotSimplify`Private`a_, 
              FeynCalc`DotSimplify`Private`b_], 
             FeynCalc`DotSimplify`Private`val_}] /; FCPatternFreeQ[
            {FeynCalc`DotSimplify`Private`a, 
             FeynCalc`DotSimplify`Private`b}] := 
          RuleDelayed @@ {FeynCalc`DotSimplify`Private`holdDOT[
              FeynCalc`DotSimplify`Private`rest1___, 
              FeynCalc`DotSimplify`Private`a, FeynCalc`DotSimplify`Private`b, 
              FeynCalc`DotSimplify`Private`rest2___], 
             FeynCalc`DotSimplify`Private`holdDOT[
               FeynCalc`DotSimplify`Private`rest1, 
               FeynCalc`DotSimplify`Private`val, 
               FeynCalc`DotSimplify`Private`rest2] + 
              FeynCalc`DotSimplify`Private`holdDOT[
               FeynCalc`DotSimplify`Private`rest1, 
               FeynCalc`DotSimplify`Private`b, 
               FeynCalc`DotSimplify`Private`a, 
               FeynCalc`DotSimplify`Private`rest2]} /. 
           FeynCalc`DotSimplify`Private`holdDOT -> DOT; 
         FeynCalc`DotSimplify`Private`ruleCommutator[
            {FeynCalc`DotSimplify`Private`commm[
              FeynCalc`DotSimplify`Private`a_, 
              FeynCalc`DotSimplify`Private`b_], 
             FeynCalc`DotSimplify`Private`val_}] /; 
            !FCPatternFreeQ[{FeynCalc`DotSimplify`Private`a, 
              FeynCalc`DotSimplify`Private`b}] := 
          RuleDelayed @@ {FeynCalc`DotSimplify`Private`holdDOT[
                FeynCalc`DotSimplify`Private`rest1___, 
                FeynCalc`DotSimplify`Private`a, 
                FeynCalc`DotSimplify`Private`b, 
                FeynCalc`DotSimplify`Private`rest2___], 
               FeynCalc`DotSimplify`Private`condition[
                FeynCalc`DotSimplify`Private`holdDOT[
                  FeynCalc`DotSimplify`Private`rest1, 
                  FeynCalc`DotSimplify`Private`val, 
                  FeynCalc`DotSimplify`Private`rest2] + 
                 FeynCalc`DotSimplify`Private`holdDOT[
                  FeynCalc`DotSimplify`Private`rest1, 
                  FeynCalc`DotSimplify`Private`b /. Pattern -> 
                    FeynCalc`DotSimplify`Private`pid, 
                  FeynCalc`DotSimplify`Private`a /. Pattern -> 
                    FeynCalc`DotSimplify`Private`pid, 
                  FeynCalc`DotSimplify`Private`rest2], 
                 !FeynCalc`DotSimplify`Private`orderedQ[
                  {FeynCalc`DotSimplify`Private`a /. Pattern :> 
                     FeynCalc`DotSimplify`Private`pid, 
                   FeynCalc`DotSimplify`Private`b /. Pattern :> 
                     FeynCalc`DotSimplify`Private`pid}, 
                  FeynCalc`DotSimplify`Private`commSortBy]]} /. 
             FeynCalc`DotSimplify`Private`holdDOT -> DOT /. 
            FeynCalc`DotSimplify`Private`condition :> Condition /. 
           FeynCalc`DotSimplify`Private`orderedQ :> OrderedQ; 
         FeynCalc`DotSimplify`Private`ruleAntiCommutator[
            {FeynCalc`DotSimplify`Private`acommm[
              FeynCalc`DotSimplify`Private`a_, 
              FeynCalc`DotSimplify`Private`b_], 
             FeynCalc`DotSimplify`Private`val_}] /; FCPatternFreeQ[
            {FeynCalc`DotSimplify`Private`a, 
             FeynCalc`DotSimplify`Private`b}] := 
          RuleDelayed @@ {FeynCalc`DotSimplify`Private`holdDOT[
              FeynCalc`DotSimplify`Private`rest1___, 
              FeynCalc`DotSimplify`Private`a, FeynCalc`DotSimplify`Private`b, 
              FeynCalc`DotSimplify`Private`rest2___], 
             FeynCalc`DotSimplify`Private`holdDOT[
               FeynCalc`DotSimplify`Private`rest1, 
               FeynCalc`DotSimplify`Private`val, 
               FeynCalc`DotSimplify`Private`rest2] - 
              FeynCalc`DotSimplify`Private`holdDOT[
               FeynCalc`DotSimplify`Private`rest1, 
               FeynCalc`DotSimplify`Private`b, 
               FeynCalc`DotSimplify`Private`a, 
               FeynCalc`DotSimplify`Private`rest2]} /. 
           FeynCalc`DotSimplify`Private`holdDOT -> DOT; 
         FeynCalc`DotSimplify`Private`ruleAntiCommutator[
            {FeynCalc`DotSimplify`Private`acommm[
              FeynCalc`DotSimplify`Private`a_, 
              FeynCalc`DotSimplify`Private`b_], 
             FeynCalc`DotSimplify`Private`val_}] /; 
            !FCPatternFreeQ[{FeynCalc`DotSimplify`Private`a, 
              FeynCalc`DotSimplify`Private`b}] := 
          {RuleDelayed @@ {FeynCalc`DotSimplify`Private`holdDOT[
                FeynCalc`DotSimplify`Private`rest1___, 
                FeynCalc`DotSimplify`Private`a, 
                FeynCalc`DotSimplify`Private`b, 
                FeynCalc`DotSimplify`Private`rest2___], 
               FeynCalc`DotSimplify`Private`condition[(1/2)*
                 FeynCalc`DotSimplify`Private`holdDOT[
                  FeynCalc`DotSimplify`Private`rest1, 
                  FeynCalc`DotSimplify`Private`val, 
                  FeynCalc`DotSimplify`Private`rest2], 
                FeynCalc`DotSimplify`Private`sameQ[
                 FeynCalc`DotSimplify`Private`a /. Pattern :> 
                   FeynCalc`DotSimplify`Private`pid, 
                 FeynCalc`DotSimplify`Private`b /. Pattern :> 
                   FeynCalc`DotSimplify`Private`pid]]} /. 
             FeynCalc`DotSimplify`Private`holdDOT -> DOT /. 
            {FeynCalc`DotSimplify`Private`sameQ :> SameQ, 
             FeynCalc`DotSimplify`Private`condition :> Condition}, 
           RuleDelayed @@ {FeynCalc`DotSimplify`Private`holdDOT[
                 FeynCalc`DotSimplify`Private`rest1___, 
                 FeynCalc`DotSimplify`Private`a, 
                 FeynCalc`DotSimplify`Private`b, 
                 FeynCalc`DotSimplify`Private`rest2___], 
                FeynCalc`DotSimplify`Private`condition[
                 FeynCalc`DotSimplify`Private`holdDOT[
                   FeynCalc`DotSimplify`Private`rest1, 
                   FeynCalc`DotSimplify`Private`val, 
                   FeynCalc`DotSimplify`Private`rest2] - 
                  FeynCalc`DotSimplify`Private`holdDOT[
                   FeynCalc`DotSimplify`Private`rest1, 
                   FeynCalc`DotSimplify`Private`b /. Pattern -> 
                     FeynCalc`DotSimplify`Private`pid, 
                   FeynCalc`DotSimplify`Private`a /. Pattern -> 
                     FeynCalc`DotSimplify`Private`pid, 
                   FeynCalc`DotSimplify`Private`rest2], 
                  !FeynCalc`DotSimplify`Private`orderedQ[
                   {FeynCalc`DotSimplify`Private`a /. Pattern :> 
                      FeynCalc`DotSimplify`Private`pid, 
                    FeynCalc`DotSimplify`Private`b /. Pattern :> 
                      FeynCalc`DotSimplify`Private`pid}, 
                   FeynCalc`DotSimplify`Private`acommSortBy]]} /. 
              FeynCalc`DotSimplify`Private`holdDOT -> DOT /. 
             FeynCalc`DotSimplify`Private`condition :> Condition /. 
            FeynCalc`DotSimplify`Private`orderedQ :> OrderedQ}; 
         FeynCalc`DotSimplify`Private`cotorules[{}] = {}; 
         FeynCalc`DotSimplify`Private`cotorules[
           FeynCalc`DotSimplify`Private`a__List] := 
          Select[FeynCalc`DotSimplify`Private`ruleCommutator /@ 
             (FeynCalc`DotSimplify`Private`a /. 
                 FeynCalc`DotSimplify`Private`h:FCPartialD | LeftPartialD | 
                    RightPartialD | LeftRightPartialD | LeftRightPartialD2 | 
                    LeftNablaD | RightNablaD | LeftRightNablaD | 
                    LeftRightNablaD2 -> FeynCalc`DotSimplify`Private`hold[
                   FeynCalc`DotSimplify`Private`h] /. FCCommutator -> 
                 FeynCalc`DotSimplify`Private`commm /. HoldPattern :> 
                Identity /. RuleDelayed -> List), 
            FreeQ[#1, FeynCalc`DotSimplify`Private`ruleCommutator] & ] /; 
           FeynCalc`DotSimplify`Private`a =!= {}; 
         FeynCalc`DotSimplify`Private`actorules[{}] = {}; 
         FeynCalc`DotSimplify`Private`actorules[
           FeynCalc`DotSimplify`Private`a__List] := 
          Select[FeynCalc`DotSimplify`Private`ruleAntiCommutator /@ 
             (FeynCalc`DotSimplify`Private`a /. 
                 FeynCalc`DotSimplify`Private`h:FCPartialD | LeftPartialD | 
                    RightPartialD | LeftRightPartialD | LeftRightPartialD2 | 
                    LeftNablaD | RightNablaD | LeftRightNablaD | 
                    LeftRightNablaD2 -> FeynCalc`DotSimplify`Private`hold[
                   FeynCalc`DotSimplify`Private`h] /. FCAntiCommutator -> 
                 FeynCalc`DotSimplify`Private`acommm /. HoldPattern :> 
                Identity /. RuleDelayed -> List), 
            FreeQ[#1, FeynCalc`DotSimplify`Private`ruleAntiCommutator] & ] /; 
           FeynCalc`DotSimplify`Private`a =!= {}; Off[Rule::rhs]; 
         FeynCalc`DotSimplify`Private`commutatorEvaluationRules = 
          Flatten[FeynCalc`DotSimplify`Private`cotorules[DownValues @@ 
              {FCCommutator}]] //. FeynCalc`DotSimplify`Private`hold[
             FeynCalc`DotSimplify`Private`h_] :> 
            FeynCalc`DotSimplify`Private`h; 
         FeynCalc`DotSimplify`Private`antiCommutatorEvaluationRules = 
          Flatten[FeynCalc`DotSimplify`Private`actorules[DownValues @@ 
              {FCAntiCommutator}]] //. FeynCalc`DotSimplify`Private`hold[
             FeynCalc`DotSimplify`Private`h_] :> 
            FeynCalc`DotSimplify`Private`h; FCPrint[3, 
          "DotSimplify: FCCommutator rules: ", 
          FeynCalc`DotSimplify`Private`commutatorEvaluationRules, 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FCPrint[3, "DotSimplify: FCAntiCommutator rules: ", 
          FeynCalc`DotSimplify`Private`antiCommutatorEvaluationRules, 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[OptionValue[FCJoinDOTs] && 
            !FeynCalc`DotSimplify`Private`optExpanding, 
          FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
           FCPrint[1, "DotSimplify: Joining DOTs.", FCDoControl -> 
             FeynCalc`DotSimplify`Private`dsVerbose]; 
           FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
              DOT -> FeynCalc`DotSimplify`Private`holdDOT //. 
             {FeynCalc`DotSimplify`Private`holdDOT[
                 FeynCalc`DotSimplify`Private`a___, 
                 FeynCalc`DotSimplify`Private`b1_, 
                 FeynCalc`DotSimplify`Private`c___] + 
                FeynCalc`DotSimplify`Private`holdDOT[
                 FeynCalc`DotSimplify`Private`a___, 
                 FeynCalc`DotSimplify`Private`b2_, 
                 FeynCalc`DotSimplify`Private`c___] :> 
               FeynCalc`DotSimplify`Private`holdDOT[
                FeynCalc`DotSimplify`Private`a, 
                FeynCalc`DotSimplify`Private`b1 + 
                 FeynCalc`DotSimplify`Private`b2, 
                FeynCalc`DotSimplify`Private`c]}; 
           FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
             FeynCalc`DotSimplify`Private`holdDOT -> DOT; 
           FCPrint[1, "DotSimplify: Done joining DOTs, timing: ", 
            N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FCPrint[3, "DotSimplify: After joining DOTs: ", 
            FeynCalc`DotSimplify`Private`x, FCDoControl -> 
             FeynCalc`DotSimplify`Private`dsVerbose]]; 
         FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
         FCPrint[1, "DotSimplify: Doing simple noncommutative expansions.", 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
           SUNTrace -> FeynCalc`Package`sunTrace; 
         FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
             DOT -> FeynCalc`DotSimplify`Private`tmpDOT /. 
            FeynCalc`DotSimplify`Private`tmpDOT[
               FeynCalc`DotSimplify`Private`a__] /; FreeQ[
                {FeynCalc`DotSimplify`Private`a}, 
                FeynCalc`DotSimplify`Private`tmpDOT] && MatchQ[
                {FeynCalc`DotSimplify`Private`a}, {__DiracGamma}] :> 
             FeynCalc`DotSimplify`Private`holdDOT[
              FeynCalc`DotSimplify`Private`a] /. 
           FeynCalc`DotSimplify`Private`tmpDOT -> DOT; 
         FCPrint[3, "DotSimplify: After sorting out trivial DOTs: ", 
          FeynCalc`DotSimplify`Private`x, FCDoControl -> 
           FeynCalc`DotSimplify`Private`dsVerbose]; 
         FCPrint[1, 
          "DotSimplify: Simple noncommutative expansions done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
         FCPrint[1, "DotSimplify: Doing main noncommutative expansions.", 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FeynCalc`DotSimplify`Private`x = FixedPoint[
           FeynCalc`DotSimplify`Private`dotExpand, 
           FeynCalc`DotSimplify`Private`x, 
           FeynCalc`DotSimplify`Private`optMaxIterations]; 
         FCPrint[1, 
          "DotSimplify: Main noncommutative expansions done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
          FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
         FCPrint[4, "DotSimplify: After simpf: ", 
          FeynCalc`DotSimplify`Private`x, FCDoControl -> 
           FeynCalc`DotSimplify`Private`dsVerbose]; 
         If[ !FreeQ[FeynCalc`DotSimplify`Private`x, DiracChain], 
          FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
           FCPrint[1, "DotSimplify: Applying DiracChainFactor.", 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FeynCalc`DotSimplify`Private`x = DiracChainFactor[
             FeynCalc`DotSimplify`Private`x, FCI -> True]; 
           FCPrint[1, "DotSimplify: DiracChainFactor done, timing: ", 
            N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FCPrint[3, "DotSimplify: After DiracChainFactor: ", 
            FeynCalc`DotSimplify`Private`x, FCDoControl -> 
             FeynCalc`DotSimplify`Private`dsVerbose]]; 
         If[ !FreeQ[FeynCalc`DotSimplify`Private`x, PauliChain], 
          FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
           FCPrint[1, "DotSimplify: Applying PauliChainFactor.", 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FeynCalc`DotSimplify`Private`x = PauliChainFactor[
             FeynCalc`DotSimplify`Private`x, FCI -> True]; 
           FCPrint[1, "DotSimplify: PauliChainFactor done, timing: ", 
            N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
            FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
           FCPrint[3, "DotSimplify: After PauliChainFactor: ", 
            FeynCalc`DotSimplify`Private`x, FCDoControl -> 
             FeynCalc`DotSimplify`Private`dsVerbose]]; 
         FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
            FeynCalc`Package`sunTrace -> SUNTrace /. 
           FeynCalc`DotSimplify`Private`holdDOT -> DOT; 
         FeynCalc`DotSimplify`Private`x]; FCPrint[1, 
       "DotSimplify: Leaving the main loop, timing: ", 
       N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time0, 4], 
       FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
      FCPrint[2, "DotSimplify: After catch", FeynCalc`DotSimplify`Private`x, 
       FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
      If[ !FreeQ2[FeynCalc`DotSimplify`Private`x, {SUNTrace, DiracTrace}], 
       FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "DotSimplify: Pulling out nested SU(N) and Dirac traces. ", 
         FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
        FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x //. 
          {DOT[FeynCalc`DotSimplify`Private`a___, 
             (FeynCalc`DotSimplify`Private`b:DiracTrace | SUNTrace)[
              FeynCalc`DotSimplify`Private`arg__], 
             FeynCalc`DotSimplify`Private`c___] :> 
            FeynCalc`DotSimplify`Private`b[FeynCalc`DotSimplify`Private`arg]*
             DOT[FeynCalc`DotSimplify`Private`a, 
              FeynCalc`DotSimplify`Private`c], 
           (FeynCalc`DotSimplify`Private`tr1:DiracTrace | SUNTrace)[
             (FeynCalc`DotSimplify`Private`tr2:DiracTrace | SUNTrace)[
               FeynCalc`DotSimplify`Private`arg__]*
              (FeynCalc`DotSimplify`Private`a_)] :> 
            FeynCalc`DotSimplify`Private`tr2[
              FeynCalc`DotSimplify`Private`arg]*
             FeynCalc`DotSimplify`Private`tr1[
              FeynCalc`DotSimplify`Private`a], 
           (FeynCalc`DotSimplify`Private`tr1:DiracTrace | SUNTrace)[
              (FeynCalc`DotSimplify`Private`a_.)*
                (FeynCalc`DotSimplify`Private`b_) /;  !FreeQ2[
                 FeynCalc`DotSimplify`Private`b, {DiracTrace, SUNTrace}]] /; 
             NonCommFreeQ[FeynCalc`DotSimplify`Private`b /. (DiracTrace | 
                  SUNTrace)[___] :> 1] :> FeynCalc`DotSimplify`Private`b*
             FeynCalc`DotSimplify`Private`tr1[
              FeynCalc`DotSimplify`Private`a]}; FCPrint[1, "DotSimplify: Done \
pulling out nested SU(N) and Dirac traces, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DotSimplify`Private`time, 4], 
         FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
        FCPrint[3, 
         "DotSimplify: After pulling out nested SU(N) and Dirac traces.", 
         FeynCalc`DotSimplify`Private`x, FCDoControl -> 
          FeynCalc`DotSimplify`Private`dsVerbose]; ]; 
      If[ !FreeQ2[FeynCalc`DotSimplify`Private`x, {SUNT, PauliSigma, 
           PauliEta, PauliEtaC, PauliXi}] && 
        FreeQ[FeynCalc`DotSimplify`Private`x, QuantumField], 
       FeynCalc`DotSimplify`Private`time = AbsoluteTime[]; 
        FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x /. 
          DOT -> FeynCalc`DotSimplify`Private`holdDOT; 
        FCPrint[1, "DotSimplify: Pulling out SU(N) matrices", 
         FCDoControl -> FeynCalc`DotSimplify`Private`dsVerbose]; 
        FeynCalc`DotSimplify`Private`x = FeynCalc`DotSimplify`Private`x //. 
          FeynCalc`DotSimplify`Private`holdDOT[
