DiracSigmaExpand[FeynCalc`DiracSigmaExpand`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`DiracSigmaExpand`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`DiracSigmaExpand`Private`ex, 
      FeynCalc`DiracSigmaExpand`Private`null1, 
      FeynCalc`DiracSigmaExpand`Private`null2, 
      FeynCalc`DiracSigmaExpand`Private`uniqList, 
      FeynCalc`DiracSigmaExpand`Private`repRule, 
      FeynCalc`DiracSigmaExpand`Private`momList, 
      FeynCalc`DiracSigmaExpand`Private`rud, 
      FeynCalc`DiracSigmaExpand`Private`uniqListEval, 
      FeynCalc`DiracSigmaExpand`Private`res}, 
     FeynCalc`DiracSigmaExpand`Private`momList = OptionValue[Momentum]; 
      If[ !OptionValue[FCI], FeynCalc`DiracSigmaExpand`Private`ex = 
        FCI[FeynCalc`DiracSigmaExpand`Private`expr], 
       FeynCalc`DiracSigmaExpand`Private`ex = 
        FeynCalc`DiracSigmaExpand`Private`expr]; 
      If[FreeQ[FeynCalc`DiracSigmaExpand`Private`ex, DiracSigma], 
       Return[FeynCalc`DiracSigmaExpand`Private`ex]]; 
      FeynCalc`DiracSigmaExpand`Private`uniqList = 
       Sort[DeleteDuplicates[Cases[FeynCalc`DiracSigmaExpand`Private`ex + 
           FeynCalc`DiracSigmaExpand`Private`null1 + 
           FeynCalc`DiracSigmaExpand`Private`null2, DiracSigma[
           FeynCalc`DiracSigmaExpand`Private`arg__ /; 
             !FreeQ2[{FeynCalc`DiracSigmaExpand`Private`arg}, 
              {Momentum, CartesianMomentum}]], Infinity]]]; 
      If[FeynCalc`DiracSigmaExpand`Private`momList =!= All && 
        Head[FeynCalc`DiracSigmaExpand`Private`momList] === List, 
       FeynCalc`DiracSigmaExpand`Private`uniqList = 
        Select[FeynCalc`DiracSigmaExpand`Private`uniqList, 
          !FreeQ2[#1, FeynCalc`DiracSigmaExpand`Private`momList] & ]]; 
      If[OptionValue[DiracGammaExpand], 
       FeynCalc`DiracSigmaExpand`Private`uniqListEval = 
        DiracGammaExpand[FeynCalc`DiracSigmaExpand`Private`uniqList, 
         FCI -> True, Momentum -> FeynCalc`DiracSigmaExpand`Private`momList, 
         DiracSigmaExpand -> False], 
       FeynCalc`DiracSigmaExpand`Private`uniqListEval = 
         FeynCalc`DiracSigmaExpand`Private`uniqList; ]; 
      FeynCalc`DiracSigmaExpand`Private`uniqListEval = 
       FeynCalc`DiracSigmaExpand`Private`uniqListEval /. 
        FeynCalc`DiracSigmaExpand`Private`z_DiracSigma :> 
         Distribute[FeynCalc`DiracSigmaExpand`Private`z]; 
      FeynCalc`DiracSigmaExpand`Private`repRule = 
       Thread[FeynCalc`DiracSigmaExpand`Private`rud[
          FeynCalc`DiracSigmaExpand`Private`uniqList, 
          FeynCalc`DiracSigmaExpand`Private`uniqListEval]] /. 
        FeynCalc`DiracSigmaExpand`Private`rud -> RuleDelayed; 
      FeynCalc`DiracSigmaExpand`Private`res = 
       FeynCalc`DiracSigmaExpand`Private`ex /. 
        Dispatch[FeynCalc`DiracSigmaExpand`Private`repRule]; 
      If[OptionValue[FCE], FeynCalc`DiracSigmaExpand`Private`res = 
        FCE[FeynCalc`DiracSigmaExpand`Private`res]]; 
      FeynCalc`DiracSigmaExpand`Private`res]
 
Options[DiracSigmaExpand] = {DiracGammaExpand -> False, 
