Options[PauliSigmaExpand] = {FeynCalcExternal -> False, 
     FeynCalcInternal -> False, Momentum -> All}
 
PauliSigmaExpand /: PauliSigmaExpand::fail = "Something went while expanding \
momenta contracted with Pauli matrices.\nEvaluation aborted!"
 
PauliSigmaExpand /: PauliSigmaExpand::usage = "PauliSigmaExpand[exp] expands \
all PauliSigma[Momentum[a+b+..]] in exp into\n(PauliSigma[Momentum[a]] + \
PauliSigma[Momentum[b]] + ...)."
 
FeynCalc`PauliSigmaExpand`Private`psev[FeynCalc`PauliSigmaExpand`Private`x_, 
     FeynCalc`PauliSigmaExpand`Private`di_:3] := 
    FeynCalc`PauliSigmaExpand`Private`psevlin[
     Expand[MomentumExpand[FeynCalc`PauliSigmaExpand`Private`x], Momentum], 
     FeynCalc`PauliSigmaExpand`Private`di]
 
FeynCalc`PauliSigmaExpand`Private`psevlin[
     FeynCalc`PauliSigmaExpand`Private`x_Plus, 
     FeynCalc`PauliSigmaExpand`Private`di_:3] := 
    (FeynCalc`PauliSigmaExpand`Private`psevlin[#1, 
       FeynCalc`PauliSigmaExpand`Private`di] & ) /@ 
     FeynCalc`PauliSigmaExpand`Private`x
 
Attributes[SUND] = {Orderless}
 
SUND[OptionsPattern[], FeynCalc`SharedObjects`Private`a_SUNIndex, 
     FeynCalc`SharedObjects`Private`a_SUNIndex, 
     FeynCalc`SharedObjects`Private`b:Except[_?OptionQ]] := 
    0 &&  !OptionQ[FeynCalc`SharedObjects`Private`b]
 
SUND[OptionsPattern[], FeynCalc`SharedObjects`Private`a_, 
     FeynCalc`SharedObjects`Private`b_, FeynCalc`SharedObjects`Private`c:
      Except[_?OptionQ]] := 
    2*SUNTrace[SUNT[SUNIndex[FeynCalc`SharedObjects`Private`a]] . 
         SUNT[SUNIndex[FeynCalc`SharedObjects`Private`b]] . 
         SUNT[SUNIndex[FeynCalc`SharedObjects`Private`c]]] + 
      2*SUNTrace[SUNT[SUNIndex[FeynCalc`SharedObjects`Private`b]] . 
         SUNT[SUNIndex[FeynCalc`SharedObjects`Private`a]] . 
         SUNT[SUNIndex[FeynCalc`SharedObjects`Private`c]]] /; 
     OptionValue[Explicit]
 
SUND /: MakeBoxes[SUND[FeynCalc`SharedObjectsTypesetting`Private`a_, 
       FeynCalc`SharedObjectsTypesetting`Private`b_, 
       FeynCalc`SharedObjectsTypesetting`Private`c:Except[_?OptionQ], 
       OptionsPattern[]], TraditionalForm] := SuperscriptBox["d", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`a, 
       FeynCalc`SharedObjectsTypesetting`Private`b, 
       FeynCalc`SharedObjectsTypesetting`Private`c]]
 
Options[SUND] = {Explicit -> False}
 
SUND /: SUND::usage = "SUND[a, b, c] are the symmetric $SU(N)$ $d_{abc}$."
 
FeynCalc`Package`colorSimplifyGeneric[0] := 0
 
