     FeynCalc`SUNSimplify`Private`ex_Plus] := 
    FeynCalc`Package`colorSimplifyGeneric /@ FeynCalc`SUNSimplify`Private`ex
 
FeynCalc`Package`colorSimplifyGeneric[FeynCalc`SUNSimplify`Private`rest_] := 
    FeynCalc`SUNSimplify`Private`rest /; 
     FreeQ2[FeynCalc`SUNSimplify`Private`rest, {SUNIndex, SUNFIndex, 
       FeynCalc`Package`sunTrace}]
 
