      FeynCalc`Package`sunTrace[FeynCalc`Package`holdDOTColor[]]^
       (FeynCalc`SUNSimplify`Private`n_.)] := 
    SUNN^FeynCalc`SUNSimplify`Private`n*FeynCalc`Package`colorSimplifyGeneric[
      FeynCalc`SUNSimplify`Private`rest]
 
FeynCalc`Package`colorSimplifyGeneric[(_.)*FeynCalc`Package`sunTrace[
       FeynCalc`Package`holdDOTColor[SUNT[_SUNIndex]]]] := 0
 
FeynCalc`Package`colorSimplifyGeneric[(_.)*FeynCalc`Package`sunTrace[
       SUNT[_SUNIndex]]] := 0
 
