FeynCalc`SUNTrace`Private`sunTraceEvaluate[
     FeynCalc`Package`holdDOTColor[
       SUNT[FeynCalc`SUNTrace`Private`a_SUNIndex], 
       SUNT[FeynCalc`SUNTrace`Private`b_SUNIndex], 
       SUNT[FeynCalc`SUNTrace`Private`c_SUNIndex]]*
      (FeynCalc`SUNTrace`Private`rest_.)] := 
    FeynCalc`SUNTrace`Private`rest*(SUND[FeynCalc`SUNTrace`Private`a, 
         FeynCalc`SUNTrace`Private`b, FeynCalc`SUNTrace`Private`c]/4 + 
       I*(SUNF[FeynCalc`SUNTrace`Private`a, FeynCalc`SUNTrace`Private`b, 
          FeynCalc`SUNTrace`Private`c]/4)) /; 
     FreeQ[FeynCalc`SUNTrace`Private`rest, SUNT]
 
FeynCalc`SUNTrace`Private`sunTraceEvaluate[
     FeynCalc`Package`holdDOTColor[
       SUNT[FeynCalc`SUNTrace`Private`a_SUNIndex], 
       SUNT[FeynCalc`SUNTrace`Private`b_SUNIndex], 
       SUNT[FeynCalc`SUNTrace`Private`c_SUNIndex], 
       SUNT[FeynCalc`SUNTrace`Private`d_SUNIndex]]*
      (FeynCalc`SUNTrace`Private`rest_.)] := 
    Block[{FeynCalc`SUNTrace`Private`e}, FeynCalc`SUNTrace`Private`e = 
        SUNIndex[FCGV[ToString[Unique["sun"]]]]; 
       FeynCalc`SUNTrace`Private`rest*
        ((1/4/SUNN)*(SUNDelta[FeynCalc`SUNTrace`Private`a, 
             FeynCalc`SUNTrace`Private`b]*SUNDelta[
             FeynCalc`SUNTrace`Private`c, FeynCalc`SUNTrace`Private`d] - 
           SUNDelta[FeynCalc`SUNTrace`Private`a, FeynCalc`SUNTrace`Private`c]*
            SUNDelta[FeynCalc`SUNTrace`Private`b, 
             FeynCalc`SUNTrace`Private`d] + 
           SUNDelta[FeynCalc`SUNTrace`Private`a, FeynCalc`SUNTrace`Private`d]*
            SUNDelta[FeynCalc`SUNTrace`Private`b, 
             FeynCalc`SUNTrace`Private`c]) + 
         (1/8)*(SUND[FeynCalc`SUNTrace`Private`a, 
             FeynCalc`SUNTrace`Private`b, FeynCalc`SUNTrace`Private`e]*
            SUND[FeynCalc`SUNTrace`Private`c, FeynCalc`SUNTrace`Private`d, 
             FeynCalc`SUNTrace`Private`e] - SUND[FeynCalc`SUNTrace`Private`a, 
             FeynCalc`SUNTrace`Private`c, FeynCalc`SUNTrace`Private`e]*
            SUND[FeynCalc`SUNTrace`Private`b, FeynCalc`SUNTrace`Private`d, 
             FeynCalc`SUNTrace`Private`e] + SUND[FeynCalc`SUNTrace`Private`a, 
             FeynCalc`SUNTrace`Private`d, FeynCalc`SUNTrace`Private`e]*
            SUND[FeynCalc`SUNTrace`Private`b, FeynCalc`SUNTrace`Private`c, 
             FeynCalc`SUNTrace`Private`e]) + 
         (I/8)*(SUND[FeynCalc`SUNTrace`Private`a, 
             FeynCalc`SUNTrace`Private`d, FeynCalc`SUNTrace`Private`e]*
            SUNF[FeynCalc`SUNTrace`Private`b, FeynCalc`SUNTrace`Private`c, 
             FeynCalc`SUNTrace`Private`e] - SUNF[FeynCalc`SUNTrace`Private`a, 
             FeynCalc`SUNTrace`Private`d, FeynCalc`SUNTrace`Private`e]*
            SUND[FeynCalc`SUNTrace`Private`b, FeynCalc`SUNTrace`Private`c, 
             FeynCalc`SUNTrace`Private`e]))] /; 
     FreeQ[FeynCalc`SUNTrace`Private`rest, SUNT]
 
