         (I/2)*SUNF[FeynCalc`SUNTrace`Private`a, FeynCalc`SUNTrace`Private`b, 
           FeynCalc`SUNTrace`Private`f]*
          FeynCalc`SUNTrace`Private`sunTraceEvaluate[
           FeynCalc`Package`holdDOTColor[SUNT[FeynCalc`SUNTrace`Private`f], 
            SUNT[FeynCalc`SUNTrace`Private`c], 
            SUNT[FeynCalc`SUNTrace`Private`d], 
            FeynCalc`SUNTrace`Private`more]])] /; 
     FreeQ[FeynCalc`SUNTrace`Private`rest, SUNT]
 
