          FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
        If[ !MatchQ[FeynCalc`FCCanonicalizeDummyIndices`Private`indexExtract, 
           {{___CartesianIndex}...}], 
         Message[FCCanonicalizeDummyIndices::failmsg, 
           "Failed to  properly extract dummy Cartesian indices."]; 
          FCPrint[1, "FCCanonicalizDummyIndices: Entering with: ", 
           FeynCalc`FCCanonicalizeDummyIndices`Private`indexExtract, 
           FCDoControl -> 
            FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
          Abort[]]; 
        FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar = 
         (Function[FeynCalc`FCCanonicalizeDummyIndices`Private`x, 
             MapIndexed[#1 -> CartesianIndex[
                 FeynCalc`FCCanonicalizeDummyIndices`Private`cihead[
                  FeynCalc`FCCanonicalizeDummyIndices`Private`fu[#2, 
                   FeynCalc`FCCanonicalizeDummyIndices`Private`seedCar]]] & , 
              FeynCalc`FCCanonicalizeDummyIndices`Private`x]][#1] & ) /@ 
          DeleteDuplicates /@ 
           (FeynCalc`FCCanonicalizeDummyIndices`Private`indexExtract /. 
            CartesianIndex[FeynCalc`FCCanonicalizeDummyIndices`Private`aa_, 
              _] :> CartesianIndex[
              FeynCalc`FCCanonicalizeDummyIndices`Private`aa]); 
        FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar = 
         FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar /. 
            Rule -> FeynCalc`FCCanonicalizeDummyIndices`Private`rule /. 
           {FeynCalc`FCCanonicalizeDummyIndices`Private`rule[
              CartesianIndex[FeynCalc`FCCanonicalizeDummyIndices`Private`x_], 
              CartesianIndex[
               FeynCalc`FCCanonicalizeDummyIndices`Private`y_]] :> 
             (FeynCalc`FCCanonicalizeDummyIndices`Private`rule[CartesianIndex[
                 FeynCalc`FCCanonicalizeDummyIndices`Private`x, #1], 
                CartesianIndex[FeynCalc`FCCanonicalizeDummyIndices`Private`y, 
                 #1]] & ) /@ 
              FeynCalc`FCCanonicalizeDummyIndices`Private`dimensions} /. 
          FeynCalc`FCCanonicalizeDummyIndices`Private`rule -> Rule; 
        FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar = 
         DeleteDuplicates /@ Flatten /@ 
           FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar; 
        FCPrint[2, "FCCanonicalizeDummyIndices: repIndexListCar: ", 
         FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar, 
         FCDoControl -> 
          FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose], 
       FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar = 
        Sequence[]]; FeynCalc`FCCanonicalizeDummyIndices`Private`otherHeads = 
       Complement[Union[FeynCalc`FCCanonicalizeDummyIndices`Private`indhead], 
        {LorentzIndex, CartesianIndex, SUNIndex, SUNFIndex, DiracIndex, 
         PauliIndex}]; FCPrint[1, 
       "FCCanonicalizeDummyIndices: Custom index heads present: ", 
       FeynCalc`FCCanonicalizeDummyIndices`Private`otherHeads, 
       FCDoControl -> 
        FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
      If[FeynCalc`FCCanonicalizeDummyIndices`Private`otherHeads =!= {}, 
       FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListsCustom = 
         (FeynCalc`FCCanonicalizeDummyIndices`Private`makeRepIndexList[#1, 
            ToExpression[StringJoin[ToString[#1], "head"]], 
            Unique[ToLowerCase[ToString[#1]]], 
            FeynCalc`FCCanonicalizeDummyIndices`Private`fu, 
            FeynCalc`FCCanonicalizeDummyIndices`Private`finalList, 
            FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions] & ) \
/@ FeynCalc`FCCanonicalizeDummyIndices`Private`otherHeads; 
        FCPrint[3, "FCCanonicalizeDummyIndices: repIndexListsCustom: ", 
         FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListsCustom, 
         FCDoControl -> 
          FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; ]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal = 
       {FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListLor, 
        FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListCar, 
        FeynCalc`FCCanonicalizeDummyIndices`Private`makeRepIndexList[
         SUNIndex, FeynCalc`FCCanonicalizeDummyIndices`Private`sunhead, 
         Unique["sun"], FeynCalc`FCCanonicalizeDummyIndices`Private`fu, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`finalList, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions], 
        FeynCalc`FCCanonicalizeDummyIndices`Private`makeRepIndexList[
         SUNFIndex, FeynCalc`FCCanonicalizeDummyIndices`Private`sunfhead, 
         Unique["sunf"], FeynCalc`FCCanonicalizeDummyIndices`Private`fu, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`finalList, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions], 
        FeynCalc`FCCanonicalizeDummyIndices`Private`makeRepIndexList[
         DiracIndex, FeynCalc`FCCanonicalizeDummyIndices`Private`dihead, 
         Unique["di"], FeynCalc`FCCanonicalizeDummyIndices`Private`fu, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`finalList, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions], 
        FeynCalc`FCCanonicalizeDummyIndices`Private`makeRepIndexList[
         PauliIndex, FeynCalc`FCCanonicalizeDummyIndices`Private`pihead, 
         Unique["pi"], FeynCalc`FCCanonicalizeDummyIndices`Private`fu, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`finalList, 
         FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions]}; 
      If[FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListsCustom =!= 
        {}, FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal = 
         Join[FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal, 
          FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListsCustom]; ]\
; FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal = 
       Flatten /@ Transpose[
         FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal]; 
      FCPrint[2, "FCCanonicalizeDummyIndices: List of replacements: ", 
       FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal, 
       FCDoControl -> 
        FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`cList = 
       {{OptionValue[LorentzIndexNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`lihead}, 
        {OptionValue[CartesianIndexNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`cihead}, 
        {OptionValue[SUNIndexNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`sunhead}, 
        {OptionValue[SUNFIndexNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`sunfhead}, 
        {OptionValue[DiracIndexNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`dihead}, 
        {OptionValue[PauliIndexNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`pihead}}; 
      If[OptionValue[CustomIndexNames] =!= {}, 
       FeynCalc`FCCanonicalizeDummyIndices`Private`cList = 
         Join[FeynCalc`FCCanonicalizeDummyIndices`Private`cList, 
          ({Last[#1], ToExpression[StringJoin[ToString[First[#1]], 
               "head"]]} & ) /@ OptionValue[CustomIndexNames]]; ]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`cList = 
       FeynCalc`FCCanonicalizeDummyIndices`Private`cList /. 
        {{}, _} :> Unevaluated[Sequence[]]; 
      If[ !FreeQ2[FeynCalc`FCCanonicalizeDummyIndices`Private`ex, 
         Flatten[FeynCalc`FCCanonicalizeDummyIndices`Private`cList /. 
           {FeynCalc`FCCanonicalizeDummyIndices`Private`l_List, _} :> 
            FeynCalc`FCCanonicalizeDummyIndices`Private`l]], 
       Message[FCCanonicalizeDummyIndices::failmsg, "Dummy index names \
supplied for renaming are already present in the expression!"]; Abort[]]; 
      FCPrint[2, "FCCanonicalizeDummyIndices: cList: ", 
       FeynCalc`FCCanonicalizeDummyIndices`Private`cList, 
       FCDoControl -> 
        FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
      If[FeynCalc`FCCanonicalizeDummyIndices`Private`cList =!= {}, 
       FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule = 
         Flatten[(FeynCalc`FCCanonicalizeDummyIndices`Private`renameDummies[
             #1[[1]], #1[[2]], 
             FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal] & \
) /@ FeynCalc`FCCanonicalizeDummyIndices`Private`cList]; 
        FCPrint[2, "FCCanonicalizeDummyIndices: User-supplied renaming of \
dummy indices: ", FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule, 
         FCDoControl -> 
          FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
        FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal = 
         FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal /. 
          FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule; ]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`canIndexList = 
       MapIndexed[
        #1 /. First[
           FeynCalc`FCCanonicalizeDummyIndices`Private`repIndexListTotal[[
            #2]]] & , 
        FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions]; 
      FCPrint[3, "FCCanonicalizeDummyIndices: canIndexList: ", 
       FeynCalc`FCCanonicalizeDummyIndices`Private`canIndexList, 
       FCDoControl -> 
        FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`finalRepList = 
       Thread[
        FeynCalc`FCCanonicalizeDummyIndices`Private`uniqueExpressions -> 
         FeynCalc`FCCanonicalizeDummyIndices`Private`canIndexList]; 
      FCPrint[3, "FCCanonicalizeDummyIndices: canIndexList: ", 
       FeynCalc`FCCanonicalizeDummyIndices`Private`finalRepList, 
       FCDoControl -> 
        FeynCalc`FCCanonicalizeDummyIndices`Private`canodummyVerbose]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`res = 
       FeynCalc`FCCanonicalizeDummyIndices`Private`rest0 + 
           FeynCalc`FCCanonicalizeDummyIndices`Private`tmp /. 
          FeynCalc`FCCanonicalizeDummyIndices`Private`finalRepList /. 
         FeynCalc`FCCanonicalizeDummyIndices`Private`isoHead | 
           FeynCalc`FCCanonicalizeDummyIndices`Private`lihead | 
           FeynCalc`FCCanonicalizeDummyIndices`Private`cihead | 
           FeynCalc`FCCanonicalizeDummyIndices`Private`sunhead | 
           FeynCalc`FCCanonicalizeDummyIndices`Private`sunfhead | 
           FeynCalc`FCCanonicalizeDummyIndices`Private`dihead | 
           FeynCalc`FCCanonicalizeDummyIndices`Private`pihead -> Identity /. 
        FeynCalc`FCCanonicalizeDummyIndices`Private`times -> Times; 
      If[OptionValue[FCE], FeynCalc`FCCanonicalizeDummyIndices`Private`res = 
        FCE[FeynCalc`FCCanonicalizeDummyIndices`Private`res]]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`res]
 
Options[FCCanonicalizeDummyIndices] = {CartesianIndexNames -> {}, 
     CustomIndexNames -> {}, DiracChainExpand -> True, DiracIndexNames -> {}, 
     DotSimplify -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCTraceExpand -> True, 
     FCParallelize -> False, FCVerbose -> False, 
     Function -> Function[{FeynCalc`FCCanonicalizeDummyIndices`Private`x, 
        FeynCalc`FCCanonicalizeDummyIndices`Private`seed}, 
       FCGV[StringJoin[ToString[
          FeynCalc`FCCanonicalizeDummyIndices`Private`seed], 
         ToString[Identity @@ 
           FeynCalc`FCCanonicalizeDummyIndices`Private`x]]]], 
     Head -> {LorentzIndex, CartesianIndex, SUNIndex, SUNFIndex, DiracIndex, 
       PauliIndex}, LorentzIndexNames -> {}, Momentum -> All, 
     NotMomentum -> {}, PauliChainExpand -> True, PauliIndexNames -> {}, 
     SUNFIndexNames -> {}, SUNIndexNames -> {}}
 
FCCanonicalizeDummyIndices /: FCCanonicalizeDummyIndices::failmsg = "Error! \
FCCanonicalizeDummyIndices has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCCanonicalizeDummyIndices /: FCCanonicalizeDummyIndices::usage = "FCCanonica\
lizeDummyIndices[expr] canonicalizes dummy indices in \
the\nexpression.\n\nFollowing index types are supported: LorentzIndex, \
CartesianIndex, SUNIndex,\nSUNFIndex, DiracIndex, PauliIndex\n\nIn the case \
of Lorentz indices the option Momentum provides a possibility to\nlimit the \
canonicalization only to particular Momenta. The option\nLorentzIndexNames \
can be used to assign specific names to  the canonicalized\nindices, to have \
say $\\mu$, $\\nu$, $\\rho$ etc. instead of some random names.\n\nFor other \
index types the corresponding options are called\nCartesianIndexNames, \
SUNIndexNames, SUNFIndexNames, DiracIndexNames and\nPauliIndexNames."
 
NotMomentum /: NotMomentum::usage = "NotMomentum is an option of \
FCCanonicalizeDummyIndices. It specifies a list of\nmomenta for which\nno \
canonicalization should be done."
 
DiracChainExpand[(FeynCalc`DiracChainExpand`Private`a_) == 
      (FeynCalc`DiracChainExpand`Private`b_), 
     FeynCalc`DiracChainExpand`Private`opts:OptionsPattern[]] := 
    DiracChainExpand[FeynCalc`DiracChainExpand`Private`a, 
      FeynCalc`DiracChainExpand`Private`opts] == DiracChainExpand[
      FeynCalc`DiracChainExpand`Private`b, 
      FeynCalc`DiracChainExpand`Private`opts]
 
DiracChainExpand[FeynCalc`DiracChainExpand`Private`expr_List, 
     FeynCalc`DiracChainExpand`Private`opts:OptionsPattern[]] := 
    (DiracChainExpand[#1, FeynCalc`DiracChainExpand`Private`opts] & ) /@ 
     FeynCalc`DiracChainExpand`Private`expr
 
DiracChainExpand[FeynCalc`DiracChainExpand`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`DiracChainExpand`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`DiracChainExpand`Private`ex, 
      FeynCalc`DiracChainExpand`Private`null1, 
      FeynCalc`DiracChainExpand`Private`null2, 
      FeynCalc`DiracChainExpand`Private`uniqList, 
      FeynCalc`DiracChainExpand`Private`solsList, 
      FeynCalc`DiracChainExpand`Private`repRule, 
      FeynCalc`DiracChainExpand`Private`ruleDelayed, 
      FeynCalc`DiracChainExpand`Private`res, 
      FeynCalc`DiracChainExpand`Private`rhs}, 
     FeynCalc`DiracChainExpand`Private`momList = OptionValue[Momentum]; 
      FeynCalc`DiracChainExpand`Private`optDotSimplify = 
       OptionValue[DotSimplify]; 
      FeynCalc`DiracChainExpand`Private`optDiracGammaExpand = 
       OptionValue[DiracGammaExpand]; If[ !OptionValue[FCI], 
       FeynCalc`DiracChainExpand`Private`ex = 
        FCI[FeynCalc`DiracChainExpand`Private`expr], 
       FeynCalc`DiracChainExpand`Private`ex = 
        FeynCalc`DiracChainExpand`Private`expr]; 
      If[FreeQ[FeynCalc`DiracChainExpand`Private`ex, DiracChain], 
       Return[FeynCalc`DiracChainExpand`Private`ex]]; 
      FeynCalc`DiracChainExpand`Private`uniqList = 
       Sort[DeleteDuplicates[Cases[FeynCalc`DiracChainExpand`Private`ex + 
           FeynCalc`DiracChainExpand`Private`null1 + 
           FeynCalc`DiracChainExpand`Private`null2, DiracChain[__], 
          Infinity]]]; If[FeynCalc`DiracChainExpand`Private`momList =!= 
         All && Head[FeynCalc`DiracChainExpand`Private`momList] === List, 
       FeynCalc`DiracChainExpand`Private`uniqList = 
        Select[FeynCalc`DiracChainExpand`Private`uniqList, 
          !FreeQ2[#1, FeynCalc`DiracChainExpand`Private`momList] & ]]; 
      FeynCalc`DiracChainExpand`Private`rhs = 
       FeynCalc`DiracChainExpand`Private`uniqList /. DiracChain -> 
          FeynCalc`DiracChainExpand`Private`chLin /. 
        FeynCalc`DiracChainExpand`Private`chLinExp -> DiracChain; 
      If[OptionValue[DiracChainFactor], 
       FeynCalc`DiracChainExpand`Private`rhs = DiracChainFactor[
         FeynCalc`DiracChainExpand`Private`rhs, FCI -> True]]; 
      FeynCalc`DiracChainExpand`Private`repRule = 
       Thread[FeynCalc`DiracChainExpand`Private`ruleDelayed[
          FeynCalc`DiracChainExpand`Private`uniqList, 
          FeynCalc`DiracChainExpand`Private`rhs]] /. 
        FeynCalc`DiracChainExpand`Private`ruleDelayed -> RuleDelayed; 
      If[ !FreeQ2[FeynCalc`DiracChainExpand`Private`repRule, 
         {FeynCalc`DiracChainExpand`Private`chLin, 
          FeynCalc`DiracChainExpand`Private`chLinExp}], 
       Message[DiracChainExpand::fail]; Abort[]]; 
      FeynCalc`DiracChainExpand`Private`res = 
       FeynCalc`DiracChainExpand`Private`ex /. 
        Dispatch[FeynCalc`DiracChainExpand`Private`repRule]; 
      If[OptionValue[FCE], FeynCalc`DiracChainExpand`Private`res = 
        FCE[FeynCalc`DiracChainExpand`Private`res]]; 
      FeynCalc`DiracChainExpand`Private`res]
 
Options[DiracChainExpand] = {DiracChainFactor -> True, 
     DiracGammaExpand -> True, DotSimplify -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, Momentum -> All}
 
DiracChainExpand /: DiracChainExpand::fail = "Something went wrong while \
expanding Dirach chains with explicit indices.\nEvaluation aborted! "
 
DiracChainExpand /: DiracChainExpand::usage = "DiracChainExpand[exp] expands \
all Dirac chains with explicit indices using\nlinearity, e.g. \
DCHN[GA[p1]+GA[p2]+m,i,j] \
becomes\nDCHN[GA[p1],i,j]+DCHN[GA[p2],i,j]+m*DCHN[1,i,j]."
 
FeynCalc`DiracChainExpand`Private`null1 /: 
    FeynCalc`DiracChainExpand`Private`null1::usage = ""
 
FeynCalc`DiracChainExpand`Private`null2 /: 
    FeynCalc`DiracChainExpand`Private`null2::usage = ""
 
FeynCalc`DiracChainExpand`Private`momList /: 
    FeynCalc`DiracChainExpand`Private`momList::usage = ""
 
FeynCalc`DiracChainExpand`Private`optDotSimplify /: 
    FeynCalc`DiracChainExpand`Private`optDotSimplify::usage = ""
 
FeynCalc`DiracChainExpand`Private`optDiracGammaExpand /: 
    FeynCalc`DiracChainExpand`Private`optDiracGammaExpand::usage = ""
 
FeynCalc`DiracChainExpand`Private`chLin[
     FeynCalc`DiracChainExpand`Private`xx_, 
     FeynCalc`DiracChainExpand`Private`i_] := 
    FeynCalc`DiracChainExpand`Private`chLinExp[
     FeynCalc`DiracChainExpand`Private`xx, 
     FeynCalc`DiracChainExpand`Private`i]
 
FeynCalc`DiracChainExpand`Private`chLin[
     FeynCalc`DiracChainExpand`Private`xx_, 
     FeynCalc`DiracChainExpand`Private`i:_DiracIndex | _ExplicitDiracIndex | 
       _Spinor, FeynCalc`DiracChainExpand`Private`j:
      _DiracIndex | _ExplicitDiracIndex | _Spinor] := 
    (FeynCalc`DiracChainExpand`Private`chLinExp[#1, 
       FeynCalc`DiracChainExpand`Private`i, 
       FeynCalc`DiracChainExpand`Private`j] & ) /@ 
     (FeynCalc`DiracChainExpand`Private`expandFu[
       FeynCalc`DiracChainExpand`Private`xx] + 
      FeynCalc`DiracChainExpand`Private`null1 + 
      FeynCalc`DiracChainExpand`Private`null2)
 
FeynCalc`DiracChainExpand`Private`chLin /: 
    FeynCalc`DiracChainExpand`Private`chLin::usage = ""
 
FeynCalc`DiracChainExpand`Private`chLinExp[
     FeynCalc`DiracChainExpand`Private`null1 | 
      FeynCalc`DiracChainExpand`Private`null2, __] := 0
 
FeynCalc`DiracChainExpand`Private`chLinExp /: 
    FeynCalc`DiracChainExpand`Private`chLinExp::usage = ""
 
FeynCalc`DiracChainExpand`Private`expandFu[
     FeynCalc`DiracChainExpand`Private`xx_] := 
    (FeynCalc`DiracChainExpand`Private`tmp = 
      Expand[FeynCalc`DiracChainExpand`Private`xx]; 
     If[FeynCalc`DiracChainExpand`Private`optDiracGammaExpand, 
      FeynCalc`DiracChainExpand`Private`tmp = DiracGammaExpand[
         FeynCalc`DiracChainExpand`Private`tmp, FCI -> True, 
         Momentum -> FeynCalc`DiracChainExpand`Private`momList]; ]; 
     If[FeynCalc`DiracChainExpand`Private`optDotSimplify, 
      FeynCalc`DiracChainExpand`Private`tmp = DotSimplify[
         FeynCalc`DiracChainExpand`Private`tmp, FCI -> True]; ]; 
     FeynCalc`DiracChainExpand`Private`tmp)
 
FeynCalc`DiracChainExpand`Private`tmp /: 
    FeynCalc`DiracChainExpand`Private`tmp::usage = ""
 
DiracChainFactor[(FeynCalc`DiracChainFactor`Private`a_) == 
      (FeynCalc`DiracChainFactor`Private`b_), 
     FeynCalc`DiracChainFactor`Private`opts:OptionsPattern[]] := 
    DiracChainFactor[FeynCalc`DiracChainFactor`Private`a, 
      FeynCalc`DiracChainFactor`Private`opts] == DiracChainFactor[
      FeynCalc`DiracChainFactor`Private`b, 
      FeynCalc`DiracChainFactor`Private`opts]
 
DiracChainFactor[FeynCalc`DiracChainFactor`Private`expr_List, 
     FeynCalc`DiracChainFactor`Private`opts:OptionsPattern[]] := 
    (DiracChainFactor[#1, FeynCalc`DiracChainFactor`Private`opts] & ) /@ 
     FeynCalc`DiracChainFactor`Private`expr
 
DiracChainFactor[FeynCalc`DiracChainFactor`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`DiracChainFactor`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`DiracChainFactor`Private`ex, 
      FeynCalc`DiracChainFactor`Private`moms, 
      FeynCalc`DiracChainFactor`Private`res, 
      FeynCalc`DiracChainFactor`Private`diracChains}, 
     If[OptionValue[FCI], FeynCalc`DiracChainFactor`Private`ex = 
        FeynCalc`DiracChainFactor`Private`expr, 
       FeynCalc`DiracChainFactor`Private`ex = 
        FCI[FeynCalc`DiracChainFactor`Private`expr]]; 
      If[FreeQ[FeynCalc`DiracChainFactor`Private`ex, DiracChain], 
       Return[FeynCalc`DiracChainFactor`Private`ex]]; 
      FeynCalc`DiracChainFactor`Private`diracChains = 
       Cases2[FeynCalc`DiracChainFactor`Private`ex, DiracChain]; 
      If[FeynCalc`DiracChainFactor`Private`diracChains =!= {}, 
       FeynCalc`DiracChainFactor`Private`res = 
        FeynCalc`DiracChainFactor`Private`ex /. 
         Dispatch[Thread[FeynCalc`DiracChainFactor`Private`diracChains -> 
            FeynCalc`DiracChainFactor`Private`chainFactor[
             FeynCalc`DiracChainFactor`Private`diracChains]]]]; 
      If[OptionValue[FCE], FeynCalc`DiracChainFactor`Private`res = 
        FCE[FeynCalc`DiracChainFactor`Private`res]]; 
      FeynCalc`DiracChainFactor`Private`res]
 
Options[DiracChainFactor] = {FeynCalcInternal -> False, 
     FeynCalcExternal -> False}
 
DiracChainFactor /: DiracChainFactor::usage = "DiracChainFactor[exp] factors \
out all expressions inside a DiracChain to which\nthe chain doesn't apply. \
For example, all objects that are not Dirac matrices\ncan be safely factrored \
out from every Dirac chain."
 
FeynCalc`DiracChainFactor`Private`chainFactor[
     FeynCalc`DiracChainFactor`Private`x_] := 
    FeynCalc`DiracChainFactor`Private`x /. 
         DOT -> FeynCalc`DiracChainFactor`Private`holdDOT /. 
        DiracChain -> FeynCalc`DiracChainFactor`Private`factorDirac /. 
       FeynCalc`DiracChainFactor`Private`holdDOT[] -> 1 /. 
      FeynCalc`DiracChainFactor`Private`factorDirac -> DiracChain /. 
     FeynCalc`DiracChainFactor`Private`holdDOT -> DOT
 
FeynCalc`DiracChainFactor`Private`holdDOT[
     FeynCalc`DiracChainFactor`Private`a___, 
     FeynCalc`DiracChainFactor`Private`b_, 
     FeynCalc`DiracChainFactor`Private`c___] := 
    FeynCalc`DiracChainFactor`Private`b*
      FeynCalc`DiracChainFactor`Private`holdDOT[
       FeynCalc`DiracChainFactor`Private`a, 
       FeynCalc`DiracChainFactor`Private`c] /; 
     NonCommFreeQ[FeynCalc`DiracChainFactor`Private`b]
 
FeynCalc`DiracChainFactor`Private`holdDOT[
     FeynCalc`DiracChainFactor`Private`a___, 
     (FeynCalc`DiracChainFactor`Private`b1_)*
      (FeynCalc`DiracChainFactor`Private`b2_), 
     FeynCalc`DiracChainFactor`Private`c___] := 
    FeynCalc`DiracChainFactor`Private`b1*
      FeynCalc`DiracChainFactor`Private`holdDOT[
       FeynCalc`DiracChainFactor`Private`a, 
       FeynCalc`DiracChainFactor`Private`b2, 
       FeynCalc`DiracChainFactor`Private`c] /; 
     NonCommFreeQ[FeynCalc`DiracChainFactor`Private`b1] && 
       !NonCommFreeQ[FeynCalc`DiracChainFactor`Private`b2]
 
FeynCalc`DiracChainFactor`Private`factorDirac[
     FeynCalc`DiracChainFactor`Private`a_, 
     FeynCalc`DiracChainFactor`Private`i_, 
     FeynCalc`DiracChainFactor`Private`j_] := 
    FeynCalc`DiracChainFactor`Private`a*DiracChain[1, 
       FeynCalc`DiracChainFactor`Private`i, 
       FeynCalc`DiracChainFactor`Private`j] /; 
     NonCommFreeQ[FeynCalc`DiracChainFactor`Private`a]
 
FeynCalc`DiracChainFactor`Private`factorDirac[
     (FeynCalc`DiracChainFactor`Private`b_.)*
      (FeynCalc`DiracChainFactor`Private`a_DiracTrace), 
     FeynCalc`DiracChainFactor`Private`i_, 
     FeynCalc`DiracChainFactor`Private`j_] := 
    FeynCalc`DiracChainFactor`Private`a*
     FeynCalc`DiracChainFactor`Private`factorDirac[
      FeynCalc`DiracChainFactor`Private`b, 
      FeynCalc`DiracChainFactor`Private`i, 
      FeynCalc`DiracChainFactor`Private`j]
 
FeynCalc`DiracChainFactor`Private`factorDirac[
     (FeynCalc`DiracChainFactor`Private`a_)*
      (FeynCalc`DiracChainFactor`Private`b_), 
     FeynCalc`DiracChainFactor`Private`i_, 
     FeynCalc`DiracChainFactor`Private`j_] := 
    FeynCalc`DiracChainFactor`Private`a*
      FeynCalc`DiracChainFactor`Private`factorDirac[
       FeynCalc`DiracChainFactor`Private`b, 
       FeynCalc`DiracChainFactor`Private`i, 
       FeynCalc`DiracChainFactor`Private`j] /; 
     NonCommFreeQ[FeynCalc`DiracChainFactor`Private`a] && 
       !NonCommFreeQ[FeynCalc`DiracChainFactor`Private`b]
 
PauliChainExpand[(FeynCalc`PauliChainExpand`Private`a_) == 
      (FeynCalc`PauliChainExpand`Private`b_), 
     FeynCalc`PauliChainExpand`Private`opts:OptionsPattern[]] := 
    PauliChainExpand[FeynCalc`PauliChainExpand`Private`a, 
      FeynCalc`PauliChainExpand`Private`opts] == PauliChainExpand[
      FeynCalc`PauliChainExpand`Private`b, 
      FeynCalc`PauliChainExpand`Private`opts]
 
PauliChainExpand[FeynCalc`PauliChainExpand`Private`expr_List, 
     FeynCalc`PauliChainExpand`Private`opts:OptionsPattern[]] := 
    (PauliChainExpand[#1, FeynCalc`PauliChainExpand`Private`opts] & ) /@ 
     FeynCalc`PauliChainExpand`Private`expr
 
PauliChainExpand[FeynCalc`PauliChainExpand`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`PauliChainExpand`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`PauliChainExpand`Private`ex, 
      FeynCalc`PauliChainExpand`Private`null1, 
      FeynCalc`PauliChainExpand`Private`null2, 
      FeynCalc`PauliChainExpand`Private`uniqList, 
      FeynCalc`PauliChainExpand`Private`solsList, 
      FeynCalc`PauliChainExpand`Private`repRule, 
      FeynCalc`PauliChainExpand`Private`ruleDelayed, 
      FeynCalc`PauliChainExpand`Private`res, 
      FeynCalc`PauliChainExpand`Private`rhs}, 
     FeynCalc`PauliChainExpand`Private`momList = OptionValue[Momentum]; 
      FeynCalc`PauliChainExpand`Private`optDotSimplify = 
       OptionValue[DotSimplify]; 
      FeynCalc`PauliChainExpand`Private`optPauliSigmaExpand = 
       OptionValue[PauliSigmaExpand]; If[ !OptionValue[FCI], 
       FeynCalc`PauliChainExpand`Private`ex = 
        FCI[FeynCalc`PauliChainExpand`Private`expr], 
       FeynCalc`PauliChainExpand`Private`ex = 
        FeynCalc`PauliChainExpand`Private`expr]; 
      If[FreeQ[FeynCalc`PauliChainExpand`Private`ex, PauliChain], 
       Return[FeynCalc`PauliChainExpand`Private`ex]]; 
      FeynCalc`PauliChainExpand`Private`uniqList = 
       Sort[DeleteDuplicates[Cases[FeynCalc`PauliChainExpand`Private`ex + 
           FeynCalc`PauliChainExpand`Private`null1 + 
           FeynCalc`PauliChainExpand`Private`null2, PauliChain[__], 
          Infinity]]]; If[FeynCalc`PauliChainExpand`Private`momList =!= 
         All && Head[FeynCalc`PauliChainExpand`Private`momList] === List, 
       FeynCalc`PauliChainExpand`Private`uniqList = 
        Select[FeynCalc`PauliChainExpand`Private`uniqList, 
          !FreeQ2[#1, FeynCalc`PauliChainExpand`Private`momList] & ]]; 
      FeynCalc`PauliChainExpand`Private`rhs = 
       FeynCalc`PauliChainExpand`Private`uniqList /. PauliChain -> 
          FeynCalc`PauliChainExpand`Private`chLin /. 
        FeynCalc`PauliChainExpand`Private`chLinExp -> PauliChain; 
      If[OptionValue[PauliChainFactor], 
       FeynCalc`PauliChainExpand`Private`rhs = PauliChainFactor[
         FeynCalc`PauliChainExpand`Private`rhs, FCI -> True]]; 
      FeynCalc`PauliChainExpand`Private`repRule = 
       Thread[FeynCalc`PauliChainExpand`Private`ruleDelayed[
          FeynCalc`PauliChainExpand`Private`uniqList, 
          FeynCalc`PauliChainExpand`Private`rhs]] /. 
        FeynCalc`PauliChainExpand`Private`ruleDelayed -> RuleDelayed; 
      If[ !FreeQ2[FeynCalc`PauliChainExpand`Private`repRule, 
         {FeynCalc`PauliChainExpand`Private`chLin, 
          FeynCalc`PauliChainExpand`Private`chLinExp}], 
       Message[PauliChainExpand::fail]; Abort[]]; 
      FeynCalc`PauliChainExpand`Private`res = 
       FeynCalc`PauliChainExpand`Private`ex /. 
        Dispatch[FeynCalc`PauliChainExpand`Private`repRule]; 
      If[OptionValue[FCE], FeynCalc`PauliChainExpand`Private`res = 
        FCE[FeynCalc`PauliChainExpand`Private`res]]; 
      FeynCalc`PauliChainExpand`Private`res]
 
Options[PauliChainExpand] = {PauliChainFactor -> True, 
     PauliSigmaExpand -> True, DotSimplify -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, Momentum -> All}
 
PauliChainExpand /: PauliChainExpand::fail = "Something went wrong while \
expanding Paulih chains with explicit indices.\nEvaluation aborted! "
 
PauliChainExpand /: PauliChainExpand::usage = "PauliChainExpand[exp] expands \
all Pauli chains with explicit indices using\nlinearity, e.g. \
PCHN[CSIS[p1]+CSIS[p2]+m,i,j] \
becomes\nPCHN[CSIS[p1],i,j]+PCHN[CSIS[p2],i,j]+m*PCHN[1,i,j]."
 
FeynCalc`PauliChainExpand`Private`null1 /: 
    FeynCalc`PauliChainExpand`Private`null1::usage = ""
 
FeynCalc`PauliChainExpand`Private`null2 /: 
    FeynCalc`PauliChainExpand`Private`null2::usage = ""
 
FeynCalc`PauliChainExpand`Private`momList /: 
    FeynCalc`PauliChainExpand`Private`momList::usage = ""
 
FeynCalc`PauliChainExpand`Private`optDotSimplify /: 
    FeynCalc`PauliChainExpand`Private`optDotSimplify::usage = ""
 
FeynCalc`PauliChainExpand`Private`optPauliSigmaExpand /: 
    FeynCalc`PauliChainExpand`Private`optPauliSigmaExpand::usage = ""
 
FeynCalc`PauliChainExpand`Private`chLin[
     FeynCalc`PauliChainExpand`Private`xx_, 
     FeynCalc`PauliChainExpand`Private`i_] := 
    FeynCalc`PauliChainExpand`Private`chLinExp[
     FeynCalc`PauliChainExpand`Private`xx, 
     FeynCalc`PauliChainExpand`Private`i]
 
FeynCalc`PauliChainExpand`Private`chLin[
     FeynCalc`PauliChainExpand`Private`xx_, 
     FeynCalc`PauliChainExpand`Private`i:_PauliIndex | _ExplicitPauliIndex | 
       _PauliXi | _PauliEta | _PauliEtaC, FeynCalc`PauliChainExpand`Private`j:
      _PauliIndex | _ExplicitPauliIndex | _PauliXi | _PauliEta | 
       _PauliEtaC] := (FeynCalc`PauliChainExpand`Private`chLinExp[#1, 
       FeynCalc`PauliChainExpand`Private`i, 
       FeynCalc`PauliChainExpand`Private`j] & ) /@ 
     (FeynCalc`PauliChainExpand`Private`expandFu[
       FeynCalc`PauliChainExpand`Private`xx] + 
      FeynCalc`PauliChainExpand`Private`null1 + 
      FeynCalc`PauliChainExpand`Private`null2)
 
FeynCalc`PauliChainExpand`Private`chLin /: 
    FeynCalc`PauliChainExpand`Private`chLin::usage = ""
 
FeynCalc`PauliChainExpand`Private`chLinExp[
     FeynCalc`PauliChainExpand`Private`null1 | 
      FeynCalc`PauliChainExpand`Private`null2, __] := 0
 
FeynCalc`PauliChainExpand`Private`chLinExp /: 
    FeynCalc`PauliChainExpand`Private`chLinExp::usage = ""
 
FeynCalc`PauliChainExpand`Private`expandFu[
     FeynCalc`PauliChainExpand`Private`xx_] := 
    (FeynCalc`PauliChainExpand`Private`tmp = 
      Expand[FeynCalc`PauliChainExpand`Private`xx]; 
     If[FeynCalc`PauliChainExpand`Private`optPauliSigmaExpand, 
      FeynCalc`PauliChainExpand`Private`tmp = PauliSigmaExpand[
         FeynCalc`PauliChainExpand`Private`tmp, FCI -> True, 
         Momentum -> FeynCalc`PauliChainExpand`Private`momList]; ]; 
     If[FeynCalc`PauliChainExpand`Private`optDotSimplify, 
      FeynCalc`PauliChainExpand`Private`tmp = DotSimplify[
         FeynCalc`PauliChainExpand`Private`tmp, FCI -> True]; ]; 
     FeynCalc`PauliChainExpand`Private`tmp)
 
FeynCalc`PauliChainExpand`Private`tmp /: 
    FeynCalc`PauliChainExpand`Private`tmp::usage = ""
 
PauliChainFactor[(FeynCalc`PauliChainFactor`Private`a_) == 
      (FeynCalc`PauliChainFactor`Private`b_), 
     FeynCalc`PauliChainFactor`Private`opts:OptionsPattern[]] := 
    PauliChainFactor[FeynCalc`PauliChainFactor`Private`a, 
      FeynCalc`PauliChainFactor`Private`opts] == PauliChainFactor[
      FeynCalc`PauliChainFactor`Private`b, 
      FeynCalc`PauliChainFactor`Private`opts]
 
PauliChainFactor[FeynCalc`PauliChainFactor`Private`expr_List, 
     FeynCalc`PauliChainFactor`Private`opts:OptionsPattern[]] := 
    (PauliChainFactor[#1, FeynCalc`PauliChainFactor`Private`opts] & ) /@ 
     FeynCalc`PauliChainFactor`Private`expr
 
PauliChainFactor[FeynCalc`PauliChainFactor`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`PauliChainFactor`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`PauliChainFactor`Private`ex, 
      FeynCalc`PauliChainFactor`Private`moms, 
      FeynCalc`PauliChainFactor`Private`res, 
      FeynCalc`PauliChainFactor`Private`PauliChains}, 
     If[OptionValue[FCI], FeynCalc`PauliChainFactor`Private`ex = 
        FeynCalc`PauliChainFactor`Private`expr, 
       FeynCalc`PauliChainFactor`Private`ex = 
        FCI[FeynCalc`PauliChainFactor`Private`expr]]; 
      If[FreeQ[FeynCalc`PauliChainFactor`Private`ex, PauliChain], 
       Return[FeynCalc`PauliChainFactor`Private`ex]]; 
      FeynCalc`PauliChainFactor`Private`PauliChains = 
       Cases2[FeynCalc`PauliChainFactor`Private`ex, PauliChain]; 
      If[FeynCalc`PauliChainFactor`Private`PauliChains =!= {}, 
       FeynCalc`PauliChainFactor`Private`res = 
        FeynCalc`PauliChainFactor`Private`ex /. 
         Dispatch[Thread[FeynCalc`PauliChainFactor`Private`PauliChains -> 
            FeynCalc`PauliChainFactor`Private`chainFactor[
             FeynCalc`PauliChainFactor`Private`PauliChains]]]]; 
      If[OptionValue[FCE], FeynCalc`PauliChainFactor`Private`res = 
        FCE[FeynCalc`PauliChainFactor`Private`res]]; 
      FeynCalc`PauliChainFactor`Private`res]
 
Options[PauliChainFactor] = {FeynCalcInternal -> False, 
     FeynCalcExternal -> False}
 
PauliChainFactor /: PauliChainFactor::usage = "PauliChainFactor[exp] factors \
out all expressions inside a PauliChain to which\nthe chain doesn't apply. \
For example, all objects that are not Pauli matrices\ncan be safely factored \
out from every Pauli chain."
 
FeynCalc`PauliChainFactor`Private`chainFactor[
     FeynCalc`PauliChainFactor`Private`x_] := 
    FeynCalc`PauliChainFactor`Private`x /. 
         DOT -> FeynCalc`PauliChainFactor`Private`holdDOT /. 
        PauliChain -> FeynCalc`PauliChainFactor`Private`factorPauli /. 
       FeynCalc`PauliChainFactor`Private`holdDOT[] -> 1 /. 
      FeynCalc`PauliChainFactor`Private`factorPauli -> PauliChain /. 
     FeynCalc`PauliChainFactor`Private`holdDOT -> DOT
 
FeynCalc`PauliChainFactor`Private`holdDOT[
     FeynCalc`PauliChainFactor`Private`a___, 
     FeynCalc`PauliChainFactor`Private`b_, 
     FeynCalc`PauliChainFactor`Private`c___] := 
    FeynCalc`PauliChainFactor`Private`b*
      FeynCalc`PauliChainFactor`Private`holdDOT[
       FeynCalc`PauliChainFactor`Private`a, 
       FeynCalc`PauliChainFactor`Private`c] /; 
     NonCommFreeQ[FeynCalc`PauliChainFactor`Private`b]
 
FeynCalc`PauliChainFactor`Private`holdDOT[
     FeynCalc`PauliChainFactor`Private`a___, 
     (FeynCalc`PauliChainFactor`Private`b1_)*
      (FeynCalc`PauliChainFactor`Private`b2_), 
     FeynCalc`PauliChainFactor`Private`c___] := 
    FeynCalc`PauliChainFactor`Private`b1*
      FeynCalc`PauliChainFactor`Private`holdDOT[
       FeynCalc`PauliChainFactor`Private`a, 
       FeynCalc`PauliChainFactor`Private`b2, 
       FeynCalc`PauliChainFactor`Private`c] /; 
     NonCommFreeQ[FeynCalc`PauliChainFactor`Private`b1] && 
       !NonCommFreeQ[FeynCalc`PauliChainFactor`Private`b2]
 
FeynCalc`PauliChainFactor`Private`factorPauli[
     FeynCalc`PauliChainFactor`Private`a_, 
     FeynCalc`PauliChainFactor`Private`i_, 
     FeynCalc`PauliChainFactor`Private`j_] := 
    FeynCalc`PauliChainFactor`Private`a*PauliChain[1, 
       FeynCalc`PauliChainFactor`Private`i, 
       FeynCalc`PauliChainFactor`Private`j] /; 
     NonCommFreeQ[FeynCalc`PauliChainFactor`Private`a]
 
FeynCalc`PauliChainFactor`Private`factorPauli[
     (FeynCalc`PauliChainFactor`Private`b_.)*
      (FeynCalc`PauliChainFactor`Private`a_PauliTrace), 
     FeynCalc`PauliChainFactor`Private`i_, 
     FeynCalc`PauliChainFactor`Private`j_] := 
    FeynCalc`PauliChainFactor`Private`a*
     FeynCalc`PauliChainFactor`Private`factorPauli[
      FeynCalc`PauliChainFactor`Private`b, 
      FeynCalc`PauliChainFactor`Private`i, 
      FeynCalc`PauliChainFactor`Private`j]
 
FeynCalc`PauliChainFactor`Private`factorPauli[
     (FeynCalc`PauliChainFactor`Private`a_)*
      (FeynCalc`PauliChainFactor`Private`b_), 
     FeynCalc`PauliChainFactor`Private`i_, 
     FeynCalc`PauliChainFactor`Private`j_] := 
    FeynCalc`PauliChainFactor`Private`a*
      FeynCalc`PauliChainFactor`Private`factorPauli[
       FeynCalc`PauliChainFactor`Private`b, 
       FeynCalc`PauliChainFactor`Private`i, 
       FeynCalc`PauliChainFactor`Private`j] /; 
     NonCommFreeQ[FeynCalc`PauliChainFactor`Private`a] && 
       !NonCommFreeQ[FeynCalc`PauliChainFactor`Private`b]
 
FCGetDimensions[FeynCalc`FCGetDimensions`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`FCGetDimensions`Private`ex, 
      FeynCalc`FCGetDimensions`Private`res, 
      FeynCalc`FCGetDimensions`Private`null1, 
      FeynCalc`FCGetDimensions`Private`null2, 
      FeynCalc`FCGetDimensions`Private`head, 
      FeynCalc`FCGetDimensions`Private`optFreeQ}, 
     FeynCalc`FCGetDimensions`Private`optFreeQ = OptionValue[FreeQ]; 
      If[Head[FeynCalc`FCGetDimensions`Private`optFreeQ] =!= List, 
       Message[FCGetDimensions::failmsg, 
         "The value of the FreeQ option must be a list."]; ]; 
      If[ !OptionValue[FCI], FeynCalc`FCGetDimensions`Private`ex = 
        FCI[FeynCalc`FCGetDimensions`Private`expr], 
       FeynCalc`FCGetDimensions`Private`ex = 
        FeynCalc`FCGetDimensions`Private`expr]; 
      If[FeynCalc`FCGetDimensions`Private`optFreeQ =!= {}, 
       FeynCalc`FCGetDimensions`Private`ex = 
         FeynCalc`FCGetDimensions`Private`ex /. Dispatch[
           (#1 -> Unique["fcgd"] & ) /@ 
            FeynCalc`FCGetDimensions`Private`optFreeQ]; 
        If[ !FreeQ2[FeynCalc`FCGetDimensions`Private`ex, 
           FeynCalc`FCGetDimensions`Private`optFreeQ], 
         Message[FCGetDimensions::failmsg, 
           "Failed to mask the specified objects."]; Abort[]]]; 
      FeynCalc`FCGetDimensions`Private`res = 
       Sort[DeleteDuplicates[Cases[FeynCalc`FCGetDimensions`Private`ex + 
           FeynCalc`FCGetDimensions`Private`null1 + 
           FeynCalc`FCGetDimensions`Private`null2, _Momentum | _DiracGamma | 
           _PauliSigma | _LorentzIndex | _ExplicitLorentzIndex | 
           _CartesianIndex | _CartesianMomentum | _TemporalMomentum, 
          Infinity]]]; FeynCalc`FCGetDimensions`Private`res = 
       FeynCalc`FCGetDimensions`Private`res /. 
        (Momentum | TemporalMomentum | DiracGamma | LorentzIndex | 
           ExplicitLorentzIndex)[_, FeynCalc`FCGetDimensions`Private`dim_:
           4] :> FeynCalc`FCGetDimensions`Private`dim; 
      FeynCalc`FCGetDimensions`Private`res = 
       FeynCalc`FCGetDimensions`Private`res /. 
        (CartesianIndex | CartesianMomentum)[_, 
          FeynCalc`FCGetDimensions`Private`dim_:3] :> 
         FeynCalc`FCGetDimensions`Private`head[
          FeynCalc`FCGetDimensions`Private`dim]; 
      FeynCalc`FCGetDimensions`Private`res = 
       FeynCalc`FCGetDimensions`Private`res /. 
        PauliSigma[_, FeynCalc`FCGetDimensions`Private`dim_:3] :> 
         FeynCalc`FCGetDimensions`Private`dim; 
      If[OptionValue[ChangeDimension], FeynCalc`FCGetDimensions`Private`res = 
        FeynCalc`FCGetDimensions`Private`res /. 
         {FeynCalc`FCGetDimensions`Private`head[3] -> 
           FeynCalc`FCGetDimensions`Private`head[4], 
          FeynCalc`FCGetDimensions`Private`head[
            (FeynCalc`FCGetDimensions`Private`s_Symbol) - 1] :> 
           FeynCalc`FCGetDimensions`Private`s}]; 
      FeynCalc`FCGetDimensions`Private`res = 
       Sort[DeleteDuplicates[FeynCalc`FCGetDimensions`Private`res /. 
          FeynCalc`FCGetDimensions`Private`head -> Identity]]; 
      FeynCalc`FCGetDimensions`Private`res]
 
Options[FCGetDimensions] = {ChangeDimension -> False, 
     FeynCalcInternal -> False, FreeQ -> {}, "DiracGamma[5]" -> True}
 
FCGetDimensions /: FCGetDimensions::failmsg = "Error! FCGetDimensions has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCGetDimensions /: FCGetDimensions::usage = "FCGetDimensions[expr] is an \
auxiliary function that determines the dimensions\nin which 4-momenta and \
Dirac matrices of the given expression are defined. The\nresult is returned \
as a list, e.g. {4}, {D} or {4,D,D-4} etc.\n\nThis is useful if one wants to \
be sure that all quantities inside a particular\nexpression are purely \
$4$-dimensional or purely $D$-dimensional."
 
ChangeDimension[FeynCalc`ChangeDimension`Private`ex_, 
     FeynCalc`ChangeDimension`Private`dim_, OptionsPattern[]] := 
    Block[{FeynCalc`ChangeDimension`Private`expr, 
      FeynCalc`ChangeDimension`Private`res, 
      FeynCalc`ChangeDimension`Private`tmp, 
      FeynCalc`ChangeDimension`Private`lorentzDim, 
      FeynCalc`ChangeDimension`Private`cartesianDim, 
      FeynCalc`ChangeDimension`Private`holdPair, 
      FeynCalc`ChangeDimension`Private`holdDiracChain, 
      FeynCalc`ChangeDimension`Private`holdPauliChain, 
      FeynCalc`ChangeDimension`Private`holdDiracGamma, 
      FeynCalc`ChangeDimension`Private`holdCartesianPair, 
      FeynCalc`ChangeDimension`Private`holdEps, 
      FeynCalc`ChangeDimension`Private`holdPauliSigma}, 
     If[OptionValue[FCI], FeynCalc`ChangeDimension`Private`expr = 
        FeynCalc`ChangeDimension`Private`ex, 
       FeynCalc`ChangeDimension`Private`expr = 
        FCI[FeynCalc`ChangeDimension`Private`ex]]; 
      Switch[Together[FeynCalc`ChangeDimension`Private`dim + 4], _Symbol, 
       FeynCalc`ChangeDimension`Private`lorentzDim = 
         FeynCalc`ChangeDimension`Private`dim; 
        FeynCalc`ChangeDimension`Private`cartesianDim = 
         FeynCalc`ChangeDimension`Private`dim, _, 
       FeynCalc`ChangeDimension`Private`lorentzDim = 
         FeynCalc`ChangeDimension`Private`dim; 
        FeynCalc`ChangeDimension`Private`cartesianDim = 
         FeynCalc`ChangeDimension`Private`dim - 1]; 
      FeynCalc`ChangeDimension`Private`tmp = 
       FeynCalc`ChangeDimension`Private`expr /. DiracChain -> 
               FeynCalc`ChangeDimension`Private`holdDiracChain /. 
             PauliChain -> FeynCalc`ChangeDimension`Private`holdPauliChain /. 
            DiracGamma -> FeynCalc`ChangeDimension`Private`holdDiracGamma /. 
           PauliSigma -> FeynCalc`ChangeDimension`Private`holdPauliSigma /. 
          Pair -> FeynCalc`ChangeDimension`Private`holdPair /. 
         CartesianPair -> 
          FeynCalc`ChangeDimension`Private`holdCartesianPair /. 
        Eps -> FeynCalc`ChangeDimension`Private`holdEps; 
      FeynCalc`ChangeDimension`Private`tmp = 
       FeynCalc`ChangeDimension`Private`tmp /. 
        FeynCalc`ChangeDimension`Private`holdDiracGamma[
          FeynCalc`ChangeDimension`Private`z:5 | 6 | 7] :> 
         DiracGamma[FeynCalc`ChangeDimension`Private`z]; 
      FeynCalc`ChangeDimension`Private`tmp = 
       FeynCalc`ChangeDimension`Private`tmp /. 
        {LorentzIndex[FeynCalc`ChangeDimension`Private`z_, ___] :> 
          LorentzIndex[FeynCalc`ChangeDimension`Private`z, 
           FeynCalc`ChangeDimension`Private`lorentzDim], 
         CartesianIndex[FeynCalc`ChangeDimension`Private`z_, ___] :> 
          CartesianIndex[FeynCalc`ChangeDimension`Private`z, 
           FeynCalc`ChangeDimension`Private`cartesianDim], 
         Momentum[FeynCalc`ChangeDimension`Private`z_, ___] :> 
          Momentum[FeynCalc`ChangeDimension`Private`z, 
           FeynCalc`ChangeDimension`Private`lorentzDim], 
         CartesianMomentum[FeynCalc`ChangeDimension`Private`z_, ___] :> 
          CartesianMomentum[FeynCalc`ChangeDimension`Private`z, 
           FeynCalc`ChangeDimension`Private`cartesianDim]}; 
      FeynCalc`ChangeDimension`Private`tmp = 
       FeynCalc`ChangeDimension`Private`tmp /. 
        {FeynCalc`ChangeDimension`Private`holdDiracGamma[
           FeynCalc`ChangeDimension`Private`z_, ___] :> 
          FeynCalc`ChangeDimension`Private`holdDiracGamma[
           FeynCalc`ChangeDimension`Private`z, 
           FeynCalc`ChangeDimension`Private`lorentzDim], 
         FeynCalc`ChangeDimension`Private`holdPauliSigma[
           FeynCalc`ChangeDimension`Private`z_, ___] :> 
          FeynCalc`ChangeDimension`Private`holdPauliSigma[
           FeynCalc`ChangeDimension`Private`z, 
           FeynCalc`ChangeDimension`Private`cartesianDim]}; 
      FeynCalc`ChangeDimension`Private`res = 
       FeynCalc`ChangeDimension`Private`tmp /. 
              FeynCalc`ChangeDimension`Private`holdDiracGamma -> 
               DiracGamma /. 
             FeynCalc`ChangeDimension`Private`holdPauliSigma -> PauliSigma /. 
            FeynCalc`ChangeDimension`Private`holdPair -> Pair /. 
           FeynCalc`ChangeDimension`Private`holdCartesianPair -> 
            CartesianPair /. FeynCalc`ChangeDimension`Private`holdEps -> 
           Eps /. FeynCalc`ChangeDimension`Private`holdDiracChain -> 
          DiracChain /. FeynCalc`ChangeDimension`Private`holdPauliChain -> 
         PauliChain; If[OptionValue[FCE], 
       FeynCalc`ChangeDimension`Private`res = 
        FCE[FeynCalc`ChangeDimension`Private`res]]; 
      FeynCalc`ChangeDimension`Private`res]
 
Options[ChangeDimension] = {FeynCalcInternal -> False, 
     FeynCalcExternal -> False}
 
ChangeDimension /: ChangeDimension::failmsg = "Error! ChangeDimension has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
ChangeDimension /: ChangeDimension::usage = "ChangeDimension[exp, dim] \
changes all LorentzIndex and Momentum symbols in exp\nto dimension dim (and \
also Levi-Civita-tensors, Dirac slashes and Dirac\nmatrices).\n\nNotice that \
the dimension of CartesianIndex and CartesianMomentum objects will\nbe \
changed to dim-1, not dim."
 
FCLoopIsolate[(FeynCalc`FCLoopIsolate`Private`a_) == 
      (FeynCalc`FCLoopIsolate`Private`b_), 
     FeynCalc`FCLoopIsolate`Private`y__] := 
    FCLoopIsolate[FeynCalc`FCLoopIsolate`Private`a, 
      FeynCalc`FCLoopIsolate`Private`y] == FCLoopIsolate[
      FeynCalc`FCLoopIsolate`Private`b, FeynCalc`FCLoopIsolate`Private`y]
 
FCLoopIsolate[(FeynCalc`FCLoopIsolate`Private`h:Rule | RuleDelayed)[
      FeynCalc`FCLoopIsolate`Private`a_, FeynCalc`FCLoopIsolate`Private`b_], 
     FeynCalc`FCLoopIsolate`Private`y__] := 
    With[{FeynCalc`FCLoopIsolate`Private`zz1 = FCLoopIsolate[
        FeynCalc`FCLoopIsolate`Private`a, FeynCalc`FCLoopIsolate`Private`y], 
      FeynCalc`FCLoopIsolate`Private`zz2 = FCLoopIsolate[
        FeynCalc`FCLoopIsolate`Private`b, FeynCalc`FCLoopIsolate`Private`y]}, 
     FeynCalc`FCLoopIsolate`Private`h[FeynCalc`FCLoopIsolate`Private`zz1, 
      FeynCalc`FCLoopIsolate`Private`zz2]]
 
FCLoopIsolate[FeynCalc`FCLoopIsolate`Private`x_List, 
     FeynCalc`FCLoopIsolate`Private`lmoms0_List /; 
      FreeQ[FeynCalc`FCLoopIsolate`Private`lmoms0, OptionQ], 
     FeynCalc`FCLoopIsolate`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopIsolate`Private`res, 
      FeynCalc`FCLoopIsolate`Private`time, 
      FeynCalc`FCLoopIsolate`Private`fcliVerbose}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopIsolate`Private`fcliVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopIsolate`Private`fcliVerbose = OptionValue[
           FCVerbose]]; ]; FeynCalc`FCLoopIsolate`Private`time = 
       AbsoluteTime[]; If[$ParallelizeFeynCalc && OptionValue[FCParallelize], 
       FCPrint[1, 
         "FCLoopIsolate: Applying FCLoopIsolate to a list in parallel.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        If[OptionValue[Isolate], Message[FCLoopIsolate::failmsg, "FCLoopIsola\
te cannot be parallelized when using the option IsolateNames."]; Abort[]]; 
        With[{FeynCalc`FCLoopIsolate`Private`xxx = 
           FeynCalc`FCLoopIsolate`Private`lmoms0, 
          FeynCalc`FCLoopIsolate`Private`ooo = 
           {FeynCalc`FCLoopIsolate`Private`opts}}, ParallelEvaluate[
          FCParallelContext`FCLoopIsolate`lmoms = 
            FeynCalc`FCLoopIsolate`Private`xxx; 
           FCParallelContext`FCLoopIsolate`pOpts = FilterRules[
             FeynCalc`FCLoopIsolate`Private`ooo, Except[FCParallelize | 
               FCVerbose]]; , DistributedContexts -> None]]; 
        FeynCalc`FCLoopIsolate`Private`res = ParallelMap[
          FCLoopIsolate[#1, FCParallelContext`FCLoopIsolate`lmoms, 
            FCParallelContext`FCLoopIsolate`pOpts, FCParallelize -> 
             False] & , FeynCalc`FCLoopIsolate`Private`x, 
          DistributedContexts -> None, Method -> "ItemsPerEvaluation" -> 
            Ceiling[N[Length[FeynCalc`FCLoopIsolate`Private`x]/$KernelCount]/
              10]], FCPrint[1, 
         "FCLoopIsolate: Applying FCLoopIsolate to a list.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         (FCLoopIsolate[#1, FeynCalc`FCLoopIsolate`Private`lmoms0, 
            FilterRules[{FeynCalc`FCLoopIsolate`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & ) /@ 
          FeynCalc`FCLoopIsolate`Private`x]; 
      FCPrint[1, "FCLoopIsolate: Function done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      FeynCalc`FCLoopIsolate`Private`res]
 
FCLoopIsolate[FeynCalc`FCLoopIsolate`Private`expr_ /; 
      Head[FeynCalc`FCLoopIsolate`Private`expr] =!= List, 
     FeynCalc`FCLoopIsolate`Private`lmoms0_List /; 
      FreeQ[FeynCalc`FCLoopIsolate`Private`lmoms0, OptionQ], 
     OptionsPattern[]] := Block[{FeynCalc`FCLoopIsolate`Private`res, 
      FeynCalc`FCLoopIsolate`Private`null1, 
      FeynCalc`FCLoopIsolate`Private`null2, 
      FeynCalc`FCLoopIsolate`Private`ex, 
      FeynCalc`FCLoopIsolate`Private`lmoms, 
      FeynCalc`FCLoopIsolate`Private`tmp, 
      FeynCalc`FCLoopIsolate`Private`loopIntHeads, 
      FeynCalc`FCLoopIsolate`Private`time, 
      FeynCalc`FCLoopIsolate`Private`optExceptHeads, 
      FeynCalc`FCLoopIsolate`Private`optHead, 
      FeynCalc`FCLoopIsolate`Private`dummy1, 
      FeynCalc`FCLoopIsolate`Private`dummy2, 
      FeynCalc`FCLoopIsolate`Private`fcliVerbose}, 
     FeynCalc`FCLoopIsolate`Private`loopIntHeads = 
       OptionValue[PaVeIntegralHeads]; 
      FeynCalc`FCLoopIsolate`Private`optExceptHeads = 
       OptionValue[ExceptHeads]; FeynCalc`FCLoopIsolate`Private`optHead = 
       OptionValue[Head]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopIsolate`Private`fcliVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopIsolate`Private`fcliVerbose = OptionValue[
           FCVerbose]]; ]; FCPrint[1, "FCLoopIsolate: Entering.", 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      FCPrint[3, "FCLoopIsolate: Entering with: ", 
       FeynCalc`FCLoopIsolate`Private`expr, FCDoControl -> 
        FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[MatchQ[FeynCalc`FCLoopIsolate`Private`lmoms0, {{___}}], 
       Message[FCLoopIsolate::fail, FeynCalc`FCLoopIsolate`Private`ex]; 
        Abort[]]; If[OptionValue[PaVe], 
       FeynCalc`FCLoopIsolate`Private`lmoms = 
        Join[FeynCalc`FCLoopIsolate`Private`lmoms0, 
         FeynCalc`FCLoopIsolate`Private`loopIntHeads], 
       FeynCalc`FCLoopIsolate`Private`lmoms = 
        FeynCalc`FCLoopIsolate`Private`lmoms0]; 
      FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopIsolate: Applying FCI and ClearHeads.", 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[OptionValue[FCI], FeynCalc`FCLoopIsolate`Private`ex = 
        FeynCalc`FCLoopIsolate`Private`expr /. (#1 -> Identity & ) /@ 
          OptionValue[ClearHeads], FeynCalc`FCLoopIsolate`Private`ex = 
        FCI[FeynCalc`FCLoopIsolate`Private`expr] /. (#1 -> Identity & ) /@ 
          OptionValue[ClearHeads]]; FCPrint[1, 
       "FCLoopIsolate: Done applying FCI and ClearHeads, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[FeynCalc`FCLoopIsolate`Private`lmoms === {}, 
       Return[FeynCalc`FCLoopIsolate`Private`expr]; ]; 
      If[OptionValue[Expanding], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCLoopIsolate: Applying Expand2.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`ex = Expand2[
          FeynCalc`FCLoopIsolate`Private`ex, 
          FeynCalc`FCLoopIsolate`Private`lmoms]; FCPrint[1, 
         "FCLoopIsolate: Done applying Expand2, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[ExpandScalarProduct], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying ExpandScalarProduct.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`tmp = 
         FCSplit[FeynCalc`FCLoopIsolate`Private`ex, 
          FeynCalc`FCLoopIsolate`Private`lmoms, Expanding -> 
           OptionValue[Expanding]]; FeynCalc`FCLoopIsolate`Private`ex = 
         FeynCalc`FCLoopIsolate`Private`tmp[[1]] + ExpandScalarProduct[
           FeynCalc`FCLoopIsolate`Private`tmp[[2]], Momentum -> 
            FeynCalc`FCLoopIsolate`Private`lmoms, Full -> OptionValue[Full]]; 
        FCPrint[1, 
         "FCLoopIsolate: Done applying ExpandScalarProduct, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[DiracGammaExpand] && 
         !FreeQ[FeynCalc`FCLoopIsolate`Private`ex, DiracGamma], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying DiracGammaExpand.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`tmp = 
         FCSplit[FeynCalc`FCLoopIsolate`Private`ex, 
          FeynCalc`FCLoopIsolate`Private`lmoms, Expanding -> 
           OptionValue[Expanding]]; FeynCalc`FCLoopIsolate`Private`ex = 
         FeynCalc`FCLoopIsolate`Private`tmp[[1]] + 
           FeynCalc`FCLoopIsolate`Private`tmp[[2]] /. 
          DiracGamma[FeynCalc`FCLoopIsolate`Private`x_, 
             FeynCalc`FCLoopIsolate`Private`dim_:4] /; 
             !FreeQ2[FeynCalc`FCLoopIsolate`Private`x, 
              FeynCalc`FCLoopIsolate`Private`lmoms] :> DiracGammaExpand[
            DiracGamma[FeynCalc`FCLoopIsolate`Private`x, 
             FeynCalc`FCLoopIsolate`Private`dim]]; 
        FCPrint[1, "FCLoopIsolate: Done applying DiracGammaExpand, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[DotSimplify] && 
         !FreeQ[FeynCalc`FCLoopIsolate`Private`ex, DOT], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying DotSimplify.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`tmp = 
         FCSplit[FeynCalc`FCLoopIsolate`Private`ex, 
          FeynCalc`FCLoopIsolate`Private`lmoms, Expanding -> 
           OptionValue[Expanding]]; FeynCalc`FCLoopIsolate`Private`ex = 
         FeynCalc`FCLoopIsolate`Private`tmp[[1]] + DotSimplify[
           FeynCalc`FCLoopIsolate`Private`tmp[[2]]]; 
        FCPrint[1, "FCLoopIsolate: Done applying DotSimplify, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[Collecting], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCLoopIsolate: Applying Collect2.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        If[TrueQ[OptionValue[Numerator]], FeynCalc`FCLoopIsolate`Private`ex = 
          Collect2[FeynCalc`FCLoopIsolate`Private`ex, 
           FeynCalc`FCLoopIsolate`Private`lmoms, Factoring -> 
            OptionValue[Factoring], TimeConstrained -> OptionValue[
             TimeConstrained]], FeynCalc`FCLoopIsolate`Private`ex = 
          Collect2[FeynCalc`FCLoopIsolate`Private`ex, FeynAmpDenominator, 
           Factoring -> OptionValue[Factoring], TimeConstrained -> 
            OptionValue[TimeConstrained]]]; FCPrint[1, 
         "FCLoopIsolate: Done applying Collect2, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[FeynAmpDenominatorSplit] && 
         !FreeQ[FeynCalc`FCLoopIsolate`Private`ex, FeynAmpDenominator], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying FeynAmpDenominatorSplit.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`ex = FeynAmpDenominatorSplit[
          FeynCalc`FCLoopIsolate`Private`ex, Momentum -> 
           FeynCalc`FCLoopIsolate`Private`lmoms]; 
        FCPrint[1, 
         "FCLoopIsolate: Done applying FeynAmpDenominatorSplit, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, 
       "FCLoopIsolate: Splitting products of loop and non-loop terms.", 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      FeynCalc`FCLoopIsolate`Private`res = 
       (SelectFree[#1, FeynCalc`FCLoopIsolate`Private`lmoms]*
            FeynCalc`FCLoopIsolate`Private`optHead[SelectNotFree[#1, 
              FeynCalc`FCLoopIsolate`Private`lmoms]] & ) /@ 
          (FeynCalc`FCLoopIsolate`Private`ex + 
           FeynCalc`FCLoopIsolate`Private`null1 + 
           FeynCalc`FCLoopIsolate`Private`null2) /. 
         {FeynCalc`FCLoopIsolate`Private`null1 | 
            FeynCalc`FCLoopIsolate`Private`null2 -> 0} /. 
        FeynCalc`FCLoopIsolate`Private`optHead[1] -> 1; 
      FCPrint[1, "FCLoopIsolate: Done splitting products of loop and non-loop \
terms, timing: ", N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[FeynCalc`FCLoopIsolate`Private`optExceptHeads =!= {}, 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying the option ExceptHeads.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          {FeynCalc`FCLoopIsolate`Private`optHead[
              FeynCalc`FCLoopIsolate`Private`x_] /; 
              !FreeQ2[FeynCalc`FCLoopIsolate`Private`x, 
               FeynCalc`FCLoopIsolate`Private`optExceptHeads] :> 
            FeynCalc`FCLoopIsolate`Private`x}; FCPrint[1, 
         "FCLoopIsolate: Done applying the option ExceptHeads, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopIsolate: Checking the intermediate result.", 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[Together[(FeynCalc`FCLoopIsolate`Private`res /. 
           FeynCalc`FCLoopIsolate`Private`optHead -> Identity) - 
          FeynCalc`FCLoopIsolate`Private`ex] =!= 0, 
       Message[FCLoopIsolate::fail, FeynCalc`FCLoopIsolate`Private`ex]; 
        Abort[]]; FCPrint[1, 
       "FCLoopIsolate: Done checking the intermediate result, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[OptionValue[DropScaleless], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCLoopIsolate: Removing scaleless integrals.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
            FreeQ2[FeynCalc`FCLoopIsolate`Private`z, 
             Join[{FeynAmpDenominator}, 
              FeynCalc`FCLoopIsolate`Private`loopIntHeads]] :> 0; 
        FCPrint[1, 
         "FCLoopIsolate: Done removing scaleless integrals, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; ]; 
      If[OptionValue[Isolate], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCLoopIsolate: Applying Isolate.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         Isolate[FeynCalc`FCLoopIsolate`Private`res, 
           FeynCalc`FCLoopIsolate`Private`optHead, IsolateNames -> 
            OptionValue[IsolateNames]] /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
            FeynCalc`FCLoopIsolate`Private`x_] :> 
           FeynCalc`FCLoopIsolate`Private`optHead[
            FRH[FeynCalc`FCLoopIsolate`Private`x]]; 
        FCPrint[1, "FCLoopIsolate: Done applying isolate, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; ]; 
      FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopIsolate: Checking the intermediate result.", 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[ !FreeQ[FeynCalc`FCLoopIsolate`Private`res /. 
           FeynCalc`FCLoopIsolate`Private`optHead[__] :> 1, 
          FeynCalc`FCLoopIsolate`Private`lmoms] & , 
       Message[FCLoopIsolate::fail, FeynCalc`FCLoopIsolate`Private`ex]; 
        Abort[]]; FCPrint[1, 
       "FCLoopIsolate: Done checking the intermediate result, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      If[ !OptionValue[Numerator], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCLoopIsolate: Applying the option Numerator.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
           FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z_] :> 
            FeynCalc`FCLoopIsolate`Private`optHead[SelectNotFree[
               FeynCalc`FCLoopIsolate`Private`z*
                FeynCalc`FCLoopIsolate`Private`dummy1*
                FeynCalc`FCLoopIsolate`Private`dummy2, FeynAmpDenominator]]*
             SelectFree[FeynCalc`FCLoopIsolate`Private`z*
               FeynCalc`FCLoopIsolate`Private`dummy1*
               FeynCalc`FCLoopIsolate`Private`dummy2, FeynAmpDenominator] /. 
          FeynCalc`FCLoopIsolate`Private`dummy1 | 
            FeynCalc`FCLoopIsolate`Private`dummy2 -> 1; 
        FCPrint[1, 
         "FCLoopIsolate: Done applying the option Numerator, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[MultiLoop], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCLoopIsolate: Applying the option MultiLoop.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
             !FeynCalc`FCLoopIsolate`Private`fullDep[
              FeynCalc`FCLoopIsolate`Private`z, 
              FeynCalc`FCLoopIsolate`Private`lmoms0] :> 
           FeynCalc`FCLoopIsolate`Private`z; FCPrint[1, 
         "FCLoopIsolate: Done applying the option MultiLoop, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[ !OptionValue[SFAD] &&  !FreeQ[FeynCalc`FCLoopIsolate`Private`res, 
          StandardPropagatorDenominator], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying the option SFAD.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
             !FreeQ[{FeynCalc`FCLoopIsolate`Private`z}, 
              StandardPropagatorDenominator] :> 
           FeynCalc`FCLoopIsolate`Private`z; FCPrint[1, 
         "FCLoopIsolate: Done applying the option SFAD, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[ !OptionValue[CFAD] &&  !FreeQ[FeynCalc`FCLoopIsolate`Private`res, 
          CartesianPropagatorDenominator], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying the option CFAD.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
             !FreeQ[{FeynCalc`FCLoopIsolate`Private`z}, 
              CartesianPropagatorDenominator] :> 
           FeynCalc`FCLoopIsolate`Private`z; FCPrint[1, 
         "FCLoopIsolate: Done applying the option CFAD, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[ !OptionValue[GFAD] &&  !FreeQ[FeynCalc`FCLoopIsolate`Private`res, 
          GenericPropagatorDenominator], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying the option GFAD.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
             !FreeQ[{FeynCalc`FCLoopIsolate`Private`z}, 
              GenericPropagatorDenominator] :> 
           FeynCalc`FCLoopIsolate`Private`z; FCPrint[1, 
         "FCLoopIsolate: Done applying the option GFAD, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[ !OptionValue[FAD] &&  !FreeQ[FeynCalc`FCLoopIsolate`Private`res, 
          PropagatorDenominator], FeynCalc`FCLoopIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCLoopIsolate: Applying the option FAD.", FCDoControl -> 
          FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
             !FreeQ[{FeynCalc`FCLoopIsolate`Private`z}, 
              PropagatorDenominator] :> FeynCalc`FCLoopIsolate`Private`z; 
        FCPrint[1, "FCLoopIsolate: Done applying the option FAD, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[FCLoopIBPReducableQ], 
       FeynCalc`FCLoopIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopIsolate: Applying the option FCLoopIBPReducableQ.", 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
        FeynCalc`FCLoopIsolate`Private`res = 
         FeynCalc`FCLoopIsolate`Private`res /. 
          FeynCalc`FCLoopIsolate`Private`optHead[
             FeynCalc`FCLoopIsolate`Private`z__] /; 
             !FCLoopIBPReducableQ[FeynCalc`FCLoopIsolate`Private`z] :> 
           FeynCalc`FCLoopIsolate`Private`z; FCPrint[1, "FCLoopIsolate: Done \
applying the option FCLoopIBPReducableQ, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopIsolate`Private`fcliVerbose]]; 
      If[OptionValue[FCE], FeynCalc`FCLoopIsolate`Private`res = 
        FCE[FeynCalc`FCLoopIsolate`Private`res]]; 
      FCPrint[1, "FCLoopIsolate: Leaving.", FCDoControl -> 
        FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      FCPrint[3, "FCLoopIsolate: Leaving with: ", 
       FeynCalc`FCLoopIsolate`Private`res, FCDoControl -> 
        FeynCalc`FCLoopIsolate`Private`fcliVerbose]; 
      FeynCalc`FCLoopIsolate`Private`res]
 
Options[FCLoopIsolate] = {CFAD -> True, ClearHeads -> {FCGV["LoopInt"]}, 
     Collecting -> True, DiracGammaExpand -> True, DotSimplify -> True, 
     DropScaleless -> False, ExceptHeads -> {}, ExpandScalarProduct -> False, 
     Expanding -> True, FAD -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCLoopIBPReducableQ -> False, 
     FCParallelize -> False, FCVerbose -> False, 
     Factoring -> {Factor2, 5000}, FeynAmpDenominatorSplit -> True, 
     Full -> True, GFAD -> True, Head -> FCGV["LoopInt"], Isolate -> False, 
     IsolateNames -> KK, MultiLoop -> False, Numerator -> True, PaVe -> True, 
     PaVeIntegralHeads -> FeynCalc`Package`PaVeHeadsList, SFAD -> True, 
     TimeConstrained -> 3}
 
FCLoopIsolate /: FCLoopIsolate::fail = 
     "FCLoopIsolate failed to isolate loop integrals in `1`!"
 
FCLoopIsolate /: FCLoopIsolate::usage = "FCLoopIsolate[expr, {q1, q2, ...}] \
wraps loop integrals into heads specified\nby the user. This is useful when \
you want to know which loop integrals appear\nin the given expression."
 
FeynCalc`FCLoopIsolate`Private`fcliVerbose /: 
    FeynCalc`FCLoopIsolate`Private`fcliVerbose::usage = ""
 
PaVeIntegralHeads /: PaVeIntegralHeads::usage = "PaVeIntegralHeads is an \
option for FCLoopIsolate, FCLoopSplit and other\nfunctions. It gives a list \
of heads that denote Passarino-Veltman integrals"
 
FeynAmpDenominatorSplit[FeynCalc`FeynAmpDenominatorSplit`Private`expr_, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FeynAmpDenominatorSplit`Private`res, 
      FeynCalc`FeynAmpDenominatorSplit`Private`momList, 
      FeynCalc`FeynAmpDenominatorSplit`Private`fad, 
      FeynCalc`FeynAmpDenominatorSplit`Private`head, 
      FeynCalc`FeynAmpDenominatorSplit`Private`allFads, 
      FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval, 
      FeynCalc`FeynAmpDenominatorSplit`Private`repRule, 
      FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose = 
          OptionValue[FCVerbose]]; ]; If[ !OptionValue[FCI], 
       FeynCalc`FeynAmpDenominatorSplit`Private`res = 
        FCI[FeynCalc`FeynAmpDenominatorSplit`Private`expr], 
       FeynCalc`FeynAmpDenominatorSplit`Private`res = 
        FeynCalc`FeynAmpDenominatorSplit`Private`expr]; 
      FCPrint[1, "FeynAmpDenominatorSplit: Entering.", 
       FCDoControl -> FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; 
      FCPrint[3, "FeynAmpDenominatorSplit Entering with: ", 
       FeynCalc`FeynAmpDenominatorSplit`Private`res, 
       FCDoControl -> FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; 
      If[TrueQ[OptionValue[List]], 
       FeynCalc`FeynAmpDenominatorSplit`Private`head = List, 
       FeynCalc`FeynAmpDenominatorSplit`Private`head = Times]; 
      FeynCalc`FeynAmpDenominatorSplit`Private`momList = 
       OptionValue[Momentum]; 
      FeynCalc`FeynAmpDenominatorSplit`Private`allFads = 
       Cases2[FeynCalc`FeynAmpDenominatorSplit`Private`res, 
        FeynAmpDenominator]; 
      FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval = 
       FeynCalc`FeynAmpDenominatorSplit`Private`allFads; 
      FCPrint[1, "FeynAmpDenominatorSplit: Relevant denominators: ", 
       FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval, 
       FCDoControl -> FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; 
      If[OptionValue[MomentumExpand], 
       FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval = 
         MomentumExpand[
          FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval]; 
        FCPrint[1, "FeynAmpDenominatorSplit: After MomentumExpand: ", 
         FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval, 
         FCDoControl -> 
          FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; ]; 
      If[FeynCalc`FeynAmpDenominatorSplit`Private`momList =!= All && 
        Head[FeynCalc`FeynAmpDenominatorSplit`Private`momList] === List, 
       FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval = 
        FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval /. 
           FeynAmpDenominator[
             FeynCalc`FeynAmpDenominatorSplit`Private`props__] :> 
            FeynCalc`FeynAmpDenominatorSplit`Private`head[
             FeynCalc`FeynAmpDenominatorSplit`Private`fad[SelectFree[{
                FeynCalc`FeynAmpDenominatorSplit`Private`props}, Sequence @@ 
                FeynCalc`FeynAmpDenominatorSplit`Private`momList]], 
             FeynCalc`FeynAmpDenominatorSplit`Private`fad[SelectNotFree[{
                FeynCalc`FeynAmpDenominatorSplit`Private`props}, Sequence @@ 
                FeynCalc`FeynAmpDenominatorSplit`Private`momList]]] /. 
          FeynCalc`FeynAmpDenominatorSplit`Private`fad[{}] :> 1 /. 
         FeynCalc`FeynAmpDenominatorSplit`Private`fad[
           {FeynCalc`FeynAmpDenominatorSplit`Private`pr__}] :> 
          FeynAmpDenominator[FeynCalc`FeynAmpDenominatorSplit`Private`pr], 
       FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval = 
        FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval /. 
         FeynAmpDenominator[FeynCalc`FeynAmpDenominatorSplit`Private`a__] :> 
          FeynCalc`FeynAmpDenominatorSplit`Private`head @@ 
           FeynAmpDenominator /@ 
            {FeynCalc`FeynAmpDenominatorSplit`Private`a}]; 
      FCPrint[1, "FeynAmpDenominatorSplit: After splitting: ", 
       FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval, 
       FCDoControl -> FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; 
      FeynCalc`FeynAmpDenominatorSplit`Private`repRule = 
       Thread[FeynCalc`FeynAmpDenominatorSplit`Private`allFads -> 
         FeynCalc`FeynAmpDenominatorSplit`Private`allFadsEval]; 
      FeynCalc`FeynAmpDenominatorSplit`Private`res = 
       FeynCalc`FeynAmpDenominatorSplit`Private`res /. 
        Dispatch[FeynCalc`FeynAmpDenominatorSplit`Private`repRule]; 
      If[OptionValue[FCE], FeynCalc`FeynAmpDenominatorSplit`Private`res = 
        FCE[FeynCalc`FeynAmpDenominatorSplit`Private`res]]; 
      FCPrint[1, "FeynAmpDenominatorSplit: Leaving.", 
       FCDoControl -> FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; 
      FCPrint[3, "FFeynAmpDenominatorSplit Leaving with: ", 
       FeynCalc`FeynAmpDenominatorSplit`Private`res, 
       FCDoControl -> FeynCalc`FeynAmpDenominatorSplit`Private`optVerbose]; 
      FeynCalc`FeynAmpDenominatorSplit`Private`res]
 
Options[FeynAmpDenominatorSplit] = {FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCVerbose -> False, List -> False, 
     Momentum -> All, MomentumExpand -> True}
 
FeynAmpDenominatorSplit /: FeynAmpDenominatorSplit::usage = "FeynAmpDenominat\
orSplit[expr] splits all FeynAmpDenominator[a,b, ...] in expr\ninto \
FeynAmpDenominator[a]*FeynAmpDenominator[b]*... \
.\nFeynAmpDenominatorSplit[expr,  Momentum ->q1] splits all \
FeynAmpDenominator in\nexpr into two products, one containing q1 and other \
momenta, the second being\nfree of q1."
 
DropScaleless /: DropScaleless::usage = "DropScaleless is an option for \
FCLoopIsolate, ApartFF, FourDivergence and\nother functions. When set to \
True, all loop integrals that do not contain a\nFeynAmpDenominator, i.e. \
consist of only scalar products but no denominators,\nare set to zero."
 
FRH[FeynCalc`SharedTools`Private`x_, OptionsPattern[]] := 
    FixedPoint[ReleaseHold, FeynCalc`SharedTools`Private`x] /; 
     OptionValue[IsolateNames] === All
 
FRH[FeynCalc`SharedTools`Private`x_, OptionsPattern[]] := 
    FixedPoint[FeynCalc`SharedTools`Private`x //. 
        HoldForm[(FeynCalc`SharedTools`Private`y_)[
            FeynCalc`SharedTools`Private`z___]] /; 
           !FreeQ2[HoldForm[FeynCalc`SharedTools`Private`y], 
            Flatten[{OptionValue[IsolateNames]}]] :> 
         FeynCalc`SharedTools`Private`y[FeynCalc`SharedTools`Private`z] & , 
      FeynCalc`SharedTools`Private`x] /; OptionValue[IsolateNames] =!= All
 
Options[FRH] = {IsolateNames -> All}
 
FRH /: FRH::usage = "FRH[exp_] corresponds to FixedPoint[ReleaseHold, exp],  \
i.e. FRH removes all\nHoldForm and Hold in exp.\n\nNotice that FRH will not \
be able to reinsert abbreviations if they were\nintroduced by Collect2 \
running in parallel mode. For that you need to use FRH2"
 
MultiLoop /: MultiLoop::usage = "MultiLoop is an option for FCLoopIsolate. \
When set to True, FCLoopIsolate will\nisolate only such loop integrals, that \
depend on all of the given loop\nmomenta. Integrals that depend only on some \
of the loop momenta will be\ntreated as non-loop terms and remain \
non-isolated."
 
FeynCalc`FCLoopIsolate`Private`fullDep[FeynCalc`FCLoopIsolate`Private`z_, 
     FeynCalc`FCLoopIsolate`Private`lmoms_] := 
    Union[Cases[ExpandScalarProduct[FeynCalc`FCLoopIsolate`Private`z, 
        FCI -> True], (CartesianMomentum | Momentum)[
          FeynCalc`FCLoopIsolate`Private`x_, ___] /; 
          !FreeQ2[FeynCalc`FCLoopIsolate`Private`x, 
           FeynCalc`FCLoopIsolate`Private`lmoms] :> 
        FeynCalc`FCLoopIsolate`Private`x, Infinity]] === 
     Sort[FeynCalc`FCLoopIsolate`Private`lmoms]
 
Options[SFAD] = {Dimension -> D, EtaSign -> 1}
 
SFAD /: SFAD::usage = "SFAD[{{q1 +..., p1 . q2 +...,} {m^2, s}, n}, ...] \
denotes a standard\nLorentzian  propagator given by \
$\\frac{1}{[(q_1+\\ldots)^2 + p_1 \\cdot q_2 ...\n+ m^2 + s i \\eta]^n}$, \
where $q_1^2$ and $p_1 \\cdot q_2$ are Lorentzian scalar\nproducts in $D$ \
dimensions.\n\nFor brevity one can also use shorter forms such as SFAD[{q1+ \
...,  m^2}, ...],\nSFAD[{q1+ ...,  m^2 , n}, ...], SFAD[{q1+ ...,  {m^2, \
-1}}, ...], SFAD[q1,...]\netc.\n\nIf s is not explicitly specified, its value \
is determined by the option\nEtaSign, which has the default value +1 and \
corresponds to $+ i \\eta$\n\nIf n is not explicitly specified, then the \
default value 1 is assumed.\nTranslation into the FeynCalc internal form is \
performed by FeynCalcInternal,\nwhere an SFAD is encoded using the special \
head StandardPropagatorDenominator.\n\nSFAD can represent more versatile \
propagators as compared to the old FAD. In\nparticular, FAD does not allow \
one to enter eikonal propagators, track the\nsign of the $i \\eta$ or change \
the sign and the form of the mass term."
 
EtaSign /: EtaSign::usage = "EtaSign is an option for SFAD, GFAD, CFAD and \
other objects representing\npropagators. It specifies the default sign of the \
$i \\eta$ prescription  in\nthe propagators, e.g. for standard Feynman \
propagators the value 1 corresponds\nto $\\frac{1}{p^2-m^2 + i \\eta}$, while \
the value -1 sets $\\frac{1}{p^2-m^2 - i\n\\eta}$."
 
StandardPropagatorDenominator /: StandardPropagatorDenominator::usage = "Stan\
dardPropagatorDenominator[propSq + ..., propEik +..., m^2, {n, s}] encodes\na \
generic Lorentzian propagator denominator $\\frac{1}{[(q_1+ \\ldots)^2 + \
q_1\n\\cdot p_1 + \\ldots + m^2 + s i \\eta]^n}$.\n\npropSq should be of the \
form Momentum[q1, D], while propEik should look like\nPair[Momentum[q1, D], \
Momentum[p1, D].\n\nThis allows to accommodate for standard propagators of \
the type $1/(p^2-m^2)$\nbut also for propagators encountered in manifestly \
Lorentz covariant effective\nfield theories such as HQET or \
SCET.\n\nStandardPropagatorDenominator is an internal object. To enter such \
propagators\nin FeynCalc you should use SFAD."
 
Options[CFAD] = {Dimension -> -1 + D, EtaSign -> -1}
 
CFAD /: CFAD::usage = "CFAD[{{q1 +..., p1 . q2 +...,} {m^2, s}, n}, ...] \
denotes a Cartesian\npropagator given by $\\frac{1}{[(q_1+\\ldots)^2 + p_1 \
\\cdot q_2 ... + m^2 + s i\n\\eta]^n}$, where $q_1^2$ and $p_1 \\cdot q_2$ \
are Cartesian scalar products in\n$D-1$ dimensions.\n\nFor brevity one can \
also use shorter forms such as CFAD[{q1+ ...,  m^2}, ...],\nCFAD[{q1+ ...,  \
m^2 , n}, ...], CFAD[{q1+ ...,  {m^2, -1}}, ...], CFAD[q1,...]\netc.\n\nIf s \
is not explicitly specified, its value is determined by the option\nEtaSign, \
which has the default value -1.\n\nIf n is not explicitly specified, then the \
default value 1 is assumed.\nTranslation into FeynCalcI internal form is \
performed by FeynCalcInternal,\nwhere a CFAD is encoded using the special \
head CartesianPropagatorDenominator."
 
CartesianPropagatorDenominator /: CartesianPropagatorDenominator::usage = "Ca\
rtesianPropagatorDenominator[propSq  + ..., propEik + ..., m^2, {n, \
s}]\nencodes a generic Cartesian propagator denominator of the \
form\n$\\frac{1}{[(q1+...)^2 + q1.p1 + ... + m^2 + s*I \\eta]^n}$\n\npropSq \
should be of the form CartesianMomentum[q1, D - 1], while propEik\nshould \
look like CartesianPair[CartesianMomentum[q1, D - 1],\nCartesianMomentum[p1, \
D - 1].\n\nCartesianPropagatorDenominator is an internal object. To enter \
such\npropagators in FeynCalc you should use CFAD."
 
Options[GFAD] = {EtaSign -> 1}
 
GFAD /: GFAD::usage = "GFAD[{{{x, s}, n}, ...] denotes a generic propagator \
given by $\\frac{1}{[x + s\ni \\eta]^n}$, where x can be an arbitrary \
expression. For brevity one can also\nuse shorter forms such as GFAD[{x, n}, \
...], GFAD[{x}, ...] or GFAD[x, ...].\n\nIf s is not explicitly specified, \
then its value is determined by the option\nEtaSign, which has the default \
value +1.\n\nIf n is not explicitly specified, then the default value 1 is \
assumed.\nTranslation into FeynCalc internal form is performed by \
FeynCalcInternal,\nwhere a GFAD is encoded using the special head \
GenericPropagatorDenominator."
 
GenericPropagatorDenominator /: GenericPropagatorDenominator::usage = "Generi\
cPropagatorDenominator[expr, {n, s}]  is a generic factor of the\ndenominator \
of a propagator. Unlike PropagatorDenominator that is supposed to\nmean \
$1/(q^2-m^2)$, expr in GenericPropagatorDenominator can be an \
arbitrary\ncombination of Pair, CartesianPair and TemporalPair objects."
 
FAD[-(FeynCalc`SharedObjects`Private`p_), FeynCalc`SharedObjects`Private`opts:
      OptionsPattern[]] := FAD[FeynCalc`SharedObjects`Private`p, 
     FeynCalc`SharedObjects`Private`opts]
 
FAD[FeynCalc`SharedObjects`Private`a___, {FeynCalc`SharedObjects`Private`x_, 
      FeynCalc`SharedObjects`Private`y_, 
      (FeynCalc`SharedObjects`Private`n_Integer)?Positive}, 
     FeynCalc`SharedObjects`Private`b:Except[_?OptionQ]..., 
     FeynCalc`SharedObjects`Private`opts:OptionsPattern[]] := 
    FAD[FeynCalc`SharedObjects`Private`a, Sequence @@ 
      Table[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}, {FeynCalc`SharedObjects`Private`i, 
        1, FeynCalc`SharedObjects`Private`n}], 
     FeynCalc`SharedObjects`Private`b, FeynCalc`SharedObjects`Private`opts]
 
FAD[FeynCalc`SharedObjects`Private`a___, {_, _, 0}, 
     FeynCalc`SharedObjects`Private`b:Except[_?OptionQ]..., 
     FeynCalc`SharedObjects`Private`opts:OptionsPattern[]] := 
    FAD[FeynCalc`SharedObjects`Private`a, FeynCalc`SharedObjects`Private`b, 
      FeynCalc`SharedObjects`Private`opts] /; 
     Length[{FeynCalc`SharedObjects`Private`a, 
        FeynCalc`SharedObjects`Private`b}] =!= 0
 
FAD[{_, _, 0}, OptionsPattern[]] := 1
 
Options[FAD] = {Dimension -> D}
 
FAD /: FAD::usage = "FAD is the FeynCalc external form of FeynAmpDenominator \
and denotes an inverse\npropagator.\n\nFAD[q, q-p, ...] is $\\frac{1}{q^2 \
(q-p)^2 \\ldots}$.\n\nFAD[{q1,m}, {q1-p,m}, q2, ...] is $\\frac{1}{[q1^2 - \
m^2][(q1-p)^2 - m^2]\nq2^2}$. Translation into FeynCalc internal form is \
performed by\nFeynCalcInternal."
 
FCLoopIBPReducableQ[(FeynCalc`FCLoopBasis`Private`sps_.)*
      (FeynCalc`FCLoopBasis`Private`fad_FeynAmpDenominator)] := 
    MemSet[FCLoopIBPReducableQ[FeynCalc`FCLoopBasis`Private`sps*
       FeynCalc`FCLoopBasis`Private`fad], 
     Block[{FeynCalc`FCLoopBasis`Private`fadList, 
       FeynCalc`FCLoopBasis`Private`res, 
       FeynCalc`FCLoopBasis`Private`propPowers}, 
      FeynCalc`FCLoopBasis`Private`fadList = 
        Sort[List @@ FeynCalc`FCLoopBasis`Private`fad]; 
       FeynCalc`FCLoopBasis`Private`propPowers = 
        Union[Flatten[{1, Cases[List @@ FeynCalc`FCLoopBasis`Private`fad, 
            (StandardPropagatorDenominator | CartesianPropagatorDenominator | 
               GenericPropagatorDenominator)[__, 
              {FeynCalc`FCLoopBasis`Private`n_, _}] :> 
             FeynCalc`FCLoopBasis`Private`n, Infinity]}]]; 
       FeynCalc`FCLoopBasis`Private`res = 
        FeynCalc`FCLoopBasis`Private`fadList =!= 
          Union[FeynCalc`FCLoopBasis`Private`fadList] || 
         MatchQ[FeynCalc`FCLoopBasis`Private`sps, 
          (_.)*(Pair | CartesianPair)[__]^_] || 
         MatchQ[FeynCalc`FCLoopBasis`Private`propPowers, {1, __}]; 
       FeynCalc`FCLoopBasis`Private`res]]
 
FCLoopIBPReducableQ /: FCLoopIBPReducableQ::failmsg = "ErroFCLoopIBPReducable\
Q has encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCLoopIBPReducableQ /: FCLoopIBPReducableQ::usage = "FCLoopIBPReducableQ[int] \
checks if the integral contains propagators raised to\ninteger powers."
 
FeynCalc`Package`PaVeHeadsList = {PaVe, GenPaVe, A0, A00, B0, B00, B1, B11, 
     DB0, DB1, C0, D0}
 
GenPaVe /: GenPaVe::usage = "GenPaVe[i, j, ..., {{0, m0}, {Momentum[p1], m1}, \
{Momentum[p2], m2}, ...]\ndenotes the invariant (and scalar) \
Passarino-Veltman integrals, i.e. the\ncoefficient functions of the tensor \
integral decomposition. In contrast to\nPaVe which uses the LoopTools \
convention,  masses and external momenta in\nGenPaVe are written in the same \
order as they appear in the original tensor\nintegral, i.e. \
FAD[{q,m0},{q-p1,m1},{q-p2,m2},...]."
 
DB0[FeynCalc`PaVeIntegrals`Private`pe_, FeynCalc`PaVeIntegrals`Private`me2_, 
     FeynCalc`PaVeIntegrals`Private`me1_, FeynCalc`PaVeIntegrals`Private`opt:
      OptionsPattern[]] := 
    DB0 @@ Prepend[{FeynCalc`PaVeIntegrals`Private`me1, 
        FeynCalc`PaVeIntegrals`Private`me2, 
        FeynCalc`PaVeIntegrals`Private`opt}, 
       Expand[FeynCalc`PaVeIntegrals`Private`pe]] /; 
      !OrderedQ[{FeynCalc`PaVeIntegrals`Private`me2, 
        FeynCalc`PaVeIntegrals`Private`me1}]
 
DB0 /: DB0::usage = "DB0[p2, m1^2, m2^2] is the derivative of the two-point \
function B0[p2, m1^2,\nm2^2] with respect to p2."
 
DB1[FeynCalc`PaVeIntegrals`Private`m_, FeynCalc`PaVeIntegrals`Private`m_, 0, 
     OptionsPattern[]] := 
    -DB0[FeynCalc`PaVeIntegrals`Private`m, FeynCalc`PaVeIntegrals`Private`m, 
        0] + 1/2/FeynCalc`PaVeIntegrals`Private`m /; OptionValue[BReduce]
 
HoldPattern[DB1[FeynCalc`PaVeIntegrals`Private`pp:Except[_SmallVariable | 0], 
      FeynCalc`PaVeIntegrals`Private`m02_, 
      FeynCalc`PaVeIntegrals`Private`m12_, OptionsPattern[]]] := 
    (-(FeynCalc`PaVeIntegrals`Private`m12 - 
          FeynCalc`PaVeIntegrals`Private`m02)/
        (2*FeynCalc`PaVeIntegrals`Private`pp^2))*
       (B0[FeynCalc`PaVeIntegrals`Private`pp, 
         FeynCalc`PaVeIntegrals`Private`m02, 
         FeynCalc`PaVeIntegrals`Private`m12] - 
        B0[0, FeynCalc`PaVeIntegrals`Private`m02, 
         FeynCalc`PaVeIntegrals`Private`m12]) + 
      ((FeynCalc`PaVeIntegrals`Private`m12 - 
         FeynCalc`PaVeIntegrals`Private`m02 - 
         FeynCalc`PaVeIntegrals`Private`pp)/
        (2*FeynCalc`PaVeIntegrals`Private`pp))*
       DB0[FeynCalc`PaVeIntegrals`Private`pp, 
        FeynCalc`PaVeIntegrals`Private`m02, 
        FeynCalc`PaVeIntegrals`Private`m12] /; OptionValue[BReduce]
 
Options[DB1] = {BReduce -> True}
 
DB1 /: DB1::usage = "DB1[p2, m1^2, m2^2] is the derivative of \
B1[p2,m1^2,m2^2] with respect to p2."
 
D0 /: MakeBoxes[D0[FeynCalc`PaVeIntegrals`Private`p10_, 
       FeynCalc`PaVeIntegrals`Private`p12_, 
       FeynCalc`PaVeIntegrals`Private`p23_, 
       FeynCalc`PaVeIntegrals`Private`p30_, 
       FeynCalc`PaVeIntegrals`Private`p20_, 
       FeynCalc`PaVeIntegrals`Private`p13_, 
       FeynCalc`PaVeIntegrals`Private`m02_, 
       FeynCalc`PaVeIntegrals`Private`m12_, 
       FeynCalc`PaVeIntegrals`Private`m22_, 
       FeynCalc`PaVeIntegrals`Private`m32_, OptionsPattern[]], 
      TraditionalForm] := ToBoxes[HoldForm[
       PaVe[0, {FeynCalc`PaVeIntegrals`Private`p10, 
         FeynCalc`PaVeIntegrals`Private`p12, 
         FeynCalc`PaVeIntegrals`Private`p23, 
         FeynCalc`PaVeIntegrals`Private`p30, 
         FeynCalc`PaVeIntegrals`Private`p20, 
         FeynCalc`PaVeIntegrals`Private`p13}, 
        {FeynCalc`PaVeIntegrals`Private`m02, 
         FeynCalc`PaVeIntegrals`Private`m12, 
         FeynCalc`PaVeIntegrals`Private`m22, 
         FeynCalc`PaVeIntegrals`Private`m32}]], TraditionalForm]
 
D0 /: D0::usage = "D0[p10, p12, p23, p30, p20, p13, m1^2, m2^2, m3^2, m4^2 ] \
is the\nPassarino-Veltman $D_0$ function. The convention for the arguments is \
that if\nthe denominator of the integrand has the form $([q^2-m1^2] \
[(q+p1)^2-m2^2]\n[(q+p2)^2-m3^2] [(q+p3)^2-m4^2])$, the first six arguments \
of D0 are the\nscalar products $p10 = p1^2$, $p12 = (p1-p2)^2$, $p23 = \
(p2-p3)^2$, $p30 =\np3^2$, $p20 = p2^2$, $p13 = (p1-p3)^2$."
 
FeynCalc`FCCanonicalizeDummyIndices`Private`makeRepIndexList[
     FeynCalc`FCCanonicalizeDummyIndices`Private`mIndexHead_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`mWrappinHead_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`mSeed_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`mFunc_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`mFinalList_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`mUniqueExp_] := 
    Block[{FeynCalc`FCCanonicalizeDummyIndices`Private`indList}, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`indList = 
       DeleteDuplicates /@ 
        (Cases[#1, FeynCalc`FCCanonicalizeDummyIndices`Private`mIndexHead[
             FeynCalc`FCCanonicalizeDummyIndices`Private`y__] /; 
            MemberQ[FeynCalc`FCCanonicalizeDummyIndices`Private`mFinalList, 
             FeynCalc`FCCanonicalizeDummyIndices`Private`mIndexHead[
              FeynCalc`FCCanonicalizeDummyIndices`Private`y]], 
           Infinity] & ) /@ 
         FeynCalc`FCCanonicalizeDummyIndices`Private`mUniqueExp; 
      (Function[FeynCalc`FCCanonicalizeDummyIndices`Private`x, 
          MapIndexed[
           #1 -> FeynCalc`FCCanonicalizeDummyIndices`Private`mIndexHead[
              FeynCalc`FCCanonicalizeDummyIndices`Private`mWrappinHead[
               FeynCalc`FCCanonicalizeDummyIndices`Private`mFunc[#2, 
                FeynCalc`FCCanonicalizeDummyIndices`Private`mSeed]]] & , 
           FeynCalc`FCCanonicalizeDummyIndices`Private`x]][#1] & ) /@ 
       FeynCalc`FCCanonicalizeDummyIndices`Private`indList]
 
LorentzIndexNames /: LorentzIndexNames::usage = "LorentzIndexNames is an \
option for FCFAConvert, FCCanonicalizeDummyIndices and\nother functions. It \
renames the generic dummy Lorentz indices to the indices\nin the supplied \
list."
 
SUNFIndexNames /: SUNFIndexNames::usage = "SUNFIndexNames is an option for \
FCFAConvert, FCCanonicalizeDummyIndices and\nother functions. It renames the \
generic dummy $SU(N)$ indices in the\nfundamental representation to the \
indices in the supplied list."
 
DiracIndexNames /: DiracIndexNames::usage = "DiracIndexNames is an option for \
FCFAConvert, FCCanonicalizeDummyIndices and\nother functions. It renames the \
generic dummy Dirac indices to the indices in\nthe supplied list."
 
PauliIndexNames /: PauliIndexNames::usage = "PauliIndexNames is an option for \
FCFAConvert, FCCanonicalizeDummyIndices and\nother functions. It renames the \
generic dummy Pauli indices to the indices in\nthe supplied list."
 
CustomIndexNames /: CustomIndexNames::usage = "CustomIndexNames is an option \
of FCCanonicalizeDummyIndices. It allows to\nspecify custom names for \
canonicalized dummy indices of custom index heads."
 
FeynCalc`FCCanonicalizeDummyIndices`Private`renameDummies[
     FeynCalc`FCCanonicalizeDummyIndices`Private`dummyNames_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`wrapHead_, 
     FeynCalc`FCCanonicalizeDummyIndices`Private`totalRepLis_] := 
    Block[{FeynCalc`FCCanonicalizeDummyIndices`Private`dummyHeads, 
      FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule = {}}, 
     If[FeynCalc`FCCanonicalizeDummyIndices`Private`dummyNames =!= {}, 
       FeynCalc`FCCanonicalizeDummyIndices`Private`dummyHeads = 
         Cases2[FeynCalc`FCCanonicalizeDummyIndices`Private`totalRepLis, 
          FeynCalc`FCCanonicalizeDummyIndices`Private`wrapHead]; 
        If[Length[FeynCalc`FCCanonicalizeDummyIndices`Private`dummyNames] < 
          Length[FeynCalc`FCCanonicalizeDummyIndices`Private`dummyHeads], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule = 
          Thread[FeynCalc`FCCanonicalizeDummyIndices`Private`dummyHeads[[
             1 ;; Length[
               FeynCalc`FCCanonicalizeDummyIndices`Private`dummyNames]]] -> 
            FeynCalc`FCCanonicalizeDummyIndices`Private`dummyNames], 
         FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule = 
          Thread[FeynCalc`FCCanonicalizeDummyIndices`Private`dummyHeads -> 
            FeynCalc`FCCanonicalizeDummyIndices`Private`dummyNames[[
             1 ;; Length[
               FeynCalc`FCCanonicalizeDummyIndices`Private`dummyHeads]]]]]]; 
      FeynCalc`FCCanonicalizeDummyIndices`Private`renamingRule]
 
SUNTraceEvaluate /: SUNTraceEvaluate::usage = "SUNTraceEvaluate is an option \
for SUNTrace, SUNSimplify and some other\nfunctions. If set to False, color \
traces remain unevaluated. Automatic implies\nevaluation of traces with 2 or \
3 color matrices. Setting this option to True\nwill force every trace to be \
evaluated. For more details, see the\ndocumentation for SUNTrace and \
SUNSimplify."
 
FeynCalc`DotSimplify`Private`holdDOT[] = 1
 
FeynCalc`DotSimplify`Private`holdDOT[___, 0, ___] := 0
 
FeynCalc`DotSimplify`Private`holdDOT[FeynCalc`DotSimplify`Private`a___, 1, 
     FeynCalc`DotSimplify`Private`b___] := 
    FeynCalc`DotSimplify`Private`holdDOT[FeynCalc`DotSimplify`Private`a, 
     FeynCalc`DotSimplify`Private`b]
 
FeynCalc`DotSimplify`Private`pid[FeynCalc`DotSimplify`Private`u_, _] := 
    FeynCalc`DotSimplify`Private`u
 
FeynCalc`DotSimplify`Private`orderedQ[FeynCalc`DotSimplify`Private`x_, 
     Automatic] := FeynCalc`DotSimplify`Private`orderedQ[
     FeynCalc`DotSimplify`Private`x]
 
FeynCalc`DotSimplify`Private`commutatorEvaluationRules /: 
    FeynCalc`DotSimplify`Private`commutatorEvaluationRules::usage = ""
 
FeynCalc`DotSimplify`Private`antiCommutatorEvaluationRules /: 
    FeynCalc`DotSimplify`Private`antiCommutatorEvaluationRules::usage = ""
 
FeynCalc`DotSimplify`Private`dotExpand[FeynCalc`DotSimplify`Private`x_] := 
    Block[{FeynCalc`DotSimplify`Private`tmp}, 
     FeynCalc`DotSimplify`Private`tmp = FeynCalc`DotSimplify`Private`x; 
      FeynCalc`DotSimplify`Private`tmp = FeynCalc`DotSimplify`Private`tmp /. 
        DOT -> FeynCalc`DotSimplify`Private`dlin0; 
      FeynCalc`DotSimplify`Private`tmp = FeynCalc`DotSimplify`Private`tmp /. 
         FeynCalc`DotSimplify`Private`dlin0 -> 
          FeynCalc`DotSimplify`Private`dlin //. 
        FeynCalc`DotSimplify`Private`dlin[
          FeynCalc`DotSimplify`Private`a__] :> 
         FeynCalc`DotSimplify`Private`dlin1[{}, 
          FeynCalc`DotSimplify`Private`a]; FeynCalc`DotSimplify`Private`tmp = 
       FeynCalc`DotSimplify`Private`tmp //. 
        FeynCalc`DotSimplify`Private`dlin1[
          {FeynCalc`DotSimplify`Private`a___}] :> 
         DOT[FeynCalc`DotSimplify`Private`a]; 
      FeynCalc`DotSimplify`Private`tmp = FeynCalc`DotSimplify`Private`tmp /. 
        DOT -> FeynCalc`DotSimplify`Private`DOTcomm; 
      FeynCalc`DotSimplify`Private`tmp = FeynCalc`DotSimplify`Private`tmp /. 
        FeynCalc`DotSimplify`Private`dlin -> DOT; 
      FeynCalc`DotSimplify`Private`tmp]
 
FeynCalc`DotSimplify`Private`dlin0[FeynCalc`DotSimplify`Private`a___] := 
    (Distribute[FeynCalc`DotSimplify`Private`dlin[
        FeynCalc`DotSimplify`Private`a]] //. 
      FeynCalc`DotSimplify`Private`dlin[FeynCalc`DotSimplify`Private`h___, 
        (FeynCalc`DotSimplify`Private`n_Integer)*
         (FeynCalc`DotSimplify`Private`c_), 
        FeynCalc`DotSimplify`Private`b___] :> FeynCalc`DotSimplify`Private`n*
        FeynCalc`DotSimplify`Private`dlin[FeynCalc`DotSimplify`Private`h, 
         FeynCalc`DotSimplify`Private`c, FeynCalc`DotSimplify`Private`b]) /; 
     FeynCalc`DotSimplify`Private`optExpanding
 
FeynCalc`DotSimplify`Private`dlin0[FeynCalc`DotSimplify`Private`a___] := 
    FeynCalc`DotSimplify`Private`dlin[FeynCalc`DotSimplify`Private`a] /; 
      !FeynCalc`DotSimplify`Private`optExpanding
 
FeynCalc`DotSimplify`Private`dlin[] = 1
 
FeynCalc`DotSimplify`Private`dlin1[{FeynCalc`DotSimplify`Private`ok___}, 
     FeynCalc`DotSimplify`Private`b_ /; 
      DataType[FeynCalc`DotSimplify`Private`b, NonCommutative], 
     FeynCalc`DotSimplify`Private`c___] := FeynCalc`DotSimplify`Private`dlin1[
     {FeynCalc`DotSimplify`Private`ok, FeynCalc`DotSimplify`Private`b}, 
     FeynCalc`DotSimplify`Private`c]
 
FeynCalc`DotSimplify`Private`dlin1[{FeynCalc`DotSimplify`Private`ok___}, 
     (FeynCalc`DotSimplify`Private`b_)*(FeynCalc`DotSimplify`Private`n_)?
        NumberQ /; DataType[FeynCalc`DotSimplify`Private`b, NonCommutative], 
     FeynCalc`DotSimplify`Private`c___] := FeynCalc`DotSimplify`Private`n*
     FeynCalc`DotSimplify`Private`dlin1[{FeynCalc`DotSimplify`Private`ok, 
       FeynCalc`DotSimplify`Private`b}, FeynCalc`DotSimplify`Private`c]
 
FeynCalc`DotSimplify`Private`dlin1[{FeynCalc`DotSimplify`Private`ok___}, 
     FeynCalc`DotSimplify`Private`b_, FeynCalc`DotSimplify`Private`c___] := 
    If[NonCommFreeQ[FeynCalc`DotSimplify`Private`b] === True && 
      FreeQ[FeynCalc`DotSimplify`Private`b, 
       FeynCalc`DotSimplify`Private`dlin1], FeynCalc`DotSimplify`Private`b*
      FeynCalc`DotSimplify`Private`dlin1[{FeynCalc`DotSimplify`Private`ok}, 
       FeynCalc`DotSimplify`Private`c], 
     If[Head[FeynCalc`DotSimplify`Private`b] === Times, 
      If[Select[FeynCalc`DotSimplify`Private`b, NonCommFreeQ[#1] & ] =!= 1, 
       Select[FeynCalc`DotSimplify`Private`b, NonCommFreeQ[#1] & ]*
        FeynCalc`DotSimplify`Private`dlin1[{FeynCalc`DotSimplify`Private`ok, 
          Select[FeynCalc`DotSimplify`Private`b,  !NonCommFreeQ[#1] & ]}, 
         FeynCalc`DotSimplify`Private`c], 
       If[Intersection[Head /@ Cases2[FeynCalc`DotSimplify`Private`b[[1]], 
             $NonComm], Head /@ Cases2[Rest[FeynCalc`DotSimplify`Private`b], 
             $NonComm]] =!= {}, Message[DotSimplify::failmsg, 
           "Detected commutative multiplication of noncommutative objects."]; 
          Abort[]]; FeynCalc`DotSimplify`Private`dlin1[
         {FeynCalc`DotSimplify`Private`ok}, FeynCalc`DotSimplify`Private`b[[
          1]], Rest[FeynCalc`DotSimplify`Private`b], 
         FeynCalc`DotSimplify`Private`c]], FeynCalc`DotSimplify`Private`dlin1[
       {FeynCalc`DotSimplify`Private`ok, FeynCalc`DotSimplify`Private`b}, 
       FeynCalc`DotSimplify`Private`c]]]
 
FeynCalc`DotSimplify`Private`DOTcomm[] = 1
 
FeynCalc`DotSimplify`Private`DOTcomm[FeynCalc`DotSimplify`Private`xy__] := 
    FixedPoint[FeynCalc`DotSimplify`Private`acomall, 
      FixedPoint[FeynCalc`DotSimplify`Private`comall, 
       DOT[FeynCalc`DotSimplify`Private`xy], 
       FeynCalc`DotSimplify`Private`optMaxIterations], 
      FeynCalc`DotSimplify`Private`optMaxIterations] /; 
     FeynCalc`DotSimplify`Private`optDotSimplifyRelations === {}
 
FeynCalc`DotSimplify`Private`DOTcomm[FeynCalc`DotSimplify`Private`xy__] := 
    (FixedPoint[FeynCalc`DotSimplify`Private`acomall, 
       FixedPoint[FeynCalc`DotSimplify`Private`comall, 
         DOT[FeynCalc`DotSimplify`Private`xy] //. 
          FeynCalc`DotSimplify`Private`optDotSimplifyRelations, 
         FeynCalc`DotSimplify`Private`optMaxIterations] //. 
        FeynCalc`DotSimplify`Private`optDotSimplifyRelations, 
       FeynCalc`DotSimplify`Private`optMaxIterations] //. 
      FeynCalc`DotSimplify`Private`optDotSimplifyRelations) /; 
     FeynCalc`DotSimplify`Private`optDotSimplifyRelations =!= {}
 
FeynCalc`DotSimplify`Private`acomall[FeynCalc`DotSimplify`Private`z__] := 
    FeynCalc`DotSimplify`Private`z //. 
     FeynCalc`DotSimplify`Private`antiCommutatorEvaluationRules
 
FeynCalc`DotSimplify`Private`comall[FeynCalc`DotSimplify`Private`z__] := 
    FeynCalc`DotSimplify`Private`z //. 
     FeynCalc`DotSimplify`Private`commutatorEvaluationRules
 
ImplicitSUNFIndex /: ImplicitSUNFIndex::usage = "ImplicitSUNFIndex is a data \
type. It mainly applies to names of quantum fields\nspecifying that the \
corresponding field carries an implicit $SU(N)$ index in\nthe fundamental \
representation.\n\nThis information can be supplied e.g. via \
DataType[QuarkField,\nImplicitSUNFIndex] = True, where QuarkField is a \
possible name of the relevant\nfield.\n\nThe ImplicitSUNFIndex property \
becomes relevant when simplifying \nnoncommutative products involving \
QuantumFields via ExpandPartialD,\nDotSimplify."
 
DotPower /: DotPower::usage = "DotPower is an option for DotSimplify. It \
determines whether non-commutative\npowers are represented by successive \
multiplication or by Power."
 
DiracGammaCombine[(FeynCalc`DiracGammaCombine`Private`a_) == 
      (FeynCalc`DiracGammaCombine`Private`b_), 
     FeynCalc`DiracGammaCombine`Private`opts:OptionsPattern[]] := 
    DiracGammaCombine[FeynCalc`DiracGammaCombine`Private`a, 
      FeynCalc`DiracGammaCombine`Private`opts] == 
     DiracGammaCombine[FeynCalc`DiracGammaCombine`Private`b, 
      FeynCalc`DiracGammaCombine`Private`opts]
 
DiracGammaCombine[FeynCalc`DiracGammaCombine`Private`expr_List, 
     FeynCalc`DiracGammaCombine`Private`opts:OptionsPattern[]] := 
    (DiracGammaCombine[#1, FeynCalc`DiracGammaCombine`Private`opts] & ) /@ 
     FeynCalc`DiracGammaCombine`Private`expr
 
DiracGammaCombine[FeynCalc`DiracGammaCombine`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`DiracGammaCombine`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`DiracGammaCombine`Private`ex, 
      FeynCalc`DiracGammaCombine`Private`tmp, 
      FeynCalc`DiracGammaCombine`Private`res, 
      FeynCalc`DiracGammaCombine`Private`holdDOT, 
      FeynCalc`DiracGammaCombine`Private`freePart, 
      FeynCalc`DiracGammaCombine`Private`diracPart, 
      FeynCalc`DiracGammaCombine`Private`holdPlus, 
      FeynCalc`DiracGammaCombine`Private`diracList, 
      FeynCalc`DiracGammaCombine`Private`diracListEval, 
      FeynCalc`DiracGammaCombine`Private`repRule, 
      FeynCalc`DiracGammaCombine`Private`null1, 
      FeynCalc`DiracGammaCombine`Private`null2}, 
     If[OptionValue[FCI], FeynCalc`DiracGammaCombine`Private`ex = 
        FeynCalc`DiracGammaCombine`Private`expr, 
       FeynCalc`DiracGammaCombine`Private`ex = 
        FCI[FeynCalc`DiracGammaCombine`Private`expr]]; 
      If[FreeQ[FeynCalc`DiracGammaCombine`Private`ex, DiracGamma], 
       Return[FeynCalc`DiracGammaCombine`Private`ex]]; 
      FeynCalc`DiracGammaCombine`Private`ex = 
       FeynCalc`DiracGammaCombine`Private`ex /. 
        Plus -> FeynCalc`DiracGammaCombine`Private`holdPlus; 
      FeynCalc`DiracGammaCombine`Private`diracList = 
       Sort[DeleteDuplicates[Cases[FeynCalc`DiracGammaCombine`Private`ex + 
           FeynCalc`DiracGammaCombine`Private`null1 + 
           FeynCalc`DiracGammaCombine`Private`null2, 
          FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`z__] /; 
            !FreeQ[{FeynCalc`DiracGammaCombine`Private`z}, DiracGamma], 
          Infinity]]]; FeynCalc`DiracGammaCombine`Private`diracListEval = 
       FeynCalc`DiracGammaCombine`Private`diracList /. 
          FeynCalc`DiracGammaCombine`Private`p_FeynCalc`DiracGammaCombine`Pri\
vate`holdPlus :> FeynCalc`DiracGammaCombine`Private`holdPlus @@ 
            Sort[List @@ FeynCalc`DiracGammaCombine`Private`p] //. 
         {FeynCalc`DiracGammaCombine`Private`holdPlus[
             FeynCalc`DiracGammaCombine`Private`a___, 
             (FeynCalc`DiracGammaCombine`Private`n1_.)*DiracGamma[Momentum[
                FeynCalc`DiracGammaCombine`Private`x_, 
                FeynCalc`DiracGammaCombine`Private`dim_:4], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             (FeynCalc`DiracGammaCombine`Private`n2_.)*DiracGamma[Momentum[
                FeynCalc`DiracGammaCombine`Private`y_, 
                FeynCalc`DiracGammaCombine`Private`dim_:4], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             FeynCalc`DiracGammaCombine`Private`b___] /; 
            NumberQ[FeynCalc`DiracGammaCombine`Private`n1] && 
             NumberQ[FeynCalc`DiracGammaCombine`Private`n2] :> 
           FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`a, DiracGamma[
             Momentum[FeynCalc`DiracGammaCombine`Private`n1*
                FeynCalc`DiracGammaCombine`Private`x + 
               FeynCalc`DiracGammaCombine`Private`n2*
                FeynCalc`DiracGammaCombine`Private`y, 
              FeynCalc`DiracGammaCombine`Private`dim], 
             FeynCalc`DiracGammaCombine`Private`dim], 
            FeynCalc`DiracGammaCombine`Private`b], 
          FeynCalc`DiracGammaCombine`Private`holdPlus[
             FeynCalc`DiracGammaCombine`Private`a___, 
             (FeynCalc`DiracGammaCombine`Private`n1_.)*DiracGamma[Momentum[
                FeynCalc`DiracGammaCombine`Private`x_, 
                FeynCalc`DiracGammaCombine`Private`dim_:4], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             (FeynCalc`DiracGammaCombine`Private`n2_.)*DiracGamma[Momentum[
                FeynCalc`DiracGammaCombine`Private`x_, 
                FeynCalc`DiracGammaCombine`Private`dim_:4], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             FeynCalc`DiracGammaCombine`Private`b___] /; 
            NumberQ[FeynCalc`DiracGammaCombine`Private`n1] && 
             NumberQ[FeynCalc`DiracGammaCombine`Private`n2] :> 
           FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`a, 
            (FeynCalc`DiracGammaCombine`Private`n1 + 
              FeynCalc`DiracGammaCombine`Private`n2)*DiracGamma[
              Momentum[FeynCalc`DiracGammaCombine`Private`x, 
               FeynCalc`DiracGammaCombine`Private`dim], 
              FeynCalc`DiracGammaCombine`Private`dim], 
            FeynCalc`DiracGammaCombine`Private`b], 
          FeynCalc`DiracGammaCombine`Private`holdPlus[
             FeynCalc`DiracGammaCombine`Private`a___, 
             (FeynCalc`DiracGammaCombine`Private`n1_.)*DiracGamma[
               LightConePerpendicularComponent[Momentum[
                 FeynCalc`DiracGammaCombine`Private`x_, 
                 FeynCalc`DiracGammaCombine`Private`dim_:4], 
                FeynCalc`DiracGammaCombine`Private`n_, 
                FeynCalc`DiracGammaCombine`Private`nb_], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             (FeynCalc`DiracGammaCombine`Private`n2_.)*DiracGamma[
               LightConePerpendicularComponent[Momentum[
                 FeynCalc`DiracGammaCombine`Private`y_, 
                 FeynCalc`DiracGammaCombine`Private`dim_:4], 
                FeynCalc`DiracGammaCombine`Private`n_, 
                FeynCalc`DiracGammaCombine`Private`nb_], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             FeynCalc`DiracGammaCombine`Private`b___] /; 
            NumberQ[FeynCalc`DiracGammaCombine`Private`n1] && 
             NumberQ[FeynCalc`DiracGammaCombine`Private`n2] :> 
           FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`a, DiracGamma[
             LightConePerpendicularComponent[Momentum[
               FeynCalc`DiracGammaCombine`Private`n1*
                 FeynCalc`DiracGammaCombine`Private`x + 
                FeynCalc`DiracGammaCombine`Private`n2*
                 FeynCalc`DiracGammaCombine`Private`y, 
               FeynCalc`DiracGammaCombine`Private`dim], 
              FeynCalc`DiracGammaCombine`Private`n, 
              FeynCalc`DiracGammaCombine`Private`nb], 
             FeynCalc`DiracGammaCombine`Private`dim], 
            FeynCalc`DiracGammaCombine`Private`b], 
          FeynCalc`DiracGammaCombine`Private`holdPlus[
             FeynCalc`DiracGammaCombine`Private`a___, 
             (FeynCalc`DiracGammaCombine`Private`n1_.)*DiracGamma[
               LightConePerpendicularComponent[Momentum[
                 FeynCalc`DiracGammaCombine`Private`x_, 
                 FeynCalc`DiracGammaCombine`Private`dim_:4], 
                FeynCalc`DiracGammaCombine`Private`n_, 
                FeynCalc`DiracGammaCombine`Private`nb_], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             (FeynCalc`DiracGammaCombine`Private`n2_.)*DiracGamma[
               LightConePerpendicularComponent[Momentum[
                 FeynCalc`DiracGammaCombine`Private`x_, 
                 FeynCalc`DiracGammaCombine`Private`dim_:4], 
                FeynCalc`DiracGammaCombine`Private`n_, 
                FeynCalc`DiracGammaCombine`Private`nb_], 
               FeynCalc`DiracGammaCombine`Private`dim_:4], 
             FeynCalc`DiracGammaCombine`Private`b___] /; 
            NumberQ[FeynCalc`DiracGammaCombine`Private`n1] && 
             NumberQ[FeynCalc`DiracGammaCombine`Private`n2] :> 
           FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`a, 
            (FeynCalc`DiracGammaCombine`Private`n1 + 
              FeynCalc`DiracGammaCombine`Private`n2)*DiracGamma[
              LightConePerpendicularComponent[Momentum[
                FeynCalc`DiracGammaCombine`Private`x, 
                FeynCalc`DiracGammaCombine`Private`dim], 
               FeynCalc`DiracGammaCombine`Private`n, 
               FeynCalc`DiracGammaCombine`Private`nb], 
              FeynCalc`DiracGammaCombine`Private`dim], 
            FeynCalc`DiracGammaCombine`Private`b], 
          FeynCalc`DiracGammaCombine`Private`holdPlus[
             FeynCalc`DiracGammaCombine`Private`a___, 
             (FeynCalc`DiracGammaCombine`Private`n1_.)*DiracGamma[
               CartesianMomentum[FeynCalc`DiracGammaCombine`Private`x_, 
                FeynCalc`DiracGammaCombine`Private`dim1_:3], 
               FeynCalc`DiracGammaCombine`Private`dim2_:4], 
             (FeynCalc`DiracGammaCombine`Private`n2_.)*DiracGamma[
               CartesianMomentum[FeynCalc`DiracGammaCombine`Private`y_, 
                FeynCalc`DiracGammaCombine`Private`dim1_:3], 
               FeynCalc`DiracGammaCombine`Private`dim2_:4], 
             FeynCalc`DiracGammaCombine`Private`b___] /; 
            NumberQ[FeynCalc`DiracGammaCombine`Private`n1] && 
             NumberQ[FeynCalc`DiracGammaCombine`Private`n2] :> 
           FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`a, DiracGamma[
             CartesianMomentum[FeynCalc`DiracGammaCombine`Private`n1*
                FeynCalc`DiracGammaCombine`Private`x + 
               FeynCalc`DiracGammaCombine`Private`n2*
                FeynCalc`DiracGammaCombine`Private`y, 
              FeynCalc`DiracGammaCombine`Private`dim1], 
             FeynCalc`DiracGammaCombine`Private`dim2], 
            FeynCalc`DiracGammaCombine`Private`b], 
          FeynCalc`DiracGammaCombine`Private`holdPlus[
             FeynCalc`DiracGammaCombine`Private`a___, 
             (FeynCalc`DiracGammaCombine`Private`n1_.)*DiracGamma[
               CartesianMomentum[FeynCalc`DiracGammaCombine`Private`x_, 
                FeynCalc`DiracGammaCombine`Private`dim1_:3], 
               FeynCalc`DiracGammaCombine`Private`dim2_:4], 
             (FeynCalc`DiracGammaCombine`Private`n2_.)*DiracGamma[
               CartesianMomentum[FeynCalc`DiracGammaCombine`Private`x_, 
                FeynCalc`DiracGammaCombine`Private`dim1_:3], 
               FeynCalc`DiracGammaCombine`Private`dim2_:4], 
             FeynCalc`DiracGammaCombine`Private`b___] /; 
            NumberQ[FeynCalc`DiracGammaCombine`Private`n1] && 
             NumberQ[FeynCalc`DiracGammaCombine`Private`n2] :> 
           FeynCalc`DiracGammaCombine`Private`holdPlus[
            FeynCalc`DiracGammaCombine`Private`a, 
            (FeynCalc`DiracGammaCombine`Private`n1 + 
              FeynCalc`DiracGammaCombine`Private`n2)*DiracGamma[
              CartesianMomentum[FeynCalc`DiracGammaCombine`Private`x, 
               FeynCalc`DiracGammaCombine`Private`dim1], 
              FeynCalc`DiracGammaCombine`Private`dim2], 
            FeynCalc`DiracGammaCombine`Private`b]} /. 
        FeynCalc`DiracGammaCombine`Private`holdPlus -> Plus; 
      FeynCalc`DiracGammaCombine`Private`repRule = 
       Thread[FeynCalc`DiracGammaCombine`Private`diracList -> 
         FeynCalc`DiracGammaCombine`Private`diracListEval]; 
      FeynCalc`DiracGammaCombine`Private`res = 
       FeynCalc`DiracGammaCombine`Private`ex /. 
         Dispatch[FeynCalc`DiracGammaCombine`Private`repRule] /. 
        FeynCalc`DiracGammaCombine`Private`holdPlus -> Plus; 
      If[OptionValue[FCE], FeynCalc`DiracGammaCombine`Private`res = 
        FCE[FeynCalc`DiracGammaCombine`Private`res]]; 
      FeynCalc`DiracGammaCombine`Private`res]
 
Options[DiracGammaCombine] = {FeynCalcExternal -> False, 
     FeynCalcInternal -> False}
 
DiracGammaCombine /: DiracGammaCombine::usage = "DiracGammaCombine[exp] is \
(nearly) the inverse operation to DiracGammaExpand."
 
FeynCalc`FCDiracIsolate`Private`makeSelectionList[
     FeynCalc`FCDiracIsolate`Private`expr_, 
     FeynCalc`FCDiracIsolate`Private`heads_List] := 
    MemSet[FeynCalc`FCDiracIsolate`Private`makeSelectionList[
      FeynCalc`FCDiracIsolate`Private`expr, 
      FeynCalc`FCDiracIsolate`Private`heads], 
     Join[FeynCalc`FCDiracIsolate`Private`heads, 
      Intersection[Cases[SelectFree[FeynCalc`FCDiracIsolate`Private`expr, 
         FeynCalc`FCDiracIsolate`Private`heads], 
        FeynCalc`FCDiracIsolate`Private`l:_LorentzIndex | _CartesianIndex :> 
         FeynCalc`FCDiracIsolate`Private`l[[1]], Infinity], 
       Cases[SelectNotFree[FeynCalc`FCDiracIsolate`Private`expr, 
         FeynCalc`FCDiracIsolate`Private`heads], 
        FeynCalc`FCDiracIsolate`Private`l:_LorentzIndex | _CartesianIndex :> 
         FeynCalc`FCDiracIsolate`Private`l[[1]], Infinity]]]]
 
FeynCalc`FCDiracIsolate`Private`holdDOT[] = 1
 
FeynCalc`FCDiracIsolate`Private`chainSplit[
     FeynCalc`FCDiracIsolate`Private`ex_, 
     FeynCalc`FCDiracIsolate`Private`head_] := 
    (FeynCalc`FCDiracIsolate`Private`tmp = 
      FeynCalc`FCDiracIsolate`Private`ex //. 
       FeynCalc`FCDiracIsolate`Private`head[
          (
            FeynCalc`FCDiracIsolate`Private`a_FeynCalc`FCDiracIsolate`Private\
`holdDOT)*(FeynCalc`FCDiracIsolate`Private`b_)] /; 
          !FreeQ[FeynCalc`FCDiracIsolate`Private`b, 
           FeynCalc`FCDiracIsolate`Private`holdDOT] :> 
        FeynCalc`FCDiracIsolate`Private`head[
          FeynCalc`FCDiracIsolate`Private`a]*
         FeynCalc`FCDiracIsolate`Private`head[
          FeynCalc`FCDiracIsolate`Private`b]; 
     If[ !FreeQ[FeynCalc`FCDiracIsolate`Private`tmp, Spinor], 
      FeynCalc`FCDiracIsolate`Private`tmp = 
       FeynCalc`FCDiracIsolate`Private`tmp /. 
        {FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
             FeynCalc`FCDiracIsolate`Private`r1___, 
             FeynCalc`FCDiracIsolate`Private`a_Spinor, 
             FeynCalc`FCDiracIsolate`Private`b___, 
             FeynCalc`FCDiracIsolate`Private`c_Spinor, 
             FeynCalc`FCDiracIsolate`Private`d_Spinor, 
             FeynCalc`FCDiracIsolate`Private`e___, 
             FeynCalc`FCDiracIsolate`Private`f_Spinor, 
             FeynCalc`FCDiracIsolate`Private`r2___]] /; 
           FreeQ[{FeynCalc`FCDiracIsolate`Private`r1, 
             FeynCalc`FCDiracIsolate`Private`b, 
             FeynCalc`FCDiracIsolate`Private`e, 
             FeynCalc`FCDiracIsolate`Private`r2}, Spinor] :> 
          FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
             FeynCalc`FCDiracIsolate`Private`a, 
             FeynCalc`FCDiracIsolate`Private`b, 
             FeynCalc`FCDiracIsolate`Private`c]]*
           FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
             FeynCalc`FCDiracIsolate`Private`d, 
             FeynCalc`FCDiracIsolate`Private`e, 
             FeynCalc`FCDiracIsolate`Private`f]]*
           FeynCalc`FCDiracIsolate`Private`head[
            FeynCalc`FCDiracIsolate`Private`holdDOT[
             FeynCalc`FCDiracIsolate`Private`r1, 
             FeynCalc`FCDiracIsolate`Private`r2]]}]; 
     FeynCalc`FCDiracIsolate`Private`tmp)
 
FCPauliIsolate[(FeynCalc`FCPauliIsolate`Private`a_) == 
      (FeynCalc`FCPauliIsolate`Private`b_), 
     FeynCalc`FCPauliIsolate`Private`opts:OptionsPattern[]] := 
    FCPauliIsolate[FeynCalc`FCPauliIsolate`Private`a, 
      FeynCalc`FCPauliIsolate`Private`opts] == FCPauliIsolate[
      FeynCalc`FCPauliIsolate`Private`b, FeynCalc`FCPauliIsolate`Private`opts]
 
FCPauliIsolate[FeynCalc`FCPauliIsolate`Private`expr_List, 
     FeynCalc`FCPauliIsolate`Private`opts:OptionsPattern[]] := 
    (FCPauliIsolate[#1, FeynCalc`FCPauliIsolate`Private`opts] & ) /@ 
     FeynCalc`FCPauliIsolate`Private`expr
 
FCPauliIsolate[FeynCalc`FCPauliIsolate`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`FCPauliIsolate`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`FCPauliIsolate`Private`res, 
      FeynCalc`FCPauliIsolate`Private`null1, 
      FeynCalc`FCPauliIsolate`Private`null2, 
      FeynCalc`FCPauliIsolate`Private`ex, 
      FeynCalc`FCPauliIsolate`Private`tmp, 
      FeynCalc`FCPauliIsolate`Private`head, 
      FeynCalc`FCPauliIsolate`Private`selectionList, 
      FeynCalc`FCPauliIsolate`Private`tmpHead, 
      FeynCalc`FCPauliIsolate`Private`time, 
      FeynCalc`FCPauliIsolate`Private`fcpiVerbose, 
      FeynCalc`FCPauliIsolate`Private`headsList, 
      FeynCalc`FCPauliIsolate`Private`headsOrig, 
      FeynCalc`FCPauliIsolate`Private`optTimeConstrained, 
      FeynCalc`FCPauliIsolate`Private`optHead, 
      FeynCalc`FCPauliIsolate`Private`headR, 
      FeynCalc`FCPauliIsolate`Private`collectList, 
      FeynCalc`FCPauliIsolate`Private`optSplit, 
      FeynCalc`FCPauliIsolate`Private`allHeads, 
      FeynCalc`FCPauliIsolate`Private`allHeadsEval}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCPauliIsolate`Private`fcpiVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCPauliIsolate`Private`fcpiVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCPauliIsolate`Private`optTimeConstrained = 
       OptionValue[TimeConstrained]; 
      FeynCalc`FCPauliIsolate`Private`optSplit = OptionValue[Split]; 
      FeynCalc`FCPauliIsolate`Private`headsOrig = 
       Complement[FeynCalc`Package`PauliHeadsList, OptionValue[ExceptHeads]]; 
      FeynCalc`FCPauliIsolate`Private`headsList = 
       FeynCalc`FCPauliIsolate`Private`headsOrig; 
      FeynCalc`FCPauliIsolate`Private`collectList = 
       FeynCalc`FCPauliIsolate`Private`headsList; 
      If[OptionValue[Polarization], 
       FeynCalc`FCPauliIsolate`Private`headsList = 
         Join[FeynCalc`FCPauliIsolate`Private`headsList, {Polarization}]; ]; 
      If[OptionValue[LorentzIndex] === All, 
       FeynCalc`FCPauliIsolate`Private`headsList = 
         Join[FeynCalc`FCPauliIsolate`Private`headsList, {LorentzIndex}]; ]; 
      If[OptionValue[CartesianIndex] === All, 
       FeynCalc`FCPauliIsolate`Private`headsList = 
         Join[FeynCalc`FCPauliIsolate`Private`headsList, 
          {CartesianIndex}]; ]; If[OptionValue[Polarization] =!= False, 
       FeynCalc`FCPauliIsolate`Private`collectList = 
        Join[FeynCalc`FCPauliIsolate`Private`collectList, {Polarization}]]; 
      If[OptionValue[LorentzIndex] =!= False, 
       FeynCalc`FCPauliIsolate`Private`collectList = 
        Join[FeynCalc`FCPauliIsolate`Private`collectList, {LorentzIndex}]]; 
      If[OptionValue[CartesianIndex] =!= False, 
       FeynCalc`FCPauliIsolate`Private`collectList = 
        Join[FeynCalc`FCPauliIsolate`Private`collectList, {CartesianIndex}]]; 
      FeynCalc`FCPauliIsolate`Private`optHead = OptionValue[Head]; 
      If[MatchQ[FeynCalc`FCPauliIsolate`Private`optHead, {_, _}], 
       {FeynCalc`FCPauliIsolate`Private`head, 
         FeynCalc`FCPauliIsolate`Private`headR} = 
        FeynCalc`FCPauliIsolate`Private`optHead, 
       FeynCalc`FCPauliIsolate`Private`head = 
         FeynCalc`FCPauliIsolate`Private`optHead; 
        FeynCalc`FCPauliIsolate`Private`headR = Identity]; 
      If[OptionValue[FCI], FeynCalc`FCPauliIsolate`Private`ex = 
        FeynCalc`FCPauliIsolate`Private`expr /. (#1 -> Identity & ) /@ 
          OptionValue[ClearHeads], FeynCalc`FCPauliIsolate`Private`ex = 
        FCI[FeynCalc`FCPauliIsolate`Private`expr] /. (#1 -> Identity & ) /@ 
          OptionValue[ClearHeads]]; FCPrint[3, 
       "FCPauliIsolate: Entering with: ", FeynCalc`FCPauliIsolate`Private`ex, 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      If[FreeQ2[FeynCalc`FCPauliIsolate`Private`ex, 
        FeynCalc`FCPauliIsolate`Private`headsList], 
       Return[FeynCalc`FCPauliIsolate`Private`restHead[
          FeynCalc`FCPauliIsolate`Private`ex] /. 
         FeynCalc`FCPauliIsolate`Private`restHead -> 
          FeynCalc`FCPauliIsolate`Private`headR]]; 
      If[OptionValue[PauliSigmaCombine], 
       FeynCalc`FCPauliIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCPauliIsolate: Applying PauliSigmaCombine.", 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FeynCalc`FCPauliIsolate`Private`ex = PauliSigmaCombine[
          FeynCalc`FCPauliIsolate`Private`ex, FCI -> True]; 
        FCPrint[1, "FCPauliIsolate: Done applying PauliSigmaCombine, timing: \
", N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FCPrint[3, "FCPauliIsolate: After PauliSigmaCombine: ", 
         FeynCalc`FCPauliIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCPauliIsolate`Private`fcpiVerbose]]; 
      If[OptionValue[Expanding], FeynCalc`FCPauliIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCPauliIsolate: Applying Expand2.", 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FeynCalc`FCPauliIsolate`Private`ex = 
         Expand2[FeynCalc`FCPauliIsolate`Private`ex, 
          FeynCalc`FCPauliIsolate`Private`headsList]; 
        FCPrint[1, "FCPauliIsolate: Done applying Expand2, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FCPrint[3, "FCPauliIsolate: After Expand2: ", 
         FeynCalc`FCPauliIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCPauliIsolate`Private`fcpiVerbose]]; 
      If[OptionValue[DotSimplify] && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`ex, DOT], 
       FeynCalc`FCPauliIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCPauliIsolate: Applying DotSimplify.", 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FeynCalc`FCPauliIsolate`Private`tmp = 
         FCSplit[FeynCalc`FCPauliIsolate`Private`ex, 
          FeynCalc`FCPauliIsolate`Private`headsList, Expanding -> 
           OptionValue[Expanding]]; FeynCalc`FCPauliIsolate`Private`ex = 
         FeynCalc`FCPauliIsolate`Private`tmp[[1]] + DotSimplify[
           FeynCalc`FCPauliIsolate`Private`tmp[[2]], Expanding -> False, 
           FCI -> True, FCJoinDOTs -> OptionValue[FCJoinDOTs]]; 
        FCPrint[1, "FCPauliIsolate: Done applying DotSimplify, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FCPrint[3, "FCPauliIsolate: After DotSimplify: ", 
         FeynCalc`FCPauliIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCPauliIsolate`Private`fcpiVerbose]]; 
      If[OptionValue[FCTraceExpand], FeynCalc`FCPauliIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCPauliIsolate: Applying FCTraceExpand.", FCDoControl -> 
          FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FeynCalc`FCPauliIsolate`Private`ex = FCTraceExpand[
          FeynCalc`FCPauliIsolate`Private`ex, FCI -> True, 
          SUNTrace -> False]; FCPrint[1, 
         "FCPauliIsolate: Done applying FCTraceExpand, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FCPrint[3, "FCPauliIsolate: After FCTraceExpand: ", 
         FeynCalc`FCPauliIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCPauliIsolate`Private`fcpiVerbose]]; 
      If[OptionValue[Collecting], FeynCalc`FCPauliIsolate`Private`time = 
         AbsoluteTime[]; FCPrint[1, "FCPauliIsolate: Applying Collect2.", 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FeynCalc`FCPauliIsolate`Private`ex = Collect2[
          FeynCalc`FCPauliIsolate`Private`ex, 
          FeynCalc`FCPauliIsolate`Private`headsList, Factoring -> 
           OptionValue[Factoring], TimeConstrained -> 
           FeynCalc`FCPauliIsolate`Private`optTimeConstrained]; 
        FCPrint[1, "FCPauliIsolate: Done applying Collect2, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        FCPrint[3, "FCPauliIsolate: After Collect2: ", 
         FeynCalc`FCPauliIsolate`Private`ex, FCDoControl -> 
          FeynCalc`FCPauliIsolate`Private`fcpiVerbose]]; 
      FeynCalc`FCPauliIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCPauliIsolate: Isolating heads.", 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      If[OptionValue[LorentzIndex] === True || 
        OptionValue[CartesianIndex] === True, 
       FeynCalc`FCPauliIsolate`Private`res = 
        ((FeynCalc`FCPauliIsolate`Private`selectionList = 
              FeynCalc`FCPauliIsolate`Private`makeSelectionList[#1, 
               FeynCalc`FCPauliIsolate`Private`headsList]; 
             FeynCalc`FCPauliIsolate`Private`restHead[SelectFree[#1, 
                FeynCalc`FCPauliIsolate`Private`selectionList]]*
              FeynCalc`FCPauliIsolate`Private`head[SelectNotFree[#1, 
                FeynCalc`FCPauliIsolate`Private`selectionList]]) & ) /@ 
           (FeynCalc`FCPauliIsolate`Private`ex + 
            FeynCalc`FCPauliIsolate`Private`null1 + 
            FeynCalc`FCPauliIsolate`Private`null2) /. 
          {FeynCalc`FCPauliIsolate`Private`null1 | 
             FeynCalc`FCPauliIsolate`Private`null2 -> 0} /. 
         FeynCalc`FCPauliIsolate`Private`head[1] -> 1, 
       FeynCalc`FCPauliIsolate`Private`res = 
        (FeynCalc`FCPauliIsolate`Private`restHead[SelectFree[#1, 
               FeynCalc`FCPauliIsolate`Private`headsList]]*
             FeynCalc`FCPauliIsolate`Private`head[SelectNotFree[#1, 
               FeynCalc`FCPauliIsolate`Private`headsList]] & ) /@ 
           (FeynCalc`FCPauliIsolate`Private`ex + 
            FeynCalc`FCPauliIsolate`Private`null1 + 
            FeynCalc`FCPauliIsolate`Private`null2) /. 
          {FeynCalc`FCPauliIsolate`Private`null1 | 
             FeynCalc`FCPauliIsolate`Private`null2 -> 0} /. 
         FeynCalc`FCPauliIsolate`Private`head[1] -> 1]; 
      FCPrint[1, "FCPauliIsolate: Done isolating heads, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      If[Together[(FeynCalc`FCPauliIsolate`Private`res /. 
           FeynCalc`FCPauliIsolate`Private`restHead | 
             FeynCalc`FCPauliIsolate`Private`head -> Identity) - 
          FeynCalc`FCPauliIsolate`Private`ex] =!= 0, 
       Message[FCPauliIsolate::fail, FeynCalc`FCPauliIsolate`Private`ex]; 
        Abort[]]; FeynCalc`FCPauliIsolate`Private`allHeads = 
       Cases2[FeynCalc`FCPauliIsolate`Private`res, 
        FeynCalc`FCPauliIsolate`Private`head]; 
      FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
       FeynCalc`FCPauliIsolate`Private`allHeads /. 
        DOT -> FeynCalc`FCPauliIsolate`Private`holdDOT; 
      FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval /. 
        {FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`x_] /; 
            !FreeQ2[FeynCalc`FCPauliIsolate`Private`x, OptionValue[
              ExceptHeads]] :> FeynCalc`FCPauliIsolate`Private`x}; 
      If[FeynCalc`FCPauliIsolate`Private`optSplit =!= False, 
       FeynCalc`FCPauliIsolate`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCPauliIsolate: Doing splittings.", 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
        Switch[FeynCalc`FCPauliIsolate`Private`optSplit, True, 
         FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
          FeynCalc`FCPauliIsolate`Private`chainSplit[
           FeynCalc`FCPauliIsolate`Private`allHeadsEval, 
           FeynCalc`FCPauliIsolate`Private`head], _Symbol, 
         FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
          FeynCalc`FCPauliIsolate`Private`allHeadsEval /. 
           FeynCalc`FCPauliIsolate`Private`head[
             FeynCalc`FCPauliIsolate`Private`x_] :> 
            FeynCalc`FCPauliIsolate`Private`optSplit[
             FeynCalc`FCPauliIsolate`Private`chainSplit[
              FeynCalc`FCPauliIsolate`Private`head[
               FeynCalc`FCPauliIsolate`Private`x], 
              FeynCalc`FCPauliIsolate`Private`head]], _, Null]; 
        FCPrint[1, "FCPauliIsolate: Splittings done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
         FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]]; 
      FeynCalc`FCPauliIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCPauliIsolate: Removing unneeded isolations.", 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      If[ !OptionValue[PauliTrace] && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`allHeadsEval, PauliTrace], 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
        FeynCalc`FCPauliIsolate`Private`allHeadsEval //. 
         FeynCalc`FCPauliIsolate`Private`head[
           (FeynCalc`FCPauliIsolate`Private`x_PauliTrace)*
            (FeynCalc`FCPauliIsolate`Private`y_.)] :> 
          FeynCalc`FCPauliIsolate`Private`x*
           FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`y]]; 
      If[ !OptionValue[PauliChain] && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`allHeadsEval, PauliChain], 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
        FeynCalc`FCPauliIsolate`Private`allHeadsEval //. 
          FeynCalc`FCPauliIsolate`Private`head[
            (FeynCalc`FCPauliIsolate`Private`x_PauliChain)*
             (FeynCalc`FCPauliIsolate`Private`y_.)] :> 
           FeynCalc`FCPauliIsolate`Private`x*
            FeynCalc`FCPauliIsolate`Private`head[
             FeynCalc`FCPauliIsolate`Private`y] //. 
         FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`holdDOT[
              FeynCalc`FCPauliIsolate`Private`x__]*
             (FeynCalc`FCPauliIsolate`Private`y_.)] /; 
            !FreeQ[{FeynCalc`FCPauliIsolate`Private`x}, PauliChain] :> 
          FeynCalc`FCPauliIsolate`Private`holdDOT[
            FeynCalc`FCPauliIsolate`Private`x]*
           FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`y]]; 
      If[ !OptionValue[PauliSigma] && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`allHeadsEval /. 
           _PauliChain :> Unique["pch"], PauliSigma], 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
        FeynCalc`FCPauliIsolate`Private`allHeadsEval //. 
          FeynCalc`FCPauliIsolate`Private`head[
            (FeynCalc`FCPauliIsolate`Private`x_PauliSigma)*
             (FeynCalc`FCPauliIsolate`Private`y_.)] :> 
           FeynCalc`FCPauliIsolate`Private`x*
            FeynCalc`FCPauliIsolate`Private`head[
             FeynCalc`FCPauliIsolate`Private`y] //. 
         FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`holdDOT[
              FeynCalc`FCPauliIsolate`Private`x__]*
             (FeynCalc`FCPauliIsolate`Private`y_.)] /; 
           FreeQ2[{FeynCalc`FCPauliIsolate`Private`x}, {PauliXi, PauliEta, 
              PauliEtaC}] &&  !FreeQ[{FeynCalc`FCPauliIsolate`Private`x}, 
              PauliSigma] :> FeynCalc`FCPauliIsolate`Private`holdDOT[
            FeynCalc`FCPauliIsolate`Private`x]*
           FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`y]]; 
      If[OptionValue[PauliXi] === False && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`allHeadsEval, PauliXi], 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
        FeynCalc`FCPauliIsolate`Private`allHeadsEval //. 
         FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`holdDOT[
              FeynCalc`FCPauliIsolate`Private`x__]*
             (FeynCalc`FCPauliIsolate`Private`y_.)] /; 
            !FreeQ[{FeynCalc`FCPauliIsolate`Private`x}, PauliXi] :> 
          FeynCalc`FCPauliIsolate`Private`holdDOT[
            FeynCalc`FCPauliIsolate`Private`x]*
           FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`y]]; 
      If[OptionValue[PauliEta] === False && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`allHeadsEval, PauliEta], 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
        FeynCalc`FCPauliIsolate`Private`allHeadsEval //. 
         FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`holdDOT[
              FeynCalc`FCPauliIsolate`Private`x__]*
             (FeynCalc`FCPauliIsolate`Private`y_.)] /; 
            !FreeQ[{FeynCalc`FCPauliIsolate`Private`x}, PauliEta] :> 
          FeynCalc`FCPauliIsolate`Private`holdDOT[
            FeynCalc`FCPauliIsolate`Private`x]*
           FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`y]]; 
      If[OptionValue[PauliEtaC] === False && 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`allHeadsEval, PauliEtaC], 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
        FeynCalc`FCPauliIsolate`Private`allHeadsEval //. 
         FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`holdDOT[
              FeynCalc`FCPauliIsolate`Private`x__]*
             (FeynCalc`FCPauliIsolate`Private`y_.)] /; 
            !FreeQ[{FeynCalc`FCPauliIsolate`Private`x}, PauliEtaC] :> 
          FeynCalc`FCPauliIsolate`Private`holdDOT[
            FeynCalc`FCPauliIsolate`Private`x]*
           FeynCalc`FCPauliIsolate`Private`head[
            FeynCalc`FCPauliIsolate`Private`y]]; 
      FCPrint[1, "FCPauliIsolate: Done removing unneeded isolations, timing: \
", N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      FeynCalc`FCPauliIsolate`Private`allHeadsEval = 
       FeynCalc`FCPauliIsolate`Private`allHeadsEval /. 
         FeynCalc`FCPauliIsolate`Private`holdDOT -> DOT //. 
        FeynCalc`FCPauliIsolate`Private`head[
           FeynCalc`FCPauliIsolate`Private`x_] /; 
          FreeQ2[FeynCalc`FCPauliIsolate`Private`x, 
           FeynCalc`FCPauliIsolate`Private`headsList] :> 
         FeynCalc`FCPauliIsolate`Private`x; 
      FeynCalc`FCPauliIsolate`Private`res = 
       FeynCalc`FCPauliIsolate`Private`res /. 
        Dispatch[Thread[FeynCalc`FCPauliIsolate`Private`allHeads -> 
           FeynCalc`FCPauliIsolate`Private`allHeadsEval]]; 
      FCPrint[1, "FCPauliIsolate: Handling nonpauli pieces.", 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      FeynCalc`FCPauliIsolate`Private`time = AbsoluteTime[]; 
      If[OptionValue[Isolate], FeynCalc`FCPauliIsolate`Private`res = 
        FeynCalc`FCPauliIsolate`Private`res /. 
         FeynCalc`FCPauliIsolate`Private`restHead[
           FeynCalc`FCPauliIsolate`Private`x_] :> 
          Isolate[FeynCalc`FCPauliIsolate`Private`x, IsolateNames -> 
            OptionValue[IsolateNames], IsolateFast -> OptionValue[
             IsolateFast]], FeynCalc`FCPauliIsolate`Private`res = 
         FeynCalc`FCPauliIsolate`Private`res /. 
           FeynCalc`FCPauliIsolate`Private`restHead[0] -> 0 /. 
          FeynCalc`FCPauliIsolate`Private`restHead -> 
           FeynCalc`FCPauliIsolate`Private`headR; ]; 
      FCPrint[1, "FCPauliIsolate: Done handling nondirac pieces, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCPauliIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      FeynCalc`FCPauliIsolate`Private`tmp = 
       FeynCalc`FCPauliIsolate`Private`headsList; 
      If[OptionValue[LorentzIndex] === True, 
       FeynCalc`FCPauliIsolate`Private`tmp = 
        Join[FeynCalc`FCPauliIsolate`Private`tmp, {LorentzIndex}]]; 
      If[OptionValue[CartesianIndex] === True, 
       FeynCalc`FCPauliIsolate`Private`tmp = 
        Join[FeynCalc`FCPauliIsolate`Private`tmp, {CartesianIndex}]]; 
      If[( !FreeQ2[FeynCalc`FCPauliIsolate`Private`res /. 
            FeynCalc`FCPauliIsolate`Private`head[__] :> 1, 
           FeynCalc`FCPauliIsolate`Private`tmp] & ) || 
         !FreeQ[FeynCalc`FCPauliIsolate`Private`res, 
          FeynCalc`FCPauliIsolate`Private`head[]], 
       Message[FCPauliIsolate::fail, FeynCalc`FCPauliIsolate`Private`ex]; 
        Abort[]]; If[OptionValue[FCE], FeynCalc`FCPauliIsolate`Private`res = 
        FCE[FeynCalc`FCPauliIsolate`Private`res]]; 
      FCPrint[1, "FCPauliIsolate: Leaving.", FCDoControl -> 
        FeynCalc`FCPauliIsolate`Private`fcpiVerbose]; 
      FeynCalc`FCPauliIsolate`Private`res]
 
Options[FCPauliIsolate] = {CartesianIndex -> False, 
     ClearHeads -> {FCGV["PauliChain"]}, Collecting -> True, 
     DotSimplify -> True, ExceptHeads -> {}, Expanding -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCJoinDOTs -> True, FCTraceExpand -> False, FCVerbose -> False, 
     Factoring -> {Factor2, 5000}, Head -> FCGV["PauliChain"], 
     Isolate -> False, IsolateFast -> False, IsolateNames -> KK, 
     LorentzIndex -> False, PauliChain -> False, PauliEta -> True, 
     PauliEtaC -> True, PauliSigma -> True, PauliSigmaCombine -> True, 
     PauliTrace -> True, PauliXi -> True, Polarization -> False, 
     Split -> True, TimeConstrained -> 3}
 
FCPauliIsolate /: FCPauliIsolate::fail = 
     "FCPauliIsolate failed to isolate Pauli structures in `1`!"
 
FCPauliIsolate /: FCPauliIsolate::usage = "FCPauliIsolate[exp] wraps chains \
of Pauli matrices into heads specified by the\nuser."
 
FeynCalc`FCPauliIsolate`Private`tmp /: 
    FeynCalc`FCPauliIsolate`Private`tmp::usage = ""
 
FeynCalc`FCPauliIsolate`Private`restHead[0] = 0
 
PauliSigmaCombine[FeynCalc`PauliSigmaCombine`Private`expr_, 
     OptionsPattern[]] := Block[{FeynCalc`PauliSigmaCombine`Private`ex, 
      FeynCalc`PauliSigmaCombine`Private`tmp, 
      FeynCalc`PauliSigmaCombine`Private`res, 
      FeynCalc`PauliSigmaCombine`Private`holdDOT, 
      FeynCalc`PauliSigmaCombine`Private`freePart, 
      FeynCalc`PauliSigmaCombine`Private`diracPart, 
      FeynCalc`PauliSigmaCombine`Private`holdPlus, 
      FeynCalc`PauliSigmaCombine`Private`pauliList, 
      FeynCalc`PauliSigmaCombine`Private`pauliListEval, 
      FeynCalc`PauliSigmaCombine`Private`repRule, 
      FeynCalc`PauliSigmaCombine`Private`null1, 
      FeynCalc`PauliSigmaCombine`Private`null2}, 
     If[OptionValue[FCI], FeynCalc`PauliSigmaCombine`Private`ex = 
        FeynCalc`PauliSigmaCombine`Private`expr, 
       FeynCalc`PauliSigmaCombine`Private`ex = 
        FCI[FeynCalc`PauliSigmaCombine`Private`expr]]; 
      If[FreeQ[FeynCalc`PauliSigmaCombine`Private`ex, PauliSigma], 
       Return[FeynCalc`PauliSigmaCombine`Private`ex]]; 
      FeynCalc`PauliSigmaCombine`Private`ex = 
       FeynCalc`PauliSigmaCombine`Private`ex /. 
        Plus -> FeynCalc`PauliSigmaCombine`Private`holdPlus; 
      FeynCalc`PauliSigmaCombine`Private`pauliList = 
       Sort[DeleteDuplicates[Cases[FeynCalc`PauliSigmaCombine`Private`ex + 
           FeynCalc`PauliSigmaCombine`Private`null1 + 
           FeynCalc`PauliSigmaCombine`Private`null2, 
          FeynCalc`PauliSigmaCombine`Private`holdPlus[
            FeynCalc`PauliSigmaCombine`Private`z__] /; 
            !FreeQ[{FeynCalc`PauliSigmaCombine`Private`z}, PauliSigma], 
          Infinity]]]; FeynCalc`PauliSigmaCombine`Private`pauliListEval = 
       FeynCalc`PauliSigmaCombine`Private`pauliList /. 
          FeynCalc`PauliSigmaCombine`Private`p_FeynCalc`PauliSigmaCombine`Pri\
vate`holdPlus :> FeynCalc`PauliSigmaCombine`Private`holdPlus @@ 
            Sort[List @@ FeynCalc`PauliSigmaCombine`Private`p] //. 
         {FeynCalc`PauliSigmaCombine`Private`holdPlus[
             FeynCalc`PauliSigmaCombine`Private`a___, 
             (FeynCalc`PauliSigmaCombine`Private`n1_.)*PauliSigma[
               CartesianMomentum[FeynCalc`PauliSigmaCombine`Private`x_, 
                FeynCalc`PauliSigmaCombine`Private`dim_:3], 
               FeynCalc`PauliSigmaCombine`Private`dim_:3], 
             (FeynCalc`PauliSigmaCombine`Private`n2_.)*PauliSigma[
               CartesianMomentum[FeynCalc`PauliSigmaCombine`Private`y_, 
                FeynCalc`PauliSigmaCombine`Private`dim_:3], 
               FeynCalc`PauliSigmaCombine`Private`dim_:3], 
             FeynCalc`PauliSigmaCombine`Private`b___] /; 
            NumberQ[FeynCalc`PauliSigmaCombine`Private`n1] && 
             NumberQ[FeynCalc`PauliSigmaCombine`Private`n2] :> 
           FeynCalc`PauliSigmaCombine`Private`holdPlus[
            FeynCalc`PauliSigmaCombine`Private`a, PauliSigma[
             CartesianMomentum[FeynCalc`PauliSigmaCombine`Private`n1*
                FeynCalc`PauliSigmaCombine`Private`x + 
               FeynCalc`PauliSigmaCombine`Private`n2*
                FeynCalc`PauliSigmaCombine`Private`y, 
              FeynCalc`PauliSigmaCombine`Private`dim], 
             FeynCalc`PauliSigmaCombine`Private`dim], 
            FeynCalc`PauliSigmaCombine`Private`b], 
          FeynCalc`PauliSigmaCombine`Private`holdPlus[
             FeynCalc`PauliSigmaCombine`Private`a___, 
             (FeynCalc`PauliSigmaCombine`Private`n1_.)*PauliSigma[
               CartesianMomentum[FeynCalc`PauliSigmaCombine`Private`x_, 
                FeynCalc`PauliSigmaCombine`Private`dim_:3], 
               FeynCalc`PauliSigmaCombine`Private`dim_:3], 
             (FeynCalc`PauliSigmaCombine`Private`n2_.)*PauliSigma[
               CartesianMomentum[FeynCalc`PauliSigmaCombine`Private`x_, 
                FeynCalc`PauliSigmaCombine`Private`dim_:3], 
               FeynCalc`PauliSigmaCombine`Private`dim_:3], 
             FeynCalc`PauliSigmaCombine`Private`b___] /; 
            NumberQ[FeynCalc`PauliSigmaCombine`Private`n1] && 
             NumberQ[FeynCalc`PauliSigmaCombine`Private`n2] :> 
           FeynCalc`PauliSigmaCombine`Private`holdPlus[
            FeynCalc`PauliSigmaCombine`Private`a, 
            (FeynCalc`PauliSigmaCombine`Private`n1 + 
              FeynCalc`PauliSigmaCombine`Private`n2)*PauliSigma[
              CartesianMomentum[FeynCalc`PauliSigmaCombine`Private`x, 
               FeynCalc`PauliSigmaCombine`Private`dim], 
              FeynCalc`PauliSigmaCombine`Private`dim], 
            FeynCalc`PauliSigmaCombine`Private`b], 
          FeynCalc`PauliSigmaCombine`Private`holdPlus[
             FeynCalc`PauliSigmaCombine`Private`a___, 
             (FeynCalc`PauliSigmaCombine`Private`n1_.)*PauliSigma[Momentum[
                FeynCalc`PauliSigmaCombine`Private`x_, 
                FeynCalc`PauliSigmaCombine`Private`dim1_:4], 
               FeynCalc`PauliSigmaCombine`Private`dim2_:3], 
             (FeynCalc`PauliSigmaCombine`Private`n2_.)*PauliSigma[Momentum[
                FeynCalc`PauliSigmaCombine`Private`y_, 
                FeynCalc`PauliSigmaCombine`Private`dim1_:4], 
               FeynCalc`PauliSigmaCombine`Private`dim2_:3], 
             FeynCalc`PauliSigmaCombine`Private`b___] /; 
            NumberQ[FeynCalc`PauliSigmaCombine`Private`n1] && 
             NumberQ[FeynCalc`PauliSigmaCombine`Private`n2] :> 
           FeynCalc`PauliSigmaCombine`Private`holdPlus[
            FeynCalc`PauliSigmaCombine`Private`a, PauliSigma[
             Momentum[FeynCalc`PauliSigmaCombine`Private`n1*
                FeynCalc`PauliSigmaCombine`Private`x + 
               FeynCalc`PauliSigmaCombine`Private`n2*
                FeynCalc`PauliSigmaCombine`Private`y, 
              FeynCalc`PauliSigmaCombine`Private`dim1], 
             FeynCalc`PauliSigmaCombine`Private`dim2], 
            FeynCalc`PauliSigmaCombine`Private`b], 
          FeynCalc`PauliSigmaCombine`Private`holdPlus[
             FeynCalc`PauliSigmaCombine`Private`a___, 
             (FeynCalc`PauliSigmaCombine`Private`n1_.)*PauliSigma[Momentum[
                FeynCalc`PauliSigmaCombine`Private`x_, 
                FeynCalc`PauliSigmaCombine`Private`dim1_:4], 
               FeynCalc`PauliSigmaCombine`Private`dim2_:3], 
             (FeynCalc`PauliSigmaCombine`Private`n2_.)*PauliSigma[Momentum[
                FeynCalc`PauliSigmaCombine`Private`x_, 
                FeynCalc`PauliSigmaCombine`Private`dim1_:4], 
               FeynCalc`PauliSigmaCombine`Private`dim2_:3], 
             FeynCalc`PauliSigmaCombine`Private`b___] /; 
            NumberQ[FeynCalc`PauliSigmaCombine`Private`n1] && 
             NumberQ[FeynCalc`PauliSigmaCombine`Private`n2] :> 
           FeynCalc`PauliSigmaCombine`Private`holdPlus[
            FeynCalc`PauliSigmaCombine`Private`a, 
            (FeynCalc`PauliSigmaCombine`Private`n1 + 
              FeynCalc`PauliSigmaCombine`Private`n2)*PauliSigma[
              Momentum[FeynCalc`PauliSigmaCombine`Private`x, 
               FeynCalc`PauliSigmaCombine`Private`dim1], 
              FeynCalc`PauliSigmaCombine`Private`dim2], 
            FeynCalc`PauliSigmaCombine`Private`b]} /. 
        FeynCalc`PauliSigmaCombine`Private`holdPlus -> Plus; 
      FeynCalc`PauliSigmaCombine`Private`repRule = 
       Thread[FeynCalc`PauliSigmaCombine`Private`pauliList -> 
         FeynCalc`PauliSigmaCombine`Private`pauliListEval]; 
      FeynCalc`PauliSigmaCombine`Private`res = 
       FeynCalc`PauliSigmaCombine`Private`ex /. 
         Dispatch[FeynCalc`PauliSigmaCombine`Private`repRule] /. 
        FeynCalc`PauliSigmaCombine`Private`holdPlus -> Plus; 
      If[OptionValue[FCE], FeynCalc`PauliSigmaCombine`Private`res = 
        FCE[FeynCalc`PauliSigmaCombine`Private`res]]; 
      FeynCalc`PauliSigmaCombine`Private`res]
 
Options[PauliSigmaCombine] = {FeynCalcInternal -> False, 
     FeynCalcExternal -> False}
 
PauliSigmaCombine /: PauliSigmaCombine::usage = "PauliSigmaCombine[exp]  is \
(nearly) the inverse operation to PauliSigmaExpand."
 
FeynCalc`FCPauliIsolate`Private`makeSelectionList[
     FeynCalc`FCPauliIsolate`Private`expr_, 
     FeynCalc`FCPauliIsolate`Private`heads_List] := 
    MemSet[FeynCalc`FCPauliIsolate`Private`makeSelectionList[
      FeynCalc`FCPauliIsolate`Private`expr, 
      FeynCalc`FCPauliIsolate`Private`heads], 
     Join[FeynCalc`FCPauliIsolate`Private`heads, 
      Intersection[Cases[SelectFree[FeynCalc`FCPauliIsolate`Private`expr, 
         FeynCalc`FCPauliIsolate`Private`heads], 
        FeynCalc`FCPauliIsolate`Private`l:_LorentzIndex | _CartesianIndex :> 
         FeynCalc`FCPauliIsolate`Private`l[[1]], Infinity], 
       Cases[SelectNotFree[FeynCalc`FCPauliIsolate`Private`expr, 
         FeynCalc`FCPauliIsolate`Private`heads], 
