FeynCalc`FCMatrixIsolate`Private`isolateMatrices[
     FeynCalc`FCMatrixIsolate`Private`x_, 
     {FeynCalc`FCMatrixIsolate`Private`fu_, 
      FeynCalc`FCMatrixIsolate`Private`checkHeads_List, 
      FeynCalc`FCMatrixIsolate`Private`isoHeads_, 
      FeynCalc`FCMatrixIsolate`Private`opts_}] := 
    Block[{FeynCalc`FCMatrixIsolate`Private`obj, 
      FeynCalc`FCMatrixIsolate`Private`objEval, 
      FeynCalc`FCMatrixIsolate`Private`repRule, 
      FeynCalc`FCMatrixIsolate`Private`time}, 
     FeynCalc`FCMatrixIsolate`Private`obj = 
       Cases2[FeynCalc`FCMatrixIsolate`Private`x, 
        FeynCalc`FCMatrixIsolate`Private`relevantPart]; 
      FCPrint[1, "FCMatrixIsolate: isolateMatrices: Entering ", 
       FeynCalc`FCMatrixIsolate`Private`fu, FCDoControl -> 
        FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FCPrint[3, "FCMatrixIsolate: isolateMatrices: Entering with", 
       FeynCalc`FCMatrixIsolate`Private`x, FCDoControl -> 
        FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      If[FreeQ2[FeynCalc`FCMatrixIsolate`Private`obj, 
        FeynCalc`FCMatrixIsolate`Private`checkHeads], 
       Return[FeynCalc`FCMatrixIsolate`Private`x]]; 
      FeynCalc`FCMatrixIsolate`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCMatrixIsolate: isolateMatrices: Applying ", 
       FeynCalc`FCMatrixIsolate`Private`fu, FCDoControl -> 
        FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FeynCalc`FCMatrixIsolate`Private`objEval = 
       (FeynCalc`FCMatrixIsolate`Private`fu[#1, 
          Join[FeynCalc`FCMatrixIsolate`Private`opts, 
           {Head -> FeynCalc`FCMatrixIsolate`Private`isoHeads}]] & ) /@ 
        (FeynCalc`FCMatrixIsolate`Private`obj /. 
         FeynCalc`FCMatrixIsolate`Private`relevantPart -> Identity); 
      FCPrint[1, StringJoin[
        "FCMatrixIsolate: isolateMatrices: Done applying ", 
        ToString[FeynCalc`FCMatrixIsolate`Private`fu, InputForm], 
        ", timing: "], N[AbsoluteTime[] - 
         FeynCalc`FCMatrixIsolate`Private`time, 4], 
       FCDoControl -> FeynCalc`FCMatrixIsolate`Private`fcmiVerbose]; 
      FeynCalc`FCMatrixIsolate`Private`repRule = 
       Thread[FeynCalc`FCMatrixIsolate`Private`obj -> 
         FeynCalc`FCMatrixIsolate`Private`objEval]; 
      FeynCalc`FCMatrixIsolate`Private`x /. 
       Dispatch[FeynCalc`FCMatrixIsolate`Private`repRule]]
 
