FeynCalc`Package`spinorSyntaxCorrectQ[FeynCalc`DiracSimplify`Private`ex_] := 
    Block[{FeynCalc`DiracSimplify`Private`spinors, 
      FeynCalc`DiracSimplify`Private`correct, 
      FeynCalc`DiracSimplify`Private`check, 
      FeynCalc`DiracSimplify`Private`null1, 
      FeynCalc`DiracSimplify`Private`null2}, 
     FeynCalc`DiracSimplify`Private`correct = True; 
      FeynCalc`DiracSimplify`Private`spinors = 
       Cases2[FeynCalc`DiracSimplify`Private`ex + 
         FeynCalc`DiracSimplify`Private`null1 + 
         FeynCalc`DiracSimplify`Private`null2, Spinor]; 
      FeynCalc`DiracSimplify`Private`spinors = MomentumExpand[
        FeynCalc`DiracSimplify`Private`spinors]; 
      If[FeynCalc`DiracSimplify`Private`spinors =!= {}, 
       FeynCalc`DiracSimplify`Private`check = 
         (MatchQ[#1, Spinor[(FeynCalc`DiracSimplify`Private`s_.)*Momentum[
                FeynCalc`DiracSimplify`Private`p_ /; 
                 Head[FeynCalc`DiracSimplify`Private`p] =!= Plus, 
                FeynCalc`DiracSimplify`Private`dim_:4], __] /; 
             MemberQ[{1, -1}, FeynCalc`DiracSimplify`Private`s]] & ) /@ 
          FeynCalc`DiracSimplify`Private`spinors; 
        If[Union[FeynCalc`DiracSimplify`Private`check] =!= {True}, 
         FeynCalc`DiracSimplify`Private`correct = False]]; 
      FeynCalc`DiracSimplify`Private`correct]
 
FermionSpinSum[FeynCalc`FermionSpinSum`Private`expr_List, 
     FeynCalc`FermionSpinSum`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FermionSpinSum`Private`optVerbose, 
      FeynCalc`FermionSpinSum`Private`res, 
      FeynCalc`FermionSpinSum`Private`time}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FermionSpinSum`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FermionSpinSum`Private`optVerbose = OptionValue[
           FCVerbose]]; ]; FeynCalc`FermionSpinSum`Private`time = 
       AbsoluteTime[]; If[$ParallelizeFeynCalc && OptionValue[FCParallelize], 
       FCPrint[1, "FermionSpinSum: Applying FermionSpinSum in parallel.", 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FeynCalc`FermionSpinSum`Private`res = ParallelMap[
          FermionSpinSum[#1, FilterRules[
             {FeynCalc`FermionSpinSum`Private`opts}, Except[FCParallelize | 
               FCVerbose]]] & , FeynCalc`FermionSpinSum`Private`expr, 
          DistributedContexts -> None, Method -> "ItemsPerEvaluation" -> 
            Ceiling[N[Length[FeynCalc`FermionSpinSum`Private`expr]/
                $KernelCount]/10]]; FCPrint[1, "FermionSpinSum: Done applying \
FermionSpinSum in parallel, timing: ", N[AbsoluteTime[] - 
           FeynCalc`FermionSpinSum`Private`time, 4], FCDoControl -> 
          FeynCalc`FermionSpinSum`Private`optVerbose], 
       FCPrint[1, "FermionSpinSum: Applying FermionSpinSum.", 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FeynCalc`FermionSpinSum`Private`res = 
         (FermionSpinSum[#1, FilterRules[
             {FeynCalc`FermionSpinSum`Private`opts}, Except[FCParallelize | 
               FCVerbose]]] & ) /@ FeynCalc`FermionSpinSum`Private`expr; 
        FCPrint[1, "FermionSpinSum: Done applying FermionSpinSum, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FermionSpinSum`Private`time, 4], 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]]; 
      FeynCalc`FermionSpinSum`Private`res]
 
