            FeynCalc`FermionSpinSum`Private`spChain[
             DOT[Spinor[(FeynCalc`FermionSpinSum`Private`u_.)*Momentum[
                 FeynCalc`FermionSpinSum`Private`r_, 
                 FeynCalc`FermionSpinSum`Private`d_:4], 
