                 FeynCalc`FermionSpinSum`Private`d_:4], 
               FeynCalc`FermionSpinSum`Private`Z___]]] /; 
           FreeQ[{FeynCalc`FermionSpinSum`Private`a, 
              FeynCalc`FermionSpinSum`Private`b}, Spinor] && 
            ((FeynCalc`FermionSpinSum`Private`optSpinorChainTranspose && 
              FeynCalc`FermionSpinSum`Private`moms === All) || 
             (MemberQ[FeynCalc`FermionSpinSum`Private`moms, 
               FeynCalc`FermionSpinSum`Private`p] && 
              -FeynCalc`FermionSpinSum`Private`u === 
               FeynCalc`FermionSpinSum`Private`s)) :> 
          -FeynCalc`FermionSpinSum`Private`spChain[
            DOT[Spinor[(-FeynCalc`FermionSpinSum`Private`v)*Momentum[
                FeynCalc`FermionSpinSum`Private`r, 
                FeynCalc`FermionSpinSum`Private`d], 
              FeynCalc`FermionSpinSum`Private`Z], 
             If[TrueQ[{FeynCalc`FermionSpinSum`Private`b} === {}], 
              Unevaluated[Sequence[]], FCChargeConjugateTransposed[DOT[
                FeynCalc`FermionSpinSum`Private`b], FCI -> True, 
               DotSimplify -> False, Explicit -> True]], 
             FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
              DiracGamma[Momentum[FeynCalc`FermionSpinSum`Private`p, 
                 FeynCalc`FermionSpinSum`Private`d], 
                FeynCalc`FermionSpinSum`Private`d] + 
               FeynCalc`FermionSpinSum`Private`s*
                FeynCalc`FermionSpinSum`Private`m], 
             FeynCalc`FermionSpinSum`Private`a, Spinor[
              FeynCalc`FermionSpinSum`Private`t*Momentum[
                FeynCalc`FermionSpinSum`Private`q, 
                FeynCalc`FermionSpinSum`Private`d], 
              FeynCalc`FermionSpinSum`Private`Y]]], 
         FeynCalc`FermionSpinSum`Private`spChain[
             DOT[Spinor[(FeynCalc`FermionSpinSum`Private`s_.)*Momentum[
                 FeynCalc`FermionSpinSum`Private`p_, 
                 FeynCalc`FermionSpinSum`Private`d_:4], 
               FeynCalc`FermionSpinSum`Private`Y___], 
              FeynCalc`FermionSpinSum`Private`a___, Spinor[
               (FeynCalc`FermionSpinSum`Private`t_.)*Momentum[
                 FeynCalc`FermionSpinSum`Private`q_, 
                 FeynCalc`FermionSpinSum`Private`d_:4], 
               FeynCalc`FermionSpinSum`Private`m_, ___]]]*
            FeynCalc`FermionSpinSum`Private`spChain[
             DOT[Spinor[(FeynCalc`FermionSpinSum`Private`u_.)*Momentum[
                 FeynCalc`FermionSpinSum`Private`r_, 
                 FeynCalc`FermionSpinSum`Private`d_:4], 
               FeynCalc`FermionSpinSum`Private`Z___], 
              FeynCalc`FermionSpinSum`Private`b___, Spinor[
               (FeynCalc`FermionSpinSum`Private`v_.)*Momentum[
                 FeynCalc`FermionSpinSum`Private`q_, 
                 FeynCalc`FermionSpinSum`Private`d_:4], 
               FeynCalc`FermionSpinSum`Private`m_, ___]]] /; 
           FreeQ[{FeynCalc`FermionSpinSum`Private`a, 
              FeynCalc`FermionSpinSum`Private`b}, Spinor] && 
            ((FeynCalc`FermionSpinSum`Private`optSpinorChainTranspose && 
              FeynCalc`FermionSpinSum`Private`moms === All) || 
             (MemberQ[FeynCalc`FermionSpinSum`Private`moms, 
               FeynCalc`FermionSpinSum`Private`q] && 
              -FeynCalc`FermionSpinSum`Private`v === 
               FeynCalc`FermionSpinSum`Private`t)) :> 
          -FeynCalc`FermionSpinSum`Private`spChain[
            DOT[Spinor[FeynCalc`FermionSpinSum`Private`s*Momentum[
                FeynCalc`FermionSpinSum`Private`p, 
                FeynCalc`FermionSpinSum`Private`d], 
              FeynCalc`FermionSpinSum`Private`Y], 
             FeynCalc`FermionSpinSum`Private`a, 
             FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
              DiracGamma[Momentum[FeynCalc`FermionSpinSum`Private`q, 
                 FeynCalc`FermionSpinSum`Private`d], 
                FeynCalc`FermionSpinSum`Private`d] + 
               FeynCalc`FermionSpinSum`Private`t*
                FeynCalc`FermionSpinSum`Private`m], 
             If[TrueQ[{FeynCalc`FermionSpinSum`Private`b} === {}], 
              Unevaluated[Sequence[]], FCChargeConjugateTransposed[DOT[
                FeynCalc`FermionSpinSum`Private`b], FCI -> True, 
               DotSimplify -> False, Explicit -> True]], 
             Spinor[(-FeynCalc`FermionSpinSum`Private`u)*Momentum[
                FeynCalc`FermionSpinSum`Private`r, 
                FeynCalc`FermionSpinSum`Private`d], 
              FeynCalc`FermionSpinSum`Private`Z]]], 
         FeynCalc`FermionSpinSum`Private`spChain[
            DOT[Spinor[(FeynCalc`FermionSpinSum`Private`s_.)*Momentum[
                FeynCalc`FermionSpinSum`Private`p_, 
                FeynCalc`FermionSpinSum`Private`d_:4], 
              FeynCalc`FermionSpinSum`Private`mass_, ___], 
             FeynCalc`FermionSpinSum`Private`x___, Spinor[
              (FeynCalc`FermionSpinSum`Private`s_.)*Momentum[
                FeynCalc`FermionSpinSum`Private`p_, 
                FeynCalc`FermionSpinSum`Private`d_:4], 
              FeynCalc`FermionSpinSum`Private`m_, ___]]] /; 
           FreeQ[{FeynCalc`FermionSpinSum`Private`x}, Spinor] && 
            (FeynCalc`FermionSpinSum`Private`moms === All || 
             MemberQ[FeynCalc`FermionSpinSum`Private`moms, 
              FeynCalc`FermionSpinSum`Private`p]) :> DiracTrace[
           DOT[FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
             DiracGamma[Momentum[FeynCalc`FermionSpinSum`Private`p, 
                FeynCalc`FermionSpinSum`Private`d], 
               FeynCalc`FermionSpinSum`Private`d] + 
              FeynCalc`FermionSpinSum`Private`s*
               FeynCalc`FermionSpinSum`Private`m], 
            FeynCalc`FermionSpinSum`Private`x]]}; 
      FCPrint[1, 
       "FermionSpinSum: Applying the spin sum formula done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FermionSpinSum`Private`time, 4], 
       FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
      FCPrint[3, "FermionSpinSum: After applying the spin sum formula: ", 
       FeynCalc`FermionSpinSum`Private`ex, FCDoControl -> 
        FeynCalc`FermionSpinSum`Private`optVerbose]; 
      If[ !FreeQ[FeynCalc`FermionSpinSum`Private`ex, 
         FCChargeConjugateTransposed], FeynCalc`FermionSpinSum`Private`ex = 
         FeynCalc`FermionSpinSum`Private`ex /. FCChargeConjugateTransposed[
            FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
             FeynCalc`FermionSpinSum`Private`x_], 
            FeynCalc`FermionSpinSum`Private`r___] :> 
           FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
            FCChargeConjugateTransposed[FeynCalc`FermionSpinSum`Private`x, 
             Explicit -> True, FeynCalc`FermionSpinSum`Private`r]]; 
        If[OptionValue[DotSimplify], 
         FCPrint[1, "FermionSpinSum: Applying DotSimplify to FCCCTs.", 
           FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
          FeynCalc`FermionSpinSum`Private`ex = 
           FeynCalc`FermionSpinSum`Private`ex /. FCChargeConjugateTransposed[
              FeynCalc`FermionSpinSum`Private`x_, 
              FeynCalc`FermionSpinSum`Private`r__] :> 
             FCChargeConjugateTransposed[FeynCalc`FermionSpinSum`Private`x, 
              DotSimplify -> True, Explicit -> True, 
              FeynCalc`FermionSpinSum`Private`r]; FCPrint[1, 
           "FermionSpinSum: Applying DotSimplify done, timing: ", 
           N[AbsoluteTime[] - FeynCalc`FermionSpinSum`Private`time, 4], 
           FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
          FCPrint[3, "FermionSpinSum: After DotSimplify: ", 
           FeynCalc`FermionSpinSum`Private`ex, FCDoControl -> 
            FeynCalc`FermionSpinSum`Private`optVerbose]; 
          If[ !FreeQ[FeynCalc`FermionSpinSum`Private`ex, 
             FCChargeConjugateTransposed], Message[
            FermionSpinSum::fcctleft]]]]; If[OptionValue[DotSimplify], 
       FeynCalc`FermionSpinSum`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FermionSpinSum: Applying DotSimplify.", 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FeynCalc`FermionSpinSum`Private`ex = 
         FeynCalc`FermionSpinSum`Private`ex /. 
          FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
            FeynCalc`FermionSpinSum`Private`x_] :> 
           FeynCalc`FermionSpinSum`Private`spinPolarizationSum[
            DotSimplify[FeynCalc`FermionSpinSum`Private`x, Expanding -> 
              False, FCI -> True]]; FCPrint[1, 
         "FermionSpinSum: Applying DotSimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FermionSpinSum`Private`time, 4], 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FCPrint[3, "FermionSpinSum: After DotSimplify: ", 
         FeynCalc`FermionSpinSum`Private`ex, FCDoControl -> 
          FeynCalc`FermionSpinSum`Private`optVerbose]]; 
      If[FeynCalc`FermionSpinSum`Private`optSpinPolarizationSum === 
         Identity && OptionValue[FCTraceFactor], 
       FeynCalc`FermionSpinSum`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FermionSpinSum: Applying FCTraceFactor.", 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FeynCalc`FermionSpinSum`Private`ex = 
         FeynCalc`FermionSpinSum`Private`ex /. 
          DiracTrace[FeynCalc`FermionSpinSum`Private`x_] /; 
             !FreeQ[FeynCalc`FermionSpinSum`Private`x, 
              FeynCalc`FermionSpinSum`Private`spinPolarizationSum] :> 
           FCTraceFactor[DiracTrace[FeynCalc`FermionSpinSum`Private`x /. 
              FeynCalc`FermionSpinSum`Private`spinPolarizationSum -> 
               Identity], FCI -> True]; FCPrint[1, 
         "FermionSpinSum: Applying FCTraceFactor done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FermionSpinSum`Private`time, 4], 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FCPrint[3, "FermionSpinSum: After FCTraceFactor: ", 
         FeynCalc`FermionSpinSum`Private`ex, FCDoControl -> 
          FeynCalc`FermionSpinSum`Private`optVerbose]]; 
      If[ !FreeQ[FeynCalc`FermionSpinSum`Private`ex, 
         FeynCalc`FermionSpinSum`Private`spinPolarizationSum], 
       FeynCalc`FermionSpinSum`Private`ex = 
         FeynCalc`FermionSpinSum`Private`ex /. 
          FeynCalc`FermionSpinSum`Private`spinPolarizationSum -> 
           FeynCalc`FermionSpinSum`Private`optSpinPolarizationSum; ]; 
      If[FeynCalc`FermionSpinSum`Private`moms === All && 
         !FreeQ[FeynCalc`FermionSpinSum`Private`ex, 
          FeynCalc`FermionSpinSum`Private`spChain], 
       Message[FermionSpinSum::spinorsleft]; ]; 
      FeynCalc`FermionSpinSum`Private`ex = 
       FeynCalc`FermionSpinSum`Private`ex /. 
        FeynCalc`FermionSpinSum`Private`spChain -> Identity; 
      FeynCalc`FermionSpinSum`Private`ex = 
       FRH[FeynCalc`FermionSpinSum`Private`ex, IsolateNames -> 
         FeynCalc`FermionSpinSum`Private`ssIso]; If[OptionValue[Collecting], 
       FeynCalc`FermionSpinSum`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FermionSpinSum: Collecting w.r.t DiracTrace", 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FeynCalc`FermionSpinSum`Private`ex = Collect2[
          FeynCalc`FermionSpinSum`Private`ex, DiracTrace, 
          Factoring -> OptionValue[Factoring]]; FCPrint[1, 
         "FermionSpinSum: Collecting w.r.t DiracTrace done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FermionSpinSum`Private`time, 4], 
         FCDoControl -> FeynCalc`FermionSpinSum`Private`optVerbose]; 
        FCPrint[3, "FermionSpinSum: After collecting w.r.t DiracTrace: ", 
         FeynCalc`FermionSpinSum`Private`ex, FCDoControl -> 
          FeynCalc`FermionSpinSum`Private`optVerbose]; ]; 
      FeynCalc`FermionSpinSum`Private`ex = FeynCalc`FermionSpinSum`Private`ex*
        FeynCalc`FermionSpinSum`Private`extraFactor; 
      If[OptionValue[FCE], FeynCalc`FermionSpinSum`Private`ex = 
        FCE[FeynCalc`FermionSpinSum`Private`ex]]; 
      FeynCalc`FermionSpinSum`Private`ex]
 
Options[FermionSpinSum] = {Collecting -> True, DotSimplify -> True, 
     ExtraFactor -> 1, FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCParallelize -> False, FCTraceFactor -> True, FCVerbose -> False, 
     Factoring -> Factor, Head -> Identity, Momentum -> All, 
     SpinorChainTranspose -> True}
 
FermionSpinSum /: FermionSpinSum::failmsg = "Error! FermionSpinSum \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FermionSpinSum /: FermionSpinSum::fcctleft = "Warning! The output contains \
structures wrapped into FCChargeConjugateTransposed. Those must necessarily \
be simplified before the computation of Dirac traces."
 
FermionSpinSum /: FermionSpinSum::spinorsleft = "Error! After applying \
FermionSpinSum to all spinor chains the output still contains spinors."
 
FermionSpinSum /: FermionSpinSum::usage = "FermionSpinSum[exp] converts \
products of closed spinor chains in exp into\nDirac traces. Both Dirac and \
Majorana particles are supported. It is\nunderstood, that exp represents a \
squared amplitude."
 
FeynCalc`FermionSpinSum`Private`optVerbose /: 
    FeynCalc`FermionSpinSum`Private`optVerbose::usage = ""
 
ExtraFactor /: ExtraFactor::usage = "ExtraFactor is an option for \
FermionSpinSum. The setting ExtraFactor -> fa \nmultiplies the whole \
amplitude with the factor fa before squaring."
 
SpinorChainTranspose[(FeynCalc`SpinorChainTranspose`Private`a_) == 
      (FeynCalc`SpinorChainTranspose`Private`b_), 
     FeynCalc`SpinorChainTranspose`Private`opts:OptionsPattern[]] := 
    SpinorChainTranspose[FeynCalc`SpinorChainTranspose`Private`a, 
      FeynCalc`SpinorChainTranspose`Private`opts] == 
     SpinorChainTranspose[FeynCalc`SpinorChainTranspose`Private`b, 
      FeynCalc`SpinorChainTranspose`Private`opts]
 
SpinorChainTranspose[FeynCalc`SpinorChainTranspose`Private`expr_List, 
     FeynCalc`SpinorChainTranspose`Private`opts:OptionsPattern[]] := 
    (SpinorChainTranspose[#1, 
       FeynCalc`SpinorChainTranspose`Private`opts] & ) /@ 
     FeynCalc`SpinorChainTranspose`Private`expr
 
SpinorChainTranspose[FeynCalc`SpinorChainTranspose`Private`expr_ /; 
       !MemberQ[{List, Equal}, FeynCalc`SpinorChainTranspose`Private`expr], 
     OptionsPattern[]] := Block[{FeynCalc`SpinorChainTranspose`Private`ex, 
      FeynCalc`SpinorChainTranspose`Private`tmp, 
      FeynCalc`SpinorChainTranspose`Private`dsHead, 
      FeynCalc`SpinorChainTranspose`Private`freePart, 
      FeynCalc`SpinorChainTranspose`Private`dsPart, 
      FeynCalc`SpinorChainTranspose`Private`null1, 
      FeynCalc`SpinorChainTranspose`Private`null2, 
      FeynCalc`SpinorChainTranspose`Private`time, 
      FeynCalc`SpinorChainTranspose`Private`diracObjects, 
      FeynCalc`SpinorChainTranspose`Private`diracObjectsEval, 
      FeynCalc`SpinorChainTranspose`Private`repRule, 
      FeynCalc`SpinorChainTranspose`Private`res, 
      FeynCalc`SpinorChainTranspose`Private`optHead, 
      FeynCalc`SpinorChainTranspose`Private`optSelect, 
      FeynCalc`SpinorChainTranspose`Private`chainPatterns}, 
     FeynCalc`SpinorChainTranspose`Private`optHead = OptionValue[Head]; 
      FeynCalc`SpinorChainTranspose`Private`optSelect = 
       FCI[OptionValue[Select]]; 
      If[ !MatchQ[FeynCalc`SpinorChainTranspose`Private`optSelect, 
         {{Spinor[__], Spinor[__]}..}], 
       Message[SpinorChainTranspose::failmsg, 
         "The value of the Select option is not a valid list of filters."]; 
        Abort[]]; FeynCalc`SpinorChainTranspose`Private`chainPatterns = 
       (FeynCalc`SpinorChainTranspose`Private`holdDOT[#1[[1]], ___, 
          #1[[2]]] & ) /@ FeynCalc`SpinorChainTranspose`Private`optSelect; 
      If[Length[FeynCalc`SpinorChainTranspose`Private`chainPatterns] === 1, 
       FeynCalc`SpinorChainTranspose`Private`chainPatterns = 
        First[FeynCalc`SpinorChainTranspose`Private`chainPatterns], 
       FeynCalc`SpinorChainTranspose`Private`chainPatterns = 
        Alternatives @@ FeynCalc`SpinorChainTranspose`Private`chainPatterns]; 
      If[OptionValue[FCI], FeynCalc`SpinorChainTranspose`Private`ex = 
        FeynCalc`SpinorChainTranspose`Private`expr, 
       FeynCalc`SpinorChainTranspose`Private`ex = 
        FCI[FeynCalc`SpinorChainTranspose`Private`expr]]; 
      If[FreeQ[FeynCalc`SpinorChainTranspose`Private`ex, Spinor], 
       Return[FeynCalc`SpinorChainTranspose`Private`ex]]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`SpinorChainTranspose`Private`sctrVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`SpinorChainTranspose`Private`sctrVerbose = 
          OptionValue[FCVerbose]]; ]; FCPrint[1, 
       "SpinorChainTranspose. Entering.", FCDoControl -> 
        FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FCPrint[3, "SpinorChainTranspose: Entering with ", 
       FeynCalc`SpinorChainTranspose`Private`ex, FCDoControl -> 
        FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      If[ !FreeQ[FeynCalc`SpinorChainTranspose`Private`ex, DiracChain], 
       FeynCalc`SpinorChainTranspose`Private`ex = 
        FeynCalc`SpinorChainTranspose`Private`ex //. 
         DiracChain[FeynCalc`SpinorChainTranspose`Private`x___, 
           FeynCalc`SpinorChainTranspose`Private`a_Spinor, 
           FeynCalc`SpinorChainTranspose`Private`b_Spinor] :> 
          DOT[FeynCalc`SpinorChainTranspose`Private`a, 
           FeynCalc`SpinorChainTranspose`Private`x, 
           FeynCalc`SpinorChainTranspose`Private`b]]; 
      If[MatchQ[FeynCalc`SpinorChainTranspose`Private`ex /. 
         DOT -> FeynCalc`SpinorChainTranspose`Private`holdDOT, 
        FeynCalc`SpinorChainTranspose`Private`holdDOT[
          FeynCalc`SpinorChainTranspose`Private`a_Spinor, 
          FeynCalc`SpinorChainTranspose`Private`b___, 
          FeynCalc`SpinorChainTranspose`Private`c_Spinor] /; 
         FreeQ[{FeynCalc`SpinorChainTranspose`Private`b}, Spinor]], 
       FCPrint[1, "SpinorChainTranspose: Recognized standalone expression.", 
         FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
        FeynCalc`SpinorChainTranspose`Private`tmp = 
         FeynCalc`SpinorChainTranspose`Private`dsHead[
          FeynCalc`SpinorChainTranspose`Private`ex]; 
        FeynCalc`SpinorChainTranspose`Private`tmp = 
         FeynCalc`SpinorChainTranspose`Private`tmp /. 
          {FeynCalc`SpinorChainTranspose`Private`dsHead[
              DOT[FeynCalc`SpinorChainTranspose`Private`a_Spinor, 
               FeynCalc`SpinorChainTranspose`Private`b___, 
               FeynCalc`SpinorChainTranspose`Private`c_Spinor]] /; 
              !MatchQ[FeynCalc`SpinorChainTranspose`Private`holdDOT[
                FeynCalc`SpinorChainTranspose`Private`a, 
                FeynCalc`SpinorChainTranspose`Private`b, 
                FeynCalc`SpinorChainTranspose`Private`c], 
               FeynCalc`SpinorChainTranspose`Private`chainPatterns] :> 
            DOT[FeynCalc`SpinorChainTranspose`Private`a, 
             FeynCalc`SpinorChainTranspose`Private`b, 
             FeynCalc`SpinorChainTranspose`Private`c]}, 
       FCPrint[1, "SpinorChainTranspose: Isolating spinor chains.", 
         FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
        FeynCalc`SpinorChainTranspose`Private`time = AbsoluteTime[]; 
        FeynCalc`SpinorChainTranspose`Private`tmp = FCDiracIsolate[
          FeynCalc`SpinorChainTranspose`Private`ex, FCI -> True, 
          Head -> FeynCalc`SpinorChainTranspose`Private`dsHead, 
          Spinor -> True, Collecting -> OptionValue[Collecting], 
          DiracGamma -> False, Factoring -> OptionValue[Factoring], 
          TimeConstrained -> OptionValue[TimeConstrained]]; 
        FCPrint[1, 
         "SpinorChainTranspose: Done isolating spinor chains, timing: ", 
         N[AbsoluteTime[] - FeynCalc`SpinorChainTranspose`Private`time, 4], 
         FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
        FCPrint[3, "SpinorChainTranspose: After FCDiracIsolate ", 
         FeynCalc`SpinorChainTranspose`Private`tmp, FCDoControl -> 
          FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
        FeynCalc`SpinorChainTranspose`Private`tmp = 
         FeynCalc`SpinorChainTranspose`Private`tmp /. 
          {FeynCalc`SpinorChainTranspose`Private`dsHead[
              DOT[FeynCalc`SpinorChainTranspose`Private`a_Spinor, 
               FeynCalc`SpinorChainTranspose`Private`b___, 
               FeynCalc`SpinorChainTranspose`Private`c_Spinor]] /; 
              !MatchQ[FeynCalc`SpinorChainTranspose`Private`holdDOT[
                FeynCalc`SpinorChainTranspose`Private`a, 
                FeynCalc`SpinorChainTranspose`Private`b, 
                FeynCalc`SpinorChainTranspose`Private`c], 
               FeynCalc`SpinorChainTranspose`Private`chainPatterns] :> 
            DOT[FeynCalc`SpinorChainTranspose`Private`a, 
             FeynCalc`SpinorChainTranspose`Private`b, 
             FeynCalc`SpinorChainTranspose`Private`c]}; ]; 
      FeynCalc`SpinorChainTranspose`Private`diracObjects = 
       DeleteDuplicates[Sort[Cases[
          FeynCalc`SpinorChainTranspose`Private`tmp + 
           FeynCalc`SpinorChainTranspose`Private`null1 + 
           FeynCalc`SpinorChainTranspose`Private`null2, 
          FeynCalc`SpinorChainTranspose`Private`dsHead[_], Infinity]]]; 
      FCPrint[3, "SpinorChainTranspose: diracObjects: ", 
       FeynCalc`SpinorChainTranspose`Private`diracObjects, 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FeynCalc`SpinorChainTranspose`Private`time = AbsoluteTime[]; 
      FCPrint[1, "SpinorChainTranspose: Checking the spinor syntax.", 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      If[FeynCalc`Package`spinorSyntaxCorrectQ[
         FeynCalc`SpinorChainTranspose`Private`diracObjects] =!= True, 
       Message[SpinorChainTranspose::failmsg, 
         "The input contains Spinor objects with incorrect syntax."]; 
        Abort[]]; FCPrint[1, "SpinorChainTranspose: Checks done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`SpinorChainTranspose`Private`time, 4], 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FCPrint[1, "SpinorChainTranspose: Trasnposing spinor chains.", 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FeynCalc`SpinorChainTranspose`Private`time = AbsoluteTime[]; 
      FeynCalc`SpinorChainTranspose`Private`diracObjectsEval = 
       FeynCalc`SpinorChainTranspose`Private`diracObjects /. 
           FeynCalc`SpinorChainTranspose`Private`dsHead -> Identity /. 
          DOT -> FeynCalc`SpinorChainTranspose`Private`holdDOT /. 
         {FeynCalc`SpinorChainTranspose`Private`holdDOT[
            Spinor[FeynCalc`SpinorChainTranspose`Private`p1_, 
             FeynCalc`SpinorChainTranspose`Private`r1__], 
            FeynCalc`SpinorChainTranspose`Private`b___, 
            Spinor[FeynCalc`SpinorChainTranspose`Private`p2_, 
             FeynCalc`SpinorChainTranspose`Private`r2__]] :> 
           -FeynCalc`SpinorChainTranspose`Private`optHead[
             DOT[Spinor[-FeynCalc`SpinorChainTranspose`Private`p2, 
               FeynCalc`SpinorChainTranspose`Private`r2], 
              FCChargeConjugateTransposed[DOT[
                 FeynCalc`SpinorChainTranspose`Private`b] /. 
                FeynCalc`SpinorChainTranspose`Private`holdDOT -> DOT, FCI -> 
                True, Explicit -> True, DotSimplify -> False], 
              Spinor[-FeynCalc`SpinorChainTranspose`Private`p1, 
               FeynCalc`SpinorChainTranspose`Private`r1]]]} /. 
        FeynCalc`SpinorChainTranspose`Private`holdDOT -> DOT; 
      FCPrint[1, 
       "SpinorChainTranspose: Done transposing spinor chains, timing: ", 
       N[AbsoluteTime[] - FeynCalc`SpinorChainTranspose`Private`time, 4], 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FCPrint[3, "SpinorChainTranspose: diracObjectsEval: ", 
       FeynCalc`SpinorChainTranspose`Private`diracObjectsEval, 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      If[OptionValue[DotSimplify], 
       FeynCalc`SpinorChainTranspose`Private`diracObjectsEval = 
        (DotSimplify[#1, FCI -> True, Expanding -> False] & ) /@ 
         FeynCalc`SpinorChainTranspose`Private`diracObjectsEval]; 
      FCPrint[1, "SpinorChainTranspose: Inserting Dirac objects back.", 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FeynCalc`SpinorChainTranspose`Private`time = AbsoluteTime[]; 
      FeynCalc`SpinorChainTranspose`Private`repRule = 
       Thread[FeynCalc`SpinorChainTranspose`Private`diracObjects -> 
         FeynCalc`SpinorChainTranspose`Private`diracObjectsEval]; 
      FCPrint[3, "SpinorChainTranspose: repRule: ", 
       FeynCalc`SpinorChainTranspose`Private`repRule, 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FeynCalc`SpinorChainTranspose`Private`res = 
       FeynCalc`SpinorChainTranspose`Private`tmp /. 
        Dispatch[FeynCalc`SpinorChainTranspose`Private`repRule]; 
      FCPrint[1, 
       "SpinorChainTranspose: Done inserting Dirac objects back, timing: ", 
       N[AbsoluteTime[] - FeynCalc`SpinorChainTranspose`Private`time, 4], 
       FCDoControl -> FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      If[OptionValue[FCE], FeynCalc`SpinorChainTranspose`Private`res = 
        FCE[FeynCalc`SpinorChainTranspose`Private`res]]; 
      FCPrint[1, "SpinorChainTranspose: Leaving.", FCDoControl -> 
        FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FCPrint[3, "SpinorChainTranspose: Leaving with ", 
       FeynCalc`SpinorChainTranspose`Private`res, FCDoControl -> 
        FeynCalc`SpinorChainTranspose`Private`sctrVerbose]; 
      FeynCalc`SpinorChainTranspose`Private`res]
 
Options[SpinorChainTranspose] = {Collecting -> True, DotSimplify -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCVerbose -> False, Factoring -> Factor, Head -> Identity, 
     Select -> {{SpinorVBar[_, _], SpinorU[_, _]}, {SpinorVBar[_, _], 
        SpinorV[_, _]}, {SpinorVBarD[_, _], SpinorUD[_, _]}, 
       {SpinorVBarD[_, _], SpinorVD[_, _]}}, TimeConstrained -> 3}
 
SpinorChainTranspose /: SpinorChainTranspose::failmsg = "Error! \
SpinorChainTranspose has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
SpinorChainTranspose /: SpinorChainTranspose::usage = "SpinorChainTranspose[e\
xp] transposes particular spinor chains in exp, which\neffectively switches \
the $u$ and $v$ spinors and reverses the order of the\nDirac matrices using \
charge conjugation operator. This operation is often\nrequired in \
calculations that involve Majorana particles. By default, the\nfunction will \
tranpose all chains of the form $\\bar{v}.x.u$ and $\\bar{v}.x.v$.\nA \
different or more fine grained choice can be obtained via the option Select."
 
FeynCalc`SpinorChainTranspose`Private`holdDOT /: 
    FeynCalc`SpinorChainTranspose`Private`holdDOT::usage = ""
 
FeynCalc`SpinorChainTranspose`Private`sctrVerbose /: 
    FeynCalc`SpinorChainTranspose`Private`sctrVerbose::usage = ""
 
FeynCalc`ComplexConjugate`Private`diracChainCC[DiracGamma[5]] := 
    -DiracGamma[5]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[DiracGamma[6]] := DiracGamma[7]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[DiracGamma[7]] := DiracGamma[6]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     (FeynCalc`ComplexConjugate`Private`ex1_DiracChain)*
      (FeynCalc`ComplexConjugate`Private`ex2_)] := 
    FeynCalc`ComplexConjugate`Private`diracChainCC[
      FeynCalc`ComplexConjugate`Private`ex1]*
     FeynCalc`ComplexConjugate`Private`diracChainCC[
      FeynCalc`ComplexConjugate`Private`ex2]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     DiracGamma[FeynCalc`ComplexConjugate`Private`arg_, 
      FeynCalc`ComplexConjugate`Private`dim___]] := 
    DiracGamma[FeynCalc`ComplexConjugate`Private`arg, 
      FeynCalc`ComplexConjugate`Private`dim] /; 
      !MemberQ[{5, 6, 7}, FeynCalc`ComplexConjugate`Private`arg]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[DiracGamma[__]^_] := 
    (Message[FermionSpinSum::failmsg, "A valid Dirac chain may not contain \
Dirac matrices raised to a power without a Dot."]; Abort[])
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     Spinor[FeynCalc`ComplexConjugate`Private`arg__]] := 
    Spinor[FeynCalc`ComplexConjugate`Private`arg]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     FeynCalc`ComplexConjugate`Private`ex_ /; 
      MemberQ[{FeynCalc`ComplexConjugate`Private`holdDOT, FCCCT}, 
       Head[FeynCalc`ComplexConjugate`Private`ex]]] := 
    Block[{FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`ex, 
       FeynCalc`ComplexConjugate`Private`diracGammaHold}, 
      If[ !FreeQ[FeynCalc`ComplexConjugate`Private`res, Eps], 
        FeynCalc`ComplexConjugate`Private`res = 
         FeynCalc`ComplexConjugate`Private`res /. 
          FeynCalc`ComplexConjugate`Private`a_Eps :> 
           (Conjugate[$LeviCivitaSign]/$LeviCivitaSign)*
            FeynCalc`ComplexConjugate`Private`a]; 
       If[ !FreeQ[FeynCalc`ComplexConjugate`Private`res, 
          FCChargeConjugateTransposed], 
        FeynCalc`ComplexConjugate`Private`res = 
         FeynCalc`ComplexConjugate`Private`res /. 
          FCChargeConjugateTransposed[FeynCalc`ComplexConjugate`Private`z_, 
            FeynCalc`ComplexConjugate`Private`opts:OptionsPattern[]] :> 
           (FeynCalc`ComplexConjugate`Private`z /. 
             DiracGamma[FeynCalc`ComplexConjugate`Private`a__] :> 
              -FeynCalc`ComplexConjugate`Private`diracGammaHold[
                FeynCalc`ComplexConjugate`Private`a] /. 
            FeynCalc`ComplexConjugate`Private`holdDOT -> 
             FeynCalc`ComplexConjugate`Private`holdDOTReversed)]; 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
           {DiracGamma[5] -> -FeynCalc`ComplexConjugate`Private`diracGammaHol\
d[5], DiracGamma[6] -> FeynCalc`ComplexConjugate`Private`diracGammaHold[7], 
            DiracGamma[7] -> FeynCalc`ComplexConjugate`Private`diracGammaHold[
              6]} /. DiracGamma[FeynCalc`ComplexConjugate`Private`a__] :> 
           FeynCalc`ComplexConjugate`Private`diracGammaHold[
            FeynCalc`ComplexConjugate`Private`a] /. 
         FeynCalc`ComplexConjugate`Private`holdDOT -> 
          FeynCalc`ComplexConjugate`Private`reverseDOT; 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
         Complex[FeynCalc`ComplexConjugate`Private`a_, 
           FeynCalc`ComplexConjugate`Private`b_] :> 
          Complex[FeynCalc`ComplexConjugate`Private`a, 
           -FeynCalc`ComplexConjugate`Private`b]; 
       FeynCalc`ComplexConjugate`Private`res] /; 
     FreeQ[FeynCalc`ComplexConjugate`Private`ex, DiracChain]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     DiracChain[FeynCalc`ComplexConjugate`Private`a_, 
      FeynCalc`ComplexConjugate`Private`i_, 
      FeynCalc`ComplexConjugate`Private`j_]] := 
    DiracChain[FeynCalc`ComplexConjugate`Private`diracChainCC[
        FeynCalc`ComplexConjugate`Private`a] /. 
       FeynCalc`ComplexConjugate`Private`diracGammaHold -> DiracGamma /. 
      FeynCalc`ComplexConjugate`Private`holdDOTReversed -> DOT, 
     FeynCalc`ComplexConjugate`Private`j, FeynCalc`ComplexConjugate`Private`i]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     DiracChain[FeynCalc`ComplexConjugate`Private`a_Spinor, 
      FeynCalc`ComplexConjugate`Private`i_]] := 
    DiracChain[FeynCalc`ComplexConjugate`Private`a, 
     FeynCalc`ComplexConjugate`Private`i]
 
FeynCalc`ComplexConjugate`Private`diracChainCC[
     DiracChain[FeynCalc`ComplexConjugate`Private`i_, 
      FeynCalc`ComplexConjugate`Private`a_Spinor]] := 
    DiracChain[FeynCalc`ComplexConjugate`Private`i, 
     FeynCalc`ComplexConjugate`Private`a]
 
FeynCalc`ComplexConjugate`Private`holdDOT /: 
    FeynCalc`ComplexConjugate`Private`holdDOT::usage = ""
 
FCCCT = FCChargeConjugateTransposed
 
FCCCT /: FCCCT::usage = "FCCCT is an alias for FCChargeConjugateTransposed."
 
FeynCalc`ComplexConjugate`Private`holdDOTReversed /: 
    FeynCalc`ComplexConjugate`Private`holdDOTReversed::usage = ""
 
FeynCalc`ComplexConjugate`Private`reverseDOT[
     FeynCalc`ComplexConjugate`Private`x__] := 
    MemSet[FeynCalc`ComplexConjugate`Private`reverseDOT[
      FeynCalc`ComplexConjugate`Private`x], 
     FeynCalc`ComplexConjugate`Private`holdDOTReversed @@ 
      Reverse[{FeynCalc`ComplexConjugate`Private`x}]]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     (FeynCalc`ComplexConjugate`Private`ex1_PauliChain)*
      (FeynCalc`ComplexConjugate`Private`ex2_)] := 
    FeynCalc`ComplexConjugate`Private`pauliChainCC[
      FeynCalc`ComplexConjugate`Private`ex1]*
     FeynCalc`ComplexConjugate`Private`pauliChainCC[
      FeynCalc`ComplexConjugate`Private`ex2]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     PauliSigma[FeynCalc`ComplexConjugate`Private`arg__]] := 
    PauliSigma[FeynCalc`ComplexConjugate`Private`arg]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[PauliSigma[__]^_] := 
    (Message[FermionSpinSum::failmsg, "A valid Pauli chain may not contain \
Pauli matrices raised to a power without a Dot."]; Abort[])
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     PauliXi[Complex[0, FeynCalc`ComplexConjugate`Private`arg_]]] := 
    PauliXi[Complex[0, -FeynCalc`ComplexConjugate`Private`arg]]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     PauliEta[Complex[0, FeynCalc`ComplexConjugate`Private`arg_]]] := 
    PauliEta[Complex[0, -FeynCalc`ComplexConjugate`Private`arg]]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     PauliEtaC[Complex[0, FeynCalc`ComplexConjugate`Private`arg_]]] := 
    PauliEtaC[Complex[0, -FeynCalc`ComplexConjugate`Private`arg]]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     FeynCalc`ComplexConjugate`Private`ex_FeynCalc`ComplexConjugate`Private`h\
oldDOT] := Block[{FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`ex, 
       FeynCalc`ComplexConjugate`Private`pauliSigmaHold}, 
      If[ !FreeQ[FeynCalc`ComplexConjugate`Private`res, Eps], 
        FeynCalc`ComplexConjugate`Private`res = 
         FeynCalc`ComplexConjugate`Private`res /. 
          FeynCalc`ComplexConjugate`Private`a_Eps :> 
           (Conjugate[$LeviCivitaSign]/$LeviCivitaSign)*
            FeynCalc`ComplexConjugate`Private`a]; 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
         FeynCalc`ComplexConjugate`Private`holdDOT -> 
          FeynCalc`ComplexConjugate`Private`reverseDOT; 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
         Complex[FeynCalc`ComplexConjugate`Private`a_, 
           FeynCalc`ComplexConjugate`Private`b_] :> 
          Complex[FeynCalc`ComplexConjugate`Private`a, 
           -FeynCalc`ComplexConjugate`Private`b]; 
       FeynCalc`ComplexConjugate`Private`res] /; 
     FreeQ[FeynCalc`ComplexConjugate`Private`ex, PauliChain]
 
FeynCalc`ComplexConjugate`Private`pauliChainCC[
     PauliChain[FeynCalc`ComplexConjugate`Private`a_, 
      FeynCalc`ComplexConjugate`Private`i_, 
      FeynCalc`ComplexConjugate`Private`j_]] := 
    PauliChain[FeynCalc`ComplexConjugate`Private`pauliChainCC[
        FeynCalc`ComplexConjugate`Private`a] /. 
       FeynCalc`ComplexConjugate`Private`pauliSigmaHold -> PauliSigma /. 
      FeynCalc`ComplexConjugate`Private`holdDOTReversed -> DOT, 
     FeynCalc`ComplexConjugate`Private`j, FeynCalc`ComplexConjugate`Private`i]
 
FeynCalc`ComplexConjugate`Private`sunChainCC[
     FeynCalc`ComplexConjugate`Private`ex:Except[_Plus | _Times]] := 
    Block[{FeynCalc`ComplexConjugate`Private`res = 
       FeynCalc`ComplexConjugate`Private`ex}, 
     If[ !FreeQ[FeynCalc`ComplexConjugate`Private`res, SUNTF], 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
         SUNTF -> FeynCalc`ComplexConjugate`Private`reverseSUNTF]; 
      If[ !FreeQ[FeynCalc`ComplexConjugate`Private`res, 
         FeynCalc`ComplexConjugate`Private`holdDOT], 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
         FeynCalc`ComplexConjugate`Private`holdDOT -> 
          FeynCalc`ComplexConjugate`Private`reverseDOT]; 
      FeynCalc`ComplexConjugate`Private`res = 
       FeynCalc`ComplexConjugate`Private`res /. 
        Complex[FeynCalc`ComplexConjugate`Private`a_, 
          FeynCalc`ComplexConjugate`Private`b_] :> 
         Complex[FeynCalc`ComplexConjugate`Private`a, 
          -FeynCalc`ComplexConjugate`Private`b]; 
      FeynCalc`ComplexConjugate`Private`res]
 
FeynCalc`ComplexConjugate`Private`sunChainCC[
     FeynCalc`ComplexConjugate`Private`ex_Plus] := 
    FeynCalc`ComplexConjugate`Private`sunChainCC /@ 
     FeynCalc`ComplexConjugate`Private`ex
 
FeynCalc`ComplexConjugate`Private`sunChainCC[
     FeynCalc`ComplexConjugate`Private`ex_Times] := 
    FeynCalc`ComplexConjugate`Private`sunChainCC /@ 
     FeynCalc`ComplexConjugate`Private`ex
 
FeynCalc`ComplexConjugate`Private`reverseSUNTF[
     {FeynCalc`ComplexConjugate`Private`a__}, 
     FeynCalc`ComplexConjugate`Private`b_, 
     FeynCalc`ComplexConjugate`Private`c_] := 
    MemSet[FeynCalc`ComplexConjugate`Private`reverseSUNTF[
      {FeynCalc`ComplexConjugate`Private`a}, 
      FeynCalc`ComplexConjugate`Private`b, 
      FeynCalc`ComplexConjugate`Private`c], 
     SUNTF[Reverse[{FeynCalc`ComplexConjugate`Private`a}], 
      FeynCalc`ComplexConjugate`Private`c, 
      FeynCalc`ComplexConjugate`Private`b]]
 
FeynCalc`ComplexConjugate`Private`prefCC[FeynCalc`ComplexConjugate`Private`ex:
      Except[_Plus | _Times]] := 
    Block[{FeynCalc`ComplexConjugate`Private`res = 
       FeynCalc`ComplexConjugate`Private`ex, 
      FeynCalc`ComplexConjugate`Private`pauliSigmaHold}, 
     If[ !FreeQ[FeynCalc`ComplexConjugate`Private`res, Eps], 
       FeynCalc`ComplexConjugate`Private`res = 
        FeynCalc`ComplexConjugate`Private`res /. 
         FeynCalc`ComplexConjugate`Private`a_Eps :> 
          (Conjugate[$LeviCivitaSign]/$LeviCivitaSign)*
           FeynCalc`ComplexConjugate`Private`a]; 
      FeynCalc`ComplexConjugate`Private`res = 
       FeynCalc`ComplexConjugate`Private`res /. 
        Complex[FeynCalc`ComplexConjugate`Private`a_, 
          FeynCalc`ComplexConjugate`Private`b_] :> 
         Complex[FeynCalc`ComplexConjugate`Private`a, 
          -FeynCalc`ComplexConjugate`Private`b]; 
      FeynCalc`ComplexConjugate`Private`res]
 
FeynCalc`ComplexConjugate`Private`prefCC[
     FeynCalc`ComplexConjugate`Private`ex_Plus] := 
    FeynCalc`ComplexConjugate`Private`prefCC /@ 
     FeynCalc`ComplexConjugate`Private`ex
 
FeynCalc`ComplexConjugate`Private`prefCC[
     FeynCalc`ComplexConjugate`Private`ex_Times] := 
    FeynCalc`ComplexConjugate`Private`prefCC /@ 
     FeynCalc`ComplexConjugate`Private`ex
 
FCRenameDummyIndices[FeynCalc`FCRenameDummyIndices`Private`expr_List, 
     FeynCalc`FCRenameDummyIndices`Private`opts:OptionsPattern[]] := 
    (FCRenameDummyIndices[#1, 
       FeynCalc`FCRenameDummyIndices`Private`opts] & ) /@ 
     FeynCalc`FCRenameDummyIndices`Private`expr
 
FCRenameDummyIndices[FeynCalc`FCRenameDummyIndices`Private`expr_, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCRenameDummyIndices`Private`indexList = {}, 
      FeynCalc`FCRenameDummyIndices`Private`replacementList, 
      FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
      FeynCalc`FCRenameDummyIndices`Private`ex, 
      FeynCalc`FCRenameDummyIndices`Private`res, 
      FeynCalc`FCRenameDummyIndices`Private`heads, 
      FeynCalc`FCRenameDummyIndices`Private`patt, 
      FeynCalc`FCRenameDummyIndices`Private`optExpanding, 
      FeynCalc`FCRenameDummyIndices`Private`time}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCRenameDummyIndices`Private`rdiVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCRenameDummyIndices`Private`rdiVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCRenameDummyIndices`Private`heads = OptionValue[Head]; 
      FeynCalc`FCRenameDummyIndices`Private`optExpanding = 
       OptionValue[Expanding]; If[ !OptionValue[FCI], 
       FeynCalc`FCRenameDummyIndices`Private`exprFCI = 
        FCI[FeynCalc`FCRenameDummyIndices`Private`expr], 
       FeynCalc`FCRenameDummyIndices`Private`exprFCI = 
        FeynCalc`FCRenameDummyIndices`Private`expr]; 
      FCPrint[1, "FCRenameDummyIndices: Entering.", 
       FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
      FCPrint[3, "FCRenameDummyIndices: Entering with ", 
       FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
       FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
      If[DummyIndexFreeQ[FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
        FeynCalc`FCRenameDummyIndices`Private`heads], 
       FCPrint[1, 
         "FCRenameDummyIndices: No relevant dummy indices found, leaving.", 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
        Return[FeynCalc`FCRenameDummyIndices`Private`exprFCI]]; 
      FeynCalc`FCRenameDummyIndices`Private`ex = 
       FeynCalc`FCRenameDummyIndices`Private`exprFCI; 
      If[OptionValue[DotSimplify], 
       FeynCalc`FCRenameDummyIndices`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCRenameDummyIndices: Applying DotSimplify.", 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
        FeynCalc`FCRenameDummyIndices`Private`exprFCI = 
         DotSimplify[FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
          FCI -> True, Expanding -> 
           FeynCalc`FCRenameDummyIndices`Private`optExpanding]; 
        FCPrint[1, "FCRenameDummyIndices: DotSimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCRenameDummyIndices`Private`time, 4], 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
        FCPrint[3, "FCRenameDummyIndices: After FCColorIsolate: ", 
         FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; ]; 
      If[FeynCalc`FCRenameDummyIndices`Private`optExpanding, 
       FeynCalc`FCRenameDummyIndices`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCRenameDummyIndices: Applying Expand.", 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
        FeynCalc`FCRenameDummyIndices`Private`exprFCI = 
         Expand[FeynCalc`FCRenameDummyIndices`Private`exprFCI]; 
        FCPrint[1, "FCRenameDummyIndices: Expand done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCRenameDummyIndices`Private`time, 4], 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
        FCPrint[3, "FCRenameDummyIndices: After Expand: ", 
         FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
         FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; ]; 
      If[Head[FeynCalc`FCRenameDummyIndices`Private`heads] =!= List || 
        FeynCalc`FCRenameDummyIndices`Private`heads === {}, 
       Message[FCRenameDummyIndices::failmsg, 
         "You did not specify which index heads should be renamed."]; 
        Abort[]]; If[Length[FeynCalc`FCRenameDummyIndices`Private`heads] > 1, 
       FeynCalc`FCRenameDummyIndices`Private`patt = Alternatives @@ 
         FeynCalc`FCRenameDummyIndices`Private`heads, 
       FeynCalc`FCRenameDummyIndices`Private`patt = 
        Identity @@ FeynCalc`FCRenameDummyIndices`Private`heads]; 
      If[Head[FeynCalc`FCRenameDummyIndices`Private`exprFCI] === Plus, 
       FeynCalc`FCRenameDummyIndices`Private`indexList = 
        Union[(Flatten[#1, 1] & )[Tally /@ 
           (Cases[#1, FeynCalc`FCRenameDummyIndices`Private`patt[
                FeynCalc`FCRenameDummyIndices`Private`ind_, ___] :> 
               FeynCalc`FCRenameDummyIndices`Private`ind, Infinity] & ) /@ 
            List @@ FeynCalc`FCRenameDummyIndices`Private`exprFCI]], 
       FeynCalc`FCRenameDummyIndices`Private`indexList = 
         Tally[Cases[FeynCalc`FCRenameDummyIndices`Private`exprFCI, 
           FeynCalc`FCRenameDummyIndices`Private`patt[
             FeynCalc`FCRenameDummyIndices`Private`ind_, ___] :> 
            FeynCalc`FCRenameDummyIndices`Private`ind, Infinity]]; ]; 
      FCPrint[1, "FCRenameDummyIndices: List of indices to be randomized: ", 
       StandardForm[FeynCalc`FCRenameDummyIndices`Private`indexList], 
       FCDoControl -> FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
      If[Select[FeynCalc`FCRenameDummyIndices`Private`indexList, 
         #1[[2]] > 2 & ] =!= {}, Message[FCRenameDummyIndices::failmsg, "The \
input expression violates Einstein summation. Some dummy indices appear more \
than twice."]; Abort[]]; 
      FeynCalc`FCRenameDummyIndices`Private`replacementList = 
       ((FeynCalc`FCRenameDummyIndices`Private`h:
            FeynCalc`FCRenameDummyIndices`Private`patt)[#1[[1]], 
           FeynCalc`FCRenameDummyIndices`Private`di___] -> 
          FeynCalc`FCRenameDummyIndices`Private`h[$AL[Unique[]], 
           FeynCalc`FCRenameDummyIndices`Private`di] & ) /@ 
        Cases[FeynCalc`FCRenameDummyIndices`Private`indexList, {_, 2}]; 
      FCPrint[2, "FCRenameDummyIndices: List of replacement rules: ", 
       FeynCalc`FCRenameDummyIndices`Private`replacementList]; 
      FeynCalc`FCRenameDummyIndices`Private`res = 
       FeynCalc`FCRenameDummyIndices`Private`ex //. 
        FeynCalc`FCRenameDummyIndices`Private`replacementList; 
      If[OptionValue[FCE], FeynCalc`FCRenameDummyIndices`Private`res = 
        FCE[FeynCalc`FCRenameDummyIndices`Private`res]]; 
      FCPrint[1, "FCRenameDummyIndices: Leaving.", FCDoControl -> 
        FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
      FCPrint[3, "FCRenameDummyIndices: Leaving with ", 
       FeynCalc`FCRenameDummyIndices`Private`res, FCDoControl -> 
        FeynCalc`FCRenameDummyIndices`Private`rdiVerbose]; 
      FeynCalc`FCRenameDummyIndices`Private`res]
 
Options[FCRenameDummyIndices] = {DotSimplify -> True, Expanding -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     Head -> {LorentzIndex, CartesianIndex, SUNIndex, SUNFIndex, PauliIndex, 
       DiracIndex}, FCVerbose -> False}
 
FCRenameDummyIndices /: FCRenameDummyIndices::failmsg = "Error! \
FCRenameDummyIndices has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCRenameDummyIndices /: FCRenameDummyIndices::usage = "FCRenameDummyIndices[e\
xpr] identifies dummy indices and changes their names\npairwise to random \
symbols. This can be useful if you have an expression that\ncontains dummy \
indices and want to compute the square of it. For example, the\nsquare of \
GA[a, l, a] equals $16$. However, if you forget to rename the dummy\nindices \
and compute GA[a, l, a, a, l, a] instead of GA[a, l, a, b, l, b], you\nwill \
get $64$.\n\nNotice that this routine does not perform any canonicalization. \
Use\nFCCanonicalizeDummyIndices for  that."
 
FeynCalc`FCRenameDummyIndices`Private`rdiVerbose /: 
    FeynCalc`FCRenameDummyIndices`Private`rdiVerbose::usage = ""
 
DummyIndexFreeQ[FeynCalc`DummyIndexFreeQ`Private`expr_, 
     FeynCalc`DummyIndexFreeQ`Private`heads_List] := 
    True /; FreeQ2[FeynCalc`DummyIndexFreeQ`Private`expr, 
      FeynCalc`DummyIndexFreeQ`Private`heads]
 
DummyIndexFreeQ[FeynCalc`DummyIndexFreeQ`Private`expr_, 
     FeynCalc`DummyIndexFreeQ`Private`heads_List] := 
    FCGetDummyIndices[FeynCalc`DummyIndexFreeQ`Private`expr, 
       FeynCalc`DummyIndexFreeQ`Private`heads] === {} /; 
      !FreeQ2[FeynCalc`DummyIndexFreeQ`Private`expr, 
       FeynCalc`DummyIndexFreeQ`Private`heads]
 
DummyIndexFreeQ /: DummyIndexFreeQ::usage = "DummyIndexFreeQ[exp, {head1, \
head2, ...}] returns True if the expression\ncontains dummy indices with \
heads head1, head2, ... and False otherwise.\n\nAs always in FeynCalc, \
Einstein summation convention is implicitly assumed.\n\nThe function is \
optimized for large expressions, i.e. it is not so good as a\ncriterion in \
e.g. Select."
 
FCGetDummyIndices[FeynCalc`FCGetDummyIndices`Private`expr_, 
     FeynCalc`FCGetDummyIndices`Private`heads_List, 
     FeynCalc`FCGetDummyIndices`Private`opts:OptionsPattern[]] := 
    FCGetFreeIndices[FeynCalc`FCGetDummyIndices`Private`expr, 
     FeynCalc`FCGetDummyIndices`Private`heads, Inverse -> True, 
     FeynCalc`FCGetDummyIndices`Private`opts]
 
Options[FCGetDummyIndices] = {}
 
FCGetDummyIndices /: FCGetDummyIndices::usage = "FCGetDummyIndices[exp, \
{head1, head2, ...}] returns the list of dummy indices\nfrom heads head1, \
head2, ...\n\nAs always in FeynCalc, Einstein summation convention is \
implicitly assumed."
 
FCGetFreeIndices[_, {}, OptionsPattern[]] := {}
 
FCGetFreeIndices[FeynCalc`FCGetFreeIndices`Private`expr_, 
     FeynCalc`FCGetFreeIndices`Private`heads_List /; 
      FeynCalc`FCGetFreeIndices`Private`heads =!= {} && 
        !OptionQ[FeynCalc`FCGetFreeIndices`Private`heads], 
     OptionsPattern[]] := 
    {} /; FreeQ2[FeynCalc`FCGetFreeIndices`Private`expr, 
      FeynCalc`FCGetFreeIndices`Private`heads]
 
FCGetFreeIndices[FeynCalc`FCGetFreeIndices`Private`expr_, 
     FeynCalc`FCGetFreeIndices`Private`heads_List /; 
      FeynCalc`FCGetFreeIndices`Private`heads =!= {} && 
        !OptionQ[FeynCalc`FCGetFreeIndices`Private`heads], 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCGetFreeIndices`Private`fullLiList, 
       FeynCalc`FCGetFreeIndices`Private`freeIndicesList, 
       FeynCalc`FCGetFreeIndices`Private`allIndicesList, 
       FeynCalc`FCGetFreeIndices`Private`dummyIndicesList, 
       FeynCalc`FCGetFreeIndices`Private`ex, 
       FeynCalc`FCGetFreeIndices`Private`times, 
       FeynCalc`FCGetFreeIndices`Private`i, 
       FeynCalc`FCGetFreeIndices`Private`sel, 
       FeynCalc`FCGetFreeIndices`Private`sel2, 
       FeynCalc`FCGetFreeIndices`Private`optFirst, 
       FeynCalc`FCGetFreeIndices`Private`time, 
       FeynCalc`FCGetFreeIndices`Private`optExpanding, 
       FeynCalc`FCGetFreeIndices`Private`null1, 
       FeynCalc`FCGetFreeIndices`Private`null2, 
       FeynCalc`FCGetFreeIndices`Private`res, 
       FeynCalc`FCGetFreeIndices`Private`optInverse}, 
      If[OptionValue[FCVerbose] === False, 
        FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[FCVerbose], _Integer], 
          FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose = 
           OptionValue[FCVerbose]]; ]; FCPrint[1, 
        "FCGetFreeIndices: Entering.", FCDoControl -> 
         FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
       FCPrint[3, "FCGetFreeIndices: Entering with: ", 
        FeynCalc`FCGetFreeIndices`Private`expr, FCDoControl -> 
         FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
       FeynCalc`FCGetFreeIndices`Private`optFirst = OptionValue[First]; 
       FeynCalc`FCGetFreeIndices`Private`optExpanding = 
        OptionValue[Expanding]; 
       FeynCalc`FCGetFreeIndices`Private`optInverse = OptionValue[Inverse]; 
       If[Head[FeynCalc`FCGetFreeIndices`Private`expr] === Times, 
        FeynCalc`FCGetFreeIndices`Private`ex = SelectNotFree[
          FeynCalc`FCGetFreeIndices`Private`expr, 
          FeynCalc`FCGetFreeIndices`Private`heads], 
        FeynCalc`FCGetFreeIndices`Private`ex = 
         FeynCalc`FCGetFreeIndices`Private`expr]; 
       If[OptionValue[FCTraceExpand], 
        FeynCalc`FCGetFreeIndices`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCGetFreeIndices: Applying FCTraceExpand.", 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FeynCalc`FCGetFreeIndices`Private`ex = FCTraceExpand[
           FeynCalc`FCGetFreeIndices`Private`ex, FCI -> True]; 
         FCPrint[1, "FCGetFreeIndices: FCTraceExpand done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCGetFreeIndices`Private`time, 4], 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FCPrint[3, "FCGetFreeIndices: After FCTraceExpand: ", 
          FeynCalc`FCGetFreeIndices`Private`ex, FCDoControl -> 
           FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; ]; 
       If[OptionValue[DotSimplify], FeynCalc`FCGetFreeIndices`Private`time = 
          AbsoluteTime[]; FCPrint[1, 
          "FCGetFreeIndices: Applying DotSimplify.", FCDoControl -> 
           FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FeynCalc`FCGetFreeIndices`Private`ex = DotSimplify[
           FeynCalc`FCGetFreeIndices`Private`ex, FCI -> True, 
           Expanding -> FeynCalc`FCGetFreeIndices`Private`optExpanding]; 
         FCPrint[1, "FCGetFreeIndices: DotSimplify done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCGetFreeIndices`Private`time, 4], 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FCPrint[3, "FCGetFreeIndices: After DotSimplify: ", 
          FeynCalc`FCGetFreeIndices`Private`ex, FCDoControl -> 
           FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; ]; 
       If[OptionValue[DiracChainExpand] && 
          !FreeQ[FeynCalc`FCGetFreeIndices`Private`ex, DiracChain], 
        FeynCalc`FCGetFreeIndices`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCGetFreeIndices: Applying DiracChainExpand.", 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FeynCalc`FCGetFreeIndices`Private`ex = DiracChainExpand[
           FeynCalc`FCGetFreeIndices`Private`ex, FCI -> True]; 
         FCPrint[1, "FCGetFreeIndices: DiracChainExpand done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCGetFreeIndices`Private`time, 4], 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FCPrint[3, "FCGetFreeIndices: After DiracChainExpand: ", 
          FeynCalc`FCGetFreeIndices`Private`ex, FCDoControl -> 
           FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; ]; 
       If[OptionValue[PauliChainExpand] && 
          !FreeQ[FeynCalc`FCGetFreeIndices`Private`ex, PauliChain], 
        FeynCalc`FCGetFreeIndices`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCGetFreeIndices: Applying PauliChainExpand.", 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FeynCalc`FCGetFreeIndices`Private`ex = PauliChainExpand[
           FeynCalc`FCGetFreeIndices`Private`ex, FCI -> True]; 
         FCPrint[1, "FCGetFreeIndices: PauliChainExpand done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCGetFreeIndices`Private`time, 4], 
          FCDoControl -> FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
         FCPrint[3, "FCGetFreeIndices: After PauliChainExpand: ", 
          FeynCalc`FCGetFreeIndices`Private`ex, FCDoControl -> 
           FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; ]; 
       FeynCalc`FCGetFreeIndices`Private`ex = ExpandAll2[
         FeynCalc`FCGetFreeIndices`Private`ex]; 
       If[Head[FeynCalc`FCGetFreeIndices`Private`ex] === Plus && 
         FeynCalc`FCGetFreeIndices`Private`optFirst && 
          !FeynCalc`FCGetFreeIndices`Private`optInverse, 
        FeynCalc`FCGetFreeIndices`Private`ex = 
         First[FeynCalc`FCGetFreeIndices`Private`ex]]; 
       If[ !FreeQ[FeynCalc`FCGetFreeIndices`Private`ex, Power], 
        FeynCalc`FCGetFreeIndices`Private`ex = 
          FeynCalc`FCGetFreeIndices`Private`ex /. 
           (FeynCalc`FCGetFreeIndices`Private`a_)^
              (FeynCalc`FCGetFreeIndices`Private`b_Integer)?Positive /; 
              !FreeQ2[FeynCalc`FCGetFreeIndices`Private`a, 
               FeynCalc`FCGetFreeIndices`Private`heads] :> 
            FeynCalc`FCGetFreeIndices`Private`times @@ 
             Table[FeynCalc`FCGetFreeIndices`Private`a, 
              {FeynCalc`FCGetFreeIndices`Private`i, 
               FeynCalc`FCGetFreeIndices`Private`b}]; ]; 
       FCPrint[3, "FCGetFreeIndices: Final ex: ", 
        FeynCalc`FCGetFreeIndices`Private`ex, FCDoControl -> 
         FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
       FeynCalc`FCGetFreeIndices`Private`sel = 
        Blank /@ FeynCalc`FCGetFreeIndices`Private`heads; 
       If[Length[FeynCalc`FCGetFreeIndices`Private`heads] === 1, 
        FeynCalc`FCGetFreeIndices`Private`sel = Identity @@ 
           Blank /@ FeynCalc`FCGetFreeIndices`Private`heads; 
         FeynCalc`FCGetFreeIndices`Private`sel2 = Identity @@ 
           FeynCalc`FCGetFreeIndices`Private`heads, 
        FeynCalc`FCGetFreeIndices`Private`sel = Alternatives @@ 
           Blank /@ FeynCalc`FCGetFreeIndices`Private`heads; 
         FeynCalc`FCGetFreeIndices`Private`sel2 = Alternatives @@ 
           FeynCalc`FCGetFreeIndices`Private`heads]; 
       FCPrint[1, "FCGetFreeIndices: sel: ", 
        FeynCalc`FCGetFreeIndices`Private`sel, FCDoControl -> 
         FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
       FCPrint[1, "FCGetFreeIndices: sel2: ", 
        FeynCalc`FCGetFreeIndices`Private`sel2, FCDoControl -> 
         FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose]; 
       FeynCalc`FCGetFreeIndices`Private`freeIndicesList = 
        (FeynCalc`FCGetFreeIndices`Private`getFreeIndices[#1, 
           FeynCalc`FCGetFreeIndices`Private`sel, 
           FeynCalc`FCGetFreeIndices`Private`sel2] & ) /@ 
         List @@ (FeynCalc`FCGetFreeIndices`Private`ex + 
           FeynCalc`FCGetFreeIndices`Private`null1 + 
           FeynCalc`FCGetFreeIndices`Private`null2); 
       FeynCalc`FCGetFreeIndices`Private`freeIndicesList = 
        Union[Flatten[FeynCalc`FCGetFreeIndices`Private`freeIndicesList]]; 
       If[TrueQ[FeynCalc`FCGetFreeIndices`Private`optInverse], 
        FeynCalc`FCGetFreeIndices`Private`allIndicesList = 
          (#1 /. FeynCalc`FCGetFreeIndices`Private`sel2[
               FeynCalc`FCGetFreeIndices`Private`z_, ___] :> 
              FeynCalc`FCGetFreeIndices`Private`z & )[
           Cases[FeynCalc`FCGetFreeIndices`Private`ex, 
            FeynCalc`FCGetFreeIndices`Private`sel, Infinity]]; 
         FeynCalc`FCGetFreeIndices`Private`allIndicesList = 
          Union[Flatten[FeynCalc`FCGetFreeIndices`Private`allIndicesList]]; 
         FeynCalc`FCGetFreeIndices`Private`dummyIndicesList = 
          Complement[FeynCalc`FCGetFreeIndices`Private`allIndicesList, 
           FeynCalc`FCGetFreeIndices`Private`freeIndicesList]; 
         FeynCalc`FCGetFreeIndices`Private`res = 
          FeynCalc`FCGetFreeIndices`Private`dummyIndicesList, 
        FeynCalc`FCGetFreeIndices`Private`res = 
         FeynCalc`FCGetFreeIndices`Private`freeIndicesList]; 
       FeynCalc`FCGetFreeIndices`Private`res] /; 
      !FreeQ2[FeynCalc`FCGetFreeIndices`Private`expr, 
       FeynCalc`FCGetFreeIndices`Private`heads]
 
Options[FCGetFreeIndices] = {DiracChainExpand -> True, DotSimplify -> True, 
     Expanding -> True, FCTraceExpand -> True, FCVerbose -> False, 
     First -> False, Inverse -> False, PauliChainExpand -> True}
 
FCGetFreeIndices /: FCGetFreeIndices::usage = "FCGetFreeIndices[exp, {head1, \
head2, ...}]  returns the list of free\n(uncontracted) indices from heads \
head1, head2, ...\n\nAs always in FeynCalc, Einstein summation convention is \
implicitly assumed.\nThe function is optimized for large expressions, i.e. it \
is not so good as a\ncriterion in e.g. Select.\n\nIf it is understood that \
each term in the expression contains the same number\nof free indices, \
setting the option First to True can considerably speed up\nthe evaluation."
 
FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose = 0
 
FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose /: 
    FeynCalc`FCGetFreeIndices`Private`fcgfiVerbose::usage = ""
 
ExpandAll2[FeynCalc`SharedTools`Private`expr_] := 
    FixedPoint[Switch[Head[#1], Times, Distribute[#1], Plus, 
       If[ !FreeQ[List @@ #1, Plus], ExpandAll2 /@ #1, #1], _, #1] & , 
     FeynCalc`SharedTools`Private`expr]
 
ExpandAll2 /: ExpandAll2::usage = "ExpandAll2[exp] is similar to ExpandAll, \
but much faster on simple structures."
 
FeynCalc`FCGetFreeIndices`Private`getFreeIndices[
     FeynCalc`FCGetFreeIndices`Private`x_, 
     FeynCalc`FCGetFreeIndices`Private`sel_, 
     FeynCalc`FCGetFreeIndices`Private`sel2_] := 
    (Cases[#1, {FeynCalc`FCGetFreeIndices`Private`z_, 1} :> 
        FeynCalc`FCGetFreeIndices`Private`z] & )[
     Tally[(#1 /. FeynCalc`FCGetFreeIndices`Private`sel2[
           FeynCalc`FCGetFreeIndices`Private`z_, ___] :> 
          FeynCalc`FCGetFreeIndices`Private`z & )[
       Cases[FeynCalc`FCGetFreeIndices`Private`x, 
        FeynCalc`FCGetFreeIndices`Private`sel, Infinity]]]]
 
FeynCalc`EpsContract`Private`epsCleverCon[
     FeynCalc`EpsContract`Private`expr_] := 
    FeynCalc`EpsContract`Private`expr //. 
           Eps[FeynCalc`EpsContract`Private`a__]^
             (FeynCalc`EpsContract`Private`n_) :> 
            FeynCalc`EpsContract`Private`epsHold[
             FeynCalc`EpsContract`Private`epscon[
               FeynCalc`EpsContract`Private`a]^
              FeynCalc`EpsContract`Private`n] //. 
          Eps[FeynCalc`EpsContract`Private`a__]*
             Eps[FeynCalc`EpsContract`Private`b__] /; 
            Length[Intersection[{FeynCalc`EpsContract`Private`a}, {
                FeynCalc`EpsContract`Private`b}]] === 3 :> 
           FeynCalc`EpsContract`Private`epsHold[
            FeynCalc`EpsContract`Private`epscon[
              FeynCalc`EpsContract`Private`a]*
             FeynCalc`EpsContract`Private`epscon[
              FeynCalc`EpsContract`Private`b]] //. 
         Eps[FeynCalc`EpsContract`Private`a__]*
            Eps[FeynCalc`EpsContract`Private`b__] /; 
           Length[Intersection[{FeynCalc`EpsContract`Private`a}, 
              {FeynCalc`EpsContract`Private`b}]] === 2 :> 
          FeynCalc`EpsContract`Private`epsHold[
           FeynCalc`EpsContract`Private`epscon[
             FeynCalc`EpsContract`Private`a]*
            FeynCalc`EpsContract`Private`epscon[
             FeynCalc`EpsContract`Private`b]] //. 
        Eps[FeynCalc`EpsContract`Private`a__]*
           Eps[FeynCalc`EpsContract`Private`b__] /; 
          Length[Intersection[{FeynCalc`EpsContract`Private`a}, 
             {FeynCalc`EpsContract`Private`b}]] === 1 :> 
         FeynCalc`EpsContract`Private`epsHold[
          FeynCalc`EpsContract`Private`epscon[FeynCalc`EpsContract`Private`a]*
           FeynCalc`EpsContract`Private`epscon[
            FeynCalc`EpsContract`Private`b]] /. 
       Eps -> FeynCalc`EpsContract`Private`epscon /. 
      FeynCalc`EpsContract`Private`epscon -> Eps /. 
     FeynCalc`EpsContract`Private`epsHold -> Identity
 
FeynCalc`EpsContract`Private`epscon /: 
    FeynCalc`EpsContract`Private`epscon[FeynCalc`EpsContract`Private`a1_, 
       FeynCalc`EpsContract`Private`a2_, FeynCalc`EpsContract`Private`a3_, 
       FeynCalc`EpsContract`Private`a4_]^2 := 
     ((-$LeviCivitaSign^2)*
        Det[{{PairContract[FeynCalc`EpsContract`Private`a1, 
            FeynCalc`EpsContract`Private`a1], PairContract[
            FeynCalc`EpsContract`Private`a1, 
            FeynCalc`EpsContract`Private`a2], PairContract[
            FeynCalc`EpsContract`Private`a1, 
            FeynCalc`EpsContract`Private`a3], PairContract[
            FeynCalc`EpsContract`Private`a1, 
            FeynCalc`EpsContract`Private`a4]}, 
          {PairContract[FeynCalc`EpsContract`Private`a2, 
            FeynCalc`EpsContract`Private`a1], PairContract[
            FeynCalc`EpsContract`Private`a2, 
            FeynCalc`EpsContract`Private`a2], PairContract[
            FeynCalc`EpsContract`Private`a2, 
            FeynCalc`EpsContract`Private`a3], PairContract[
            FeynCalc`EpsContract`Private`a2, 
            FeynCalc`EpsContract`Private`a4]}, 
          {PairContract[FeynCalc`EpsContract`Private`a3, 
            FeynCalc`EpsContract`Private`a1], PairContract[
            FeynCalc`EpsContract`Private`a3, 
            FeynCalc`EpsContract`Private`a2], PairContract[
            FeynCalc`EpsContract`Private`a3, 
            FeynCalc`EpsContract`Private`a3], PairContract[
            FeynCalc`EpsContract`Private`a3, 
            FeynCalc`EpsContract`Private`a4]}, 
          {PairContract[FeynCalc`EpsContract`Private`a4, 
            FeynCalc`EpsContract`Private`a1], PairContract[
            FeynCalc`EpsContract`Private`a4, 
            FeynCalc`EpsContract`Private`a2], PairContract[
            FeynCalc`EpsContract`Private`a4, 
            FeynCalc`EpsContract`Private`a3], PairContract[
            FeynCalc`EpsContract`Private`a4, 
            FeynCalc`EpsContract`Private`a4]}}] /. PairContract -> Pair) /; 
      Complement[DeleteDuplicates[Head /@ {FeynCalc`EpsContract`Private`a1, 
           FeynCalc`EpsContract`Private`a2, FeynCalc`EpsContract`Private`a3, 
           FeynCalc`EpsContract`Private`a4}], {LorentzIndex, Momentum, 
         ExplicitLorentzIndex}] === {}
 
FeynCalc`EpsContract`Private`epscon /: 
    FeynCalc`EpsContract`Private`epscon[FeynCalc`EpsContract`Private`a1_, 
       FeynCalc`EpsContract`Private`a2_, FeynCalc`EpsContract`Private`a3_]^
      2 := (Expand[$LeviCivitaSign^2*
         Det[{{CartesianPairContract[FeynCalc`EpsContract`Private`a1, 
             FeynCalc`EpsContract`Private`a1], CartesianPairContract[
             FeynCalc`EpsContract`Private`a1, 
             FeynCalc`EpsContract`Private`a2], CartesianPairContract[
             FeynCalc`EpsContract`Private`a1, 
             FeynCalc`EpsContract`Private`a3]}, {CartesianPairContract[
             FeynCalc`EpsContract`Private`a2, 
             FeynCalc`EpsContract`Private`a1], CartesianPairContract[
             FeynCalc`EpsContract`Private`a2, 
             FeynCalc`EpsContract`Private`a2], CartesianPairContract[
             FeynCalc`EpsContract`Private`a2, 
             FeynCalc`EpsContract`Private`a3]}, {CartesianPairContract[
             FeynCalc`EpsContract`Private`a3, 
             FeynCalc`EpsContract`Private`a1], CartesianPairContract[
             FeynCalc`EpsContract`Private`a3, 
             FeynCalc`EpsContract`Private`a2], CartesianPairContract[
