      LightConePerpendicularComponent[(FeynCalc`PairContract`Private`h:
         LorentzIndex | Momentum | ExplicitLorentzIndex)[
        FeynCalc`PairContract`Private`x_, 
        FeynCalc`PairContract`Private`dim___], 
       FeynCalc`PairContract`Private`n_, FeynCalc`PairContract`Private`nb_]]*
     (FeynCalc`PairContract`Private`f_)[
      FeynCalc`PairContract`Private`a__] ^:= 
    (FeynCalc`PairContract`Private`f[FeynCalc`PairContract`Private`a] /. 
      LorentzIndex[FeynCalc`PairContract`Private`z, ___] -> 
       LightConePerpendicularComponent[FeynCalc`PairContract`Private`h[
         FeynCalc`PairContract`Private`x, FeynCalc`PairContract`Private`dim], 
        FeynCalc`PairContract`Private`n, 
        FeynCalc`PairContract`Private`nb]) /; 
      !FreeQ[FeynCalc`PairContract`Private`f[
        FeynCalc`PairContract`Private`a], LorentzIndex[
        FeynCalc`PairContract`Private`z, ___]]
 
PairContract3[LorentzIndex[FeynCalc`PairContract`Private`z_, 
       FeynCalc`PairContract`Private`dimL_:4], 
      (FeynCalc`PairContract`Private`h:CartesianIndex | CartesianMomentum)[
       FeynCalc`PairContract`Private`x_, FeynCalc`PairContract`Private`dimC_:
        3]]*(FeynCalc`PairContract`Private`f_)[
      FeynCalc`PairContract`Private`a__] ^:= 
    (FeynCalc`PairContract`Private`f[FeynCalc`PairContract`Private`a] /. 
      LorentzIndex[FeynCalc`PairContract`Private`z, ___] -> 
       FeynCalc`PairContract`Private`h[FeynCalc`PairContract`Private`x, 
        FeynCalc`PairContract`Private`dimC]) /; 
      !FreeQ[FeynCalc`PairContract`Private`f[
         FeynCalc`PairContract`Private`a], LorentzIndex[
         FeynCalc`PairContract`Private`z, ___]] && 
      MatchQ[{FeynCalc`PairContract`Private`dimL, 
        FeynCalc`PairContract`Private`dimC}, 
       {4, 3} | {_Symbol, _Symbol - 1} | {_Symbol - 4, _Symbol - 4}]
 
PairContract3[0, _] := 0
 
PairContract3[LorentzIndex[FeynCalc`PairContract`Private`x_, 
      FeynCalc`PairContract`Private`dim1_:4], 
     LorentzIndex[FeynCalc`PairContract`Private`x_, 
      FeynCalc`PairContract`Private`dim2_:4]] := 
    FeynCalc`PairContract`Private`dimEval[FeynCalc`PairContract`Private`dim1, 
      FeynCalc`PairContract`Private`dim2] /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
PairContract3[LightConePerpendicularComponent[LorentzIndex[
       FeynCalc`PairContract`Private`x_, FeynCalc`PairContract`Private`dim1_:
        4], FeynCalc`PairContract`Private`n_, 
      FeynCalc`PairContract`Private`nb_], LightConePerpendicularComponent[
      LorentzIndex[FeynCalc`PairContract`Private`x_, 
       FeynCalc`PairContract`Private`dim2_:4], 
      FeynCalc`PairContract`Private`n_, 
      FeynCalc`PairContract`Private`nb_]] := 
    FeynCalc`PairContract`Private`dimEval[FeynCalc`PairContract`Private`dim1, 
       FeynCalc`PairContract`Private`dim2] - 2 /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
PairContract3[CartesianIndex[FeynCalc`PairContract`Private`x_, 
      FeynCalc`PairContract`Private`dim1_:3], CartesianIndex[
      FeynCalc`PairContract`Private`x_, FeynCalc`PairContract`Private`dim2_:
       3]] := FeynCalc`PairContract`Private`dimEval[
       FeynCalc`PairContract`Private`dim1, 
       FeynCalc`PairContract`Private`dim2]*FeynCalc`Package`MetricS /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
PairContract3[(FeynCalc`PairContract`Private`h1:LorentzIndex | Momentum | 
         TemporalMomentum | ExplicitLorentzIndex)[
       FeynCalc`PairContract`Private`x_, FeynCalc`PairContract`Private`dim1_:
        4], (FeynCalc`PairContract`Private`h2:LorentzIndex | Momentum | 
         TemporalMomentum | ExplicitLorentzIndex)[
       FeynCalc`PairContract`Private`y_, FeynCalc`PairContract`Private`dim2_:
        4]] /; {FeynCalc`PairContract`Private`dim1} =!= 
      {FeynCalc`PairContract`Private`dim2} := 
    PairContract3[FeynCalc`PairContract`Private`h1[
       FeynCalc`PairContract`Private`x, FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]], 
      FeynCalc`PairContract`Private`h2[FeynCalc`PairContract`Private`y, 
       FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]]] /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
PairContract3[(FeynCalc`PairContract`Private`h1:LorentzIndex | Momentum | 
         TemporalMomentum | ExplicitLorentzIndex)[
       FeynCalc`PairContract`Private`x_, FeynCalc`PairContract`Private`dim1_:
        4], (FeynCalc`PairContract`Private`h2:CartesianIndex | 
         CartesianMomentum)[FeynCalc`PairContract`Private`y_, 
       FeynCalc`PairContract`Private`dim2_:3]] /; 
     {FeynCalc`PairContract`Private`dim1} =!= 
      {FeynCalc`PairContract`Private`dim2} := 
    Block[{FeynCalc`PairContract`Private`dims = 
        FeynCalc`PairContract`Private`dimEvalLorentzCartesian[
         FeynCalc`PairContract`Private`dim1, 
         FeynCalc`PairContract`Private`dim2]}, PairContract3[
       FeynCalc`PairContract`Private`h1[FeynCalc`PairContract`Private`x, 
        FeynCalc`PairContract`Private`dims[[1]]], 
       FeynCalc`PairContract`Private`h2[FeynCalc`PairContract`Private`y, 
        FeynCalc`PairContract`Private`dims[[2]]]]] /; 
     Head[FeynCalc`PairContract`Private`dimEvalLorentzCartesian[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEvalLorentzCartesian
 
PairContract3[(FeynCalc`PairContract`Private`h1:CartesianIndex | 
         CartesianMomentum)[FeynCalc`PairContract`Private`x_, 
       FeynCalc`PairContract`Private`dim1_:3], 
      (FeynCalc`PairContract`Private`h2:CartesianIndex | CartesianMomentum)[
       FeynCalc`PairContract`Private`y_, FeynCalc`PairContract`Private`dim2_:
        3]] /; {FeynCalc`PairContract`Private`dim1} =!= 
      {FeynCalc`PairContract`Private`dim2} := 
    PairContract3[FeynCalc`PairContract`Private`h1[
       FeynCalc`PairContract`Private`x, FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]], 
      FeynCalc`PairContract`Private`h2[FeynCalc`PairContract`Private`y, 
       FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]]] /; 
     Head[FeynCalc`PairContract`Private`dimEval[
        FeynCalc`PairContract`Private`dim1, 
        FeynCalc`PairContract`Private`dim2]] =!= 
      FeynCalc`PairContract`Private`dimEval
 
PairContract3[FeynCalc`PairContract`Private`a_, 
     FeynCalc`PairContract`Private`b_] := 
    FCUseCache[ExpandScalarProduct, {Pair[FeynCalc`PairContract`Private`a, 
        FeynCalc`PairContract`Private`b]}, {FCI -> True}] /; 
     FreeQ2[{FeynCalc`PairContract`Private`a, 
       FeynCalc`PairContract`Private`b}, {LorentzIndex, CartesianIndex}]
 
PairContract3 /: PairContract3::usage = "PairContract3 is like Pair, but with \
local contraction properties among\nPairContract3s. The function fully \
supports the BMHV algebra and, unlike\nPairContract or PairContract2 will \
always expand momenta inside scalar\nproducts.\n\nPairContract3 is an \
auxiliary function used in higher level FeynCalc functions\nthat require fast \
contractions between multiple expressions, where Contract\nwould be too \
slow."
 
FeynCalc`Contract`Private`prepareProductContractions[
     FeynCalc`Contract`Private`ex_ /;  !MemberQ[{Times, Plus}, 
        Head[FeynCalc`Contract`Private`ex]], _] := 
    FeynCalc`Contract`Private`ex
 
FeynCalc`Contract`Private`prepareProductContractions[
     FeynCalc`Contract`Private`ex_Plus, 
     FeynCalc`Contract`Private`optVerbose_] := 
    (FeynCalc`Contract`Private`prepareProductContractions[#1, 
       FeynCalc`Contract`Private`optVerbose] & ) /@ 
     FeynCalc`Contract`Private`ex
 
FeynCalc`Contract`Private`prepareProductContractions[
     FeynCalc`Contract`Private`expr_Times, 
     FeynCalc`Contract`Private`optVerbose_] := 
    Block[{FeynCalc`Contract`Private`ex = FeynCalc`Contract`Private`expr, 
      FeynCalc`Contract`Private`irrelevantPart, 
      FeynCalc`Contract`Private`relevantPart, 
      FeynCalc`Contract`Private`listOfProducts, 
      FeynCalc`Contract`Private`time, FeynCalc`Contract`Private`res}, 
     FCPrint[1, "Contract: prepareProductContractions: Entering.", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: prepareProductContractions: Entering with: ", 
       FeynCalc`Contract`Private`expr, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      If[ !FreeQ2[FeynCalc`Contract`Private`ex, {DiracGamma, DiracChain, 
          PauliSigma, PauliChain, Eps, Rule}], 
       FCPrint[1, "Contract: prepareProductContractions: Expression contains \
DiracGamma, PauliSigma or Eps. Passing to Contract.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        Return[FeynCalc`Contract`Private`ex]]; 
      If[DummyIndexFreeQ[FeynCalc`Contract`Private`ex, 
        {LorentzIndex, CartesianIndex}], FCPrint[1, "Contract: \
prepareProductContractions: Expression is free of Lorentz indices. Leaving.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        Return[FeynCalc`Contract`Private`ex]]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[1, "Contract: prepareProductContractions: Splitting into parts \
free and not free of Lorentz indices.", FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      {FeynCalc`Contract`Private`irrelevantPart, 
        FeynCalc`Contract`Private`relevantPart} = FCProductSplit[
        FeynCalc`Contract`Private`ex, {LorentzIndex, CartesianIndex}]; 
      FCPrint[1, 
       "Contract: prepareProductContractions: Splitting done. Timing: ", 
       N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, 
       "Contract: prepareProductContractions: Part free of Lorentz indices: "\
, FeynCalc`Contract`Private`irrelevantPart, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, 
       "Contract: prepareProductContractions: Part with Lorentz indices: ", 
       FeynCalc`Contract`Private`relevantPart, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      Switch[Head[FeynCalc`Contract`Private`relevantPart], Plus, 
       FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, "Contract: prepareProductContractions: The indexed part is \
a sum, applying prepareProductContractions again.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`relevantPart = 
         FeynCalc`Contract`Private`prepareProductContractions[
          FeynCalc`Contract`Private`relevantPart, 0]; FCPrint[1, "Contract: \
prepareProductContractions: Done applying prepareProductContractions. Timing: \
", N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose], Times, 
       FCPrint[1, "Contract: prepareProductContractions: The indexed part is \
a product, applying reduceSumsToProducts.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "Contract: prepareProductContractions: Collecting w.r.t indices.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`listOfProducts = 
         List @@ FeynCalc`Contract`Private`relevantPart; 
        FeynCalc`Contract`Private`listOfProducts = 
         Collect2[FeynCalc`Contract`Private`listOfProducts, 
          {LorentzIndex, CartesianIndex}, IsolateNames -> 
           FeynCalc`Contract`Private`prefactorIso, Factoring -> 
           FeynCalc`Contract`Private`optFactoring, TimeConstrained -> 
           FeynCalc`Contract`Private`optTimeConstrained]; 
        FCPrint[1, 
         "Contract: prepareProductContractions: Done collecting, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FCPrint[1, "Contract: prepareProductContractions: Applying \
reduceSumsToProducts.", FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FeynCalc`Contract`Private`relevantPart = 
         Fold[FeynCalc`Contract`Private`reduceSumsToProducts[
            Collect2[#1, {LorentzIndex, CartesianIndex}, IsolateNames -> 
              FeynCalc`Contract`Private`prefactorIso, Factoring -> 
              FeynCalc`Contract`Private`optFactoring, TimeConstrained -> 
              FeynCalc`Contract`Private`optTimeConstrained], #2, 
            FeynCalc`Contract`Private`optVerbose] & , 
          FeynCalc`Contract`Private`listOfProducts]; FCPrint[1, "Contract: \
prepareProductContractions: Done applying reduceSumsToProducts. Timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "Contract: prepareProductContractions: Removing isolations.", 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        FeynCalc`Contract`Private`relevantPart = 
         FRH[FeynCalc`Contract`Private`relevantPart, IsolateNames -> 
           FeynCalc`Contract`Private`prefactorIso]; FCPrint[1, "Contract: \
prepareProductContractions: Done remvoing isolations, timing: ", 
         N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
         FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
        If[FeynCalc`Contract`Private`optExpandScalarProduct, 
         FeynCalc`Contract`Private`time = AbsoluteTime[]; 
          FCPrint[1, "Contract: prepareProductContractions: Applying \
ExpandScalarProduct.", FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
          FeynCalc`Contract`Private`res = ExpandScalarProduct[
            FeynCalc`Contract`Private`relevantPart, FCI -> True]; 
          FCPrint[1, "Contract: prepareProductContractions: \
ExpandScalarProduct done, timing: ", N[AbsoluteTime[] - 
             FeynCalc`Contract`Private`time, 4], FCDoControl -> 
            FeynCalc`Contract`Private`optVerbose]; ]; , _, 
       FCPrint[1, "Contract: prepareProductContractions: The indexed part is \
a single term or something else.", FCDoControl -> 
          FeynCalc`Contract`Private`optVerbose]; True]; 
      If[ !FreeQ2[FeynCalc`Contract`Private`relevantPart, 
         {FeynCalc`Contract`Private`prepareProductContractions, 
          FeynCalc`Contract`Private`reduceSumsToProducts}], 
       Message[Contract::fail, "Something went wrong when applying \
reduceSumsToProducts or prepareProductContractions."]; Abort[]]; 
      FeynCalc`Contract`Private`res = FeynCalc`Contract`Private`relevantPart*
        FeynCalc`Contract`Private`irrelevantPart; 
      FCPrint[1, "Contract: prepareProductContractions: Leaving.", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[4, "Contract: prepareProductContractions: Leaving with: ", 
       FeynCalc`Contract`Private`res, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; FeynCalc`Contract`Private`res]
 
FCProductSplit[FeynCalc`SharedTools`Private`expr_, {}, OptionsPattern[]] := 
    {FeynCalc`SharedTools`Private`expr, 1}
 
FCProductSplit[FeynCalc`SharedTools`Private`expr_, 
     FeynCalc`SharedTools`Private`vars_List /; 
      FeynCalc`SharedTools`Private`vars =!= {}, OptionsPattern[]] := 
    Block[{FeynCalc`SharedTools`Private`dummy1, 
      FeynCalc`SharedTools`Private`dummy2, 
      FeynCalc`SharedTools`Private`exprAsList, 
      FeynCalc`SharedTools`Private`pow, FeynCalc`SharedTools`Private`free, 
      FeynCalc`SharedTools`Private`notfree, 
      FeynCalc`SharedTools`Private`list}, 
     If[ !MatchQ[FeynCalc`SharedTools`Private`expr, _Times], 
       If[NTerms[FeynCalc`SharedTools`Private`expr, Expand -> False] > 1, 
         Message[FCProductSplit::failmsg, 
           "The input expression is not a product"]; Abort[]]; ]; 
      If[ !FreeQ[FeynCalc`SharedTools`Private`exprAsList, Power], 
       FeynCalc`SharedTools`Private`exprAsList = 
         FeynCalc`SharedTools`Private`list @@ 
          (FeynCalc`SharedTools`Private`expr*
           FeynCalc`SharedTools`Private`dummy1*
           FeynCalc`SharedTools`Private`dummy2); 
        FeynCalc`SharedTools`Private`exprAsList /. Power -> 
            FeynCalc`SharedTools`Private`pow //. 
          {FeynCalc`SharedTools`Private`list[
             FeynCalc`SharedTools`Private`a___, 
             FeynCalc`SharedTools`Private`pow[
              FeynCalc`SharedTools`Private`b_, 
              (FeynCalc`SharedTools`Private`n_Integer)?Positive], 
             FeynCalc`SharedTools`Private`c___] :> 
            FeynCalc`SharedTools`Private`list[FeynCalc`SharedTools`Private`a, 
             Sequence @@ ConstantArray[FeynCalc`SharedTools`Private`b, 
               FeynCalc`SharedTools`Private`n], 
             FeynCalc`SharedTools`Private`c], 
           FeynCalc`SharedTools`Private`list[
             FeynCalc`SharedTools`Private`a___, 
             FeynCalc`SharedTools`Private`pow[
              FeynCalc`SharedTools`Private`b_, 
              (FeynCalc`SharedTools`Private`n_Integer)?Negative], 
             FeynCalc`SharedTools`Private`c___] :> 
            FeynCalc`SharedTools`Private`list[FeynCalc`SharedTools`Private`a, 
             Sequence @@ ConstantArray[1/FeynCalc`SharedTools`Private`b, 
               -FeynCalc`SharedTools`Private`n], 
             FeynCalc`SharedTools`Private`c]} /. 
         FeynCalc`SharedTools`Private`pow -> Power; 
        FeynCalc`SharedTools`Private`exprAsList = 
         FeynCalc`SharedTools`Private`exprAsList /. 
          FeynCalc`SharedTools`Private`list -> List, 
       FeynCalc`SharedTools`Private`exprAsList = 
        List @@ (FeynCalc`SharedTools`Private`expr*
          FeynCalc`SharedTools`Private`dummy1*
          FeynCalc`SharedTools`Private`dummy2)]; 
      FeynCalc`SharedTools`Private`free = 
       SelectFree[FeynCalc`SharedTools`Private`exprAsList, 
         FeynCalc`SharedTools`Private`vars] /. 
        FeynCalc`SharedTools`Private`dummy1 | 
          FeynCalc`SharedTools`Private`dummy2 :> Unevaluated[Sequence[]]; 
      FeynCalc`SharedTools`Private`notfree = SelectNotFree[
        FeynCalc`SharedTools`Private`exprAsList, 
        FeynCalc`SharedTools`Private`vars]; 
      FeynCalc`SharedTools`Private`free = 
       Times @@ FeynCalc`SharedTools`Private`free; 
      FeynCalc`SharedTools`Private`notfree = 
       Times @@ FeynCalc`SharedTools`Private`notfree; 
      If[Factor[FeynCalc`SharedTools`Private`free*
           FeynCalc`SharedTools`Private`notfree - 
          FeynCalc`SharedTools`Private`expr] || 
         !FreeQ2[FeynCalc`SharedTools`Private`free, 
          FeynCalc`SharedTools`Private`vars], 
       Message[FCProductSplit::failmsg, StringJoin["Error! Splitting", 
          ToString[FeynCalc`SharedTools`Private`expr, InputForm], " w.r.t ", 
          ToString[FeynCalc`SharedTools`Private`vars, InputForm], 
          " failed!"]]; Abort[]]; {FeynCalc`SharedTools`Private`free, 
       FeynCalc`SharedTools`Private`notfree}]
 
Options[FCProductSplit] = {Abort -> False}
 
FCProductSplit /: FCProductSplit::failmsg = "Error! FCProductSplit has \
encountered a fatal problem and must abort the computation. \n\nThe problem \
reads: `1`"
 
FCProductSplit /: FCProductSplit::usage = "FCProductSplit[exp, {v1, v2, ...}] \
splits expr into pieces that are free of\nany occurrence of v1, v2, ... and \
pieces that contain those variables. This\nworks both only for products. The \
output is provided in the form of a two\nelement list. One can recover the \
original expression by applying Times to\nthat list."
 
NTerms[FeynCalc`SharedTools`Private`x_Plus, OptionsPattern[]] := 
    Length[FeynCalc`SharedTools`Private`x]
 
NTerms[FeynCalc`SharedTools`Private`x_, OptionsPattern[]] := 
    Block[{FeynCalc`SharedTools`Private`ntermslex}, 
     If[OptionValue[Expand], FeynCalc`SharedTools`Private`ntermslex = 
        Expand[FeynCalc`SharedTools`Private`x], 
       FeynCalc`SharedTools`Private`ntermslex = 
        FeynCalc`SharedTools`Private`x]; 
      If[Head[FeynCalc`SharedTools`Private`ntermslex] === Plus, 
       FeynCalc`SharedTools`Private`ntermslex = 
        Length[FeynCalc`SharedTools`Private`ntermslex], 
       If[FeynCalc`SharedTools`Private`x === 0, 
        FeynCalc`SharedTools`Private`ntermslex = 0, 
        FeynCalc`SharedTools`Private`ntermslex = 1]]; 
      FeynCalc`SharedTools`Private`ntermslex]
 
Options[NTerms] = {Expand -> True}
 
NTerms /: NTerms::usage = "NTerms[x] is equivalent to Length if x is a sum; \
otherwise NTerms[x] returns\n1, except NTerms[0] -> 0."
 
FeynCalc`Contract`Private`prefactorIso /: 
    FeynCalc`Contract`Private`prefactorIso::usage = ""
 
FeynCalc`Contract`Private`reduceSumsToProducts[FeynCalc`Contract`Private`a_, 
     FeynCalc`Contract`Private`b_, FeynCalc`Contract`Private`optVerbose_] := 
    FeynCalc`Contract`Private`reduceSumsToProducts[
      FeynCalc`Contract`Private`b, FeynCalc`Contract`Private`a, 
      FeynCalc`Contract`Private`optVerbose] /; 
     LeafCount[FeynCalc`Contract`Private`a] < 
      LeafCount[FeynCalc`Contract`Private`b]
 
FeynCalc`Contract`Private`reduceSumsToProducts[FeynCalc`Contract`Private`a_, 
     FeynCalc`Contract`Private`b_, FeynCalc`Contract`Private`optVerbose_] := 
    Block[{FeynCalc`Contract`Private`res, FeynCalc`Contract`Private`bnew}, 
      FCPrint[3, "Contract: reduceSumsToProducts: Entering.", 
        FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
       FCPrint[4, "Contract: reduceSumsToProducts: Entering with: {a,b}: ", 
        {FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b}, 
        FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
       If[FreeQ2[FeynCalc`Contract`Private`b, {LorentzIndex, 
          CartesianIndex}], Return[FeynCalc`Contract`Private`a*
          FeynCalc`Contract`Private`b]]; 
       If[TrueQ[MatchQ[SelectNotFree[FeynCalc`Contract`Private`b, Pair, 
            CartesianPair], HoldPattern[Times][__CartesianPair, __Pair] | 
            HoldPattern[Times][__Pair, __CartesianPair] | HoldPattern[Times][
             __Pair] | HoldPattern[Times][
             __FeynCalc`Contract`Private`CartesianPairPair]]] || 
         Head[FeynCalc`Contract`Private`b] === Pair || 
         Head[FeynCalc`Contract`Private`b] === CartesianPair, 
        FCPrint[3, "Contract: reduceSumsToProducts: b factorizes, calling \
contractWithProductOfPairs.", FCDoControl -> 
           FeynCalc`Contract`Private`optVerbose]; FCPrint[4, 
          "Contract: reduceSumsToProducts: {a,b}:", 
          {FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b}, 
          FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
         FeynCalc`Contract`Private`res = 
          FeynCalc`Contract`Private`contractWithProductOfPairs[
           FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b], 
        FCPrint[3, "Contract: reduceSumsToProducts: b doesn't factorize, \
calling Collect2.", FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
         FeynCalc`Contract`Private`bnew = Collect2[
           FeynCalc`Contract`Private`b, {LorentzIndex, CartesianIndex}]; 
         If[Head[FeynCalc`Contract`Private`bnew] === Plus, 
          FCPrint[3, "Contract: reduceSumsToProducts: b still does not \
factorize, calling reduceSumsToProducts", FCDoControl -> 
             FeynCalc`Contract`Private`optVerbose]; 
           FeynCalc`Contract`Private`res = 
            (FeynCalc`Contract`Private`reduceSumsToProducts[
               FeynCalc`Contract`Private`a, #1, 
               FeynCalc`Contract`Private`optVerbose] & ) /@ 
             FeynCalc`Contract`Private`bnew, FCPrint[3, "Contract: \
reduceSumsToProducts: b now factorizes, calling contractWithProductOfPairs.", 
            FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
           FeynCalc`Contract`Private`res = 
            FeynCalc`Contract`Private`contractWithProductOfPairs[
             FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`bnew]]]; 
       FCPrint[4, "Contract: reduceSumsToProducts: result: ", 
        FeynCalc`Contract`Private`res, FCDoControl -> 
         FeynCalc`Contract`Private`optVerbose]; 
       If[FeynCalc`Contract`Private`optExpandScalarProduct, 
        FeynCalc`Contract`Private`res = ExpandScalarProduct[
           FeynCalc`Contract`Private`res, FCI -> True]; ]; 
       If[ !FreeQ2[FeynCalc`Contract`Private`res, {LorentzIndex, 
           CartesianIndex}], FeynCalc`Contract`Private`res = 
          Expand2[FeynCalc`Contract`Private`res, {LorentzIndex, 
            CartesianIndex}]; ]; FCPrint[3, 
        "Contract: reduceSumsToProducts: Leaving.", FCDoControl -> 
         FeynCalc`Contract`Private`optVerbose]; 
       FeynCalc`Contract`Private`res] /; 
     LeafCount[FeynCalc`Contract`Private`a] >= 
      LeafCount[FeynCalc`Contract`Private`b]
 
FeynCalc`Contract`Private`contractWithProductOfPairs[
     FeynCalc`Contract`Private`a_, FeynCalc`Contract`Private`b_Pair] := 
    FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b]
 
FeynCalc`Contract`Private`contractWithProductOfPairs[
     FeynCalc`Contract`Private`a_, 
     FeynCalc`Contract`Private`b_CartesianPair] := 
    FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b]
 
FeynCalc`Contract`Private`contractWithProductOfPairs[
     FeynCalc`Contract`Private`a_, FeynCalc`Contract`Private`b_ /; 
       !MemberQ[{Pair, CartesianPair, Times}, 
        Head[FeynCalc`Contract`Private`b]]] := FeynCalc`Contract`Private`a*
     FeynCalc`Contract`Private`b
 
FeynCalc`Contract`Private`contractWithProductOfPairs[
     FeynCalc`Contract`Private`a_, FeynCalc`Contract`Private`b_Times] := 
    (Fold[FeynCalc`Contract`Private`contractWithSinglePair, 
        FeynCalc`Contract`Private`a, List @@ FeynCalc`Contract`Private`b] /. 
       Pair -> PairContract /. PairContract -> Pair) /; 
     FreeQ2[{FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b}, 
      {CartesianPair, CartesianMomentum, CartesianIndex}]
 
FeynCalc`Contract`Private`contractWithProductOfPairs[
     FeynCalc`Contract`Private`a_, FeynCalc`Contract`Private`b_Times] := 
    (Fold[FeynCalc`Contract`Private`contractWithSinglePair, 
          FeynCalc`Contract`Private`a, List @@ 
           FeynCalc`Contract`Private`b] /. Pair -> PairContract /. 
        CartesianPair -> CartesianPairContract /. PairContract -> Pair /. 
      CartesianPairContract -> CartesianPair) /; 
      !FreeQ2[{FeynCalc`Contract`Private`a, FeynCalc`Contract`Private`b}, 
       {CartesianPair, CartesianMomentum, CartesianIndex}]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, FeynCalc`Contract`Private`pref_ /; 
       !MemberQ[{Pair, CartesianPair, Times}, 
        Head[FeynCalc`Contract`Private`pref]]] := FeynCalc`Contract`Private`a*
     FeynCalc`Contract`Private`pref
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, 
     Pair[LorentzIndex[FeynCalc`Contract`Private`ind_, 
       FeynCalc`Contract`Private`dim___], 
      FeynCalc`Contract`Private`secondSlot_]] := 
    Expand2[FeynCalc`Contract`Private`a*
       Pair[LorentzIndex[FeynCalc`Contract`Private`ind, 
         FeynCalc`Contract`Private`dim], 
        FeynCalc`Contract`Private`secondSlot], Pair] /; 
     FreeQ[FeynCalc`Contract`Private`a, LorentzIndex[
       FeynCalc`Contract`Private`ind, ___]]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, CartesianPair[CartesianIndex[
       FeynCalc`Contract`Private`ind_, FeynCalc`Contract`Private`dim___], 
      FeynCalc`Contract`Private`secondSlot_]] := 
    Expand2[FeynCalc`Contract`Private`a*CartesianPair[
        CartesianIndex[FeynCalc`Contract`Private`ind, 
         FeynCalc`Contract`Private`dim], 
        FeynCalc`Contract`Private`secondSlot], CartesianPair] /; 
     FreeQ[FeynCalc`Contract`Private`a, CartesianIndex[
       FeynCalc`Contract`Private`ind, ___]]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, 
     Pair[LorentzIndex[FeynCalc`Contract`Private`ind_, 
       FeynCalc`Contract`Private`dim___], (FeynCalc`Contract`Private`h:
        LorentzIndex | Momentum | ExplicitLorentzIndex)[
       FeynCalc`Contract`Private`x_, FeynCalc`Contract`Private`dim___]]] := 
    (FeynCalc`Contract`Private`a /. 
      LorentzIndex[FeynCalc`Contract`Private`ind, ___] :> 
       FeynCalc`Contract`Private`h[FeynCalc`Contract`Private`x, 
        FeynCalc`Contract`Private`dim]) /; 
      !FreeQ[FeynCalc`Contract`Private`a, LorentzIndex[
        FeynCalc`Contract`Private`ind, ___]]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, 
     Pair[LorentzIndex[FeynCalc`Contract`Private`ind_, 
       FeynCalc`Contract`Private`dimL_:4], 
      (FeynCalc`Contract`Private`h:CartesianIndex | CartesianMomentum)[
       FeynCalc`Contract`Private`x_, FeynCalc`Contract`Private`dimC_:3]]] := 
    (FeynCalc`Contract`Private`a /. 
      LorentzIndex[FeynCalc`Contract`Private`ind, ___] :> 
       FeynCalc`Contract`Private`h[FeynCalc`Contract`Private`x, 
        FeynCalc`Contract`Private`dimC]) /; 
      !FreeQ[FeynCalc`Contract`Private`a, LorentzIndex[
         FeynCalc`Contract`Private`ind, ___]] && 
      MatchQ[{FeynCalc`Contract`Private`dimL, 
        FeynCalc`Contract`Private`dimC}, {4, 3} | {_Symbol, _Symbol - 1} | 
        {_Symbol - 4, _Symbol - 4}]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, CartesianPair[CartesianIndex[
       FeynCalc`Contract`Private`ind_, FeynCalc`Contract`Private`dim___], 
      (FeynCalc`Contract`Private`h:CartesianIndex | CartesianMomentum)[
       FeynCalc`Contract`Private`x_, FeynCalc`Contract`Private`dim___]]] := 
    (FeynCalc`Contract`Private`a /. 
      CartesianIndex[FeynCalc`Contract`Private`ind, ___] :> 
       FeynCalc`Contract`Private`h[FeynCalc`Contract`Private`x, 
        FeynCalc`Contract`Private`dim]) /; 
      !FreeQ[FeynCalc`Contract`Private`a, CartesianIndex[
        FeynCalc`Contract`Private`ind, ___]]
 
FeynCalc`Contract`Private`contractWithSinglePair[
      FeynCalc`Contract`Private`a_, 
      Pair[LorentzIndex[FeynCalc`Contract`Private`ind_, 
        FeynCalc`Contract`Private`dim1___], (FeynCalc`Contract`Private`h:
         LorentzIndex | Momentum | ExplicitLorentzIndex)[
        FeynCalc`Contract`Private`x_, FeynCalc`Contract`Private`dim2___]]] /; 
     FeynCalc`Contract`Private`dim1 =!= FeynCalc`Contract`Private`dim2 := 
    Expand2[FeynCalc`Contract`Private`a*
      Pair[LorentzIndex[FeynCalc`Contract`Private`ind, 
        FeynCalc`Contract`Private`dim1], FeynCalc`Contract`Private`h[
        FeynCalc`Contract`Private`x, FeynCalc`Contract`Private`dim2]], Pair]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, Pair[CartesianIndex[
       FeynCalc`Contract`Private`ind_, FeynCalc`Contract`Private`dimL_:4], 
      (FeynCalc`Contract`Private`h:CartesianIndex | CartesianMomentum)[
       FeynCalc`Contract`Private`x_, FeynCalc`Contract`Private`dimC_:3]]] := 
    Expand2[FeynCalc`Contract`Private`a*CartesianPair[
        CartesianIndex[FeynCalc`Contract`Private`ind, 
         FeynCalc`Contract`Private`dimL], FeynCalc`Contract`Private`h[
         FeynCalc`Contract`Private`x, FeynCalc`Contract`Private`dimC]], 
      CartesianPair] /; MatchQ[{FeynCalc`Contract`Private`dimL, 
       FeynCalc`Contract`Private`dimC}, {4, 3} | {_Symbol, _Symbol - 1} | 
       {_Symbol - 4, _Symbol - 4}]
 
FeynCalc`Contract`Private`contractWithSinglePair[
     FeynCalc`Contract`Private`a_, FeynCalc`Contract`Private`b_] := 
    Expand2[FeynCalc`Contract`Private`a*FeynCalc`Contract`Private`b, 
      {Pair, CartesianPair}] /; FreeQ2[{FeynCalc`Contract`Private`a}, 
       {LorentzIndex, CartesianIndex}] || 
      FreeQ2[{FeynCalc`Contract`Private`b}, {LorentzIndex, CartesianIndex}]
 
FeynCalc`Contract`Private`cartesianContract[FeynCalc`Contract`Private`x:
      Except[_Plus], FeynCalc`Contract`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`Contract`Private`contractres = 
       FeynCalc`Contract`Private`x, 
      FeynCalc`Contract`Private`contractexpandopt, 
      FeynCalc`Contract`Private`time, FeynCalc`Contract`Private`optVerbose}, 
     If[OptionValue[Contract, {FeynCalc`Contract`Private`opts}, 
         FCVerbose] === False, FeynCalc`Contract`Private`optVerbose = 
        $VeryVerbose, If[MatchQ[OptionValue[Contract, 
           {FeynCalc`Contract`Private`opts}, FCVerbose], _Integer], 
         FeynCalc`Contract`Private`optVerbose = OptionValue[Contract, 
           {FeynCalc`Contract`Private`opts}, FCVerbose]]; ]; 
      FeynCalc`Contract`Private`contractexpandopt = OptionValue[Contract, 
        {FeynCalc`Contract`Private`opts}, Expanding]; 
      FCPrint[3, "Contract: cartesianContract: Entering", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[4, "Contract: cartesianContract: Entering with ", 
       FeynCalc`Contract`Private`x, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      If[FeynCalc`Contract`Private`contractexpandopt, 
       FeynCalc`Contract`Private`contractres = 
        Expand2[FeynCalc`Contract`Private`contractres, CartesianIndex]]; 
      FeynCalc`Contract`Private`time = AbsoluteTime[]; 
      FCPrint[3, "Contract: cartesianContract: Applying PairContract.", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`contractres = 
       FeynCalc`Contract`Private`contractres /. Pair -> PairContract /. 
          CartesianPair -> CartesianPairContract /. PairContract -> Pair /. 
        CartesianPairContract -> CartesianPair; 
      FCPrint[3, "Contract: cartesianContract: PairContract done. Timing: ", 
       N[AbsoluteTime[] - FeynCalc`Contract`Private`time, 4], 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[4, "Contract: cartesianContract: After PairContract: ", 
       FeynCalc`Contract`Private`contractres, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[3, "Contract: cartesianContract: Leaving.", 
       FCDoControl -> FeynCalc`Contract`Private`optVerbose]; 
      FCPrint[4, "Contract: cartesianContract: Leaving with: ", 
       FeynCalc`Contract`Private`contractres, FCDoControl -> 
        FeynCalc`Contract`Private`optVerbose]; 
      FeynCalc`Contract`Private`contractres]
 
EpsContractFreeQ[FeynCalc`EpsContractFreeQ`Private`expr_] := 
    True /; FreeQ[FeynCalc`EpsContractFreeQ`Private`expr, Eps]
 
EpsContractFreeQ[FeynCalc`EpsContractFreeQ`Private`expr_] := 
    Block[{FeynCalc`EpsContractFreeQ`Private`tmp, 
       FeynCalc`EpsContractFreeQ`Private`head, 
       FeynCalc`EpsContractFreeQ`Private`ex, 
       FeynCalc`EpsContractFreeQ`Private`times, 
       FeynCalc`EpsContractFreeQ`Private`i}, 
      If[Head[FeynCalc`EpsContractFreeQ`Private`expr] === Times, 
        FeynCalc`EpsContractFreeQ`Private`ex = SelectNotFree[
          FeynCalc`EpsContractFreeQ`Private`expr, Eps], 
        FeynCalc`EpsContractFreeQ`Private`ex = 
         FeynCalc`EpsContractFreeQ`Private`expr]; 
       If[ !FreeQ[FeynCalc`EpsContractFreeQ`Private`ex, Power], 
        FeynCalc`EpsContractFreeQ`Private`ex = 
          FeynCalc`EpsContractFreeQ`Private`ex /. 
           (FeynCalc`EpsContractFreeQ`Private`a_)^
              (FeynCalc`EpsContractFreeQ`Private`b_Integer)?Positive /; 
              !FreeQ[FeynCalc`EpsContractFreeQ`Private`a, Eps] :> 
            FeynCalc`EpsContractFreeQ`Private`times @@ 
             Table[FeynCalc`EpsContractFreeQ`Private`a, 
              {FeynCalc`EpsContractFreeQ`Private`i, 
               FeynCalc`EpsContractFreeQ`Private`b}]; ]; 
       FeynCalc`EpsContractFreeQ`Private`ex = ExpandAll2[
         FeynCalc`EpsContractFreeQ`Private`ex]; 
       If[Head[FeynCalc`EpsContractFreeQ`Private`ex] === Plus, 
        FeynCalc`EpsContractFreeQ`Private`tmp = 
         (FeynCalc`EpsContractFreeQ`Private`head @@ Cases[#1, _Eps, 
             Infinity] & ) /@ List @@ FeynCalc`EpsContractFreeQ`Private`ex, 
        FeynCalc`EpsContractFreeQ`Private`tmp = 
         Cases[FeynCalc`EpsContractFreeQ`Private`ex, _Eps, Infinity]]; 
       FeynCalc`EpsContractFreeQ`Private`tmp = 
        FeynCalc`EpsContractFreeQ`Private`tmp /. 
         FeynCalc`EpsContractFreeQ`Private`head[] | 
           FeynCalc`EpsContractFreeQ`Private`head[_] :> 
          Unevaluated[Sequence[]]; FeynCalc`EpsContractFreeQ`Private`tmp === 
        {}] /;  !FreeQ[FeynCalc`EpsContractFreeQ`Private`expr, Eps]
 
EpsContractFreeQ /: EpsContractFreeQ::usage = "EpsContractFreeQ[exp] returns \
True if the expression contains epsilon tensors\nthat can be contracted with \
each other. The function is optimized for large\nexpressions, i.e. it is not \
so good as a criterion in e.g. Select."
 
FeynCalc`PauliTrick`Private`insidePauliTrace /: 
    FeynCalc`PauliTrick`Private`insidePauliTrace::usage = ""
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[Dot[]] := 1
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     PauliChain[FeynCalc`PauliTrick`Private`x_, 
      FeynCalc`PauliTrick`Private`i_, FeynCalc`PauliTrick`Private`j_]] := 
    PauliChain[FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
      FeynCalc`PauliTrick`Private`x], FeynCalc`PauliTrick`Private`i, 
     FeynCalc`PauliTrick`Private`j]
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[FeynCalc`PauliTrick`Private`ex:
      PauliSigma[__]] := FeynCalc`PauliTrick`Private`ex /; 
      !FeynCalc`PauliTrick`Private`insidePauliTrace
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     PauliSigma[_CartesianMomentum | _CartesianIndex, ___]] := 
    0 /; FeynCalc`PauliTrick`Private`insidePauliTrace
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[FeynCalc`PauliTrick`Private`ex:
      PauliSigma[_Momentum | _LorentzIndex, ___]] := 
    FeynCalc`PauliTrick`Private`ex /; 
     FeynCalc`PauliTrick`Private`insidePauliTrace
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     (FeynCalc`PauliTrick`Private`b___) . PauliSigma[
       FeynCalc`PauliTrick`Private`l_LorentzIndex, 
       FeynCalc`PauliTrick`Private`dim_:3] . 
      PauliSigma[FeynCalc`PauliTrick`Private`l_LorentzIndex, 
       FeynCalc`PauliTrick`Private`dim_:3] . 
      (FeynCalc`PauliTrick`Private`d___)] := 
    (FeynCalc`Package`MetricT + FeynCalc`Package`MetricS*
        FeynCalc`PauliTrick`Private`dim)*
      FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
       DOT[FeynCalc`PauliTrick`Private`b, FeynCalc`PauliTrick`Private`d]] /; 
      !MatchQ[FeynCalc`PauliTrick`Private`dim, _Symbol - 4]
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     (FeynCalc`PauliTrick`Private`b___) . PauliSigma[
       FeynCalc`PauliTrick`Private`l_LorentzIndex, 
       -4 + (FeynCalc`PauliTrick`Private`dim_Symbol)] . 
      PauliSigma[FeynCalc`PauliTrick`Private`l_LorentzIndex, 
       -4 + (FeynCalc`PauliTrick`Private`dim_Symbol)] . 
      (FeynCalc`PauliTrick`Private`d___)] := FeynCalc`Package`MetricS*
     (FeynCalc`PauliTrick`Private`dim - 4)*
     FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
      DOT[FeynCalc`PauliTrick`Private`b, FeynCalc`PauliTrick`Private`d]]
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     (FeynCalc`PauliTrick`Private`b___) . PauliSigma[
       FeynCalc`PauliTrick`Private`l_CartesianIndex, 
       FeynCalc`PauliTrick`Private`dim_:3] . 
      PauliSigma[FeynCalc`PauliTrick`Private`l_CartesianIndex, 
       FeynCalc`PauliTrick`Private`dim_:3] . 
      (FeynCalc`PauliTrick`Private`d___)] := FeynCalc`PauliTrick`Private`dim*
     FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
      DOT[FeynCalc`PauliTrick`Private`b, FeynCalc`PauliTrick`Private`d]]
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     (FeynCalc`PauliTrick`Private`b___) . PauliSigma[
       FeynCalc`PauliTrick`Private`c_Momentum, 
       FeynCalc`PauliTrick`Private`dim___] . 
      PauliSigma[FeynCalc`PauliTrick`Private`c_Momentum, 
       FeynCalc`PauliTrick`Private`dim___] . 
      (FeynCalc`PauliTrick`Private`d___)] := 
    FCUseCache[ExpandScalarProduct, {Pair[FeynCalc`PauliTrick`Private`c, 
        FeynCalc`PauliTrick`Private`c]}, {}]*
     FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
      DOT[FeynCalc`PauliTrick`Private`b, FeynCalc`PauliTrick`Private`d]]
 
FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
     (FeynCalc`PauliTrick`Private`b___) . PauliSigma[
       FeynCalc`PauliTrick`Private`c_CartesianMomentum, 
       FeynCalc`PauliTrick`Private`dim___] . 
      PauliSigma[FeynCalc`PauliTrick`Private`c_CartesianMomentum, 
       FeynCalc`PauliTrick`Private`dim___] . 
      (FeynCalc`PauliTrick`Private`d___)] := 
    FCUseCache[ExpandScalarProduct, 
      {CartesianPair[FeynCalc`PauliTrick`Private`c, 
        FeynCalc`PauliTrick`Private`c]}, {}]*
     FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
      DOT[FeynCalc`PauliTrick`Private`b, FeynCalc`PauliTrick`Private`d]]
 
FeynCalc`PauliTrace`Private`pauliTraceEvaluate[
     FeynCalc`PauliTrace`Private`expr_ /; 
      FreeQ[FeynCalc`PauliTrace`Private`expr, PauliSigma], 
     OptionsPattern[]] := FeynCalc`PauliTrace`Private`unitMatrixTrace*
     FeynCalc`PauliTrace`Private`expr
 
FeynCalc`PauliTrace`Private`pauliTraceEvaluate[
     FeynCalc`PauliTrace`Private`expr_ /; 
       !FreeQ[FeynCalc`PauliTrace`Private`expr, PauliSigma], 
     FeynCalc`PauliTrace`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`PauliTrace`Private`paulitrres, 
      FeynCalc`PauliTrace`Private`tmp = FeynCalc`PauliTrace`Private`expr, 
      FeynCalc`PauliTrace`Private`paulitrfact, 
      FeynCalc`PauliTrace`Private`paulitrcoll, 
      FeynCalc`PauliTrace`Private`ptmp, FeynCalc`PauliTrace`Private`pWrap, 
      FeynCalc`PauliTrace`Private`wrapRule, 
      FeynCalc`PauliTrace`Private`prepSpur, FeynCalc`PauliTrace`Private`time, 
      FeynCalc`PauliTrace`Private`time2, 
      FeynCalc`PauliTrace`Private`contract, 
      FeynCalc`PauliTrace`Private`spurHeadList, 
      FeynCalc`PauliTrace`Private`spurHeadListOdd, 
      FeynCalc`PauliTrace`Private`spurHeadListEven, 
      FeynCalc`PauliTrace`Private`sigmaFree, 
      FeynCalc`PauliTrace`Private`sigmaPart, 
      FeynCalc`PauliTrace`Private`traceListOdd, 
      FeynCalc`PauliTrace`Private`traceListEven, 
      FeynCalc`PauliTrace`Private`repRule, FeynCalc`PauliTrace`Private`null1, 
      FeynCalc`PauliTrace`Private`null2, 
      FeynCalc`PauliTrace`Private`dummyIndexFreeQ}, 
     FeynCalc`PauliTrace`Private`wrapRule = 
       {FeynCalc`PauliTrace`Private`pWrap[FeynCalc`PauliTrace`Private`a:
           _Momentum | _LorentzIndex, FeynCalc`PauliTrace`Private`d___] -> 
         PauliSigma[FeynCalc`PauliTrace`Private`a, 
          FeynCalc`PauliTrace`Private`d], FeynCalc`PauliTrace`Private`pWrap[
          _CartesianMomentum | _CartesianIndex, ___] -> 0}; 
      FeynCalc`PauliTrace`Private`paulitrfact = OptionValue[PauliTrace, 
        {FeynCalc`PauliTrace`Private`opts}, Factoring]; 
      FeynCalc`PauliTrace`Private`paulitrcoll = OptionValue[PauliTrace, 
        {FeynCalc`PauliTrace`Private`opts}, PairCollect]; 
      FeynCalc`PauliTrace`Private`contract = OptionValue[PauliTrace, 
        {FeynCalc`PauliTrace`Private`opts}, Contract]; 
      If[FeynCalc`PauliTrace`Private`paulitrfact === Automatic, 
       FeynCalc`PauliTrace`Private`paulitrfact = 
         Function[FeynCalc`PauliTrace`Private`x, 
          If[LeafCount[FeynCalc`PauliTrace`Private`x] < 5000, 
           Factor[FeynCalc`PauliTrace`Private`x], 
           FeynCalc`PauliTrace`Private`x]]; ]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Entering", 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrace: pauliTraceEvaluate: Entering with: ", 
       FeynCalc`PauliTrace`Private`expr, FCDoControl -> 
        FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Checking if there are \
indices that need to be contracted. ", FCDoControl -> 
        FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`dummyIndexFreeQ = DummyIndexFreeQ[
        FeynCalc`PauliTrace`Private`tmp, {LorentzIndex, CartesianIndex}]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Check done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Applying PauliTrick.", 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`tmp = PauliTrick[
        FeynCalc`PauliTrace`Private`tmp, FCI -> True, InsidePauliTrace -> 
         True, FCPauliIsolate -> False]; FCPrint[1, 
       "PauliTrace: pauliTraceEvaluate: PauliTrick done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrace: pauliTraceEvaluate: After PauliTrick: ", 
       FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
        FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
      If[ !FreeQ[FeynCalc`PauliTrace`Private`tmp, PauliSigma], 
       FCPrint[1, "PauliTrace: pauliTraceEvaluate: Calculating the trace.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Applying Dotsimplify.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = DotSimplify[
          FeynCalc`PauliTrace`Private`tmp, Expanding -> True]; 
        FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: Dotsimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: After Dotsimplify: ", 
         FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Applying PauliTrick.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = PauliTrick[
          FeynCalc`PauliTrace`Private`tmp, FCI -> True, InsidePauliTrace -> 
           True, FCJoinDOTs -> False]; FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: PauliTrick done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: After PauliTrick: ", 
         FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = FeynCalc`PauliTrace`Private`tmp /. 
           {PauliSigma -> FeynCalc`PauliTrace`Private`pWrap} /. 
          DOT -> FeynCalc`PauliTrace`Private`prepSpur; 
        FeynCalc`PauliTrace`Private`tmp = FeynCalc`PauliTrace`Private`tmp /. 
          FeynCalc`PauliTrace`Private`prepSpur[
            FeynCalc`PauliTrace`Private`zzz__] :> 
           FeynCalc`PauliTrace`Private`spurHead @@ 
            ({FeynCalc`PauliTrace`Private`zzz} /. 
             {FeynCalc`PauliTrace`Private`pWrap -> PauliSigma}); 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: Wrapped in spurHead: ", 
         FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = FeynCalc`PauliTrace`Private`tmp /. 
          FeynCalc`PauliTrace`Private`spurHead[
             FeynCalc`PauliTrace`Private`x__] /; 
             !NonCommFreeQ[{FeynCalc`PauliTrace`Private`x} /. PauliSigma -> 
                FeynCalc`PauliTrace`Private`null1] :> 
           FeynCalc`PauliTrace`Private`noSpur[FeynCalc`PauliTrace`Private`x]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: Trace contains unknown \
non-commutative objects: ",  !FreeQ[FeynCalc`PauliTrace`Private`tmp, 
           FeynCalc`PauliTrace`Private`noSpur], FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = FeynCalc`PauliTrace`Private`tmp /. 
          FeynCalc`PauliTrace`Private`spurHead[
             FeynCalc`PauliTrace`Private`x__] /; 
             !FreeQ2[{FeynCalc`PauliTrace`Private`x}, {Momentum, 
               LorentzIndex}] :> FeynCalc`PauliTrace`Private`noSpur[
            FeynCalc`PauliTrace`Private`x]; 
        If[FeynCalc`PauliTrace`Private`optSort, 
         FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
          FCPrint[1, "PauliTrace: pauliTraceEvaluate: Applying the cyclicity \
of the trace to sort the matrices canonically.", FCDoControl -> 
            FeynCalc`PauliTrace`Private`paTrVerbose]; 
          FeynCalc`PauliTrace`Private`tmp = 
           FeynCalc`PauliTrace`Private`tmp /. 
            FeynCalc`PauliTrace`Private`spurHead[
               FeynCalc`PauliTrace`Private`x__] /; FCGetDimensions[
                {FeynCalc`PauliTrace`Private`x}] === {3} -> 
             FeynCalc`PauliTrace`Private`orderSpurHead[
              FeynCalc`PauliTrace`Private`x]; 
          If[ !FreeQ[FeynCalc`PauliTrace`Private`tmp, 
             FeynCalc`PauliTrace`Private`orderSpurHead], 
           Message[PauliTrace::failmsg, 
             "Sorting matrices inside Pauli traces failed."]; Abort[]]; 
          FCPrint[1, "PauliTrace: pauliTraceEvaluate: Done sorting matrices \
canonically, timing: ", N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 
            4], FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
          FCPrint[3, "PauliTrace: pauliTraceEvaluate: After sorting matrices \
canonically: ", FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
            FeynCalc`PauliTrace`Private`paTrVerbose]]; 
        {FeynCalc`PauliTrace`Private`sigmaFree, 
          FeynCalc`PauliTrace`Private`sigmaPart} = 
         FCSplit[FeynCalc`PauliTrace`Private`tmp, 
          {FeynCalc`PauliTrace`Private`spurHead}]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: sigmaFree: ", 
         FeynCalc`PauliTrace`Private`sigmaFree, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: sigmaPart: ", 
         FeynCalc`PauliTrace`Private`sigmaPart, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        If[FeynCalc`PauliTrace`Private`sigmaPart =!= 0, 
         Scan[If[ !MatchQ[#1, (FeynCalc`PauliTrace`Private`a_.)*
                 FeynCalc`PauliTrace`Private`spurHead[
                  FeynCalc`PauliTrace`Private`b__] /; 
                FreeQ[{FeynCalc`PauliTrace`Private`a, 
                   FeynCalc`PauliTrace`Private`b}, 
                  FeynCalc`PauliTrace`Private`spurHead] && 
                  !FreeQ[{FeynCalc`PauliTrace`Private`b}, PauliSigma]], 
             Message[PauliTrace::failmsg, "Irregular trace structure in ", 
               ToString[#1, InputForm]]; Abort[]] & , 
           FeynCalc`PauliTrace`Private`sigmaPart + 
            FeynCalc`PauliTrace`Private`spurHead[PauliSigma]]; ]; 
        FeynCalc`PauliTrace`Private`spurHeadList = 
         Union[Cases[FeynCalc`PauliTrace`Private`sigmaPart + 
            FeynCalc`PauliTrace`Private`null1 + 
            FeynCalc`PauliTrace`Private`null2, 
           FeynCalc`PauliTrace`Private`spurHead[__], Infinity]]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: spurHeadList", 
         FeynCalc`PauliTrace`Private`spurHeadList, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        Scan[If[ !MatchQ[#1, FeynCalc`PauliTrace`Private`spurHead[
              PauliSigma[_[_, ___], ___]...]], Message[PauliTrace::failmsg, 
             "Traces are not in the proper form."]; Abort[]] & , 
         FeynCalc`PauliTrace`Private`spurHeadList]; 
        FeynCalc`PauliTrace`Private`spurHeadListOdd = 
         Select[FeynCalc`PauliTrace`Private`spurHeadList, 
          OddQ[Length[#1]] & ]; 
        FeynCalc`PauliTrace`Private`spurHeadListEven = 
         Complement[FeynCalc`PauliTrace`Private`spurHeadList, 
          FeynCalc`PauliTrace`Private`spurHeadListOdd]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: spurHeadListOdd: ", 
         FeynCalc`PauliTrace`Private`spurHeadListOdd, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: spurHeadListEven: ", 
         FeynCalc`PauliTrace`Private`spurHeadListEven, 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        If[FeynCalc`PauliTrace`Private`spurHeadList =!= 
          Union[Join[FeynCalc`PauliTrace`Private`spurHeadListOdd, 
            FeynCalc`PauliTrace`Private`spurHeadListEven]], 
         Message[PauliTrace::failmsg, 
           "Splitting between odd and even traces failed"]; Abort[]]; 
        Scan[If[Length[FCGetDimensions[#1]] =!= 1, 
           Message[PauliTrace::mixmsg]; Abort[]] & , 
         FeynCalc`PauliTrace`Private`spurHeadList]; 
        FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: Calculating even traces.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`traceListEven = 
         FeynCalc`PauliTrace`Private`spurHeadListEven /. 
          FeynCalc`PauliTrace`Private`spurHead -> 
           FeynCalc`PauliTrace`Private`spurEven; FCPrint[1, "PauliTrace: \
pauliTraceEvaluate: Done calculating even traces, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: traceListEven", 
         FeynCalc`PauliTrace`Private`traceListEven, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        If[ !FreeQ2[FeynCalc`PauliTrace`Private`traceListEven, 
           {FeynCalc`PauliTrace`Private`spurHead, PauliSigma}], 
         Message[PauliTrace::failmsg, "Not all even traces were evaluated."]; 
          Abort[]]; FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Calculating odd traces.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`traceListOdd = 
         FeynCalc`PauliTrace`Private`spurHeadListOdd /. 
          FeynCalc`PauliTrace`Private`spurHead[
             FeynCalc`PauliTrace`Private`x__] /; 
            FCGetDimensions[{FeynCalc`PauliTrace`Private`x}] === {3} :> 
           FeynCalc`PauliTrace`Private`spurOddIn3Dim[
            FeynCalc`PauliTrace`Private`x]; 
        If[ !FreeQ[FeynCalc`PauliTrace`Private`traceListOdd, 
           FeynCalc`PauliTrace`Private`spurHead], 
         Switch[FeynCalc`Package`PauliSigmaScheme, "None", 
          FeynCalc`PauliTrace`Private`traceListOdd = 
           FeynCalc`PauliTrace`Private`traceListOdd /. 
            FeynCalc`PauliTrace`Private`spurHead -> 
             FeynCalc`PauliTrace`Private`noSpur, "Naive", 
          FeynCalc`PauliTrace`Private`traceListOdd = 
           FeynCalc`PauliTrace`Private`traceListOdd /. 
            FeynCalc`PauliTrace`Private`spurHead -> 
             FeynCalc`PauliTrace`Private`noSpur, _, 
          Message[PauliTrace::failmsg, "Unknown scheme for handling Pauli \
matrices in dimensional regularization."]; Abort[]]]; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Done calculating odd \
traces, timing: ", N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: traceListOdd", 
         FeynCalc`PauliTrace`Private`traceListOdd, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        If[ !FreeQ2[FeynCalc`PauliTrace`Private`traceListOdd /. 
            _FeynCalc`PauliTrace`Private`noSpur :> 1, 
           {FeynCalc`PauliTrace`Private`spurHead, PauliSigma, 
            FeynCalc`PauliTrace`Private`traceOdd}], 
         Print[FeynCalc`PauliTrace`Private`traceListOdd]; 
          Message[PauliTrace::failmsg, "Not all odd traces were evaluated."]; 
          Abort[]]; FeynCalc`PauliTrace`Private`traceListOdd = 
         FeynCalc`PauliTrace`Private`traceListOdd /. 
          FeynCalc`PauliTrace`Private`leviCivitaSign -> $LeviCivitaSign; 
        If[OptionValue[PauliTrace, {FeynCalc`PauliTrace`Private`opts}, 
           Expand] &&  !FreeQ[{FeynCalc`PauliTrace`Private`traceListEven, 
             FeynCalc`PauliTrace`Private`traceListOdd, 
             FeynCalc`PauliTrace`Private`sigmaFree, 
             FeynCalc`PauliTrace`Private`sigmaPart}, Momentum], 
         FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
          FCPrint[1, 
           "PauliTrace: pauliTraceEvaluate: Expanding scalar products", 
           FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
          FeynCalc`PauliTrace`Private`traceListEven = 
           (ExpandScalarProduct[#1, FCI -> True] & ) /@ 
            FeynCalc`PauliTrace`Private`traceListEven; 
          FeynCalc`PauliTrace`Private`traceListOdd = 
           (ExpandScalarProduct[#1, FCI -> True] & ) /@ 
            FeynCalc`PauliTrace`Private`traceListOdd; 
          FeynCalc`PauliTrace`Private`sigmaFree = ExpandScalarProduct[
            FeynCalc`PauliTrace`Private`sigmaFree, FCI -> True]; 
          FeynCalc`PauliTrace`Private`sigmaPart = ExpandScalarProduct[
            FeynCalc`PauliTrace`Private`sigmaPart, FCI -> True]; 
          FCPrint[1, "PauliTrace: pauliTraceEvaluate: Done expanding the \
result, timing: ", N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 4], 
           FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]]; 
        FeynCalc`PauliTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: Rebuilding the full result.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`repRule = 
         Thread[FeynCalc`PauliTrace`Private`spurHeadListOdd -> 
           FeynCalc`PauliTrace`Private`traceListOdd]; 
        FeynCalc`PauliTrace`Private`repRule = 
         Join[FeynCalc`PauliTrace`Private`repRule, 
          Thread[FeynCalc`PauliTrace`Private`spurHeadListEven -> 
            FeynCalc`PauliTrace`Private`traceListEven]]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: repRule: ", 
         FeynCalc`PauliTrace`Private`traceListOdd, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = 
         (FeynCalc`PauliTrace`Private`sigmaFree /. 
           FeynCalc`PauliTrace`Private`wrapRule) + 
          (FeynCalc`PauliTrace`Private`sigmaPart /. 
           Dispatch[FeynCalc`PauliTrace`Private`repRule]); 
        FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: Full result ready, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: tmp: ", 
         FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        If[ !FreeQ2[FeynCalc`PauliTrace`Private`tmp /. 
            _FeynCalc`PauliTrace`Private`noSpur :> 1, 
           {FeynCalc`PauliTrace`Private`spurHead, PauliSigma}], 
         Message[PauliTrace::failmsg, 
           "Something went wrong while substituting trace results."]; 
          Abort[]]; ]; FCPrint[1, 
       "PauliTrace: pauliTraceEvaluate: Main part finished, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      If[ !FreeQ[FeynCalc`PauliTrace`Private`tmp /. 
          _FeynCalc`PauliTrace`Private`noSpur :> 1, PauliSigma], 
       Message[PauliTrace::failmsg, 
         "The output still contains Pauli matrices"]; Abort[]]; 
      If[FeynCalc`PauliTrace`Private`contract === True && 
         !FeynCalc`PauliTrace`Private`dummyIndexFreeQ, 
       FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: Contracting Lorentz indices. ", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = Contract[
          FeynCalc`PauliTrace`Private`tmp, FCI -> True]; 
        FCPrint[3, "PauliTrace: pauliTraceEvaluate: After Contract: ", 
         FeynCalc`PauliTrace`Private`tmp, FCDoControl -> 
          FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Contract done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]]; 
      If[ !FreeQ[FeynCalc`PauliTrace`Private`tmp, Eps], 
       FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Treating Eps tensors.", 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`tmp = Expand[EpsEvaluate[
           FeynCalc`PauliTrace`Private`tmp, FCI -> True, 
           EpsExpand -> OptionValue[PauliTrace, 
             {FeynCalc`PauliTrace`Private`opts}, EpsExpand]]]; 
        If[FeynCalc`PauliTrace`Private`contract === True || 
          (NumberQ[FeynCalc`PauliTrace`Private`contract] && 
           LeafCount[FeynCalc`PauliTrace`Private`tmp] < 
            FeynCalc`PauliTrace`Private`contract), 
         FeynCalc`PauliTrace`Private`tmp = Contract[
            FeynCalc`PauliTrace`Private`tmp, EpsContract -> 
             OptionValue[PauliTrace, {FeynCalc`PauliTrace`Private`opts}, 
              EpsContract], Expanding -> False, FCI -> True, 
            EpsExpand -> OptionValue[PauliTrace, 
              {FeynCalc`PauliTrace`Private`opts}, EpsExpand]]; ]; ]; 
      FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Factoring the result.", 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      If[FeynCalc`PauliTrace`Private`paulitrfact === True, 
       FeynCalc`PauliTrace`Private`paulitrres = 
        Factor2[FeynCalc`PauliTrace`Private`unitMatrixTrace*
          FeynCalc`PauliTrace`Private`tmp], 
       If[FeynCalc`PauliTrace`Private`paulitrfact === False, 
        FeynCalc`PauliTrace`Private`paulitrres = 
         FeynCalc`PauliTrace`Private`unitMatrixTrace*
          FeynCalc`PauliTrace`Private`tmp, 
        FeynCalc`PauliTrace`Private`paulitrres = 
         FeynCalc`PauliTrace`Private`paulitrfact[
          FeynCalc`PauliTrace`Private`unitMatrixTrace*
           FeynCalc`PauliTrace`Private`tmp]]]; 
      FCPrint[3, "PauliTrace: pauliTraceEvaluate: After factoring: ", 
       FeynCalc`PauliTrace`Private`paulitrres, FCDoControl -> 
        FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Factoring done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`paulitrpc[
        FeynCalc`PauliTrace`Private`x__] := 
       Plus[FeynCalc`PauliTrace`Private`x] /; 
        FreeQ[{FeynCalc`PauliTrace`Private`x}, Pair]; 
      If[FeynCalc`PauliTrace`Private`paulitrcoll === True, 
       FeynCalc`PauliTrace`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "PauliTrace: pauliTraceEvaluate: Collecting the result w.r.t Pairs."\
, FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
        FeynCalc`PauliTrace`Private`paulitrpc[
          FeynCalc`PauliTrace`Private`x__] := Collect2[
          Plus[FeynCalc`PauliTrace`Private`x], Pair, Factoring -> False]; 
        FeynCalc`PauliTrace`Private`paulitrres = 
         FeynCalc`PauliTrace`Private`paulitrres /. 
          Plus -> FeynCalc`PauliTrace`Private`paulitrpc; 
        FCPrint[1, "PauliTrace: pauliTraceEvaluate: Collecting done, timing", 
         N[AbsoluteTime[] - FeynCalc`PauliTrace`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; ]; 
      FCPrint[1, "PauliTrace: pauliTraceEvaluate: Leaving.", 
       FCDoControl -> FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrace: pauliTraceEvaluate: Leaving with: ", 
       FeynCalc`PauliTrace`Private`paulitrres, FCDoControl -> 
        FeynCalc`PauliTrace`Private`paTrVerbose]; 
      FeynCalc`PauliTrace`Private`paulitrres]
 
PairCollect /: PairCollect::usage = "PairCollect is an option for DiracTrace \
specifying if the result is collected\nwith respect to Pairs."
 
PauliTrick[FeynCalc`PauliTrick`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`PauliTrick`Private`res, FeynCalc`PauliTrick`Private`tmp, 
      FeynCalc`PauliTrick`Private`ex, FeynCalc`PauliTrick`Private`null1, 
      FeynCalc`PauliTrick`Private`null2, FeynCalc`PauliTrick`Private`holdDOT, 
      FeynCalc`PauliTrick`Private`freePart, 
      FeynCalc`PauliTrick`Private`paPart, 
      FeynCalc`PauliTrick`Private`pauliObjects, 
      FeynCalc`PauliTrick`Private`pauliObjectsEval, 
      FeynCalc`PauliTrick`Private`repRule, FeynCalc`PauliTrick`Private`time, 
      FeynCalc`PauliTrick`Private`paHead}, 
     FeynCalc`PauliTrick`Private`optJoin = OptionValue[FCJoinDOTs]; 
      FeynCalc`PauliTrick`Private`pauliReduce = OptionValue[PauliReduce]; 
      FeynCalc`PauliTrick`Private`insidePauliTrace = 
       OptionValue[InsidePauliTrace]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`PauliTrick`Private`paTrVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`PauliTrick`Private`paTrVerbose = OptionValue[
           FCVerbose]]; ]; FCPrint[1, "PauliTrick. Entering.", 
       FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrick: Entering with ", 
       FeynCalc`PauliTrick`Private`expr, FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; If[OptionValue[FCI], 
       FeynCalc`PauliTrick`Private`ex = FeynCalc`PauliTrick`Private`expr, 
       FeynCalc`PauliTrick`Private`ex = 
        FCI[FeynCalc`PauliTrick`Private`expr]]; 
      If[FreeQ2[FeynCalc`PauliTrick`Private`ex, 
        FeynCalc`Package`PauliHeadsList], 
       Return[FeynCalc`PauliTrick`Private`ex]]; 
      If[OptionValue[FCPauliIsolate], FCPrint[1, "PauliTrick: Normal mode.", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`time = AbsoluteTime[]; 
        FCPrint[1, "PauliTrick: Extracting Pauli objects.", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`ex = FCPauliIsolate[
          FeynCalc`PauliTrick`Private`ex, FCI -> True, 
          Head -> FeynCalc`PauliTrick`Private`paHead, DotSimplify -> True, 
          PauliSigmaCombine -> OptionValue[PauliSigmaCombine], 
          LorentzIndex -> True, FCJoinDOTs -> 
           FeynCalc`PauliTrick`Private`optJoin, PauliChain -> 
           OptionValue[PauliChain]]; {FeynCalc`PauliTrick`Private`freePart, 
          FeynCalc`PauliTrick`Private`paPart} = 
         FCSplit[FeynCalc`PauliTrick`Private`ex, 
          {FeynCalc`PauliTrick`Private`paHead}]; FCPrint[3, 
         "PauliTrick: paPart: ", FeynCalc`PauliTrick`Private`paPart, 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrick: freePart: ", 
         FeynCalc`PauliTrick`Private`freePart, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FCPrint[1, "PauliTrick: Done extracting Pauli objects, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`pauliObjects = 
         Union[Cases[FeynCalc`PauliTrick`Private`paPart + 
            FeynCalc`PauliTrick`Private`null1 + 
            FeynCalc`PauliTrick`Private`null2, 
           FeynCalc`PauliTrick`Private`paHead[_], Infinity]]; 
        FCPrint[3, "PauliTrick: pauliObjects: ", 
         FeynCalc`PauliTrick`Private`pauliObjects, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`time = AbsoluteTime[]; 
        FCPrint[1, "PauliTrick: Applying pauliTrickEval", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`pauliObjectsEval = 
         (FeynCalc`PauliTrick`Private`pauliTrickEvalFast[#1] /. 
            FeynCalc`PauliTrick`Private`pauliTrickEvalFast -> 
             FeynCalc`PauliTrick`Private`pauliTrickEval & ) /@ 
          (FeynCalc`PauliTrick`Private`pauliObjects /. 
           FeynCalc`PauliTrick`Private`paHead -> Identity); 
        FCPrint[3, "PauliTrick: After pauliTrickEval: ", 
         FeynCalc`PauliTrick`Private`pauliObjectsEval, 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FCPrint[1, "PauliTrick: pauliTrickEval done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        If[ !FreeQ2[FeynCalc`PauliTrick`Private`pauliObjectsEval, 
           {FeynCalc`PauliTrick`Private`pauliTrickEvalFast, 
            FeynCalc`PauliTrick`Private`pauliTrickEval, 
            FeynCalc`PauliTrick`Private`holdDOT}], 
         Message[PauliTrick::failmsg, 
           "Evaluation of isolated objects failed."]; Abort[]]; 
        FCPrint[1, "PauliTrick: Inserting Pauli objects back.", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`time = AbsoluteTime[]; 
        FeynCalc`PauliTrick`Private`repRule = 
         Thread[FeynCalc`PauliTrick`Private`pauliObjects -> 
           FeynCalc`PauliTrick`Private`pauliObjectsEval]; 
        FCPrint[3, "PauliTrick: repRule: ", 
         FeynCalc`PauliTrick`Private`repRule, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = 
         FeynCalc`PauliTrick`Private`freePart + 
          (FeynCalc`PauliTrick`Private`paPart /. Dispatch[
            FeynCalc`PauliTrick`Private`repRule]); 
        FCPrint[1, "PauliTrick: Done inserting Pauli objects back, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose], 
       FCPrint[1, "PauliTrick: Fast mode.", FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = 
         FeynCalc`PauliTrick`Private`pauliTrickEvalFast[
          FeynCalc`PauliTrick`Private`ex]; FCPrint[3, 
         "PauliTrick: After pauliTrickEvalFast: ", 
         FeynCalc`PauliTrick`Private`res, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]; 
        If[ !FreeQ2[FeynCalc`PauliTrick`Private`res, 
           {FeynCalc`Package`PauliHeadsList, 
            FeynCalc`PauliTrick`Private`pauliTrickEvalFast}], 
         FeynCalc`PauliTrick`Private`res = FeynCalc`PauliTrick`Private`res /. 
           FeynCalc`PauliTrick`Private`pauliTrickEvalFast -> 
            FeynCalc`PauliTrick`Private`pauliTrickEval]; 
        If[ !FreeQ2[FeynCalc`PauliTrick`Private`res, 
           {FeynCalc`PauliTrick`Private`pauliTrickEvalFast, 
            FeynCalc`PauliTrick`Private`pauliTrickEval, 
            FeynCalc`PauliTrick`Private`holdDOT}], 
         Message[PauliTrick::failmsg, 
           "Evaluation of isolated objects failed."]; Abort[]]]; 
      If[OptionValue[Expanding], FeynCalc`PauliTrick`Private`time = 
         AbsoluteTime[]; FCPrint[1, "PauliTrick: Expanding the result.", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = 
         Expand[FeynCalc`PauliTrick`Private`res]; 
        FCPrint[1, "PauliTrick: Expanding done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrick: After expanding: ", 
         FeynCalc`PauliTrick`Private`res, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]]; 
      If[OptionValue[FCE], FeynCalc`PauliTrick`Private`res = 
        FCE[FeynCalc`PauliTrick`Private`res]]; 
      FCPrint[1, "PauliTrick. Leaving.", FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrick: Leaving with ", 
       FeynCalc`PauliTrick`Private`res, FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FeynCalc`PauliTrick`Private`res]
 
Options[PauliTrick] = {Expanding -> False, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCJoinDOTs -> False, FCPauliIsolate -> True, 
     FCVerbose -> False, InsidePauliTrace -> False, PauliChain -> True, 
     PauliSigmaCombine -> False, PauliReduce -> False}
 
PauliTrick /: PauliTrick::failmsg = "Error! PauliTrick has encountered a \
fatal problem and must abort the computation. The problem reads: `1`"
 
PauliTrick /: PauliTrick::usage = "PauliTrick[exp] contracts $\\sigma$ \
matrices with each other and performs\nseveral simplifications (no expansion, \
use PauliSimplify for this)."
 
FeynCalc`PauliTrick`Private`optJoin /: 
    FeynCalc`PauliTrick`Private`optJoin::usage = ""
 
FeynCalc`PauliTrick`Private`pauliReduce /: 
    FeynCalc`PauliTrick`Private`pauliReduce::usage = ""
 
PauliReduce /: PauliReduce::usage = "PauliReduce is an option for PauliTrick \
and other functions. It specifies\nwhether a chain of Pauli matrices should \
be reduced to at most one matrix by\nrewriting every pair of matrices in \
terms of commutator and anticommutator."
 
InsidePauliTrace /: InsidePauliTrace::usage = "InsidePauliTrace is an option \
of PauliSimplify and some other functions\ndealing with Pauli algebra. If set \
to True, the function assumes to operate\ninside a Pauli trace."
 
FeynCalc`PauliTrick`Private`paTrVerbose /: 
    FeynCalc`PauliTrick`Private`paTrVerbose::usage = ""
 
FeynCalc`PauliTrick`Private`pauliTrickEval[FeynCalc`PauliTrick`Private`ex_ /; 
      Head[FeynCalc`PauliTrick`Private`ex] =!= PauliSigma] := 
    Which[FeynCalc`Package`PauliSigmaScheme === "None" && 
       FeynCalc`PauliTrick`Private`insidePauliTrace, 
      FeynCalc`PauliTrick`Private`pauliTrickEvalCachedNoneInsideTrace[
       FeynCalc`PauliTrick`Private`ex], FeynCalc`Package`PauliSigmaScheme === 
        "Naive" && FeynCalc`PauliTrick`Private`insidePauliTrace, 
      FeynCalc`PauliTrick`Private`pauliTrickEvalCachedNaiveInsideTrace[
       FeynCalc`PauliTrick`Private`ex], FeynCalc`Package`PauliSigmaScheme === 
       "None", 
      FeynCalc`PauliTrick`Private`pauliTrickEvalCachedNoneInsideTrace[
       FeynCalc`PauliTrick`Private`ex], FeynCalc`Package`PauliSigmaScheme === 
       "Naive", 
      FeynCalc`PauliTrick`Private`pauliTrickEvalCachedNaiveInsideTrace[
       FeynCalc`PauliTrick`Private`ex], True, 
      Message[PauliTrick::failmsg, "Unknown scheme for Pauli matrices"]; 
       Abort[]] /; FeynCalc`PauliTrick`Private`ex =!= 0
 
FeynCalc`Package`PauliSigmaScheme = "None"
 
FeynCalc`PauliTrick`Private`pauliTrickEvalCachedNoneInsideTrace[
     FeynCalc`PauliTrick`Private`x_] := 
    FeynCalc`PauliTrick`Private`pauliTrickEvalInternal[
     FeynCalc`PauliTrick`Private`x]
 
FeynCalc`PauliTrick`Private`pauliTrickEvalInternal[
     FeynCalc`PauliTrick`Private`ex_ /; 
      Head[FeynCalc`PauliTrick`Private`ex] =!= PauliSigma] := 
    Block[{FeynCalc`PauliTrick`Private`res = FeynCalc`PauliTrick`Private`ex, 
      FeynCalc`PauliTrick`Private`holdDOT, FeynCalc`PauliTrick`Private`time, 
      FeynCalc`PauliTrick`Private`dim, 
      FeynCalc`PauliTrick`Private`noncommPresent, 
      FeynCalc`PauliTrick`Private`null1, FeynCalc`PauliTrick`Private`null2, 
      FeynCalc`PauliTrick`Private`paHead}, 
     FCPrint[1, "PauliTrick: pauliTrickEval: Entering.", 
       FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrick: pauliTrickEval: Entering with", 
       FeynCalc`PauliTrick`Private`ex, FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; 
      If[FeynCalc`PauliTrick`Private`insidePauliTrace, 
       FeynCalc`PauliTrick`Private`time = AbsoluteTime[]; 
        FCPrint[2, 
         "DiracTrick: pauliTrickEval: Applying pauliTraceSimplify ", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = 
         FeynCalc`PauliTrick`Private`pauliTraceSimplify[
             FeynCalc`PauliTrick`Private`res] /. DOT -> 
             FeynCalc`PauliTrick`Private`holdDOT /. 
           FeynCalc`PauliTrick`Private`pauliTraceSimplify[
             FeynCalc`PauliTrick`Private`holdDOT[
              FeynCalc`PauliTrick`Private`x__]] :> 
            FeynCalc`PauliTrick`Private`pauliTraceSimplify[
             FeynCalc`PauliTrick`Private`x] /. 
          FeynCalc`PauliTrick`Private`pauliTraceSimplify -> 
           FeynCalc`PauliTrick`Private`holdDOT; FCPrint[1, 
         "PauliTrick: pauliTrickEval: pauliTraceSimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrick: pauliTrickEval: After pauliTraceSimplify ", 
         FeynCalc`PauliTrick`Private`res, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose], 
       FeynCalc`PauliTrick`Private`res = FeynCalc`PauliTrick`Private`res /. 
          DOT -> FeynCalc`PauliTrick`Private`holdDOT; ]; 
      If[ !FreeQ[FeynCalc`PauliTrick`Private`res, Pair], 
       FeynCalc`PauliTrick`Private`res = 
         Expand2[FeynCalc`PauliTrick`Private`res, Pair] /. 
           Pair -> PairContract /. PairContract -> Pair; ]; 
      If[ !FreeQ[FeynCalc`PauliTrick`Private`res, CartesianPair], 
       FeynCalc`PauliTrick`Private`res = 
         Expand2[FeynCalc`PauliTrick`Private`res, CartesianPair] /. 
           CartesianPair -> CartesianPairContract /. CartesianPairContract -> 
           CartesianPair; ]; If[FreeQ2[FeynCalc`PauliTrick`Private`res, 
        FeynCalc`Package`PauliHeadsList], 
       Return[FeynCalc`PauliTrick`Private`res]]; 
      FeynCalc`PauliTrick`Private`dim = FCGetDimensions[
        FeynCalc`PauliTrick`Private`res]; 
      FeynCalc`PauliTrick`Private`noncommPresent = 
        !NonCommFreeQ[FeynCalc`PauliTrick`Private`res /. 
          PauliSigma -> FeynCalc`PauliTrick`Private`pasi]; 
      FCPrint[3, 
       "PauliTrick: pauliTrickEval: unknown non-commutative objects present: \
", FeynCalc`PauliTrick`Private`noncommPresent, FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrick: pauliTrickEval: Dimensions: ", 
       FeynCalc`PauliTrick`Private`dim, FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FCPrint[1, "PauliTrick: pauliTrickEval: Doing simplifications.", 
       FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
      Which[MatchQ[FeynCalc`PauliTrick`Private`dim, {} | {3} | {4} | {3, 4}], 
       FCPrint[1, "PauliTrick: pauliTrickEval: Purely 4-dim.", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = FeynCalc`PauliTrick`Private`res /. 
           FeynCalc`PauliTrick`Private`holdDOT -> 
            FeynCalc`PauliTrick`Private`pauli4Dim /. 
          FeynCalc`PauliTrick`Private`pauli4Dim -> 
           FeynCalc`PauliTrick`Private`holdDOT; FCPrint[3, 
         "PauliTrick: pauliTrickEval: After pauli4Dim: ", 
         FeynCalc`PauliTrick`Private`res, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose], 
       MatchQ[FeynCalc`PauliTrick`Private`dim, {_Symbol - 1} | {_Symbol} | 
         {_Symbol, _Symbol - 1} | {_Symbol - 1, _Symbol}], 
       FCPrint[1, "PauliTrick: pauliTrickEval: Purely D-dim.", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = FeynCalc`PauliTrick`Private`res /. 
           FeynCalc`PauliTrick`Private`holdDOT -> 
            FeynCalc`PauliTrick`Private`pauliDDim /. 
          FeynCalc`PauliTrick`Private`pauliDDim -> 
           FeynCalc`PauliTrick`Private`holdDOT; FCPrint[3, 
         "PauliTrick: pauliTrickEval: After pauliDDim: ", 
         FeynCalc`PauliTrick`Private`res, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose], True, 
       Message[PauliTrick::failmsg, 
         "Unsupported combination of dimensions!"]; Abort[]]; 
      FCPrint[1, "PauliTrick: pauliTrickEval: Done with simplifications.", 
       FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FeynCalc`PauliTrick`Private`res = FeynCalc`PauliTrick`Private`res /. 
        FeynCalc`PauliTrick`Private`holdDOT -> DOT; 
      If[FeynCalc`PauliTrick`Private`insidePauliTrace && 
        FeynCalc`PauliTrick`Private`res =!= 0, 
       FeynCalc`PauliTrick`Private`time = AbsoluteTime[]; 
        FCPrint[2, 
         "DiracTrick: pauliTrickEval: Applying pauliTraceSimplify ", 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FeynCalc`PauliTrick`Private`res = 
         FeynCalc`PauliTrick`Private`pauliTraceSimplify[
              FeynCalc`PauliTrick`Private`res] /. DOT -> 
              FeynCalc`PauliTrick`Private`holdDOT /. 
            FeynCalc`PauliTrick`Private`pauliTraceSimplify[
              FeynCalc`PauliTrick`Private`holdDOT[
               FeynCalc`PauliTrick`Private`x__]] :> 
             FeynCalc`PauliTrick`Private`pauliTraceSimplify[
              FeynCalc`PauliTrick`Private`x] /. 
           FeynCalc`PauliTrick`Private`pauliTraceSimplify -> DOT /. 
          FeynCalc`PauliTrick`Private`holdDOT -> DOT; 
        FCPrint[1, 
         "PauliTrick: pauliTrickEval: pauliTraceSimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PauliTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
        FCPrint[3, "PauliTrick: pauliTrickEval: After pauliTraceSimplify ", 
         FeynCalc`PauliTrick`Private`res, FCDoControl -> 
          FeynCalc`PauliTrick`Private`paTrVerbose]]; 
      FCPrint[1, "PauliTrick: pauliTrickEval: Leaving.", 
       FCDoControl -> FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FCPrint[3, "PauliTrick: pauliTrickEval: Leaving with ", 
       FeynCalc`PauliTrick`Private`res, FCDoControl -> 
        FeynCalc`PauliTrick`Private`paTrVerbose]; 
      FeynCalc`PauliTrick`Private`res]
 
FeynCalc`PauliTrick`Private`pauliTraceSimplify[] := 1
 
FeynCalc`PauliTrick`Private`pauliTraceSimplify[___, 0, ___] := 0
 
FeynCalc`PauliTrick`Private`pauliTraceSimplify[
     PauliSigma[FeynCalc`PauliTrick`Private`c1:_CartesianMomentum | 
        _CartesianIndex, ___], PauliSigma[FeynCalc`PauliTrick`Private`c2:
       _CartesianMomentum | _CartesianIndex, ___]] := 
    FCUseCache[ExpandScalarProduct, 
     {CartesianPair[FeynCalc`PauliTrick`Private`c1, 
       FeynCalc`PauliTrick`Private`c2]}, {}]
 
FeynCalc`PauliTrick`Private`pasi /: FeynCalc`PauliTrick`Private`pasi::usage = 
     ""
 
FeynCalc`PauliTrick`Private`pauli4Dim[] := 1
 
FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b___, 
     PauliSigma[FeynCalc`PauliTrick`Private`c_Momentum], 
     PauliSigma[FeynCalc`PauliTrick`Private`c_Momentum], 
     FeynCalc`PauliTrick`Private`d___] := 
    FCUseCache[ExpandScalarProduct, {Pair[FeynCalc`PauliTrick`Private`c, 
        FeynCalc`PauliTrick`Private`c]}, {}]*
     FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b, 
      FeynCalc`PauliTrick`Private`d]
 
FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b___, 
     PauliSigma[FeynCalc`PauliTrick`Private`l_LorentzIndex], 
     PauliSigma[FeynCalc`PauliTrick`Private`l_LorentzIndex], 
     FeynCalc`PauliTrick`Private`d___] := 
    (FeynCalc`Package`MetricT + 3*FeynCalc`Package`MetricS)*
     FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b, 
      FeynCalc`PauliTrick`Private`d]
 
FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b___, 
     PauliSigma[FeynCalc`PauliTrick`Private`l_CartesianIndex], 
     PauliSigma[FeynCalc`PauliTrick`Private`l_CartesianIndex], 
     FeynCalc`PauliTrick`Private`d___] := 
    3*FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b, 
      FeynCalc`PauliTrick`Private`d]
 
FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b___, 
     PauliSigma[FeynCalc`PauliTrick`Private`c_CartesianMomentum], 
     PauliSigma[FeynCalc`PauliTrick`Private`c_CartesianMomentum], 
     FeynCalc`PauliTrick`Private`d___] := 
    FCUseCache[ExpandScalarProduct, 
      {CartesianPair[FeynCalc`PauliTrick`Private`c, 
        FeynCalc`PauliTrick`Private`c]}, {}]*
     FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b, 
      FeynCalc`PauliTrick`Private`d]
 
FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b___, 
      PauliSigma[FeynCalc`PauliTrick`Private`c1:_CartesianMomentum | 
         _CartesianIndex], PauliSigma[FeynCalc`PauliTrick`Private`c2:
        _CartesianMomentum | _CartesianIndex], 
      FeynCalc`PauliTrick`Private`d___] /; FeynCalc`PauliTrick`Private`c1 =!= 
      FeynCalc`PauliTrick`Private`c2 := 
    (FeynCalc`PauliTrick`Private`tmpli = CartesianIndex[$MU[Unique[]]]; 
      FCUseCache[ExpandScalarProduct, {CartesianPair[
             FeynCalc`PauliTrick`Private`c1, 
             FeynCalc`PauliTrick`Private`c2]}, {}]*
          FeynCalc`PauliTrick`Private`pauli4Dim[
           FeynCalc`PauliTrick`Private`b, FeynCalc`PauliTrick`Private`d] + 
         I*Eps[FeynCalc`PauliTrick`Private`c1, 
           FeynCalc`PauliTrick`Private`c2, FeynCalc`PauliTrick`Private`tmpli]*
          FeynCalc`PauliTrick`Private`pauli4Dim[
           FeynCalc`PauliTrick`Private`b, PauliSigma[
            FeynCalc`PauliTrick`Private`tmpli], 
           FeynCalc`PauliTrick`Private`d] /. CartesianPair -> 
         CartesianPairContract /. CartesianPairContract -> CartesianPair) /; 
     FeynCalc`PauliTrick`Private`pauliReduce
 
FeynCalc`PauliTrick`Private`pauli4Dim[FeynCalc`PauliTrick`Private`b___, 
     PauliSigma[FeynCalc`PauliTrick`Private`c1_CartesianIndex], 
