FeynCalc`PauliTrace`Private`noSpur /: 
    FeynCalc`PauliTrace`Private`noSpur::usage = ""
 
FeynCalc`PauliTrace`Private`orderSpurHead[
     FeynCalc`PauliTrace`Private`x__PauliSigma, 
     FeynCalc`PauliTrace`Private`y_PauliSigma] := 
    Block[{FeynCalc`PauliTrace`Private`p1, FeynCalc`PauliTrace`Private`p2, 
      FeynCalc`PauliTrace`Private`tmpSpur, FeynCalc`PauliTrace`Private`li = 
       {FeynCalc`PauliTrace`Private`x, FeynCalc`PauliTrace`Private`y}, 
      FeynCalc`PauliTrace`Private`pos, FeynCalc`PauliTrace`Private`tab}, 
     FeynCalc`PauliTrace`Private`tab = 
       Table[FeynCalc`PauliTrace`Private`p1 = FeynCalc`PauliTrace`Private`li[[
           1 ;; FeynCalc`PauliTrace`Private`i]]; 
         FeynCalc`PauliTrace`Private`p2 = FeynCalc`PauliTrace`Private`li[[
           FeynCalc`PauliTrace`Private`i + 1 ;; All]]; 
         {1, FeynCalc`PauliTrace`Private`tmpSpur[Sequence @@ 
            FeynCalc`PauliTrace`Private`p2, Sequence @@ 
            FeynCalc`PauliTrace`Private`p1]}, {FeynCalc`PauliTrace`Private`i, 
         1, Length[FeynCalc`PauliTrace`Private`li] - 1}]; 
      FeynCalc`PauliTrace`Private`tab = 
       Join[{{1, FeynCalc`PauliTrace`Private`tmpSpur[
           FeynCalc`PauliTrace`Private`x, FeynCalc`PauliTrace`Private`y]}}, 
        FeynCalc`PauliTrace`Private`tab]; FeynCalc`PauliTrace`Private`pos = 
       First[Ordering[FeynCalc`PauliTrace`Private`tab /. 
          {_, FeynCalc`PauliTrace`Private`tmpSpur[
             FeynCalc`PauliTrace`Private`b__]} :> 
           {FeynCalc`PauliTrace`Private`b}]]; 
      FeynCalc`PauliTrace`Private`spurHead[Sequence @@ 
        FeynCalc`PauliTrace`Private`tab[[FeynCalc`PauliTrace`Private`pos]][[
         2]]]]
 
FeynCalc`PauliTrace`Private`spurEven[
     FeynCalc`PauliTrace`Private`x__PauliSigma] := 
    FeynCalc`PauliTrace`Private`traceEvenWrap[
      Sequence @@ First /@ {FeynCalc`PauliTrace`Private`x}] /; 
     EvenQ[Length[{FeynCalc`PauliTrace`Private`x}]]
 
FeynCalc`PauliTrace`Private`traceEvenWrap[] = 1
 
FeynCalc`PauliTrace`Private`traceEvenWrap[FeynCalc`PauliTrace`Private`SI1_, 
     FeynCalc`PauliTrace`Private`SI2__] := 
    Block[{FeynCalc`PauliTrace`Private`res, 
       FeynCalc`PauliTrace`Private`repRule, FeynCalc`PauliTrace`Private`tab, 
       FeynCalc`PauliTrace`Private`set, SI, FeynCalc`PauliTrace`Private`args, 
       FeynCalc`PauliTrace`Private`setDel, 
       FeynCalc`PauliTrace`Private`tmpRes, 
       FeynCalc`PauliTrace`Private`finalRes}, 
      FeynCalc`PauliTrace`Private`tab = Table[ToExpression[
          StringJoin["MyI", ToString[FeynCalc`PauliTrace`Private`i]]], 
         {FeynCalc`PauliTrace`Private`i, 1, Length[
           {FeynCalc`PauliTrace`Private`SI1, 
            FeynCalc`PauliTrace`Private`SI2}]}]; 
       FeynCalc`PauliTrace`Private`finalRes = 
        FeynCalc`PauliTrace`Private`traceEvenFun @@ 
         {FeynCalc`PauliTrace`Private`SI1, FeynCalc`PauliTrace`Private`SI2}; 
       If[Head[FeynCalc`PauliTrace`Private`finalRes] === 
         FeynCalc`PauliTrace`Private`traceEvenFun, 
        FeynCalc`PauliTrace`Private`tmpRes = 
          FeynCalc`PauliTrace`Private`traceEven @@ 
           FeynCalc`PauliTrace`Private`tab; 
         If[$FCMemoryAvailable - MemoryInUse[]/1.*^6 > 1., 
          FeynCalc`PauliTrace`Private`args = Sequence @@ 
             (Pattern[#1, _] & ) /@ FeynCalc`PauliTrace`Private`tab; 
           FeynCalc`PauliTrace`Private`setDel[
             FeynCalc`PauliTrace`Private`traceEvenFun[
              FeynCalc`PauliTrace`Private`args], 
             FeynCalc`PauliTrace`Private`fastExpand[
              FeynCalc`PauliTrace`Private`tmpRes]] /. 
            FeynCalc`PauliTrace`Private`setDel -> SetDelayed; 
           FeynCalc`PauliTrace`Private`res = 
            FeynCalc`PauliTrace`Private`traceEvenFun @@ 
             {FeynCalc`PauliTrace`Private`SI1, 
              FeynCalc`PauliTrace`Private`SI2}, 
          FeynCalc`PauliTrace`Private`res = 
           FeynCalc`PauliTrace`Private`tmpRes /. Thread[
             FeynCalc`PauliTrace`Private`tab -> 
              {FeynCalc`PauliTrace`Private`SI1, 
               FeynCalc`PauliTrace`Private`SI2}]], 
        FeynCalc`PauliTrace`Private`res = 
         FeynCalc`PauliTrace`Private`finalRes]; 
       FeynCalc`PauliTrace`Private`res] /; 
     EvenQ[Length[{FeynCalc`PauliTrace`Private`SI1, 
        FeynCalc`PauliTrace`Private`SI2}]]
 
FeynCalc`PauliTrace`Private`traceEvenFun /: 
    FeynCalc`PauliTrace`Private`traceEvenFun::usage = ""
 
FeynCalc`PauliTrace`Private`traceEven[FeynCalc`PauliTrace`Private`SI1_, 
     FeynCalc`PauliTrace`Private`SI2__] := 
    Block[{FeynCalc`PauliTrace`Private`head, FeynCalc`PauliTrace`Private`s = 
        -1, FeynCalc`PauliTrace`Private`res}, 
      FeynCalc`PauliTrace`Private`res = Plus @@ MapIndexed[
          (FeynCalc`PauliTrace`Private`s = -FeynCalc`PauliTrace`Private`s)*
            CartesianPair[FeynCalc`PauliTrace`Private`SI1, #1]*
            Drop[FeynCalc`PauliTrace`Private`head[
              FeynCalc`PauliTrace`Private`SI2], #2] & , 
          {FeynCalc`PauliTrace`Private`SI2}]; 
       FeynCalc`PauliTrace`Private`res = FeynCalc`PauliTrace`Private`res /. 
         FeynCalc`PauliTrace`Private`head -> 
          FeynCalc`PauliTrace`Private`traceEvenWrap; 
       FeynCalc`PauliTrace`Private`res] /; 
     EvenQ[Length[{FeynCalc`PauliTrace`Private`SI1, 
        FeynCalc`PauliTrace`Private`SI2}]]
 
FeynCalc`PauliTrace`Private`fastExpand[FeynCalc`PauliTrace`Private`xx_] := 
    Replace[FeynCalc`PauliTrace`Private`xx, 
     (FeynCalc`PauliTrace`Private`p_.)*((FeynCalc`PauliTrace`Private`a__)*
        (FeynCalc`PauliTrace`Private`x_Plus)) :> 
      Distribute[FeynCalc`PauliTrace`Private`p*FeynCalc`PauliTrace`Private`a*
        FeynCalc`PauliTrace`Private`x, Plus], 1]
 
