            FeynCalc`PauliTrace`Private`setDel -> SetDelayed; 
           FeynCalc`PauliTrace`Private`res = 
            FeynCalc`PauliTrace`Private`traceOddFun @@ 
             {FeynCalc`PauliTrace`Private`SI1}, 
          FeynCalc`PauliTrace`Private`res = 
           FeynCalc`PauliTrace`Private`tmpRes /. Thread[
             FeynCalc`PauliTrace`Private`tab -> 
              {FeynCalc`PauliTrace`Private`SI1}]], 
        FeynCalc`PauliTrace`Private`res = 
         FeynCalc`PauliTrace`Private`realRes]; 
       FeynCalc`PauliTrace`Private`res] /; 
     OddQ[Length[{FeynCalc`PauliTrace`Private`SI1}]]
 
FeynCalc`PauliTrace`Private`traceOddFun /: 
    FeynCalc`PauliTrace`Private`traceOddFun::usage = ""
 
FeynCalc`PauliTrace`Private`traceOdd[FeynCalc`PauliTrace`Private`mu_, 
     FeynCalc`PauliTrace`Private`nu_, FeynCalc`PauliTrace`Private`rho_, 
     FeynCalc`PauliTrace`Private`SI1_, FeynCalc`PauliTrace`Private`SI2__] := 
    CartesianPair[FeynCalc`PauliTrace`Private`mu, 
       FeynCalc`PauliTrace`Private`nu]*FeynCalc`PauliTrace`Private`traceOdd[
       FeynCalc`PauliTrace`Private`rho, FeynCalc`PauliTrace`Private`SI1, 
