Attributes[MT] = {Orderless}
 
MT[0, 0] = 1
 
MT[FeynCalc`SharedObjects`Private`i:1 | 2 | 3, 
     FeynCalc`SharedObjects`Private`i:1 | 2 | 3] := FeynCalc`Package`MetricS
 
MT[FeynCalc`SharedObjects`Private`i:1 | 2 | 3, 
     FeynCalc`SharedObjects`Private`j:1 | 2 | 3] := 
    0 /; FeynCalc`SharedObjects`Private`i =!= FeynCalc`SharedObjects`Private`j
 
MT[0, 1 | 2 | 3] = 0
 
MT /: MakeBoxes[MT[FeynCalc`SharedObjectsTypesetting`Private`x_, 
       FeynCalc`SharedObjectsTypesetting`Private`y_], TraditionalForm] := 
     ToBoxes[Pair[LorentzIndex[FeynCalc`SharedObjectsTypesetting`Private`x], 
       LorentzIndex[FeynCalc`SharedObjectsTypesetting`Private`y]], 
      TraditionalForm]
 
MT /: MT::usage = "MT[mu, nu] is the metric tensor in $4$ dimensions."
 
MTLR[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y_, 
     FeynCalc`SharedObjects`Private`r___] := 
    MTLR[FeynCalc`SharedObjects`Private`y, FeynCalc`SharedObjects`Private`x, 
      FeynCalc`SharedObjects`Private`r] /; 
      !OrderedQ[{FeynCalc`SharedObjects`Private`x, 
        FeynCalc`SharedObjects`Private`y}]
 
MTLR[FeynCalc`SharedObjects`Private`x_, FeynCalc`SharedObjects`Private`y_] := 
