     FeynCalc`FeynCalcExternal`Private`x_] := 
    FeynCalc`FeynCalcExternal`Private`x /; 
      !FreeQ[FeynCalc`FeynCalcExternal`Private`x, 
       GenericPropagatorDenominator]
 
FeynCalc`FeynCalcExternal`Private`momentumCombine[
     FeynCalc`FeynCalcExternal`Private`x_] := 
