FactorList2[FeynCalc`SharedTools`Private`poly_, OptionsPattern[]] := 
    Block[{FeynCalc`SharedTools`Private`res, 
      FeynCalc`SharedTools`Private`allVars, 
      FeynCalc`SharedTools`Private`allVarsNum, 
      FeynCalc`SharedTools`Private`holdPower, 
      FeynCalc`SharedTools`Private`optRandomPrime, 
      FeynCalc`SharedTools`Private`nRule, FeynCalc`SharedTools`Private`chk}, 
     FeynCalc`SharedTools`Private`optRandomPrime = OptionValue[RandomPrime]; 
      FeynCalc`SharedTools`Private`allVars = Variables2[
        Cases[FeynCalc`SharedTools`Private`poly /. Power -> 
            FeynCalc`SharedTools`Private`holdPower, 
          FeynCalc`SharedTools`Private`holdPower[
            FeynCalc`SharedTools`Private`x_, _] :> 
           FeynCalc`SharedTools`Private`x, Infinity] /. 
         FeynCalc`SharedTools`Private`holdPower -> Power]; 
      FeynCalc`SharedTools`Private`allVars = SelectFree[
        FeynCalc`SharedTools`Private`allVars, Variables2[
         Cases[FeynCalc`SharedTools`Private`poly, 
          _^(FeynCalc`SharedTools`Private`x_) :> 
           FeynCalc`SharedTools`Private`x, Infinity]]]; 
      FeynCalc`SharedTools`Private`allVarsNum = 
       Table[RandomPrime[FeynCalc`SharedTools`Private`optRandomPrime], 
        {FeynCalc`SharedTools`Private`i, 1, 
         Length[FeynCalc`SharedTools`Private`allVars]}]; 
      FeynCalc`SharedTools`Private`nRule = 
       Thread[FeynCalc`SharedTools`Private`allVars -> 
         FeynCalc`SharedTools`Private`allVarsNum]; 
      FeynCalc`SharedTools`Private`res = 
       FactorList[FeynCalc`SharedTools`Private`poly] //. 
        {{FeynCalc`SharedTools`Private`r1___, 
           {(FeynCalc`SharedTools`Private`x_)^
             (FeynCalc`SharedTools`Private`y_), 
            FeynCalc`SharedTools`Private`pow_}, 
           FeynCalc`SharedTools`Private`r2___} :> 
          {FeynCalc`SharedTools`Private`r1, {FeynCalc`SharedTools`Private`x, 
            FeynCalc`SharedTools`Private`pow*FeynCalc`SharedTools`Private`y}, 
           FeynCalc`SharedTools`Private`r2}, 
         {FeynCalc`SharedTools`Private`r1___, 
           {FeynCalc`SharedTools`Private`a_, 
            FeynCalc`SharedTools`Private`pow1_}, 
           FeynCalc`SharedTools`Private`r2___, 
           {FeynCalc`SharedTools`Private`a_, 
            FeynCalc`SharedTools`Private`pow2_}, 
           FeynCalc`SharedTools`Private`r3___} :> 
          {FeynCalc`SharedTools`Private`r1, {FeynCalc`SharedTools`Private`a, 
            FeynCalc`SharedTools`Private`pow1 + 
             FeynCalc`SharedTools`Private`pow2}, 
           FeynCalc`SharedTools`Private`r2, FeynCalc`SharedTools`Private`r3}, 
         {FeynCalc`SharedTools`Private`r1___, 
            {FeynCalc`SharedTools`Private`a_, 
             FeynCalc`SharedTools`Private`pow1_}, 
            FeynCalc`SharedTools`Private`r2___} /; 
           Denominator[FeynCalc`SharedTools`Private`a] =!= 1 :> 
          {FeynCalc`SharedTools`Private`r1, 
           {Numerator[FeynCalc`SharedTools`Private`a], 
            FeynCalc`SharedTools`Private`pow1}, 
           {Denominator[FeynCalc`SharedTools`Private`a], 
            -FeynCalc`SharedTools`Private`pow1}, 
           FeynCalc`SharedTools`Private`r2}}; 
      FeynCalc`SharedTools`Private`res = 
       Factor[FeynCalc`SharedTools`Private`res] //. 
        {{FeynCalc`SharedTools`Private`r1___, 
           {(FeynCalc`SharedTools`Private`x_)^
             (FeynCalc`SharedTools`Private`y_), 
            FeynCalc`SharedTools`Private`pow_}, 
           FeynCalc`SharedTools`Private`r2___} :> 
          {FeynCalc`SharedTools`Private`r1, {FeynCalc`SharedTools`Private`x, 
            FeynCalc`SharedTools`Private`pow*FeynCalc`SharedTools`Private`y}, 
           FeynCalc`SharedTools`Private`r2}, 
         {FeynCalc`SharedTools`Private`r1___, 
           {FeynCalc`SharedTools`Private`a_, 
            FeynCalc`SharedTools`Private`pow1_}, 
           FeynCalc`SharedTools`Private`r2___, 
           {FeynCalc`SharedTools`Private`a_, 
            FeynCalc`SharedTools`Private`pow2_}, 
           FeynCalc`SharedTools`Private`r3___} :> 
          {FeynCalc`SharedTools`Private`r1, {FeynCalc`SharedTools`Private`a, 
            FeynCalc`SharedTools`Private`pow1 + 
             FeynCalc`SharedTools`Private`pow2}, 
           FeynCalc`SharedTools`Private`r2, FeynCalc`SharedTools`Private`r3}, 
         {FeynCalc`SharedTools`Private`r1___, 
            {FeynCalc`SharedTools`Private`a_, 
             FeynCalc`SharedTools`Private`pow1_}, 
            FeynCalc`SharedTools`Private`r2___} /; 
           Denominator[FeynCalc`SharedTools`Private`a] =!= 1 :> 
          {FeynCalc`SharedTools`Private`r1, 
           {Numerator[FeynCalc`SharedTools`Private`a], 
            FeynCalc`SharedTools`Private`pow1}, 
           {Denominator[FeynCalc`SharedTools`Private`a], 
            -FeynCalc`SharedTools`Private`pow1}, 
           FeynCalc`SharedTools`Private`r2}}; If[OptionValue[Check], 
       FeynCalc`SharedTools`Private`chk = 
         (FeynCalc`SharedTools`Private`poly /. Dispatch[
            FeynCalc`SharedTools`Private`nRule]) - 
          (Times @@ Apply[Power, FeynCalc`SharedTools`Private`res, {1}] /. 
           Dispatch[FeynCalc`SharedTools`Private`nRule]); 
        If[Simplify[PowerExpand[FeynCalc`SharedTools`Private`chk]] =!= 0, 
         Print[Simplify[PowerExpand[FeynCalc`SharedTools`Private`chk]]]; 
          Message[FactorList2::failmsg, 
           "Something went wrong when factorizing the polynomial."]; 
          Abort[]]; ]; FeynCalc`SharedTools`Private`res]
 
Options[FactorList2] = {Check -> True, RandomPrime -> 100000000}
 
FactorList2 /: FactorList2::failmsg = "Error! FactorList2 has encountered a \
fatal problem and must abort the computation. \n\nThe problem reads: `1`"
 
FactorList2 /: FactorList2::usage = "FactorList2[exp] is similar to \
FactorList except that it correctly handles\nsymbolic exponents."
 
Variables2[FeynCalc`SharedTools`Private`expr_Plus, 
     FeynCalc`SharedTools`Private`opts:OptionsPattern[]] := 
    Union[Flatten[(Variables2[#1, FeynCalc`SharedTools`Private`opts] & ) /@ 
       List @@ FeynCalc`SharedTools`Private`expr]]
 
Variables2[FeynCalc`SharedTools`Private`expr_List, 
     FeynCalc`SharedTools`Private`opts:OptionsPattern[]] := 
    Union[Flatten[(Variables2[#1, FeynCalc`SharedTools`Private`opts] & ) /@ 
       FeynCalc`SharedTools`Private`expr]]
 
Variables2[FeynCalc`SharedTools`Private`expr_, OptionsPattern[]] := 
    Union[Variables[FeynCalc`SharedTools`Private`expr]] /; 
      !MemberQ[{List, Equal, Rule, RuleDelayed, Re, Im}, 
       Head[FeynCalc`SharedTools`Private`expr]]
 
Variables2[(Equal | Rule | RuleDelayed)[FeynCalc`SharedTools`Private`a_, 
      FeynCalc`SharedTools`Private`b_], OptionsPattern[]] := 
    Union[Variables[FeynCalc`SharedTools`Private`a], 
     Variables[FeynCalc`SharedTools`Private`b]]
 
Variables2[(Re | Im)[FeynCalc`SharedTools`Private`a_], OptionsPattern[]] := 
    Variables[FeynCalc`SharedTools`Private`a]
 
Options[Variables2] = {}
 
Variables2 /: Variables2::usage = "Variables2[expr] is like Variables, but it \
also works on rules and equalities\nas well as lists thereof.\n\nVariables2 \
always applies Union to the output."
 
FeynCalc`NPointTo4Point`Private`getDet[
     FeynCalc`NPointTo4Point`Private`mli_List, 
     FeynCalc`NPointTo4Point`Private`pli_List, 
     FeynCalc`NPointTo4Point`Private`sps_, 
     FeynCalc`NPointTo4Point`Private`fad_, 
     FeynCalc`NPointTo4Point`Private`termHold_, 
     FeynCalc`NPointTo4Point`Private`detFunc_, 
     FeynCalc`NPointTo4Point`Private`factFunc_, OptionsPattern[]] := 
    Block[{FeynCalc`NPointTo4Point`Private`pl = 
       Prepend[FeynCalc`NPointTo4Point`Private`pli, 0], 
      FeynCalc`NPointTo4Point`Private`n = 
       Length[FeynCalc`NPointTo4Point`Private`mli], 
      FeynCalc`NPointTo4Point`Private`Y, 
      FeynCalc`NPointTo4Point`Private`augmY, 
      FeynCalc`NPointTo4Point`Private`prefac}, 
     FeynCalc`NPointTo4Point`Private`Y = 
       Table[FeynCalc`NPointTo4Point`Private`matrixElement[
         {FeynCalc`NPointTo4Point`Private`pl[[
           FeynCalc`NPointTo4Point`Private`i]], 
          FeynCalc`NPointTo4Point`Private`mli[[
           FeynCalc`NPointTo4Point`Private`i]]}, 
         {FeynCalc`NPointTo4Point`Private`pl[[
           FeynCalc`NPointTo4Point`Private`j]], 
          FeynCalc`NPointTo4Point`Private`mli[[
           FeynCalc`NPointTo4Point`Private`j]]}], 
        {FeynCalc`NPointTo4Point`Private`j, 1, 
         FeynCalc`NPointTo4Point`Private`n}, 
        {FeynCalc`NPointTo4Point`Private`i, 1, 
         FeynCalc`NPointTo4Point`Private`n}]; 
      If[ !SymmetricMatrixQ[FeynCalc`NPointTo4Point`Private`Y], 
       Message[NPointTo4Point::failmsg, "Y-matrix is not symmetric."]; 
        Abort[]]; FeynCalc`NPointTo4Point`Private`augmY = 
       (Prepend[#1, 1] & ) /@ FeynCalc`NPointTo4Point`Private`Y; 
      FCPrint[3, "NPointTo4Point: getDet: Y-matrix: ", 
       FeynCalc`NPointTo4Point`Private`Y, FCDoControl -> 
        FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FCPrint[3, "NPointTo4Point: getDet: augmented Y-matrix: ", 
       FeynCalc`NPointTo4Point`Private`augmY, FCDoControl -> 
        FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FeynCalc`NPointTo4Point`Private`prefac = 
       1/FeynCalc`NPointTo4Point`Private`termHold[
         FeynCalc`NPointTo4Point`Private`detFunc[
          FeynCalc`NPointTo4Point`Private`Y]]; 
      {FeynCalc`NPointTo4Point`Private`prefac, 
       FeynCalc`NPointTo4Point`Private`sps*
        Sum[(-1)^FeynCalc`NPointTo4Point`Private`i*
          FeynCalc`NPointTo4Point`Private`termHold[
           FeynCalc`NPointTo4Point`Private`factFunc[
            FeynCalc`NPointTo4Point`Private`detFunc[
             Drop[FeynCalc`NPointTo4Point`Private`augmY, None, 
              {FeynCalc`NPointTo4Point`Private`i + 1, 
               FeynCalc`NPointTo4Point`Private`i + 1}]]]]*
          Drop[FeynCalc`NPointTo4Point`Private`fad, 
           {FeynCalc`NPointTo4Point`Private`i, 
            FeynCalc`NPointTo4Point`Private`i}], 
         {FeynCalc`NPointTo4Point`Private`i, 1, 
          Length[FeynCalc`NPointTo4Point`Private`fad]}]}]
 
Attributes[FeynCalc`NPointTo4Point`Private`matrixElement] = {Orderless}
 
FeynCalc`NPointTo4Point`Private`matrixElement[
     {FeynCalc`NPointTo4Point`Private`pi_, 
      FeynCalc`NPointTo4Point`Private`mi_}, 
     {FeynCalc`NPointTo4Point`Private`pj_, 
      FeynCalc`NPointTo4Point`Private`mj_}] := 
    Expand[FeynCalc`NPointTo4Point`Private`smdaemon[
      FeynCalc`NPointTo4Point`Private`mi^2 + 
       FeynCalc`NPointTo4Point`Private`mj^2 - ExpandScalarProduct[
        Pair[Momentum[FeynCalc`NPointTo4Point`Private`pi - 
           FeynCalc`NPointTo4Point`Private`pj, 
          FeynCalc`NPointTo4Point`Private`dim], 
         Momentum[FeynCalc`NPointTo4Point`Private`pi - 
           FeynCalc`NPointTo4Point`Private`pj, 
          FeynCalc`NPointTo4Point`Private`dim]]]]]
 
FeynCalc`NPointTo4Point`Private`smdaemon[
     FeynCalc`NPointTo4Point`Private`x_] := 
    FeynCalc`NPointTo4Point`Private`x /. SmallVariable -> 
      FeynCalc`NPointTo4Point`Private`smn
 
FeynCalc`NPointTo4Point`Private`smn[_] := 0
 
FeynCalc`NPointTo4Point`Private`dim /: 
    FeynCalc`NPointTo4Point`Private`dim::usage = ""
 
NPointTo4Point[FeynCalc`NPointTo4Point`Private`expr_Plus, 
     FeynCalc`NPointTo4Point`Private`q_, FeynCalc`NPointTo4Point`Private`opts:
      OptionsPattern[]] := 
    (NPointTo4Point[#1, FeynCalc`NPointTo4Point`Private`q, 
       FeynCalc`NPointTo4Point`Private`opts] & ) /@ 
     FeynCalc`NPointTo4Point`Private`expr
 
NPointTo4Point[(FeynCalc`NPointTo4Point`Private`pref_.)*
      (FeynCalc`NPointTo4Point`Private`fad_FeynAmpDenominator), _, 
     OptionsPattern[]] := FeynCalc`NPointTo4Point`Private`pref*
      FeynCalc`NPointTo4Point`Private`fad /; 
     Length[List @@ FeynCalc`NPointTo4Point`Private`fad] < 5
 
NPointTo4Point[(FeynCalc`NPointTo4Point`Private`pref_.)*
      (FeynCalc`NPointTo4Point`Private`fad_FeynAmpDenominator), 
     FeynCalc`NPointTo4Point`Private`qu_, OptionsPattern[]] := 
    Block[{FeynCalc`NPointTo4Point`Private`pp, 
      FeynCalc`NPointTo4Point`Private`res, 
      FeynCalc`NPointTo4Point`Private`tim, 
      FeynCalc`NPointTo4Point`Private`pl, FeynCalc`NPointTo4Point`Private`ml, 
      FeynCalc`NPointTo4Point`Private`termHold, 
      FeynCalc`NPointTo4Point`Private`tmp, 
      FeynCalc`NPointTo4Point`Private`factoring}, 
     If[ !FreeQ2[{FeynCalc`NPointTo4Point`Private`pref*
           FeynCalc`NPointTo4Point`Private`fad}, FeynCalc`Package`NRStuff], 
       Message[FeynCalc::nrfail]; Abort[]]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`NPointTo4Point`Private`nptfpVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`NPointTo4Point`Private`nptfpVerbose = 
          OptionValue[FCVerbose]]; ]; 
      If[Length[List @@ FeynCalc`NPointTo4Point`Private`fad] =!= 5 || 
         !FreeQ[FeynCalc`NPointTo4Point`Private`pref, 
          FeynCalc`NPointTo4Point`Private`qu], 
       Return[FeynCalc`NPointTo4Point`Private`pref*
         FeynCalc`NPointTo4Point`Private`fad]]; 
      FCPrint[0, 
       "NPointTo4Point: The reduction of the scalar 5-point function ", 
       FeynCalc`NPointTo4Point`Private`fad, "is valid only if all the IR \
divergences were explicitly regularized with fictitious masses!", 
       FCDoControl -> FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FeynCalc`NPointTo4Point`Private`isoName = OptionValue[IsolateNames]; 
      FeynCalc`NPointTo4Point`Private`dim = OptionValue[Dimension]; 
      If[OptionValue[Factoring] === False, 
       FeynCalc`NPointTo4Point`Private`factoring -> Identity, 
       FeynCalc`NPointTo4Point`Private`factoring = OptionValue[Factoring]]; 
      If[FeynCalc`NPointTo4Point`Private`isoName === False, 
       FeynCalc`NPointTo4Point`Private`termHold = Identity, 
       FeynCalc`NPointTo4Point`Private`termHold = 
         FeynCalc`NPointTo4Point`Private`subdethold; ]; 
      FCPrint[3, "NPointTo4Point: Entering with: ", 
       FeynCalc`NPointTo4Point`Private`pref*
        FeynCalc`NPointTo4Point`Private`fad, FCDoControl -> 
        FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FeynCalc`NPointTo4Point`Private`pp[FeynCalc`NPointTo4Point`Private`a_, 
        _] := Expand[(FeynCalc`NPointTo4Point`Private`a /. 
          FeynCalc`NPointTo4Point`Private`m_Momentum :> 
           FeynCalc`NPointTo4Point`Private`m[[1]]) - 
         FeynCalc`NPointTo4Point`Private`qu]; 
      FeynCalc`NPointTo4Point`Private`pl = 
       Rest[FeynCalc`NPointTo4Point`Private`fad /. FeynAmpDenominator -> 
           List /. PropagatorDenominator -> 
          FeynCalc`NPointTo4Point`Private`pp]; 
      If[FCGramDeterminant[FeynCalc`NPointTo4Point`Private`pl] === 0, 
       FCPrint[1, "NPointTo4Point: Zero Gram determinant encountered. \
Returning unevaluated result.", FCDoControl -> 
          FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
        Return[FeynCalc`NPointTo4Point`Private`pref*
          FeynCalc`NPointTo4Point`Private`fad]]; 
      FCPrint[3, "NPointTo4Point: pl: ", FeynCalc`NPointTo4Point`Private`pl, 
       FCDoControl -> FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FeynCalc`NPointTo4Point`Private`ml = 
       FeynCalc`NPointTo4Point`Private`fad /. FeynAmpDenominator -> List /. 
        FeynCalc`NPointTo4Point`Private`pd_PropagatorDenominator :> 
         FeynCalc`NPointTo4Point`Private`pd[[2]]; 
      FCPrint[3, "NPointTo4Point: ml: ", FeynCalc`NPointTo4Point`Private`ml, 
       FCDoControl -> FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FeynCalc`NPointTo4Point`Private`tmp = FCUseCache[
        FeynCalc`NPointTo4Point`Private`getDet, 
        {FeynCalc`NPointTo4Point`Private`ml, 
         FeynCalc`NPointTo4Point`Private`pl, 
         FeynCalc`NPointTo4Point`Private`pref, 
         FeynCalc`NPointTo4Point`Private`fad, 
         FeynCalc`NPointTo4Point`Private`termHold, Det, 
         FeynCalc`NPointTo4Point`Private`factoring}]; 
      If[OptionValue[List], FeynCalc`NPointTo4Point`Private`res = 
        FeynCalc`NPointTo4Point`Private`tmp, 
       FeynCalc`NPointTo4Point`Private`res = 
        FeynCalc`NPointTo4Point`Private`tmp[[1]]*
         FeynCalc`NPointTo4Point`Private`tmp[[2]]]; If[OptionValue[FCE], 
       FeynCalc`NPointTo4Point`Private`res = 
        FCE[FeynCalc`NPointTo4Point`Private`res]]; 
      FCPrint[3, "NPointTo4Point: res: ", 
       FeynCalc`NPointTo4Point`Private`res, FCDoControl -> 
        FeynCalc`NPointTo4Point`Private`nptfpVerbose]; 
      FeynCalc`NPointTo4Point`Private`res]
 
NPointTo4Point[FeynCalc`NPointTo4Point`Private`expr_, _, OptionsPattern[]] := 
    FeynCalc`NPointTo4Point`Private`expr /; 
     FreeQ[FeynCalc`NPointTo4Point`Private`expr, FeynAmpDenominator]
 
Options[NPointTo4Point] = {Dimension -> D, FeynCalcExternal -> False, 
     FCVerbose -> False, Factoring -> Factor2, IsolateNames -> False, 
     List -> False}
 
NPointTo4Point /: NPointTo4Point::failmsg = "Error! NPointTo4Point has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
NPointTo4Point /: NPointTo4Point::usage = "NPointTo4Point[expr, q] reduces \
scalar IR finite 5-point functions to scalar\n4-point functions according to \
Eq. 4.52 in\n[arXiv:0709.1075](https://arxiv.org/abs/0709.1075)."
 
FeynCalc`Package`NRStuff = {CartesianPair, CartesianMomentum, CartesianIndex, 
     TemporalMomentum, TemporalPair, CV, CVD, CVE, TC, KD, KDD, KDE, CSP, 
     CSPD, CSPE, CLC, CLCD, CGA, CGAD, CGAE, TGA, CGS, CGSD, CGSE, SI, SID, 
     SIE, SIS, SISD, SISE, CSI, CSID, CSIE, CSIS, CSISD, CSISE}
 
FeynCalc`NPointTo4Point`Private`nptfpVerbose /: 
    FeynCalc`NPointTo4Point`Private`nptfpVerbose::usage = ""
 
FeynCalc`NPointTo4Point`Private`isoName /: 
    FeynCalc`NPointTo4Point`Private`isoName::usage = ""
 
FeynCalc`NPointTo4Point`Private`subdethold[
     FeynCalc`NPointTo4Point`Private`x_] := 
    Isolate[FeynCalc`NPointTo4Point`Private`x, IsolateNames -> 
      FeynCalc`NPointTo4Point`Private`isoName]
 
FCGramDeterminant[{}, OptionsPattern[]] := 1
 
FCGramDeterminant[FeynCalc`FCGram`Private`moms_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCGram`Private`mat, FeynCalc`FCGram`Private`det}, 
      FeynCalc`FCGram`Private`mat = FCGramMatrix[
         FeynCalc`FCGram`Private`moms, Dimension -> OptionValue[Dimension], 
         Prefactor -> OptionValue[Prefactor], Head -> OptionValue[Head], 
         FinalSubstitutions -> OptionValue[FinalSubstitutions]]; 
       FeynCalc`FCGram`Private`det = Det[FeynCalc`FCGram`Private`mat]; 
       If[OptionValue[ExpandScalarProduct], FeynCalc`FCGram`Private`det = 
         ExpandScalarProduct[FeynCalc`FCGram`Private`det, FCI -> True]]; 
       If[OptionValue[FCE], FeynCalc`FCGram`Private`det = 
          FCE[FeynCalc`FCGram`Private`det]; ]; 
       FeynCalc`FCGram`Private`det] /; FeynCalc`FCGram`Private`moms =!= {}
 
Options[FCGramDeterminant] = {Dimension -> D, ExpandScalarProduct -> True, 
     FinalSubstitutions -> {}, FeynCalcExternal -> False, 
     Head -> {Pair, Momentum}, Prefactor -> 2}
 
FCGramDeterminant /: FCGramDeterminant::usage = "FCGramDeterminant[{p1, p2, \
...}] computes the determinant of the Gram matrix\ncreated from the given \
list of momenta."
 
FCGramMatrix[FeynCalc`FCGram`Private`moms_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCGram`Private`mat, FeynCalc`FCGram`Private`len, 
       FeynCalc`FCGram`Private`dim, FeynCalc`FCGram`Private`res, 
       FeynCalc`FCGram`Private`pairHead, FeynCalc`FCGram`Private`momHead, 
       FeynCalc`FCGram`Private`optKinematics}, 
      FeynCalc`FCGram`Private`len = Length[FeynCalc`FCGram`Private`moms]; 
       FeynCalc`FCGram`Private`dim = OptionValue[Dimension]; 
       FeynCalc`FCGram`Private`pairHead = OptionValue[Head][[1]]; 
       FeynCalc`FCGram`Private`momHead = OptionValue[Head][[2]]; 
       FeynCalc`FCGram`Private`optKinematics = OptionValue[
         FinalSubstitutions]; If[FeynCalc`FCGram`Private`optKinematics =!= 
          {} &&  !OptionValue[FCI], FeynCalc`FCGram`Private`optKinematics = 
         FCI[FeynCalc`FCGram`Private`optKinematics]]; 
       FeynCalc`FCGram`Private`mat = Table[FeynCalc`FCGram`Private`pairHead[
           FeynCalc`FCGram`Private`momHead[FeynCalc`FCGram`Private`moms[[
             FeynCalc`FCGram`Private`i]], FeynCalc`FCGram`Private`dim], 
           FeynCalc`FCGram`Private`momHead[FeynCalc`FCGram`Private`moms[[
             FeynCalc`FCGram`Private`j]], FeynCalc`FCGram`Private`dim]], 
          {FeynCalc`FCGram`Private`i, 1, FeynCalc`FCGram`Private`len}, 
          {FeynCalc`FCGram`Private`j, 1, FeynCalc`FCGram`Private`len}] /. 
         FeynCalc`FCGram`Private`optKinematics; 
       If[ !MatrixQ[FeynCalc`FCGram`Private`mat], 
        Message[FCGramMatrix::failmsg, 
          "The created Gram matrix is incorrect."]; Abort[]]; 
       FeynCalc`FCGram`Private`res = OptionValue[Prefactor]*
         FeynCalc`FCGram`Private`mat; If[OptionValue[FCE], 
        FeynCalc`FCGram`Private`res = FCE[FeynCalc`FCGram`Private`res]; ]; 
       FeynCalc`FCGram`Private`res] /; FeynCalc`FCGram`Private`moms =!= {}
 
Options[FCGramMatrix] = {Dimension -> D, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FinalSubstitutions -> {}, 
     Head -> {Pair, Momentum}, Prefactor -> 2}
 
FCGramMatrix /: FCGramMatrix::failmsg = "Error! FCGramMatrix has encountered \
a fatal problem and must abort the computation. The problem reads: `1`"
 
FCGramMatrix /: FCGramMatrix::usage = "FCGramMatrix[{p1, p2, ...}] creates a \
Gram matrix from the given list of\nmomenta."
 
Prefactor /: Prefactor::usage = "Prefactor is an option for various \
functions. It usually specifies that the\nexpression should be multiplied by \
global Prefactor before or after\ncalculation."
 
FeynCalc`SimplifyPolyLog`Private`simplifyArgument[
     FeynCalc`SimplifyPolyLog`Private`su_, 
     FeynCalc`SimplifyPolyLog`Private`head_, {}] := 
    If[FreeQ[FeynCalc`SimplifyPolyLog`Private`su, Plus], 
     FeynCalc`SimplifyPolyLog`Private`head[
      FeynCalc`SimplifyPolyLog`Private`su], 
     FeynCalc`SimplifyPolyLog`Private`head[
      Factor2[Cancel[Factor2[FeynCalc`SimplifyPolyLog`Private`su]]]]]
 
FeynCalc`SimplifyPolyLog`Private`simplifyArgument[
     FeynCalc`SimplifyPolyLog`Private`su1_, 
     FeynCalc`SimplifyPolyLog`Private`su2_, 
     FeynCalc`SimplifyPolyLog`Private`head_, {}] := 
    If[FreeQ[FeynCalc`SimplifyPolyLog`Private`su2, Plus], 
     FeynCalc`SimplifyPolyLog`Private`head[
      FeynCalc`SimplifyPolyLog`Private`su1, 
      FeynCalc`SimplifyPolyLog`Private`su2], 
     FeynCalc`SimplifyPolyLog`Private`head[
      FeynCalc`SimplifyPolyLog`Private`su1, 
      Factor2[Cancel[Factor2[FeynCalc`SimplifyPolyLog`Private`su2]]]]]
 
FeynCalc`FCApart`Private`pfracRaw[
     FeynCalc`FCApart`Private`inputVectorSet_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCApart`Private`vectorSet, 
      FeynCalc`FCApart`Private`removalList, FeynCalc`FCApart`Private`f, 
      FeynCalc`FCApart`Private`v, FeynCalc`FCApart`Private`ca, 
      FeynCalc`FCApart`Private`M, FeynCalc`FCApart`Private`expCounts, 
      FeynCalc`FCApart`Private`spIndices, 
      FeynCalc`FCApart`Private`spPosition, 
      FeynCalc`FCApart`Private`spExponent, FeynCalc`FCApart`Private`spfCoeff, 
      FeynCalc`FCApart`Private`spType, FeynCalc`FCApart`Private`res, 
      FeynCalc`FCApart`Private`iterList, FeynCalc`FCApart`Private`dummy, 
      FeynCalc`FCApart`Private`eiPos, FeynCalc`FCApart`Private`tmpNS, 
      FeynCalc`FCApart`Private`tmp, FeynCalc`FCApart`Private`hRule, 
      FeynCalc`FCApart`Private`vectorSet12, 
      FeynCalc`FCApart`Private`nlCoeffs}, 
     FCPrint[3, "FCApart: pfrac: Entering with ", 
       FeynCalc`FCApart`Private`inputVectorSet, FCDoControl -> 
        FeynCalc`FCApart`Private`fcaVerbose]; 
      FeynCalc`FCApart`Private`removalList = 
       Position[FeynCalc`FCApart`Private`inputVectorSet[[3]], 0]; 
      FeynCalc`FCApart`Private`vectorSet = 
       {Delete[FeynCalc`FCApart`Private`inputVectorSet[[1]], 
         FeynCalc`FCApart`Private`removalList], 
        FeynCalc`FCApart`Private`inputVectorSet[[2]], 
        Delete[FeynCalc`FCApart`Private`inputVectorSet[[3]], 
         FeynCalc`FCApart`Private`removalList], 
        Delete[FeynCalc`FCApart`Private`inputVectorSet[[4]], 
         FeynCalc`FCApart`Private`removalList]}; 
      FCPrint[3, "FCApart: pfrac: Basis with zero exponents removed ", 
       FeynCalc`FCApart`Private`vectorSet, FCDoControl -> 
        FeynCalc`FCApart`Private`fcaVerbose]; 
      FeynCalc`FCApart`Private`expCounts = 
       FeynCalc`FCApart`Private`vectorSet[[3]]; 
      If[FeynCalc`FCApart`Private`expCounts === {}, 
       FCPrint[3, "FCApart: pfrac: The propagator is unity: ", 
         FeynCalc`FCApart`Private`vectorSet, FCDoControl -> 
          FeynCalc`FCApart`Private`fcaVerbose]; 
        Return[FeynCalc`FCApart`Private`pfracOut[
          FeynCalc`FCApart`Private`vectorSet]]]; 
      FeynCalc`FCApart`Private`nlCoeffs = 
       Select[FeynCalc`FCApart`Private`vectorSet[[2]], 
         !MemberQ[{Pair, CartesianPair, TemporalPair}, Head[#1]] & ]; 
      FeynCalc`FCApart`Private`hRule = (#1 -> Unique["caVar"] & ) /@ 
        FeynCalc`FCApart`Private`nlCoeffs; 
      FeynCalc`FCApart`Private`vectorSet12 = 
       {FeynCalc`FCApart`Private`vectorSet[[1]] //. 
         FeynCalc`FCApart`Private`hRule, 
        Join[Complement[FeynCalc`FCApart`Private`vectorSet[[2]], 
          FeynCalc`FCApart`Private`nlCoeffs], 
         Last /@ FeynCalc`FCApart`Private`hRule]}; 
      FeynCalc`FCApart`Private`ca = Normal[CoefficientArrays @@ 
         FeynCalc`FCApart`Private`vectorSet12]; FeynCalc`FCApart`Private`M = 
       Transpose[FeynCalc`FCApart`Private`ca[[2]]]; 
      FeynCalc`FCApart`Private`tmpNS = 
       Sort[NullSpace[FeynCalc`FCApart`Private`M]]; 
      If[FeynCalc`FCApart`Private`tmpNS === {}, 
       FCPrint[3, "FCApart: pfrac: ", FeynCalc`FCApart`Private`vectorSet, 
         " contains only linearly independent polynomial. Done!", 
         FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
        Return[FeynCalc`FCApart`Private`pfracOut[
          FeynCalc`FCApart`Private`vectorSet]]; ]; 
      FeynCalc`FCApart`Private`spIndices = 
       Position[FeynCalc`FCApart`Private`expCounts, _Integer?Negative]; 
      If[FeynCalc`FCApart`Private`spIndices =!= {}, 
       FeynCalc`FCApart`Private`spPosition = 
         FeynCalc`FCApart`Private`spIndices[[1]][[1]]; 
        FeynCalc`FCApart`Private`v = 
         If[Length[FeynCalc`FCApart`Private`tmpNS] > 1 || 
           First[FeynCalc`FCApart`Private`tmpNS][[
             FeynCalc`FCApart`Private`spPosition]] =!= 0, 
