             FeynCalc`FCApart`Private`vectorSet[[2]], 
             Delete[FeynCalc`FCApart`Private`expCounts, 
              {FeynCalc`FCApart`Private`spPosition}], 
             Delete[FeynCalc`FCApart`Private`vectorSet[[4]], 
