FeynCalc`FCApart`Private`fcaVerbose = 0
 
FeynCalc`FCApart`Private`fcaVerbose /: 
    FeynCalc`FCApart`Private`fcaVerbose::usage = ""
 
FeynCalc`FCApart`Private`pfracOut /: 
    FeynCalc`FCApart`Private`pfracOut::usage = ""
 
FeynCalc`FCApart`Private`pfrac[
     FeynCalc`FCApart`Private`inputVectorSet_List] := 
    FCUseCache[FeynCalc`FCApart`Private`pfracRaw, 
      {FeynCalc`FCApart`Private`inputVectorSet}, {}] /; 
     FeynCalc`FCApart`Private`counter === Infinity
 
FeynCalc`FCApart`Private`pfrac[
     FeynCalc`FCApart`Private`inputVectorSet_List] := 
    (FeynCalc`FCApart`Private`counter--; FCPrint[3, 
       "FCApart: pfrac: Counter is ", FeynCalc`FCApart`Private`counter, 
       FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
      FeynCalc`FCApart`Private`pfracRaw[
       FeynCalc`FCApart`Private`inputVectorSet]) /; 
     FeynCalc`FCApart`Private`counter > 0 && 
      FeynCalc`FCApart`Private`counter =!= Infinity
 
FeynCalc`FCApart`Private`counter = Infinity
 
FeynCalc`FCApart`Private`counter /: FeynCalc`FCApart`Private`counter::usage = 
     ""
 
FeynCalc`Package`momentumRoutingDenner[FeynCalc`ToPaVe`Private`moms_List, 
     FeynCalc`ToPaVe`Private`fu_, OptionsPattern[]] := 
    Block[{FeynCalc`ToPaVe`Private`firstLines, 
       FeynCalc`ToPaVe`Private`lastLine, FeynCalc`ToPaVe`Private`kmax = 
        (Length[FeynCalc`ToPaVe`Private`moms] + 1)/2, 
       FeynCalc`ToPaVe`Private`res, FeynCalc`ToPaVe`Private`p, 
       FeynCalc`ToPaVe`Private`repRule}, FeynCalc`ToPaVe`Private`repRule = 
        Thread[Table[FeynCalc`ToPaVe`Private`p[FeynCalc`ToPaVe`Private`i], 
           {FeynCalc`ToPaVe`Private`i, 1, 2*FeynCalc`ToPaVe`Private`kmax - 
             1}] -> FeynCalc`ToPaVe`Private`moms]; 
       FeynCalc`ToPaVe`Private`firstLines = Transpose[
         Table[FeynCalc`ToPaVe`Private`fu[FeynCalc`ToPaVe`Private`p[
             FeynCalc`ToPaVe`Private`k + FeynCalc`ToPaVe`Private`l] - 
            FeynCalc`ToPaVe`Private`p[FeynCalc`ToPaVe`Private`l]], 
          {FeynCalc`ToPaVe`Private`l, 0, 2*FeynCalc`ToPaVe`Private`kmax - 1}, 
          {FeynCalc`ToPaVe`Private`k, 1, FeynCalc`ToPaVe`Private`kmax - 1}]]; 
       FeynCalc`ToPaVe`Private`lastLine = Table[FeynCalc`ToPaVe`Private`fu[
          FeynCalc`ToPaVe`Private`p[FeynCalc`ToPaVe`Private`kmax + 
             FeynCalc`ToPaVe`Private`l] - FeynCalc`ToPaVe`Private`p[
            FeynCalc`ToPaVe`Private`l]], {FeynCalc`ToPaVe`Private`l, 0, 
          FeynCalc`ToPaVe`Private`kmax - 1}]; FeynCalc`ToPaVe`Private`res = 
        Join[Flatten[FeynCalc`ToPaVe`Private`firstLines], 
          FeynCalc`ToPaVe`Private`lastLine] //. 
         {FeynCalc`ToPaVe`Private`p[2*FeynCalc`ToPaVe`Private`kmax] -> 
           FeynCalc`ToPaVe`Private`p[0], FeynCalc`ToPaVe`Private`p[
             FeynCalc`ToPaVe`Private`x_] /; FeynCalc`ToPaVe`Private`x > 
             2*FeynCalc`ToPaVe`Private`kmax :> FeynCalc`ToPaVe`Private`p[
            FeynCalc`ToPaVe`Private`x - 2*FeynCalc`ToPaVe`Private`kmax], 
          FeynCalc`ToPaVe`Private`p[0] -> 0}; 
       If[Length[FeynCalc`ToPaVe`Private`res] =!= 
         (FeynCalc`ToPaVe`Private`kmax - 1)*2*FeynCalc`ToPaVe`Private`kmax + 
          FeynCalc`ToPaVe`Private`kmax, Message[ToPaVe::failmsg, 
          "Wrong number of the kinematic invariants!"]; Abort[]]; 
       FeynCalc`ToPaVe`Private`res /. Dispatch[
         FeynCalc`ToPaVe`Private`repRule]] /; 
     OddQ[Length[FeynCalc`ToPaVe`Private`moms]]
 
FeynCalc`Package`momentumRoutingDenner[FeynCalc`ToPaVe`Private`moms_List, 
     FeynCalc`ToPaVe`Private`fu_, OptionsPattern[]] := 
    Block[{FeynCalc`ToPaVe`Private`firstLines, 
       FeynCalc`ToPaVe`Private`lastLine, FeynCalc`ToPaVe`Private`kmax = 
        Length[FeynCalc`ToPaVe`Private`moms]/2, FeynCalc`ToPaVe`Private`res, 
       FeynCalc`ToPaVe`Private`p, FeynCalc`ToPaVe`Private`repRule}, 
      FeynCalc`ToPaVe`Private`repRule = 
        Thread[Table[FeynCalc`ToPaVe`Private`p[FeynCalc`ToPaVe`Private`i], 
           {FeynCalc`ToPaVe`Private`i, 1, 2*FeynCalc`ToPaVe`Private`kmax}] -> 
          FeynCalc`ToPaVe`Private`moms]; FeynCalc`ToPaVe`Private`res = 
        Transpose[Table[FeynCalc`ToPaVe`Private`fu[
           FeynCalc`ToPaVe`Private`p[FeynCalc`ToPaVe`Private`k + 
              FeynCalc`ToPaVe`Private`l] - FeynCalc`ToPaVe`Private`p[
             FeynCalc`ToPaVe`Private`l]], {FeynCalc`ToPaVe`Private`l, 0, 
           2*FeynCalc`ToPaVe`Private`kmax}, {FeynCalc`ToPaVe`Private`k, 1, 
           FeynCalc`ToPaVe`Private`kmax}]]; FeynCalc`ToPaVe`Private`res = 
        Flatten[FeynCalc`ToPaVe`Private`res //. 
          {FeynCalc`ToPaVe`Private`p[2*FeynCalc`ToPaVe`Private`kmax + 1] -> 
            FeynCalc`ToPaVe`Private`p[0], FeynCalc`ToPaVe`Private`p[
              FeynCalc`ToPaVe`Private`x_] /; FeynCalc`ToPaVe`Private`x > 
              2*FeynCalc`ToPaVe`Private`kmax + 1 :> FeynCalc`ToPaVe`Private`p[
             FeynCalc`ToPaVe`Private`x - 2*FeynCalc`ToPaVe`Private`kmax - 1], 
           FeynCalc`ToPaVe`Private`p[0] -> 0}]; 
       If[Length[FeynCalc`ToPaVe`Private`res] =!= 
         FeynCalc`ToPaVe`Private`kmax*(2*FeynCalc`ToPaVe`Private`kmax + 1), 
        Message[ToPaVe::failmsg, 
          "Wrong number of the kinematic invariants!"]; Abort[]]; 
       FeynCalc`ToPaVe`Private`res /. Dispatch[
         FeynCalc`ToPaVe`Private`repRule]] /; 
     EvenQ[Length[FeynCalc`ToPaVe`Private`moms]]
 
ToPaVe[(FeynCalc`ToPaVe`Private`a_) == (FeynCalc`ToPaVe`Private`b_), 
     FeynCalc`ToPaVe`Private`rest___] := 
    ToPaVe[FeynCalc`ToPaVe`Private`a, FeynCalc`ToPaVe`Private`rest] == 
     ToPaVe[FeynCalc`ToPaVe`Private`b, FeynCalc`ToPaVe`Private`rest]
 
ToPaVe[FeynCalc`ToPaVe`Private`expr_List, FeynCalc`ToPaVe`Private`rest___] := 
    (ToPaVe[#1, FeynCalc`ToPaVe`Private`rest] & ) /@ 
     FeynCalc`ToPaVe`Private`expr
 
ToPaVe[FeynCalc`ToPaVe`Private`expr_ /;  !MemberQ[{List, Equal}, 
        FeynCalc`ToPaVe`Private`expr], FeynCalc`ToPaVe`Private`q_, 
     OptionsPattern[]] := Block[{FeynCalc`ToPaVe`Private`ex, 
      FeynCalc`ToPaVe`Private`loopInt, FeynCalc`ToPaVe`Private`irrel, 
      FeynCalc`ToPaVe`Private`rel, Removed["repList"], 
      FeynCalc`ToPaVe`Private`res, FeynCalc`ToPaVe`Private`loopList, 
      FeynCalc`ToPaVe`Private`optOtherLoopMomenta, 
      FeynCalc`ToPaVe`Private`loopListEval, 
      FeynCalc`ToPaVe`Private`optFinalSubstitutions, 
      FeynCalc`ToPaVe`Private`optFactoring}, 
     If[ !FreeQ[$ScalarProducts, FeynCalc`ToPaVe`Private`q], 
       Message[ToPaVe::failmsg, StringJoin["The loop momentum ", 
          ToString[FeynCalc`ToPaVe`Private`q, InputForm], 
          " has scalar product rules attached to it."]]; Abort[]]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`ToPaVe`Private`tpvVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`ToPaVe`Private`tpvVerbose = OptionValue[FCVerbose]]; ]; 
      FCPrint[1, "ToPaVe: Entering.", FCDoControl -> 
        FeynCalc`ToPaVe`Private`tpvVerbose]; 
      FCPrint[3, "ToPaVe: Entering with: ", FeynCalc`ToPaVe`Private`expr, 
       FCDoControl -> FeynCalc`ToPaVe`Private`tpvVerbose]; 
      FeynCalc`ToPaVe`Private`genpave = OptionValue[GenPaVe]; 
      FeynCalc`ToPaVe`Private`optPaVeOrder = OptionValue[PaVeOrder]; 
      FeynCalc`ToPaVe`Private`optOtherLoopMomenta = 
       OptionValue[OtherLoopMomenta]; 
      FeynCalc`ToPaVe`Private`optFinalSubstitutions = 
       OptionValue[FinalSubstitutions]; 
      FeynCalc`ToPaVe`Private`optFactoring = OptionValue[Factoring]; 
      If[OptionValue[FCI], FeynCalc`ToPaVe`Private`ex = 
        FeynCalc`ToPaVe`Private`expr, {FeynCalc`ToPaVe`Private`ex, 
         FeynCalc`ToPaVe`Private`optFinalSubstitutions} = 
        FCI[{FeynCalc`ToPaVe`Private`expr, 
          FRH[FeynCalc`ToPaVe`Private`optFinalSubstitutions]}]]; 
      FeynCalc`ToPaVe`Private`ex = FCLoopSplit[FeynCalc`ToPaVe`Private`ex, 
        {FeynCalc`ToPaVe`Private`q}, FCI -> True]; 
      FeynCalc`ToPaVe`Private`irrel = FeynCalc`ToPaVe`Private`ex[[1]] + 
        FeynCalc`ToPaVe`Private`ex[[3]] + FeynCalc`ToPaVe`Private`ex[[4]]; 
      FeynCalc`ToPaVe`Private`rel = FeynCalc`ToPaVe`Private`ex[[2]]; 
      FeynCalc`ToPaVe`Private`rel = FCLoopIsolate[
        FeynCalc`ToPaVe`Private`rel, {FeynCalc`ToPaVe`Private`q}, 
        Head -> FeynCalc`ToPaVe`Private`loopInt, FCI -> True, GFAD -> False, 
        CFAD -> False, SFAD -> True, PaVe -> False]; 
      FeynCalc`ToPaVe`Private`loopList = Cases2[FeynCalc`ToPaVe`Private`rel, 
        FeynCalc`ToPaVe`Private`loopInt]; FCPrint[3, 
       "ToPaVe: List of loop integrals: ", FeynCalc`ToPaVe`Private`loopList, 
       FCDoControl -> FeynCalc`ToPaVe`Private`tpvVerbose]; 
      FeynCalc`ToPaVe`Private`loopListEval = 
       (FCLoopPropagatorPowersExpand[#1, FCI -> True] & ) /@ 
        (FeynCalc`ToPaVe`Private`loopList /. 
         FeynCalc`ToPaVe`Private`loopInt -> Identity); 
      FeynCalc`ToPaVe`Private`loopListEval = 
       (If[FreeQ2[#1, FeynCalc`ToPaVe`Private`optOtherLoopMomenta], 
          FeynCalc`ToPaVe`Private`toPaVe[#1, FeynCalc`ToPaVe`Private`q, 
           OptionValue[PaVeAutoOrder], OptionValue[PaVeAutoReduce]], 
          #1] & ) /@ FeynCalc`ToPaVe`Private`loopListEval; 
      FeynCalc`ToPaVe`Private`loopListEval = 
       FeynCalc`ToPaVe`Private`loopListEval /. 
        FeynCalc`ToPaVe`Private`toPaVe[FeynCalc`ToPaVe`Private`z_, _, _, 
           _] /;  !FreeQ[FeynCalc`ToPaVe`Private`z, 
            StandardPropagatorDenominator] :> FeynCalc`ToPaVe`Private`z; 
      If[FeynCalc`ToPaVe`Private`optFinalSubstitutions =!= {}, 
       FeynCalc`ToPaVe`Private`loopListEval = 
        FeynCalc`ToPaVe`Private`loopListEval /. 
         Dispatch[FeynCalc`ToPaVe`Private`optFinalSubstitutions]]; 
      FCPrint[3, "ToPaVe: List of converted loop integrals: ", 
       FeynCalc`ToPaVe`Private`loopListEval, FCDoControl -> 
        FeynCalc`ToPaVe`Private`tpvVerbose]; If[OptionValue[PaVeToABCD], 
       FeynCalc`ToPaVe`Private`loopListEval = PaVeToABCD[
         FeynCalc`ToPaVe`Private`loopListEval]]; Removed["repList"] = 
       Thread[FeynCalc`ToPaVe`Private`loopList -> 
         FeynCalc`ToPaVe`Private`loopListEval]; FeynCalc`ToPaVe`Private`res = 
       (FeynCalc`ToPaVe`Private`rel /. Dispatch[Removed["repList"]]) + 
        FeynCalc`ToPaVe`Private`irrel; 
      If[ !FreeQ[FeynCalc`ToPaVe`Private`res, 
         FeynCalc`ToPaVe`Private`toPaVe], Message[ToPaVe::failmsg, "Not all \
1-loop scalar integrals could be converted to PaVe functions. Please apply \
FDS to the input and try again."]; Abort[]]; If[OptionValue[FCE], 
       FeynCalc`ToPaVe`Private`res = FCE[FeynCalc`ToPaVe`Private`res]]; 
      FCPrint[1, "ToPaVe: Leaving.", FCDoControl -> 
        FeynCalc`ToPaVe`Private`tpvVerbose]; FeynCalc`ToPaVe`Private`res]
 
Options[ToPaVe] = {Factoring -> Factor, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCVerbose -> False, FinalSubstitutions -> {}, 
     GenPaVe -> False, OtherLoopMomenta -> {}, PaVeAutoOrder -> True, 
     PaVeAutoReduce -> True, PaVeOrder -> True, PaVeToABCD -> True}
 
ToPaVe /: ToPaVe::failmsg = "Error! ToPaVe has encountered a fatal problem \
and must abort the computation. The problem reads: `1`"
 
ToPaVe /: ToPaVe::usage = "ToPaVe[exp, q]  converts all scalar 1-loop \
integrals in exp that depend on the\nmomentum q to scalar Passarino Veltman \
functions A0, B0, C0, D0 etc."
 
FeynCalc`ToPaVe`Private`optFactoring /: 
    FeynCalc`ToPaVe`Private`optFactoring::usage = ""
 
FeynCalc`ToPaVe`Private`tpvVerbose = 0
 
FeynCalc`ToPaVe`Private`tpvVerbose /: 
    FeynCalc`ToPaVe`Private`tpvVerbose::usage = ""
 
FeynCalc`ToPaVe`Private`genpave = False
 
FeynCalc`ToPaVe`Private`genpave /: FeynCalc`ToPaVe`Private`genpave::usage = ""
 
FeynCalc`ToPaVe`Private`optPaVeOrder = True
 
FeynCalc`ToPaVe`Private`optPaVeOrder /: 
    FeynCalc`ToPaVe`Private`optPaVeOrder::usage = ""
 
PaVeOrder[FeynCalc`PaVeOrder`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`PaVeOrder`Private`ex, 
      FeynCalc`PaVeOrder`Private`paveHead, FeynCalc`PaVeOrder`Private`new, 
      FeynCalc`PaVeOrder`Private`dordering, 
      FeynCalc`PaVeOrder`Private`optPaVeOrderList, 
      FeynCalc`PaVeOrder`Private`rest, FeynCalc`PaVeOrder`Private`loops, 
      FeynCalc`PaVeOrder`Private`paveInts, 
      FeynCalc`PaVeOrder`Private`paveIntsEval, 
      FeynCalc`PaVeOrder`Private`repRule, FeynCalc`PaVeOrder`Private`res, 
      FeynCalc`PaVeOrder`Private`time}, 
     FeynCalc`PaVeOrder`Private`optPaVeOrderList = 
       OptionValue[PaVeOrderList]; FeynCalc`PaVeOrder`Private`optSum = 
       OptionValue[Sum]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`PaVeOrder`Private`pvoVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`PaVeOrder`Private`pvoVerbose = OptionValue[FCVerbose]]; ]; 
      FCPrint[1, "PaVeOrder: Entering.", FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[3, "PaVeOrder: Entering with: ", 
       FeynCalc`PaVeOrder`Private`expr, FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[1, "PaVeOrder: Applying FCLoopExtract.", 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FeynCalc`PaVeOrder`Private`time = AbsoluteTime[]; 
      {FeynCalc`PaVeOrder`Private`rest, FeynCalc`PaVeOrder`Private`loops, 
        FeynCalc`PaVeOrder`Private`paveInts} = FCLoopExtract[
        FeynCalc`PaVeOrder`Private`expr, {}, 
        FeynCalc`PaVeOrder`Private`paveHead, FCI -> OptionValue[FCI], 
        FeynAmpDenominatorCombine -> False, FAD -> False, GFAD -> False, 
        CFAD -> False, SFAD -> True, PaVe -> True]; If[ !OptionValue[FCI], 
       FeynCalc`PaVeOrder`Private`optPaVeOrderList = 
        FCI[FeynCalc`PaVeOrder`Private`optPaVeOrderList]]; 
      FCPrint[1, "PaVeOrder: Done applying FCLoopExtract, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PaVeOrder`Private`time, 4], 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[3, "PaVeOrder: List of uniques PaVe functions: ", 
       FeynCalc`PaVeOrder`Private`paveInts, FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[1, "PaVeOrder: Applying ToPaVe2.", FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FeynCalc`PaVeOrder`Private`time = AbsoluteTime[]; 
      FeynCalc`PaVeOrder`Private`paveIntsEval = 
       ToPaVe2[FeynCalc`PaVeOrder`Private`paveInts] /. 
          PaVe -> FeynCalc`Package`paveHold /. SmallVariable -> 
          FeynCalc`PaVeOrder`Private`smallvarHold /. 
        FeynCalc`PaVeOrder`Private`paveHead -> Identity; 
      FCPrint[1, "PaVeOrder: Done applying ToPaVe2, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PaVeOrder`Private`time, 4], 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[3, "PaVeOrder: After ToPaVe2: ", 
       FeynCalc`PaVeOrder`Private`paveIntsEval, FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      If[ !MatchQ[Head /@ FeynCalc`PaVeOrder`Private`paveIntsEval, 
         {FeynCalc`Package`paveHold...}], Message[PaVeOrder::failmsg, 
         "Failed to convert the occurring functions to PaVe"]; Abort[]]; 
      FCPrint[1, "PaVeOrder: Applying paveAutoOrder.", 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FeynCalc`PaVeOrder`Private`time = AbsoluteTime[]; 
      FeynCalc`PaVeOrder`Private`paveIntsEval = 
       FeynCalc`Package`paveAutoOrder /@ 
        FeynCalc`PaVeOrder`Private`paveIntsEval; 
      FCPrint[1, "PaVeOrder: Done applying paveAutoOrder, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PaVeOrder`Private`time, 4], 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[3, "PaVeOrder: After paveAutoOrder: ", 
       FeynCalc`PaVeOrder`Private`paveIntsEval, FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      If[FeynCalc`PaVeOrder`Private`optPaVeOrderList =!= {}, 
       If[Head[FeynCalc`PaVeOrder`Private`optPaVeOrderList[[1]]] =!= List, 
         FeynCalc`PaVeOrder`Private`optPaVeOrderList = 
          {FeynCalc`PaVeOrder`Private`optPaVeOrderList}]; 
        FCPrint[1, "PaVeOrder: Applying paveOrder.", FCDoControl -> 
          FeynCalc`PaVeOrder`Private`pvoVerbose]; 
        FeynCalc`PaVeOrder`Private`time = AbsoluteTime[]; 
        FeynCalc`PaVeOrder`Private`optPaVeOrderList = 
         FeynCalc`PaVeOrder`Private`optPaVeOrderList /. SmallVariable -> 
           FeynCalc`PaVeOrder`Private`smallvarHold; 
        FeynCalc`PaVeOrder`Private`paveIntsEval = 
         (Fold[FeynCalc`PaVeOrder`Private`paveOrder, #1, 
            FeynCalc`PaVeOrder`Private`optPaVeOrderList] & ) /@ 
          FeynCalc`PaVeOrder`Private`paveIntsEval; 
        FCPrint[1, "PaVeOrder: Done applying paveOrder, timing: ", 
         N[AbsoluteTime[] - FeynCalc`PaVeOrder`Private`time, 4], 
         FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
        FCPrint[3, "PaVeOrder: After paveOrder: ", 
         FeynCalc`PaVeOrder`Private`paveIntsEval, FCDoControl -> 
          FeynCalc`PaVeOrder`Private`pvoVerbose]; ]; 
      FeynCalc`PaVeOrder`Private`paveIntsEval = 
       FeynCalc`PaVeOrder`Private`paveIntsEval /. 
         FeynCalc`PaVeOrder`Private`smallvarHold -> SmallVariable /. 
        FeynCalc`PaVeOrder`Private`paveReordered | 
          FeynCalc`Package`paveHold -> PaVe; If[OptionValue[PaVeToABCD], 
       FeynCalc`PaVeOrder`Private`paveIntsEval = PaVeToABCD[
          FeynCalc`PaVeOrder`Private`paveIntsEval]; 
        FCPrint[3, "PaVeOrder: After PaVeToABCD: ", 
         FeynCalc`PaVeOrder`Private`paveIntsEval, FCDoControl -> 
          FeynCalc`PaVeOrder`Private`pvoVerbose]; ]; 
      FeynCalc`PaVeOrder`Private`repRule = 
       Thread[FeynCalc`PaVeOrder`Private`paveInts -> 
         FeynCalc`PaVeOrder`Private`paveIntsEval]; 
      FCPrint[3, "PaVeOrder: Final replacement rule: ", 
       FeynCalc`PaVeOrder`Private`repRule, FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FeynCalc`PaVeOrder`Private`res = FeynCalc`PaVeOrder`Private`rest + 
         FeynCalc`PaVeOrder`Private`loops /. 
        Dispatch[FeynCalc`PaVeOrder`Private`repRule]; 
      FCPrint[1, "PaVeOrder: Applying Collect2.", FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FeynCalc`PaVeOrder`Private`res = Collect2[
        FeynCalc`PaVeOrder`Private`res, {PaVe, A0, A00, B0, B1, B00, B11, C0, 
         D0}, Factoring -> OptionValue[Factoring], TimeConstrained -> 
         OptionValue[TimeConstrained]]; FCPrint[1, 
       "PaVeOrder: Collect2 done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`PaVeOrder`Private`time, 4], 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[3, "PaVeOrder: After Collect2: ", 
       FeynCalc`PaVeOrder`Private`res, FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[1, "PaVeOrder: Leaving.", FCDoControl -> 
        FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      FCPrint[3, "PaVeOrder: Leaving with: ", FeynCalc`PaVeOrder`Private`res, 
       FCDoControl -> FeynCalc`PaVeOrder`Private`pvoVerbose]; 
      If[OptionValue[FCE], FeynCalc`PaVeOrder`Private`res = 
        FCE[FeynCalc`PaVeOrder`Private`res]]; FeynCalc`PaVeOrder`Private`res]
 
Options[PaVeOrder] = {Collecting -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCVerbose -> False, 
     Factoring -> {Factor, 5000}, PaVeOrderList -> {}, PaVeToABCD -> False, 
     Sum -> False, TimeConstrained -> 3}
 
PaVeOrder /: PaVeOrder::failmsg = "Error! PaVeOrder encountered a fatal \
problem and must abort the computation. The problem reads: `1`"
 
PaVeOrder /: PaVeOrder::usage = "PaVeOrder[expr] orders the arguments of PaVe \
functions in expr in a standard\nway.\n\nPaVeOrder[expr, PaVeOrderList -> { \
{..., s, u, ...}, {... m1^2, m2^2, ...},\n...}] orders the arguments of PaVe \
functions in expr according to the\nspecified ordering lists. The lists may \
contain only a subsequence of the\nkinematic variables.\n\nPaVeOrder has \
knows about symmetries in the arguments of PaVe functions with\nup to 6 \
legs.\n\nAvailable symmetry relations are saved \
here\n\nFileBaseName/@FileNames[\"*.sym\",FileNameJoin[{$FeynCalcDirectory,\n\
\"Tables\", \n\"PaVeSymmetries\"}]]\n\nFor the time being, these tables \
contain relations for B-functions up to rank\n10, C-functions up to rank 9, \
D-functions up to rank 8,\nE-functions (5-point functions) up to rank 7 and \
F-functions (6-point\nfunctions) up to rank 4. If needed, relations for more \
legs\nand higher tensor ranks can be calculated using FeynCalc and saved \
to\nPaVeSymmetries using template codes provided inside *.sym files."
 
PaVeOrderList /: PaVeOrderList::usage = "PaVeOrderList is an option for \
PaVeOrder and PaVeReduce, specifying in which\norder the arguments of D0 are \
to be permuted."
 
FeynCalc`PaVeOrder`Private`optSum = False
 
FeynCalc`PaVeOrder`Private`optSum /: 
    FeynCalc`PaVeOrder`Private`optSum::usage = ""
 
FeynCalc`PaVeOrder`Private`pvoVerbose = 0
 
FeynCalc`PaVeOrder`Private`pvoVerbose /: 
    FeynCalc`PaVeOrder`Private`pvoVerbose::usage = ""
 
FCLoopExtract[FeynCalc`FCLoopExtract`Private`ex_, 
     FeynCalc`FCLoopExtract`Private`lmoms_, 
     FeynCalc`FCLoopExtract`Private`loopHead_, OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopExtract`Private`exp, 
      FeynCalc`FCLoopExtract`Private`tmp, FeynCalc`FCLoopExtract`Private`rel, 
      FeynCalc`FCLoopExtract`Private`irrel, 
      FeynCalc`FCLoopExtract`Private`rest, 
      FeynCalc`FCLoopExtract`Private`loopInts, 
      FeynCalc`FCLoopExtract`Private`intsUnique, 
      FeynCalc`FCLoopExtract`Private`null1, 
      FeynCalc`FCLoopExtract`Private`null2}, 
     If[ !OptionValue[FCI], FeynCalc`FCLoopExtract`Private`exp = 
        FCI[FeynCalc`FCLoopExtract`Private`ex], 
       FeynCalc`FCLoopExtract`Private`exp = 
        FeynCalc`FCLoopExtract`Private`ex]; 
      If[OptionValue[FeynAmpDenominatorCombine], 
       FeynCalc`FCLoopExtract`Private`exp = FeynAmpDenominatorCombine[
         FeynCalc`FCLoopExtract`Private`exp]]; 
      FeynCalc`FCLoopExtract`Private`tmp = FCLoopSplit[
        FeynCalc`FCLoopExtract`Private`exp, 
        FeynCalc`FCLoopExtract`Private`lmoms, FCI -> True, 
        Collecting -> False]; FeynCalc`FCLoopExtract`Private`rel = 
       Sort[OptionValue[FCLoopSplit]]; FeynCalc`FCLoopExtract`Private`irrel = 
       Complement[{1, 2, 3, 4}, FeynCalc`FCLoopExtract`Private`rel]; 
      If[Sort[Join[FeynCalc`FCLoopExtract`Private`rel, 
          FeynCalc`FCLoopExtract`Private`irrel]] =!= {1, 2, 3, 4}, 
       Message[FCLoopExtract::fail, ToString[
         FeynCalc`FCLoopExtract`Private`exp, InputForm]]]; 
      FeynCalc`FCLoopExtract`Private`rest = 
       Plus @@ FeynCalc`FCLoopExtract`Private`tmp[[
         FeynCalc`FCLoopExtract`Private`irrel]]; 
      FeynCalc`FCLoopExtract`Private`loopInts = FCLoopIsolate[
        Plus @@ FeynCalc`FCLoopExtract`Private`tmp[[
          FeynCalc`FCLoopExtract`Private`rel]], 
        FeynCalc`FCLoopExtract`Private`lmoms, CFAD -> OptionValue[CFAD], 
        Collecting -> OptionValue[Collecting], DropScaleless -> 
         OptionValue[DropScaleless], ExpandScalarProduct -> 
         OptionValue[ExpandScalarProduct], FAD -> OptionValue[FAD], 
        FCI -> True, FCLoopIBPReducableQ -> OptionValue[FCLoopIBPReducableQ], 
        Factoring -> OptionValue[Factoring], Factoring -> 
         OptionValue[Factoring], Full -> OptionValue[Full], 
        GFAD -> OptionValue[GFAD], Head -> 
         FeynCalc`FCLoopExtract`Private`loopHead, MultiLoop -> 
         OptionValue[MultiLoop], Numerator -> OptionValue[Numerator], 
        PaVe -> OptionValue[PaVe], PaVeIntegralHeads -> 
         OptionValue[PaVeIntegralHeads], SFAD -> OptionValue[SFAD], 
        TimeConstrained -> OptionValue[TimeConstrained]]; 
      If[OptionValue[FCLoopBasisSplit], 
       FeynCalc`FCLoopExtract`Private`loopInts = 
        FeynCalc`FCLoopExtract`Private`loopInts /. 
          FeynCalc`FCLoopExtract`Private`loopHead[
            FeynCalc`FCLoopExtract`Private`zz_] :> FCLoopBasisSplit[
            FeynCalc`FCLoopExtract`Private`zz, 
            FeynCalc`FCLoopExtract`Private`lmoms, List -> False, 
            Head -> FeynCalc`FCLoopExtract`Private`loopHead] /. 
         FeynCalc`FCLoopExtract`Private`loopHead[
           FeynCalc`FCLoopExtract`Private`zz_, 0] :> 
          FeynCalc`FCLoopExtract`Private`loopHead[
           FeynCalc`FCLoopExtract`Private`zz]]; 
      FeynCalc`FCLoopExtract`Private`intsUnique = 
       Union[Cases[FeynCalc`FCLoopExtract`Private`loopInts + 
           FeynCalc`FCLoopExtract`Private`null1 + 
           FeynCalc`FCLoopExtract`Private`null2, 
          FeynCalc`FCLoopExtract`Private`loopHead[__], Infinity] /. 
         FeynCalc`FCLoopExtract`Private`null1 | 
           FeynCalc`FCLoopExtract`Private`null2 -> 0]; 
      If[OptionValue[FCE], {FeynCalc`FCLoopExtract`Private`rest, 
         FeynCalc`FCLoopExtract`Private`loopInts, 
         FeynCalc`FCLoopExtract`Private`intsUnique} = 
        FCE[{FeynCalc`FCLoopExtract`Private`rest, 
          FeynCalc`FCLoopExtract`Private`loopInts, 
          FeynCalc`FCLoopExtract`Private`intsUnique}]]; 
      {FeynCalc`FCLoopExtract`Private`rest, 
       FeynCalc`FCLoopExtract`Private`loopInts, 
       FeynCalc`FCLoopExtract`Private`intsUnique}]
 
Options[FCLoopExtract] = {CFAD -> True, Collecting -> True, 
     DropScaleless -> False, ExpandScalarProduct -> False, 
     Factoring -> {Factor2, 5000}, FAD -> True, Full -> False, 
     FeynCalcInternal -> False, FeynCalcExternal -> False, 
     FCLoopIBPReducableQ -> False, FCLoopSplit -> {2, 3, 4}, 
     FCLoopBasisSplit -> False, FeynAmpDenominatorCombine -> True, 
     GFAD -> True, MultiLoop -> False, Numerator -> True, PaVe -> True, 
     PaVeIntegralHeads -> FeynCalc`Package`PaVeHeadsList, SFAD -> True, 
     TimeConstrained -> 3}
 
FCLoopExtract /: FCLoopExtract::fail = 
     "Error! FCLoopExtract failed extract loop integrals in `1`!"
 
FCLoopExtract /: FCLoopExtract::usage = "FCLoopExtract[expr, {q1, q2, ...}, \
loopHead] exctracts loop integrals that\ndepend on q1, q2, ... from the given \
expression. The output is given as a list\nof three entries. The first one \
contains part of the original expression that\nconsists of irrelevant loop \
integrals and terms that are free of any loop\nintegrals. The second entry \
contains relevant loop integrals, where each\nintegral is wrapped into \
loopHead. The third entry is a list of all the unique\nloop integrals from \
the second entry and can be used as an input to another\nfunction. Note that \
if loop integrals contain free indices, those will not be\ncanonicalized."
 
FeynAmpDenominatorCombine[FeynCalc`FeynAmpDenominatorCombine`Private`expr_, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FeynAmpDenominatorCombine`Private`ex, 
      FeynCalc`FeynAmpDenominatorCombine`Private`res, 
      FeynCalc`FeynAmpDenominatorCombine`Private`optMomentum, 
      FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose, 
      FeynCalc`FeynAmpDenominatorCombine`Private`time, 
      FeynCalc`FeynAmpDenominatorCombine`Private`momsList, 
      FeynCalc`FeynAmpDenominatorCombine`Private`momsListExpanded, 
      FeynCalc`FeynAmpDenominatorCombine`Private`repRule, 
      FeynCalc`FeynAmpDenominatorCombine`Private`feyncombList, 
      FeynCalc`FeynAmpDenominatorCombine`Private`feyncombListEval}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FeynAmpDenominatorCombine: Applying FCI.", 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      If[OptionValue[FCI], FeynCalc`FeynAmpDenominatorCombine`Private`ex = 
        FeynCalc`FeynAmpDenominatorCombine`Private`expr, 
       FeynCalc`FeynAmpDenominatorCombine`Private`ex = 
        FCI[FeynCalc`FeynAmpDenominatorCombine`Private`expr]]; 
      FCPrint[1, "FeynAmpDenominatorCombine: Done applying FCI, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FeynAmpDenominatorCombine`Private`time, 
        4], FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`optMomentum = 
       OptionValue[Momentum]; 
      If[FreeQ[FeynCalc`FeynAmpDenominatorCombine`Private`ex, 
        FeynAmpDenominator], Return[
        FeynCalc`FeynAmpDenominatorCombine`Private`ex]]; 
      If[Head[FeynCalc`FeynAmpDenominatorCombine`Private`expr] =!= List, 
       FeynCalc`FeynAmpDenominatorCombine`Private`ex = 
        {FeynCalc`FeynAmpDenominatorCombine`Private`ex}]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FeynAmpDenominatorCombine: Applying Expand2.", 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`res = 
       Expand2[FeynCalc`FeynAmpDenominatorCombine`Private`ex, 
        FeynAmpDenominator]; FCPrint[1, 
       "FeynAmpDenominatorCombine: Done applying Expand2, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FeynAmpDenominatorCombine`Private`time, 
        4], FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`time = AbsoluteTime[]; 
      FCPrint[1, 
       "FeynAmpDenominatorCombine: Precombining FeynAmpDenominators.", 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      If[FeynCalc`FeynAmpDenominatorCombine`Private`optMomentum =!= All && 
        Head[FeynCalc`FeynAmpDenominatorCombine`Private`optMomentum] === 
         List, FeynCalc`FeynAmpDenominatorCombine`Private`res = 
        FeynCalc`FeynAmpDenominatorCombine`Private`res /. 
         FeynAmpDenominator[
            FeynCalc`FeynAmpDenominatorCombine`Private`x__] /; 
            !FreeQ2[{FeynCalc`FeynAmpDenominatorCombine`Private`x}, 
             FeynCalc`FeynAmpDenominatorCombine`Private`optMomentum] :> 
          FeynCalc`FeynAmpDenominatorCombine`Private`feyncomb[
           FeynCalc`FeynAmpDenominatorCombine`Private`x], 
       FeynCalc`FeynAmpDenominatorCombine`Private`res = 
        FeynCalc`FeynAmpDenominatorCombine`Private`res /. 
         FeynAmpDenominator -> 
          FeynCalc`FeynAmpDenominatorCombine`Private`feyncomb]; 
      FCPrint[1, "FeynAmpDenominatorCombine: Done precombining \
FeynAmpDenominators, timing: ", N[AbsoluteTime[] - 
         FeynCalc`FeynAmpDenominatorCombine`Private`time, 4], 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FeynAmpDenominatorCombine: Creating replacement rules.", 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorCombine`Private`fadcVerbose]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`feyncombList = 
       Cases2[FeynCalc`FeynAmpDenominatorCombine`Private`res, 
        FeynCalc`FeynAmpDenominatorCombine`Private`feyncomb]; 
      FeynCalc`FeynAmpDenominatorCombine`Private`momsList = 
       Cases2[FeynCalc`FeynAmpDenominatorCombine`Private`feyncombList, 
        {Momentum, CartesianMomentum, TemporalMomentum}]; 
