FeynCalc`Package`lenso[PropagatorDenominator[
      FeynCalc`FeynAmpDenominatorSimplify`Private`x_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1_], 
     PropagatorDenominator[FeynCalc`FeynAmpDenominatorSimplify`Private`y_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m2_]] := 
    FeynCalc`Package`lenso[PD[FeynCalc`FeynAmpDenominatorSimplify`Private`x, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m1], 
      PD[FeynCalc`FeynAmpDenominatorSimplify`Private`y, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2]] = 
     Which[NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x] =!= 
       NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y], 
      NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x] < 
       NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y], 
      NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x] === 
       NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y], 
      If[FeynCalc`FeynAmpDenominatorSimplify`Private`x =!= 
        FeynCalc`FeynAmpDenominatorSimplify`Private`y, 
       OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`x, 
         FeynCalc`FeynAmpDenominatorSimplify`Private`y}], 
       OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`m1, 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m2}]], True, 
      Message[FDS::failmsg, "Can't sort the list of propagators."]; Abort[]]
 
FeynCalc`Package`lenso[(FeynCalc`FeynAmpDenominatorSimplify`Private`h1:
       StandardPropagatorDenominator | CartesianPropagatorDenominator)[
      FeynCalc`FeynAmpDenominatorSimplify`Private`x1_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`x2_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`s1_], 
     (FeynCalc`FeynAmpDenominatorSimplify`Private`h2:
       StandardPropagatorDenominator | CartesianPropagatorDenominator)[
      FeynCalc`FeynAmpDenominatorSimplify`Private`y1_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`y2_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m2_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`s2_]] := 
    FeynCalc`Package`lenso[FeynCalc`FeynAmpDenominatorSimplify`Private`h1[
       FeynCalc`FeynAmpDenominatorSimplify`Private`x1, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`x2, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m1, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`s1], 
      FeynCalc`FeynAmpDenominatorSimplify`Private`h2[
       FeynCalc`FeynAmpDenominatorSimplify`Private`y1, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`y2, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`s2]] = 
     Which[FeynCalc`FeynAmpDenominatorSimplify`Private`h1 === 
        StandardPropagatorDenominator && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`h2 === 
        CartesianPropagatorDenominator, True, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`h1 === 
        CartesianPropagatorDenominator && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`h2 === 
        StandardPropagatorDenominator, False, 
      NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`x2] =!= 
       NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`y2], 
      NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`x2] < 
       NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`y2], 
      NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`x2] === 
       NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`y2], 
      If[FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`x2 =!= 
        FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`y2, 
       OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`x2, 
         FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`y2}], 
       OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`m1, 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m2}]], True, 
      Message[FDS::failmsg, "Can't sort the list of propagators."]; Abort[]]
 
FDS = FeynAmpDenominatorSimplify
 
FDS /: FDS::failmsg = "Error! FDS has encountered a fatal problem and must \
abort the computation. \n\nThe problem reads: `1`"
 
FDS /: FDS::twoloopsefail = "FDS detected a fatal error while converting the \
2-loop self energy integral `1` \n\ninto canonicla form. Evaluation aborted!"
 
FDS /: FDS::usage = "FDS is shorthand for FeynAmpDenominatorSimplify."
 
Attributes[FeynAmpDenominatorSimplify] = {Listable}
 
FeynAmpDenominatorSimplify[FeynCalc`FeynAmpDenominatorSimplify`Private`expr_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`qs___ /; 
      FreeQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`qs}, Momentum], 
     FeynCalc`FeynAmpDenominatorSimplify`Private`opt:OptionsPattern[]] := 
    Block[{FeynCalc`FeynAmpDenominatorSimplify`Private`ex, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`rest, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`loopInts, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`intsUnique, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`solsList, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`repRule, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`time, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`topoCheckUnique, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`topoCheck, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`multiLoopHead, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`solsList2, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`intsTops, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`intsTops2, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`optCollecting, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`power, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fadList, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fadHold, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`intsUniqueClassified, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`optFCLoopScalelessQ, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fdsHold1L, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fdsHold2L, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fdsHoldXL}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose = 
          OptionValue[FCVerbose]]; ]; 
      If[ !FreeQ2[$ScalarProducts, 
         {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}], 
       Message[FDS::failmsg, "Some loop momenta have scalar product rules \
attached to them. Evaluation aborted!"]; Abort[]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`optCollecting = 
       OptionValue[Collecting]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`optFCLoopScalelessQ = 
       OptionValue[FCLoopScalelessQ]; If[ !OptionValue[FCI], 
       FeynCalc`FeynAmpDenominatorSimplify`Private`ex = 
        FeynCalcInternal[FeynCalc`FeynAmpDenominatorSimplify`Private`expr], 
       FeynCalc`FeynAmpDenominatorSimplify`Private`ex = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`expr]; 
      FCPrint[1, "FDS: Entering FDS. ", FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FCPrint[3, "FDS: Entering with: ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`ex, 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      If[FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`ex, 
        FeynAmpDenominator], FCPrint[1, "FDS: Nothing to do.", 
         FCDoControl -> FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbos\
e]; Return[FeynCalc`FeynAmpDenominatorSimplify`Private`ex]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`ex = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`ex /. 
        FeynAmpDenominator[FeynCalc`FeynAmpDenominatorSimplify`Private`a__]^
          (FeynCalc`FeynAmpDenominatorSimplify`Private`b_) :> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`power[
          FeynCalc`FeynAmpDenominatorSimplify`Private`fadHold[
           FeynCalc`FeynAmpDenominatorSimplify`Private`a], 
          FeynCalc`FeynAmpDenominatorSimplify`Private`b]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fadList = 
       Cases2[FeynCalc`FeynAmpDenominatorSimplify`Private`ex + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`null1 + 
         FeynCalc`FeynAmpDenominatorSimplify`Private`null2, 
        FeynAmpDenominator, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`power]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fadList /. 
          {FeynCalc`FeynAmpDenominatorSimplify`Private`power[
              FeynCalc`FeynAmpDenominatorSimplify`Private`fadHold[
               FeynCalc`FeynAmpDenominatorSimplify`Private`a__], 
              FeynCalc`FeynAmpDenominatorSimplify`Private`n_] /; 
             MatchQ[FeynCalc`FeynAmpDenominatorSimplify`Private`n, 
              _Integer?Positive] :> FeynAmpDenominator[Sequence @@ 
              Flatten[ConstantArray[
                {FeynCalc`FeynAmpDenominatorSimplify`Private`a}, 
                FeynCalc`FeynAmpDenominatorSimplify`Private`n]]]} /. 
         FeynCalc`FeynAmpDenominatorSimplify`Private`power -> Power /. 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fadHold -> 
         FeynAmpDenominator; FCPrint[3, 
       "FDS: Original list of propagators with combined powers: ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      If[OptionValue[FCLoopPropagatorPowersExpand], 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval = 
        FCLoopPropagatorPowersExpand[
         FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
         FCI -> True]]; 
      If[ !FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
         PD], FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval /. 
          PD -> FeynCalc`FeynAmpDenominatorSimplify`Private`procan /. 
         FeynCalc`FeynAmpDenominatorSimplify`Private`procan -> PD]; 
      If[ !FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
         StandardPropagatorDenominator], 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval /. 
          StandardPropagatorDenominator -> 
           FeynCalc`FeynAmpDenominatorSimplify`Private`procanSFAD /. 
         FeynCalc`FeynAmpDenominatorSimplify`Private`procanSFAD -> 
          StandardPropagatorDenominator]; 
      If[ !FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
         CartesianPropagatorDenominator], 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval /. 
          CartesianPropagatorDenominator -> 
           FeynCalc`FeynAmpDenominatorSimplify`Private`procanCFAD /. 
         FeynCalc`FeynAmpDenominatorSimplify`Private`procanCFAD -> 
          CartesianPropagatorDenominator]; FCPrint[3, "FDS: After fixing the \
signs of squared momenta in the propagators: ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval, 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      If[Length[{FeynCalc`FeynAmpDenominatorSimplify`Private`qs}] === 0, 
       FCPrint[1, "FDS: No loop momenta were given.", FCDoControl -> 
          FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval = 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval /. 
          FeynAmpDenominator -> 
           FeynCalc`FeynAmpDenominatorSimplify`Private`feyncan; 
        FeynCalc`FeynAmpDenominatorSimplify`Private`repRule = 
         Thread[FeynCalc`FeynAmpDenominatorSimplify`Private`fadList -> 
           FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval]; 
        FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
         FeynCalc`FeynAmpDenominatorSimplify`Private`ex /. 
          Dispatch[FeynCalc`FeynAmpDenominatorSimplify`Private`repRule]; 
        If[OptionValue[FCE], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
          FCE[FeynCalc`FeynAmpDenominatorSimplify`Private`res]]; 
        Return[FeynCalc`FeynAmpDenominatorSimplify`Private`res]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`repRule = 
       Thread[FeynCalc`FeynAmpDenominatorSimplify`Private`fadList -> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fadListEval]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`ex = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`ex /. 
        Dispatch[FeynCalc`FeynAmpDenominatorSimplify`Private`repRule]; 
      FCPrint[3, "FDS: New ex: ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`ex, 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FCPrint[1, "FDS: Extracting unique loop integrals. ", 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`time = AbsoluteTime[]; 
      {FeynCalc`FeynAmpDenominatorSimplify`Private`rest, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`loopInts, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`intsUnique} = 
       FCLoopExtract[FeynCalc`FeynAmpDenominatorSimplify`Private`ex, 
        {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`loopHead, FCI -> True, 
        PaVe -> False, FCLoopBasisSplit -> True, ExpandScalarProduct -> True, 
        Full -> False, GFAD -> False, CFAD -> True, SFAD -> True]; 
      FCPrint[1, "FDS: Done extracting unique loop integrals, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FeynAmpDenominatorSimplify`Private`time, 
        4], FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FCPrint[1, "FDS: Number of the unique integrals: ", 
       Length[FeynCalc`FeynAmpDenominatorSimplify`Private`intsUnique], 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FCPrint[3, "FDS: List of unique integrals ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`intsUnique, 
       FCDoControl -> 
