Options[FeynAmpDenominatorSimplify] = {ApartFF -> False, Collecting -> True, 
     DetectLoopTopologies -> True, ExpandScalarProduct -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCVerbose -> False, Factoring -> Factor, FeynAmpDenominatorCombine -> 
      True, FCLoopPropagatorPowersExpand -> True, 
     FCLoopPropagatorPowersCombine -> True, FCLoopScalelessQ -> True, 
     Rename -> True}
 
FeynAmpDenominatorSimplify /: FeynAmpDenominatorSimplify::usage = "FeynAmpDen\
ominatorSimplify[exp] tries to simplify each PropagatorDenominator\nin a \
canonical way. FeynAmpDenominatorSimplify[exp, q1] simplifies \
all\nFeynAmpDenominators in exp in a canonical way, including momentum \
shifts.\nScaleless integrals are discarded."
 
FeynCalc`FeynAmpDenominatorSimplify`Private`optFCLoopScalelessQ /: 
    FeynCalc`FeynAmpDenominatorSimplify`Private`optFCLoopScalelessQ::usage = 
     ""
 
FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose = 0
 
FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose /: 
    FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose::usage = ""
 
FCLoopScalelessQ[FeynCalc`FCLoopScalelessQ`Private`expr:{__FCTopology}, 
     FeynCalc`FCLoopScalelessQ`Private`opts:OptionsPattern[]] := 
    FCLoopScalelessQ[FeynCalc`FCLoopScalelessQ`Private`expr, {FCGV["dummy"]}, 
     FeynCalc`FCLoopScalelessQ`Private`opts]
 
FCLoopScalelessQ[FeynCalc`FCLoopScalelessQ`Private`expr_FCTopology, 
     FeynCalc`FCLoopScalelessQ`Private`opts:OptionsPattern[]] := 
    FCLoopScalelessQ[FeynCalc`FCLoopScalelessQ`Private`expr, {FCGV["dummy"]}, 
     FeynCalc`FCLoopScalelessQ`Private`opts]
 
FCLoopScalelessQ[FeynCalc`FCLoopScalelessQ`Private`expr_, 
     FeynCalc`FCLoopScalelessQ`Private`lmomsRaw_ /; 
       !OptionQ[FeynCalc`FCLoopScalelessQ`Private`lmomsRaw], 
     OptionsPattern[]] := Block[{FeynCalc`FCLoopScalelessQ`Private`uPoly, 
      FeynCalc`FCLoopScalelessQ`Private`fPoly, 
      FeynCalc`FCLoopScalelessQ`Private`pows, 
      FeynCalc`FCLoopScalelessQ`Private`mat, 
      FeynCalc`FCLoopScalelessQ`Private`Q, 
      FeynCalc`FCLoopScalelessQ`Private`J, 
      FeynCalc`FCLoopScalelessQ`Private`tensorPart, 
      FeynCalc`FCLoopScalelessQ`Private`tensorRank, 
      FeynCalc`FCLoopScalelessQ`Private`res, 
      FeynCalc`FCLoopScalelessQ`Private`time, 
      FeynCalc`FCLoopScalelessQ`Private`x, 
      FeynCalc`FCLoopScalelessQ`Private`lmoms, 
      FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions, 
      FeynCalc`FCLoopScalelessQ`Private`ex, 
      FeynCalc`FCLoopScalelessQ`Private`notList = False, 
      FeynCalc`FCLoopScalelessQ`Private`tmp, 
      FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows, 
      FeynCalc`FCLoopScalelessQ`Private`extraRules}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopScalelessQ`Private`fclsVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopScalelessQ`Private`fclsVerbose = 
          OptionValue[FCVerbose]]; ]; 
      If[Head[FeynCalc`FCLoopScalelessQ`Private`lmomsRaw] =!= List, 
       Message[FCLoopScalelessQ::failmsg, 
         "The second argument must be a list of loop momenta"]; Abort[]]; 
      FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions = 
       OptionValue[FinalSubstitutions]; FCPrint[1, 
       "FCLoopScalelessQ: Entering.", FCDoControl -> 
        FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FCPrint[3, "FCLoopScalelessQ: Entering with: ", 
       FeynCalc`FCLoopScalelessQ`Private`expr, FCDoControl -> 
        FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      If[OptionValue[FCI], {FeynCalc`FCLoopScalelessQ`Private`ex, 
         FeynCalc`FCLoopScalelessQ`Private`lmoms} = 
        {FeynCalc`FCLoopScalelessQ`Private`expr, 
         FeynCalc`FCLoopScalelessQ`Private`lmomsRaw}, 
       {FeynCalc`FCLoopScalelessQ`Private`ex, 
         FeynCalc`FCLoopScalelessQ`Private`lmoms, 
         FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions} = 
        FCI[{FeynCalc`FCLoopScalelessQ`Private`expr, 
          FeynCalc`FCLoopScalelessQ`Private`lmomsRaw, 
          FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions}]]; 
      FeynCalc`FCLoopScalelessQ`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopScalelessQ: Calling FCFeynmanPrepare.", 
       FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      If[FeynCalc`FCLoopScalelessQ`Private`lmomsRaw === {FCGV["dummy"]}, 
       FeynCalc`FCLoopScalelessQ`Private`lmoms = Sequence[]]; 
      Which[MatchQ[FeynCalc`FCLoopScalelessQ`Private`ex, 
         (_.)*_FeynAmpDenominator] || 
        MatchQ[FeynCalc`FCLoopScalelessQ`Private`ex, _GLI | _FCTopology], 
       FeynCalc`FCLoopScalelessQ`Private`notList = True; 
        FeynCalc`FCLoopScalelessQ`Private`tmp = FCFeynmanPrepare[
          FeynCalc`FCLoopScalelessQ`Private`ex, 
          FeynCalc`FCLoopScalelessQ`Private`lmoms, FCI -> True, 
          Names -> FeynCalc`FCLoopScalelessQ`Private`x, Check -> False, 
          Collecting -> OptionValue[Collecting], TimeConstrained -> 
           OptionValue[TimeConstrained], Factoring -> OptionValue[Factoring], 
          FinalSubstitutions -> 
           FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions, 
          FCLoopGetEtaSigns -> False, "IgnoreNumerator" -> True, 
          "MarkNonUnitNumerators" -> True]; 
        FeynCalc`FCLoopScalelessQ`Private`tmp = 
         {FeynCalc`FCLoopScalelessQ`Private`tmp}; 
        FeynCalc`FCLoopScalelessQ`Private`ex = 
         {FeynCalc`FCLoopScalelessQ`Private`ex}, 
       MatchQ[FeynCalc`FCLoopScalelessQ`Private`ex, 
        {__GLI} | {__FCTopology}], FeynCalc`FCLoopScalelessQ`Private`tmp = 
        FCFeynmanPrepare[FeynCalc`FCLoopScalelessQ`Private`ex, 
         FeynCalc`FCLoopScalelessQ`Private`lmoms, FCI -> True, 
         Names -> FeynCalc`FCLoopScalelessQ`Private`x, Check -> False, 
         Collecting -> OptionValue[Collecting], TimeConstrained -> 
          OptionValue[TimeConstrained], Factoring -> OptionValue[Factoring], 
         FinalSubstitutions -> 
          FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions, 
         FCLoopGetEtaSigns -> False, "IgnoreNumerator" -> True, 
         "MarkNonUnitNumerators" -> True], 
       MatchQ[FeynCalc`FCLoopScalelessQ`Private`ex, 
        {(_.)*_FeynAmpDenominator..}], 
       FeynCalc`FCLoopScalelessQ`Private`tmp = 
        (FCFeynmanPrepare[#1, FeynCalc`FCLoopScalelessQ`Private`lmoms, 
           FCI -> True, Names -> FeynCalc`FCLoopScalelessQ`Private`x, 
           Check -> False, Collecting -> OptionValue[Collecting], 
           TimeConstrained -> OptionValue[TimeConstrained], 
           Factoring -> OptionValue[Factoring], FinalSubstitutions -> 
            FeynCalc`FCLoopScalelessQ`Private`optFinalSubstitutions, 
           FCLoopGetEtaSigns -> False, "IgnoreNumerator" -> True, 
           "MarkNonUnitNumerators" -> True] & ) /@ 
         FeynCalc`FCLoopScalelessQ`Private`ex, True, 
       Message[FCLoopScalelessQ::failmsg, 
         "Failed to recognize the form of the input expression."]; Abort[]]; 
      FCPrint[1, "FCLoopScalelessQ: FCFeynmanPrepare done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopScalelessQ`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FeynCalc`FCLoopScalelessQ`Private`tmp = 
       Transpose[FeynCalc`FCLoopScalelessQ`Private`tmp]; 
      {FeynCalc`FCLoopScalelessQ`Private`uPoly, 
        FeynCalc`FCLoopScalelessQ`Private`fPoly} = 
       FeynCalc`FCLoopScalelessQ`Private`tmp[[1 ;; 2]]; 
      FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows = 
       Position[Last[FeynCalc`FCLoopScalelessQ`Private`tmp], True]; 
      FCPrint[3, "FCLoopScalelessQ: U: ", 
       FeynCalc`FCLoopScalelessQ`Private`uPoly, FCDoControl -> 
        FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FCPrint[3, "FCLoopScalelessQ: F: ", 
       FeynCalc`FCLoopScalelessQ`Private`fPoly, FCDoControl -> 
        FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FCPrint[3, "FCLoopScalelessQ: Negative propagator powers: ", 
       FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows, 
       FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FeynCalc`FCLoopScalelessQ`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopScalelessQ: Calling FCPakScalelessQ.", 
       FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FeynCalc`FCLoopScalelessQ`Private`res = 
       MapThread[FCLoopPakScalelessQ[#1*#2, 
          FeynCalc`FCLoopScalelessQ`Private`x] & , 
        {FeynCalc`FCLoopScalelessQ`Private`uPoly, 
         FeynCalc`FCLoopScalelessQ`Private`fPoly}]; 
      FCPrint[1, "FCLoopScalelessQ: FCPakScalelessQ done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopScalelessQ`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      If[FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows =!= {}, 
       If[OptionValue[FCFeynmanParametrize], 
        FeynCalc`FCLoopScalelessQ`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCLoopScalelessQ: Calling FCFeynmanParametrize.", 
          FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
         FeynCalc`FCLoopScalelessQ`Private`extraRules = 
          MapThread[FeynCalc`FCLoopScalelessQ`Private`checkIntsWithNumerators[
             #1, FeynCalc`FCLoopScalelessQ`Private`lmoms, #2] & , 
           {Extract[FeynCalc`FCLoopScalelessQ`Private`ex, 
             FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows], 
            Extract[FeynCalc`FCLoopScalelessQ`Private`res, 
             FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows]}]; 
         FCPrint[1, "FCLoopScalelessQ: FCFeynmanParametrize done, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCLoopScalelessQ`Private`time, 4], 
          FCDoControl -> FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
         FeynCalc`FCLoopScalelessQ`Private`extraRules = 
          Thread[FeynCalc`FCLoopScalelessQ`Private`intsWithNegativePows -> 
             FeynCalc`FCLoopScalelessQ`Private`extraRules] /. 
           (_ -> False) -> Unevaluated[Sequence[]]; 
         FCPrint[3, "FCLoopScalelessQ: extraRules: ", 
          FeynCalc`FCLoopScalelessQ`Private`extraRules, FCDoControl -> 
           FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
         If[ !MatchQ[FeynCalc`FCLoopScalelessQ`Private`extraRules, 
            {(_ -> True)...}], Message[FCLoopScalelessQ::failmsg, "Something \
went wrong when determining extra vanishing integrals."]; Abort[]]; 
         If[FeynCalc`FCLoopScalelessQ`Private`extraRules =!= {}, 
          FeynCalc`FCLoopScalelessQ`Private`extraRules = 
            FeynCalc`FCLoopScalelessQ`Private`extraRules[[All,1]]; 
           FeynCalc`FCLoopScalelessQ`Private`res = 
            FeynCalc`FCLoopScalelessQ`Private`ReplaceAt[
             FeynCalc`FCLoopScalelessQ`Private`res, _ -> True, 
             FeynCalc`FCLoopScalelessQ`Private`extraRules]]]]; 
      If[FeynCalc`FCLoopScalelessQ`Private`notList, 
       FeynCalc`FCLoopScalelessQ`Private`res = 
        First[FeynCalc`FCLoopScalelessQ`Private`res]]; 
      FCPrint[3, "FCLoopScalelessQ: Leaving.", FCDoControl -> 
        FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FCPrint[3, "FCLoopScalelessQ: Leaving with: ", 
       FeynCalc`FCLoopScalelessQ`Private`res, FCDoControl -> 
        FeynCalc`FCLoopScalelessQ`Private`fclsVerbose]; 
      FeynCalc`FCLoopScalelessQ`Private`res]
 
Options[FCLoopScalelessQ] = {Collecting -> True, FeynCalcInternal -> False, 
     FCVerbose -> False, Factoring -> {Factor2, 5000}, 
     FCFeynmanParametrize -> True, FinalSubstitutions -> {}, 
     TimeConstrained -> 3}
 
FCLoopScalelessQ /: FCLoopScalelessQ::failmsg = "Error! FCLoopScalelessQ has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCLoopScalelessQ /: FCLoopScalelessQ::usage = "FCLoopScalelessQ[int, {p1, p2, \
...}] checks whether the loop integral int\ndepending on the loop momenta p1, \
p2, ... is scaleless. Only integrals that\nadmit a Feynman parametrization \
with proper $U$ and $F$ polynomials are\nsupported.\n\nThe function uses the \
algorithm of Alexey Pak\n[arXiv:1111.0868](https://arxiv.org/abs/1111.0868). \
Cf. also the PhD thesis of\nJens Hoff \
[10.5445/IR/1000047447](https://doi.org/10.5445/IR/1000047447) for\nthe \
detailed description of a possible implementation."
 
FCTopology /: FCTopology::usage = "FCTopology[id, {prop1, prop2, ...}, {l1, \
l2, ...}, {p1, p2, ...}, {kRule1,\nkRule2, ...}, {}] denotes a topology with \
the identifier id that is\ncharacterized by the propagators {prop1, prop2, \
...}. The propagators in the\nlist do not necessarily have to form a valid \
basis, i.e. the basis may also be\nincomplete or overdetermined. The lists \
{l1, l2, ...} and {p1, p2, ...} stand\nfor the loop and external momenta \
respectively. Furthermore, {kRule1, kRule2,\n...} denotes replacement rules \
for kinematic invariants.\n\nThe last argument (an empty list) is reserved \
for future improvements."
 
FeynCalc`FCLoopScalelessQ`Private`fclsVerbose = 0
 
FeynCalc`FCLoopScalelessQ`Private`fclsVerbose /: 
    FeynCalc`FCLoopScalelessQ`Private`fclsVerbose::usage = ""
 
GLI /: MakeBoxes[GLI[FeynCalc`SharedObjectsTypesetting`Private`id_, 
       FeynCalc`SharedObjectsTypesetting`Private`indices_List], 
      TraditionalForm] := RowBox[{SuperscriptBox["G", 
        ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`id]], "(", 
       TBox[Sequence @@ Riffle[
          FeynCalc`SharedObjectsTypesetting`Private`indices, ","]], ")"}]
 
GLI /: GLI::usage = "GLI[id,{indices}] is a generic loop integral, where the \
indices denote powers\nof propagators in the propagator basis (FCTopology) \
named id."
 
FCFeynmanPrepare[FeynCalc`FCFeynmanPrepare`Private`gli_, 
     FeynCalc`FCFeynmanPrepare`Private`topos:{__FCTopology}, 
     FeynCalc`FCFeynmanPrepare`Private`opts:OptionsPattern[]] := 
    FCFeynmanPrepare[FeynCalc`FCFeynmanPrepare`Private`gli, 
      FCLoopSelectTopology[FeynCalc`FCFeynmanPrepare`Private`gli, 
       FeynCalc`FCFeynmanPrepare`Private`topos], 
      FeynCalc`FCFeynmanPrepare`Private`opts] /; 
     MatchQ[FeynCalc`FCFeynmanPrepare`Private`gli, 
      _GLI | _GLI^_ | HoldPattern[Times][(_GLI | _GLI^_)..]]
 
FCFeynmanPrepare[FeynCalc`FCFeynmanPrepare`Private`gli_, 
     FeynCalc`FCFeynmanPrepare`Private`topo_FCTopology, 
     FeynCalc`FCFeynmanPrepare`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FCFeynmanPrepare`Private`int, 
       FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions, 
       FeynCalc`FCFeynmanPrepare`Private`lmomsHead, 
       FeynCalc`FCFeynmanPrepare`Private`lmoms, 
       FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta}, 
      If[OptionValue[FCVerbose] === False, 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[FCVerbose], _Integer], 
          FeynCalc`FCFeynmanPrepare`Private`fcszVerbose = 
           OptionValue[FCVerbose]]; ]; FCPrint[1, 
        "FCFeynmanPrepare: Entry point: single GLI and single topology ", 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta = 
        OptionValue[LoopMomenta]; 
       FeynCalc`FCFeynmanPrepare`Private`lmomsHead = 
        Head[FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta[1, 1]]; 
       FeynCalc`FCFeynmanPrepare`Private`int = FCLoopFromGLI[
         FeynCalc`FCFeynmanPrepare`Private`gli, 
         FeynCalc`FCFeynmanPrepare`Private`topo, FCI -> OptionValue[FCI], 
         LoopMomenta -> FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta, 
         FeynAmpDenominatorExplicit -> False, FCParallelize -> 
          OptionValue[FCParallelize]]; FCPrint[1, 
        "FCFeynmanPrepare: After FCLoopFromGLI: ", 
        FeynCalc`FCFeynmanPrepare`Private`int, FCDoControl -> 
         FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions = 
        Join[OptionValue[FinalSubstitutions], 
         FeynCalc`FCFeynmanPrepare`Private`topo[[5]]]; 
       If[ !OptionValue[FCI], 
        FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions = 
         FCI[FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions]]; 
       FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions = 
        FCI[FRH[FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions]]; 
       If[ !FreeQ[FeynCalc`FCFeynmanPrepare`Private`int, 
          FeynCalc`FCFeynmanPrepare`Private`lmomsHead], 
        FeynCalc`FCFeynmanPrepare`Private`lmoms = 
         Join[Cases2[FeynCalc`FCFeynmanPrepare`Private`int, 
           FeynCalc`FCFeynmanPrepare`Private`lmomsHead], 
          FeynCalc`FCFeynmanPrepare`Private`topo[[3]]], 
        FeynCalc`FCFeynmanPrepare`Private`lmoms = 
         FeynCalc`FCFeynmanPrepare`Private`topo[[3]]]; 
       FCFeynmanPrepare[FeynCalc`FCFeynmanPrepare`Private`int, 
        FeynCalc`FCFeynmanPrepare`Private`lmoms, 
        Join[{FCI -> True, FinalSubstitutions -> 
           FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions}, 
         FilterRules[{FeynCalc`FCFeynmanPrepare`Private`opts}, 
          Except[FCI | FinalSubstitutions]]]]] /; 
     MatchQ[FeynCalc`FCFeynmanPrepare`Private`gli, {__GLI}] || 
      MatchQ[FeynCalc`FCFeynmanPrepare`Private`gli, _GLI | _GLI^_ | 
        HoldPattern[Times][(_GLI | _GLI^_)..]]
 
FCFeynmanPrepare[FeynCalc`FCFeynmanPrepare`Private`glis_, 
     FeynCalc`FCFeynmanPrepare`Private`topos:{__FCTopology}, 
     FeynCalc`FCFeynmanPrepare`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FCFeynmanPrepare`Private`ints, 
       FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions, 
       FeynCalc`FCFeynmanPrepare`Private`relTopos, 
       FeynCalc`FCFeynmanPrepare`Private`lmomsList, 
       FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta, 
       FeynCalc`FCFeynmanPrepare`Private`lmomsHead, 
       FeynCalc`FCFeynmanPrepare`Private`time, 
       FeynCalc`FCFeynmanPrepare`Private`res, 
       FeynCalc`FCFeynmanPrepare`Private`time1, 
       FeynCalc`FCFeynmanPrepare`Private`optFCParallelize}, 
      If[OptionValue[FCVerbose] === False, 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[FCVerbose], _Integer], 
          FeynCalc`FCFeynmanPrepare`Private`fcszVerbose = 
           OptionValue[FCVerbose]]; ]; FCPrint[1, "FCFeynmanPrepare: Entry \
point: multiple GLIs and multiple topologies.", FCDoControl -> 
         FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta = 
        OptionValue[LoopMomenta]; 
       FeynCalc`FCFeynmanPrepare`Private`optFCParallelize = 
        OptionValue[FCParallelize]; 
       FeynCalc`FCFeynmanPrepare`Private`lmomsHead = 
        Head[FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta[1, 1]]; 
       FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
       FCPrint[1, "FCFeynmanPrepare: Applying FCLoopFromGLI.", 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`ints = FCLoopFromGLI[
         FeynCalc`FCFeynmanPrepare`Private`glis, 
         FeynCalc`FCFeynmanPrepare`Private`topos, FCI -> OptionValue[FCI], 
         LoopMomenta -> FeynCalc`FCFeynmanPrepare`Private`optLoopMomenta, 
         FeynAmpDenominatorExplicit -> False, FCParallelize -> 
          FeynCalc`FCFeynmanPrepare`Private`optFCParallelize]; 
       FCPrint[1, "FCFeynmanPrepare: Done applying FCLoopFromGLI, timing: ", 
        N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FCPrint[3, "FCFeynmanPrepare: After FCLoopFromGLI: ", 
        FeynCalc`FCFeynmanPrepare`Private`ints, FCDoControl -> 
         FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
       FCPrint[1, "FCFeynmanPrepare: Applying FCLoopSelectTopology.", 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`relTopos = FCLoopSelectTopology[
         FeynCalc`FCFeynmanPrepare`Private`glis, 
         FeynCalc`FCFeynmanPrepare`Private`topos, Check -> False, 
         "OneToOneCorrespondence" -> True]; FCPrint[1, 
        "FCFeynmanPrepare: Done applying FCLoopSelectTopology, timing: ", 
        N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
       FCPrint[1, "FCFeynmanPrepare: Doing some intermediate steps.", 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       If[ !MatchQ[FeynCalc`FCFeynmanPrepare`Private`relTopos, 
          {{__FCTopology}..}], Message[FCFeynmanPrepare::failmsg, "Something \
went wrong when extracting topologies relevant for the given GLIs."]; 
         Abort[]]; FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions = 
        Flatten /@ Function[FeynCalc`FCFeynmanPrepare`Private`x, 
           (#1[[5]] & ) /@ FeynCalc`FCFeynmanPrepare`Private`x] /@ 
          FeynCalc`FCFeynmanPrepare`Private`relTopos; 
       FeynCalc`FCFeynmanPrepare`Private`lmomsList = 
        Union[Flatten[(#1[[3]] & ) /@ Flatten[
            FeynCalc`FCFeynmanPrepare`Private`relTopos]]]; 
       If[ !FreeQ[FeynCalc`FCFeynmanPrepare`Private`ints, 
          FeynCalc`FCFeynmanPrepare`Private`lmomsHead], 
        FeynCalc`FCFeynmanPrepare`Private`lmomsList = 
          Join[FeynCalc`FCFeynmanPrepare`Private`lmomsList, 
           Cases2[FeynCalc`FCFeynmanPrepare`Private`ints, 
            FeynCalc`FCFeynmanPrepare`Private`lmomsHead]]; ]; 
       FCPrint[1, "FCFeynmanPrepare: All loop momenta: ", 
        FeynCalc`FCFeynmanPrepare`Private`lmomsList, FCDoControl -> 
         FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       If[ !OptionValue[FCI], 
        FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions = 
         FCI[FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions]]; 
       FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions = 
        FCI[FRH[FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions]]; 
       FCPrint[1, "FCFeynmanPrepare: Intermediate steps done, timing: ", 
        N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
        FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
       FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
       If[$ParallelizeFeynCalc && 
         FeynCalc`FCFeynmanPrepare`Private`optFCParallelize, 
        FCPrint[1, 
          "FCFeynmanPrepare: Applying FCFeynmanPrepare in parallel.", 
          FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
         With[{FeynCalc`FCFeynmanPrepare`Private`xxx = 
            FeynCalc`FCFeynmanPrepare`Private`lmomsList}, 
          ParallelEvaluate[FCContext`FCFeynmanPrepare`lmomsList = 
             FeynCalc`FCFeynmanPrepare`Private`xxx; , DistributedContexts -> 
            None]]; FeynCalc`FCFeynmanPrepare`Private`res = 
          ParallelMap[FCFeynmanPrepare[#1[[1]], 
             FCContext`FCFeynmanPrepare`lmomsList, Join[{FCI -> True, 
               FinalSubstitutions -> #1[[2]]}, FilterRules[{
                FeynCalc`FCFeynmanPrepare`Private`opts}, Except[
                FCI | FinalSubstitutions | FCVerbose]]]] & , 
           Transpose[{FeynCalc`FCFeynmanPrepare`Private`ints, 
             FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions}], 
           DistributedContexts -> None, Method -> "ItemsPerEvaluation" -> 
             Ceiling[N[Length[FeynCalc`FCFeynmanPrepare`Private`ints]/
                 $KernelCount]/10]]; FCPrint[1, "FCFeynmanPrepare: Done \
applying FCFeynmanPrepare in parallel, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
          FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose], 
        FCPrint[1, "FCFeynmanPrepare: Applying FCFeynmanPrepare.", 
          FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
         FeynCalc`FCFeynmanPrepare`Private`res = MapThread[
           FCFeynmanPrepare[#1, FeynCalc`FCFeynmanPrepare`Private`lmomsList, 
             Join[{FCI -> True, FinalSubstitutions -> #2}, FilterRules[{
                FeynCalc`FCFeynmanPrepare`Private`opts}, Except[
                FCI | FinalSubstitutions | FCVerbose]]]] & , 
           {FeynCalc`FCFeynmanPrepare`Private`ints, 
            FeynCalc`FCFeynmanPrepare`Private`finalSubstitutions}]; 
         FCPrint[1, 
          "FCFeynmanPrepare: Done applying FCFeynmanPrepare, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
          FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]]; 
       FeynCalc`FCFeynmanPrepare`Private`res] /; 
     MatchQ[FeynCalc`FCFeynmanPrepare`Private`glis, {__GLI}] || 
      MatchQ[FeynCalc`FCFeynmanPrepare`Private`glis, 
