         FeynCalc`FCFeynmanPrepare`Private`qkspd}]; 
      FCPrint[3, "FCFeynmanPrepare: fpJ: ", 
       FeynCalc`FCFeynmanPrepare`Private`fpJ, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`fpQ = SelectNotFree2[
        FeynCalc`FCFeynmanPrepare`Private`tmp0, 
        FeynCalc`FCFeynmanPrepare`Private`qkspd]; 
      FCPrint[3, "FCFeynmanPrepare: raw fpQ: ", 
       FeynCalc`FCFeynmanPrepare`Private`fpQ, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[ !FeynCalc`FCFeynmanPrepare`Private`isCartesian, 
       FeynCalc`FCFeynmanPrepare`Private`fpQ = 
        (SelectNotFree2[(-2^(-1))*FeynCalc`FCFeynmanPrepare`Private`fpQ, 
            #1] /. FeynCalc`FCFeynmanPrepare`Private`qkspd[
             FeynCalc`FCFeynmanPrepare`Private`a_, #1] :> 
            Pair[Momentum[FeynCalc`FCFeynmanPrepare`Private`a, 
              FeynCalc`FCFeynmanPrepare`Private`dim], LorentzIndex[
              FeynCalc`FCFeynmanPrepare`Private`li, 
              FeynCalc`FCFeynmanPrepare`Private`dim]] & ) /@ 
         FeynCalc`FCFeynmanPrepare`Private`lmoms, 
       FeynCalc`FCFeynmanPrepare`Private`fpQ = 
         (SelectNotFree2[(-2^(-1))*FeynCalc`FCFeynmanPrepare`Private`fpQ, 
             #1] /. FeynCalc`FCFeynmanPrepare`Private`qkspd[
              FeynCalc`FCFeynmanPrepare`Private`a_, #1] :> CartesianPair[
              CartesianMomentum[FeynCalc`FCFeynmanPrepare`Private`a, 
               FeynCalc`FCFeynmanPrepare`Private`dim], CartesianIndex[
               FeynCalc`FCFeynmanPrepare`Private`ci, 
               FeynCalc`FCFeynmanPrepare`Private`dim]] & ) /@ 
          FeynCalc`FCFeynmanPrepare`Private`lmoms; ]; 
      FCPrint[3, "FCFeynmanPrepare: final fpQ: ", 
       FeynCalc`FCFeynmanPrepare`Private`fpQ, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[1, "FCFeynmanPrepare: Q and J ready, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCFeynmanPrepare: Constructing M.", 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`tmp0 = 
       FeynCalc`FCFeynmanPrepare`Private`tmp0 /. 
        FeynCalc`FCFeynmanPrepare`Private`spd[
          FeynCalc`FCFeynmanPrepare`Private`a_, 
          FeynCalc`FCFeynmanPrepare`Private`b_] :> 
         (1/2)*(FeynCalc`FCFeynmanPrepare`Private`spd[
            FeynCalc`FCFeynmanPrepare`Private`a, 
            FeynCalc`FCFeynmanPrepare`Private`b] + 
           FeynCalc`FCFeynmanPrepare`Private`spd[
            FeynCalc`FCFeynmanPrepare`Private`b, 
            FeynCalc`FCFeynmanPrepare`Private`a]); 
      FCPrint[3, "FCFeynmanPrepare: tmp0: ", 
       FeynCalc`FCFeynmanPrepare`Private`tmp0, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`mtmp = SelectNotFree2[
        FeynCalc`FCFeynmanPrepare`Private`tmp0, 
        FeynCalc`FCFeynmanPrepare`Private`spd]; 
      FCPrint[3, "FCFeynmanPrepare: mtmp: ", 
       FeynCalc`FCFeynmanPrepare`Private`mtmp, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`matrix = 
       Outer[FeynCalc`FCFeynmanPrepare`Private`spd, 
         FeynCalc`FCFeynmanPrepare`Private`lmoms, 
         FeynCalc`FCFeynmanPrepare`Private`lmoms] /. 
        FeynCalc`FCFeynmanPrepare`Private`a_FeynCalc`FCFeynmanPrepare`Private\
`spd :> Coefficient[FeynCalc`FCFeynmanPrepare`Private`mtmp, 
          FeynCalc`FCFeynmanPrepare`Private`a]; 
      FCPrint[3, "FCFeynmanPrepare: M: ", 
       FeynCalc`FCFeynmanPrepare`Private`matrix, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[1, "FCFeynmanPrepare: M ready, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCFeynmanPrepare: Constructing U and F.", 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`tmp = ExpandScalarProduct[
        FeynCalc`FCFeynmanPrepare`Private`tmp, Momentum -> 
         FeynCalc`FCFeynmanPrepare`Private`lmoms, FCI -> True]; 
      FCPrint[3, "FCFeynmanPrepare: tmp for buildF: ", 
       FeynCalc`FCFeynmanPrepare`Private`tmp, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      {FeynCalc`FCFeynmanPrepare`Private`symU, 
        FeynCalc`FCFeynmanPrepare`Private`symF} = 
       Fold[FeynCalc`FCFeynmanPrepare`Private`buildF, 
        {1, FeynCalc`FCFeynmanPrepare`Private`tmp}, 
        FeynCalc`FCFeynmanPrepare`Private`lmoms]; 
      FCPrint[1, "FCFeynmanPrepare: U and F ready, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[3, "FCFeynmanPrepare: Raw U: ", 
       FeynCalc`FCFeynmanPrepare`Private`symU, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[3, "FCFeynmanPrepare: Raw F: ", 
       FeynCalc`FCFeynmanPrepare`Private`symF, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[FeynCalc`FCFeynmanPrepare`Private`tensorPart =!= 1, 
       FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCFeynmanPrepare: Constructing N.", 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
        FeynCalc`FCFeynmanPrepare`Private`tensorPart = 
         FeynCalc`FCFeynmanPrepare`Private`buildN[
          FeynCalc`FCFeynmanPrepare`Private`tensorPart, 
          FeynCalc`FCFeynmanPrepare`Private`symU, 
          FeynCalc`FCFeynmanPrepare`Private`matrix, 
          FeynCalc`FCFeynmanPrepare`Private`fpQ, 
          FeynCalc`FCFeynmanPrepare`Private`powers, 
          FeynCalc`FCFeynmanPrepare`Private`lmoms]; 
        FCPrint[1, "FCFeynmanPrepare: N ready, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; ]; 
      If[ !FeynCalc`FCFeynmanPrepare`Private`isCartesian && 
         !FeynCalc`FCFeynmanPrepare`Private`optEuclidean, 
       FeynCalc`FCFeynmanPrepare`Private`res = 
        {FeynCalc`FCFeynmanPrepare`Private`symU, 
         -Together[FeynCalc`FCFeynmanPrepare`Private`symU*
             FeynCalc`FCFeynmanPrepare`Private`symF] - 
          I*FeynCalc`FCFeynmanPrepare`Private`etaSigns[[1]]*SMP["Eta"], 
         FeynCalc`FCFeynmanPrepare`Private`powers, 
         FeynCalc`FCFeynmanPrepare`Private`matrix, 
         FeynCalc`FCFeynmanPrepare`Private`fpQ, 
         FeynCalc`FCFeynmanPrepare`Private`fpJ, 
         FeynCalc`FCFeynmanPrepare`Private`tensorPart, 
         FeynCalc`FCFeynmanPrepare`Private`tensorRank}, 
       FeynCalc`FCFeynmanPrepare`Private`res = 
         {FeynCalc`FCFeynmanPrepare`Private`symU, 
          Together[FeynCalc`FCFeynmanPrepare`Private`symU*
             FeynCalc`FCFeynmanPrepare`Private`symF] + 
           I*FeynCalc`FCFeynmanPrepare`Private`etaSigns[[1]]*SMP["Eta"], 
          FeynCalc`FCFeynmanPrepare`Private`powers, 
          FeynCalc`FCFeynmanPrepare`Private`matrix, 
          FeynCalc`FCFeynmanPrepare`Private`fpQ, 
          FeynCalc`FCFeynmanPrepare`Private`fpJ, 
          FeynCalc`FCFeynmanPrepare`Private`tensorPart, 
          FeynCalc`FCFeynmanPrepare`Private`tensorRank}; ]; 
      If[ !OptionValue[EtaSign], FeynCalc`FCFeynmanPrepare`Private`res = 
        FeynCalc`FCFeynmanPrepare`Private`res /. SMP["Eta"] -> 0]; 
      If[OptionValue[Check] && {FeynCalc`FCFeynmanPrepare`Private`symU, 
          FeynCalc`FCFeynmanPrepare`Private`symF} =!= {0, 0}, 
       FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCFeynmanPrepare: Checking the results.", 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
        If[ !FeynCalc`FCFeynmanPrepare`Private`isCartesian && 
           !FeynCalc`FCFeynmanPrepare`Private`optEuclidean, 
         If[Factor[Together[FeynCalc`FCFeynmanPrepare`Private`symU*(
                ExpandScalarProduct[Contract[
                  FeynCalc`FCFeynmanPrepare`Private`fpQ . Inverse[
                    FeynCalc`FCFeynmanPrepare`Private`matrix] . 
                   FeynCalc`FCFeynmanPrepare`Private`fpQ, FCI -> True], 
                 FCI -> True] - FeynCalc`FCFeynmanPrepare`Private`fpJ) - 
              (FeynCalc`FCFeynmanPrepare`Private`res[[2]] /. SMP["Eta"] -> 
                0)]] =!= 0, Message[FCFeynmanPrepare::failmsg, 
            "The obtained Q and J are incorrect."]; Abort[]], 
         If[Factor[Together[FeynCalc`FCFeynmanPrepare`Private`symU*(
                -ExpandScalarProduct[Contract[
                   FeynCalc`FCFeynmanPrepare`Private`fpQ . Inverse[
                     FeynCalc`FCFeynmanPrepare`Private`matrix] . 
                    FeynCalc`FCFeynmanPrepare`Private`fpQ, FCI -> True], 
                  FCI -> True] + FeynCalc`FCFeynmanPrepare`Private`fpJ) - 
              (FeynCalc`FCFeynmanPrepare`Private`res[[2]] /. SMP["Eta"] -> 
                0)]] =!= 0, Message[FCFeynmanPrepare::failmsg, 
            "The obtained Q and J are incorrect."]; Abort[]]]; 
        If[Simplify[Det[FeynCalc`FCFeynmanPrepare`Private`matrix] - 
             FeynCalc`FCFeynmanPrepare`Private`symU] =!= 0 || 
           !SymmetricMatrixQ[FeynCalc`FCFeynmanPrepare`Private`matrix], 
         Message[FCFeynmanPrepare::failmsg, 
           "Something went wrong when calculating the matrix M!"]; Abort[]]; 
        FCPrint[1, "FCFeynmanPrepare: Checks done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]]; 
      If[FeynCalc`FCFeynmanPrepare`Private`tcHideRule =!= {}, 
       FeynCalc`FCFeynmanPrepare`Private`res = 
        FeynCalc`FCFeynmanPrepare`Private`res /. Reverse /@ 
          FeynCalc`FCFeynmanPrepare`Private`tcHideRule]; 
      FCPrint[3, "FCFeynmanPrepare: Preliminary result: ", 
       FeynCalc`FCFeynmanPrepare`Private`res, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions =!= {}, 
       FeynCalc`FCFeynmanPrepare`Private`res = 
        FeynCalc`FCFeynmanPrepare`Private`res //. 
         FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions]; 
      If[FeynCalc`FCFeynmanPrepare`Private`nDenoms > 1 && 
        OptionValue[Reduce], FeynCalc`FCFeynmanPrepare`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCFeynmanPrepare: Reducing the number of Feynman parameters.", 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
        FeynCalc`FCFeynmanPrepare`Private`constraint = 
         Sum[FeynCalc`FCFeynmanPrepare`Private`feynX[[
            FeynCalc`FCFeynmanPrepare`Private`i]], 
           {FeynCalc`FCFeynmanPrepare`Private`i, 1, 
            FeynCalc`FCFeynmanPrepare`Private`nDenoms}] == 1; 
        FCPrint[3, "FCFeynmanPrepare: Constraint on the values of the Feynman \
parameters: ", FeynCalc`FCFeynmanPrepare`Private`constraint, 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
        FeynCalc`FCFeynmanPrepare`Private`res = 
         Simplify[FeynCalc`FCFeynmanPrepare`Private`res, 
          FeynCalc`FCFeynmanPrepare`Private`constraint]; 
        FCPrint[1, "FCFeynmanPrepare: Reductions done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]]; 
      If[OptionValue[Collecting], FeynCalc`FCFeynmanPrepare`Private`time = 
         AbsoluteTime[]; FCPrint[1, 
         "FCFeynmanPrepare: Collecting terms in the final result.", 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
        FeynCalc`FCFeynmanPrepare`Private`res = 
         Collect2[FeynCalc`FCFeynmanPrepare`Private`res, LorentzIndex, 
          CartesianIndex, Factoring -> OptionValue[Factoring], 
          TimeConstrained -> OptionValue[TimeConstrained]]; 
        FCPrint[1, "FCFeynmanPrepare: Done collecting terms, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
         FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
        FCPrint[3, 
         "FCFeynmanPrepare: After applying Collect2 to the result: ", 
         FeynCalc`FCFeynmanPrepare`Private`res, FCDoControl -> 
          FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]]; 
      If[OptionValue[FCE], FeynCalc`FCFeynmanPrepare`Private`res = 
        FCE[FeynCalc`FCFeynmanPrepare`Private`res]]; 
      If[OptionValue["MarkNonUnitNumerators"], 
       FeynCalc`FCFeynmanPrepare`Private`res = 
        Join[FeynCalc`FCFeynmanPrepare`Private`res, 
         {FeynCalc`FCFeynmanPrepare`Private`nonUnitNum}]]; 
      If[OptionValue["AddLoopMomentaAndKinematics"], 
       FeynCalc`FCFeynmanPrepare`Private`res = 
        Join[FeynCalc`FCFeynmanPrepare`Private`res, 
         {FeynCalc`FCFeynmanPrepare`Private`lmoms}, 
         {FeynCalc`FCFeynmanPrepare`Private`optFinalSubstitutions}]]; 
      FCPrint[1, "FCFeynmanPrepare: Leaving.", FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[3, "FCFeynmanPrepare: Leaving with: ", 
       FeynCalc`FCFeynmanPrepare`Private`res, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`res]
 
Options[FCFeynmanPrepare] = {FCFeynmanParameterJoin -> False, 
     CartesianIndexNames -> FCGV["i"], Check -> True, Collecting -> True, 
     "Euclidean" -> False, EtaSign -> False, ExtraPropagators -> {}, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCParallelize -> False, FCLoopGetEtaSigns -> True, 
     FCReplaceMomenta -> {}, FCVerbose -> False, 
     Factoring -> {Factor2, 5000}, FinalSubstitutions -> {}, Indexed -> True, 
     "IgnoreNumerator" -> False, "MarkNonUnitNumerators" -> False, 
     "AddLoopMomentaAndKinematics" -> False, LoopMomenta -> 
      Function[{FeynCalc`FCFeynmanPrepare`Private`x, 
        FeynCalc`FCFeynmanPrepare`Private`y}, FCGV["lmom"][
        FeynCalc`FCFeynmanPrepare`Private`x, 
        FeynCalc`FCFeynmanPrepare`Private`y]], LorentzIndexNames -> 
      FCGV["mu"], Names -> FCGV["x"], Reduce -> False, 
     SortBy -> Function[FeynCalc`FCFeynmanPrepare`Private`x, 
       FeynCalc`FCFeynmanPrepare`Private`x[[2]] < 0], TimeConstrained -> 3}
 
FCFeynmanPrepare /: FCFeynmanPrepare::failmsg = "Error! FCFeynmanPrepare has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCFeynmanPrepare /: FCFeynmanPrepare::usage = "FCFeynmanPrepare[int, {q1, q2, \
...}] is an auxiliary function that returns all\nnecessary building for \
writing down a Feynman parametrization of the given\ntensor or scalar \
multi-loop integral. The integral int can be Lorentzian or\nCartesian.\n\nThe \
output of the function is a list given by {U,F, pows, M, Q, J, N, r},\nwhere \
U and F are the Symanzik polynomials, with $U = det M$, while pows\ncontains \
the powers of the occurring propagators. The vector Q and the\nfunction J are \
the usual quantities appearing in the definition of the F\npolynomial.\n\nIf \
the integral has free indices, then N encodes its tensor structure, while \
r\ngives its tensor rank. For scalar integrals N is always 1 and r is 0. In N \
the\nF-polynomial is not substituted but left as FCGV[\"F\"].\n\nTo ensure a \
certain correspondence between propagators and Feynman parameters,\nit is \
also possible to enter the integral as a list of propagators, \
e.g.\nFCFeynmanPrepare[{FAD[{q,m1}],FAD[{q-p,m2}],SPD[p,q]},{q}]. In this \
case the\ntensor part of the integral should be the very last element of the \
list.\n\nIt is also possible to invoke the function as \
FCFeynmanPrepare[GLI[...],\nFCTopology[...]] or \
FCFeynmanPrepare[FCTopology[...]]. Notice that in this\ncase the value of the \
option FinalSubstitutions is ignored, as replacement\nrules will be extracted \
directly from the definition of the topology.\n\nThe definitions of M, Q, J \
and N follow from Eq. 4.17 in the [PhD Thesis of\nStefan \
Jahn](http://mediatum.ub.tum.de/?id=1524691) \
and\n[arXiv:1010.1667](https://arxiv.org/abs/1010.1667).The algorithm for \
deriving\nthe UF-parametrization of a loop integral was adopted from the UF \
generator\navailable in multiple codes of Alexander Smirnov, such as \
FIESTA\n([arXiv:1511.03614](https://arxiv.org/abs/1511.03614)) and \
FIRE\n([arXiv:1901.07808](https://arxiv.org/abs/1901.07808)). The code UF.m \
is also\nmentioned in the book \"Analytic Tools for Feynman Integrals\" by \
Vladimir\nSmirnov, Chapter 2.3."
 
FCLoopSelectTopology[FeynCalc`FCLoopSelectTopology`Private`glisRaw_, 
     FeynCalc`FCLoopSelectTopology`Private`topo_FCTopology, 
     FeynCalc`FCLoopSelectTopology`Private`opts:OptionsPattern[]] := 
    FCLoopSelectTopology[FeynCalc`FCLoopSelectTopology`Private`glisRaw, 
     {FeynCalc`FCLoopSelectTopology`Private`topo}, 
     FeynCalc`FCLoopSelectTopology`Private`opts]
 
FCLoopSelectTopology[FeynCalc`FCLoopSelectTopology`Private`ex_ /; 
      Head[FeynCalc`FCLoopSelectTopology`Private`ex] =!= List, 
     FeynCalc`FCLoopSelectTopology`Private`topos:{__FCTopology}, 
     FeynCalc`FCLoopSelectTopology`Private`opts:OptionsPattern[]] := 
    First[FCLoopSelectTopology[{FeynCalc`FCLoopSelectTopology`Private`ex}, 
      FeynCalc`FCLoopSelectTopology`Private`topos, 
      FeynCalc`FCLoopSelectTopology`Private`opts]]
 
FCLoopSelectTopology[FeynCalc`FCLoopSelectTopology`Private`glisRaw_List, 
     FeynCalc`FCLoopSelectTopology`Private`topos:{__FCTopology}, 
     OptionsPattern[]] := Block[{FeynCalc`FCLoopSelectTopology`Private`res, 
      FeynCalc`FCLoopSelectTopology`Private`glis, 
      FeynCalc`FCLoopSelectTopology`Private`gliTopos, 
      FeynCalc`FCLoopSelectTopology`Private`null, 
      FeynCalc`FCLoopSelectTopology`Private`optOneToOne, 
      FeynCalc`FCLoopSelectTopology`Private`aux}, 
     If[FeynCalc`FCLoopSelectTopology`Private`glisRaw === {}, Return[{}]]; 
      FeynCalc`FCLoopSelectTopology`Private`optOneToOne = 
       OptionValue["OneToOneCorrespondence"]; 
      If[TrueQ[ !MatchQ[FeynCalc`FCLoopSelectTopology`Private`glisRaw, 
          {__GLI}]], If[TrueQ[MatchQ[
          FeynCalc`FCLoopSelectTopology`Private`glisRaw, 
          {(_GLI | _GLI^_ | 0 | HoldPattern[Times][(_GLI | _GLI^_)..])..}]], 
        FeynCalc`FCLoopSelectTopology`Private`glis = 
          (Cases2[#1 + FeynCalc`FCLoopSelectTopology`Private`null, 
             GLI] & ) /@ FeynCalc`FCLoopSelectTopology`Private`glisRaw; 
         FeynCalc`FCLoopSelectTopology`Private`gliTopos = 
          FeynCalc`FCLoopSelectTopology`Private`glis /. 
           GLI[FeynCalc`FCLoopSelectTopology`Private`id_, __] :> 
            FeynCalc`FCLoopSelectTopology`Private`id, 
        FeynCalc`FCLoopSelectTopology`Private`glis = 
          Cases2[FeynCalc`FCLoopSelectTopology`Private`glisRaw + 
            FeynCalc`FCLoopSelectTopology`Private`null, GLI]; 
         FeynCalc`FCLoopSelectTopology`Private`gliTopos = 
          List /@ FeynCalc`FCLoopSelectTopology`Private`glis[[All,1]]], 
       FeynCalc`FCLoopSelectTopology`Private`glis = 
         FeynCalc`FCLoopSelectTopology`Private`glisRaw; 
        FeynCalc`FCLoopSelectTopology`Private`gliTopos = 
         List /@ First /@ FeynCalc`FCLoopSelectTopology`Private`glis; ]; 
      If[ !FeynCalc`FCLoopSelectTopology`Private`optOneToOne, 
       FeynCalc`FCLoopSelectTopology`Private`gliTopos = 
        Union[Flatten[FeynCalc`FCLoopSelectTopology`Private`gliTopos]]]; 
      If[ !FeynCalc`FCLoopSelectTopology`Private`optOneToOne, 
       FeynCalc`FCLoopSelectTopology`Private`res = 
        Sort[Select[FeynCalc`FCLoopSelectTopology`Private`topos, 
          MemberQ[FeynCalc`FCLoopSelectTopology`Private`gliTopos, 
            First[#1]] & ]], FeynCalc`FCLoopSelectTopology`Private`aux = 
         (#1[[1]] -> #1 & ) /@ FeynCalc`FCLoopSelectTopology`Private`topos; 
        FeynCalc`FCLoopSelectTopology`Private`res = 
         FeynCalc`FCLoopSelectTopology`Private`gliTopos /. 
          Dispatch[FeynCalc`FCLoopSelectTopology`Private`aux]]; 
      If[FeynCalc`FCLoopSelectTopology`Private`res === {}, 
       Message[FCLoopSelectTopology::failmsg, 
         "There are no topologies that appear in the given list of GLIs"]; 
        Abort[]]; If[OptionValue[Check], 
       If[ !FCLoopValidTopologyQ[DeleteDuplicates[Flatten[
             FeynCalc`FCLoopSelectTopology`Private`res]]], 
         Message[FCLoopSelectTopology::failmsg, 
           "The supplied list of topologie is incorrect."]; Abort[]]; ]; 
      If[OptionValue[FCE], FeynCalc`FCLoopSelectTopology`Private`res = 
        FCE[FeynCalc`FCLoopSelectTopology`Private`res]]; 
      FeynCalc`FCLoopSelectTopology`Private`res]
 
Options[FCLoopSelectTopology] = {FeynCalcExternal -> False, Check -> True, 
     "OneToOneCorrespondence" -> False}
 
FCLoopSelectTopology /: FCLoopSelectTopology::failmsg = "Error! \
FCLoopSelectTopology has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCLoopSelectTopology /: FCLoopSelectTopology::usage = "FCLoopSelectTopology[i\
nt, topos] selects the topology that matches the GLI int\nfrom a list of \
topologies topos.\n\nThe first argument can be also a list, in which case the \
function will return\na list of matching topologies."
 
FCLoopValidTopologyQ[FeynCalc`FCLoopValidTopologyQ`Private`topos_List] := 
    Block[{FeynCalc`FCLoopValidTopologyQ`Private`ids}, 
     If[ !MatchQ[FeynCalc`FCLoopValidTopologyQ`Private`topos, 
         {__FCTopology}], Message[FCLoopValidTopologyQ::inv, 
         "The input is not a valid list of FCTopology objects."]; 
        Return[False]]; If[ !MatchQ[FCLoopValidTopologyQ /@ 
          FeynCalc`FCLoopValidTopologyQ`Private`topos, {True..}], 
       Message[FCLoopValidTopologyQ::inv, 
         "Some of the topologies in the given list are invalid."]; 
        Return[False]]; If[ !DuplicateFreeQ[First /@ 
          FeynCalc`FCLoopValidTopologyQ`Private`topos], 
       Message[FCLoopValidTopologyQ::inv, 
         "Detected duplicate topologies in the given list."]; Return[False]]; 
      True]
 
FCLoopValidTopologyQ[
     FeynCalc`FCLoopValidTopologyQ`Private`topoRaw_FCTopology] := 
    MemSet[FCLoopValidTopologyQ[
      FeynCalc`FCLoopValidTopologyQ`Private`topoRaw], 
     Block[{FeynCalc`FCLoopValidTopologyQ`Private`topo, 
       FeynCalc`FCLoopValidTopologyQ`Private`allmoms}, 
      FeynCalc`FCLoopValidTopologyQ`Private`topo = 
        FCI[FeynCalc`FCLoopValidTopologyQ`Private`topoRaw]; 
       If[ !MatchQ[FeynCalc`FCLoopValidTopologyQ`Private`topo /. 
           {(FeynCalc`FCLoopValidTopologyQ`Private`c_.)*(
                FeynCalc`FCLoopValidTopologyQ`Private`x_FeynAmpDenominator) \
/; FreeQ[FeynCalc`FCLoopValidTopologyQ`Private`c, FeynAmpDenominator] :> 
             FeynCalc`FCLoopValidTopologyQ`Private`x}, FCTopology[_, 
           {__FeynAmpDenominator}, {__Symbol}, _List, _List, _List, ___]], 
        Message[FCLoopValidTopologyQ::inv, StringJoin["The topology ", 
           ToString[FeynCalc`FCLoopValidTopologyQ`Private`topo[[1]], 
            InputForm], " does not have the correct form."]]; Return[False]]; 
       FeynCalc`FCLoopValidTopologyQ`Private`allmoms = 
        DeleteDuplicates[Sort[Cases[MomentumExpand[
            FeynCalc`FCLoopValidTopologyQ`Private`topo[[2]]], 
           (Momentum | CartesianMomentum | TemporalMomentum)[
             FeynCalc`FCLoopValidTopologyQ`Private`x_, ___] :> 
            FeynCalc`FCLoopValidTopologyQ`Private`x, Infinity]]]; 
       If[ !SubsetQ[Join[FeynCalc`FCLoopValidTopologyQ`Private`topo[[3]], 
           FeynCalc`FCLoopValidTopologyQ`Private`topo[[4]]], 
          FeynCalc`FCLoopValidTopologyQ`Private`allmoms], 
        Message[FCLoopValidTopologyQ::inv, StringJoin["The topology ", 
           ToString[FeynCalc`FCLoopValidTopologyQ`Private`topo[[1]], 
            InputForm], " contains undeclared momenta."]]; Return[False]]; 
       True]]
 
FCLoopValidTopologyQ /: FCLoopValidTopologyQ::inv = 
     "Topology validation failed: `1`"
 
FCLoopValidTopologyQ /: FCLoopValidTopologyQ::usage = "FCLoopValidTopologyQ[t\
opo] returns True if topo is a valid FCTopology object\nor a list thereof."
 
FeynCalc`FCFeynmanPrepare`Private`fcszVerbose = 0
 
FeynCalc`FCFeynmanPrepare`Private`fcszVerbose /: 
    FeynCalc`FCFeynmanPrepare`Private`fcszVerbose::usage = ""
 
LoopMomenta /: LoopMomenta::usage = "LoopMomenta is an option of FCFAConvert. \
It specifies how the loop momenta in\nthe diagram should be named. The number \
and order of momenta in the list of\nmomenta should exactly match those in \
InsertFields of FeynArts."
 
FCLoopFromGLI[FeynCalc`FCLoopFromGLI`Private`expr_, 
     FeynCalc`FCLoopFromGLI`Private`topo_FCTopology, 
     FeynCalc`FCLoopFromGLI`Private`opts:OptionsPattern[]] := 
    FCLoopFromGLI[FeynCalc`FCLoopFromGLI`Private`expr, 
     {FeynCalc`FCLoopFromGLI`Private`topo}, 
     FeynCalc`FCLoopFromGLI`Private`opts]
 
FCLoopFromGLI[FeynCalc`FCLoopFromGLI`Private`expr_, 
     FeynCalc`FCLoopFromGLI`Private`toposRaw_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopFromGLI`Private`res, 
      FeynCalc`FCLoopFromGLI`Private`topos, 
      FeynCalc`FCLoopFromGLI`Private`listGLI, 
      FeynCalc`FCLoopFromGLI`Private`rule, 
      FeynCalc`FCLoopFromGLI`Private`optLoopMomenta, 
      FeynCalc`FCLoopFromGLI`Private`gliHead, 
      FeynCalc`FCLoopFromGLI`Private`time, 
      FeynCalc`FCLoopFromGLI`Private`time1, 
      FeynCalc`FCLoopFromGLI`Private`pattern, 
      FeynCalc`FCLoopFromGLI`Private`fromGliRule, 
      FeynCalc`FCLoopFromGLI`Private`listGLIEval, 
      FeynCalc`FCLoopFromGLI`Private`ruleFinal, 
      FeynCalc`FCLoopFromGLI`Private`relevantTopos, 
      FeynCalc`FCLoopFromGLI`Private`optList, 
      FeynCalc`FCLoopFromGLI`Private`optFCParallelize, 
      FeynCalc`FCLoopFromGLI`Private`fgliVerbose}, 
     FeynCalc`FCLoopFromGLI`Private`optFeynAmpDenominatorExplicit = 
       OptionValue[FeynAmpDenominatorExplicit]; 
      FeynCalc`FCLoopFromGLI`Private`optExpandScalarProduct = 
       OptionValue[ExpandScalarProduct]; 
      FeynCalc`FCLoopFromGLI`Private`optLoopMomenta = 
       OptionValue[LoopMomenta]; FeynCalc`FCLoopFromGLI`Private`optList = 
       OptionValue[List]; FeynCalc`FCLoopFromGLI`Private`optFCParallelize = 
       OptionValue[FCParallelize]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopFromGLI`Private`fgliVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopFromGLI`Private`fgliVerbose = OptionValue[
           FCVerbose]]; ]; FCPrint[1, "FCLoopFromGLI: Entering.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Entering with: ", 
       FeynCalc`FCLoopFromGLI`Private`expr, FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Topologies: ", 
       FeynCalc`FCLoopFromGLI`Private`toposRaw, FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[Head[FeynCalc`FCLoopFromGLI`Private`optLoopMomenta] =!= Function, 
       Message[FCLoopFromGLI::failmsg, 
         "Incorrect value of the LoopMomenta option."]; Abort[]]; 
      FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFromGLI: Applying FCI.", FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[ !OptionValue[FCI], FeynCalc`FCLoopFromGLI`Private`topos = 
        FCI[FeynCalc`FCLoopFromGLI`Private`toposRaw], 
       FeynCalc`FCLoopFromGLI`Private`topos = 
        FeynCalc`FCLoopFromGLI`Private`toposRaw]; 
      FCPrint[1, "FCLoopFromGLI: Done applying FCI, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFromGLI: Applying FCLoopValidTopologyQ.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[ !FCLoopValidTopologyQ[FeynCalc`FCLoopFromGLI`Private`topos], 
       Message[FCLoopFromGLI::failmsg, 
         "The list of the supplied topologies is incorrect."]; Abort[]]; 
      FCPrint[1, 
       "FCLoopFromGLI: Done applying FCLoopValidTopologyQ, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[FreeQ[FeynCalc`FCLoopFromGLI`Private`expr, GLI], 
       FCPrint[1, "FCLoopFromGLI: Nothing to do.", FCDoControl -> 
          FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
        Return[FeynCalc`FCLoopFromGLI`Private`expr]]; 
      Which[MatchQ[FeynCalc`FCLoopFromGLI`Private`expr, {__GLI}], 
       FeynCalc`FCLoopFromGLI`Private`listGLI = 
         FeynCalc`FCLoopFromGLI`Private`expr; 
        FeynCalc`FCLoopFromGLI`Private`res = 
         FeynCalc`FCLoopFromGLI`Private`gliHead /@ 
          FeynCalc`FCLoopFromGLI`Private`listGLI, 
       MatchQ[FeynCalc`FCLoopFromGLI`Private`expr, _GLI | _GLI^_ | 
         HoldPattern[Times][(_GLI | _GLI^_)..]], 
       FeynCalc`FCLoopFromGLI`Private`listGLI = 
         {FeynCalc`FCLoopFromGLI`Private`expr}; 
        FeynCalc`FCLoopFromGLI`Private`res = 
         FeynCalc`FCLoopFromGLI`Private`gliHead[
          FeynCalc`FCLoopFromGLI`Private`expr], 
       MatchQ[FeynCalc`FCLoopFromGLI`Private`expr, 
        {(_GLI | _GLI^_ | HoldPattern[Times][(_GLI | _GLI^_)..])..}], 
       FeynCalc`FCLoopFromGLI`Private`listGLI = 
         FeynCalc`FCLoopFromGLI`Private`expr; 
        FeynCalc`FCLoopFromGLI`Private`res = 
         FeynCalc`FCLoopFromGLI`Private`gliHead /@ 
          FeynCalc`FCLoopFromGLI`Private`listGLI, True, 
       FeynCalc`FCLoopFromGLI`Private`listGLI = 
         Cases2[FeynCalc`FCLoopFromGLI`Private`expr, GLI]; 
        FeynCalc`FCLoopFromGLI`Private`res = 
         FeynCalc`FCLoopFromGLI`Private`expr /. 
          FeynCalc`FCLoopFromGLI`Private`a_GLI :> 
           FeynCalc`FCLoopFromGLI`Private`gliHead[
            FeynCalc`FCLoopFromGLI`Private`a]]; 
      FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFromGLI: Selecting relevant topologies.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`relevantTopos = 
       Union[FCLoopSelectTopology[FeynCalc`FCLoopFromGLI`Private`listGLI, 
         FeynCalc`FCLoopFromGLI`Private`topos]]; 
      FCPrint[1, "FCLoopFromGLI: Done selecting relevant topologies, timing: \
", N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Relevant topologies: ", 
       FeynCalc`FCLoopFromGLI`Private`relevantTopos, 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFromGLI: Creating conversion rules.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[$ParallelizeFeynCalc && 
        FeynCalc`FCLoopFromGLI`Private`optFCParallelize, 
       FCPrint[1, "FCLoopFromGLI: Running in parallel.", 
         FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
        With[{FeynCalc`FCLoopFromGLI`Private`xxx = 
           FeynCalc`FCLoopFromGLI`Private`powFu}, ParallelEvaluate[
          FCParallelContext`FCLoopFromGLI`powFu = 
            FeynCalc`FCLoopFromGLI`Private`xxx; , DistributedContexts -> 
           None]]; FeynCalc`FCLoopFromGLI`Private`fromGliRule = 
         ParallelMap[FeynCalc`FCLoopFromGLI`Private`rule[GLI[#1[[1]], 
              Table[FeynCalc`FCLoopFromGLI`Private`pattern[ToExpression[
                 StringJoin["n", ToString[
                   FeynCalc`FCLoopFromGLI`Private`i]]], _], {
                FeynCalc`FCLoopFromGLI`Private`i, 1, Length[#1[[2]]]}]], 
             FCParallelContext`FCLoopFromGLI`powFu[#1[[2]]]] /. 
            FeynCalc`FCLoopFromGLI`Private`pattern -> Pattern & , 
          FeynCalc`FCLoopFromGLI`Private`relevantTopos, 
          DistributedContexts -> None, Method -> "CoarsestGrained"]; 
        FeynCalc`FCLoopFromGLI`Private`fromGliRule = 
         FeynCalc`FCLoopFromGLI`Private`fromGliRule /. 
          FeynCalc`FCLoopFromGLI`Private`rule -> RuleDelayed, 
       FeynCalc`FCLoopFromGLI`Private`fromGliRule = 
         (FeynCalc`FCLoopFromGLI`Private`rule[GLI[#1[[1]], Table[
                FeynCalc`FCLoopFromGLI`Private`pattern[ToExpression[
                  StringJoin["n", ToString[
                    FeynCalc`FCLoopFromGLI`Private`i]]], _], 
                {FeynCalc`FCLoopFromGLI`Private`i, 1, Length[#1[[2]]]}]], 
              FeynCalc`FCLoopFromGLI`Private`powFu[#1[[2]]]] & ) /@ 
            FeynCalc`FCLoopFromGLI`Private`relevantTopos /. 
           FeynCalc`FCLoopFromGLI`Private`pattern -> Pattern /. 
          FeynCalc`FCLoopFromGLI`Private`rule -> RuleDelayed; ]; 
      FCPrint[1, "FCLoopFromGLI: Done creating conversion rules, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Conversion rules: ", 
       FeynCalc`FCLoopFromGLI`Private`fromGliRule, FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[1, "FCLoopFromGLI: Applying conversion rules.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[ !MatchQ[FeynCalc`FCLoopFromGLI`Private`listGLI, {__GLI}], 
       If[$ParallelizeFeynCalc && 
         Length[FeynCalc`FCLoopFromGLI`Private`topos] =!= 1 && 
         FeynCalc`FCLoopFromGLI`Private`optFCParallelize, 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
         ParallelMap[FeynCalc`FCLoopFromGLI`Private`gliToFAD[#1, 
             FeynCalc`FCLoopFromGLI`Private`fromGliRule, 
             FeynCalc`FCLoopFromGLI`Private`relevantTopos, 
             FeynCalc`FCLoopFromGLI`Private`optLoopMomenta] & , 
           FeynCalc`FCLoopFromGLI`Private`listGLI, DistributedContexts -> 
            None] /. FeynCalc`FCLoopFromGLI`Private`powerHold -> 
           FeynCalc`FCLoopFromGLI`Private`power, 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
         (FeynCalc`FCLoopFromGLI`Private`gliToFAD[#1, 
             FeynCalc`FCLoopFromGLI`Private`fromGliRule, 
             FeynCalc`FCLoopFromGLI`Private`relevantTopos, 
             FeynCalc`FCLoopFromGLI`Private`optLoopMomenta] & ) /@ 
           FeynCalc`FCLoopFromGLI`Private`listGLI /. 
          FeynCalc`FCLoopFromGLI`Private`powerHold -> 
           FeynCalc`FCLoopFromGLI`Private`power], 
       If[$ParallelizeFeynCalc && 
         Length[FeynCalc`FCLoopFromGLI`Private`topos] =!= 1 && 
         FeynCalc`FCLoopFromGLI`Private`optFCParallelize, 
        FeynCalc`FCLoopFromGLI`Private`time1 = AbsoluteTime[]; 
         FCPrint[1, "FCLoopFromGLI: Distributing conversion rules among the \
parallel kernels", FCDoControl -> 
           FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
         With[{FeynCalc`FCLoopFromGLI`Private`xxx = Compress[
             FeynCalc`FCLoopFromGLI`Private`fromGliRule]}, 
          ParallelEvaluate[FCContextFCLoopFromGLI`fromGliRule = 
             FeynCalc`FCLoopFromGLI`Private`xxx; , DistributedContexts -> 
            None]]; ParallelEvaluate[FCContextFCLoopFromGLI`fromGliRule = 
            Dispatch[Uncompress[FCContextFCLoopFromGLI`fromGliRule]]; , 
          DistributedContexts -> None]; FCPrint[1, "FCLoopFromGLI: Done \
distributing conversion rules among the parallel kernels, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time1, 4], 
          FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
         FeynCalc`FCLoopFromGLI`Private`time1 = AbsoluteTime[]; 
         FCPrint[1, 
          "FCLoopFromGLI: Applying conversion rules on parallel kernels", 
          FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
         FeynCalc`FCLoopFromGLI`Private`listGLIEval = ParallelMap[
           #1 /. FCContextFCLoopFromGLI`fromGliRule /. 
              FeynCalc`FCLoopFromGLI`Private`powerHold -> 
               FeynCalc`FCLoopFromGLI`Private`power /. 
             FeynCalc`FCLoopFromGLI`Private`list[] -> 0 & , 
           Partition[FeynCalc`FCLoopFromGLI`Private`listGLI, 
            UpTo[Ceiling[Length[FeynCalc`FCLoopFromGLI`Private`listGLI]/
               Length[Kernels[]]]]], DistributedContexts -> None, 
           Method -> "CoarsestGrained"]; 
         FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
          Flatten[FeynCalc`FCLoopFromGLI`Private`listGLIEval]; 
         FCPrint[1, "FCLoopFromGLI: Done applying conversion rules on \
parallel, timing: ", N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time1, 
           4], FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; , 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
          FeynCalc`FCLoopFromGLI`Private`listGLI /. Dispatch[
              FeynCalc`FCLoopFromGLI`Private`fromGliRule] /. 
            FeynCalc`FCLoopFromGLI`Private`powerHold -> 
             FeynCalc`FCLoopFromGLI`Private`power /. 
           FeynCalc`FCLoopFromGLI`Private`list[] -> 0; ]]; 
      FCPrint[1, "FCLoopFromGLI: Done applying conversion rules, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Converted GLIs: ", 
       FeynCalc`FCLoopFromGLI`Private`listGLIEval, FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      Switch[FeynCalc`FCLoopFromGLI`Private`optList, True, 
       FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval /. 
         FeynCalc`FCLoopFromGLI`Private`list -> List, False, 
       FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval /. 
         FeynCalc`FCLoopFromGLI`Private`list -> Times, FeynAmpDenominator, 
       FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval /. FeynAmpDenominator -> 
           Sequence /. FeynCalc`FCLoopFromGLI`Private`list -> 
          FeynAmpDenominator, _, Message[FCLoopFromGLI::failmsg, 
         "Unknown value of the option List."]; Abort[]]; 
      If[ !FreeQ2[FeynCalc`FCLoopFromGLI`Private`listGLIEval, 
         {GLI, FeynCalc`FCLoopFromGLI`Private`power, 
          FeynCalc`FCLoopFromGLI`Private`powFu, 
          FeynCalc`FCLoopFromGLI`Private`gliToFAD, 
          FeynCalc`FCLoopFromGLI`Private`list}], 
       Message[FCLoopFromGLI::failmsg, 
         "Failed to eliminate some of the GLIs."]; Abort[]]; 
      If[OptionValue[FeynAmpDenominatorCombine], 
       FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopFromGLI: Applying FeynAmpDenominatorCombine.", 
         FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
        FeynCalc`FCLoopFromGLI`Private`listGLIEval = 
         (FeynAmpDenominatorCombine[#1, FCI -> True] & ) /@ 
          FeynCalc`FCLoopFromGLI`Private`listGLIEval; 
        FCPrint[1, 
         "FCLoopFromGLI: Done applying FeynAmpDenominatorCombine, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; ]; 
      FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFromGLI: Creating the final replacement rule.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`ruleFinal = 
       Thread[FeynCalc`FCLoopFromGLI`Private`gliHead /@ 
          FeynCalc`FCLoopFromGLI`Private`listGLI -> 
         FeynCalc`FCLoopFromGLI`Private`listGLIEval]; 
      FCPrint[1, 
       "FCLoopFromGLI: Done creating the final replacement rule, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Final set of the replacement rules: ", 
       FeynCalc`FCLoopFromGLI`Private`ruleFinal, FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFromGLI: Applying the final replacement rule.", 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`res = 
       FeynCalc`FCLoopFromGLI`Private`res /. 
        Dispatch[FeynCalc`FCLoopFromGLI`Private`ruleFinal]; 
      FCPrint[1, 
       "FCLoopFromGLI: Done applying the final replacement rule, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFromGLI`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FCPrint[3, "FCLoopFromGLI: Raw result: ", 
       FeynCalc`FCLoopFromGLI`Private`res, FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      If[ !FreeQ[FeynCalc`FCLoopFromGLI`Private`res, GLI], 
       Message[FCLoopFromGLI::failmsg, 
         "The input expression still contains GLIs."]; Abort[]]; 
      If[OptionValue[FCE], FeynCalc`FCLoopFromGLI`Private`res = 
        FCE[FeynCalc`FCLoopFromGLI`Private`res]]; 
      FCPrint[1, "FCLoopFromGLI: Leaving.", FCDoControl -> 
        FeynCalc`FCLoopFromGLI`Private`fgliVerbose]; 
      FeynCalc`FCLoopFromGLI`Private`res]
 
Options[FCLoopFromGLI] = {ExpandScalarProduct -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCParallelize -> False, FCVerbose -> False, FeynAmpDenominatorCombine -> 
      False, FeynAmpDenominatorExplicit -> True, List -> False, 
     LoopMomenta -> Function[{FeynCalc`FCLoopFromGLI`Private`x, 
        FeynCalc`FCLoopFromGLI`Private`y}, FCGV[StringJoin["lmom", 
         ToString[FeynCalc`FCLoopFromGLI`Private`x], 
         ToString[FeynCalc`FCLoopFromGLI`Private`y]]]]}
 
FCLoopFromGLI /: FCLoopFromGLI::failmsg = "Error! FCLoopFromGLI has \
encountered a fatal problem and must abort the computation. \n\nThe problem \
reads: `1`"
 
FCLoopFromGLI /: FCLoopFromGLI::usage = "FCLoopFromGLI[exp, topologies] \
replaces GLIs in exp with the corresponding\nloop integrals in the \
FeynAmpDenominator notation according to the information\nprovided in \
topologies."
 
FeynCalc`FCLoopFromGLI`Private`optFeynAmpDenominatorExplicit /: 
    FeynCalc`FCLoopFromGLI`Private`optFeynAmpDenominatorExplicit::usage = ""
 
FeynAmpDenominatorExplicit[
     FeynCalc`FeynAmpDenominatorExplicit`Private`expr_List, 
     FeynCalc`FeynAmpDenominatorExplicit`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`res, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`time}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`time = AbsoluteTime[]; 
      If[$ParallelizeFeynCalc && OptionValue[FCParallelize], 
       FCPrint[1, "FeynAmpDenominatorExplicit: Applying \
FeynAmpDenominatorExplicit in parallel.", FCDoControl -> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose]; 
        FeynCalc`FeynAmpDenominatorExplicit`Private`res = 
         ParallelMap[FeynAmpDenominatorExplicit[#1, FilterRules[
             {FeynCalc`FeynAmpDenominatorExplicit`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & , 
          FeynCalc`FeynAmpDenominatorExplicit`Private`expr, 
          DistributedContexts -> None, Method -> "ItemsPerEvaluation" -> 
            Ceiling[N[Length[
                 FeynCalc`FeynAmpDenominatorExplicit`Private`expr]/
                $KernelCount]/10]]; FCPrint[1, "FeynAmpDenominatorExplicit: \
Done applying FeynAmpDenominatorExplicit in parallel, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FeynAmpDenominatorExplicit`Private`time, 
          4], FCDoControl -> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose], 
       FCPrint[1, 
         "FeynAmpDenominatorExplicit: Applying FeynAmpDenominatorExplicit.", 
         FCDoControl -> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose]; 
        FeynCalc`FeynAmpDenominatorExplicit`Private`res = 
         (FeynAmpDenominatorExplicit[#1, FilterRules[
             {FeynCalc`FeynAmpDenominatorExplicit`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & ) /@ 
          FeynCalc`FeynAmpDenominatorExplicit`Private`expr; 
        FCPrint[1, "FeynAmpDenominatorExplicit: Done applying \
FeynAmpDenominatorExplicit, timing: ", N[AbsoluteTime[] - 
           FeynCalc`FeynAmpDenominatorExplicit`Private`time, 4], 
         FCDoControl -> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`optVerbose]]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`res]
 
FeynAmpDenominatorExplicit[
     FeynCalc`FeynAmpDenominatorExplicit`Private`expr_ /; 
      Head[FeynCalc`FeynAmpDenominatorExplicit`Private`expr] =!= List, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FeynAmpDenominatorExplicit`Private`ex, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`dim, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`res, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`head1, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`head2, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`mandel, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`ruleNormal, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`id, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`ruleMandelstam, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`fad, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`esp, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`mc, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`fadList, 
      FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval}, 
     FeynCalc`FeynAmpDenominatorExplicit`Private`id[
        FeynCalc`FeynAmpDenominatorExplicit`Private`x_, ___] := 
       FeynCalc`FeynAmpDenominatorExplicit`Private`x; 
      If[OptionValue[ExpandScalarProduct], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`esp = ExpandScalarProduct, 
       FeynCalc`FeynAmpDenominatorExplicit`Private`esp = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`id]; 
      If[OptionValue[MomentumCombine], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`mc = MomentumCombine, 
       FeynCalc`FeynAmpDenominatorExplicit`Private`mc = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`id]; 
      If[OptionValue[FCI], FeynCalc`FeynAmpDenominatorExplicit`Private`ex = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`expr, 
       FeynCalc`FeynAmpDenominatorExplicit`Private`ex = 
        FCI[FeynCalc`FeynAmpDenominatorExplicit`Private`expr]]; 
      If[FreeQ[FeynCalc`FeynAmpDenominatorExplicit`Private`ex, 
        FeynAmpDenominator], Return[
        FeynCalc`FeynAmpDenominatorExplicit`Private`ex]]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`fadList = 
       Cases2[FeynCalc`FeynAmpDenominatorExplicit`Private`ex, 
        FeynAmpDenominator]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadList /. 
        FeynAmpDenominator -> 
         FeynCalc`FeynAmpDenominatorExplicit`Private`fad; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`dim = 
       OptionValue[Dimension]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`mandel = 
       OptionValue[Mandelstam]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`ruleNormal = 
       {PropagatorDenominator[FeynCalc`FeynAmpDenominatorExplicit`Private`a_, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`b_] :> 
         1/Expand[FeynCalc`FeynAmpDenominatorExplicit`Private`esp[
             FeynCalc`FeynAmpDenominatorExplicit`Private`mc[
              Pair[FeynCalc`FeynAmpDenominatorExplicit`Private`a, 
               FeynCalc`FeynAmpDenominatorExplicit`Private`a]], 
             FCI -> True] - FeynCalc`FeynAmpDenominatorExplicit`Private`b^2], 
        GenericPropagatorDenominator[
          FeynCalc`FeynAmpDenominatorExplicit`Private`pr_, 
          {FeynCalc`FeynAmpDenominatorExplicit`Private`n_, _}] :> 
         (1/Expand[FeynCalc`FeynAmpDenominatorExplicit`Private`esp[
             FeynCalc`FeynAmpDenominatorExplicit`Private`mc[
              FeynCalc`FeynAmpDenominatorExplicit`Private`pr], FCI -> True]])^
          FeynCalc`FeynAmpDenominatorExplicit`Private`n, 
        CartesianPropagatorDenominator[
          FeynCalc`FeynAmpDenominatorExplicit`Private`ex1_, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`ex2_, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`m2_, 
          {FeynCalc`FeynAmpDenominatorExplicit`Private`n_, _}] :> 
         (1/Expand[FeynCalc`FeynAmpDenominatorExplicit`Private`esp[
             FeynCalc`FeynAmpDenominatorExplicit`Private`mc[CartesianPair[
                FeynCalc`FeynAmpDenominatorExplicit`Private`ex1, 
                FeynCalc`FeynAmpDenominatorExplicit`Private`ex1] + 
               FeynCalc`FeynAmpDenominatorExplicit`Private`ex2 + 
               FeynCalc`FeynAmpDenominatorExplicit`Private`m2], 
             FCI -> True]])^FeynCalc`FeynAmpDenominatorExplicit`Private`n, 
        StandardPropagatorDenominator[
          FeynCalc`FeynAmpDenominatorExplicit`Private`ex1_, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`ex2_, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`m2_, 
          {FeynCalc`FeynAmpDenominatorExplicit`Private`n_, _}] :> 
         (1/Expand[FeynCalc`FeynAmpDenominatorExplicit`Private`esp[
             FeynCalc`FeynAmpDenominatorExplicit`Private`mc[
              Pair[FeynCalc`FeynAmpDenominatorExplicit`Private`ex1, 
                FeynCalc`FeynAmpDenominatorExplicit`Private`ex1] + 
               FeynCalc`FeynAmpDenominatorExplicit`Private`ex2 + 
               FeynCalc`FeynAmpDenominatorExplicit`Private`m2], 
             FCI -> True]])^FeynCalc`FeynAmpDenominatorExplicit`Private`n}; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`ruleMandelstam = 
       {PropagatorDenominator[FeynCalc`FeynAmpDenominatorExplicit`Private`a_, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`b_] :> 
         1/TrickMandelstam[FeynCalc`FeynAmpDenominatorExplicit`Private`esp[
             FeynCalc`FeynAmpDenominatorExplicit`Private`mc[
              Pair[FeynCalc`FeynAmpDenominatorExplicit`Private`a, 
               FeynCalc`FeynAmpDenominatorExplicit`Private`a]], 
             FCI -> True] - FeynCalc`FeynAmpDenominatorExplicit`Private`b^2, 
           FeynCalc`FeynAmpDenominatorExplicit`Private`mandel], 
        GenericPropagatorDenominator[
          FeynCalc`FeynAmpDenominatorExplicit`Private`pr_, 
          {FeynCalc`FeynAmpDenominatorExplicit`Private`n_, _}] :> 
         (1/TrickMandelstam[FeynCalc`FeynAmpDenominatorExplicit`Private`esp[
             FeynCalc`FeynAmpDenominatorExplicit`Private`mc[
              FeynCalc`FeynAmpDenominatorExplicit`Private`pr], FCI -> True], 
            FeynCalc`FeynAmpDenominatorExplicit`Private`mandel])^
          FeynCalc`FeynAmpDenominatorExplicit`Private`n}; 
      If[TrueQ[FeynCalc`FeynAmpDenominatorExplicit`Private`mandel === {}], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval //. 
         FeynCalc`FeynAmpDenominatorExplicit`Private`ruleNormal, 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval //. 
         FeynCalc`FeynAmpDenominatorExplicit`Private`ruleMandelstam]; 
      If[OptionValue[SmallVariable], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval /. 
         FeynCalc`FeynAmpDenominatorExplicit`Private`fad[
           FeynCalc`FeynAmpDenominatorExplicit`Private`c___] :> 
          (FeynCalc`FeynAmpDenominatorExplicit`Private`fad[
            FeynCalc`FeynAmpDenominatorExplicit`Private`c] /. 
           SmallVariable[_] :> 0)]; 
      If[FeynCalc`FeynAmpDenominatorExplicit`Private`dim === False, 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval /. 
         FeynCalc`FeynAmpDenominatorExplicit`Private`fad[
           FeynCalc`FeynAmpDenominatorExplicit`Private`c___] :> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`head1[
           Times[FeynCalc`FeynAmpDenominatorExplicit`Private`c]], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval /. 
         FeynCalc`FeynAmpDenominatorExplicit`Private`fad[
           FeynCalc`FeynAmpDenominatorExplicit`Private`c___] :> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`head1[
           ChangeDimension[Times[
             FeynCalc`FeynAmpDenominatorExplicit`Private`c], 
            FeynCalc`FeynAmpDenominatorExplicit`Private`dim]]]; 
      If[TrueQ[OptionValue[Denominator]], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
         FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval /. 
          FeynCalc`FeynAmpDenominatorExplicit`Private`head1[
             FeynCalc`FeynAmpDenominatorExplicit`Private`x_] /; 
            Numerator[FeynCalc`FeynAmpDenominatorExplicit`Private`x] === 1 :> 
           1/FeynCalc`FeynAmpDenominatorExplicit`Private`head2[
             Denominator[FeynCalc`FeynAmpDenominatorExplicit`Private`x]]; 
        If[ !FreeQ[FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval, 
           FeynCalc`FeynAmpDenominatorExplicit`Private`head1], 
         Message[FeynAmpDenominatorExplicit::failmsg, 
           "The numerator is not unity!"]; Abort[]]; 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
         FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval /. 
          FeynCalc`FeynAmpDenominatorExplicit`Private`head2 -> 
           OptionValue[Head], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval = 
        FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval /. 
         FeynCalc`FeynAmpDenominatorExplicit`Private`head1 -> 
          OptionValue[Head]]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`res = 
       FeynCalc`FeynAmpDenominatorExplicit`Private`ex /. 
        Thread[FeynCalc`FeynAmpDenominatorExplicit`Private`fadList -> 
          FeynCalc`FeynAmpDenominatorExplicit`Private`fadListEval]; 
      If[ !FreeQ2[FeynCalc`FeynAmpDenominatorExplicit`Private`res, 
         {FeynCalc`FeynAmpDenominatorExplicit`Private`fad, 
          FeynAmpDenominator, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`head1, 
          FeynCalc`FeynAmpDenominatorExplicit`Private`head2}], 
       Message[FeynAmpDenominatorExplicit::failmsg, 
         "Something went wrong while writing out the denominators."]; 
        Abort[]]; If[OptionValue[FCE], 
       FeynCalc`FeynAmpDenominatorExplicit`Private`res = 
        FCE[FeynCalc`FeynAmpDenominatorExplicit`Private`res]]; 
      FeynCalc`FeynAmpDenominatorExplicit`Private`res]
 
Options[FeynAmpDenominatorExplicit] = {Denominator -> False, 
     Dimension -> False, ExpandScalarProduct -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCParallelize -> False, FCVerbose -> False, Head -> Identity, 
     Mandelstam -> {}, MomentumCombine -> False, SmallVariable -> False}
 
FeynAmpDenominatorExplicit /: FeynAmpDenominatorExplicit::failmsg = "Error! \
FeynAmpDenominatorExplicit encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FeynAmpDenominatorExplicit /: FeynAmpDenominatorExplicit::usage = "FeynAmpDen\
ominatorExplicit[exp] changes each occurrence of\nPropagatorDenominator[a,b] \
in exp into 1/(SPD[a,a]-b^2) and replaces\nFeynAmpDenominator by Identity."
 
Mandelstam /: Mandelstam::usage = "Mandelstam is an option for DiracTrace, \
TrickMandelstam and other functions. \nA typical setting is Mandelstam -> {s, \
t, u, m1^2+m2^2+m3^2+m4^2}, which\nimplies $s + t + u = \
m_1^2+m_2^2+m_3^2+m_4^2$. If other than four-particle\nprocesses are \
calculated, the setting should be Mandelstam -> {}."
 
TrickMandelstam[FeynCalc`TrickMandelstam`Private`ex_, {}, 
     OptionsPattern[]] := FeynCalc`TrickMandelstam`Private`ex
 
TrickMandelstam[FeynCalc`TrickMandelstam`Private`ex_, 
     FeynCalc`TrickMandelstam`Private`s_, 
     FeynCalc`TrickMandelstam`Private`t_, 
     FeynCalc`TrickMandelstam`Private`u_, 
     FeynCalc`TrickMandelstam`Private`mm_ /; 
       !OptionQ[FeynCalc`TrickMandelstam`Private`mm], 
     FeynCalc`TrickMandelstam`Private`opts:OptionsPattern[]] := 
    TrickMandelstam[FeynCalc`TrickMandelstam`Private`ex, 
     {FeynCalc`TrickMandelstam`Private`s, FeynCalc`TrickMandelstam`Private`t, 
      FeynCalc`TrickMandelstam`Private`u, 
      FeynCalc`TrickMandelstam`Private`mm}, 
     FeynCalc`TrickMandelstam`Private`opts]
 
TrickMandelstam[FeynCalc`TrickMandelstam`Private`expr_List, 
     {FeynCalc`TrickMandelstam`Private`s_, 
       FeynCalc`TrickMandelstam`Private`t_, 
       FeynCalc`TrickMandelstam`Private`u_, 
       FeynCalc`TrickMandelstam`Private`mm_} /; 
       !OptionQ[{FeynCalc`TrickMandelstam`Private`s, 
         FeynCalc`TrickMandelstam`Private`t, 
         FeynCalc`TrickMandelstam`Private`u, 
         FeynCalc`TrickMandelstam`Private`mm}], 
     FeynCalc`TrickMandelstam`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`TrickMandelstam`Private`optVerbose, 
      FeynCalc`TrickMandelstam`Private`res, 
      FeynCalc`TrickMandelstam`Private`time}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`TrickMandelstam`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`TrickMandelstam`Private`optVerbose = 
          OptionValue[FCVerbose]]; ]; FeynCalc`TrickMandelstam`Private`time = 
       AbsoluteTime[]; If[$ParallelizeFeynCalc && OptionValue[FCParallelize], 
       FCPrint[1, "TrickMandelstam: Applying TrickMandelstam in parallel.", 
         FCDoControl -> FeynCalc`TrickMandelstam`Private`optVerbose]; 
        FeynCalc`TrickMandelstam`Private`res = ParallelMap[
          TrickMandelstam[#1, {FeynCalc`TrickMandelstam`Private`s, 
             FeynCalc`TrickMandelstam`Private`t, 
             FeynCalc`TrickMandelstam`Private`u, 
             FeynCalc`TrickMandelstam`Private`mm}, FilterRules[
             {FeynCalc`TrickMandelstam`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & , 
          FeynCalc`TrickMandelstam`Private`expr, DistributedContexts -> None, 
          Method -> "ItemsPerEvaluation" -> Ceiling[
             N[Length[FeynCalc`TrickMandelstam`Private`expr]/$KernelCount]/
              10]]; FCPrint[1, "TrickMandelstam: Done applying \
TrickMandelstam in parallel, timing: ", N[AbsoluteTime[] - 
           FeynCalc`TrickMandelstam`Private`time, 4], FCDoControl -> 
          FeynCalc`TrickMandelstam`Private`optVerbose], 
       FCPrint[1, "TrickMandelstam: Applying TrickMandelstam.", 
         FCDoControl -> FeynCalc`TrickMandelstam`Private`optVerbose]; 
        FeynCalc`TrickMandelstam`Private`res = 
         (TrickMandelstam[#1, {FeynCalc`TrickMandelstam`Private`s, 
             FeynCalc`TrickMandelstam`Private`t, 
             FeynCalc`TrickMandelstam`Private`u, 
             FeynCalc`TrickMandelstam`Private`mm}, FilterRules[
             {FeynCalc`TrickMandelstam`Private`opts}, 
             Except[FCParallelize | FCVerbose]]] & ) /@ 
          FeynCalc`TrickMandelstam`Private`expr; FCPrint[1, 
         "TrickMandelstam: Done applying TrickMandelstam, timing: ", 
         N[AbsoluteTime[] - FeynCalc`TrickMandelstam`Private`time, 4], 
         FCDoControl -> FeynCalc`TrickMandelstam`Private`optVerbose]]; 
      FeynCalc`TrickMandelstam`Private`res]
 
TrickMandelstam[FeynCalc`TrickMandelstam`Private`ex_List, 
     FeynCalc`TrickMandelstam`Private`y__] := 
    (TrickMandelstam[#1, FeynCalc`TrickMandelstam`Private`y] & ) /@ 
     FeynCalc`TrickMandelstam`Private`ex
 
TrickMandelstam[FeynCalc`TrickMandelstam`Private`expr_ /; 
      Head[FeynCalc`TrickMandelstam`Private`expr] =!= List, 
     {FeynCalc`TrickMandelstam`Private`s_, 
       FeynCalc`TrickMandelstam`Private`t_, 
       FeynCalc`TrickMandelstam`Private`u_, 
       FeynCalc`TrickMandelstam`Private`mm_} /; 
       !OptionQ[{FeynCalc`TrickMandelstam`Private`s, 
         FeynCalc`TrickMandelstam`Private`t, 
         FeynCalc`TrickMandelstam`Private`u, 
         FeynCalc`TrickMandelstam`Private`mm}], OptionsPattern[]] := 
    Block[{FeynCalc`TrickMandelstam`Private`tmp, 
      FeynCalc`TrickMandelstam`Private`null}, 
     FeynCalc`TrickMandelstam`Private`tmp = 
       Factor2[FeynCalc`TrickMandelstam`Private`expr]; 
      If[FreeQ[FeynCalc`TrickMandelstam`Private`tmp, Plus], 
       Return[FeynCalc`TrickMandelstam`Private`tmp]]; 
      Switch[Head[FeynCalc`TrickMandelstam`Private`tmp], Times, 
       FeynCalc`TrickMandelstam`Private`tmp = 
        (TrickMandelstam[#1, {FeynCalc`TrickMandelstam`Private`s, 
            FeynCalc`TrickMandelstam`Private`t, 
            FeynCalc`TrickMandelstam`Private`u, 
            FeynCalc`TrickMandelstam`Private`mm}] & ) /@ 
         FeynCalc`TrickMandelstam`Private`tmp, Power, 
       FeynCalc`TrickMandelstam`Private`tmp = 
        TrickMandelstam[FeynCalc`TrickMandelstam`Private`tmp[[1]], 
          {FeynCalc`TrickMandelstam`Private`s, 
           FeynCalc`TrickMandelstam`Private`t, 
           FeynCalc`TrickMandelstam`Private`u, 
           FeynCalc`TrickMandelstam`Private`mm}]^
         FeynCalc`TrickMandelstam`Private`tmp[[2]], Plus, 
       FeynCalc`TrickMandelstam`Private`tmp = 
        FeynCalc`TrickMandelstam`Private`trickPlus[
         FeynCalc`TrickMandelstam`Private`tmp, 
         {FeynCalc`TrickMandelstam`Private`s, 
          FeynCalc`TrickMandelstam`Private`t, 
          FeynCalc`TrickMandelstam`Private`u, 
          FeynCalc`TrickMandelstam`Private`mm}], _, 
       FeynCalc`TrickMandelstam`Private`tmp = 
        FeynCalc`TrickMandelstam`Private`trickPlus[
          FeynCalc`TrickMandelstam`Private`tmp + 
           FeynCalc`TrickMandelstam`Private`null, 
          {FeynCalc`TrickMandelstam`Private`s, 
           FeynCalc`TrickMandelstam`Private`t, 
           FeynCalc`TrickMandelstam`Private`u, 
           FeynCalc`TrickMandelstam`Private`mm}] /. 
         FeynCalc`TrickMandelstam`Private`null -> 0]; 
      If[LeafCount[FeynCalc`TrickMandelstam`Private`tmp] < 2000, 
       FeynCalc`TrickMandelstam`Private`tmp = 
        Cancel[FeynCalc`TrickMandelstam`Private`tmp]]; 
      Factor2[FeynCalc`TrickMandelstam`Private`tmp]]
 
Options[TrickMandelstam] = {FCParallelize -> False, FCVerbose -> False}
 
TrickMandelstam /: TrickMandelstam::usage = "TrickMandelstam[expr, {s, t, u, \
m1^2 + m2^2 + m3^2 + m4^2}] simplifies all\nsums in expr so that one of the \
Mandelstam variables $s$, $t$ or $u$ is\neliminated by the relation $s + t + \
u = m_1^2 + m_2^2 + m_3^2 + m_4^2$ . The\ntrick is that the resulting sum has \
the most short number of terms."
 
FeynCalc`TrickMandelstam`Private`trickPlus[
     FeynCalc`TrickMandelstam`Private`x_Plus, 
     FeynCalc`TrickMandelstam`Private`args_List] := 
    Block[{FeynCalc`TrickMandelstam`Private`tricktemp, 
       FeynCalc`TrickMandelstam`Private`merk, 
       FeynCalc`TrickMandelstam`Private`nx = 
        FeynCalc`TrickMandelstam`Private`x, 
       FeynCalc`TrickMandelstam`Private`plusch, 
       FeynCalc`TrickMandelstam`Private`plusch0}, 
      FeynCalc`TrickMandelstam`Private`plusch0[
         FeynCalc`TrickMandelstam`Private`z__] := 
        Plus[FeynCalc`TrickMandelstam`Private`z] /; 
          !FreeQ[{FeynCalc`TrickMandelstam`Private`z}, 
           FeynCalc`TrickMandelstam`Private`plusch0]; 
       FeynCalc`TrickMandelstam`Private`plusch[
         FeynCalc`TrickMandelstam`Private`z__] := 
        FeynCalc`TrickMandelstam`Private`drickstu[
          Plus[FeynCalc`TrickMandelstam`Private`z], 
          FeynCalc`TrickMandelstam`Private`args] /; 
         Length[{FeynCalc`TrickMandelstam`Private`z}] === 
           Length[Plus @@ FeynCalc`TrickMandelstam`Private`args] - 1 && 
          FreeQ[{FeynCalc`TrickMandelstam`Private`z}, Plus]; 
       FeynCalc`TrickMandelstam`Private`plusch[
         FeynCalc`TrickMandelstam`Private`z__] := 
        Factor2 /@ Collect2[Plus[FeynCalc`TrickMandelstam`Private`z], 
           Take[FeynCalc`TrickMandelstam`Private`args, 3]] /; 
         Length[{FeynCalc`TrickMandelstam`Private`z}] =!= 
          Length[Plus @@ FeynCalc`TrickMandelstam`Private`args] - 1; 
       FeynCalc`TrickMandelstam`Private`tricktemp = 
        FeynCalc`TrickMandelstam`Private`drickstu[
         FeynCalc`TrickMandelstam`Private`nx, 
         FeynCalc`TrickMandelstam`Private`args]; 
       FeynCalc`TrickMandelstam`Private`tricktemp /. 
          Plus -> FeynCalc`TrickMandelstam`Private`plusch0 /. 
         FeynCalc`TrickMandelstam`Private`plusch0 -> 
          FeynCalc`TrickMandelstam`Private`plusch /. 
        FeynCalc`TrickMandelstam`Private`plusch -> Plus] /; 
     Length[FeynCalc`TrickMandelstam`Private`args] === 4 || 
      FeynCalc`TrickMandelstam`Private`args === {}
 
FeynCalc`TrickMandelstam`Private`drickstu[
     FeynCalc`TrickMandelstam`Private`exp_, {}] := 
    FeynCalc`TrickMandelstam`Private`exp
 
FeynCalc`TrickMandelstam`Private`drickstu[
     FeynCalc`TrickMandelstam`Private`exp_, 
     {FeynCalc`TrickMandelstam`Private`s_, 
      FeynCalc`TrickMandelstam`Private`t_, 
      FeynCalc`TrickMandelstam`Private`u_, _}] := 
    FeynCalc`TrickMandelstam`Private`exp /; 
      !FreeQ[{FeynCalc`TrickMandelstam`Private`s, 
        FeynCalc`TrickMandelstam`Private`t, 
        FeynCalc`TrickMandelstam`Private`u}, Plus]
 
FeynCalc`TrickMandelstam`Private`drickstu[
     FeynCalc`TrickMandelstam`Private`x_Plus, 
     {FeynCalc`TrickMandelstam`Private`s_, 
      FeynCalc`TrickMandelstam`Private`t_, 
      FeynCalc`TrickMandelstam`Private`u_, 
      FeynCalc`TrickMandelstam`Private`m_}] := 
    Block[{FeynCalc`TrickMandelstam`Private`result, 
      FeynCalc`TrickMandelstam`Private`tristemp, 
      FeynCalc`TrickMandelstam`Private`eM, 
      FeynCalc`TrickMandelstam`Private`otherVars, 
      FeynCalc`TrickMandelstam`Private`null, 
      FeynCalc`TrickMandelstam`Private`trickargs, 
      FeynCalc`TrickMandelstam`Private`takeShortest, 
      FeynCalc`TrickMandelstam`Private`nsortQ}, 
     FeynCalc`TrickMandelstam`Private`takeShortest[
        FeynCalc`TrickMandelstam`Private`xx_Plus, 
        FeynCalc`TrickMandelstam`Private`es_, 
        FeynCalc`TrickMandelstam`Private`te_, 
        FeynCalc`TrickMandelstam`Private`uu_, 
        FeynCalc`TrickMandelstam`Private`ma_] := 
       First[Sort[{FeynCalc`TrickMandelstam`Private`xx, 
          Expand[FeynCalc`TrickMandelstam`Private`xx /. 
            FeynCalc`TrickMandelstam`Private`te -> 
             FeynCalc`TrickMandelstam`Private`ma - 
              FeynCalc`TrickMandelstam`Private`es - 
              FeynCalc`TrickMandelstam`Private`uu], 
          Expand[FeynCalc`TrickMandelstam`Private`xx /. 
            FeynCalc`TrickMandelstam`Private`uu -> 
             FeynCalc`TrickMandelstam`Private`ma - 
              FeynCalc`TrickMandelstam`Private`te - 
              FeynCalc`TrickMandelstam`Private`es]}, 
         FeynCalc`TrickMandelstam`Private`nsortQ]]; 
      FeynCalc`TrickMandelstam`Private`takeShortest[
        (FeynCalc`TrickMandelstam`Private`a_)*
         (FeynCalc`TrickMandelstam`Private`b_), 
        FeynCalc`TrickMandelstam`Private`c__] := 
       FeynCalc`TrickMandelstam`Private`takeShortest[
         FeynCalc`TrickMandelstam`Private`a, 
         FeynCalc`TrickMandelstam`Private`c]*
        FeynCalc`TrickMandelstam`Private`takeShortest[
         FeynCalc`TrickMandelstam`Private`b, 
         FeynCalc`TrickMandelstam`Private`c]; 
      FeynCalc`TrickMandelstam`Private`takeShortest[
        (FeynCalc`TrickMandelstam`Private`a_)^
         (FeynCalc`TrickMandelstam`Private`n_), 
        FeynCalc`TrickMandelstam`Private`c__] := 
       FeynCalc`TrickMandelstam`Private`takeShortest[
         FeynCalc`TrickMandelstam`Private`a, 
         FeynCalc`TrickMandelstam`Private`c]^
        FeynCalc`TrickMandelstam`Private`n; 
      FeynCalc`TrickMandelstam`Private`takeShortest[
        FeynCalc`TrickMandelstam`Private`xx_, __] := 
       FeynCalc`TrickMandelstam`Private`xx /; 
        Head[FeynCalc`TrickMandelstam`Private`xx] =!= Plus && 
         Head[FeynCalc`TrickMandelstam`Private`xx] =!= Times && 
         Head[FeynCalc`TrickMandelstam`Private`xx] =!= Power; 
      FeynCalc`TrickMandelstam`Private`nsortQ[
        FeynCalc`TrickMandelstam`Private`xx_, 
        FeynCalc`TrickMandelstam`Private`y_] := 
       If[TrueQ[NTerms[FeynCalc`TrickMandelstam`Private`xx] <= 
          NTerms[FeynCalc`TrickMandelstam`Private`y]], True, False]; 
      FeynCalc`TrickMandelstam`Private`tristemp = 
       Factor2[FeynCalc`TrickMandelstam`Private`x /. 
         FeynCalc`TrickMandelstam`Private`s -> 
          FeynCalc`TrickMandelstam`Private`m - 
           FeynCalc`TrickMandelstam`Private`t - 
           FeynCalc`TrickMandelstam`Private`u]; 
      If[Head[FeynCalc`TrickMandelstam`Private`tristemp] =!= Plus, 
       FeynCalc`TrickMandelstam`Private`result = TrickMandelstam[
         FeynCalc`TrickMandelstam`Private`tristemp, 
         {FeynCalc`TrickMandelstam`Private`s, 
          FeynCalc`TrickMandelstam`Private`t, 
          FeynCalc`TrickMandelstam`Private`u, 
          FeynCalc`TrickMandelstam`Private`m}], 
       FeynCalc`TrickMandelstam`Private`otherVars = 
         Complement[Variables[FeynCalc`TrickMandelstam`Private`tristemp], 
          Variables[FeynCalc`TrickMandelstam`Private`s + 
            FeynCalc`TrickMandelstam`Private`t + 
            FeynCalc`TrickMandelstam`Private`u + 
            FeynCalc`TrickMandelstam`Private`m]]; 
        If[FeynCalc`TrickMandelstam`Private`otherVars =!= {}, 
         FeynCalc`TrickMandelstam`Private`result = Factor2 /@ 
            Collect2[FeynCalc`TrickMandelstam`Private`eM*
              FeynCalc`TrickMandelstam`Private`tristemp, 
             Append[FeynCalc`TrickMandelstam`Private`otherVars, 
              FeynCalc`TrickMandelstam`Private`eM]]; 
          FeynCalc`TrickMandelstam`Private`result = 
           (FeynCalc`TrickMandelstam`Private`takeShortest[#1, 
                FeynCalc`TrickMandelstam`Private`s, 
                FeynCalc`TrickMandelstam`Private`t, 
                FeynCalc`TrickMandelstam`Private`u, 
                FeynCalc`TrickMandelstam`Private`m] & ) /@ 
              (FeynCalc`TrickMandelstam`Private`result + 
               FeynCalc`TrickMandelstam`Private`null) /. 
             FeynCalc`TrickMandelstam`Private`null -> 0 /. 
            FeynCalc`TrickMandelstam`Private`eM -> 1; 
          FeynCalc`TrickMandelstam`Private`result = Factor2 /@ 
            FeynCalc`TrickMandelstam`Private`result, 
         FeynCalc`TrickMandelstam`Private`result = 
          FeynCalc`TrickMandelstam`Private`takeShortest[
           FeynCalc`TrickMandelstam`Private`tristemp, 
           FeynCalc`TrickMandelstam`Private`s, 
           FeynCalc`TrickMandelstam`Private`t, 
           FeynCalc`TrickMandelstam`Private`u, 
           FeynCalc`TrickMandelstam`Private`m]]]; 
      FeynCalc`TrickMandelstam`Private`result]
 
