FeynCalc`FCLoopFromGLI`Private`gliToFadRenameMomenta[
     FeynCalc`FCLoopFromGLI`Private`z_GLI, 
     FeynCalc`FCLoopFromGLI`Private`rule_List, 
     FeynCalc`FCLoopFromGLI`Private`topo_FCTopology, 
     FeynCalc`FCLoopFromGLI`Private`lmomFun_, 
     (FeynCalc`FCLoopFromGLI`Private`i_Integer)?Positive] := 
    Block[{FeynCalc`FCLoopFromGLI`Private`lmoms, 
      FeynCalc`FCLoopFromGLI`Private`lmomsRule, 
      FeynCalc`FCLoopFromGLI`Private`res}, 
     FeynCalc`FCLoopFromGLI`Private`lmoms = 
       FeynCalc`FCLoopFromGLI`Private`topo[[3]]; 
      FeynCalc`FCLoopFromGLI`Private`lmomsRule = 
       Thread[FeynCalc`FCLoopFromGLI`Private`lmoms -> 
         Table[FeynCalc`FCLoopFromGLI`Private`lmomFun[
           FeynCalc`FCLoopFromGLI`Private`i, 
           FeynCalc`FCLoopFromGLI`Private`j], 
          {FeynCalc`FCLoopFromGLI`Private`j, 1, 
           Length[FeynCalc`FCLoopFromGLI`Private`lmoms]}]]; 
      FeynCalc`FCLoopFromGLI`Private`res = 
       FeynCalc`FCLoopFromGLI`Private`z /. Dispatch[
          FeynCalc`FCLoopFromGLI`Private`rule] /. 
        FeynCalc`FCLoopFromGLI`Private`lmomsRule; 
      If[ !FreeQ2[FeynCalc`FCLoopFromGLI`Private`res, 
         FeynCalc`FCLoopFromGLI`Private`lmoms], 
       Message[FCLoopFromGLI::failmsg, "Failed to rename loop momenta when \
converting a factorizing integral."]; Abort[]]; 
      FeynCalc`FCLoopFromGLI`Private`res]
 
