      FeynCalc`FCReplaceMomenta`Private`vars = OptionValue[Variables]; 
      FeynCalc`FCReplaceMomenta`Private`selectFree = OptionValue[SelectFree]; 
      FeynCalc`FCReplaceMomenta`Private`maskedObjects = {}; 
      FCPrint[1, "FCReplaceMomenta: Entering.", FCDoControl -> 
        FeynCalc`FCReplaceMomenta`Private`fcrmVerbose]; 
      FCPrint[3, "FCReplaceMomenta: Entering with ", 
       FeynCalc`FCReplaceMomenta`Private`expr, FCDoControl -> 
        FeynCalc`FCReplaceMomenta`Private`fcrmVerbose]; 
      If[ !OptionValue[FCI], FeynCalc`FCReplaceMomenta`Private`ex = 
        FCI[FeynCalc`FCReplaceMomenta`Private`expr], 
       FeynCalc`FCReplaceMomenta`Private`ex = 
        FeynCalc`FCReplaceMomenta`Private`expr]; 
      If[ !FeynCalc`FCReplaceMomenta`Private`MathcQ[
         FeynCalc`FCReplaceMomenta`Private`replacementRules, {___Rule}], 
       Message[FCReplaceMomenta::failmsg, 
         "The momentum replacement rules are incorrect."]; Abort[]]; 
      If[FeynCalc`FCReplaceMomenta`Private`replacementRules === {}, 
       FCPrint[1, "FCReplaceMomenta: Nothing to do.", FCDoControl -> 
          FeynCalc`FCReplaceMomenta`Private`fcrmVerbose]; 
        Return[FeynCalc`FCReplaceMomenta`Private`ex]]; 
