    FeynCalc`FCFeynmanPrepare`Private`dim::usage = ""
 
FCLoopBasisExtract[FeynCalc`FCLoopBasisExtract`Private`exp_, 
     FeynCalc`FCLoopBasisExtract`Private`loopmoms_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopBasisExtract`Private`expr, 
      FeynCalc`FCLoopBasisExtract`Private`coeffs, 
      FeynCalc`FCLoopBasisExtract`Private`lmoms, 
      FeynCalc`FCLoopBasisExtract`Private`allmoms, 
      FeynCalc`FCLoopBasisExtract`Private`extmoms, 
      FeynCalc`FCLoopBasisExtract`Private`basisElements, 
      FeynCalc`FCLoopBasisExtract`Private`availableDims, 
      FeynCalc`FCLoopBasisExtract`Private`dims, 
      FeynCalc`FCLoopBasisExtract`Private`res, 
      FeynCalc`FCLoopBasisExtract`Private`useToSFAD, 
      FeynCalc`FCLoopBasisExtract`Private`integralBasis, 
      FeynCalc`FCLoopBasisExtract`Private`integralBasisT, 
      FeynCalc`FCLoopBasisExtract`Private`coeffsPair, 
      FeynCalc`FCLoopBasisExtract`Private`coeffsCartesianPair, 
      FeynCalc`FCLoopBasisExtract`Private`coeffsTemporalPair, 
      FeynCalc`FCLoopBasisExtract`Private`lorentzianDims, 
      FeynCalc`FCLoopBasisExtract`Private`cartesianDims, 
      FeynCalc`FCLoopBasisExtract`Private`null1, 
      FeynCalc`FCLoopBasisExtract`Private`null2, 
      FeynCalc`FCLoopBasisExtract`Private`aux, 
      FeynCalc`FCLoopBasisExtract`Private`optSortBy, 
      FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions, 
      FeynCalc`FCLoopBasisExtract`Private`etaSigns, 
      FeynCalc`FCLoopBasisExtract`Private`etaSignsLorentzian, 
      FeynCalc`FCLoopBasisExtract`Private`etaSignsCartesian, 
      FeynCalc`FCLoopBasisExtract`Private`etaSignsGeneric, 
      FeynCalc`FCLoopBasisExtract`Private`optVerbose}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopBasisExtract`Private`optVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopBasisExtract`Private`optVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCLoopBasisExtract`Private`dims = OptionValue[SetDimensions]; 
      FeynCalc`FCLoopBasisExtract`Private`optSortBy = OptionValue[SortBy]; 
      FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions = 
       OptionValue[FinalSubstitutions]; 
      If[FeynCalc`FCLoopBasisExtract`Private`dims === {}, 
       Message[FCLoopBasisExtract::failmsg, 
         "The list of dimensions cannot be empty."]; Abort[]]; 
      If[FeynCalc`FCLoopBasisExtract`Private`loopmoms === {}, 
       Message[FCLoopBasisExtract::failmsg, 
         "The list of loop momenta cannot be empty."]; Abort[]]; 
      If[ !OptionValue[FCI], {FeynCalc`FCLoopBasisExtract`Private`expr, 
         FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions} = 
        FCI[{FeynCalc`FCLoopBasisExtract`Private`exp, 
          FRH[FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions]}], 
       {FeynCalc`FCLoopBasisExtract`Private`expr, 
         FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions} = 
        {FeynCalc`FCLoopBasisExtract`Private`exp, 
         FRH[FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions]}]; 
      FCPrint[1, "FCLoopBasisExtract: Entering.", FCDoControl -> 
        FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      FCPrint[3, "FCLoopBasisExtract: Entering with: ", 
       FeynCalc`FCLoopBasisExtract`Private`expr, FCDoControl -> 
        FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      FCPrint[3, "FCLoopBasisExtract: Loop momenta: ", 
       FeynCalc`FCLoopBasisExtract`Private`loopmoms, 
       FCDoControl -> FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      FeynCalc`FCLoopBasisExtract`Private`useToSFAD = 
        !FreeQ[FeynCalc`FCLoopBasisExtract`Private`expr, 
         StandardPropagatorDenominator]; 
      FeynCalc`FCLoopBasisExtract`Private`etaSignsLorentzian = 
       FCLoopGetEtaSigns[FeynCalc`FCLoopBasisExtract`Private`expr, 
        SFAD -> True, GFAD -> False, CFAD -> False]; 
      FeynCalc`FCLoopBasisExtract`Private`etaSignsCartesian = 
       FCLoopGetEtaSigns[FeynCalc`FCLoopBasisExtract`Private`expr, 
        SFAD -> False, GFAD -> False, CFAD -> True]; 
      FeynCalc`FCLoopBasisExtract`Private`etaSignsGeneric = 
       FCLoopGetEtaSigns[FeynCalc`FCLoopBasisExtract`Private`expr, 
        SFAD -> False, GFAD -> True, CFAD -> False]; 
      If[FeynCalc`FCLoopBasisExtract`Private`etaSignsLorentzian === {}, 
       FeynCalc`FCLoopBasisExtract`Private`etaSignsLorentzian = {1}]; 
      If[FeynCalc`FCLoopBasisExtract`Private`etaSignsCartesian === {}, 
       FeynCalc`FCLoopBasisExtract`Private`etaSignsCartesian = {-1}]; 
      If[FeynCalc`FCLoopBasisExtract`Private`etaSignsGeneric === {}, 
       FeynCalc`FCLoopBasisExtract`Private`etaSignsGeneric = {1}]; 
      If[ !MatchQ[FeynCalc`FCLoopBasisExtract`Private`etaSignsLorentzian, 
         {1} | {-1}], Message[FCLoopBasisExtract::failmsg, 
         StringJoin["The integral contains Lorentzian propagators with \
different EtaSign prescriptions. ", "Please use FCLoopSwitchEtaSign to have \
the same prescription in all propagators."]]; Abort[]]; 
      If[ !MatchQ[FeynCalc`FCLoopBasisExtract`Private`etaSignsCartesian, 
         {1} | {-1}], Message[FCLoopBasisExtract::failmsg, 
         StringJoin["The integral contains Cartesian propagators with \
different EtaSign prescriptions. ", "Please use FCLoopSwitchEtaSign to have \
the same prescription in all propagators."]]; Abort[]]; 
      If[ !MatchQ[FeynCalc`FCLoopBasisExtract`Private`etaSignsGeneric, 
         {1} | {-1}], Message[FCLoopBasisExtract::failmsg, 
         StringJoin["The integral contains generic propagators with different \
EtaSign prescriptions. ", "Please use FCLoopSwitchEtaSign to have the same \
prescription in all propagators."]]; Abort[]]; 
      FeynCalc`FCLoopBasisExtract`Private`integralBasis = 
       FCLoopIntegralToPropagators[FeynCalc`FCLoopBasisExtract`Private`expr, 
        FeynCalc`FCLoopBasisExtract`Private`loopmoms, FCI -> True, 
        EtaSign -> {FeynCalc`FCLoopBasisExtract`Private`etaSignsLorentzian[[
           1]], FeynCalc`FCLoopBasisExtract`Private`etaSignsCartesian[[1]], 
          FeynCalc`FCLoopBasisExtract`Private`etaSignsGeneric[[1]]}, 
        Rest -> OptionValue[Rest], Negative -> True, Tally -> True, 
        Pair -> OptionValue[Pair], CartesianPair -> OptionValue[
          CartesianPair], ToSFAD -> 
         FeynCalc`FCLoopBasisExtract`Private`useToSFAD, 
        MomentumCombine -> True, ExpandScalarProduct -> True, Sort -> False]; 
      FCPrint[3, 
       "FCLoopBasisExtract: Integral basis from FCLoopIntegralToPropagators: \
", FeynCalc`FCLoopBasisExtract`Private`integralBasis, 
       FCDoControl -> FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      If[FreeQ2[FeynCalc`FCLoopBasisExtract`Private`expr, 
         {FCTopology, GLI}] && 
        Head[FeynCalc`FCLoopBasisExtract`Private`expr] =!= List, 
       FeynCalc`FCLoopBasisExtract`Private`integralBasis = 
         Join[SelectNotFree[
           FeynCalc`FCLoopBasisExtract`Private`integralBasis, Pair, 
           CartesianPair], SelectFree[
           FeynCalc`FCLoopBasisExtract`Private`integralBasis, Pair, 
           CartesianPair]]; FCPrint[3, 
         "FCLoopBasisExtract: Reordered integral basis: ", 
         FeynCalc`FCLoopBasisExtract`Private`integralBasis, 
         FCDoControl -> FeynCalc`FCLoopBasisExtract`Private`optVerbose]; ]; 
      If[FeynCalc`FCLoopBasisExtract`Private`optSortBy =!= Identity, 
       FeynCalc`FCLoopBasisExtract`Private`integralBasis = 
         SortBy[FeynCalc`FCLoopBasisExtract`Private`integralBasis, 
          FeynCalc`FCLoopBasisExtract`Private`optSortBy]; 
        FCPrint[3, "FCLoopBasisExtract: Sorted integral basis: ", 
         FeynCalc`FCLoopBasisExtract`Private`integralBasis, 
         FCDoControl -> FeynCalc`FCLoopBasisExtract`Private`optVerbose]]; 
      FeynCalc`FCLoopBasisExtract`Private`integralBasisT = 
       Transpose[FeynCalc`FCLoopBasisExtract`Private`integralBasis]; 
      FeynCalc`FCLoopBasisExtract`Private`allmoms = DeleteDuplicates[
        Sort[Cases[MomentumExpand[
           FeynCalc`FCLoopBasisExtract`Private`integralBasis], 
          (Momentum | CartesianMomentum | TemporalMomentum)[
            FeynCalc`FCLoopBasisExtract`Private`x_, ___] :> 
           FeynCalc`FCLoopBasisExtract`Private`x, Infinity]]]; 
      FeynCalc`FCLoopBasisExtract`Private`extmoms = 
       Complement[FeynCalc`FCLoopBasisExtract`Private`allmoms, 
        FeynCalc`FCLoopBasisExtract`Private`loopmoms]; 
      If[OptionValue[FCTopology], FeynCalc`FCLoopBasisExtract`Private`lmoms = 
        FeynCalc`FCLoopBasisExtract`Private`loopmoms, 
       FeynCalc`FCLoopBasisExtract`Private`lmoms = Intersection[
         FeynCalc`FCLoopBasisExtract`Private`loopmoms, 
         Complement[FeynCalc`FCLoopBasisExtract`Private`allmoms, 
          FeynCalc`FCLoopBasisExtract`Private`extmoms]]]; 
      FeynCalc`FCLoopBasisExtract`Private`basisElements = 
       FCLoopPropagatorsToTopology[
        FeynCalc`FCLoopBasisExtract`Private`integralBasisT[[1]], FCI -> True, 
        ExpandScalarProduct -> True, DeleteDuplicates -> False]; 
      If[FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions =!= {}, 
       FeynCalc`FCLoopBasisExtract`Private`basisElements = 
        FeynCalc`FCLoopBasisExtract`Private`basisElements //. 
         FeynCalc`FCLoopBasisExtract`Private`optFinalSubstitutions]; 
      FCPrint[3, 
       "FCLoopBasisExtract: Basis elements from FCLoopPropagatorsToTopology: \
", FeynCalc`FCLoopBasisExtract`Private`basisElements, 
       FCDoControl -> FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      FeynCalc`FCLoopBasisExtract`Private`availableDims = 
       Intersection[FCGetDimensions[
         FeynCalc`FCLoopBasisExtract`Private`basisElements], 
        FeynCalc`FCLoopBasisExtract`Private`dims]; 
      If[FeynCalc`FCLoopBasisExtract`Private`availableDims === {}, 
       Message[FCLoopBasisExtract::failmsg, 
         "The supplied dimensions are not present in the given expression."]; 
        Abort[]]; FeynCalc`FCLoopBasisExtract`Private`lorentzianDims = 
       Cases[FeynCalc`FCLoopBasisExtract`Private`availableDims, 4 | _Symbol]; 
      If[FeynCalc`FCLoopBasisExtract`Private`lorentzianDims =!= {}, 
       FeynCalc`FCLoopBasisExtract`Private`coeffsPair = 
        Sort[FCLoopBasisCreateScalarProducts[
          FeynCalc`FCLoopBasisExtract`Private`lmoms, 
          FeynCalc`FCLoopBasisExtract`Private`extmoms, 
          FeynCalc`FCLoopBasisExtract`Private`lorentzianDims, Pair]], 
       FeynCalc`FCLoopBasisExtract`Private`coeffsPair = {}]; 
      FeynCalc`FCLoopBasisExtract`Private`cartesianDims = 
       Cases[FeynCalc`FCLoopBasisExtract`Private`availableDims, 
        3 | _Symbol - 1]; 
      If[FeynCalc`FCLoopBasisExtract`Private`cartesianDims =!= {}, 
       FeynCalc`FCLoopBasisExtract`Private`coeffsCartesianPair = 
        Sort[FCLoopBasisCreateScalarProducts[
          FeynCalc`FCLoopBasisExtract`Private`lmoms, 
          FeynCalc`FCLoopBasisExtract`Private`extmoms, 
          FeynCalc`FCLoopBasisExtract`Private`cartesianDims, CartesianPair]], 
       FeynCalc`FCLoopBasisExtract`Private`coeffsCartesianPair = {}]; 
      FeynCalc`FCLoopBasisExtract`Private`coeffsTemporalPair = 
       Sort[(TemporalPair[ExplicitLorentzIndex[0], TemporalMomentum[
            #1]] & ) /@ FeynCalc`FCLoopBasisExtract`Private`lmoms]; 
      FeynCalc`FCLoopBasisExtract`Private`coeffs = {}; 
      If[ !FreeQ[FeynCalc`FCLoopBasisExtract`Private`expr, Momentum], 
       FeynCalc`FCLoopBasisExtract`Private`coeffs = 
        Join[FeynCalc`FCLoopBasisExtract`Private`coeffs, 
         FeynCalc`FCLoopBasisExtract`Private`coeffsPair]]; 
      If[ !FreeQ[FeynCalc`FCLoopBasisExtract`Private`expr, 
         CartesianMomentum], FeynCalc`FCLoopBasisExtract`Private`coeffs = 
        Join[FeynCalc`FCLoopBasisExtract`Private`coeffs, 
         FeynCalc`FCLoopBasisExtract`Private`coeffsCartesianPair]]; 
      If[ !FreeQ[FeynCalc`FCLoopBasisExtract`Private`expr, TemporalMomentum], 
       FeynCalc`FCLoopBasisExtract`Private`coeffs = 
        Join[FeynCalc`FCLoopBasisExtract`Private`coeffs, 
         FeynCalc`FCLoopBasisExtract`Private`coeffsTemporalPair]]; 
      FeynCalc`FCLoopBasisExtract`Private`aux = 
       Flatten[(List @@ (ExpandAll[#1] + 
             FeynCalc`FCLoopBasisExtract`Private`null1 + 
             FeynCalc`FCLoopBasisExtract`Private`null2) & ) /@ 
          FeynCalc`FCLoopBasisExtract`Private`basisElements /. 
         FeynCalc`FCLoopBasisExtract`Private`null1 | 
           FeynCalc`FCLoopBasisExtract`Private`null2 :> 
          Unevaluated[Sequence[]]]; FeynCalc`FCLoopBasisExtract`Private`aux = 
       Union[(SelectNotFree[#1, 
            FeynCalc`FCLoopBasisExtract`Private`lmoms] & ) /@ 
          FeynCalc`FCLoopBasisExtract`Private`aux //. 
         {FeynCalc`FCLoopBasisExtract`Private`r___, 1, 
           FeynCalc`FCLoopBasisExtract`Private`s___} :> 
          {FeynCalc`FCLoopBasisExtract`Private`r, 
           FeynCalc`FCLoopBasisExtract`Private`s}]; 
      FeynCalc`FCLoopBasisExtract`Private`coeffs = 
       Join[FeynCalc`FCLoopBasisExtract`Private`coeffs, 
        Complement[FeynCalc`FCLoopBasisExtract`Private`aux, 
         FeynCalc`FCLoopBasisExtract`Private`coeffs]]; 
      FCPrint[3, 
       "FCLoopBasisExtract: Loop momentum dependent coefficients: ", 
       FeynCalc`FCLoopBasisExtract`Private`coeffs, FCDoControl -> 
        FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      FCPrint[1, "FCLoopBasisExtract: Leaving.", FCDoControl -> 
        FeynCalc`FCLoopBasisExtract`Private`optVerbose]; 
      FeynCalc`FCLoopBasisExtract`Private`res = 
       {FeynCalc`FCLoopBasisExtract`Private`basisElements, 
        FeynCalc`FCLoopBasisExtract`Private`coeffs, 
        FeynCalc`FCLoopBasisExtract`Private`integralBasisT[[2]], 
        FeynCalc`FCLoopBasisExtract`Private`integralBasisT[[1]]}; 
      If[OptionValue[FCE], FeynCalc`FCLoopBasisExtract`Private`res = 
        FCE[FeynCalc`FCLoopBasisExtract`Private`res]]; 
      FeynCalc`FCLoopBasisExtract`Private`res]
 
Options[FCLoopBasisExtract] = {CartesianPair -> True, 
     FeynCalcInternal -> False, FeynCalcExternal -> False, 
     FCVerbose -> False, FCTopology -> False, FinalSubstitutions -> {}, 
     Pair -> True, Rest -> None, SetDimensions -> {3, 4, D, -1 + D}, 
     SortBy -> Identity}
 
FCLoopBasisExtract /: FCLoopBasisExtract::failmsg = "Error! \
FCLoopBasisExtract has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCLoopBasisExtract /: FCLoopBasisExtract::usage = "FCLoopBasisExtract[int, \
{q1, q2, ...}] is an auxiliary function that extracts\nthe scalar products \
that form the basis of the loop integral in int. It needs\nto know the loop \
momenta on which the integral depends and the dimensions of\nthe momenta that \
may occur in the integral."
 
FCLoopGetEtaSigns[FeynCalc`FCLoopGetEtaSigns`Private`expr_, 
     OptionsPattern[]] := Block[{FeynCalc`FCLoopGetEtaSigns`Private`ex, 
      FeynCalc`FCLoopGetEtaSigns`Private`res, 
      FeynCalc`FCLoopGetEtaSigns`Private`signs, 
      FeynCalc`FCLoopGetEtaSigns`Private`propTypes = {}}, 
     If[OptionValue[FCI], FeynCalc`FCLoopGetEtaSigns`Private`ex = 
        FeynCalc`FCLoopGetEtaSigns`Private`expr, 
       FeynCalc`FCLoopGetEtaSigns`Private`ex = 
        FCI[FeynCalc`FCLoopGetEtaSigns`Private`expr]]; 
      If[ !FreeQ[FeynCalc`FCLoopGetEtaSigns`Private`ex, 
         PropagatorDenominator], FeynCalc`FCLoopGetEtaSigns`Private`ex = 
        ToSFAD[FeynCalc`FCLoopGetEtaSigns`Private`ex, FCI -> True]]; 
      If[OptionValue[SFAD], FeynCalc`FCLoopGetEtaSigns`Private`propTypes = 
        Join[FeynCalc`FCLoopGetEtaSigns`Private`propTypes, 
         {StandardPropagatorDenominator}]]; If[OptionValue[CFAD], 
       FeynCalc`FCLoopGetEtaSigns`Private`propTypes = 
        Join[FeynCalc`FCLoopGetEtaSigns`Private`propTypes, 
         {CartesianPropagatorDenominator}]]; If[OptionValue[GFAD], 
       FeynCalc`FCLoopGetEtaSigns`Private`propTypes = 
        Join[FeynCalc`FCLoopGetEtaSigns`Private`propTypes, 
         {GenericPropagatorDenominator}]]; 
      FeynCalc`FCLoopGetEtaSigns`Private`propTypes = 
       Alternatives @@ FeynCalc`FCLoopGetEtaSigns`Private`propTypes; 
      FeynCalc`FCLoopGetEtaSigns`Private`signs = 
       Cases[FeynCalc`FCLoopGetEtaSigns`Private`ex, 
        FeynCalc`FCLoopGetEtaSigns`Private`propTypes[__, 
          {_, FeynCalc`FCLoopGetEtaSigns`Private`s_}] :> 
         FeynCalc`FCLoopGetEtaSigns`Private`s, Infinity]; 
      FeynCalc`FCLoopGetEtaSigns`Private`res = 
       Union[Flatten[FeynCalc`FCLoopGetEtaSigns`Private`signs]]; 
      FeynCalc`FCLoopGetEtaSigns`Private`res]
 
Options[FCLoopGetEtaSigns] = {ToSFAD -> True, FeynCalcInternal -> False, 
     CFAD -> True, GFAD -> True, SFAD -> True}
 
FCLoopGetEtaSigns /: FCLoopGetEtaSigns::failmsg = "FCLoopGetEtaSigns has \
encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCLoopGetEtaSigns /: FCLoopGetEtaSigns::usage = "FCLoopGetEtaSigns[exp]  is \
an auxiliary function that extracts the signs of $i\n\\eta$ from propagators \
present in the input expression.  The result is\nreturned as a list, e.g. {}, \
{1}, {-1} or {-1,1}.\n\nThis is useful if one wants ensure that all \
propagators of the given integral\nor topology follow a particular $i \\eta$ \
sign convention."
 
ToSFAD[FeynCalc`ToSFAD`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`ToSFAD`Private`ex, FeynCalc`ToSFAD`Private`res, 
      FeynCalc`ToSFAD`Private`fads, FeynCalc`ToSFAD`Private`pds, 
      FeynCalc`ToSFAD`Private`pdsEval, FeynCalc`ToSFAD`Private`fadsConverted, 
      FeynCalc`ToSFAD`Private`pdsConverted, FeynCalc`ToSFAD`Private`rulePds, 
      FeynCalc`ToSFAD`Private`ruleFads, FeynCalc`ToSFAD`Private`ruleFinal}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`ToSFAD`Private`sfadVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`ToSFAD`Private`sfadVerbose = OptionValue[FCVerbose]]; ]; 
      FCPrint[1, "ToSFAD: Entering.", FCDoControl -> 
        FeynCalc`ToSFAD`Private`sfadVerbose]; 
      FCPrint[3, "ToSFAD: Entering with: ", FeynCalc`ToSFAD`Private`expr, 
       FCDoControl -> FeynCalc`ToSFAD`Private`sfadVerbose]; 
      If[OptionValue[FCI], FeynCalc`ToSFAD`Private`ex = 
        FeynCalc`ToSFAD`Private`expr, FeynCalc`ToSFAD`Private`ex = 
        FCI[FeynCalc`ToSFAD`Private`expr]]; 
      If[FreeQ2[{FeynCalc`ToSFAD`Private`ex}, {PropagatorDenominator, 
         CartesianPropagatorDenominator}], 
       Return[FeynCalc`ToSFAD`Private`ex]]; 
      FeynCalc`ToSFAD`Private`optEtaSign = OptionValue[EtaSign]; 
      FeynCalc`ToSFAD`Private`pds = Cases2[FeynCalc`ToSFAD`Private`ex, 
        {PropagatorDenominator, CartesianPropagatorDenominator}]; 
      FCPrint[3, "ToSFAD: Relevant propagator denominators: ", 
       FeynCalc`ToSFAD`Private`pds, FCDoControl -> 
        FeynCalc`ToSFAD`Private`sfadVerbose]; 
      FeynCalc`ToSFAD`Private`pdsEval = 
       (FeynCalc`ToSFAD`Private`toSFAD[MomentumCombine[#1, 
           FCI -> True]] & ) /@ FeynCalc`ToSFAD`Private`pds; 
      FeynCalc`ToSFAD`Private`pdsEval = FeynCalc`ToSFAD`Private`pdsEval /. 
        FeynCalc`ToSFAD`Private`toSFAD[
          FeynCalc`ToSFAD`Private`x_CartesianPropagatorDenominator] :> 
         FeynCalc`ToSFAD`Private`x; FCPrint[3, "ToSFAD: After toSFAD: ", 
       FeynCalc`ToSFAD`Private`pdsEval, FCDoControl -> 
        FeynCalc`ToSFAD`Private`sfadVerbose]; 
      If[ !FreeQ[FeynCalc`ToSFAD`Private`pdsEval, 
         FeynCalc`ToSFAD`Private`toSFAD], Message[ToSFAD::failmsg, "Failed to \
convert all PropagatorDenominators to StandardPropagatorDenominators."]; 
        Abort[]]; FeynCalc`ToSFAD`Private`ruleFinal = 
       Thread[FeynCalc`ToSFAD`Private`pds -> 
         FeynCalc`ToSFAD`Private`pdsEval]; FeynCalc`ToSFAD`Private`res = 
       FeynCalc`ToSFAD`Private`ex /. FeynCalc`ToSFAD`Private`ruleFinal; 
      If[ !FreeQ2[{FeynCalc`ToSFAD`Private`res}, 
         {FAD, PropagatorDenominator}], Message[ToSFAD::failmsg, 
        "Failed to eliminate all the occurences of FADs or PDs."]]; 
      If[OptionValue[FCE], FeynCalc`ToSFAD`Private`res = 
        FCE[FeynCalc`ToSFAD`Private`res]]; FCPrint[1, "ToSFAD: Leaving.", 
       FCDoControl -> FeynCalc`ToSFAD`Private`sfadVerbose]; 
      FeynCalc`ToSFAD`Private`res]
 
Options[ToSFAD] = {EtaSign -> Automatic, FeynCalcInternal -> False, 
     FeynCalcExternal -> False, FCVerbose -> False}
 
ToSFAD /: ToSFAD::failmsg = "Error! ToSFAD has encountered a fatal problem \
and must abort the computation. The problem reads: `1`"
 
ToSFAD /: ToSFAD::usage = "ToSFAD[exp] converts all propagator denominators \
written as FAD or\nFeynAmpDenmoninator[...,PropagatorDenominator[...],...] to \
SFAD or\nFeynAmpDenmoninator[...,StandardPropagatorDenominator[...],...] \
