          Abort[]]]; If[OptionValue[Negative], 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        FeynCalc`FCLoopIntegralToPropagators`Private`res /. 
         {{FeynAmpDenominator[(FeynCalc`FCLoopIntegralToPropagators`Private`h:
                StandardPropagatorDenominator | 
                 CartesianPropagatorDenominator | 
                 GenericPropagatorDenominator)[
               FeynCalc`FCLoopIntegralToPropagators`Private`a__, {
                FeynCalc`FCLoopIntegralToPropagators`Private`n_Integer, 
                FeynCalc`FCLoopIntegralToPropagators`Private`s_}]], 
             FeynCalc`FCLoopIntegralToPropagators`Private`pow_} /; 
            FeynCalc`FCLoopIntegralToPropagators`Private`n < 0 && 
             FeynCalc`FCLoopIntegralToPropagators`Private`pow > 0 :> 
           {FeynAmpDenominator[FeynCalc`FCLoopIntegralToPropagators`Private`h[
              FeynCalc`FCLoopIntegralToPropagators`Private`a, 
              {FeynCalc`FCLoopIntegralToPropagators`Private`n, 
               FeynCalc`FCLoopIntegralToPropagators`Private`s}]], 
            -FeynCalc`FCLoopIntegralToPropagators`Private`pow}}]; 
      If[OptionValue[Pair], 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        FeynCalc`FCLoopIntegralToPropagators`Private`res /. 
         FeynAmpDenominator[StandardPropagatorDenominator[0, 
            FeynCalc`FCLoopIntegralToPropagators`Private`sp_, 0, {-1, _}]] :> 
          FeynCalc`FCLoopIntegralToPropagators`Private`sp]; 
      If[OptionValue[CartesianPair], 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        FeynCalc`FCLoopIntegralToPropagators`Private`res /. 
         FeynAmpDenominator[CartesianPropagatorDenominator[0, 
            FeynCalc`FCLoopIntegralToPropagators`Private`sp_, 0, {-1, _}]] :> 
          FeynCalc`FCLoopIntegralToPropagators`Private`sp]; 
      If[OptionValue[TemporalPair], 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        FeynCalc`FCLoopIntegralToPropagators`Private`res /. 
         FeynAmpDenominator[GenericPropagatorDenominator[
            FeynCalc`FCLoopIntegralToPropagators`Private`sp_, {-1, _}]] :> 
          FeynCalc`FCLoopIntegralToPropagators`Private`sp]; 
      Switch[OptionValue[Rest], True, 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        {FeynCalc`FCLoopIntegralToPropagators`Private`res, 
         FeynCalc`FCLoopIntegralToPropagators`Private`rest}, False, Null, 
       None, If[FeynCalc`FCLoopIntegralToPropagators`Private`rest =!= 1, 
        Message[FCLoopIntegralToPropagators::failmsg, 
          "The input expression may not contain non-loop terms!"]; Abort[]], 
       _, Message[FCLoopIntegralToPropagators::failmsg, 
         "Unknown value of the option Rest."]; Abort[]]; 
      If[OptionValue[ExpandScalarProduct], 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        ExpandScalarProduct[FeynCalc`FCLoopIntegralToPropagators`Private`res, 
         FCI -> True]]; If[OptionValue[FCE], 
       FeynCalc`FCLoopIntegralToPropagators`Private`res = 
        FCE[FeynCalc`FCLoopIntegralToPropagators`Private`res]]; 
      FCPrint[1, "FCLoopIntegralToPropagators: Leaving.", 
       FCDoControl -> 
        FeynCalc`FCLoopIntegralToPropagators`Private`itpVerbose]; 
      FCPrint[3, "FCLoopIntegralToPropagators: Leaving with ", 
       FeynCalc`FCLoopIntegralToPropagators`Private`res, 
       FCDoControl -> 
        FeynCalc`FCLoopIntegralToPropagators`Private`itpVerbose]; 
      FeynCalc`FCLoopIntegralToPropagators`Private`res]
 
Options[FCLoopIntegralToPropagators] = {CartesianPair -> False, 
     EtaSign -> {1, -1, 1}, ExpandScalarProduct -> False, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCVerbose -> False, MomentumCombine -> True, Negative -> False, 
     Pair -> False, Rest -> False, Sort -> True, Tally -> False, 
     TemporalPair -> False, ToSFAD -> True}
 
FCLoopIntegralToPropagators /: FCLoopIntegralToPropagators::failmsg = "Error! \
FCLoopIntegralToPropagators encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCLoopIntegralToPropagators /: FCLoopIntegralToPropagators::usage = "FCLoopIn\
tegralToPropagators[int, {q1, q2, ...}] is an auxiliary function \
that\nconverts the loop integral int that depends on the loop momenta q1, q2, \
... to\na list of propagators and scalar products.\n\nAll propagators and \
scalar products that do not depend on the loop momenta are\ndiscarded, unless \
the Rest option is set to True."
 
FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign = {1, -1, 1}
 
FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign /: 
    FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign::usage = ""
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`exp_FeynAmpDenominator)^
      (FeynCalc`FCLoopIntegralToPropagators`Private`n_Integer)?Positive, 
     _] := ConstantArray[{FeynCalc`FCLoopIntegralToPropagators`Private`exp}, 
      FeynCalc`FCLoopIntegralToPropagators`Private`n] /; 
     Length[List @@ FeynCalc`FCLoopIntegralToPropagators`Private`exp] === 1
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     FeynAmpDenominator[StandardPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`args__, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`pow_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}]]^
      (FeynCalc`FCLoopIntegralToPropagators`Private`n_Integer)?Negative, 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     FeynAmpDenominator[StandardPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`args, 
       {FeynCalc`FCLoopIntegralToPropagators`Private`pow*
         FeynCalc`FCLoopIntegralToPropagators`Private`n, 
        FeynCalc`FCLoopIntegralToPropagators`Private`s}]], 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`c_.)*
      (FeynCalc`FCLoopIntegralToPropagators`Private`a_FeynAmpDenominator)*
      (FeynCalc`FCLoopIntegralToPropagators`Private`b_FeynAmpDenominator), 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    {FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
      FeynCalc`FCLoopIntegralToPropagators`Private`a, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms], 
     FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
      FeynCalc`FCLoopIntegralToPropagators`Private`b*
       FeynCalc`FCLoopIntegralToPropagators`Private`c, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]}
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     FeynCalc`FCLoopIntegralToPropagators`Private`exp_FeynAmpDenominator, 
     _] := {FeynCalc`FCLoopIntegralToPropagators`Private`exp} /; 
     Length[List @@ FeynCalc`FCLoopIntegralToPropagators`Private`exp] === 1
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref0_.)*
      ((FeynCalc`FCLoopIntegralToPropagators`Private`pref_.)*
        (FeynCalc`FCLoopIntegralToPropagators`Private`exp_Pair))^
       (FeynCalc`FCLoopIntegralToPropagators`Private`n_Integer)?Positive, 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    ConstantArray[FeynAmpDenominator[StandardPropagatorDenominator[0, 
        FeynCalc`FCLoopIntegralToPropagators`Private`pow[
          FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 
          1/FeynCalc`FCLoopIntegralToPropagators`Private`n]*
         FeynCalc`FCLoopIntegralToPropagators`Private`pref*
         FeynCalc`FCLoopIntegralToPropagators`Private`exp, 0, 
        {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[1]]}]], 
      FeynCalc`FCLoopIntegralToPropagators`Private`n] /; 
     FreeQ2[{FeynCalc`FCLoopIntegralToPropagators`Private`pref, 
       FeynCalc`FCLoopIntegralToPropagators`Private`pref0}, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref_.)*
      (FeynCalc`FCLoopIntegralToPropagators`Private`exp_Pair), 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    FeynAmpDenominator[StandardPropagatorDenominator[0, 
       FeynCalc`FCLoopIntegralToPropagators`Private`pref*
        FeynCalc`FCLoopIntegralToPropagators`Private`exp, 0, 
       {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[
         1]]}]] /; FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`pref, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref0_.)*
      ((FeynCalc`FCLoopIntegralToPropagators`Private`pref_.)*
        (FeynCalc`FCLoopIntegralToPropagators`Private`exp_CartesianPair))^
       (FeynCalc`FCLoopIntegralToPropagators`Private`n_Integer)?Positive, 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    ConstantArray[FeynAmpDenominator[CartesianPropagatorDenominator[0, 
        FeynCalc`FCLoopIntegralToPropagators`Private`pow[
          FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 
          1/FeynCalc`FCLoopIntegralToPropagators`Private`n]*
         FeynCalc`FCLoopIntegralToPropagators`Private`pref*
         FeynCalc`FCLoopIntegralToPropagators`Private`exp, 0, 
        {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[2]]}]], 
      FeynCalc`FCLoopIntegralToPropagators`Private`n] /; 
     FreeQ2[{FeynCalc`FCLoopIntegralToPropagators`Private`pref, 
       FeynCalc`FCLoopIntegralToPropagators`Private`pref0}, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref0_.)*
      ((FeynCalc`FCLoopIntegralToPropagators`Private`pref_.)*
        (FeynCalc`FCLoopIntegralToPropagators`Private`exp_CartesianPair))^
       ((FeynCalc`FCLoopIntegralToPropagators`Private`n_Rational)?Positive /; 
        Denominator[FeynCalc`FCLoopIntegralToPropagators`Private`n] === 2 && 
         Numerator[FeynCalc`FCLoopIntegralToPropagators`Private`n] >= 3), 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    Join[ConstantArray[FeynAmpDenominator[CartesianPropagatorDenominator[0, 
         FeynCalc`FCLoopIntegralToPropagators`Private`pow[
           FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 
           1/(FeynCalc`FCLoopIntegralToPropagators`Private`n - 1/2)]*
          FeynCalc`FCLoopIntegralToPropagators`Private`pref*
          FeynCalc`FCLoopIntegralToPropagators`Private`exp, 0, 
         {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[
           2]]}]], FeynCalc`FCLoopIntegralToPropagators`Private`n - 1/2], 
      {FeynAmpDenominator[CartesianPropagatorDenominator[0, 
         FeynCalc`FCLoopIntegralToPropagators`Private`pow[
           FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 1/2]*
          Sqrt[FeynCalc`FCLoopIntegralToPropagators`Private`pref]*
          Sqrt[FeynCalc`FCLoopIntegralToPropagators`Private`exp], 0, 
         {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[
           2]]}]]}] /; FreeQ2[
      {FeynCalc`FCLoopIntegralToPropagators`Private`pref, 
       FeynCalc`FCLoopIntegralToPropagators`Private`pref0}, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref_.)*
      (FeynCalc`FCLoopIntegralToPropagators`Private`exp_CartesianPair), 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    FeynAmpDenominator[CartesianPropagatorDenominator[0, 
       FeynCalc`FCLoopIntegralToPropagators`Private`pref*
        FeynCalc`FCLoopIntegralToPropagators`Private`exp, 0, 
       {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[
         2]]}]] /; FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`pref, 
      FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`pow /: 
    FeynCalc`FCLoopIntegralToPropagators`Private`pow::usage = ""
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators2[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref0_.)*
      (FeynCalc`FCLoopIntegralToPropagators`Private`exp_)^
       (FeynCalc`FCLoopIntegralToPropagators`Private`n_Integer)?Positive, 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    ConstantArray[FeynAmpDenominator[GenericPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`pow[
          FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 
          1/FeynCalc`FCLoopIntegralToPropagators`Private`n]*
         FeynCalc`FCLoopIntegralToPropagators`Private`exp, 
        {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[3]]}]], 
      FeynCalc`FCLoopIntegralToPropagators`Private`n] /; 
      !FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`exp, 
        FeynCalc`FCLoopIntegralToPropagators`Private`lmoms] && 
      FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 
       FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators2[
     (FeynCalc`FCLoopIntegralToPropagators`Private`pref0_.)*
      (FeynCalc`FCLoopIntegralToPropagators`Private`exp_)^
       ((FeynCalc`FCLoopIntegralToPropagators`Private`n_Rational)?Positive /; 
        Numerator[FeynCalc`FCLoopIntegralToPropagators`Private`n] === 1), 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    FeynAmpDenominator[GenericPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`pref0*
        FeynCalc`FCLoopIntegralToPropagators`Private`exp^
         FeynCalc`FCLoopIntegralToPropagators`Private`n, 
       {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[
         3]]}]] /;  !FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`exp, 
        FeynCalc`FCLoopIntegralToPropagators`Private`lmoms] && 
      FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`pref0, 
       FeynCalc`FCLoopIntegralToPropagators`Private`lmoms]
 
FeynCalc`FCLoopIntegralToPropagators`Private`auxIntegralToPropagators2[
     FeynCalc`FCLoopIntegralToPropagators`Private`exp_, 
     FeynCalc`FCLoopIntegralToPropagators`Private`lmoms_] := 
    FeynAmpDenominator[GenericPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`exp, 
       {-1, FeynCalc`FCLoopIntegralToPropagators`Private`optEtaSign[[
         3]]}]] /;  !FreeQ2[FeynCalc`FCLoopIntegralToPropagators`Private`exp, 
        FeynCalc`FCLoopIntegralToPropagators`Private`lmoms] && 
      Head[FeynCalc`FCLoopIntegralToPropagators`Private`exp] =!= Power
 
FeynCalc`FCLoopIntegralToPropagators`Private`rulePropagatorPowersToOne = 
    {CartesianPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`arg__, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`i_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}] /; 
       FeynCalc`FCLoopIntegralToPropagators`Private`i =!= 1 :> 
      CartesianPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`arg, 
       {1, FeynCalc`FCLoopIntegralToPropagators`Private`s}], 
     StandardPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`arg__, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`i_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}] /; 
       FeynCalc`FCLoopIntegralToPropagators`Private`i =!= 1 :> 
      StandardPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`arg, 
       {1, FeynCalc`FCLoopIntegralToPropagators`Private`s}], 
     GenericPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`arg_, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`i_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}] /; 
       FeynCalc`FCLoopIntegralToPropagators`Private`i =!= 1 :> 
      GenericPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`arg, 
       {1, FeynCalc`FCLoopIntegralToPropagators`Private`s}]}
 
FeynCalc`FCLoopIntegralToPropagators`Private`rulePropagatorPowers = 
    {CartesianPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`arg__, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`i_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}] /; 
       Abs[FeynCalc`FCLoopIntegralToPropagators`Private`i] =!= 1 && 
        FeynCalc`FCLoopIntegralToPropagators`Private`i =!= 0 :> 
      CartesianPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`arg, 
       {Sign[FeynCalc`FCLoopIntegralToPropagators`Private`i], 
        FeynCalc`FCLoopIntegralToPropagators`Private`s}], 
     StandardPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`arg__, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`i_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}] /; 
       Abs[FeynCalc`FCLoopIntegralToPropagators`Private`i] =!= 1 && 
        FeynCalc`FCLoopIntegralToPropagators`Private`i =!= 0 :> 
      StandardPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`arg, 
       {Sign[FeynCalc`FCLoopIntegralToPropagators`Private`i], 
        FeynCalc`FCLoopIntegralToPropagators`Private`s}], 
     GenericPropagatorDenominator[
        FeynCalc`FCLoopIntegralToPropagators`Private`arg_, 
        {FeynCalc`FCLoopIntegralToPropagators`Private`i_, 
         FeynCalc`FCLoopIntegralToPropagators`Private`s_}] /; 
       Abs[FeynCalc`FCLoopIntegralToPropagators`Private`i] =!= 1 && 
        FeynCalc`FCLoopIntegralToPropagators`Private`i =!= 0 :> 
      GenericPropagatorDenominator[
       FeynCalc`FCLoopIntegralToPropagators`Private`arg, 
       {Sign[FeynCalc`FCLoopIntegralToPropagators`Private`i], 
        FeynCalc`FCLoopIntegralToPropagators`Private`s}]}
 
FCLoopPropagatorsToTopology[
     FeynCalc`FCLoopPropagatorsToTopology`Private`topos:{__FCTopology}, 
     FeynCalc`FCLoopPropagatorsToTopology`Private`opts:OptionsPattern[]] := 
    (FCLoopPropagatorsToTopology[#1, 
       FeynCalc`FCLoopPropagatorsToTopology`Private`opts] & ) /@ 
     FeynCalc`FCLoopPropagatorsToTopology`Private`topos
 
FCLoopPropagatorsToTopology[
     FeynCalc`FCLoopPropagatorsToTopology`Private`topoRaw_FCTopology, 
     FeynCalc`FCLoopPropagatorsToTopology`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopPropagatorsToTopology`Private`topo, 
      FeynCalc`FCLoopPropagatorsToTopology`Private`optFinalSubstitutions}, 
     If[OptionValue[FCI], FeynCalc`FCLoopPropagatorsToTopology`Private`topo = 
        FeynCalc`FCLoopPropagatorsToTopology`Private`topoRaw, 
       FeynCalc`FCLoopPropagatorsToTopology`Private`topo = 
        FCI[FeynCalc`FCLoopPropagatorsToTopology`Private`topoRaw]]; 
      If[ !FCLoopValidTopologyQ[
         FeynCalc`FCLoopPropagatorsToTopology`Private`topo], 
       Message[FCLoopPropagatorsToTopology::failmsg, 
         "The supplied topology is incorrect."]; Abort[]]; 
      FCLoopPropagatorsToTopology[
       FeynCalc`FCLoopPropagatorsToTopology`Private`topo[[2]], 
       Join[{FCI -> True}, FilterRules[
         {FeynCalc`FCLoopPropagatorsToTopology`Private`opts}, Except[FCI]]]]]
 
FCLoopPropagatorsToTopology[
     FeynCalc`FCLoopPropagatorsToTopology`Private`props_List /; 
      FeynCalc`FCLoopPropagatorsToTopology`Private`props =!= {} && 
       FreeQ[FeynCalc`FCLoopPropagatorsToTopology`Private`props, FCTopology], 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopPropagatorsToTopology`Private`expr, 
      FeynCalc`FCLoopPropagatorsToTopology`Private`tmp, 
      FeynCalc`FCLoopPropagatorsToTopology`Private`res}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopPropagatorsToTopology`Private`fclpttVerbose = 
        $VeryVerbose, If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopPropagatorsToTopology`Private`fclpttVerbose = 
          OptionValue[FCVerbose]]; ]; FCPrint[1, 
       "FCLoopPropagatorsToTopology: Entering.", FCDoControl -> 
        FeynCalc`FCLoopPropagatorsToTopology`Private`fclpttVerbose]; 
      FCPrint[3, "FCLoopPropagatorsToTopology: Entering with: ", 
       FeynCalc`FCLoopPropagatorsToTopology`Private`props, 
       FCDoControl -> 
        FeynCalc`FCLoopPropagatorsToTopology`Private`fclpttVerbose]; 
      If[ !OptionValue[FCI], 
       FeynCalc`FCLoopPropagatorsToTopology`Private`expr = 
        FCI[FeynCalc`FCLoopPropagatorsToTopology`Private`props], 
       FeynCalc`FCLoopPropagatorsToTopology`Private`expr = 
        FeynCalc`FCLoopPropagatorsToTopology`Private`props]; 
      If[OptionValue[MomentumCombine], 
       FeynCalc`FCLoopPropagatorsToTopology`Private`expr = 
        MomentumCombine[FeynCalc`FCLoopPropagatorsToTopology`Private`expr, 
         FCI -> True]]; FeynCalc`FCLoopPropagatorsToTopology`Private`tmp = 
       FeynCalc`FCLoopPropagatorsToTopology`Private`expr /. 
