or] :> 1/FeynAmpDenominator[FeynCalc`FCLoopPropagatorsToTopology`Private`a], 
         FeynAmpDenominator[(FeynCalc`FCLoopPropagatorsToTopology`Private`h:
              StandardPropagatorDenominator | 
               CartesianPropagatorDenominator | GenericPropagatorDenominator)[
             FeynCalc`FCLoopPropagatorsToTopology`Private`a__, 
             {FeynCalc`FCLoopPropagatorsToTopology`Private`n_, 
              FeynCalc`FCLoopPropagatorsToTopology`Private`s_}]] /; 
           FeynCalc`FCLoopPropagatorsToTopology`Private`n =!= 0 :> 
          FeynAmpDenominator[FeynCalc`FCLoopPropagatorsToTopology`Private`h[
            FeynCalc`FCLoopPropagatorsToTopology`Private`a, 
            {-1, FeynCalc`FCLoopPropagatorsToTopology`Private`s}]]}; 
      FCPrint[3, "FCLoopPropagatorsToTopology: tmp: ", 
       FeynCalc`FCLoopPropagatorsToTopology`Private`tmp, 
       FCDoControl -> 
        FeynCalc`FCLoopPropagatorsToTopology`Private`fclpttVerbose]; 
      FeynCalc`FCLoopPropagatorsToTopology`Private`res = 
       (FeynAmpDenominatorExplicit[#1, FCI -> True, ExpandScalarProduct -> 
           False] & ) /@ FeynCalc`FCLoopPropagatorsToTopology`Private`tmp; 
      FCPrint[3, "FCLoopPropagatorsToTopology: Raw result: ", 
       FeynCalc`FCLoopPropagatorsToTopology`Private`res, 
       FCDoControl -> 
        FeynCalc`FCLoopPropagatorsToTopology`Private`fclpttVerbose]; 
      If[OptionValue[ExpandScalarProduct], 
