FCLoopBasisCreateScalarProducts[
     FeynCalc`FCLoopBasisCreateScalarProducts`Private`lmoms_List, 
     FeynCalc`FCLoopBasisCreateScalarProducts`Private`extmoms_List, 
     FeynCalc`FCLoopBasisCreateScalarProducts`Private`dims_List, 
     FeynCalc`FCLoopBasisCreateScalarProducts`Private`head_Symbol, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp, 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`res, 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`dummyDim, 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`repRule}, 
     If[Length[FeynCalc`FCLoopBasisCreateScalarProducts`Private`lmoms] === 0, 
       Message[FCLoopBasisCreateScalarProducts::failmsg, 
         "The list of loop momenta may not be empty."]; Abort[]]; 
      If[Length[FeynCalc`FCLoopBasisCreateScalarProducts`Private`dims] === 0, 
       Message[FCLoopBasisCreateScalarProducts::failmsg, 
         "The list of the dimensions may not be empty."]; Abort[]]; 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp = 
       Join[({#1, #1} & ) /@ 
         FeynCalc`FCLoopBasisCreateScalarProducts`Private`lmoms, 
        Subsets[FeynCalc`FCLoopBasisCreateScalarProducts`Private`lmoms, {2}], 
        Flatten[
         (Thread[{FeynCalc`FCLoopBasisCreateScalarProducts`Private`extmoms, 
             #1}] & ) /@ 
          FeynCalc`FCLoopBasisCreateScalarProducts`Private`lmoms, 1]]; 
      If[Length[FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp] =!= 
        FCLoopBasisGetSize[Length[
          FeynCalc`FCLoopBasisCreateScalarProducts`Private`lmoms], 
         Length[FeynCalc`FCLoopBasisCreateScalarProducts`Private`extmoms]], 
       Message[FCLoopBasisCreateScalarProducts::failmsg, 
         "The number of the obtained scalar products is incorrect."]; 
        Abort[]]; 
      If[ !MatchQ[FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp, 
         {{_, _}..}], Message[FCLoopBasisCreateScalarProducts::failmsg, 
         "The list of the obtained scalar products is incorrect."]; 
        Print[FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp]; 
        Abort[]]; Which[
       FeynCalc`FCLoopBasisCreateScalarProducts`Private`head === Pair, 
       FeynCalc`FCLoopBasisCreateScalarProducts`Private`res = 
        (Pair[Momentum[#1[[1]], 
            FeynCalc`FCLoopBasisCreateScalarProducts`Private`dummyDim], 
           Momentum[#1[[2]], 
            FeynCalc`FCLoopBasisCreateScalarProducts`Private`dummyDim]] & ) \
/@ FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp, 
       FeynCalc`FCLoopBasisCreateScalarProducts`Private`head === 
        CartesianPair, FeynCalc`FCLoopBasisCreateScalarProducts`Private`res = 
        (CartesianPair[CartesianMomentum[#1[[1]], 
            FeynCalc`FCLoopBasisCreateScalarProducts`Private`dummyDim], 
           CartesianMomentum[#1[[2]], 
            FeynCalc`FCLoopBasisCreateScalarProducts`Private`dummyDim]] & ) \
/@ FeynCalc`FCLoopBasisCreateScalarProducts`Private`tmp, True, 
       Message[FCLoopBasisCreateScalarProducts::failmsg, 
         "Unknown scalar product head."]; Abort[]]; 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`repRule = 
       List /@ Thread[
         FeynCalc`FCLoopBasisCreateScalarProducts`Private`dummyDim -> 
          FeynCalc`FCLoopBasisCreateScalarProducts`Private`dims]; 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`res = 
       Flatten[FeynCalc`FCLoopBasisCreateScalarProducts`Private`res /. 
         FeynCalc`FCLoopBasisCreateScalarProducts`Private`repRule]; 
      If[OptionValue[FCE], 
       FeynCalc`FCLoopBasisCreateScalarProducts`Private`res = 
        FCE[FeynCalc`FCLoopBasisCreateScalarProducts`Private`res]]; 
      FeynCalc`FCLoopBasisCreateScalarProducts`Private`res]
 
