     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCFeynmanParameterJoin`Private`fcfpjVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCFeynmanParameterJoin`Private`fcfpjVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCFeynmanParameterJoin`Private`optIndexed = 
       OptionValue[Indexed]; 
      FeynCalc`FCFeynmanParameterJoin`Private`optFactoring = 
       OptionValue[Factoring]; 
      FeynCalc`FCFeynmanParameterJoin`Private`optFinalSubstitutions = 
       OptionValue[FinalSubstitutions]; 
