          {FeynCalc`SharedTools`Private`args}]]; 
       If[Head[FeynCalc`SharedTools`Private`tmp] === Plus, 
        FeynCalc`SharedTools`Private`res = SelectNotFree[
          FeynCalc`SharedTools`Private`tmp, 
