        FeynCalc`SharedTools`Private`res = 
         SelectNotFree[FeynCalc`SharedTools`Private`tmp + 
            FeynCalc`SharedTools`Private`null1 + 
            FeynCalc`SharedTools`Private`null2, 
           FeynCalc`SharedTools`Private`args] /. 
          FeynCalc`SharedTools`Private`null1 | 
            FeynCalc`SharedTools`Private`null2 -> 0]; 
       FeynCalc`SharedTools`Private`res] /; 
     Head[FeynCalc`SharedTools`Private`x] =!= List && 
      FeynCalc`SharedTools`Private`x =!= 0
 
SelectNotFree2 /: SelectNotFree2::usage = "SelectNotFree2[expr, a, b, ...] is \
similar to SelectNotFree but it also\ndiffers from the latter in several \
respects.\n\nIf expr is  a list, SelectNotFree2 behaves exactly the same way \
as\nSelectNotFree.\n\nIf expr is not a list, SelectNotFree2 first expands the \
expression w.r.t. the\narguments via Expand2.\n\nFurthermore, \
SelectNotFree2[a,b] returns 0. This differs from the behavior of\nSelectFree \
but is consistent with the naive expectations when applying the\nfunction to \
a sum of terms."
 
FeynCalc`FCFeynmanPrepare`Private`buildF[
     {FeynCalc`FCFeynmanPrepare`Private`oldSymU_, 
      FeynCalc`FCFeynmanPrepare`Private`oldSymF_}, 
     FeynCalc`FCFeynmanPrepare`Private`lmom_] := 
    Block[{FeynCalc`FCFeynmanPrepare`Private`tmp, 
      FeynCalc`FCFeynmanPrepare`Private`lambda, 
      FeynCalc`FCFeynmanPrepare`Private`J, 
      FeynCalc`FCFeynmanPrepare`Private`num, 
      FeynCalc`FCFeynmanPrepare`Private`res, 
      FeynCalc`FCFeynmanPrepare`Private`time, 
      FeynCalc`FCFeynmanPrepare`Private`time0, 
      FeynCalc`FCFeynmanPrepare`Private`loopMark, 
      FeynCalc`FCFeynmanPrepare`Private`numN, 
      FeynCalc`FCFeynmanPrepare`Private`numD}, 
     FCPrint[3, "FCFeynmanPrepare: buildF: Current loop momentum: ", 
       FeynCalc`FCFeynmanPrepare`Private`lmom, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`time0 = AbsoluteTime[]; 
      FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
      FCPrint[2, "FCFeynmanPrepare: buildF: Extracting lambda.", 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`tmp = 
       FeynCalc`FCFeynmanPrepare`Private`oldSymF /. 
        FeynCalc`FCFeynmanPrepare`Private`x:(Momentum | CartesianMomentum)[
           FeynCalc`FCFeynmanPrepare`Private`lmom, 
           FeynCalc`FCFeynmanPrepare`Private`dim] -> 
         FeynCalc`FCFeynmanPrepare`Private`loopMark*
          FeynCalc`FCFeynmanPrepare`Private`x; 
      FeynCalc`FCFeynmanPrepare`Private`lambda = 
       Coefficient[FeynCalc`FCFeynmanPrepare`Private`tmp, 
         FeynCalc`FCFeynmanPrepare`Private`loopMark, 2] /. 
        {Pair[Momentum[FeynCalc`FCFeynmanPrepare`Private`lmom, 
            FeynCalc`FCFeynmanPrepare`Private`dim], 
           Momentum[FeynCalc`FCFeynmanPrepare`Private`lmom, 
            FeynCalc`FCFeynmanPrepare`Private`dim]] -> 1, 
         CartesianPair[CartesianMomentum[
            FeynCalc`FCFeynmanPrepare`Private`lmom, 
            FeynCalc`FCFeynmanPrepare`Private`dim], CartesianMomentum[
            FeynCalc`FCFeynmanPrepare`Private`lmom, 
            FeynCalc`FCFeynmanPrepare`Private`dim]] -> 1}; 
      FCPrint[2, 
       "FCFeynmanPrepare: buildF: Done extracting lambda, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[3, "FCFeynmanPrepare: buildF: lambda: ", 
       FeynCalc`FCFeynmanPrepare`Private`lambda, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[FeynCalc`FCFeynmanPrepare`Private`lambda === 0, Return[{0, 0}]; ]; 
      FeynCalc`FCFeynmanPrepare`Private`time = AbsoluteTime[]; 
      FCPrint[2, "FCFeynmanPrepare: buildF: Extracting num and J.", 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`num = 
       Together[Coefficient[FeynCalc`FCFeynmanPrepare`Private`tmp, 
         FeynCalc`FCFeynmanPrepare`Private`loopMark, 1]]; 
      {FeynCalc`FCFeynmanPrepare`Private`numN, 
        FeynCalc`FCFeynmanPrepare`Private`numD} = 
       {Numerator[FeynCalc`FCFeynmanPrepare`Private`num], 
        Denominator[FeynCalc`FCFeynmanPrepare`Private`num]}; 
      FeynCalc`FCFeynmanPrepare`Private`numN = 
       Expand2[FeynCalc`FCFeynmanPrepare`Private`numN^2, 
         FeynCalc`FCFeynmanPrepare`Private`lmom] /. 
        {Pair[Momentum[FeynCalc`FCFeynmanPrepare`Private`lmom, 
             FeynCalc`FCFeynmanPrepare`Private`dim], 
            FeynCalc`FCFeynmanPrepare`Private`x_]*
           Pair[Momentum[FeynCalc`FCFeynmanPrepare`Private`lmom, 
             FeynCalc`FCFeynmanPrepare`Private`dim], 
            FeynCalc`FCFeynmanPrepare`Private`y_] :> ExpandScalarProduct[
           Pair[FeynCalc`FCFeynmanPrepare`Private`x, 
            FeynCalc`FCFeynmanPrepare`Private`y], FCI -> True], 
         Pair[Momentum[FeynCalc`FCFeynmanPrepare`Private`lmom, 
             FeynCalc`FCFeynmanPrepare`Private`dim], 
            FeynCalc`FCFeynmanPrepare`Private`x_]^2 :> ExpandScalarProduct[
           Pair[FeynCalc`FCFeynmanPrepare`Private`x, 
            FeynCalc`FCFeynmanPrepare`Private`x], FCI -> True], 
         CartesianPair[CartesianMomentum[
             FeynCalc`FCFeynmanPrepare`Private`lmom, 
             FeynCalc`FCFeynmanPrepare`Private`dim], 
            FeynCalc`FCFeynmanPrepare`Private`x_]*CartesianPair[
            CartesianMomentum[FeynCalc`FCFeynmanPrepare`Private`lmom, 
             FeynCalc`FCFeynmanPrepare`Private`dim], 
            FeynCalc`FCFeynmanPrepare`Private`y_] :> ExpandScalarProduct[
           CartesianPair[FeynCalc`FCFeynmanPrepare`Private`x, 
            FeynCalc`FCFeynmanPrepare`Private`y], FCI -> True], 
         CartesianPair[CartesianMomentum[
             FeynCalc`FCFeynmanPrepare`Private`lmom, 
             FeynCalc`FCFeynmanPrepare`Private`dim], 
            FeynCalc`FCFeynmanPrepare`Private`x_]^2 :> ExpandScalarProduct[
           CartesianPair[FeynCalc`FCFeynmanPrepare`Private`x, 
            FeynCalc`FCFeynmanPrepare`Private`x], FCI -> True]}; 
      FeynCalc`FCFeynmanPrepare`Private`num = 
       FeynCalc`FCFeynmanPrepare`Private`numN/
        FeynCalc`FCFeynmanPrepare`Private`numD^2; 
      FeynCalc`FCFeynmanPrepare`Private`J = Coefficient[
        FeynCalc`FCFeynmanPrepare`Private`tmp, 
        FeynCalc`FCFeynmanPrepare`Private`loopMark, 0]; 
      FCPrint[2, 
       "FCFeynmanPrepare: buildF: Done extracting num and J, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time, 4], 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[3, "FCFeynmanPrepare: buildF: num: ", 
       FeynCalc`FCFeynmanPrepare`Private`num, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FCPrint[3, "FCFeynmanPrepare: buildF: J: ", 
       FeynCalc`FCFeynmanPrepare`Private`J, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`res = 
       {FeynCalc`FCFeynmanPrepare`Private`oldSymU*
         FeynCalc`FCFeynmanPrepare`Private`lambda, 
        Together[FeynCalc`FCFeynmanPrepare`Private`J - 
          FeynCalc`FCFeynmanPrepare`Private`num/
           (4*FeynCalc`FCFeynmanPrepare`Private`lambda)]}; 
      FCPrint[3, "FCFeynmanPrepare: buildF: res: ", 
       FeynCalc`FCFeynmanPrepare`Private`res, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[ !FreeQ2[FeynCalc`FCFeynmanPrepare`Private`res, 
         {FeynCalc`FCFeynmanPrepare`Private`lmom, 
          FeynCalc`FCFeynmanPrepare`Private`loopMark}], 
       Message[FCFeynmanPrepare::failmsg, 
         "buildF failed to eliminate one of the loop momenta."]; Abort[]]; 
      FCPrint[2, "FCFeynmanPrepare: buildF: Total timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCFeynmanPrepare`Private`time0, 4], 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      FeynCalc`FCFeynmanPrepare`Private`res]
 
FeynCalc`FCFeynmanPrepare`Private`buildN[
     FeynCalc`FCFeynmanPrepare`Private`tensorPart_, 
     FeynCalc`FCFeynmanPrepare`Private`U_, 
     FeynCalc`FCFeynmanPrepare`Private`M_, 
     FeynCalc`FCFeynmanPrepare`Private`fpQ_, 
     FeynCalc`FCFeynmanPrepare`Private`powers_, 
     FeynCalc`FCFeynmanPrepare`Private`lmoms_List] := 
    Block[{FeynCalc`FCFeynmanPrepare`Private`tensorList, 
      FeynCalc`FCFeynmanPrepare`Private`null1, 
      FeynCalc`FCFeynmanPrepare`Private`null2, 
      FeynCalc`FCFeynmanPrepare`Private`check, 
      FeynCalc`FCFeynmanPrepare`Private`aIndices, 
      FeynCalc`FCFeynmanPrepare`Private`pIndices, 
      FeynCalc`FCFeynmanPrepare`Private`tildeM, 
      FeynCalc`FCFeynmanPrepare`Private`nM, 
      FeynCalc`FCFeynmanPrepare`Private`nLoops, 
      FeynCalc`FCFeynmanPrepare`Private`tensorListEval, 
      FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefac, 
      FeynCalc`FCFeynmanPrepare`Private`Ar, 
      FeynCalc`FCFeynmanPrepare`Private`Pr, 
      FeynCalc`FCFeynmanPrepare`Private`res, 
      FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacList, 
      FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacListEval}, 
     FeynCalc`FCFeynmanPrepare`Private`tensorList = 
       Sort[List @@ (FeynCalc`FCFeynmanPrepare`Private`tensorPart*
           FeynCalc`FCFeynmanPrepare`Private`null1*
           FeynCalc`FCFeynmanPrepare`Private`null2) /. 
         FeynCalc`FCFeynmanPrepare`Private`null1 | 
           FeynCalc`FCFeynmanPrepare`Private`null2 -> Unevaluated[
           Sequence[]]]; FeynCalc`FCFeynmanPrepare`Private`tensorRank = 
       Length[FeynCalc`FCFeynmanPrepare`Private`tensorList]; 
      FCPrint[3, "FCFeynmanPrepare: buildN: tensorPart as a list: ", 
       FeynCalc`FCFeynmanPrepare`Private`tensorList, 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[ !MatchQ[FeynCalc`FCFeynmanPrepare`Private`tensorList, 
         {(Pair | CartesianPair)[(LorentzIndex | CartesianIndex)[__], 
            (Momentum | CartesianMomentum)[__]]..}], 
       Message[FCFeynmanPrepare::failmsg, 
         "Failed to extract the tensor part of the integral."]; Abort[]]; 
      If[ !SubsetQ[FeynCalc`FCFeynmanPrepare`Private`lmoms, 
         Union[Cases[FeynCalc`FCFeynmanPrepare`Private`tensorList, 
           CartesianMomentum | Momentum[FeynCalc`FCFeynmanPrepare`Private`p_, 
              ___] :> FeynCalc`FCFeynmanPrepare`Private`p, Infinity]]], 
       Message[FCFeynmanPrepare::failmsg, "Only loop momenta with \
uncontracted indices are allowed in the numerator."]; Abort[]]; 
      FeynCalc`FCFeynmanPrepare`Private`tensorList = 
       FeynCalc`FCFeynmanPrepare`Private`tensorList /. 
        {Pair[LorentzIndex[FeynCalc`FCFeynmanPrepare`Private`a_, 
            FeynCalc`FCFeynmanPrepare`Private`dim], 
           Momentum[FeynCalc`FCFeynmanPrepare`Private`p_, 
            FeynCalc`FCFeynmanPrepare`Private`dim]] :> 
          {FeynCalc`FCFeynmanPrepare`Private`a, 
           Position[FeynCalc`FCFeynmanPrepare`Private`lmoms, 
              FeynCalc`FCFeynmanPrepare`Private`p][[1]][[1]]}, 
         CartesianPair[CartesianIndex[FeynCalc`FCFeynmanPrepare`Private`a_, 
            FeynCalc`FCFeynmanPrepare`Private`dim], CartesianMomentum[
            FeynCalc`FCFeynmanPrepare`Private`p_, 
            FeynCalc`FCFeynmanPrepare`Private`dim]] :> 
          {FeynCalc`FCFeynmanPrepare`Private`a, 
           Position[FeynCalc`FCFeynmanPrepare`Private`lmoms, 
              FeynCalc`FCFeynmanPrepare`Private`p][[1]][[1]]}}; 
      FCPrint[3, "FCFeynmanPrepare: buildN: final tensorList: ", 
       FeynCalc`FCFeynmanPrepare`Private`tensorList, 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[ !FeynCalc`FCFeynmanPrepare`Private`isCartesian, 
       FeynCalc`FCFeynmanPrepare`Private`check = 
        (Pair[LorentzIndex[#1[[1]], FeynCalc`FCFeynmanPrepare`Private`dim], 
           Momentum[FeynCalc`FCFeynmanPrepare`Private`lmoms[[#1[[2]]]], 
            FeynCalc`FCFeynmanPrepare`Private`dim]] & ) /@ 
         FeynCalc`FCFeynmanPrepare`Private`tensorList, 
       FeynCalc`FCFeynmanPrepare`Private`check = 
        (CartesianPair[CartesianIndex[#1[[1]], 
            FeynCalc`FCFeynmanPrepare`Private`dim], CartesianMomentum[
            FeynCalc`FCFeynmanPrepare`Private`lmoms[[#1[[2]]]], 
            FeynCalc`FCFeynmanPrepare`Private`dim]] & ) /@ 
         FeynCalc`FCFeynmanPrepare`Private`tensorList]; 
      FCPrint[3, "FCFeynmanPrepare: buildN: check: ", 
       FeynCalc`FCFeynmanPrepare`Private`check, FCDoControl -> 
        FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[FeynCalc`FCFeynmanPrepare`Private`tensorPart =!= 
        Times @@ FeynCalc`FCFeynmanPrepare`Private`check, 
       Message[FCFeynmanPrepare::failmsg, "Failed to rewrite the tensor part \
of the integral in an appropriate way."]; Abort[]]; 
      FeynCalc`FCFeynmanPrepare`Private`aIndices = 
       Subsets[FeynCalc`FCFeynmanPrepare`Private`tensorList, 
        {0, Length[FeynCalc`FCFeynmanPrepare`Private`tensorList], 2}]; 
      FeynCalc`FCFeynmanPrepare`Private`pIndices = 
       (Complement[FeynCalc`FCFeynmanPrepare`Private`tensorList, #1] & ) /@ 
        FeynCalc`FCFeynmanPrepare`Private`aIndices; 
      FeynCalc`FCFeynmanPrepare`Private`tildeM = 
       Factor[FeynCalc`FCFeynmanPrepare`Private`U*
         Inverse[FeynCalc`FCFeynmanPrepare`Private`M]]; 
      FeynCalc`FCFeynmanPrepare`Private`nM = 
       Total[Last[Transpose[FeynCalc`FCFeynmanPrepare`Private`powers]]]; 
      FeynCalc`FCFeynmanPrepare`Private`nLoops = 
       Length[FeynCalc`FCFeynmanPrepare`Private`lmoms]; 
      FeynCalc`FCFeynmanPrepare`Private`tensorListEval = 
       MapThread[FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefac[
           Length[#1]/2]*FeynCalc`FCFeynmanPrepare`Private`Ar @@ #1*
          FeynCalc`FCFeynmanPrepare`Private`Pr @@ #2 & , 
        {FeynCalc`FCFeynmanPrepare`Private`aIndices, 
         FeynCalc`FCFeynmanPrepare`Private`pIndices}]; 
      FeynCalc`FCFeynmanPrepare`Private`tensorListEval = 
       FeynCalc`FCFeynmanPrepare`Private`tensorListEval /. 
        {FeynCalc`FCFeynmanPrepare`Private`Ar -> 
          FeynCalc`FCFeynmanPrepare`Private`evalAr, 
         FeynCalc`FCFeynmanPrepare`Private`Pr -> 
          FeynCalc`FCFeynmanPrepare`Private`evalPr}; 
      If[ !FeynCalc`FCFeynmanPrepare`Private`isCartesian, 
       FeynCalc`FCFeynmanPrepare`Private`tensorListEval = 
        FeynCalc`FCFeynmanPrepare`Private`tensorListEval /. 
         {FeynCalc`FCFeynmanPrepare`Private`Gt -> 
           FeynCalc`FCFeynmanPrepare`Private`evalGt[
            FeynCalc`FCFeynmanPrepare`Private`tildeM, Pair, LorentzIndex], 
          FeynCalc`FCFeynmanPrepare`Private`Pt -> 
           FeynCalc`FCFeynmanPrepare`Private`evalPt[
            FeynCalc`FCFeynmanPrepare`Private`nLoops, 
            FeynCalc`FCFeynmanPrepare`Private`li, 
            FeynCalc`FCFeynmanPrepare`Private`fpQ, 
            FeynCalc`FCFeynmanPrepare`Private`tildeM]}, 
       FeynCalc`FCFeynmanPrepare`Private`tensorListEval = 
        FeynCalc`FCFeynmanPrepare`Private`tensorListEval /. 
         {FeynCalc`FCFeynmanPrepare`Private`Gt -> 
           FeynCalc`FCFeynmanPrepare`Private`evalGt[
            FeynCalc`FCFeynmanPrepare`Private`tildeM, CartesianPair, 
            CartesianIndex], FeynCalc`FCFeynmanPrepare`Private`Pt -> 
           FeynCalc`FCFeynmanPrepare`Private`evalPt[
            FeynCalc`FCFeynmanPrepare`Private`nLoops, 
            FeynCalc`FCFeynmanPrepare`Private`ci, 
            FeynCalc`FCFeynmanPrepare`Private`fpQ, 
            FeynCalc`FCFeynmanPrepare`Private`tildeM]}]; 
      FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacList = 
       Cases2[FeynCalc`FCFeynmanPrepare`Private`tensorListEval, 
        FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefac]; 
      If[ !FeynCalc`FCFeynmanPrepare`Private`isCartesian && 
         !FeynCalc`FCFeynmanPrepare`Private`optEuclidean, 
       FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacListEval = 
        FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacList /. 
         FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefac[
           FeynCalc`FCFeynmanPrepare`Private`m_Integer] :> 
          (-2^(-1))^FeynCalc`FCFeynmanPrepare`Private`m*
           FCGV["F"]^FeynCalc`FCFeynmanPrepare`Private`m*
           Gamma[FeynCalc`FCFeynmanPrepare`Private`nM - 
             FeynCalc`FCFeynmanPrepare`Private`nLoops*
              (FeynCalc`FCFeynmanPrepare`Private`dim/2) - 
             FeynCalc`FCFeynmanPrepare`Private`m], 
       FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacListEval = 
        FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacList /. 
         FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefac[
           FeynCalc`FCFeynmanPrepare`Private`m_Integer] :> 
          (1/2)^FeynCalc`FCFeynmanPrepare`Private`m*FCGV["F"]^
            FeynCalc`FCFeynmanPrepare`Private`m*
           Gamma[FeynCalc`FCFeynmanPrepare`Private`nM - 
             FeynCalc`FCFeynmanPrepare`Private`nLoops*
              (FeynCalc`FCFeynmanPrepare`Private`dim/2) - 
             FeynCalc`FCFeynmanPrepare`Private`m]]; 
      FeynCalc`FCFeynmanPrepare`Private`tensorListEval = 
       FeynCalc`FCFeynmanPrepare`Private`tensorListEval /. 
        Dispatch[Thread[FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacLis\
t -> FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefacListEval]]; 
      FCPrint[3, "FCFeynmanPrepare: buildN: tensorListEval: ", 
       FeynCalc`FCFeynmanPrepare`Private`tensorListEval, 
       FCDoControl -> FeynCalc`FCFeynmanPrepare`Private`fcszVerbose]; 
      If[ !FreeQ2[FeynCalc`FCFeynmanPrepare`Private`tensorListEval, 
         {FeynCalc`FCFeynmanPrepare`Private`Ar, 
          FeynCalc`FCFeynmanPrepare`Private`Pr, 
          FeynCalc`FCFeynmanPrepare`Private`Gt, 
          FeynCalc`FCFeynmanPrepare`Private`Pt, 
          FeynCalc`FCFeynmanPrepare`Private`evalGt, 
          FeynCalc`FCFeynmanPrepare`Private`evalPt, 
          FeynCalc`FCFeynmanPrepare`Private`evalAr, 
          FeynCalc`FCFeynmanPrepare`Private`evalPr, 
          FeynCalc`FCFeynmanPrepare`Private`tensorTermPrefac}], 
       Message[FCFeynmanPrepare::failmsg, 
         "buildN failed to build the correct N-term."]; Abort[]]; 
      FeynCalc`FCFeynmanPrepare`Private`res = 
       Total[FeynCalc`FCFeynmanPrepare`Private`tensorListEval]; 
      FeynCalc`FCFeynmanPrepare`Private`res]
 
FeynCalc`FCFeynmanPrepare`Private`evalAr[] = 1
 
FeynCalc`FCFeynmanPrepare`Private`evalAr[
     FeynCalc`FCFeynmanPrepare`Private`inds__] := 
    Times @@ FeynCalc`FCFeynmanPrepare`Private`Gt /@ 
       Partition[{FeynCalc`FCFeynmanPrepare`Private`inds}, 2] /; 
     EvenQ[Length[{FeynCalc`FCFeynmanPrepare`Private`inds}]]
 
FeynCalc`FCFeynmanPrepare`Private`Gt /: 
    FeynCalc`FCFeynmanPrepare`Private`Gt::usage = ""
 
FeynCalc`FCFeynmanPrepare`Private`evalPr[] = 1
 
FeynCalc`FCFeynmanPrepare`Private`evalPr[
     FeynCalc`FCFeynmanPrepare`Private`inds__] := 
    Times @@ FeynCalc`FCFeynmanPrepare`Private`Pt /@ 
      {FeynCalc`FCFeynmanPrepare`Private`inds}
 
FeynCalc`FCFeynmanPrepare`Private`Pt /: 
    FeynCalc`FCFeynmanPrepare`Private`Pt::usage = ""
 
FeynCalc`FCFeynmanPrepare`Private`evalGt[
      FeynCalc`FCFeynmanPrepare`Private`tildeM_, 
      FeynCalc`FCFeynmanPrepare`Private`pairHead_, 
      FeynCalc`FCFeynmanPrepare`Private`indexHead_][
     {{FeynCalc`FCFeynmanPrepare`Private`ind1_, 
       (FeynCalc`FCFeynmanPrepare`Private`li1_Integer)?Positive}, 
      {FeynCalc`FCFeynmanPrepare`Private`ind2_, 
       (FeynCalc`FCFeynmanPrepare`Private`li2_Integer)?Positive}}] := 
    FeynCalc`FCFeynmanPrepare`Private`tildeM[
        FeynCalc`FCFeynmanPrepare`Private`li1][
       FeynCalc`FCFeynmanPrepare`Private`li2]*
      FeynCalc`FCFeynmanPrepare`Private`pairHead[
       FeynCalc`FCFeynmanPrepare`Private`indexHead[
        FeynCalc`FCFeynmanPrepare`Private`ind1, 
        FeynCalc`FCFeynmanPrepare`Private`dim], 
       FeynCalc`FCFeynmanPrepare`Private`indexHead[
        FeynCalc`FCFeynmanPrepare`Private`ind2, 
        FeynCalc`FCFeynmanPrepare`Private`dim]] /; 
      !MatrixQ[FeynCalc`FCFeynmanPrepare`Private`tildeM]
 
FeynCalc`FCFeynmanPrepare`Private`evalGt[
      FeynCalc`FCFeynmanPrepare`Private`tildeM_, 
      FeynCalc`FCFeynmanPrepare`Private`pairHead_, 
      FeynCalc`FCFeynmanPrepare`Private`indexHead_][
     {{FeynCalc`FCFeynmanPrepare`Private`ind1_, 
       (FeynCalc`FCFeynmanPrepare`Private`li1_Integer)?Positive}, 
      {FeynCalc`FCFeynmanPrepare`Private`ind2_, 
       (FeynCalc`FCFeynmanPrepare`Private`li2_Integer)?Positive}}] := 
    FeynCalc`FCFeynmanPrepare`Private`tildeM[[
        FeynCalc`FCFeynmanPrepare`Private`li1]][[
       FeynCalc`FCFeynmanPrepare`Private`li2]]*
      FeynCalc`FCFeynmanPrepare`Private`pairHead[
       FeynCalc`FCFeynmanPrepare`Private`indexHead[
        FeynCalc`FCFeynmanPrepare`Private`ind1, 
        FeynCalc`FCFeynmanPrepare`Private`dim], 
       FeynCalc`FCFeynmanPrepare`Private`indexHead[
        FeynCalc`FCFeynmanPrepare`Private`ind2, 
        FeynCalc`FCFeynmanPrepare`Private`dim]] /; 
     MatrixQ[FeynCalc`FCFeynmanPrepare`Private`tildeM]
 
FeynCalc`FCFeynmanPrepare`Private`evalPt[
      FeynCalc`FCFeynmanPrepare`Private`nLoops_Integer, 
      FeynCalc`FCFeynmanPrepare`Private`lci_, 
      FeynCalc`FCFeynmanPrepare`Private`fpQ_, 
      FeynCalc`FCFeynmanPrepare`Private`tildeM_][
     {FeynCalc`FCFeynmanPrepare`Private`ind1_, 
      (FeynCalc`FCFeynmanPrepare`Private`li1_Integer)?Positive}] := 
    (Sum[FeynCalc`FCFeynmanPrepare`Private`tildeM[
          FeynCalc`FCFeynmanPrepare`Private`li1][
         FeynCalc`FCFeynmanPrepare`Private`i]*
        FeynCalc`FCFeynmanPrepare`Private`fpQ[[
         FeynCalc`FCFeynmanPrepare`Private`i]], 
       {FeynCalc`FCFeynmanPrepare`Private`i, 1, 
        FeynCalc`FCFeynmanPrepare`Private`nLoops}] /. 
      FeynCalc`FCFeynmanPrepare`Private`lci -> 
       FeynCalc`FCFeynmanPrepare`Private`ind1) /; 
      !MatrixQ[FeynCalc`FCFeynmanPrepare`Private`tildeM]
 
FeynCalc`FCFeynmanPrepare`Private`evalPt[
      FeynCalc`FCFeynmanPrepare`Private`nLoops_Integer, 
      FeynCalc`FCFeynmanPrepare`Private`lci_, 
      FeynCalc`FCFeynmanPrepare`Private`fpQ_, 
      FeynCalc`FCFeynmanPrepare`Private`tildeM_][
     {FeynCalc`FCFeynmanPrepare`Private`ind1_, 
      (FeynCalc`FCFeynmanPrepare`Private`li1_Integer)?Positive}] := 
    (Sum[FeynCalc`FCFeynmanPrepare`Private`tildeM[[
          FeynCalc`FCFeynmanPrepare`Private`li1]][[
         FeynCalc`FCFeynmanPrepare`Private`i]]*
        FeynCalc`FCFeynmanPrepare`Private`fpQ[[
         FeynCalc`FCFeynmanPrepare`Private`i]], 
       {FeynCalc`FCFeynmanPrepare`Private`i, 1, 
        FeynCalc`FCFeynmanPrepare`Private`nLoops}] /. 
      FeynCalc`FCFeynmanPrepare`Private`lci -> 
       FeynCalc`FCFeynmanPrepare`Private`ind1) /; 
     MatrixQ[FeynCalc`FCFeynmanPrepare`Private`tildeM]
 
FCLoopPakScalelessQ[0, _, OptionsPattern[]] := True
 
FCLoopPakScalelessQ[FeynCalc`FCLoopPakScalelessQ`Private`poly_ /; 
      FeynCalc`FCLoopPakScalelessQ`Private`poly =!= 0, 
     FeynCalc`FCLoopPakScalelessQ`Private`var_, OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopPakScalelessQ`Private`xVars, 
      FeynCalc`FCLoopPakScalelessQ`Private`res, 
      FeynCalc`FCLoopPakScalelessQ`Private`time, 
      FeynCalc`FCLoopPakScalelessQ`Private`coeffsList, 
      FeynCalc`FCLoopPakScalelessQ`Private`rank, 
      FeynCalc`FCLoopPakScalelessQ`Private`vecs, 
      FeynCalc`FCLoopPakScalelessQ`Private`mat, 
      FeynCalc`FCLoopPakScalelessQ`Private`polyMasked, 
      FeynCalc`FCLoopPakScalelessQ`Private`allVars, 
      FeynCalc`FCLoopPakScalelessQ`Private`expVars, 
      FeynCalc`FCLoopPakScalelessQ`Private`kinVars, 
      FeynCalc`FCLoopPakScalelessQ`Private`pow, 
      FeynCalc`FCLoopPakScalelessQ`Private`optRandomPrime, 
      FeynCalc`FCLoopPakScalelessQ`Private`kinVarsNum, 
      FeynCalc`FCLoopPakScalelessQ`Private`cru}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCLoopPakScalelessQ`Private`optRandomPrime = 
       OptionValue[RandomPrime]; 
      If[FeynCalc`FCLoopPakScalelessQ`Private`poly === 0, Return[True]]; 
      FCPrint[1, "FCLoopPakScalelessQ: Entering.", FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FCPrint[3, "FCLoopPakScalelessQ: Entering with: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`poly, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      Which[Head[FeynCalc`FCLoopPakScalelessQ`Private`var] === Symbol, 
       FeynCalc`FCLoopPakScalelessQ`Private`xVars = 
        Cases2[FeynCalc`FCLoopPakScalelessQ`Private`poly, 
         FeynCalc`FCLoopPakScalelessQ`Private`var], 
       Head[FeynCalc`FCLoopPakScalelessQ`Private`var] === List, 
       FeynCalc`FCLoopPakScalelessQ`Private`xVars = 
        FeynCalc`FCLoopPakScalelessQ`Private`var, True, 
       Message[FCLoopPakScalelessQ::failmsg, 
         "Unknowns format of the second argument"]; Abort[]]; 
      FeynCalc`FCLoopPakScalelessQ`Private`allVars = 
       Variables2[FeynCalc`FCLoopPakScalelessQ`Private`poly]; 
      FeynCalc`FCLoopPakScalelessQ`Private`expVars = 
       Variables2[Cases[FeynCalc`FCLoopPakScalelessQ`Private`poly /. 
          Power -> FeynCalc`FCLoopPakScalelessQ`Private`pow, 
         FeynCalc`FCLoopPakScalelessQ`Private`pow[_, 
           FeynCalc`FCLoopPakScalelessQ`Private`x_] :> 
          FeynCalc`FCLoopPakScalelessQ`Private`x, Infinity]]; 
      FeynCalc`FCLoopPakScalelessQ`Private`kinVars = 
       Complement[FeynCalc`FCLoopPakScalelessQ`Private`allVars, 
        FeynCalc`FCLoopPakScalelessQ`Private`xVars, 
        FeynCalc`FCLoopPakScalelessQ`Private`expVars]; 
      FCPrint[2, 
       "FCLoopPakScalelessQ: All variables present in the expression: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`allVars, 
       FCDoControl -> FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FCPrint[1, "FCLoopPakScalelessQ: Feynman parameter variables: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`xVars, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FCPrint[1, "FCLoopPakScalelessQ: Variables appearing in the exponents: \
", FeynCalc`FCLoopPakScalelessQ`Private`expVars, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FCPrint[1, "FCLoopPakScalelessQ: Kinematic variables: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`kinVars, 
       FCDoControl -> FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FeynCalc`FCLoopPakScalelessQ`Private`kinVarsNum = 
       Table[RandomPrime[
         FeynCalc`FCLoopPakScalelessQ`Private`optRandomPrime], 
        {FeynCalc`FCLoopPakScalelessQ`Private`i, 1, 
         Length[FeynCalc`FCLoopPakScalelessQ`Private`kinVars]}]; 
      FeynCalc`FCLoopPakScalelessQ`Private`cru = 
       Thread[FeynCalc`FCLoopPakScalelessQ`Private`kinVars -> 
         FeynCalc`FCLoopPakScalelessQ`Private`kinVarsNum]; 
      FCPrint[3, 
       "FCLoopPakScalelessQ: Replacement rule for the kinematic variables: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`cru, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FeynCalc`FCLoopPakScalelessQ`Private`polyMasked = 
       FeynCalc`FCLoopPakScalelessQ`Private`poly /. 
        Dispatch[FeynCalc`FCLoopPakScalelessQ`Private`cru]; 
      FCPrint[3, "FCLoopPakScalelessQ: Characteristic polynomal after masking \
kinematic variables: ", FeynCalc`FCLoopPakScalelessQ`Private`polyMasked, 
       FCDoControl -> FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FeynCalc`FCLoopPakScalelessQ`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopPakScalelessQ: Calculating coefficient lists.", 
       FCDoControl -> FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FeynCalc`FCLoopPakScalelessQ`Private`coeffsList = 
       GroebnerBasis`DistributedTermsList[
        FeynCalc`FCLoopPakScalelessQ`Private`polyMasked, 
        FeynCalc`FCLoopPakScalelessQ`Private`xVars]; 
      FCPrint[1, 
       "FCLoopPakScalelessQ: Done calculating coefficient lists, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopPakScalelessQ`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FCPrint[3, "FCLoopPakScalelessQ: coeffsList: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`coeffsList, 
       FCDoControl -> FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      If[FeynCalc`FCLoopPakScalelessQ`Private`coeffsList[[2]] =!= 
        FeynCalc`FCLoopPakScalelessQ`Private`xVars, 
       Message[FCLoopPakScalelessQ::failmsg, 
         "Incorrect polynomial variables."]; Abort[]]; 
      If[ !MatchQ[Last /@ FeynCalc`FCLoopPakScalelessQ`Private`coeffsList[[
           1]], {__?NumberQ}], Message[FCLoopPakScalelessQ::failmsg, 
         "Vector coefficients are not numerical."]; ]; 
      FeynCalc`FCLoopPakScalelessQ`Private`vecs = 
       First /@ FeynCalc`FCLoopPakScalelessQ`Private`coeffsList[[1]]; 
      If[TrueQ[Length[FeynCalc`FCLoopPakScalelessQ`Private`vecs] > 1], 
       FeynCalc`FCLoopPakScalelessQ`Private`mat = 
        (First[FeynCalc`FCLoopPakScalelessQ`Private`vecs] - #1 & ) /@ 
         Rest[FeynCalc`FCLoopPakScalelessQ`Private`vecs], 
       FeynCalc`FCLoopPakScalelessQ`Private`mat = {{0}}]; 
      If[ !MatrixQ[FeynCalc`FCLoopPakScalelessQ`Private`mat], 
       Message[FCLoopPakScalelessQ::failmsg, 
         "Failed to build up the matrix."]; Abort[]]; 
      FCPrint[3, "FCLoopPakScalelessQ: Matrix: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`mat, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FeynCalc`FCLoopPakScalelessQ`Private`rank = 
       MatrixRank[FeynCalc`FCLoopPakScalelessQ`Private`mat]; 
      FCPrint[2, "FCLoopPakScalelessQ: Matrix rank: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`rank, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      If[FeynCalc`FCLoopPakScalelessQ`Private`rank > 
        Length[FeynCalc`FCLoopPakScalelessQ`Private`xVars] - 1, 
       Message[FCLoopPakScalelessQ::failmsg, 
         "The determined matrix rank is incorrect."]; Abort[]]; 
      FeynCalc`FCLoopPakScalelessQ`Private`res = 
       FeynCalc`FCLoopPakScalelessQ`Private`rank < 
        Length[FeynCalc`FCLoopPakScalelessQ`Private`xVars] - 1; 
      FCPrint[1, "FCLoopPakScalelessQ: Leaving.", FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FCPrint[3, "FCLoopPakScalelessQ: Leaving with: ", 
       FeynCalc`FCLoopPakScalelessQ`Private`res, FCDoControl -> 
        FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose]; 
      FeynCalc`FCLoopPakScalelessQ`Private`res]
 
Options[FCLoopPakScalelessQ] = {FCVerbose -> False, RandomPrime -> 100000000}
 
FCLoopPakScalelessQ /: FCLoopPakScalelessQ::failmsg = "Error! \
FCLoopPakScalelessQ has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCLoopPakScalelessQ /: FCLoopPakScalelessQ::usage = "FCLoopPakScalelessQ[poly\
, x] checks whether the characteristic polynomial poly\n(in the $U \\times \
xF$ form) with the Feynman parameters x[1], x[2], ...\ncorresponds to a \
scaleless loop integral or loop integral topology. The\npolynomial does not \
need to be canonically ordered.\n\nThe function uses the algorithm of Alexey \
Pak\n[arXiv:1111.0868](https://arxiv.org/abs/1111.0868). Cf. also the PhD \
thesis of\nJens Hoff \
[10.5445/IR/1000047447](https://doi.org/10.5445/IR/1000047447) for\nthe \
detailed description of a possible implementation. FCLoopPakScalelessQ  is\na \
backend function used in FCLoopScalelessQ, FCLoopFindSubtopologies etc."
 
FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose = 0
 
FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose /: 
    FeynCalc`FCLoopPakScalelessQ`Private`fcpsVerbose::usage = ""
 
FCFeynmanParametrize[FeynCalc`FCFeynmanParametrize`Private`expr_, 
     FeynCalc`FCFeynmanParametrize`Private`topo_FCTopology, 
     FeynCalc`FCFeynmanParametrize`Private`opts:OptionsPattern[]] := 
    FCFeynmanParametrize[FeynCalc`FCFeynmanParametrize`Private`expr, 1, 
     {FeynCalc`FCFeynmanParametrize`Private`topo}, 
     FeynCalc`FCFeynmanParametrize`Private`opts]
 
FCFeynmanParametrize[FeynCalc`FCFeynmanParametrize`Private`expr_, 
     FeynCalc`FCFeynmanParametrize`Private`lmoms_List /; 
       !OptionQ[FeynCalc`FCFeynmanParametrize`Private`lmoms], 
     FeynCalc`FCFeynmanParametrize`Private`opts:OptionsPattern[]] := 
    FCFeynmanParametrize[FeynCalc`FCFeynmanParametrize`Private`expr, 1, 
     FeynCalc`FCFeynmanParametrize`Private`lmoms, 
     FeynCalc`FCFeynmanParametrize`Private`opts]
 
FCFeynmanParametrize[FeynCalc`FCFeynmanParametrize`Private`expr_, 
     FeynCalc`FCFeynmanParametrize`Private`extra_ /; 
      Head[FeynCalc`FCFeynmanParametrize`Private`extra] =!= List, 
     FeynCalc`FCFeynmanParametrize`Private`lmomsRaw_List /; 
       !OptionQ[FeynCalc`FCFeynmanParametrize`Private`lmomsRaw], 
     OptionsPattern[]] := Block[{FeynCalc`FCFeynmanParametrize`Private`res, 
      FeynCalc`FCFeynmanParametrize`Private`optFinalSubstitutions, 
      FeynCalc`FCFeynmanParametrize`Private`dim, 
      FeynCalc`FCFeynmanParametrize`Private`uPoly, 
      FeynCalc`FCFeynmanParametrize`Private`fPoly, 
      FeynCalc`FCFeynmanParametrize`Private`pows, 
      FeynCalc`FCFeynmanParametrize`Private`mat, 
      FeynCalc`FCFeynmanParametrize`Private`powsT, 
      FeynCalc`FCFeynmanParametrize`Private`propPowers, 
      FeynCalc`FCFeynmanParametrize`Private`lmoms, 
      FeynCalc`FCFeynmanParametrize`Private`propPowersHat, 
      FeynCalc`FCFeynmanParametrize`Private`propPowersTilde, 
      FeynCalc`FCFeynmanParametrize`Private`ppSymbols, 
      FeynCalc`FCFeynmanParametrize`Private`ppSymbolsRule, 
      FeynCalc`FCFeynmanParametrize`Private`optIndexed, 
      FeynCalc`FCFeynmanParametrize`Private`denPowers, 
      FeynCalc`FCFeynmanParametrize`Private`zeroPowerProps, 
      FeynCalc`FCFeynmanParametrize`Private`numPowers, 
      FeynCalc`FCFeynmanParametrize`Private`numVars, 
      FeynCalc`FCFeynmanParametrize`Private`zeroDenVars, 
      FeynCalc`FCFeynmanParametrize`Private`optFCReplaceMomenta, 
      FeynCalc`FCFeynmanParametrize`Private`nM, 
      FeynCalc`FCFeynmanParametrize`Private`nLoops, 
      FeynCalc`FCFeynmanParametrize`Private`fPow, 
      FeynCalc`FCFeynmanParametrize`Private`pref, 
      FeynCalc`FCFeynmanParametrize`Private`fpInt, 
      FeynCalc`FCFeynmanParametrize`Private`fpPref, 
      FeynCalc`FCFeynmanParametrize`Private`optFCReplaceD, 
      FeynCalc`FCFeynmanParametrize`Private`vars, 
      FeynCalc`FCFeynmanParametrize`Private`optVariables, 
      FeynCalc`FCFeynmanParametrize`Private`optExtraPropagators, 
      FeynCalc`FCFeynmanParametrize`Private`aux, 
      FeynCalc`FCFeynmanParametrize`Private`ex, 
      FeynCalc`FCFeynmanParametrize`Private`Q, 
      FeynCalc`FCFeynmanParametrize`Private`J, 
      FeynCalc`FCFeynmanParametrize`Private`tensorPart, 
      FeynCalc`FCFeynmanParametrize`Private`tensorRank, 
      FeynCalc`FCFeynmanParametrize`Private`optMethod, 
      FeynCalc`FCFeynmanParametrize`Private`extraPref, 
      FeynCalc`FCFeynmanParametrize`Private`optFeynmanIntegralPrefactor, 
      FeynCalc`FCFeynmanParametrize`Private`optEuclidean, 
      FeynCalc`FCFeynmanParametrize`Private`inverseMeasure, 
      FeynCalc`FCFeynmanParametrize`Private`optNames, 
      FeynCalc`FCFeynmanParametrize`Private`outputFCFeynmanPrepare, 
      FeynCalc`FCFeynmanParametrize`Private`isCartesian, 
      FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
      FeynCalc`FCFeynmanParametrize`Private`optHead, 
      FeynCalc`FCFeynmanParametrize`Private`fPolyHead, 
      FeynCalc`FCFeynmanParametrize`Private`uPolyHead}, 
     FeynCalc`FCFeynmanParametrize`Private`optFinalSubstitutions = 
       OptionValue[FinalSubstitutions]; 
      FeynCalc`FCFeynmanParametrize`Private`optFCReplaceD = 
       OptionValue[FCReplaceD]; 
      FeynCalc`FCFeynmanParametrize`Private`optVariables = 
       OptionValue[Variables]; 
      FeynCalc`FCFeynmanParametrize`Private`optMethod = OptionValue[Method]; 
      FeynCalc`FCFeynmanParametrize`Private`optFeynmanIntegralPrefactor = 
       OptionValue[FeynmanIntegralPrefactor]; 
      FeynCalc`FCFeynmanParametrize`Private`optEuclidean = 
       OptionValue["Euclidean"]; 
      FeynCalc`FCFeynmanParametrize`Private`optNames = OptionValue[Names]; 
      FeynCalc`FCFeynmanParametrize`Private`optIndexed = 
       OptionValue[Indexed]; 
      FeynCalc`FCFeynmanParametrize`Private`optExtraPropagators = 
       OptionValue[ExtraPropagators]; 
      FeynCalc`FCFeynmanParametrize`Private`optFCReplaceMomenta = 
       OptionValue[FCReplaceMomenta]; 
      FeynCalc`FCFeynmanParametrize`Private`optHead = OptionValue[Head]; 
      {FeynCalc`FCFeynmanParametrize`Private`uPolyHead, 
        FeynCalc`FCFeynmanParametrize`Private`fPolyHead} = 
       FeynCalc`FCFeynmanParametrize`Private`optHead; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose = 
          OptionValue[FCVerbose]]; ]; If[OptionValue[FCI], 
       {FeynCalc`FCFeynmanParametrize`Private`ex, 
         FeynCalc`FCFeynmanParametrize`Private`lmoms} = 
        {FeynCalc`FCFeynmanParametrize`Private`expr, 
         FeynCalc`FCFeynmanParametrize`Private`lmomsRaw}, 
       {FeynCalc`FCFeynmanParametrize`Private`ex, 
         FeynCalc`FCFeynmanParametrize`Private`optFinalSubstitutions, 
         FeynCalc`FCFeynmanParametrize`Private`lmoms} = 
        FCI[{FeynCalc`FCFeynmanParametrize`Private`expr, 
          FeynCalc`FCFeynmanParametrize`Private`optFinalSubstitutions, 
          FeynCalc`FCFeynmanParametrize`Private`lmomsRaw}]]; 
      If[FreeQ[FeynCalc`FCFeynmanParametrize`Private`ex, GLI], 
       FeynCalc`FCFeynmanParametrize`Private`cartesianCheck = 
        FeynCalc`FCFeynmanParametrize`Private`ex, 
       FeynCalc`FCFeynmanParametrize`Private`cartesianCheck = 
        FCLoopSelectTopology[FeynCalc`FCFeynmanParametrize`Private`ex, 
         FeynCalc`FCFeynmanParametrize`Private`lmoms]]; 
      Which[ !FreeQ[FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
          Momentum] && FreeQ[
         FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
         CartesianMomentum], 
       FeynCalc`FCFeynmanParametrize`Private`isCartesian = False, 
       FreeQ[FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
         Momentum] && 
         !FreeQ[FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
          CartesianMomentum], 
       FeynCalc`FCFeynmanParametrize`Private`isCartesian = True, 
        !FreeQ[FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
          Momentum] && 
         !FreeQ[FeynCalc`FCFeynmanParametrize`Private`cartesianCheck, 
          CartesianMomentum], Message[FCFeynmanParametrize::failmsg, "Integra\
ls that simultaneously depend on Lorentz and Cartesian vectors are not \
supported."]; Abort[]]; 
      If[FeynCalc`FCFeynmanParametrize`Private`optVariables =!= {}, 
       If[IntersectingQ[FeynCalc`FCFeynmanParametrize`Private`optVariables, 
         Flatten[{FCMakeSymbols[
            FeynCalc`FCFeynmanParametrize`Private`optNames, Range[1, 20], 
            List], Table[FeynCalc`FCFeynmanParametrize`Private`optNames[
             FeynCalc`FCFeynmanParametrize`Private`i], 
            {FeynCalc`FCFeynmanParametrize`Private`i, 1, 20}]}]], 
        Message[FCFeynmanParametrize::failmsg, StringJoin[
           "Names of Feynman parameters to be introduced cannot be present", 
           " in the list submitted via the Variables option."]]; Abort[]]]; 
      If[ !MemberQ[{True, False}, 
         FeynCalc`FCFeynmanParametrize`Private`isCartesian], 
       Message[FCFeynmanParametrize::failmsg, 
         "Failed to determine whether the integral is Lorentzian or \
Cartesian."]; Abort[]]; 
      If[TrueQ[Head[FeynCalc`FCFeynmanParametrize`Private`ex] =!= List], 
       {FeynCalc`FCFeynmanParametrize`Private`extraPref, 
         FeynCalc`FCFeynmanParametrize`Private`ex} = FCProductSplit[
         FeynCalc`FCFeynmanParametrize`Private`ex, 
         Join[{FeynCalc`FCFeynmanParametrize`Private`lmoms}, 
          {FeynAmpDenominator, Pair, CartesianPair, GLI}]], 
       FeynCalc`FCFeynmanParametrize`Private`extraPref = 1]; 
      FCPrint[1, "FCFeynmanParametrize: Prefactor in the input: ", 
       FeynCalc`FCFeynmanParametrize`Private`extraPref, 
       FCDoControl -> FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
      If[FreeQ[FeynCalc`FCFeynmanParametrize`Private`ex, GLI], 
       FeynCalc`FCFeynmanParametrize`Private`dim = FCGetDimensions[
         FeynCalc`FCFeynmanParametrize`Private`ex /. 
          {TemporalPair[_, ExplicitLorentzIndex[0]] :> Unique[]}], 
       FeynCalc`FCFeynmanParametrize`Private`dim = FCGetDimensions[
         FCLoopSelectTopology[FeynCalc`FCFeynmanParametrize`Private`ex, 
           FeynCalc`FCFeynmanParametrize`Private`lmoms] /. 
          {TemporalPair[_, ExplicitLorentzIndex[0]] :> Unique[]}]]; 
      If[Length[FeynCalc`FCFeynmanParametrize`Private`dim] =!= 1, 
       Message[FCFeynmanParametrize::failmsg, StringJoin[
          "The loop integrals contains momenta in different dimensions: ", 
          ToString[FeynCalc`FCFeynmanParametrize`Private`dim, InputForm]]]; 
        Abort[]]; FeynCalc`FCFeynmanParametrize`Private`dim = 
       First[FeynCalc`FCFeynmanParametrize`Private`dim]; 
      FCPrint[1, "FCFeynmanParametrize: Dimension: ", 
       FeynCalc`FCFeynmanParametrize`Private`dim, FCDoControl -> 
        FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
      FCPrint[1, "FCFeynmanParametrize: Calling FCFeynmanPrepare.", 
       FCDoControl -> FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
      {FeynCalc`FCFeynmanParametrize`Private`uPoly, 
        FeynCalc`FCFeynmanParametrize`Private`fPoly, 
        FeynCalc`FCFeynmanParametrize`Private`pows, 
        FeynCalc`FCFeynmanParametrize`Private`mat, 
        FeynCalc`FCFeynmanParametrize`Private`Q, 
        FeynCalc`FCFeynmanParametrize`Private`J, 
        FeynCalc`FCFeynmanParametrize`Private`tensorPart, 
        FeynCalc`FCFeynmanParametrize`Private`tensorRank} = 
       FCFeynmanPrepare[FeynCalc`FCFeynmanParametrize`Private`ex, 
        FeynCalc`FCFeynmanParametrize`Private`lmoms, FCI -> True, 
        FinalSubstitutions -> 
         FeynCalc`FCFeynmanParametrize`Private`optFinalSubstitutions, 
        Names -> FeynCalc`FCFeynmanParametrize`Private`optNames, 
        Indexed -> OptionValue[Indexed], Reduce -> OptionValue[Reduce], 
        "Euclidean" -> FeynCalc`FCFeynmanParametrize`Private`optEuclidean, 
        EtaSign -> OptionValue[EtaSign], ExtraPropagators -> 
         FeynCalc`FCFeynmanParametrize`Private`optExtraPropagators, 
        FCReplaceMomenta -> 
         FeynCalc`FCFeynmanParametrize`Private`optFCReplaceMomenta, 
        Check -> OptionValue[Check]]; 
      FeynCalc`FCFeynmanParametrize`Private`uPoly = 
       FeynCalc`FCFeynmanParametrize`Private`uPolyHead[
        FeynCalc`FCFeynmanParametrize`Private`uPoly]; 
      FeynCalc`FCFeynmanParametrize`Private`fPoly = 
