      If[MatchQ[FeynCalc`FCFeynmanParametrize`Private`optFCReplaceD, 
        {_Rule}], FeynCalc`FCFeynmanParametrize`Private`fpInt = 
         FCReplaceD[FeynCalc`FCFeynmanParametrize`Private`fpInt, 
          First[FeynCalc`FCFeynmanParametrize`Private`optFCReplaceD]]; 
        FeynCalc`FCFeynmanParametrize`Private`pref = 
         FCReplaceD[FeynCalc`FCFeynmanParametrize`Private`pref, 
          First[FeynCalc`FCFeynmanParametrize`Private`optFCReplaceD]]; 
        FCPrint[3, "FCFeynmanParametrize: fpInt after FCReplaceD: ", 
         FeynCalc`FCFeynmanParametrize`Private`fpInt, FCDoControl -> 
          FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
        FCPrint[3, "FCFeynmanParametrize: pref after FCReplaceD: ", 
         FeynCalc`FCFeynmanParametrize`Private`pref, FCDoControl -> 
          FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]]; 
      If[OptionValue[Simplify], FeynCalc`FCFeynmanParametrize`Private`fpInt = 
         Simplify[FeynCalc`FCFeynmanParametrize`Private`fpInt, 
          Assumptions -> OptionValue[Assumptions]]; 
        FeynCalc`FCFeynmanParametrize`Private`pref = 
         Simplify[FeynCalc`FCFeynmanParametrize`Private`pref, 
          Assumptions -> OptionValue[Assumptions]]; 
        FCPrint[3, "FCFeynmanParametrize: fpInt after Simplify: ", 
         FeynCalc`FCFeynmanParametrize`Private`fpInt, FCDoControl -> 
          FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
        FCPrint[3, "FCFeynmanParametrize: pref after Simplify: ", 
         FeynCalc`FCFeynmanParametrize`Private`pref, FCDoControl -> 
          FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]]; 
      If[Head[FeynCalc`FCFeynmanParametrize`Private`fpInt] =!= Times && 
         !MemberQ[{"Lee-Pomeransky"}, 
          FeynCalc`FCFeynmanParametrize`Private`optMethod], 
       FeynCalc`FCFeynmanParametrize`Private`fpInt = 
         Together[FeynCalc`FCFeynmanParametrize`Private`fpInt]; 
        FCPrint[3, "FCFeynmanParametrize: fpInt after Together: ", 
         FeynCalc`FCFeynmanParametrize`Private`fpInt, FCDoControl -> 
          FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]]; 
      FeynCalc`FCFeynmanParametrize`Private`aux = FCProductSplit[
        FeynCalc`FCFeynmanParametrize`Private`fpInt, 
        FeynCalc`FCFeynmanParametrize`Private`vars]; 
      FeynCalc`FCFeynmanParametrize`Private`pref = 
       FeynCalc`FCFeynmanParametrize`Private`pref*
        FeynCalc`FCFeynmanParametrize`Private`aux[[1]]; 
      FeynCalc`FCFeynmanParametrize`Private`fpInt = 
       FeynCalc`FCFeynmanParametrize`Private`aux[[2]]; 
      FeynCalc`FCFeynmanParametrize`Private`res = 
       {FeynCalc`FCFeynmanParametrize`Private`fpInt, 
        FeynCalc`FCFeynmanParametrize`Private`pref, 
        FeynCalc`FCFeynmanParametrize`Private`vars}; 
      If[OptionValue[Expanding], FeynCalc`FCFeynmanParametrize`Private`res = 
         FeynCalc`FCFeynmanParametrize`Private`res /. 
           Gamma[FeynCalc`FCFeynmanParametrize`Private`x_] :> 
            Gamma[ExpandAll[FeynCalc`FCFeynmanParametrize`Private`x]] /. 
          (FeynCalc`FCFeynmanParametrize`Private`x_)^
            (FeynCalc`FCFeynmanParametrize`Private`y_) :> 
           FeynCalc`FCFeynmanParametrize`Private`x^ExpandAll[
             FeynCalc`FCFeynmanParametrize`Private`y]; 
        FCPrint[3, "FCFeynmanParametrize: res after ExpandAll: ", 
         FeynCalc`FCFeynmanParametrize`Private`res, FCDoControl -> 
          FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]]; 
      If[OptionValue[FCFeynmanPrepare], 
       FeynCalc`FCFeynmanParametrize`Private`res = 
        Join[FeynCalc`FCFeynmanParametrize`Private`res, 
         {FeynCalc`FCFeynmanParametrize`Private`outputFCFeynmanPrepare}]]; 
      If[OptionValue[FCE], FeynCalc`FCFeynmanParametrize`Private`res = 
        FCE[FeynCalc`FCFeynmanParametrize`Private`res]]; 
      FCPrint[1, "FCFeynmanParametrize: Leaving.", FCDoControl -> 
        FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
      FCPrint[3, "FCFeynmanParametrize: Leaving with: ", 
       FeynCalc`FCFeynmanParametrize`Private`res, FCDoControl -> 
        FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose]; 
      FeynCalc`FCFeynmanParametrize`Private`res]
 
Options[FCFeynmanParametrize] = {Assumptions -> {}, DiracDelta -> False, 
     Check -> True, EtaSign -> False, Expanding -> True, 
     ExtraPropagators -> {}, "Euclidean" -> False, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCLoopPakScalelessQ -> True, 
     FCReplaceD -> {}, FCReplaceMomenta -> {}, FCVerbose -> False, 
     FeynmanIntegralPrefactor -> "Multiloop1", FinalSubstitutions -> {}, 
     Indexed -> True, Head -> {Identity, Identity}, 
     FCFeynmanPrepare -> False, Method -> "Feynman", Names -> FCGV["x"], 
     Reduce -> False, Simplify -> False, SplitSymbolicPowers -> False, 
     Variables -> {}}
 
FCFeynmanParametrize /: FCFeynmanParametrize::failmsg = "Error! \
FCFeynmanParametrize has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCFeynmanParametrize /: FCFeynmanParametrize::usage = "FCFeynmanParametrize[i\
nt, {q1, q2, ...}] introduces Feynman parameters for the\nmulti-loop integral \
int.\n\nThe function returns {fpInt,pref,vars},  where fpInt is the integrand \
in\nFeynman parameters, pref is the prefactor free of Feynman parameters and \
vars\nis the list of integration variables.\n\nIf the chosen parametrization \
contains a Dirac delta multiplying the\nintegrand, it will be omitted unless \
the option DiracDelta is set to True.\n\nBy default FCFeynmanParametrize uses \
normalization that is common in\nmulti-loop calculations, i.e. $\\frac{1}{i \
\\pi^{D/2}}$ or $\\frac{1}{\\pi^{D/2}}$\nper loop for Minkowski or \
Euclidean/Cartesian integrals respectively.\n\nIf you want to have the \
standard $\\frac{1}{(2 \\pi)^D}$ normalization or yet\nanother value, please \
set the option FeynmanIntegralPrefactor accordingly.\nFollowing values are \
available\n\n- \"MultiLoop1\" - default value explained above\n- \
\"MultiLoop2\" - like the default value but with an extra \
$e^{\\gamma_E\n\\frac{4-D}{2}}$ per loop\n- \"Textbook\" - $\\frac{1}{(2 \
\\pi)^D}$ per loop\n- \"Unity\" - no extra prefactor multiplying the integral \
measure\n- \"LoopTools\" - overall prefactor $\\frac{1}{i (\\pi)^{D/2} \
r_{\\Gamma}}$ with\n$r_{\\Gamma} = \\frac{\\Gamma(3-D/2) \\Gamma^2 \
(D/2-1)}{\\Gamma(D-3)}$ at 1 loop.\nThis matches the the normalization of \
1-loop integrals in LoopTools. For 2\nloops and above an extra $\\frac{1}{i \
\\pi^{D/2}}$ is added per loop.\n\nThe calculation of $D$-dimensional \
Minkowski integrals and $D-1$-dimensional\nCartesian integrals is \
straightforward.\n\nTo calculate a $D$-dimensional Euclidean integral (i.e. \
an integral defined\nwith the Euclidean\nmetric signature $(1,1,1,1)$ you \
need to write it in terms of FVD, SPD, FAD,\nSFAD etc. and set the option \
\"Euclidean\" to True.\n\nThe function can derive different representations \
of a loop integral. The\nchoice of the representation is controlled by the \
option Method. Following\nrepresentations are available\n\n- \"Feynman\" - \
the standard Feynman representation (default value). Both\ntensor integrals \
and integrals with scalar products in the numerator are\nsupported.\n- \
\"Lee-Pomeransky\" - this representation was first introduced \
in\n[1308.6676](https://arxiv.org/abs/1308.6676) by Roman Lee and \
Andrei\nPomeransky. Currently, only scalar integrals without numerators are \
supported.\n\nFCFeynmanParametrize can also be employed in conjunction \
with\nFCFeynmanParameterJoin, where one first joins suitable propagators \
using\nauxiliary Feynman\nparameters and then finally integrates out loop \
momenta.\n\nFor a proper analysis of a loop integral one usually needs the U \
and F\npolynomials separately. Since internally FCFeynmanParametrize \
uses\nFCFeynmanPrepare, the information available from the latter is also \
accessible\nto FCFeynmanParametrize.\n\nBy setting the option \
FCFeynmanPrepare to True, the output of FCFeynmanPrepare\nwill be added the \
the output of FCFeynmanParametrize as the 4th list element."
 
FCReplaceD[FeynCalc`FCReplaceD`Private`expr_, 
     {FeynCalc`FCReplaceD`Private`ru_Rule}, FeynCalc`FCReplaceD`Private`opts:
      OptionsPattern[]] := FCReplaceD[FeynCalc`FCReplaceD`Private`expr, 
     FeynCalc`FCReplaceD`Private`ru, FeynCalc`FCReplaceD`Private`opts]
 
FCReplaceD[FeynCalc`FCReplaceD`Private`expr_, 
     FeynCalc`FCReplaceD`Private`dim_Symbol -> 
      FeynCalc`FCReplaceD`Private`x_, OptionsPattern[]] := 
    Block[{FeynCalc`FCReplaceD`Private`ex, 
      FeynCalc`FCReplaceD`Private`vectorSet, FeynCalc`FCReplaceD`Private`res, 
      FeynCalc`FCReplaceD`Private`check, 
      FeynCalc`FCReplaceD`Private`scalarTerm, 
      FeynCalc`FCReplaceD`Private`vectorTerm = 1, 
      FeynCalc`FCReplaceD`Private`pref = 1, FeynCalc`FCReplaceD`Private`tmp, 
      FeynCalc`FCReplaceD`Private`scaleless1 = 0, 
      FeynCalc`FCReplaceD`Private`scaleless2 = 0, 
      FeynCalc`FCReplaceD`Private`ruleProtect, 
      FeynCalc`FCReplaceD`Private`holddim, FeynCalc`FCReplaceD`Private`diga, 
      FeynCalc`FCReplaceD`Private`pasi, FeynCalc`FCReplaceD`Private`dchn, 
      FeynCalc`FCReplaceD`Private`pchn}, FCPrint[1, "FCReplaceD: dim: ", 
       FeynCalc`FCReplaceD`Private`dim, FCDoControl -> 
        FeynCalc`FCReplaceD`Private`fcrdVerbose]; 
      If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCReplaceD`Private`fcrdVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCReplaceD`Private`fcrdVerbose = OptionValue[
           FCVerbose]]; ]; If[ !OptionValue[FCI], 
       FeynCalc`FCReplaceD`Private`ex = 
        FCI[FeynCalc`FCReplaceD`Private`expr], 
       FeynCalc`FCReplaceD`Private`ex = FeynCalc`FCReplaceD`Private`expr]; 
      FeynCalc`FCReplaceD`Private`tmp = 
       FeynCalc`FCReplaceD`Private`ex /. DiracChain -> 
            FeynCalc`FCReplaceD`Private`dchn /. PauliChain -> 
           FeynCalc`FCReplaceD`Private`pchn /. DiracGamma -> 
          FeynCalc`FCReplaceD`Private`diga /. PauliSigma -> 
         FeynCalc`FCReplaceD`Private`pasi; FeynCalc`FCReplaceD`Private`tmp = 
       FeynCalc`FCReplaceD`Private`tmp //. 
        {FeynCalc`FCReplaceD`Private`diga[FeynCalc`FCReplaceD`Private`a_, 
           FeynCalc`FCReplaceD`Private`di_] :> 
          FeynCalc`FCReplaceD`Private`diga[
           FeynCalc`FCReplaceD`Private`holddim[FeynCalc`FCReplaceD`Private`a, 
            ToString[FeynCalc`FCReplaceD`Private`di, InputForm]]], 
         FeynCalc`FCReplaceD`Private`pasi[FeynCalc`FCReplaceD`Private`a_, 
           FeynCalc`FCReplaceD`Private`di_] :> 
          FeynCalc`FCReplaceD`Private`pasi[
           FeynCalc`FCReplaceD`Private`holddim[FeynCalc`FCReplaceD`Private`a, 
            ToString[FeynCalc`FCReplaceD`Private`di, InputForm]]]}; 
      FCPrint[1, "FCReplaceD: tmp: ", FeynCalc`FCReplaceD`Private`tmp, 
       FCDoControl -> FeynCalc`FCReplaceD`Private`fcrdVerbose]; 
      FeynCalc`FCReplaceD`Private`tmp = FeynCalc`FCReplaceD`Private`tmp //. 
        (FeynCalc`FCReplaceD`Private`h:LorentzIndex | ExplicitLorentzIndex | 
            Momentum | CartesianIndex | CartesianMomentum)[
          FeynCalc`FCReplaceD`Private`a_, FeynCalc`FCReplaceD`Private`di_] :> 
         FeynCalc`FCReplaceD`Private`h[FeynCalc`FCReplaceD`Private`holddim[
           FeynCalc`FCReplaceD`Private`a, ToString[
            FeynCalc`FCReplaceD`Private`di, InputForm]]]; 
      FCPrint[1, "FCReplaceD: tmp: ", FeynCalc`FCReplaceD`Private`tmp, 
       FCDoControl -> FeynCalc`FCReplaceD`Private`fcrdVerbose]; 
      If[ !FreeQ[Cases2[FeynCalc`FCReplaceD`Private`tmp, 
          {ExplicitLorentzIndex, LorentzIndex, Momentum, CartesianIndex, 
           CartesianMomentum, DiracGamma, PauliSigma}], 
         FeynCalc`FCReplaceD`Private`dim], Message[FCReplaceD::checkfail]; 
        Abort[]]; FeynCalc`FCReplaceD`Private`tmp = 
       FeynCalc`FCReplaceD`Private`tmp //. 
        {FeynCalc`FCReplaceD`Private`dim -> FeynCalc`FCReplaceD`Private`x}; 
      If[ !FreeQ[FeynCalc`FCReplaceD`Private`tmp, 
         FeynCalc`FCReplaceD`Private`dim], Message[FCReplaceD::repfail, 
         FeynCalc`FCReplaceD`Private`dim, FeynCalc`FCReplaceD`Private`x]; 
        Abort[]]; FeynCalc`FCReplaceD`Private`res = 
       FeynCalc`FCReplaceD`Private`tmp //. 
        (FeynCalc`FCReplaceD`Private`h:LorentzIndex | ExplicitLorentzIndex | 
            Momentum | CartesianIndex | CartesianMomentum)[
          FeynCalc`FCReplaceD`Private`holddim[FeynCalc`FCReplaceD`Private`a_, 
           FeynCalc`FCReplaceD`Private`str_String]] :> 
         FeynCalc`FCReplaceD`Private`h[FeynCalc`FCReplaceD`Private`a, 
          ToExpression[FeynCalc`FCReplaceD`Private`str]]; 
      FeynCalc`FCReplaceD`Private`res = FeynCalc`FCReplaceD`Private`res /. 
        (FeynCalc`FCReplaceD`Private`h:LorentzIndex | ExplicitLorentzIndex | 
             Momentum | CartesianIndex | CartesianMomentum)[
           FeynCalc`FCReplaceD`Private`a_] /; 
          Head[FeynCalc`FCReplaceD`Private`a] =!= 
           FeynCalc`FCReplaceD`Private`holddim :> 
         FeynCalc`FCReplaceD`Private`h[FeynCalc`FCReplaceD`Private`a]; 
      FeynCalc`FCReplaceD`Private`res = FeynCalc`FCReplaceD`Private`res /. 
        FeynCalc`FCReplaceD`Private`diga[FeynCalc`FCReplaceD`Private`holddim[
           FeynCalc`FCReplaceD`Private`a_, 
           FeynCalc`FCReplaceD`Private`str_String]] :> 
         DiracGamma[FeynCalc`FCReplaceD`Private`a, ToExpression[
           FeynCalc`FCReplaceD`Private`str]]; 
      FeynCalc`FCReplaceD`Private`res = FeynCalc`FCReplaceD`Private`res /. 
        FeynCalc`FCReplaceD`Private`diga[FeynCalc`FCReplaceD`Private`a_] /; 
          Head[FeynCalc`FCReplaceD`Private`a] =!= 
           FeynCalc`FCReplaceD`Private`holddim :> DiracGamma[
          FeynCalc`FCReplaceD`Private`a]; FeynCalc`FCReplaceD`Private`res = 
       FeynCalc`FCReplaceD`Private`res /. FeynCalc`FCReplaceD`Private`pasi[
          FeynCalc`FCReplaceD`Private`holddim[FeynCalc`FCReplaceD`Private`a_, 
           FeynCalc`FCReplaceD`Private`str_String]] :> 
         PauliSigma[FeynCalc`FCReplaceD`Private`a, ToExpression[
           FeynCalc`FCReplaceD`Private`str]]; 
      FeynCalc`FCReplaceD`Private`res = FeynCalc`FCReplaceD`Private`res /. 
        FeynCalc`FCReplaceD`Private`pasi[FeynCalc`FCReplaceD`Private`a_] /; 
          Head[FeynCalc`FCReplaceD`Private`a] =!= 
           FeynCalc`FCReplaceD`Private`holddim :> PauliSigma[
          FeynCalc`FCReplaceD`Private`a]; FeynCalc`FCReplaceD`Private`res = 
       FeynCalc`FCReplaceD`Private`res /. FeynCalc`FCReplaceD`Private`dchn -> 
          DiracChain /. FeynCalc`FCReplaceD`Private`pchn -> PauliChain; 
      If[ !FreeQ2[FeynCalc`FCReplaceD`Private`res, 
         {FeynCalc`FCReplaceD`Private`holddim, 
          FeynCalc`FCReplaceD`Private`diga, 
          FeynCalc`FCReplaceD`Private`pasi}], Message[FCReplaceD::resfail]; 
        Abort[]]; If[OptionValue[FCE], FeynCalc`FCReplaceD`Private`res = 
        FCE[FeynCalc`FCReplaceD`Private`res]]; 
      FeynCalc`FCReplaceD`Private`res]
 
Options[FCReplaceD] = {FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCVerbose -> False}
 
FCReplaceD /: FCReplaceD::checkfail = "Error! Failed to save the \
dimensionality of Pair and DiracGamma objects. Evaluation aborted."
 
FCReplaceD /: FCReplaceD::repfail = "Error! Failed to replace all occurences \
of `1` with `2`. Evaluation aborted."
 
FCReplaceD /: FCReplaceD::resfail = "Error! Failed to restore the \
dimensionality of Pair and DiracGamma objects. Evaluation aborted."
 
FCReplaceD /: FCReplaceD::usage = "FCReplaceD[expr, rule] replaces D in expr \
according to the supplied\nreplacement rule (e.g. D -> 4 - 2*Epsilon) but \
doesn't touch D inside Pairs\nand DiracGammas, i.e the dimension of scalar \
products, metric tensors and\nDirac matrices is unchanged. The latter can and \
should be done via\nChangeDimension."
 
FeynCalc`FCReplaceD`Private`fcrdVerbose /: 
    FeynCalc`FCReplaceD`Private`fcrdVerbose::usage = ""
 
FeynmanIntegralPrefactor /: FeynmanIntegralPrefactor::usage = "FeynmanIntegra\
lPrefactor is an option for FCFeynmanParametrize and other\nfunctions. It \
denotes an implicit prefactor that has to be understood in front\nof a loop \
integral in the usual FeynAmpDenominator-notation. The prefactor is\nthe \
quantity that multiplies the loop integral measure $d^D q_1 \\ldots d^D\nq_n$ \
and plays an important role e.g. when deriving the Feynman \
parameter\nrepresentation of the given integral. Apart from specifying an \
explicit value,\nthe user may also choose from the following predefined \
conventions: \n\n- \"Unity\" - 1 for each loop\n- \"Textbook\" - \
$\\frac{1}{(2\\pi)^D}$ for each loop.\n- \"Multiloop1\" - $\\frac{1}{i \
\\pi^{D/2}}$ for each loop if the integral is\nMinkowskian, $\\frac{1}{i \
\\pi^{D/2}}$ or $\\frac{1}{i \\pi^{(D-1)/2}}$  for each\nloop if the integral \
is Euclidean or Cartesian respectively.\n- \"Multiloop2\" - like \
\"Multiloop1\" but with an extra $e^{\\frac{(4-D)}{2}\n\\gamma_E}$  for each \
loop\n\nThe standard value is \"Multiloop1\"."
 
FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose /: 
    FeynCalc`FCFeynmanParametrize`Private`fcfpVerbose::usage = ""
 
FCMakeSymbols[FeynCalc`SharedTools`Private`name_, 
     FeynCalc`SharedTools`Private`range_List, 
     FeynCalc`SharedTools`Private`type_, OptionsPattern[]] := 
    Block[{FeynCalc`SharedTools`Private`res, 
      FeynCalc`SharedTools`Private`body}, 
     FeynCalc`SharedTools`Private`body = ToString[
        FeynCalc`SharedTools`Private`name]; 
      FeynCalc`SharedTools`Private`res = 
       (ToExpression[StringJoin[FeynCalc`SharedTools`Private`body, 
           ToString[#1]]] & ) /@ FeynCalc`SharedTools`Private`range; 
      Switch[FeynCalc`SharedTools`Private`type, List, True, Sequence, 
       FeynCalc`SharedTools`Private`res = Sequence @@ 
         FeynCalc`SharedTools`Private`res, _, 
       Message[FCMakeSymbols::failmsg, "Unknown type!"]; Abort[]]; 
      FeynCalc`SharedTools`Private`res]
 
FCMakeSymbols /: FCMakeSymbols::failmsg = "Error! FCMakeSymbols has \
encountered a fatal problem and must abort the computation. \n\nThe problem \
reads: `1`"
 
FCMakeSymbols /: FCMakeSymbols::usage = "FCMakeSymbols[name, range, type] \
generates a list or a sequence of symbols\n(depending on the value of type) \
by attaching elements of the list range to\nname.\n\nFor example, \
FCMakeSymbols[mu, Range[1, 3], List] returns {mu1,mu2,mu3}."
 
SplitSymbolicPowers /: SplitSymbolicPowers::usage = "SplitSymbolicPowers is \
an option for FCFeynmanParametrize and other functions.\nWhen set to True, \
propagator powers containing symbols will be split into a\nnonnegative \
integer piece and the remaining piece.\nThis leads to a somewhat different \
form of the resulting parametric integral,\nalthough the final result remains \
the same. The default value is False."
 
FeynCalc`FCLoopScalelessQ`Private`checkIntsWithNumerators[_, _, True] := True
 
FeynCalc`FCLoopScalelessQ`Private`checkIntsWithNumerators[
     FeynCalc`FCLoopScalelessQ`Private`int_, 
     FeynCalc`FCLoopScalelessQ`Private`lmoms_, False] := 
    TrueQ[FCFeynmanParametrize[FeynCalc`FCLoopScalelessQ`Private`int, 
        FeynCalc`FCLoopScalelessQ`Private`lmoms][[2]] === 0]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`null1 /: 
    FeynCalc`FeynAmpDenominatorSimplify`Private`null1::usage = ""
 
FeynCalc`FeynAmpDenominatorSimplify`Private`null2 /: 
    FeynCalc`FeynAmpDenominatorSimplify`Private`null2::usage = ""
 
FCLoopPropagatorPowersExpand[
     FeynCalc`FCLoopPropagatorPowersExpand`Private`expr_, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopPropagatorPowersExpand`Private`ex, 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`res, 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsList, 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsListEval, 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`repRule}, 
     If[OptionValue[FCI], FeynCalc`FCLoopPropagatorPowersExpand`Private`ex = 
        FeynCalc`FCLoopPropagatorPowersExpand`Private`expr, 
       FeynCalc`FCLoopPropagatorPowersExpand`Private`ex = 
        FCI[FeynCalc`FCLoopPropagatorPowersExpand`Private`expr]]; 
      If[FreeQ2[FeynCalc`FCLoopPropagatorPowersExpand`Private`ex, 
        {StandardPropagatorDenominator, CartesianPropagatorDenominator, 
         GenericPropagatorDenominator}], 
       Return[FeynCalc`FCLoopPropagatorPowersExpand`Private`ex]]; 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsList = 
       Cases2[FeynCalc`FCLoopPropagatorPowersExpand`Private`ex, 
        FeynAmpDenominator]; 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsListEval = 
       FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsList /. 
        {(FeynCalc`FCLoopPropagatorPowersExpand`Private`h:
             StandardPropagatorDenominator | CartesianPropagatorDenominator | 
              GenericPropagatorDenominator)[
            FeynCalc`FCLoopPropagatorPowersExpand`Private`x__, 
            {FeynCalc`FCLoopPropagatorPowersExpand`Private`n_Integer, 
             FeynCalc`FCLoopPropagatorPowersExpand`Private`s_}] /; 
           Abs[FeynCalc`FCLoopPropagatorPowersExpand`Private`n] > 1 :> 
          Sequence @@ ConstantArray[
            FeynCalc`FCLoopPropagatorPowersExpand`Private`h[
             FeynCalc`FCLoopPropagatorPowersExpand`Private`x, 
             {1, FeynCalc`FCLoopPropagatorPowersExpand`Private`s}], 
            FeynCalc`FCLoopPropagatorPowersExpand`Private`n]}; 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`repRule = 
       Thread[FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsList -> 
         FeynCalc`FCLoopPropagatorPowersExpand`Private`fadsListEval]; 
      FeynCalc`FCLoopPropagatorPowersExpand`Private`res = 
       FeynCalc`FCLoopPropagatorPowersExpand`Private`ex /. 
        Dispatch[FeynCalc`FCLoopPropagatorPowersExpand`Private`repRule]; 
      If[OptionValue[FCE], 
