FeynCalc`FeynAmpDenominatorSimplify`Private`procan[
     FeynCalc`FeynAmpDenominatorSimplify`Private`a_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`m_] := 
    Block[{FeynCalc`FeynAmpDenominatorSimplify`Private`tt, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`one, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`numfac}, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`tt = 
       Factor2[FeynCalc`FeynAmpDenominatorSimplify`Private`one*
         MomentumExpand[FeynCalc`FeynAmpDenominatorSimplify`Private`a]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`numfac = 
       NumericalFactor[FeynCalc`FeynAmpDenominatorSimplify`Private`tt]; 
      If[TrueQ[FeynCalc`FeynAmpDenominatorSimplify`Private`numfac < 0 && 
         MatchQ[FeynCalc`FeynAmpDenominatorSimplify`Private`numfac, 
          _Rational | _Integer]], 
       PD[Expand[-FeynCalc`FeynAmpDenominatorSimplify`Private`tt /. 
          FeynCalc`FeynAmpDenominatorSimplify`Private`one -> 1], 
        FeynCalc`FeynAmpDenominatorSimplify`Private`m], 
       PD[Expand[FeynCalc`FeynAmpDenominatorSimplify`Private`tt /. 
          FeynCalc`FeynAmpDenominatorSimplify`Private`one -> 1], 
