FCLoopBasisSplit[FeynCalc`FCLoopBasisSplit`Private`ex_, _List, 
     OptionsPattern[]] := FeynCalc`FCLoopBasisSplit`Private`ex /; 
     FreeQ[FeynCalc`FCLoopBasisSplit`Private`ex, FeynAmpDenominator]
 
FCLoopBasisSplit[(FeynCalc`FCLoopBasisSplit`Private`sps_.)*
      (FeynCalc`FCLoopBasisSplit`Private`fad_FeynAmpDenominator), 
     FeynCalc`FCLoopBasisSplit`Private`lmoms_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopBasisSplit`Private`ex, 
      FeynCalc`FCLoopBasisSplit`Private`rest, 
      FeynCalc`FCLoopBasisSplit`Private`res, 
      FeynCalc`FCLoopBasisSplit`Private`loopMomenta}, 
     FeynCalc`FCLoopBasisSplit`Private`ex = FeynAmpDenominatorSplit[
        FeynCalc`FCLoopBasisSplit`Private`sps*
         FeynCalc`FCLoopBasisSplit`Private`fad, FCI -> True]; 
      FeynCalc`FCLoopBasisSplit`Private`loopMomenta = 
       Select[FeynCalc`FCLoopBasisSplit`Private`lmoms, 
         !FreeQ[FeynCalc`FCLoopBasisSplit`Private`ex, #1] & ]; 
      If[FeynCalc`FCLoopBasisSplit`Private`loopMomenta === {}, 
       Return[OptionValue[Head][FeynCalc`FCLoopBasisSplit`Private`sps*
          FeynCalc`FCLoopBasisSplit`Private`fad, 0]]]; 
      {FeynCalc`FCLoopBasisSplit`Private`ex, 
        FeynCalc`FCLoopBasisSplit`Private`rest} = 
       {SelectNotFree[FeynCalc`FCLoopBasisSplit`Private`ex, 
         FeynCalc`FCLoopBasisSplit`Private`loopMomenta], 
        SelectFree[FeynCalc`FCLoopBasisSplit`Private`ex, 
         FeynCalc`FCLoopBasisSplit`Private`loopMomenta]}; 
      FeynCalc`FCLoopBasisSplit`Private`res = 
       FeynCalc`FCLoopBasisSplit`Private`loopSplitFu[{}, 
        FeynCalc`FCLoopBasisSplit`Private`ex, 
        FeynCalc`FCLoopBasisSplit`Private`lmoms, 
        Rest[Subsets[FeynCalc`FCLoopBasisSplit`Private`lmoms]]]; 
      If[FeynCalc`FCLoopBasisSplit`Private`rest =!= 1, 
       FeynCalc`FCLoopBasisSplit`Private`res = 
        Join[FeynCalc`FCLoopBasisSplit`Private`res, 
         {FeynCalc`FCLoopBasisSplit`Private`lintegral[
           FeynCalc`FCLoopBasisSplit`Private`rest, 0]}]]; 
      If[OptionValue[FeynAmpDenominatorCombine], 
       FeynCalc`FCLoopBasisSplit`Private`res = 
        FeynCalc`FCLoopBasisSplit`Private`res /. 
         FeynCalc`FCLoopBasisSplit`Private`lintegral[
           FeynCalc`FCLoopBasisSplit`Private`x_, 
           FeynCalc`FCLoopBasisSplit`Private`y_] :> 
          FeynCalc`FCLoopBasisSplit`Private`lintegral[
           FeynAmpDenominatorCombine[FeynCalc`FCLoopBasisSplit`Private`x, 
            FCI -> True], FeynCalc`FCLoopBasisSplit`Private`y]]; 
      FeynCalc`FCLoopBasisSplit`Private`res = 
       FeynCalc`FCLoopBasisSplit`Private`res /. 
        FeynCalc`FCLoopBasisSplit`Private`lintegral -> OptionValue[Head]; 
      If[ !OptionValue[List], FeynCalc`FCLoopBasisSplit`Private`res = 
        Times @@ FeynCalc`FCLoopBasisSplit`Private`res]; 
      If[OptionValue[FCE], FeynCalc`FCLoopBasisSplit`Private`res = 
        FCE[FeynCalc`FCLoopBasisSplit`Private`res]]; 
      FeynCalc`FCLoopBasisSplit`Private`res]
 
