FeynCalc`FCLoopBasisSplit`Private`loopSplitFu[
     FeynCalc`FCLoopBasisSplit`Private`done_List, 
     FeynCalc`FCLoopBasisSplit`Private`remaining_, 
     FeynCalc`FCLoopBasisSplit`Private`lmoms_, 
     FeynCalc`FCLoopBasisSplit`Private`subsets_] := 
    Block[{FeynCalc`FCLoopBasisSplit`Private`splitting, 
       FeynCalc`FCLoopBasisSplit`Private`tmp}, 
      FeynCalc`FCLoopBasisSplit`Private`splitting = 
        Catch[((FeynCalc`FCLoopBasisSplit`Private`tmp = 
             {SelectNotFree[FeynCalc`FCLoopBasisSplit`Private`remaining, #1], 
              #1, SelectFree[FeynCalc`FCLoopBasisSplit`Private`remaining, 
               #1]}; If[TrueQ[FeynCalc`FCLoopBasisSplit`Private`tmp[[1]] =!= 
                1 && FreeQ2[FeynCalc`FCLoopBasisSplit`Private`tmp[[1]], 
                Complement[FeynCalc`FCLoopBasisSplit`Private`lmoms, #1]]], 
             Throw[FeynCalc`FCLoopBasisSplit`Private`tmp], Null]) & ) /@ 
          FeynCalc`FCLoopBasisSplit`Private`subsets]; 
       If[TrueQ[Last[FeynCalc`FCLoopBasisSplit`Private`splitting] === 1], 
        Join[FeynCalc`FCLoopBasisSplit`Private`done, 
         {FeynCalc`FCLoopBasisSplit`Private`lintegral[
           FeynCalc`FCLoopBasisSplit`Private`splitting[[1]], 
           FeynCalc`FCLoopBasisSplit`Private`splitting[[2]]]}], 
        FeynCalc`FCLoopBasisSplit`Private`loopSplitFu[
         Join[FeynCalc`FCLoopBasisSplit`Private`done, 
          {FeynCalc`FCLoopBasisSplit`Private`lintegral[
            FeynCalc`FCLoopBasisSplit`Private`splitting[[1]], 
            FeynCalc`FCLoopBasisSplit`Private`splitting[[2]]]}], 
         FeynCalc`FCLoopBasisSplit`Private`splitting[[3]], 
         FeynCalc`FCLoopBasisSplit`Private`lmoms, 
