      Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[-Momentum[k1, D] + Momentum[l, D], 
      Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[-Momentum[k2, D] + Momentum[l, D], 
      Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[-Momentum[k1, D] - Momentum[k2, D] + 
       Momentum[l, D], Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[Momentum[k1, D] + Momentum[k3, D] + 
       Momentum[l, D], Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[Momentum[k2, D] + Momentum[k3, D] + 
       Momentum[l, D], Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[Momentum[k1, D] + Momentum[k2, D] + 
       Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      Momentum[k1, D] + Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]], 
     PropagatorDenominator[Momentum[k1, D] + Momentum[k2, D] + 
       Momentum[k3, D] + Momentum[l, D], Subscript[m, Hp]]] = True
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[PropagatorDenominator[
      FeynCalc`FeynAmpDenominatorSimplify`Private`x_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1_], 
     PropagatorDenominator[FeynCalc`FeynAmpDenominatorSimplify`Private`y_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m2_]] := 
    FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[
      PD[FeynCalc`FeynAmpDenominatorSimplify`Private`x, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m1], 
      PD[FeynCalc`FeynAmpDenominatorSimplify`Private`y, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2]] = 
     Which[FeynCalc`FeynAmpDenominatorSimplify`Private`m1 =!= 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 =!= 0, 
      OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`m1, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`m2}], 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 === 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 =!= 0, True, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 =!= 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 === 0, False, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 === 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 === 0, 
      If[NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x] < 
        NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y], True, 
       If[NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x] === 
         NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y], 
        OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`x, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`y}], False], False], 
      True, Message[FDS::failmsg, "Can't sort the list of propagators."]; 
       Abort[]]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[
     (FeynCalc`FeynAmpDenominatorSimplify`Private`h1:
       StandardPropagatorDenominator | CartesianPropagatorDenominator)[
      FeynCalc`FeynAmpDenominatorSimplify`Private`x1_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`x2_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`s1_], 
     (FeynCalc`FeynAmpDenominatorSimplify`Private`h2:
       StandardPropagatorDenominator | CartesianPropagatorDenominator)[
      FeynCalc`FeynAmpDenominatorSimplify`Private`y1_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`y2_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m2_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`s2_]] := 
    FeynCalc`FeynAmpDenominatorSimplify`Private`lenso2[
      FeynCalc`FeynAmpDenominatorSimplify`Private`h1[
       FeynCalc`FeynAmpDenominatorSimplify`Private`x1, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`x2, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m1, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`s1], 
      FeynCalc`FeynAmpDenominatorSimplify`Private`h2[
       FeynCalc`FeynAmpDenominatorSimplify`Private`y1, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`y2, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`s2]] = 
     Which[FeynCalc`FeynAmpDenominatorSimplify`Private`h1 === 
        StandardPropagatorDenominator && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`h2 === 
        CartesianPropagatorDenominator, True, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`h1 === 
        CartesianPropagatorDenominator && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`h2 === 
        StandardPropagatorDenominator, False, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 =!= 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 =!= 0, 
      OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`m1, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`m2}], 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 === 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 =!= 0, True, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 =!= 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 === 0, False, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`m1 === 0 && 
       FeynCalc`FeynAmpDenominatorSimplify`Private`m2 === 0, 
      If[NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`x2] < 
        NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`y2], True, 
       If[NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
           FeynCalc`FeynAmpDenominatorSimplify`Private`x2] === 
         NTerms[FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
           FeynCalc`FeynAmpDenominatorSimplify`Private`y2], 
        OrderedQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`x1 + 
           FeynCalc`FeynAmpDenominatorSimplify`Private`x2, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`y1 + 
           FeynCalc`FeynAmpDenominatorSimplify`Private`y2}], False], False], 
      True, Message[FDS::failmsg, "Can't sort the list of propagators."]; 
       Abort[]]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`removeAnitsymmetricIntegrals[
     FeynCalc`FeynAmpDenominatorSimplify`Private`int_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`qmin_List, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`qs_List] := 
    If[TrueQ[Expand[(MomentumExpand[EpsEvaluate[
              FeynCalc`FeynAmpDenominatorSimplify`Private`int /. Thread[
                FeynCalc`FeynAmpDenominatorSimplify`Private`qmin -> 
                 -FeynCalc`FeynAmpDenominatorSimplify`Private`qmin], 
              FCI -> True]] /. FeynAmpDenominator -> 
             FeynCalc`Package`feynsimp[
              FeynCalc`FeynAmpDenominatorSimplify`Private`qs] /. 
           FeynAmpDenominator -> 
            FeynCalc`FeynAmpDenominatorSimplify`Private`feynord2[
             FeynCalc`FeynAmpDenominatorSimplify`Private`qs]) + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`int] === 0], 0, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`int] /; 
     FeynCalc`FeynAmpDenominatorSimplify`Private`int =!= 0
 
FeynCalc`FeynAmpDenominatorSimplify`Private`removeAnitsymmetricIntegrals[0, 
     {__}, {__}] := 0
 
FeynCalc`FeynAmpDenominatorSimplify`Private`extractm[
     FeynCalc`FeynAmpDenominatorSimplify`Private`a_, ___] := 
    FeynCalc`FeynAmpDenominatorSimplify`Private`a
 
FCLoopMixedIntegralQ[(FeynCalc`FCLoopMixedIntegralQ`Private`sps_.)*
      (FeynCalc`FCLoopMixedIntegralQ`Private`fad_FeynAmpDenominator)] := 
    Block[{FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
       FeynCalc`FCLoopMixedIntegralQ`Private`res}, 
      FeynCalc`FCLoopMixedIntegralQ`Private`heads = 
        Union[Cases[FeynCalc`FCLoopMixedIntegralQ`Private`sps*
           FeynCalc`FCLoopMixedIntegralQ`Private`fad, 
          (FeynCalc`FCLoopMixedIntegralQ`Private`h:LorentzIndex | 
              CartesianIndex | ExplicitLorentzIndex | Momentum | 
              CartesianMomentum | TemporalMomentum)[__] :> 
           FeynCalc`FCLoopMixedIntegralQ`Private`h, Infinity]]; 
       Which[FeynCalc`FCLoopMixedIntegralQ`Private`heads === {}, 
        FeynCalc`FCLoopMixedIntegralQ`Private`res = False, 
        (FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
           {LorentzIndex, Momentum, ExplicitLorentzIndex, 
            TemporalMomentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {CartesianIndex, CartesianMomentum}]) || 
         (FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
           {LorentzIndex, Momentum, CartesianIndex, CartesianMomentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {ExplicitLorentzIndex, TemporalMomentum}]) || 
         (FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
           {ExplicitLorentzIndex, TemporalMomentum, CartesianIndex, 
            CartesianMomentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {LorentzIndex, Momentum}]), 
        FeynCalc`FCLoopMixedIntegralQ`Private`res = False, 
        ( !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {LorentzIndex, Momentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {CartesianIndex, CartesianMomentum}]) || 
         ( !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {LorentzIndex, Momentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {ExplicitLorentzIndex, TemporalMomentum}]) || 
         ( !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {CartesianIndex, CartesianMomentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {ExplicitLorentzIndex, TemporalMomentum}]) || 
         ( !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {LorentzIndex, Momentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {ExplicitLorentzIndex, TemporalMomentum}] && 
           !FreeQ2[FeynCalc`FCLoopMixedIntegralQ`Private`heads, 
            {CartesianIndex, CartesianMomentum}]), 
        FeynCalc`FCLoopMixedIntegralQ`Private`res = True, True, 
        Message[FCLoopMixedIntegralQ::failmsg, 
          "Unknown combination of heads."]; Abort[]]; 
       FeynCalc`FCLoopMixedIntegralQ`Private`res] /; 
     FreeQ[FeynCalc`FCLoopMixedIntegralQ`Private`sps, FeynAmpDenominator]
 
FCLoopMixedIntegralQ /: FCLoopMixedIntegralQ::failmsg = "FCLoopMixedIntegralQ \
has encountered a fatal problem and must abort the computation. The problem \
reads: `1`"
 
FCLoopMixedIntegralQ /: FCLoopMixedIntegralQ::usage = "FCLoopMixedIntegralQ[e\
xp] returns True if the integral contains both Lorentz\nand Cartesian indices \
and momenta."
 
FCLoopEikonalPropagatorFreeQ[
     (FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`sps_.)*
      (FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`fad_FeynAmpDenominator), 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`fadList, 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`res, 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`eikProps, 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optMomentum, 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optFirst}, 
      FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optMomentum = 
        OptionValue[Momentum]; 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optFirst = 
        OptionValue[First]; 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`fadList = 
        Sort[List @@ FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`fad]; 
       If[FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optMomentum =!= 
          All &&  !MatchQ[
           FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optMomentum, {__}], 
        Message[FCLoopEikonalPropagatorFreeQ::failmsg, 
          "Incorrect value of the option Momentum"]; Abort[]]; 
       If[FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optMomentum === All, 
        FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`eikProps = 
         Cases[FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`fadList, 
          (StandardPropagatorDenominator | CartesianPropagatorDenominator)[
            FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`w_ /; 
             (FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`w === 0 && 
               FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optFirst) || 
               !FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optFirst, 
            FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`x_ /; 
             FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`x =!= 0, _, _] :> 
           True, Infinity], 
        FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`eikProps = 
         Cases[FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`fadList, 
          (StandardPropagatorDenominator | CartesianPropagatorDenominator)[
            FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`w_ /; 
             (FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`w === 0 && 
               FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optFirst) || 
               !FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optFirst, 
            FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`x_ /; 
             FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`x =!= 0 && 
               !FreeQ2[{FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`x}, 
                FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`optMomentum], 
            _, _] :> True, Infinity]]; 
       FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`eikProps === {}] /; 
     FreeQ[FeynCalc`FCLoopEikonalPropagatorFreeQ`Private`sps, 
      FeynAmpDenominator]
 
Options[FCLoopEikonalPropagatorFreeQ] = {First -> True, Momentum -> All}
 
FCLoopEikonalPropagatorFreeQ /: FCLoopEikonalPropagatorFreeQ::failmsg = "FCLo\
opEikonalPropagatorFreeQ has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCLoopEikonalPropagatorFreeQ /: FCLoopEikonalPropagatorFreeQ::usage = "FCLoop\
EikonalPropagatorFreeQ[exp] checks if the integral is free of \
eikonal\npropagators $\\frac{1}{p \\cdot q+x}$. If the option First is set to \
False,\npropagators that have both a quadratic and linear piece, e.g. \
$\\frac{1}{p^2 +\np \\cdot q+x}$ will also count as eikonal propagators. The \
option Momentum can\nbe used to check for the presence of eikonal propagators \
only with respect to\nparticular momenta. The check is performed only \
for\nStandardPropagatorDenominator and CartesianPropagatorDenominator."
 
FeynCalc`FeynAmpDenominatorSimplify`Private`fdsOneLoopsGeneric[
     FeynCalc`FeynAmpDenominatorSimplify`Private`expr:
      FeynAmpDenominator[FeynCalc`FeynAmpDenominatorSimplify`Private`props__]*
       (_.), FeynCalc`FeynAmpDenominatorSimplify`Private`q_] := 
    Block[{FeynCalc`FeynAmpDenominatorSimplify`Private`prs, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`prs2, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`canonicalProps, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res}, 
     FCPrint[3, "FDS: fdsOneLoopsGeneric: Entering with ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`expr, 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`prs = 
       Expand /@ ({FeynCalc`FeynAmpDenominatorSimplify`Private`props} /. 
         {PropagatorDenominator[
            FeynCalc`FeynAmpDenominatorSimplify`Private`z_, _:0] :> 
           (FeynCalc`FeynAmpDenominatorSimplify`Private`z /. 
            Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`a_, _:4] :> 
             FeynCalc`FeynAmpDenominatorSimplify`Private`a), 
          StandardPropagatorDenominator[
            FeynCalc`FeynAmpDenominatorSimplify`Private`z_, _, _, _] :> 
           (FeynCalc`FeynAmpDenominatorSimplify`Private`z /. 
            Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`a_, _:4] :> 
             FeynCalc`FeynAmpDenominatorSimplify`Private`a), 
          CartesianPropagatorDenominator[
            FeynCalc`FeynAmpDenominatorSimplify`Private`z_, _, _, _] :> 
           (FeynCalc`FeynAmpDenominatorSimplify`Private`z /. 
            CartesianMomentum[FeynCalc`FeynAmpDenominatorSimplify`Private`a_, 
              _:3] :> FeynCalc`FeynAmpDenominatorSimplify`Private`a)}); 
      FeynCalc`FeynAmpDenominatorSimplify`Private`canonicalProps = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`createOneLoopCanonicalProp\
sList[FeynCalc`FeynAmpDenominatorSimplify`Private`prs, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`q, True]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList = 
       FixedPoint[
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsOneLoopsShiftMaker[
           #1[[1]], FeynCalc`FeynAmpDenominatorSimplify`Private`q, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`canonicalProps, 
           #1[[2]]] & , {FeynCalc`FeynAmpDenominatorSimplify`Private`prs, 
          {}}, Length[FeynCalc`FeynAmpDenominatorSimplify`Private`prs] - 1][[
        2]]; FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList /. 
        Momentum -> FeynCalc`FeynAmpDenominatorSimplify`Private`extractm; 
      FCPrint[3, 
       "FDS: fdsOneLoopsGeneric: List of the shifts to be applied: ", 
       FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList, 
       FCDoControl -> 
        FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`expr; 
      If[FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList =!= {}, 
       Do[FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
         MomentumExpand[FeynCalc`FeynAmpDenominatorSimplify`Private`res /. 
            FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList[[
             FeynCalc`FeynAmpDenominatorSimplify`Private`i]] /. 
           FeynAmpDenominator :> FeynCalc`Package`feynsimp[
             {FeynCalc`FeynAmpDenominatorSimplify`Private`q}]], 
        {FeynCalc`FeynAmpDenominatorSimplify`Private`i, 
         Length[FeynCalc`FeynAmpDenominatorSimplify`Private`shiftList]}]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res /. 
        FeynAmpDenominator :> FeynCalc`Package`feynord[
          {FeynCalc`FeynAmpDenominatorSimplify`Private`q}]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`prs2 = 
       First[Cases[FeynCalc`FeynAmpDenominatorSimplify`Private`res + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`null1 + 
          FeynCalc`FeynAmpDenominatorSimplify`Private`null2, 
         FeynAmpDenominator[
           FeynCalc`FeynAmpDenominatorSimplify`Private`pros__] :> 
          Expand /@ Union[
            {FeynCalc`FeynAmpDenominatorSimplify`Private`pros} /. 
               PropagatorDenominator[
                 FeynCalc`FeynAmpDenominatorSimplify`Private`z_, _:0] :> 
                (FeynCalc`FeynAmpDenominatorSimplify`Private`z /. 
                 Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`a_, 
                   _:4] :> FeynCalc`FeynAmpDenominatorSimplify`Private`a) /. 
              FeynCalc`FeynAmpDenominatorSimplify`Private`q -> 0 /. 
             0 -> Unevaluated[Sequence[]]], Infinity]]; 
      If[FeynCalc`FeynAmpDenominatorSimplify`Private`prs2 =!= {}, 
       If[Length[Select[FeynCalc`FeynAmpDenominatorSimplify`Private`prs2, 
            FeynCalc`FeynAmpDenominatorSimplify`Private`nufaQ]] > 
          Length[Complement[FeynCalc`FeynAmpDenominatorSimplify`Private`prs2, 
            Select[FeynCalc`FeynAmpDenominatorSimplify`Private`prs2, 
             FeynCalc`FeynAmpDenominatorSimplify`Private`nufaQ]]], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
          MomentumExpand[FeynCalc`FeynAmpDenominatorSimplify`Private`res /. 
             FeynCalc`FeynAmpDenominatorSimplify`Private`q -> 
              -FeynCalc`FeynAmpDenominatorSimplify`Private`q /. 
            FeynAmpDenominator :> FeynCalc`Package`feynsimp[
              {FeynCalc`FeynAmpDenominatorSimplify`Private`q}]]]; 
        If[Length[Select[FeynCalc`FeynAmpDenominatorSimplify`Private`prs2, 
