FeynCalc`FeynAmpDenominatorSimplify`Private`createOneLoopCanonicalPropsList[
     FeynCalc`FeynAmpDenominatorSimplify`Private`prs_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`q_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`ext_] := 
    FeynCalc`FeynAmpDenominatorSimplify`Private`createOneLoopCanonicalPropsLi\
st[FeynCalc`FeynAmpDenominatorSimplify`Private`prs, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`q, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`ext] = 
     Block[{FeynCalc`FeynAmpDenominatorSimplify`Private`moms, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`extra, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`fu, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res}, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`fu[
         FeynCalc`FeynAmpDenominatorSimplify`Private`x_] := 
        ({FeynCalc`FeynAmpDenominatorSimplify`Private`q - #1[[2]], 
           FeynCalc`FeynAmpDenominatorSimplify`Private`q + #1[[2]], 
           FeynCalc`FeynAmpDenominatorSimplify`Private`q - 
            Abs[#1[[1]]]*#1[[2]], 
           FeynCalc`FeynAmpDenominatorSimplify`Private`q + 
            Abs[#1[[1]]]*#1[[2]]} & ) /@ 
         FeynCalc`FeynAmpDenominatorSimplify`Private`x; 
       If[FeynCalc`FeynAmpDenominatorSimplify`Private`ext === True, 
        FeynCalc`FeynAmpDenominatorSimplify`Private`extra = 
          Union[Flatten[({#1[[1]] + #1[[2]], #1[[1]] - #1[[2]]} & ) /@ 
             Subsets[FeynCalc`FeynAmpDenominatorSimplify`Private`prs /. 
                FeynCalc`FeynAmpDenominatorSimplify`Private`q -> 0 /. 0 -> 
                Unevaluated[Sequence[]], {2}]]]; 
         FeynCalc`FeynAmpDenominatorSimplify`Private`extra = 
          Flatten[({FeynCalc`FeynAmpDenominatorSimplify`Private`q - #1, 
              FeynCalc`FeynAmpDenominatorSimplify`Private`q + #1} & ) /@ 
            FeynCalc`FeynAmpDenominatorSimplify`Private`extra], 
        FeynCalc`FeynAmpDenominatorSimplify`Private`extra = {}]; 
       Quiet[FeynCalc`FeynAmpDenominatorSimplify`Private`moms = 
         Check[(Thread[{Total[Rest[Normal[CoefficientArrays[#1]]]], 
              Variables[#1]}] & ) /@ 
           Rest[FeynCalc`FeynAmpDenominatorSimplify`Private`prs /. 
             FeynCalc`FeynAmpDenominatorSimplify`Private`q -> 0], {}, 
          {General::poly}], {General::poly, General::argt}]; 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
        Flatten[(FeynCalc`FeynAmpDenominatorSimplify`Private`fu[#1] & ) /@ 
          FeynCalc`FeynAmpDenominatorSimplify`Private`moms]; 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
        Join[{FeynCalc`FeynAmpDenominatorSimplify`Private`q}, 
