         AbsoluteTime[]; FCPrint[1, "FCLoopFindTopologies: Handling the \
loop-momentum denominator free part of the expression.", 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
        If[Length[FeynCalc`FCLoopFindTopologies`Private`realTopologies] === 
          0, FeynCalc`FCLoopFindTopologies`Private`realTopologies = 
           {FCTopology[StringJoin[
              FeynCalc`FCLoopFindTopologies`Private`topoTempName, "1"], 
             Join[
              FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsFirst, 
              FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsLast]]}; 
          FeynCalc`FCLoopFindTopologies`Private`realTopologies = 
           MapIndexed[(FeynCalc`FCLoopFindTopologies`Private`momenta = Union[
                Cases[MomentumExpand[#1[[2]]], Momentum[
                   FeynCalc`FCLoopFindTopologies`Private`m_, ___] :> 
                  FeynCalc`FCLoopFindTopologies`Private`m, Infinity]]; 
              FCTopology[#1[[1]], #1[[2]], Intersection[
                FeynCalc`FCLoopFindTopologies`Private`momenta, 
                FeynCalc`FCLoopFindTopologies`Private`lmoms], SelectFree[
                FeynCalc`FCLoopFindTopologies`Private`momenta, 
                FeynCalc`FCLoopFindTopologies`Private`lmoms], 
               FeynCalc`FCLoopFindTopologies`Private`optFinalSubstitutions, {
                }]) & , 
            FeynCalc`FCLoopFindTopologies`Private`realTopologies]; 
          FeynCalc`FCLoopFindTopologies`Private`denFreePart = 
           FeynCalc`FCLoopFindTopologies`Private`denFreePart*
            GLI[StringJoin[
              FeynCalc`FCLoopFindTopologies`Private`topoTempName, "1"], 
             Join[ConstantArray[1, Length[
                FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsFirst]]\
, ConstantArray[1, Length[
                FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsLast]]]]\
, FeynCalc`FCLoopFindTopologies`Private`denFreeTopoName = 
           FeynCalc`FCLoopFindTopologies`Private`realTopologies[[1]][[1]]; 
          FeynCalc`FCLoopFindTopologies`Private`denFreePart = 
           FeynCalc`FCLoopFindTopologies`Private`denFreePart*
            GLI[FeynCalc`FCLoopFindTopologies`Private`denFreeTopoName, 
             Join[ConstantArray[1, Length[
                FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsFirst]]\
, ConstantArray[0, Length[
                 FeynCalc`FCLoopFindTopologies`Private`realTopologies[[1]][[
                  2]]] - Length[
                 FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsFirst] \
- Length[FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsLast]], 
              ConstantArray[1, Length[
                FeynCalc`FCLoopFindTopologies`Private`extraPropagatorsLast]]]]\
]; FCPrint[1, "FCLoopFindTopologies: Done handling the loop-momentum \
denominator free part of the expression, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopFindTopologies`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; ]; 
      FeynCalc`FCLoopFindTopologies`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFindTopologies: Intorducing final names for the \
identified topologies.", FCDoControl -> 
        FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      Switch[FeynCalc`FCLoopFindTopologies`Private`optNames, _String, 
       FeynCalc`FCLoopFindTopologies`Private`newNames = 
        Table[StringJoin[FeynCalc`FCLoopFindTopologies`Private`optNames, 
          ToString[FeynCalc`FCLoopFindTopologies`Private`i]], 
         {FeynCalc`FCLoopFindTopologies`Private`i, 1, 
          Length[FeynCalc`FCLoopFindTopologies`Private`realTopologies] - 
           Length[
            FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies]}]\
, _Symbol, FeynCalc`FCLoopFindTopologies`Private`newNames = 
        Table[ToExpression[StringJoin[ToString[
            FeynCalc`FCLoopFindTopologies`Private`optNames], 
           ToString[FeynCalc`FCLoopFindTopologies`Private`i]]], 
         {FeynCalc`FCLoopFindTopologies`Private`i, 1, 
          Length[FeynCalc`FCLoopFindTopologies`Private`realTopologies] - 
           Length[
            FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies]}]\
, _Function, FeynCalc`FCLoopFindTopologies`Private`newNames = 
        Table[FeynCalc`FCLoopFindTopologies`Private`optNames[
          FeynCalc`FCLoopFindTopologies`Private`i], 
         {FeynCalc`FCLoopFindTopologies`Private`i, 1, 
          Length[FeynCalc`FCLoopFindTopologies`Private`realTopologies] - 
           Length[
            FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies]}]\
, _, Message[FCLoopFindTopologies::failmsg, 
         "Unknown value of the Names option."]; Abort[]]; 
      If[FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies =!= 
         {} && 
        Sort[Join[
           FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies, 
           FeynCalc`FCLoopFindTopologies`Private`newNames]] =!= 
         Union[
          FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies, 
          FeynCalc`FCLoopFindTopologies`Private`newNames], 
       Message[FCLoopFindTopologies::failmsg, "Some names of the preferred \
topologies collide with the names of the new identified topologies."]; 
        Abort[]]; FeynCalc`FCLoopFindTopologies`Private`oldNames = 
       SelectFree[First /@ 
         FeynCalc`FCLoopFindTopologies`Private`realTopologies, 
        FeynCalc`FCLoopFindTopologies`Private`namesPreferredTopologies]; 
      FeynCalc`FCLoopFindTopologies`Private`ruleNames = 
       Thread[FeynCalc`FCLoopFindTopologies`Private`oldNames -> 
         FeynCalc`FCLoopFindTopologies`Private`newNames]; 
      FeynCalc`FCLoopFindTopologies`Private`finalTopologies = 
       FeynCalc`FCLoopFindTopologies`Private`realTopologies /. 
        Dispatch[FeynCalc`FCLoopFindTopologies`Private`ruleNames]; 
      If[Intersection[First /@ 
          FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
         FeynCalc`FCLoopFindTopologies`Private`oldNames] =!= {}, 
       Message[FCLoopFindTopologies::failmsg, 
         "The final list of the topologies still contains temporary names."]; 
        Abort[]]; FCPrint[1, "FCLoopFindTopologies: Done intorducing the \
final names for the identified topologies, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFindTopologies`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      If[OptionValue[MomentumCombine], 
       FeynCalc`FCLoopFindTopologies`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopFindTopologies: Applying MomentumCombine.", 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
        FeynCalc`FCLoopFindTopologies`Private`finalTopologies = 
         MomentumCombine[
          FeynCalc`FCLoopFindTopologies`Private`finalTopologies, FCI -> True, 
          FV -> False, LC -> False, FCParallelize -> 
           FeynCalc`FCLoopFindTopologies`Private`optFCParallelize]; 
        FCPrint[1, 
         "FCLoopFindTopologies: Done applying MomentumCombine, timing: ", 
         N[AbsoluteTime[] - FeynCalc`FCLoopFindTopologies`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; ]; 
      FCPrint[3, 
       "FCLoopFindTopologies: Final list of the identified topologies: ", 
       FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
       FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      If[ !OptionValue[FCLoopScalelessQ], 
       FeynCalc`FCLoopFindTopologies`Private`time = AbsoluteTime[]; 
        FCPrint[1, "FCLoopFindTopologies: Identifying scaleless topologies.", 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
        If[ !FreeQ[FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
           GenericPropagatorDenominator], FCPrint[0, "FCLoopFindTopologies: \
Some topology candidates contain GFADs. To avoid false positives, those will \
not be checked with FCLoopScalelessQ.", FCDoControl -> 
            FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
          FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckLhs = 
           SelectFree[FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
            GenericPropagatorDenominator], 
         FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckLhs = 
          FeynCalc`FCLoopFindTopologies`Private`finalTopologies]; 
        If[FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckLhs =!= 
          {}, FeynCalc`FCLoopFindTopologies`Private`time0 = AbsoluteTime[]; 
          If[$ParallelizeFeynCalc && 
            FeynCalc`FCLoopFindTopologies`Private`optFCParallelize, 
           FCPrint[1, 
             "FCLoopFindTopologies: Applying FCLoopScalelessQ in parallel.", 
             FCDoControl -> 
              FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
            FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckRhs = 
             ParallelMap[FCLoopScalelessQ[#1] & , 
              FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckLhs, 
              DistributedContexts -> None, Method -> "ItemsPerEvaluation" -> 
                Ceiling[N[Length[
                     FeynCalc`FCLoopFindTopologies`Private`finalTopologiesChe\
ckLhs]/$KernelCount]/10]], FCPrint[1, 
             "FCLoopFindTopologies: Applying FCLoopScalelessQ.", 
             FCDoControl -> 
              FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
            FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckRhs = 
             FCLoopScalelessQ /@ 
              FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckLhs]; 
          FCPrint[1, 
           "FCLoopFindTopologies: Done applying FCLoopScalelessQ, timing: ", 
           N[AbsoluteTime[] - FeynCalc`FCLoopFindTopologies`Private`time0, 
            4], FCDoControl -> 
            FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
          FeynCalc`FCLoopFindTopologies`Private`scalelessTopologies = 
           Thread[
             FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckLhs -> 
              FeynCalc`FCLoopFindTopologies`Private`finalTopologiesCheckRhs] \
/. {(_FCTopology -> False) :> Unevaluated[Sequence[]], 
             (FeynCalc`FCLoopFindTopologies`Private`a_FCTopology -> True) :> 
              First[FeynCalc`FCLoopFindTopologies`Private`a]}, 
         FeynCalc`FCLoopFindTopologies`Private`scalelessTopologies = {}]; 
        If[FeynCalc`FCLoopFindTopologies`Private`scalelessTopologies =!= {}, 
         FCPrint[2, "FCLoopFindTopologies: Follwing identified topologies are \
scaleless and will be set to zero: ", First /@ SelectNotFree[
             FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
             FeynCalc`FCLoopFindTopologies`Private`scalelessTopologies], 
           FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
          FeynCalc`FCLoopFindTopologies`Private`finalTopologies = 
           SelectFree[FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
            FeynCalc`FCLoopFindTopologies`Private`scalelessTopologies]; 
          FeynCalc`FCLoopFindTopologies`Private`ruleScalelessTopologies = 
           (GLI[#1, _] -> 0 & ) /@ 
            FeynCalc`FCLoopFindTopologies`Private`scalelessTopologies]; 
        FCPrint[1, "FCLoopFindTopologies: Done identifying scaleless \
topologies, timing: ", N[AbsoluteTime[] - 
           FeynCalc`FCLoopFindTopologies`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; ]; 
      FeynCalc`FCLoopFindTopologies`Private`time = AbsoluteTime[]; 
      FCPrint[1, "FCLoopFindTopologies: Assembling the final result.", 
       FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      FeynCalc`FCLoopFindTopologies`Private`exFinal = 
       FeynCalc`FCLoopFindTopologies`Private`denFreePart + 
           FeynCalc`FCLoopFindTopologies`Private`denPart /. 
          Dispatch[FeynCalc`FCLoopFindTopologies`Private`finalRule] /. 
         Dispatch[FeynCalc`FCLoopFindTopologies`Private`ruleNames] /. 
        Dispatch[
         FeynCalc`FCLoopFindTopologies`Private`ruleScalelessTopologies]; 
      FCPrint[1, 
       "FCLoopFindTopologies: Done assembling the final result, timing: ", 
       N[AbsoluteTime[] - FeynCalc`FCLoopFindTopologies`Private`time, 4], 
       FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      If[FeynCalc`FCLoopFindTopologies`Private`optCollecting, 
       FeynCalc`FCLoopFindTopologies`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "FCLoopFindTopologies: Collecting w.r.t the unique denominators.", 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
        FeynCalc`FCLoopFindTopologies`Private`exFinal = 
         Collect2[FeynCalc`FCLoopFindTopologies`Private`exFinal, GLI, 
          Factoring -> FeynCalc`FCLoopFindTopologies`Private`optFactoring, 
          IsolateNames -> OptionValue[IsolateNames], IsolateFast -> 
           OptionValue[IsolateFast], Head -> 
           FeynCalc`FCLoopFindTopologies`Private`optHead]; 
        FCPrint[1, "FCLoopFindTopologies: Done collecting w.r.t the unique \
denominators, timing: ", N[AbsoluteTime[] - 
           FeynCalc`FCLoopFindTopologies`Private`time, 4], 
         FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]]; 
      If[Head[FeynCalc`FCLoopFindTopologies`Private`ex] =!= List && 
        Head[FeynCalc`FCLoopFindTopologies`Private`exFinal] === List && 
        Length[FeynCalc`FCLoopFindTopologies`Private`exFinal] === 1, 
       FeynCalc`FCLoopFindTopologies`Private`exFinal = 
        First[FeynCalc`FCLoopFindTopologies`Private`exFinal]]; 
      FCPrint[0, "FCLoopFindTopologies: ", FeynCalc`Package`FCStyle[
        "Final number of found topologies: ", {Darker[Green, 0.55], Bold}], 
       Length[FeynCalc`FCLoopFindTopologies`Private`finalTopologies], 
       FCDoControl -> FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      FeynCalc`FCLoopFindTopologies`Private`res = 
       {FeynCalc`FCLoopFindTopologies`Private`exFinal, 
         FeynCalc`FCLoopFindTopologies`Private`finalTopologies} /. 
        FeynCalc`FCLoopFindTopologies`Private`topoName -> Identity; 
      If[OptionValue[FCLoopGetKinematicInvariants], 
       FeynCalc`FCLoopFindTopologies`Private`kinInvs = 
         Union[Flatten[FCLoopGetKinematicInvariants[
            FeynCalc`FCLoopFindTopologies`Private`finalTopologies, 
            FCFeynmanPrepare ->  !OptionValue["NonstandardPropagators"]]]]; 
        If[FeynCalc`FCLoopFindTopologies`Private`kinInvs =!= {}, 
         FeynCalc`FCLoopFindTopologies`Private`check = ToString /@ 
            FeynCalc`FCLoopFindTopologies`Private`kinInvs; 
          If[ !MatchQ[LowerCaseQ /@ StringReplace[
               FeynCalc`FCLoopFindTopologies`Private`check, "1" | "2" | "3" | 
                 "4" | "5" | "6" | "7" | "8" | "9" | "0" -> ""], {True...}], 
           FCPrint[0, "FCLoopFindTopologies: ", FeynCalc`Package`FCStyle["You\
r topologies depend on the follwing kinematic invariants that are not all \
entirely lowercase: ", {Darker[Yellow, 0.55], Bold}], 
             FeynCalc`FCLoopFindTopologies`Private`check, FCDoControl -> 
              FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
            FCPrint[0, "FCLoopFindTopologies: ", FeynCalc`Package`FCStyle["Th\
is may lead to issues if these topologies are meant to be processed using \
tools such as FIRE, KIRA or Fermat.", {Darker[Yellow, 0.55], Bold}], 
             FCDoControl -> 
              FeynCalc`FCLoopFindTopologies`Private`optVerbose]; ]; ]; ]; 
      If[OptionValue[FCE], FeynCalc`FCLoopFindTopologies`Private`res = 
        FCE[FeynCalc`FCLoopFindTopologies`Private`res]]; 
      FCPrint[1, "FCLoopFindTopologies: Leaving.", FCDoControl -> 
        FeynCalc`FCLoopFindTopologies`Private`optVerbose]; 
      FeynCalc`FCLoopFindTopologies`Private`res]
 
Options[FCLoopFindTopologies] = {Collecting -> True, ExtraPropagators -> {}, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCParallelize -> True, FCLoopBasisOverdeterminedQ -> True, 
     FCLoopGetKinematicInvariants -> True, FCLoopIsolate -> True, 
     FCLoopScalelessQ -> False, FCVerbose -> False, FDS -> True, 
     Factoring -> False, FinalSubstitutions -> {}, 
     Head -> {Identity, FCGV["GLIProduct"]}, IsolateFast -> False, 
     IsolateNames -> False, MomentumCombine -> True, Names -> "fctopology", 
     "NonstandardPropagators" -> False, Ordering -> {}, 
     PreferredTopologies -> {}, SetDimensions -> {D}}
 
FCLoopFindTopologies /: FCLoopFindTopologies::failmsg = "Error! \
FCLoopFindTopologies has encountered a fatal problem and must abort the \
computation. \n\nThe problem reads: `1`"
 
FCLoopFindTopologies /: FCLoopFindTopologies::usage = "FCLoopFindTopologies[e\
xp, {q1, q2, ...}] attempts to identify the loop\nintegral topologies present \
in exp by looking at the propagator denominators\nthat depend on the loop \
momenta q1, q2, ... . It returns a list of two\nentries, where the first one \
is the original expression with the denominators\nrewritten as GLIs, and the \
second one is the set of the identified topologies.\n\nEach of the identified \
topologies must contain linearly independent\npropagators (unless the option \
FCLoopBasisOverdeterminedQ is set to True), but\nmay lack propagators needed \
to form a complete basis.\n\nScaleless topologies are automatically removed, \
but this can be disabled by\nsetting the option FCLoopScalelessQ to True."
 
PreferredTopologies /: PreferredTopologies::usage = "PreferredTopologies is \
an option for FCLoopFindTopologies,\nFCLoopFindTopologyMappings and other \
related functions. It allows to specify a\nlist of topologies onto which the \
occurring topologies should be preferably\nmapped."
 
Rename /: Rename::usage = "Rename is an option for Contract. If set to True, \
dummy indices in Eps are\nrenamed, using $MU[i]."
 
DetectLoopTopologies /: DetectLoopTopologies::usage = "DetectLoopTopologies \
is an option for FDS. If set to True, FDS will try to\nrecognize some special \
multiloop topologies and apply appropriate\nsimplifications"
 
FeynCalc`FCLoopFindTopologies`Private`selectMembers[
     FeynCalc`FCLoopFindTopologies`Private`small_List, 
     FeynCalc`FCLoopFindTopologies`Private`large_List] := 
    Select[FeynCalc`FCLoopFindTopologies`Private`small, 
     MemberQ[FeynCalc`FCLoopFindTopologies`Private`large, #1] & ]
 
FeynCalc`FCLoopFindTopologies`Private`orderedSelectNotFree[_List, {}] := {}
 
FeynCalc`FCLoopFindTopologies`Private`orderedSelectNotFree[
     FeynCalc`FCLoopFindTopologies`Private`props_List, 
     FeynCalc`FCLoopFindTopologies`Private`names_List] := 
    Flatten[Join[(SelectNotFree[FeynCalc`FCLoopFindTopologies`Private`props, 
          #1] & ) /@ FeynCalc`FCLoopFindTopologies`Private`names], 1] /; 
     FeynCalc`FCLoopFindTopologies`Private`names =!= {}
 
FCLoopBasisOverdeterminedQ[FeynCalc`FCLoopBasisOverdeterminedQ`Private`topos:
      {__FCTopology}, FeynCalc`FCLoopBasisOverdeterminedQ`Private`opts:
      OptionsPattern[]] := (FCLoopBasisOverdeterminedQ[#1, 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`opts] & ) /@ 
     FeynCalc`FCLoopBasisOverdeterminedQ`Private`topos
 
FCLoopBasisOverdeterminedQ[
     FeynCalc`FCLoopBasisOverdeterminedQ`Private`topoRaw_FCTopology, 
     FeynCalc`FCLoopBasisOverdeterminedQ`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions}, 
     If[OptionValue[FCI], FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo = 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`topoRaw, 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo = 
        FCI[FeynCalc`FCLoopBasisOverdeterminedQ`Private`topoRaw]]; 
      If[ !FCLoopValidTopologyQ[
         FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo], 
       Message[FCLoopBasisOverdeterminedQ::failmsg, 
         "The supplied topology is incorrect."]; Abort[]]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions = 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo[[5]]; 
      FCLoopBasisOverdeterminedQ[Times @@ 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo[[2]], 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`topo[[3]], 
       Join[{FCI -> True, InitialSubstitutions -> 
          FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions}\
, FilterRules[{FeynCalc`FCLoopBasisOverdeterminedQ`Private`opts}, 
         Except[FCI | InitialSubstitutions]]]]]
 
FCLoopBasisOverdeterminedQ[FeynCalc`FCLoopBasisOverdeterminedQ`Private`expr_, 
     FeynCalc`FCLoopBasisOverdeterminedQ`Private`lmoms_List, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`ca, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`res, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`dims, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`lmomSP, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`check, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`hRule, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs12New, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`nlCoeffs, 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose = 
        $VeryVerbose, If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions = 
       OptionValue[InitialSubstitutions]; 
      If[FreeQ2[FeynCalc`FCLoopBasisOverdeterminedQ`Private`expr, 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`lmoms], 
       Message[FCLoopBasisOverdeterminedQ::failmsg, 
         "The input expression does not depend on the given loop momenta."]; 
        Abort[]]; If[ !OptionValue[FCI], 
       {FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex, 
         FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions} \
= FCI[{FeynCalc`FCLoopBasisOverdeterminedQ`Private`expr, 
          FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions}\
], FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex = 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`expr]; 
      If[ !MatchQ[FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex, 
         (_.)*_FeynAmpDenominator], Message[FCLoopBasisOverdeterminedQ::fail, 
         ToString[FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex, 
          InputForm]]; Abort[]]; FCPrint[3, 
       "FCLoopBasisOverdeterminedQ: Entering with: ", 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex, 
       FCDoControl -> 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose]; 
      FCPrint[3, "FCLoopBasisOverdeterminedQ: Loop momenta: ", 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`lmoms, 
       FCDoControl -> 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs = 
       FCLoopBasisExtract[FeynCalc`FCLoopBasisOverdeterminedQ`Private`ex, 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`lmoms, 
        SetDimensions -> OptionValue[SetDimensions], Rest -> False]; 
      FCPrint[3, 
       "FCLoopBasisOverdeterminedQ: Output of extractBasisVectors: ", 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs, 
       FCDoControl -> 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs = 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs /. 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`optInitialSubstitutions; 
      FCPrint[3, 
       "FCLoopBasisOverdeterminedQ: Vectors after applying substitutions: ", 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs, 
       FCDoControl -> 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`nlCoeffs = 
       Select[FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs[[2]], 
         !MemberQ[{Pair, CartesianPair, TemporalPair}, Head[#1]] & ]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`hRule = 
       (#1 -> Unique["caVar"] & ) /@ 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`nlCoeffs; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs12New = 
       {FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs[[1]] //. 
         FeynCalc`FCLoopBasisOverdeterminedQ`Private`hRule, 
        Join[Complement[FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs[[
           2]], FeynCalc`FCLoopBasisOverdeterminedQ`Private`nlCoeffs], 
         Last /@ FeynCalc`FCLoopBasisOverdeterminedQ`Private`hRule]}; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`ca = 
       Normal[CoefficientArrays @@ 
         FeynCalc`FCLoopBasisOverdeterminedQ`Private`vecs12New]; 
      FCPrint[3, "FCLoopBasisOverdeterminedQ: Output of CoefficientArrays: ", 
       FeynCalc`FCLoopBasisOverdeterminedQ`Private`ca, 
       FCDoControl -> 
        FeynCalc`FCLoopBasisOverdeterminedQ`Private`fclbVerbose]; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`res = 
       NullSpace[Transpose[Last[
           FeynCalc`FCLoopBasisOverdeterminedQ`Private`ca]]] =!= {}; 
      FeynCalc`FCLoopBasisOverdeterminedQ`Private`res]
 
Options[FCLoopBasisOverdeterminedQ] = {FeynCalcInternal -> False, 
     FCVerbose -> False, InitialSubstitutions -> {}, 
     SetDimensions -> {3, 4, D, -1 + D}}
 
FCLoopBasisOverdeterminedQ /: FCLoopBasisOverdeterminedQ::failmsg = "Error! \
FCLoopBasisOverdeterminedQ has encountered a fatal problem and must abort the \
computation. The problem reads: `1`"
 
FCLoopBasisOverdeterminedQ /: FCLoopBasisOverdeterminedQ::usage = "FCLoopBasi\
sOverdeterminedQ[int, {q1, q2, ...}] checks whether the loop\nintegral or \
topology int contains linearly dependent propagators.\n\nThe input can also \
consist of an FCTopology object or a list thereof."
 
InitialSubstitutions /: InitialSubstitutions::usage = "InitialSubstitutions \
is an option for various functions. All substitutions\nindicated hereby are \
done before the calculation."
 
FCGetScalarProducts[{}, OptionsPattern[]] := {}
 
FCGetScalarProducts[{FeynCalc`FCGetScalarProducts`Private`moms__}, 
     OptionsPattern[]] := Block[{FeynCalc`FCGetScalarProducts`Private`spList, 
      FeynCalc`FCGetScalarProducts`Private`res, 
      FeynCalc`FCGetScalarProducts`Private`mom1, 
      FeynCalc`FCGetScalarProducts`Private`mom2, 
      FeynCalc`FCGetScalarProducts`Private`pattern, 
      FeynCalc`FCGetScalarProducts`Private`listHold, 
      FeynCalc`FCGetScalarProducts`Private`ruleDelayed, 
      FeynCalc`FCGetScalarProducts`Private`optSetDimensions, 
      FeynCalc`FCGetScalarProducts`Private`spRules, 
      FeynCalc`FCGetScalarProducts`Private`cspRules}, 
     FeynCalc`FCGetScalarProducts`Private`optSetDimensions = 
       OptionValue[SetDimensions]; 
      FeynCalc`FCGetScalarProducts`Private`spList = 
       SelectNotFree[$ScalarProducts, 
        FeynCalc`FCGetScalarProducts`Private`moms]; 
      FeynCalc`FCGetScalarProducts`Private`spRules = 
       (FeynCalc`FCGetScalarProducts`Private`ruleDelayed[
            {Momentum[FeynCalc`FCGetScalarProducts`Private`pattern[
               FeynCalc`FCGetScalarProducts`Private`mom1, _], ___], 
             Momentum[FeynCalc`FCGetScalarProducts`Private`pattern[
               FeynCalc`FCGetScalarProducts`Private`mom2, _], ___]}, 
            Hold[Pair][Momentum[FeynCalc`FCGetScalarProducts`Private`mom1, 
              #1], Momentum[FeynCalc`FCGetScalarProducts`Private`mom2, 
              #1]]] & ) /@ 
          FeynCalc`FCGetScalarProducts`Private`optSetDimensions /. 
         FeynCalc`FCGetScalarProducts`Private`pattern -> Pattern /. 
        FeynCalc`FCGetScalarProducts`Private`ruleDelayed -> RuleDelayed; 
      FeynCalc`FCGetScalarProducts`Private`cspRules = 
       (FeynCalc`FCGetScalarProducts`Private`ruleDelayed[
             {CartesianMomentum[FeynCalc`FCGetScalarProducts`Private`pattern[
                FeynCalc`FCGetScalarProducts`Private`mom1, _], ___], 
              CartesianMomentum[FeynCalc`FCGetScalarProducts`Private`pattern[
                FeynCalc`FCGetScalarProducts`Private`mom2, _], ___]}, 
             Hold[CartesianPair][CartesianMomentum[
               FeynCalc`FCGetScalarProducts`Private`mom1, #1], 
              CartesianMomentum[FeynCalc`FCGetScalarProducts`Private`mom2, 
               #1]]] & ) /@ 
           FeynCalc`FCGetScalarProducts`Private`optSetDimensions /. 
          FeynCalc`FCGetScalarProducts`Private`pattern -> Pattern /. 
         FeynCalc`FCGetScalarProducts`Private`ruleDelayed -> RuleDelayed /. 
        {CartesianMomentum[FeynCalc`FCGetScalarProducts`Private`x_, 
           _Symbol] -> CartesianMomentum[
           FeynCalc`FCGetScalarProducts`Private`x, _Symbol - 1], 
         CartesianMomentum[FeynCalc`FCGetScalarProducts`Private`x_, 4] -> 
          CartesianMomentum[FeynCalc`FCGetScalarProducts`Private`x, 3]}; 
      FeynCalc`FCGetScalarProducts`Private`res = 
       Flatten[SelectNotFree[(FeynCalc`FCGetScalarProducts`Private`spList /. 
            #1 & ) /@ Join[FeynCalc`FCGetScalarProducts`Private`spRules, 
           FeynCalc`FCGetScalarProducts`Private`cspRules], 
         {Hold[Pair], Hold[CartesianPair]}]]; 
      FeynCalc`FCGetScalarProducts`Private`res = 
       Select[FeynCalc`FCGetScalarProducts`Private`res, 
         !MemberQ[{Pair, CartesianPair}, Head[FRH[#1]]] & ]; 
      FeynCalc`FCGetScalarProducts`Private`res = (#1 -> FRH[#1] & ) /@ 
        FeynCalc`FCGetScalarProducts`Private`res; 
      FeynCalc`FCGetScalarProducts`Private`res]
 
Options[FCGetScalarProducts] = {SetDimensions -> {4, D}}
 
FCGetScalarProducts /: FCGetScalarProducts::usage = "FCGetScalarProducts[{p1, \
p2, ...}] returns all scalar products involving\nexternal momenta p1, p2, ... \
that were set using down values.\n\nUsing the option SetDimensions one can \
specify the dimensions of scalar\nproducts one is interested in."
 
FeynCalc`FCLoopFindTopologies`Private`findSubtopologies[
     FeynCalc`FCLoopFindTopologies`Private`currTopo_, 
     FeynCalc`FCLoopFindTopologies`Private`list_] := 
    (If[SubsetQ[#1[[2]], FeynCalc`FCLoopFindTopologies`Private`currTopo[[
          2]]] === True, #1, Unevaluated[Sequence[]]] & ) /@ 
     FeynCalc`FCLoopFindTopologies`Private`list
 
FCLoopCreateRuleGLIToGLI[{}, {}, OptionsPattern[]] := {}
 
FCLoopCreateRuleGLIToGLI[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopos:
      {__FCTopology}, FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopos:
      {{__FCTopology}..}, FeynCalc`FCLoopCreateRuleGLIToGLI`Private`opts:
      OptionsPattern[]] := MapThread[FCLoopCreateRuleGLIToGLI[#1, #2, 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`opts] & , 
     {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopos, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopos}, 
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`opts]
 
FCLoopCreateRuleGLIToGLI[
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo_FCTopology, 
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopos:{__FCTopology}, 
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`opts:OptionsPattern[]] := 
    (FCLoopCreateRuleGLIToGLI[
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo, #1, 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`opts] & ) /@ 
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopos
 
FCLoopCreateRuleGLIToGLI[
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo_FCTopology, 
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo_FCTopology, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainName, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subName, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainLen, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subLen, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`pattern, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`lhs, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rhs, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rule, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`ruleDelayed, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`checkGLI, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`checkNew, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`checkOld, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`optReverse, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopoName, 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopoName}, 
     FeynCalc`FCLoopCreateRuleGLIToGLI`Private`optReverse = 
       OptionValue[Reverse]; If[OptionValue[FCVerbose] === False, 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose = 
          OptionValue[FCVerbose]]; ]; 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopoName = 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo[[1]]; 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopoName = 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo[[1]]; 
      FCPrint[1, "FCLoopCreateRuleGLIToGLI: Entering.", 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      FCPrint[3, "FCLoopCreateRuleGLIToGLI: Entering with: Main topology: ", 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo, 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      FCPrint[3, "FCLoopCreateRuleGLIToGLI: Entering with: Subtopology: ", 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo, 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainName, 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subName} = 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo[[1]], 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo[[1]]}; 
      {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics, 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics} = 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo[[5]], 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo[[5]]}; 
      If[ !OptionValue[FCI], 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics} = 
        FCI[{FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo[[2]], 
          FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo[[2]], 
          FRH[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics], 
          FRH[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics]}], 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics} = 
        {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopo[[2]], 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopo[[2]], 
         FRH[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics], 
         FRH[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics]}]; 
      If[OptionValue[ToSFAD], 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps} = 
        ToSFAD[{FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
          FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps}, FCI -> True]]; 
      If[OptionValue[FeynAmpDenominatorExplicit], 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps} = 
        FeynAmpDenominatorExplicit[
         {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
          FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps}, FCI -> True], 
       If[OptionValue[MomentumExpand], 
         {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps} = 
          MomentumExpand[
           {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
            FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps}]]; 
        If[OptionValue[ExpandScalarProduct], 
         {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps} = 
          ExpandScalarProduct[
           {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
            FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps}, 
           FCI -> True]]; ]; 
      {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps} = 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps /. 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainKinematics, 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps /. 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subKinematics}; 
      FCPrint[3, 
       "FCLoopCreateRuleGLIToGLI: Main topology after all simplifications: ", 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      FCPrint[3, 
       "FCLoopCreateRuleGLIToGLI: Subtopology  after all simplifications: ", 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps, 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      If[OptionValue[Expanding], 
       {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps} = 
        ExpandAll[{FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
          FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps}]]; 
      {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainLen, 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subLen} = 
       Length /@ {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps}; 
      If[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainName === 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subName, 
       Message[FCLoopCreateRuleGLIToGLI::failmsg, 
         "The two topologies may not have identical IDs."]; Abort[]]; 
      If[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainLen === 0 || 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subLen === 0, 
       Message[FCLoopCreateRuleGLIToGLI::failmsg, 
         "Empty topologies are not allowed."]; Abort[]]; 
      If[ !OptionValue[FeynAmpDenominatorExplicit], 
       If[
        Union[Head /@ 
            FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps] =!= 
          {FeynAmpDenominator} || 
         Union[Head /@ 
            FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps] =!= 
          {FeynAmpDenominator}, Message[FCLoopCreateRuleGLIToGLI::failmsg, 
          "The FCTopology format is not correct."]; Abort[]]]; 
      If[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subLen > 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainLen, 
       Message[FCLoopCreateRuleGLIToGLI::failmsg, StringJoin[
          "The subtopology ", ToString[
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopoName], 
          " may not be larger than the main topology ", 
          ToString[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopoName]]]; 
        Abort[]]; 
      If[Union[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps] =!= 
        Sort[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps], 
       Message[FCLoopCreateRuleGLIToGLI::failmsg, StringJoin[
          "The subtopology ", ToString[
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopoName], 
          " may not contain duplicate entries."]]; Abort[]]; 
      If[Union[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps] =!= 
        Sort[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps], 
       Message[FCLoopCreateRuleGLIToGLI::failmsg, StringJoin[
          "The main topology ", ToString[
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopoName], 
          " may not contain duplicate entries."]]; Abort[]]; 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList = 
       (Position[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainProps, 
          #1] & ) /@ FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subProps; 
      FCPrint[3, "FCLoopCreateRuleGLIToGLI: List of positions: ", 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList, 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      If[ !MatchQ[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList, 
          {{{_Integer?Positive}}..}] || 
        Length[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList] =!= 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subLen, 
       Message[FCLoopCreateRuleGLIToGLI::failmsg, StringJoin[
          "The subtopology ", ToString[
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subTopoName], 
          " does not fit into the main topology ", 
          ToString[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainTopoName]]]; 
        Abort[]]; FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList = 
       Flatten[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList]; 
      If[TrueQ[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`optReverse], 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`lhs = 
         GLI[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainName, 
           Table[If[MemberQ[
              FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList, 
              FeynCalc`FCLoopCreateRuleGLIToGLI`Private`i], 
             FeynCalc`FCLoopCreateRuleGLIToGLI`Private`pattern[
              ToExpression[StringJoin["n", ToString[
                 FeynCalc`FCLoopCreateRuleGLIToGLI`Private`i]]], _], 0], 
            {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`i, 1, 
             FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainLen}]] /. 
          FeynCalc`FCLoopCreateRuleGLIToGLI`Private`pattern -> Pattern; 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rhs = 
         GLI[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subName, 
          (ToExpression[StringJoin["n", ToString[#1]]] & ) /@ 
           FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList], 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`lhs = 
         GLI[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`subName, 
           (FeynCalc`FCLoopCreateRuleGLIToGLI`Private`pattern[
              ToExpression[StringJoin["n", ToString[#1]]], _] & ) /@ 
            FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList] /. 
          FeynCalc`FCLoopCreateRuleGLIToGLI`Private`pattern -> Pattern; 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rhs = 
         GLI[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainName, 
          Table[If[MemberQ[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`posList, 
             FeynCalc`FCLoopCreateRuleGLIToGLI`Private`i], 
            ToExpression[StringJoin["n", ToString[
               FeynCalc`FCLoopCreateRuleGLIToGLI`Private`i]]], 0], 
           {FeynCalc`FCLoopCreateRuleGLIToGLI`Private`i, 1, 
            FeynCalc`FCLoopCreateRuleGLIToGLI`Private`mainLen}]]]; 
      FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rule = 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`ruleDelayed[
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`lhs, 
         FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rhs] /. 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`ruleDelayed -> RuleDelayed; 
      FCPrint[3, "FCLoopCreateRuleGLIToGLI: The obtained replacement rule: ", 
       FeynCalc`FCLoopCreateRuleGLIToGLI`Private`rule, 
       FCDoControl -> 
        FeynCalc`FCLoopCreateRuleGLIToGLI`Private`crgtgVerbose]; 
      If[TrueQ[FeynCalc`FCLoopCreateRuleGLIToGLI`Private`optReverse], 
