       {FeynCalc`FCLoopSplit`Private`loopFree, 
        FeynCalc`FCLoopSplit`Private`loopScalar, 
        FeynCalc`FCLoopSplit`Private`loopTensorQP, 
        FeynCalc`FCLoopSplit`Private`loopTensorFreeInd}; 
      If[OptionValue[FCE], FeynCalc`FCLoopSplit`Private`res = 
        FCE[FeynCalc`FCLoopSplit`Private`res]]; 
      FeynCalc`FCLoopSplit`Private`res]
 
Options[FCLoopSplit] = {Collecting -> True, DiracGammaExpand -> True, 
     DotSimplify -> True, Expanding -> True, Factoring -> {Factor2, 5000}, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     PaVeIntegralHeads -> FeynCalc`Package`PaVeHeadsList, 
     TimeConstrained -> 3}
 
FCLoopSplit /: FCLoopSplit::failmsg = 
     "Splitting the expression `1` into loop and non-loop pieces failed!"
 
FCLoopSplit /: FCLoopSplit::usage = "FCLoopSplit[exp, {q1, q2, ...}] \
separates exp into the following four pieces: \n\n1) terms that are free of \
loop integrals\n\n2) terms with scalar loop integrals\n\n3) terms with tensor \
loop integrals, where all loop momenta are contracted\n\n4) terms with tensor \
loop integrals, where at least some loop momenta have\nfree indices\n\nThe \
result is returned as a list with the 4 above elements."
 
FCLoopRemoveNegativePropagatorPowers[
     FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`expr_, 
     OptionsPattern[]] := 
    Block[{FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex, 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`res, 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsList, 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsListEval, 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`repRule, 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fad}, 
     If[OptionValue[FCI], 
       FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex = 
        FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`expr, 
       FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex = 
        FCI[FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`expr]]; 
      If[OptionValue[FCLoopPropagatorPowersCombine], 
       FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex = 
        FCLoopPropagatorPowersCombine[
         FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex, 
         FCI -> True]]; 
      If[FreeQ2[FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex, 
        {StandardPropagatorDenominator, CartesianPropagatorDenominator, 
         GenericPropagatorDenominator}], 
       Return[FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex]]; 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsList = 
       Cases2[FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex, 
        FeynAmpDenominator]; 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsListEval = 
       FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsList /. 
           FeynAmpDenominator -> 
            FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fad /. 
          {FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fad[
              FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`a___, 
              (FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`h:
                StandardPropagatorDenominator | 
                 CartesianPropagatorDenominator | 
                 GenericPropagatorDenominator)[
               FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`x__, {
                FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`n_Integ\
er, FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`s_}], 
              FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`b___] /; 
             FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`n < 0 :> 
            FeynAmpDenominatorExplicit[FeynAmpDenominator[
               FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`h[
                FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`x, 
                {FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`n, 
                 FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`s}]], 
              FCI -> True]*
             FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fad[
              FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`a, 
              FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`b]} /. 
         FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fad[] -> 1 /. 
        FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fad -> 
         FeynAmpDenominator; 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`repRule = 
       Thread[
        FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsList -> 
         FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`fadsListEval]; 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`res = 
       FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`ex /. 
        Dispatch[FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`repRul\
e]; If[OptionValue[FCE], 
       FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`res = 
        FCE[FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`res]]; 
      FeynCalc`FCLoopRemoveNegativePropagatorPowers`Private`res]
 
Options[FCLoopRemoveNegativePropagatorPowers] = {FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCLoopPropagatorPowersCombine -> True}
 
FCLoopRemoveNegativePropagatorPowers /: 
    FCLoopRemoveNegativePropagatorPowers::failmsg = "FCLoopRemoveNegativeProp\
agatorPowers has encountered a fatal problem and must abort the computation. \
The problem reads: `1`"
 
FCLoopRemoveNegativePropagatorPowers /: 
    FCLoopRemoveNegativePropagatorPowers::usage = "FCLoopRemoveNegativePropag\
atorPowers[exp] rewrites propagators raised to\ninteger powers as products."
 
FCProgressBar[FeynCalc`SharedTools`Private`text_String, 
     FeynCalc`SharedTools`Private`i_Integer, 
     FeynCalc`SharedTools`Private`tot_Integer] := 
    FCPrint[0, StringJoin[FeynCalc`SharedTools`Private`text, 
      ToString[FeynCalc`SharedTools`Private`i], " / ", 
      ToString[FeynCalc`SharedTools`Private`tot], "\n"], 
     UseWriteString -> True]
 
FCProgressBar /: FCProgressBar::usage = "FCProgressBar[text, i, total]  is a \
simple auxiliary function that can be used\nto display the progress of a \
certain evaluation, e.g. mapping a list of\nintegrals to some function. Here \
i is the number of the current step while\ntotal denotes the overall number \
of steps."
 
FCApart[FeynCalc`FCApart`Private`expr_, FeynCalc`FCApart`Private`lmoms_List, 
     FeynCalc`FCApart`Private`opts:OptionsPattern[]] := 
    FCApart[FeynCalc`FCApart`Private`expr, 1, FeynCalc`FCApart`Private`lmoms, 
     FeynCalc`FCApart`Private`opts]
 
FCApart[FeynCalc`FCApart`Private`expr_, FeynCalc`FCApart`Private`extraPiece_, 
     FeynCalc`FCApart`Private`lmoms_List, OptionsPattern[]] := 
    Block[{FeynCalc`FCApart`Private`ex, FeynCalc`FCApart`Private`vectorSet, 
       FeynCalc`FCApart`Private`res, FeynCalc`FCApart`Private`check, 
       FeynCalc`FCApart`Private`scalarTerm, 
       FeynCalc`FCApart`Private`vectorTerm = 1, 
       FeynCalc`FCApart`Private`pref = 1, FeynCalc`FCApart`Private`tmp, 
       FeynCalc`FCApart`Private`scaleless1 = 0, 
       FeynCalc`FCApart`Private`scaleless2 = 0, 
       FeynCalc`FCApart`Private`time, FeynCalc`FCApart`Private`optFactoring, 
       FeynCalc`FCApart`Private`optTimeConstrained, 
       FeynCalc`FCApart`Private`rd, FeynCalc`FCApart`Private`dt, 
       FeynCalc`FCApart`Private`extraTensors, 
       FeynCalc`FCApart`Private`optFDS, 
       FeynCalc`FCApart`Private`optDropScaleless, 
       FeynCalc`FCApart`Private`optFinalSubstitutions, 
       FeynCalc`FCApart`Private`optRandomPrime, FeynCalc`FCApart`Private`lhs, 
       FeynCalc`FCApart`Private`rhs, FeynCalc`FCApart`Private`vars, 
       FeynCalc`FCApart`Private`varsNum, FeynCalc`FCApart`Private`repRule, 
       FeynCalc`FCApart`Private`optCollecting}, 
      FeynCalc`FCApart`Private`optFDS = OptionValue[FDS]; 
       FeynCalc`FCApart`Private`optDropScaleless = 
        OptionValue[DropScaleless]; FeynCalc`FCApart`Private`counter = 
        OptionValue[MaxIterations]; FeynCalc`FCApart`Private`optFactoring = 
        OptionValue[Factoring]; FeynCalc`FCApart`Private`optTimeConstrained = 
        OptionValue[TimeConstrained]; 
       FeynCalc`FCApart`Private`optFinalSubstitutions = 
        OptionValue[FinalSubstitutions]; 
       FeynCalc`FCApart`Private`optRandomPrime = OptionValue[RandomPrime]; 
       FeynCalc`FCApart`Private`optCollecting = OptionValue[Collecting]; 
       If[OptionValue[FCVerbose] === False, 
        FeynCalc`FCApart`Private`fcaVerbose = $VeryVerbose, 
        If[MatchQ[OptionValue[FCVerbose], _Integer], 
          FeynCalc`FCApart`Private`fcaVerbose = OptionValue[FCVerbose]]; ]; 
       If[ !OptionValue[FCI], {FeynCalc`FCApart`Private`ex, 
          FeynCalc`FCApart`Private`optFinalSubstitutions} = 
         FCI[{FeynCalc`FCApart`Private`expr, 
           FRH[FeynCalc`FCApart`Private`optFinalSubstitutions]}], 
        {FeynCalc`FCApart`Private`ex, 
          FeynCalc`FCApart`Private`optFinalSubstitutions} = 
         {FeynCalc`FCApart`Private`expr, 
          FRH[FeynCalc`FCApart`Private`optFinalSubstitutions]}]; 
       FCPrint[3, "FCApart: Entering with: ", FeynCalc`FCApart`Private`ex, 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FCPrint[3, "FCApart: Extra piece: ", 
        FeynCalc`FCApart`Private`extraPiece, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       If[FeynCalc`FCApart`Private`extraPiece =!= 1, 
        FCPrint[1, "FCApart: extraPiece=!=1, disabling FDS and \
DropScaleless.", FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`optFDS = False; 
         FeynCalc`FCApart`Private`optDropScaleless = False; ]; 
       If[ !MatchQ[ExpandAll[FeynCalc`FCApart`Private`ex], 
           (_.)*FeynAmpDenominator[FeynCalc`FCApart`Private`y__] /; 
             !FreeQ2[{FeynCalc`FCApart`Private`y}, 
              FeynCalc`FCApart`Private`lmoms]] || 
         SelectFree[ExpandAll[FeynCalc`FCApart`Private`ex], 
           Sequence @@ FeynCalc`FCApart`Private`lmoms] =!= 1, 
        Message[FeynCalc`FCApart`Private`FCLoopBasis::fail, 
          ToString[FeynCalc`FCApart`Private`ex, InputForm]]; Abort[]]; 
       If[OptionValue[ExpandScalarProduct], FeynCalc`FCApart`Private`ex = 
         ExpandScalarProduct[FeynCalc`FCApart`Private`ex, FCI -> True]]; 
       If[ !FreeQ2[FeynCalc`FCApart`Private`ex, 
          {StandardPropagatorDenominator, CartesianPropagatorDenominator, 
           GenericPropagatorDenominator}], FeynCalc`FCApart`Private`ex = 
          FeynCalc`FCApart`Private`cancelSP[FeynCalc`FCApart`Private`ex]; 
         FeynCalc`FCApart`Private`ex = FeynCalc`FCApart`Private`ex /. 
           FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r___, 
              (FeynCalc`FCApart`Private`h:StandardPropagatorDenominator | 
                 CartesianPropagatorDenominator | 
                 GenericPropagatorDenominator)[FeynCalc`FCApart`Private`a__, {
                FeynCalc`FCApart`Private`n_, FeynCalc`FCApart`Private`s_}], 
              FeynCalc`FCApart`Private`t___] /; FeynCalc`FCApart`Private`n < 
              0 :> FeynCalc`FCApart`Private`fadHold[
              FeynCalc`FCApart`Private`r, FeynCalc`FCApart`Private`t]*
             FeynAmpDenominatorExplicit[FeynAmpDenominator[
               FeynCalc`FCApart`Private`h[FeynCalc`FCApart`Private`a, 
                {FeynCalc`FCApart`Private`n, FeynCalc`FCApart`Private`s}]], 
              FCI -> True, ExpandScalarProduct -> OptionValue[
                ExpandScalarProduct]]; FeynCalc`FCApart`Private`ex = 
          FeynCalc`FCApart`Private`ex /. FeynCalc`FCApart`Private`fadHold[
              ] -> 1 /. FeynCalc`FCApart`Private`fadHold -> 
            FeynAmpDenominator; FCPrint[3, 
          "FCApart: After the initial cancelling of scalar products ", 
          FeynCalc`FCApart`Private`ex, FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]]; 
       If[FeynCalc`FCApart`Private`optFDS, FeynCalc`FCApart`Private`ex = 
         FeynCalc`FCApart`Private`ex /. FeynAmpDenominator -> 
           FeynCalc`Package`feynsimp[FeynCalc`FCApart`Private`lmoms]]; 
       If[FreeQ2[FeynCalc`FCApart`Private`ex, 
         FeynCalc`FCApart`Private`lmoms], 
        FCPrint[3, 
          "FCApart: The intermediate expression contains no loop integrals ", 
          FeynCalc`FCApart`Private`ex, FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]; 
         If[FeynCalc`FCApart`Private`optDropScaleless, Return[0]]; 
         FeynCalc`FCApart`Private`ex = FeynCalc`FCApart`Private`ex*
           FeynCalc`FCApart`Private`extraPiece; If[OptionValue[FCE], 
          FeynCalc`FCApart`Private`ex = FCE[FeynCalc`FCApart`Private`ex]]; 
         Return[FeynCalc`FCApart`Private`ex]; ]; 
       FeynCalc`FCApart`Private`extraTensors = 
        Cases[SelectNotFree2[DownValues[DataType], FCTensor] /. 
            RuleDelayed -> FeynCalc`FCApart`Private`rd /. 
           DataType -> FeynCalc`FCApart`Private`dt /. HoldPattern -> 
           Identity, FeynCalc`FCApart`Private`rd[FeynCalc`FCApart`Private`dt[
            FeynCalc`FCApart`Private`a_, FCTensor], True] :> 
          FeynCalc`FCApart`Private`a, Infinity]; 
       FeynCalc`FCApart`Private`extraTensors = SelectFree[
         FeynCalc`FCApart`Private`extraTensors, {Eps, Pair, CartesianPair}]; 
       FCPrint[2, 
        "FCApart: Extra tensors to consider for determining the vector part: \
", FeynCalc`FCApart`Private`extraTensors, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       If[ !FreeQ2[FeynCalc`FCApart`Private`ex, 
          Join[{LorentzIndex, CartesianIndex, Eps, DiracGamma, PauliSigma}, 
           FeynCalc`FCApart`Private`extraTensors]], 
        {FeynCalc`FCApart`Private`scalarTerm, 
           FeynCalc`FCApart`Private`vectorTerm} = FCProductSplit[
           FeynCalc`FCApart`Private`ex, Join[{LorentzIndex, CartesianIndex, 
             Eps, DiracGamma, PauliSigma}, 
            FeynCalc`FCApart`Private`extraTensors]]; 
         If[FeynCalc`FCApart`Private`scalarTerm*
             FeynCalc`FCApart`Private`vectorTerm =!= 
            FeynCalc`FCApart`Private`ex || 
            !FreeQ2[FeynCalc`FCApart`Private`scalarTerm, {LorentzIndex, 
              CartesianIndex}], Message[FCApart::error, 
            FeynCalc`FCApart`Private`ex]; Abort[]], 
        FeynCalc`FCApart`Private`scalarTerm = FeynCalc`FCApart`Private`ex]; 
       FeynCalc`FCApart`Private`vectorTerm = 
        FeynCalc`FCApart`Private`extraPiece*
         FeynCalc`FCApart`Private`vectorTerm; FCPrint[3, 
        "FCApart: Vector term ", FeynCalc`FCApart`Private`vectorTerm, 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FCPrint[3, "FCApart: Scalar term ", 
        FeynCalc`FCApart`Private`scalarTerm, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       If[FreeQ[FeynCalc`FCApart`Private`scalarTerm, FeynAmpDenominator], 
        If[FeynCalc`FCApart`Private`optDropScaleless, 
          FeynCalc`FCApart`Private`scalarTerm = 0]; 
         FeynCalc`FCApart`Private`ex = FeynCalc`FCApart`Private`vectorTerm*
           FeynCalc`FCApart`Private`scalarTerm; If[OptionValue[FCE], 
          FeynCalc`FCApart`Private`ex = FCE[FeynCalc`FCApart`Private`ex]]; 
         Return[FeynCalc`FCApart`Private`ex]]; 
       If[ !FCLoopBasisOverdeterminedQ[FeynCalc`FCApart`Private`scalarTerm, 
          FeynCalc`FCApart`Private`lmoms, SetDimensions -> 
           OptionValue[SetDimensions], FCI -> True, InitialSubstitutions -> 
           FeynCalc`FCApart`Private`optFinalSubstitutions], 
        FCPrint[3, "FCApart: No furher partial fractioning is possible in ", 
          FeynCalc`FCApart`Private`ex, FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]; If[OptionValue[FCE], 
          FeynCalc`FCApart`Private`ex = FCE[FeynCalc`FCApart`Private`ex]]; 
         FeynCalc`FCApart`Private`ex = FeynCalc`FCApart`Private`ex*
           FeynCalc`FCApart`Private`extraPiece; 
         Return[FeynCalc`FCApart`Private`ex]; ]; 
       If[SelectFree[List @@ SelectNotFree[
            FeynCalc`FCApart`Private`scalarTerm, FeynAmpDenominator], 
          Sequence @@ FeynCalc`FCApart`Private`lmoms] =!= {}, 
        FeynCalc`FCApart`Private`scalarTerm = FeynAmpDenominatorSplit[
           FeynCalc`FCApart`Private`scalarTerm, Momentum -> 
            FeynCalc`FCApart`Private`lmoms]; FeynCalc`FCApart`Private`pref = 
          SelectFree[FeynCalc`FCApart`Private`scalarTerm, 
           Sequence @@ FeynCalc`FCApart`Private`lmoms]; 
         FeynCalc`FCApart`Private`tmp = SelectNotFree[
           FeynCalc`FCApart`Private`scalarTerm, Sequence @@ 
            FeynCalc`FCApart`Private`lmoms]; 
         If[FeynCalc`FCApart`Private`pref*FeynCalc`FCApart`Private`tmp =!= 
           FeynCalc`FCApart`Private`scalarTerm, Message[FCApart::error, 
            FeynCalc`FCApart`Private`ex]; Abort[]]; 
         FeynCalc`FCApart`Private`scalarTerm = FeynAmpDenominatorCombine[
           FeynCalc`FCApart`Private`tmp]]; FCPrint[3, 
        "FCApart: Final scalar term ", FeynCalc`FCApart`Private`scalarTerm, 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`vectorSet = FCLoopBasisExtract[
         FeynCalc`FCApart`Private`scalarTerm, FeynCalc`FCApart`Private`lmoms, 
         FCI -> True, SetDimensions -> OptionValue[SetDimensions], 
         FinalSubstitutions -> 
          FeynCalc`FCApart`Private`optFinalSubstitutions]; 
       FCPrint[3, "FCApart: vectorSet: ", FeynCalc`FCApart`Private`vectorSet, 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       If[ !MatchQ[FeynCalc`FCApart`Private`vectorSet[[3]], {__?NumberQ}], 
        FCPrint[3, "FCApart: Partial fractioning is not applicable to \
integrals with symbolic propagator powers.", FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]; If[OptionValue[FCE], 
          FeynCalc`FCApart`Private`ex = FCE[FeynCalc`FCApart`Private`ex]]; 
         FeynCalc`FCApart`Private`ex = FeynCalc`FCApart`Private`ex*
           FeynCalc`FCApart`Private`extraPiece; 
         Return[FeynCalc`FCApart`Private`ex]; ]; 
       FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
       FCPrint[1, "FCApart: Doing the actual partial fractioning via pfrac", 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`res = FeynCalc`FCApart`Private`pref*
         FeynCalc`FCApart`Private`vectorTerm*FeynCalc`FCApart`Private`pfrac[
          FeynCalc`FCApart`Private`vectorSet]; 
       FCPrint[1, "FCApart: Done applying pfrac, timing: ", 
        N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`res = FeynCalc`FCApart`Private`res /. 
          FeynCalc`FCApart`Private`pfracRaw | 
            FeynCalc`FCApart`Private`pfrac -> 
           FeynCalc`FCApart`Private`pfracOut /. 
         FeynCalc`FCApart`Private`pfracOut[FeynCalc`FCApart`Private`u_List, 
           {}] :> FeynCalc`FCApart`Private`pfracOut[
           FeynCalc`FCApart`Private`u]; FeynCalc`FCApart`Private`res = 
        FeynCalc`FCApart`Private`res /. FeynCalc`FCApart`Private`pfracOut[
            {_, _, {}, _}] -> 1 /. FeynCalc`FCApart`Private`pfracOut[
           {_, _, {(0)..}, _}] -> 1; 
       If[FeynCalc`FCApart`Private`optCollecting, 
        FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCApart: Applying Collect2.", FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`res = Collect2[
           FeynCalc`FCApart`Private`res, FeynCalc`FCApart`Private`pfracOut, 
           Factoring -> FeynCalc`FCApart`Private`optFactoring, 
           TimeConstrained -> FeynCalc`FCApart`Private`optTimeConstrained]; 
         FCPrint[1, "FCApart: Done applying Collect2, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; ]; 
       FCPrint[3, "FCApart: Preliminary result ", 
        FeynCalc`FCApart`Private`res, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
       FCPrint[1, "FCApart: Converting the output back into the standard \
FeynCalc notation.", FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`res = FeynCalc`FCApart`Private`res /. 
         FeynCalc`FCApart`Private`pfracOut[{_, _, 
            FeynCalc`FCApart`Private`x_, FeynCalc`FCApart`Private`y_}] :> 
          FeynAmpDenominatorCombine[Times @@ MapIndexed[
             FeynCalc`FCApart`Private`y[[First[#2]]]^Abs[#1] & , 
             FeynCalc`FCApart`Private`x]]; FCPrint[1, 
        "FCApart: Done converting the output, timing: ", 
        N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FCPrint[3, 
        "FCApart: Preliminary result after an intermediate conversion: ", 
        FeynCalc`FCApart`Private`res, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
       FCPrint[1, "FCApart: Applying FCLoopRemoveNegativePropagatorPowers.", 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FeynCalc`FCApart`Private`res = FCLoopRemoveNegativePropagatorPowers[
         FeynCalc`FCApart`Private`res, FCI -> True, 
         FCLoopPropagatorPowersCombine -> True]; FCPrint[1, "FCApart: Done \
applying FCLoopRemoveNegativePropagatorPowers, timing: ", 
        N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       FCPrint[3, "FCApart: After FCLoopRemoveNegativePropagatorPowers: ", 
        FeynCalc`FCApart`Private`res, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       If[FeynCalc`FCApart`Private`optCollecting, 
        FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCApart: Applying Collect2 (again).", 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`res = Collect2[
           FeynCalc`FCApart`Private`res, Join[{FeynAmpDenominator}, 
            FeynCalc`FCApart`Private`lmoms], Factoring -> 
            FeynCalc`FCApart`Private`optFactoring, TimeConstrained -> 
            FeynCalc`FCApart`Private`optTimeConstrained]; 
         FCPrint[1, "FCApart: Done applying Collect2, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; ]; 
       FCPrint[3, 
        "FCApart: Preliminary result converted back to FeynCalc notation ", 
        FeynCalc`FCApart`Private`res, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; If[OptionValue[Check], 
        FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCApart: Checking the result.", FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`lhs = FeynAmpDenominatorExplicit[
            FeynCalc`FCApart`Private`ex*
             FeynCalc`FCApart`Private`extraPiece] /. 
           FeynCalc`FCApart`Private`optFinalSubstitutions; 
         FeynCalc`FCApart`Private`rhs = FeynAmpDenominatorExplicit[
            FeynCalc`FCApart`Private`res] /. 
           FeynCalc`FCApart`Private`optFinalSubstitutions; 
         FeynCalc`FCApart`Private`vars = Variables2[
           FeynCalc`FCApart`Private`lhs]; FeynCalc`FCApart`Private`varsNum = 
          Table[RandomPrime[FeynCalc`FCApart`Private`optRandomPrime], 
           {FeynCalc`FCApart`Private`i, 1, Length[
             FeynCalc`FCApart`Private`vars]}]; 
         FeynCalc`FCApart`Private`repRule = Thread[
           FeynCalc`FCApart`Private`vars -> 
            FeynCalc`FCApart`Private`varsNum]; 
         FeynCalc`FCApart`Private`check = (FeynCalc`FCApart`Private`lhs /. 
            Dispatch[FeynCalc`FCApart`Private`repRule]) - 
           (FeynCalc`FCApart`Private`rhs /. Dispatch[
             FeynCalc`FCApart`Private`repRule]); 
         If[FeynCalc`FCApart`Private`check =!= 0, 
          Message[FCApart::checkfail, ToString[FeynCalc`FCApart`Private`ex, 
             InputForm]]; FCPrint[0, StandardForm[
             FeynCalc`FCApart`Private`check]]; Abort[]]; 
         FCPrint[1, "FCApart: Done checking the result, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; ]; 
       If[FeynCalc`FCApart`Private`optFDS, FeynCalc`FCApart`Private`time = 
          AbsoluteTime[]; FCPrint[1, "FCApart: Applying FDS.", 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`res = FDS[FeynCalc`FCApart`Private`res, 
           Sequence @@ FeynCalc`FCApart`Private`lmoms]; 
         If[FeynCalc`FCApart`Private`optCollecting, 
          FeynCalc`FCApart`Private`res = Collect2[
            FeynCalc`FCApart`Private`res, Join[{FeynAmpDenominator}, 
             FeynCalc`FCApart`Private`lmoms], Factoring -> 
             FeynCalc`FCApart`Private`optFactoring, TimeConstrained -> 
             FeynCalc`FCApart`Private`optTimeConstrained]]; 
         FCPrint[1, "FCApart: Done applying FDS, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; ]; 
       FCPrint[3, "FCApart: Preliminary result after FDS ", 
        FeynCalc`FCApart`Private`res, FCDoControl -> 
         FeynCalc`FCApart`Private`fcaVerbose]; 
       If[FeynCalc`FCApart`Private`optDropScaleless, 
        FCPrint[1, "FCApart: Dropping integrals that are scaleless in DR", 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`tmp = FeynCalc`FCApart`Private`res; 
         {FeynCalc`FCApart`Private`scaleless1, 
           FeynCalc`FCApart`Private`res} = FCSplit[
           FeynCalc`FCApart`Private`res, FeynCalc`FCApart`Private`lmoms]; 
         {FeynCalc`FCApart`Private`scaleless2, 
           FeynCalc`FCApart`Private`res} = FCSplit[
           FeynCalc`FCApart`Private`res, {FeynAmpDenominator}]; 
         If[Factor[Expand2[FeynCalc`FCApart`Private`scaleless1 + 
              FeynCalc`FCApart`Private`scaleless2 + 
              FeynCalc`FCApart`Private`res - 
              FeynCalc`FCApart`Private`tmp]] =!= 0, 
          Message[FCApart::checkfail, ToString[FeynCalc`FCApart`Private`ex, 
             InputForm]]; Abort[]]; FCPrint[1, 
          "FCApart: Done dropping scaleless integrals, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
         FCPrint[3, 
          "FCApart: The following parts of the integral vanish in DR: ", 
          FeynCalc`FCApart`Private`scaleless1 + 
           FeynCalc`FCApart`Private`scaleless2, FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]; FCPrint[3, 
          "FCApart: The non-vanishing part is ", 
          FeynCalc`FCApart`Private`res, FCDoControl -> 
           FeynCalc`FCApart`Private`fcaVerbose]]; 
       If[FeynCalc`FCApart`Private`optCollecting, 
        FeynCalc`FCApart`Private`time = AbsoluteTime[]; 
         FCPrint[1, "FCApart: Applying Collect2 (last time).", 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
         FeynCalc`FCApart`Private`res = Collect2[
           FeynCalc`FCApart`Private`res, Join[{FeynAmpDenominator}, 
            FeynCalc`FCApart`Private`lmoms], Factoring -> 
            FeynCalc`FCApart`Private`optFactoring, TimeConstrained -> 
            FeynCalc`FCApart`Private`optTimeConstrained]; 
         FCPrint[1, "FCApart: Done applying Collect2, timing: ", 
          N[AbsoluteTime[] - FeynCalc`FCApart`Private`time, 4], 
          FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]]; 
       FCPrint[3, "FCApart: Leaving with ", FeynCalc`FCApart`Private`res, 
        FCDoControl -> FeynCalc`FCApart`Private`fcaVerbose]; 
       If[OptionValue[FCE], FeynCalc`FCApart`Private`res = 
         FCE[FeynCalc`FCApart`Private`res]]; 
       Return[FeynCalc`FCApart`Private`res]] /; 
     FeynCalc`FCApart`Private`lmoms =!= {} && 
       !FreeQ2[FeynCalc`FCApart`Private`expr, FeynCalc`FCApart`Private`lmoms]
 
Options[FCApart] = {Check -> True, Collecting -> True, DropScaleless -> True, 
     ExpandScalarProduct -> True, FeynCalcExternal -> False, 
     FeynCalcInternal -> False, FCVerbose -> False, FDS -> True, 
     FinalSubstitutions -> {}, Factoring -> {Factor, 5000}, 
     MaxIterations -> Infinity, RandomPrime -> 100000000, 
     SetDimensions -> {3, 4, D, -1 + D}, TimeConstrained -> 3}
 
FCApart /: FCApart::checkfail = "\nError! Partial fractioning of the loop \
integral `1` by FCApart has produced an inconsistent result. Evaluation \
aborted"
 
FCApart /: FCApart::error = "\nError! Something went wrong while partial \
fractioning the loop integral `1` by FCApart. Evaluation aborted"
 
FCApart /: FCApart::usage = "FCApart[expr, {q1, q2, ...}] is an internal \
function that partial fractions a\nloop integral (that depends on q1,q2, ...) \
into integrals that contain only\nlinearly independent propagators. The \
algorithm is largely based \
on\n[arXiv:1204.2314](https://arxiv.org/abs/1204.2314) by F.Feng. FCApart is \
meant\nto be applied to single loop integrals only. If you need to perform \
partial\nfractioning on an expression that contains multiple loop integrals, \
use\nApartFF.\n\nThere is actually no reason, why one would want to apply \
FCApart instead of\nApartFF, except for cases, where FCApart is called from a \
different package\nthat interacts with FeynCalc."
 
FeynCalc`FCApart`Private`cancelSP[FeynCalc`FCApart`Private`ex_] := 
    FeynCalc`FCApart`Private`ex /. FeynAmpDenominator -> 
        FeynCalc`FCApart`Private`fadHold //. 
      Dispatch[{(FeynCalc`FCApart`Private`b_Pair)*
          FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1___, 
           StandardPropagatorDenominator[0, FeynCalc`FCApart`Private`b_Pair, 
            0*_, {FeynCalc`FCApart`Private`n_, FeynCalc`FCApart`Private`s_}], 
           FeynCalc`FCApart`Private`r2___] :> 
         FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1, 
          StandardPropagatorDenominator[0, FeynCalc`FCApart`Private`b, 0, 
           {FeynCalc`FCApart`Private`n - 1, FeynCalc`FCApart`Private`s}], 
          FeynCalc`FCApart`Private`r2], (FeynCalc`FCApart`Private`b_Pair)^
           (FeynCalc`FCApart`Private`m_)*FeynCalc`FCApart`Private`fadHold[
           FeynCalc`FCApart`Private`r1___, StandardPropagatorDenominator[0, 
            FeynCalc`FCApart`Private`b_Pair, 0, {FeynCalc`FCApart`Private`n_, 
             FeynCalc`FCApart`Private`s_}], 
           FeynCalc`FCApart`Private`r2___] :> 
         FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1, 
          StandardPropagatorDenominator[0, FeynCalc`FCApart`Private`b, 0, 
           {FeynCalc`FCApart`Private`n - FeynCalc`FCApart`Private`m, 
            FeynCalc`FCApart`Private`s}], FeynCalc`FCApart`Private`r2], 
        (FeynCalc`FCApart`Private`b_CartesianPair)*
          FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1___, 
           CartesianPropagatorDenominator[0, 
            FeynCalc`FCApart`Private`b_CartesianPair, 0, 
            {FeynCalc`FCApart`Private`n_, FeynCalc`FCApart`Private`s_}], 
           FeynCalc`FCApart`Private`r2___] :> 
         FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1, 
          CartesianPropagatorDenominator[0, FeynCalc`FCApart`Private`b, 0, 
           {FeynCalc`FCApart`Private`n - 1, FeynCalc`FCApart`Private`s}], 
          FeynCalc`FCApart`Private`r2], 
        (FeynCalc`FCApart`Private`b_CartesianPair)^
           (FeynCalc`FCApart`Private`m_)*FeynCalc`FCApart`Private`fadHold[
           FeynCalc`FCApart`Private`r1___, CartesianPropagatorDenominator[0, 
            FeynCalc`FCApart`Private`b_CartesianPair, 0, 
            {FeynCalc`FCApart`Private`n_, FeynCalc`FCApart`Private`s_}], 
           FeynCalc`FCApart`Private`r2___] :> 
         FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1, 
          CartesianPropagatorDenominator[0, FeynCalc`FCApart`Private`b, 0, 
           {FeynCalc`FCApart`Private`n - FeynCalc`FCApart`Private`m, 
            FeynCalc`FCApart`Private`s}], FeynCalc`FCApart`Private`r2], 
        (FeynCalc`FCApart`Private`b_CartesianPair)^
           (FeynCalc`FCApart`Private`m1_.)*FeynCalc`FCApart`Private`fadHold[
           FeynCalc`FCApart`Private`r1___, GenericPropagatorDenominator[
            (FeynCalc`FCApart`Private`b_CartesianPair)^
             (FeynCalc`FCApart`Private`m2_), {FeynCalc`FCApart`Private`n_, 
             FeynCalc`FCApart`Private`s_}], 
           FeynCalc`FCApart`Private`r2___] :> 
         FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1, 
          CartesianPropagatorDenominator[0, FeynCalc`FCApart`Private`b^
            FeynCalc`FCApart`Private`m2, 0, {FeynCalc`FCApart`Private`n - 
             FeynCalc`FCApart`Private`m1/FeynCalc`FCApart`Private`m2, 
            FeynCalc`FCApart`Private`s}], FeynCalc`FCApart`Private`r2]}] /. 
     FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1___, 
       (StandardPropagatorDenominator | CartesianPropagatorDenominator)[__, 
        {0, _}], FeynCalc`FCApart`Private`r2___] :> 
      FeynCalc`FCApart`Private`fadHold[FeynCalc`FCApart`Private`r1, 
       FeynCalc`FCApart`Private`r2]
 
FCTensor /: FCTensor::usage = 
     "FCTensor is a data type. E.g. DataType[R, FCTensor] = True."
 
FeynCalc`FeynAmpDenominatorSimplify`Private`fdsMultiLoop[
     FeynCalc`FeynAmpDenominatorSimplify`Private`loopInt:
      FeynAmpDenominator[FeynCalc`FeynAmpDenominatorSimplify`Private`props__]*
       (_.), FeynCalc`FeynAmpDenominatorSimplify`Private`qs__] := 
    Block[{FeynCalc`FeynAmpDenominatorSimplify`Private`tmp, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`tmpNew, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`solsList, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`repRule}, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`tmp = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`loopInt; 
       FCPrint[3, "FDS: fdsMultiLoop: Entering with: ", 
        FeynCalc`FeynAmpDenominatorSimplify`Private`tmp, 
        FCDoControl -> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
       FeynCalc`FeynAmpDenominatorSimplify`Private`tmp = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`tmp /. 
          FeynAmpDenominator -> FeynCalc`Package`feynsimp[
            {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}] /. 
         FeynAmpDenominator -> 
          FeynCalc`FeynAmpDenominatorSimplify`Private`feynord2[
           {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}]; 
       FCPrint[3, 
        "FDS: fdsMultiLoop: After first ordering of the propagators: ", 
        FeynCalc`FeynAmpDenominatorSimplify`Private`tmp, 
        FCDoControl -> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
       FeynCalc`FeynAmpDenominatorSimplify`Private`tmp = 
        Fold[FeynCalc`FeynAmpDenominatorSimplify`Private`removeAnitsymmetricI\
ntegrals[#1, #2, {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}] & , 
         FeynCalc`FeynAmpDenominatorSimplify`Private`tmp, 
         Subsets[{FeynCalc`FeynAmpDenominatorSimplify`Private`qs}]]; 
       FCPrint[3, 
        "FDS: fdsMultiLoop: After removing antisymmetric integrals: ", 
        FeynCalc`FeynAmpDenominatorSimplify`Private`tmp, 
        FCDoControl -> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
       If[FeynCalc`FeynAmpDenominatorSimplify`Private`tmp === 0, Return[0], 
        FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
         FeynCalc`FeynAmpDenominatorSimplify`Private`tmp]; 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
        FeynCalc`FeynAmpDenominatorSimplify`Private`res /. 
         FeynAmpDenominator :> FeynCalc`Package`feynord[
           {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}]; 
       FCPrint[3, "FDS: fdsMultiLoop: Final ordering: ", 
        FeynCalc`FeynAmpDenominatorSimplify`Private`res, 
        FCDoControl -> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
       FCPrint[3, "FDS: fdsMultiLoop: Leaving with: ", 
        FeynCalc`FeynAmpDenominatorSimplify`Private`res, 
        FCDoControl -> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`fdsVerbose]; 
       FeynCalc`FeynAmpDenominatorSimplify`Private`res] /; 
      !FreeQ2[{FeynCalc`FeynAmpDenominatorSimplify`Private`props}, 
       {FeynCalc`FeynAmpDenominatorSimplify`Private`qs}]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`getTopology[
     FeynAmpDenominator[FeynCalc`FeynAmpDenominatorSimplify`Private`props__]*
      (_.), FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms_List] := 
    {Length[Union[{FeynCalc`FeynAmpDenominatorSimplify`Private`props}]], 
      Select[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms, 
        !FreeQ[{FeynCalc`FeynAmpDenominatorSimplify`Private`props}, #1] & ], 
      Union[Cases[MomentumExpand[
         {FeynCalc`FeynAmpDenominatorSimplify`Private`props}], 
        Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`x_, _:4] /; 
          FreeQ2[FeynCalc`FeynAmpDenominatorSimplify`Private`x, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms] :> 
         FeynCalc`FeynAmpDenominatorSimplify`Private`x, Infinity]]} /; 
     Length[Union[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms]] === 
      Length[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`checkTopology[
     {FeynCalc`FeynAmpDenominatorSimplify`Private`prnum_, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms_List, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`emoms_List}] := 
    Which[2 <= FeynCalc`FeynAmpDenominatorSimplify`Private`prnum <= 5 && 
      Length[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms] === 2 && 
      Length[FeynCalc`FeynAmpDenominatorSimplify`Private`emoms] === 1, 
     "2-loop-self-energy", True, "generic"]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`fds2LoopsSE[
     FeynCalc`FeynAmpDenominatorSimplify`Private`expr_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`q1_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`q2_, _] := 
    FeynCalc`FeynAmpDenominatorSimplify`Private`expr /; 
     FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`expr, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`q1] || 
      FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`expr, 
       FeynCalc`FeynAmpDenominatorSimplify`Private`q2]
 
FeynCalc`FeynAmpDenominatorSimplify`Private`fds2LoopsSE[
     FeynCalc`FeynAmpDenominatorSimplify`Private`expr_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`q1_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`q2_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`p_] := 
    (MomentumExpand[FixedPoint[
        FeynCalc`FeynAmpDenominatorSimplify`Private`fds2LoopsSE2[#1, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`p] & , 
        FeynCalc`FeynAmpDenominatorSimplify`Private`expr, 5]] /. 
      {PropagatorDenominator[
         -Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d_:4], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m_] :> 
        PropagatorDenominator[Momentum[
          FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`d], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m], 
       PropagatorDenominator[
         -Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d_:4], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m_] :> 
        PropagatorDenominator[Momentum[
          FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
          FeynCalc`FeynAmpDenominatorSimplify`Private`d], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m], 
       PropagatorDenominator[
         Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`p, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d_:4] - 
          Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`e_:4], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m_] :> 
        PropagatorDenominator[
         Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`e] - 
          Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`p, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m], 
       PropagatorDenominator[
         Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`p, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d_:4] - 
          Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`e_:4], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m_] :> 
        PropagatorDenominator[
         Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`e] - 
          Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`p, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m], 
       PropagatorDenominator[
         Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`d_:4] - 
          Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`e_:4], 
         FeynCalc`FeynAmpDenominatorSimplify`Private`m_] :> 
        PropagatorDenominator[
         Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q1, 
           FeynCalc`FeynAmpDenominatorSimplify`Private`e] - 
          Momentum[FeynCalc`FeynAmpDenominatorSimplify`Private`q2, 
