FeynCalc`FeynAmpDenominatorSimplify`Private`renameLoopMomenta[
     FeynCalc`FeynAmpDenominatorSimplify`Private`int_, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`qs_List] := 
    Block[{FeynCalc`FeynAmpDenominatorSimplify`Private`permutations, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`listOfRenamings, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`equivalentInts, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`nLoops, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`rule, 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res}, 
     FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms = 
       Select[FeynCalc`FeynAmpDenominatorSimplify`Private`qs, 
         !FreeQ[FeynCalc`FeynAmpDenominatorSimplify`Private`int, #1] & ]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`nLoops = 
       Length[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`permutations = 
       Permute[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms, 
        PermutationGroup[(Cycles[{#1}] & ) /@ Subsets[
           Range[FeynCalc`FeynAmpDenominatorSimplify`Private`nLoops], 
           {2, FeynCalc`FeynAmpDenominatorSimplify`Private`nLoops}]]]; 
      If[FeynCalc`FeynAmpDenominatorSimplify`Private`permutations === {{}}, 
       Return[FeynCalc`FeynAmpDenominatorSimplify`Private`int]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`listOfRenamings = 
       Sort[Thread[FeynCalc`FeynAmpDenominatorSimplify`Private`rule[
             Table[FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms, 
              {FeynCalc`FeynAmpDenominatorSimplify`Private`i, 1, Length[
                FeynCalc`FeynAmpDenominatorSimplify`Private`permutations]}], 
             FeynCalc`FeynAmpDenominatorSimplify`Private`permutations]] /. 
           FeynCalc`FeynAmpDenominatorSimplify`Private`rule[
             FeynCalc`FeynAmpDenominatorSimplify`Private`x_List, 
             FeynCalc`FeynAmpDenominatorSimplify`Private`y_List] :> 
            Thread[FeynCalc`FeynAmpDenominatorSimplify`Private`rule[
              FeynCalc`FeynAmpDenominatorSimplify`Private`x, 
              FeynCalc`FeynAmpDenominatorSimplify`Private`y]] /. 
          FeynCalc`FeynAmpDenominatorSimplify`Private`rule[
            FeynCalc`FeynAmpDenominatorSimplify`Private`a_, 
            FeynCalc`FeynAmpDenominatorSimplify`Private`a_] :> 
           Unevaluated[Sequence[]]] /. 
        FeynCalc`FeynAmpDenominatorSimplify`Private`rule -> Rule; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`equivalentInts = 
       (FeynCalc`FeynAmpDenominatorSimplify`Private`int /. #1 /. 
           FeynAmpDenominator -> FeynCalc`Package`feynsimp[
             FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms] /. 
          FeynAmpDenominator -> FeynCalc`Package`feynord[
            FeynCalc`FeynAmpDenominatorSimplify`Private`lmoms] & ) /@ 
        FeynCalc`FeynAmpDenominatorSimplify`Private`listOfRenamings; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res = 
       First[Sort[
         FeynCalc`FeynAmpDenominatorSimplify`Private`equivalentInts]]; 
      FeynCalc`FeynAmpDenominatorSimplify`Private`res]
 
ToPaVe2[FeynCalc`ToPaVe2`Private`expr_PaVe, OptionsPattern[]] := 
    FeynCalc`ToPaVe2`Private`expr
 
ToPaVe2[FeynCalc`ToPaVe2`Private`expr_ /; 
      Head[FeynCalc`ToPaVe2`Private`expr] =!= PaVe, OptionsPattern[]] := 
    Block[{FeynCalc`ToPaVe2`Private`ex, FeynCalc`ToPaVe2`Private`pave}, 
     If[ !OptionValue[PaVe, PaVeAutoReduce], FeynCalc`ToPaVe2`Private`ex = 
        FeynCalc`ToPaVe2`Private`expr /. {A0[FeynCalc`ToPaVe2`Private`m_, 
            OptionsPattern[]] :> FeynCalc`ToPaVe2`Private`pave[0, {}, 
            {FeynCalc`ToPaVe2`Private`m}], A00[FeynCalc`ToPaVe2`Private`m_, 
            OptionsPattern[]] :> FeynCalc`ToPaVe2`Private`pave[0, 0, {}, 
            {FeynCalc`ToPaVe2`Private`m}], B0[FeynCalc`ToPaVe2`Private`pp_, 
            FeynCalc`ToPaVe2`Private`m1_, FeynCalc`ToPaVe2`Private`m2_, 
            OptionsPattern[]] :> FeynCalc`ToPaVe2`Private`pave[0, 
            {FeynCalc`ToPaVe2`Private`pp}, {FeynCalc`ToPaVe2`Private`m1, 
             FeynCalc`ToPaVe2`Private`m2}], B1[FeynCalc`ToPaVe2`Private`pp_, 
            FeynCalc`ToPaVe2`Private`m1_, FeynCalc`ToPaVe2`Private`m2_, 
            OptionsPattern[]] :> FeynCalc`ToPaVe2`Private`pave[1, 
            {FeynCalc`ToPaVe2`Private`pp}, {FeynCalc`ToPaVe2`Private`m1, 
             FeynCalc`ToPaVe2`Private`m2}], B00[FeynCalc`ToPaVe2`Private`pp_, 
            FeynCalc`ToPaVe2`Private`m1_, FeynCalc`ToPaVe2`Private`m2_, 
            OptionsPattern[]] :> FeynCalc`ToPaVe2`Private`pave[0, 0, 
            {FeynCalc`ToPaVe2`Private`pp}, {FeynCalc`ToPaVe2`Private`m1, 
             FeynCalc`ToPaVe2`Private`m2}], B11[FeynCalc`ToPaVe2`Private`pp_, 
            FeynCalc`ToPaVe2`Private`m1_, FeynCalc`ToPaVe2`Private`m2_, 
            OptionsPattern[]] :> FeynCalc`ToPaVe2`Private`pave[1, 1, 
            {FeynCalc`ToPaVe2`Private`pp}, {FeynCalc`ToPaVe2`Private`m1, 
             FeynCalc`ToPaVe2`Private`m2}], C0[FeynCalc`ToPaVe2`Private`p10_, 
            FeynCalc`ToPaVe2`Private`p12_, FeynCalc`ToPaVe2`Private`p20_, 
            FeynCalc`ToPaVe2`Private`m1_, FeynCalc`ToPaVe2`Private`m2_, 
            FeynCalc`ToPaVe2`Private`m3_, OptionsPattern[]] :> 
           FeynCalc`ToPaVe2`Private`pave[0, {FeynCalc`ToPaVe2`Private`p10, 
             FeynCalc`ToPaVe2`Private`p12, FeynCalc`ToPaVe2`Private`p20}, 
            {FeynCalc`ToPaVe2`Private`m1, FeynCalc`ToPaVe2`Private`m2, 
             FeynCalc`ToPaVe2`Private`m3}], D0[FeynCalc`ToPaVe2`Private`p10_, 
            FeynCalc`ToPaVe2`Private`p12_, FeynCalc`ToPaVe2`Private`p23_, 
            FeynCalc`ToPaVe2`Private`p30_, FeynCalc`ToPaVe2`Private`p20_, 
            FeynCalc`ToPaVe2`Private`p13_, FeynCalc`ToPaVe2`Private`m1_, 
            FeynCalc`ToPaVe2`Private`m2_, FeynCalc`ToPaVe2`Private`m3_, 
            FeynCalc`ToPaVe2`Private`m4_, OptionsPattern[]] :> 
           FeynCalc`ToPaVe2`Private`pave[0, {FeynCalc`ToPaVe2`Private`p10, 
             FeynCalc`ToPaVe2`Private`p12, FeynCalc`ToPaVe2`Private`p23, 
             FeynCalc`ToPaVe2`Private`p30, FeynCalc`ToPaVe2`Private`p20, 
             FeynCalc`ToPaVe2`Private`p13}, {FeynCalc`ToPaVe2`Private`m1, 
             FeynCalc`ToPaVe2`Private`m2, FeynCalc`ToPaVe2`Private`m3, 
             FeynCalc`ToPaVe2`Private`m4}]}]; 
      If[OptionValue[PaVeAutoOrder] === False, FeynCalc`ToPaVe2`Private`ex = 
        FeynCalc`ToPaVe2`Private`ex /. FeynCalc`ToPaVe2`Private`pave[
           FeynCalc`ToPaVe2`Private`x__] :> FeynCalc`ToPaVe2`Private`pave[
           FeynCalc`ToPaVe2`Private`x, PaVeAutoOrder -> False]]; 
      FeynCalc`ToPaVe2`Private`ex = FeynCalc`ToPaVe2`Private`ex /. 
        FeynCalc`ToPaVe2`Private`pave -> PaVe; FeynCalc`ToPaVe2`Private`ex]
 
Options[ToPaVe2] = {PaVeAutoOrder -> True}
 
ToPaVe2 /: ToPaVe2::usage = "ToPaVe2[expr] converts all the direct \
Passarino-Veltman functions (A0, A00,\nB0, B1, B00, B11, C0, D0) to \
PaVe-functions."
 
PaVeAutoOrder /: PaVeAutoOrder::usage = "PaVeAutoOrder is an option of PaVe \
and other functions that work with PaVe\nfunctions. When set to True,  the \
arguments of the PaVe functions will be\nautomatically ordered by using known \
symmetries between those arguments."
 
