PaVeToABCD[FeynCalc`PaVeToABCD`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`PaVeToABCD`Private`res, 
      FeynCalc`PaVeToABCD`Private`repRule, 
      FeynCalc`PaVeToABCD`Private`paveInts, 
      FeynCalc`PaVeToABCD`Private`paveIntsEval}, 
     FeynCalc`PaVeToABCD`Private`paveInts = 
       Cases2[FeynCalc`PaVeToABCD`Private`expr, PaVe]; 
      FeynCalc`PaVeToABCD`Private`paveIntsEval = 
       FeynCalc`PaVeToABCD`Private`paveInts /. 
        {PaVe[0, {}, {FeynCalc`PaVeToABCD`Private`m_}, OptionsPattern[]] :> 
          A0[FeynCalc`PaVeToABCD`Private`m], 
         PaVe[0, 0, {}, {FeynCalc`PaVeToABCD`Private`m_}, 
           OptionsPattern[]] :> A00[FeynCalc`PaVeToABCD`Private`m], 
         PaVe[0, {FeynCalc`PaVeToABCD`Private`pp_}, 
           {FeynCalc`PaVeToABCD`Private`m1_, 
            FeynCalc`PaVeToABCD`Private`m2_}, OptionsPattern[]] :> 
          B0[FeynCalc`PaVeToABCD`Private`pp, FeynCalc`PaVeToABCD`Private`m1, 
           FeynCalc`PaVeToABCD`Private`m2], 
         PaVe[1, {FeynCalc`PaVeToABCD`Private`pp_}, 
           {FeynCalc`PaVeToABCD`Private`m1_, 
            FeynCalc`PaVeToABCD`Private`m2_}, OptionsPattern[]] :> 
          B1[FeynCalc`PaVeToABCD`Private`pp, FeynCalc`PaVeToABCD`Private`m1, 
           FeynCalc`PaVeToABCD`Private`m2], 
         PaVe[0, 0, {FeynCalc`PaVeToABCD`Private`pp_}, 
           {FeynCalc`PaVeToABCD`Private`m1_, 
            FeynCalc`PaVeToABCD`Private`m2_}, OptionsPattern[]] :> 
          B00[FeynCalc`PaVeToABCD`Private`pp, FeynCalc`PaVeToABCD`Private`m1, 
           FeynCalc`PaVeToABCD`Private`m2], 
         PaVe[1, 1, {FeynCalc`PaVeToABCD`Private`pp_}, 
           {FeynCalc`PaVeToABCD`Private`m1_, 
            FeynCalc`PaVeToABCD`Private`m2_}, OptionsPattern[]] :> 
          B11[FeynCalc`PaVeToABCD`Private`pp, FeynCalc`PaVeToABCD`Private`m1, 
           FeynCalc`PaVeToABCD`Private`m2], 
         PaVe[0, {FeynCalc`PaVeToABCD`Private`p10_, 
            FeynCalc`PaVeToABCD`Private`p12_, 
            FeynCalc`PaVeToABCD`Private`p20_}, 
           {FeynCalc`PaVeToABCD`Private`m1_, FeynCalc`PaVeToABCD`Private`m2_, 
            FeynCalc`PaVeToABCD`Private`m3_}, OptionsPattern[]] :> 
          C0[FeynCalc`PaVeToABCD`Private`p10, 
           FeynCalc`PaVeToABCD`Private`p12, FeynCalc`PaVeToABCD`Private`p20, 
           FeynCalc`PaVeToABCD`Private`m1, FeynCalc`PaVeToABCD`Private`m2, 
           FeynCalc`PaVeToABCD`Private`m3], 
         PaVe[0, {FeynCalc`PaVeToABCD`Private`p10_, 
            FeynCalc`PaVeToABCD`Private`p12_, 
            FeynCalc`PaVeToABCD`Private`p23_, 
            FeynCalc`PaVeToABCD`Private`p30_, 
            FeynCalc`PaVeToABCD`Private`p20_, 
            FeynCalc`PaVeToABCD`Private`p13_}, 
           {FeynCalc`PaVeToABCD`Private`m1_, FeynCalc`PaVeToABCD`Private`m2_, 
            FeynCalc`PaVeToABCD`Private`m3_, 
            FeynCalc`PaVeToABCD`Private`m4_}, OptionsPattern[]] :> 
          D0[FeynCalc`PaVeToABCD`Private`p10, 
           FeynCalc`PaVeToABCD`Private`p12, FeynCalc`PaVeToABCD`Private`p23, 
           FeynCalc`PaVeToABCD`Private`p30, FeynCalc`PaVeToABCD`Private`p20, 
           FeynCalc`PaVeToABCD`Private`p13, FeynCalc`PaVeToABCD`Private`m1, 
           FeynCalc`PaVeToABCD`Private`m2, FeynCalc`PaVeToABCD`Private`m3, 
           FeynCalc`PaVeToABCD`Private`m4]}; 
      FeynCalc`PaVeToABCD`Private`paveIntsEval = 
       FeynCalc`PaVeToABCD`Private`paveIntsEval /. 
        (FeynCalc`PaVeToABCD`Private`a_ -> FeynCalc`PaVeToABCD`Private`a_) :> 
         Unevaluated[Sequence[]]; FeynCalc`PaVeToABCD`Private`repRule = 
       Thread[FeynCalc`PaVeToABCD`Private`paveInts -> 
         FeynCalc`PaVeToABCD`Private`paveIntsEval]; 
      FeynCalc`PaVeToABCD`Private`res = FeynCalc`PaVeToABCD`Private`expr /. 
        Dispatch[FeynCalc`PaVeToABCD`Private`repRule]; 
      FeynCalc`PaVeToABCD`Private`res]
 
Options[PaVeToABCD] = {}
 
PaVeToABCD /: PaVeToABCD::usage = "PaVeToABCD[expr] converts suitable PaVe \
functions to direct Passarino-Veltman\nfunctions (A0,  A00, B0, B1, B00, B11, \
C0, D0). PaVeToABCD is nearly the\ninverse of ToPaVe2."
 
OtherLoopMomenta /: OtherLoopMomenta::usage = "OtherLoopMomenta is an option \
of ToPaVe. It takes a list of loop momenta other\nthan q that appear in the \
expression. Knowing about these momenta prevents\nToPaVe from erroneously \
converting multi-loop integrals into PaVe scalar\nfunctions.\n\nThis is of \
course relevant only for multi-loop calculations. At 1-loop you\ndon't need \
to specify this option explicitly."
 
FeynCalc`ToPaVe`Private`toPaVe[FeynCalc`ToPaVe`Private`x_, _, _, _] := 
    FeynCalc`ToPaVe`Private`x /;  !FreeQ2[Head[FeynCalc`ToPaVe`Private`x], 
       FeynCalc`Package`PaVeHeadsList]
 
FeynCalc`ToPaVe`Private`toPaVe[FeynAmpDenominator[PropagatorDenominator[
       Momentum[FeynCalc`ToPaVe`Private`q_, FeynCalc`ToPaVe`Private`dim_], 
       FeynCalc`ToPaVe`Private`m1_], FeynCalc`ToPaVe`Private`re:
       PropagatorDenominator[Momentum[FeynCalc`ToPaVe`Private`q_, 
           FeynCalc`ToPaVe`Private`dim_] + (_:0), _]...], 
     FeynCalc`ToPaVe`Private`q_, FeynCalc`ToPaVe`Private`paveao_, 
     FeynCalc`ToPaVe`Private`pavear_] := 
    Block[{FeynCalc`ToPaVe`Private`tmp, FeynCalc`ToPaVe`Private`res, 
       FeynCalc`ToPaVe`Private`pair}, If[{FeynCalc`ToPaVe`Private`re} === {}, 
        FeynCalc`ToPaVe`Private`tmp = {{}, {}}, 
        FeynCalc`ToPaVe`Private`tmp = Transpose[
           Cases[{FeynCalc`ToPaVe`Private`re}, 
            PD[Momentum[FeynCalc`ToPaVe`Private`q, 
                FeynCalc`ToPaVe`Private`dim] + (FeynCalc`ToPaVe`Private`x_:
                0), FeynCalc`ToPaVe`Private`m_:0] :> 
             {FeynCalc`ToPaVe`Private`x, FeynCalc`ToPaVe`Private`m}]]; ]; 
       If[Length[FeynCalc`ToPaVe`Private`tmp[[1]]] =!= 
          Length[{FeynCalc`ToPaVe`Private`re}] || 
         Length[FeynCalc`ToPaVe`Private`tmp[[2]]] =!= 
          Length[{FeynCalc`ToPaVe`Private`re}], 
        Message[ToPaVe::failmsg, 
          "toPave: Wrong number of the kinematic invariants!"]; Abort[]]; 
       FeynCalc`ToPaVe`Private`res = I*Pi^2*PaVe[0, ExpandScalarProduct[
           FeynCalc`Package`momentumRoutingDenner[
             FeynCalc`ToPaVe`Private`tmp[[1]], FeynCalc`ToPaVe`Private`pair[
               #1, #1] & ] /. FeynCalc`ToPaVe`Private`pair -> Pair], 
          (#1^2 & ) /@ Join[{FeynCalc`ToPaVe`Private`m1}, 
            FeynCalc`ToPaVe`Private`tmp[[2]]], PaVeAutoOrder -> 
           FeynCalc`ToPaVe`Private`paveao, PaVeAutoReduce -> 
           FeynCalc`ToPaVe`Private`pavear]; 
       If[FeynCalc`ToPaVe`Private`optPaVeOrder, FeynCalc`ToPaVe`Private`res = 
         PaVeOrder[FeynCalc`ToPaVe`Private`res]]; 
       If[FeynCalc`ToPaVe`Private`optFactoring =!= False, 
        FeynCalc`ToPaVe`Private`res = FeynCalc`ToPaVe`Private`res /. 
          PaVe[0, FeynCalc`ToPaVe`Private`a__] :> 
           PaVe[0, Sequence @@ FeynCalc`ToPaVe`Private`optFactoring /@ 
              {FeynCalc`ToPaVe`Private`a}]]; FeynCalc`ToPaVe`Private`res] /; 
      !FeynCalc`ToPaVe`Private`genpave
 
FeynCalc`ToPaVe`Private`toPaVe[FeynAmpDenominator[
      StandardPropagatorDenominator[Momentum[FeynCalc`ToPaVe`Private`q_, 
        FeynCalc`ToPaVe`Private`dim_], 0, FeynCalc`ToPaVe`Private`mm1_, 
       {1, 1}], FeynCalc`ToPaVe`Private`re:StandardPropagatorDenominator[
         Momentum[FeynCalc`ToPaVe`Private`q_, FeynCalc`ToPaVe`Private`dim_] + 
          (_:0), 0, _, {1, 1}]...], FeynCalc`ToPaVe`Private`q_, 
     FeynCalc`ToPaVe`Private`paveao_, FeynCalc`ToPaVe`Private`pavear_] := 
    Block[{FeynCalc`ToPaVe`Private`tmp, FeynCalc`ToPaVe`Private`res, 
       FeynCalc`ToPaVe`Private`pair}, If[{FeynCalc`ToPaVe`Private`re} === {}, 
        FeynCalc`ToPaVe`Private`tmp = {{}, {}}, 
        FeynCalc`ToPaVe`Private`tmp = Transpose[
           Cases[{FeynCalc`ToPaVe`Private`re}, StandardPropagatorDenominator[
              Momentum[FeynCalc`ToPaVe`Private`q, 
                FeynCalc`ToPaVe`Private`dim] + (FeynCalc`ToPaVe`Private`x_:
                0), 0, FeynCalc`ToPaVe`Private`m_:0, {1, 1}] :> 
             {FeynCalc`ToPaVe`Private`x, -FeynCalc`ToPaVe`Private`m}]]; ]; 
       If[Length[FeynCalc`ToPaVe`Private`tmp[[1]]] =!= 
          Length[{FeynCalc`ToPaVe`Private`re}] || 
         Length[FeynCalc`ToPaVe`Private`tmp[[2]]] =!= 
          Length[{FeynCalc`ToPaVe`Private`re}], 
        Message[ToPaVe::failmsg, 
          "toPave: Wrong number of the kinematic invariants!"]; Abort[]]; 
       FeynCalc`ToPaVe`Private`res = I*Pi^2*PaVe[0, ExpandScalarProduct[
           FeynCalc`Package`momentumRoutingDenner[
             FeynCalc`ToPaVe`Private`tmp[[1]], FeynCalc`ToPaVe`Private`pair[
               #1, #1] & ] /. FeynCalc`ToPaVe`Private`pair -> Pair], 
          Join[{-FeynCalc`ToPaVe`Private`mm1}, FeynCalc`ToPaVe`Private`tmp[[
            2]]], PaVeAutoOrder -> FeynCalc`ToPaVe`Private`paveao, 
          PaVeAutoReduce -> FeynCalc`ToPaVe`Private`pavear]; 
       If[FeynCalc`ToPaVe`Private`optPaVeOrder, FeynCalc`ToPaVe`Private`res = 
         PaVeOrder[FeynCalc`ToPaVe`Private`res]]; 
       If[FeynCalc`ToPaVe`Private`optFactoring =!= False, 
        FeynCalc`ToPaVe`Private`res = FeynCalc`ToPaVe`Private`res /. 
          PaVe[0, FeynCalc`ToPaVe`Private`a__] :> 
           PaVe[0, Sequence @@ FeynCalc`ToPaVe`Private`optFactoring /@ 
              {FeynCalc`ToPaVe`Private`a}]]; FeynCalc`ToPaVe`Private`res] /; 
      !FeynCalc`ToPaVe`Private`genpave
 
FeynCalc`ToPaVe`Private`toPaVe[FeynAmpDenominator[FeynCalc`ToPaVe`Private`prs:
       PropagatorDenominator[Momentum[_, _] + (_:0), _]..], 
     FeynCalc`ToPaVe`Private`q_, _, _] := 
    I*Pi^2*GenPaVe[{0}, MomentumExpand[{FeynCalc`ToPaVe`Private`prs}] /. 
        PD[Momentum[FeynCalc`ToPaVe`Private`q, _:4] + 
           (FeynCalc`ToPaVe`Private`p_:0), FeynCalc`ToPaVe`Private`m_:0] :> 
         {FeynCalc`ToPaVe`Private`p, FeynCalc`ToPaVe`Private`m}] /; 
     FeynCalc`ToPaVe`Private`genpave
 
FeynCalc`FCLoopFindIntegralMappings`Private`makeMappingRules[
     FeynCalc`FCLoopFindIntegralMappings`Private`ints_List, _List, {}] := 
    {FeynCalc`FCLoopFindIntegralMappings`Private`ints[[1]] -> 
       FeynCalc`FCLoopFindIntegralMappings`Private`ints[[1]]} /; 
     Length[FeynCalc`FCLoopFindIntegralMappings`Private`ints] === 1
 
