     FeynCalc`FCLoopFindIntegralMappings`Private`ints_List, 
     FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals_List /; 
      FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals =!= {}, 
     {}] := 
    (#1 -> First[FeynCalc`FCLoopFindIntegralMappings`Private`ints] & ) /@ 
      Rest[FeynCalc`FCLoopFindIntegralMappings`Private`ints] /; 
     Length[FeynCalc`FCLoopFindIntegralMappings`Private`ints] > 1 && 
      FreeQ2[FeynCalc`FCLoopFindIntegralMappings`Private`ints, 
       FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals]
 
FeynCalc`FCLoopFindIntegralMappings`Private`makeMappingRules[
     FeynCalc`FCLoopFindIntegralMappings`Private`ints_List, {}, {}] := 
    (#1 -> First[FeynCalc`FCLoopFindIntegralMappings`Private`ints] & ) /@ 
      Rest[FeynCalc`FCLoopFindIntegralMappings`Private`ints] /; 
     Length[FeynCalc`FCLoopFindIntegralMappings`Private`ints] > 1
 
FeynCalc`FCLoopFindIntegralMappings`Private`makeMappingRules[
     FeynCalc`FCLoopFindIntegralMappings`Private`ints_List, 
     FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals_List /; 
      FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals =!= {}, 
     {}] := (FeynCalc`FCLoopFindIntegralMappings`Private`lhs = 
       First[Intersection[FeynCalc`FCLoopFindIntegralMappings`Private`ints, 
         FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals]]; 
      (#1 -> FeynCalc`FCLoopFindIntegralMappings`Private`lhs & ) /@ 
       SelectFree[FeynCalc`FCLoopFindIntegralMappings`Private`ints, 
        FeynCalc`FCLoopFindIntegralMappings`Private`lhs]) /; 
     Length[FeynCalc`FCLoopFindIntegralMappings`Private`ints] > 1 && 
       !FreeQ2[FeynCalc`FCLoopFindIntegralMappings`Private`ints, 
        FeynCalc`FCLoopFindIntegralMappings`Private`preferredIntegrals]
 
