     FeynCalc`VertexFunctions`Private`x6_, 
     FeynCalc`VertexFunctions`Private`x7_, 
     FeynCalc`VertexFunctions`Private`x8_, 
     FeynCalc`VertexFunctions`Private`opts:OptionsPattern[]] := 
    GluonVertex[{FeynCalc`VertexFunctions`Private`x1, 
       FeynCalc`VertexFunctions`Private`x2}, 
      {FeynCalc`VertexFunctions`Private`x3, 
       FeynCalc`VertexFunctions`Private`x4}, 
      {FeynCalc`VertexFunctions`Private`x5, 
       FeynCalc`VertexFunctions`Private`x6}, 
      {FeynCalc`VertexFunctions`Private`x7, 
       FeynCalc`VertexFunctions`Private`x8}, 
      FeynCalc`VertexFunctions`Private`opts] /; 
     FreeQ2[Union[Head /@ {FeynCalc`VertexFunctions`Private`x1, 
         FeynCalc`VertexFunctions`Private`x2, 
         FeynCalc`VertexFunctions`Private`x3, 
         FeynCalc`VertexFunctions`Private`x4, 
         FeynCalc`VertexFunctions`Private`x5, 
         FeynCalc`VertexFunctions`Private`x6, 
         FeynCalc`VertexFunctions`Private`x7, 
         FeynCalc`VertexFunctions`Private`x8}], {Integer, Rule, RuleDelayed}]
 
GluonVertex[_, FeynCalc`VertexFunctions`Private`x1_, 
     FeynCalc`VertexFunctions`Private`x2_, _, 
     FeynCalc`VertexFunctions`Private`x3_, 
     FeynCalc`VertexFunctions`Private`x4_, _, 
     FeynCalc`VertexFunctions`Private`x5_, 
