GluonVertex[{___, FeynCalc`VertexFunctions`Private`mui_, 
      FeynCalc`VertexFunctions`Private`ai_}, 
     {___, FeynCalc`VertexFunctions`Private`nui_, 
      FeynCalc`VertexFunctions`Private`bi_}, 
     {___, FeynCalc`VertexFunctions`Private`lai_, 
      FeynCalc`VertexFunctions`Private`ci_}, 
     {___, FeynCalc`VertexFunctions`Private`sii_, 
      FeynCalc`VertexFunctions`Private`di_}, OptionsPattern[]] := 
    Block[{FeynCalc`VertexFunctions`Private`gauge, 
       FeynCalc`VertexFunctions`Private`dim, 
       FeynCalc`VertexFunctions`Private`mu, 
       FeynCalc`VertexFunctions`Private`nu, 
       FeynCalc`VertexFunctions`Private`la, 
       FeynCalc`VertexFunctions`Private`si, 
       FeynCalc`VertexFunctions`Private`a, 
       FeynCalc`VertexFunctions`Private`b, 
       FeynCalc`VertexFunctions`Private`c, 
       FeynCalc`VertexFunctions`Private`d, 
       FeynCalc`VertexFunctions`Private`e, 
       FeynCalc`VertexFunctions`Private`gl4v, 
       FeynCalc`VertexFunctions`Private`coup}, 
      FeynCalc`VertexFunctions`Private`coup = OptionValue[CouplingConstant]; 
       FeynCalc`VertexFunctions`Private`dim = OptionValue[Dimension]; 
       {FeynCalc`VertexFunctions`Private`mu, 
         FeynCalc`VertexFunctions`Private`nu, 
         FeynCalc`VertexFunctions`Private`la, 
         FeynCalc`VertexFunctions`Private`si} = 
        FeynCalc`VertexFunctions`Private`lorfix[
         (LorentzIndex[#1, FeynCalc`VertexFunctions`Private`dim] & ) /@ 
          ({FeynCalc`VertexFunctions`Private`mui, 
            FeynCalc`VertexFunctions`Private`nui, 
            FeynCalc`VertexFunctions`Private`lai, 
            FeynCalc`VertexFunctions`Private`sii} /. 
           ExplicitLorentzIndex[0] -> 0)]; 
       {FeynCalc`VertexFunctions`Private`a, 
         FeynCalc`VertexFunctions`Private`b, 
         FeynCalc`VertexFunctions`Private`c, 
         FeynCalc`VertexFunctions`Private`d} = 
        FeynCalc`VertexFunctions`Private`momfix[(SUNIndex[#1] & ) /@ 
          {FeynCalc`VertexFunctions`Private`ai, 
           FeynCalc`VertexFunctions`Private`bi, 
           FeynCalc`VertexFunctions`Private`ci, 
           FeynCalc`VertexFunctions`Private`di}]; 
       FeynCalc`VertexFunctions`Private`e = SUNIndex[
         FCGV[ToString[Unique["u"]]]]; 
       FeynCalc`VertexFunctions`Private`gl4v = 
        (-I)*FeynCalc`VertexFunctions`Private`coup^2*
         (SUNF[FeynCalc`VertexFunctions`Private`a, 
            FeynCalc`VertexFunctions`Private`b, 
            FeynCalc`VertexFunctions`Private`e]*
           SUNF[FeynCalc`VertexFunctions`Private`c, 
            FeynCalc`VertexFunctions`Private`d, 
            FeynCalc`VertexFunctions`Private`e]*
           (Pair[FeynCalc`VertexFunctions`Private`mu, 
              FeynCalc`VertexFunctions`Private`la]*
             Pair[FeynCalc`VertexFunctions`Private`nu, 
              FeynCalc`VertexFunctions`Private`si] - 
            Pair[FeynCalc`VertexFunctions`Private`mu, 
              FeynCalc`VertexFunctions`Private`si]*
             Pair[FeynCalc`VertexFunctions`Private`nu, 
              FeynCalc`VertexFunctions`Private`la]) + 
          SUNF[FeynCalc`VertexFunctions`Private`a, 
            FeynCalc`VertexFunctions`Private`c, 
            FeynCalc`VertexFunctions`Private`e]*
           SUNF[FeynCalc`VertexFunctions`Private`b, 
            FeynCalc`VertexFunctions`Private`d, 
            FeynCalc`VertexFunctions`Private`e]*
           (Pair[FeynCalc`VertexFunctions`Private`mu, 
              FeynCalc`VertexFunctions`Private`nu]*
             Pair[FeynCalc`VertexFunctions`Private`la, 
              FeynCalc`VertexFunctions`Private`si] - 
            Pair[FeynCalc`VertexFunctions`Private`mu, 
              FeynCalc`VertexFunctions`Private`si]*
             Pair[FeynCalc`VertexFunctions`Private`nu, 
              FeynCalc`VertexFunctions`Private`la]) + 
          SUNF[FeynCalc`VertexFunctions`Private`a, 
            FeynCalc`VertexFunctions`Private`d, 
            FeynCalc`VertexFunctions`Private`e]*
           SUNF[FeynCalc`VertexFunctions`Private`b, 
            FeynCalc`VertexFunctions`Private`c, 
            FeynCalc`VertexFunctions`Private`e]*
           (Pair[FeynCalc`VertexFunctions`Private`mu, 
              FeynCalc`VertexFunctions`Private`nu]*
             Pair[FeynCalc`VertexFunctions`Private`la, 
              FeynCalc`VertexFunctions`Private`si] - 
            Pair[FeynCalc`VertexFunctions`Private`mu, 
              FeynCalc`VertexFunctions`Private`la]*
             Pair[FeynCalc`VertexFunctions`Private`nu, 
              FeynCalc`VertexFunctions`Private`si])); 
       FeynCalc`VertexFunctions`Private`gl4v] /; OptionValue[Explicit]
 
GluonVertex /: MakeBoxes[GluonVertex[{FeynCalc`VertexFunctions`Private`p1_, 
        FeynCalc`VertexFunctions`Private`mu1_}, 
       {FeynCalc`VertexFunctions`Private`p2_, 
        FeynCalc`VertexFunctions`Private`mu2_}, 
       {FeynCalc`VertexFunctions`Private`p3_, 
        FeynCalc`VertexFunctions`Private`mu3_}], TraditionalForm] := 
     RowBox[{SuperscriptBox["V", TBox[FeynCalc`VertexFunctions`Private`mu1, 
         FeynCalc`VertexFunctions`Private`mu2, 
         FeynCalc`VertexFunctions`Private`mu3]], "(", 
       TBox[FeynCalc`VertexFunctions`Private`p1, ", ", 
        FeynCalc`VertexFunctions`Private`p2, ", ", 
        FeynCalc`VertexFunctions`Private`p3], ")"}]
 
GluonVertex /: MakeBoxes[GluonVertex[
       {_, FeynCalc`VertexFunctions`Private`mu1_}, 
       {_, FeynCalc`VertexFunctions`Private`mu2_}, 
       {_, FeynCalc`VertexFunctions`Private`mu3_}, 
       {_, FeynCalc`VertexFunctions`Private`mu4_}], TraditionalForm] := 
     SuperscriptBox["V", TBox[FeynCalc`VertexFunctions`Private`mu1, 
       FeynCalc`VertexFunctions`Private`mu2, 
       FeynCalc`VertexFunctions`Private`mu3, 
       FeynCalc`VertexFunctions`Private`mu4]]
 
GluonVertex /: MakeBoxes[GluonVertex[{FeynCalc`VertexFunctions`Private`p1_, 
        FeynCalc`VertexFunctions`Private`mu1_, 
        FeynCalc`VertexFunctions`Private`a_}, 
       {FeynCalc`VertexFunctions`Private`p2_, 
        FeynCalc`VertexFunctions`Private`mu2_, 
        FeynCalc`VertexFunctions`Private`b_}, 
       {FeynCalc`VertexFunctions`Private`p3_, 
        FeynCalc`VertexFunctions`Private`mu3_, 
        FeynCalc`VertexFunctions`Private`c_}, 
       {FeynCalc`VertexFunctions`Private`p4_, 
        FeynCalc`VertexFunctions`Private`mu4_, 
        FeynCalc`VertexFunctions`Private`d_}], TraditionalForm] := 
     RowBox[{SubsuperscriptBox["V", TBox[FeynCalc`VertexFunctions`Private`a, 
         FeynCalc`VertexFunctions`Private`b, 
         FeynCalc`VertexFunctions`Private`c, 
         FeynCalc`VertexFunctions`Private`d], 
        TBox[FeynCalc`VertexFunctions`Private`mu1, 
         FeynCalc`VertexFunctions`Private`mu2, 
         FeynCalc`VertexFunctions`Private`mu3, 
         FeynCalc`VertexFunctions`Private`mu4]], "(", 
       TBox[FeynCalc`VertexFunctions`Private`p1, ", ", 
        FeynCalc`VertexFunctions`Private`p2, ", ", 
        FeynCalc`VertexFunctions`Private`p3, ", ", 
        FeynCalc`VertexFunctions`Private`p4], ")"}]
 
Options[GluonVertex] = {CouplingConstant -> SMP["g_s"], Dimension -> D, 
     Explicit -> False}
 
GluonVertex /: GluonVertex::usage = "GluonVertex[{p, mu, a}, {q, nu, b}, {k, \
la, c}] or GluonVertex[p, mu, a, q,\nnu, b, k, la, c] yields the 3-gluon \
vertex.\n\nGluonVertex[{p, mu}, {q, nu}, {k, la}] yields the 3-gluon vertex \
without color\nstructure and the coupling constant.\n\nGluonVertex[{p, mu, \
a}, {q, nu, b}, {k, la, c}, {s, si, d}] or\nGluonVertex[{mu, a}, {nu, b}, \
{la, c}, {si, d}] or GluonVertex[p, mu, a, q,\nnu, b, k, la, c , s, si, d] or \
GluonVertex[mu, a, nu, b, la, c, si, d] yields\nthe 4-gluon vertex.\n\nGV can \
be used as an abbreviation of GluonVertex.\n\nThe dimension and the name of \
the coupling constant are determined by the\noptions Dimension and \
CouplingConstant. All momenta are flowing into the\nvertex."
 
FeynCalc`VertexFunctions`Private`lorfix[
     FeynCalc`VertexFunctions`Private`w_] := 
    MomentumCombine[FeynCalc`VertexFunctions`Private`w, LeafCount -> 1000] /. 
      LorentzIndex -> FeynCalc`VertexFunctions`Private`lorf /. 
     FeynCalc`VertexFunctions`Private`lorf -> LorentzIndex
 
FeynCalc`VertexFunctions`Private`lorf[
     FeynCalc`VertexFunctions`Private`y_FeynCalc`VertexFunctions`Private`lorf\
, ___] := FeynCalc`VertexFunctions`Private`y
 
FeynCalc`VertexFunctions`Private`lorf[
     FeynCalc`VertexFunctions`Private`y_Momentum, ___] := 
    FeynCalc`VertexFunctions`Private`y
 
FeynCalc`VertexFunctions`Private`momfix[
     FeynCalc`VertexFunctions`Private`v_] := 
    MomentumCombine[FeynCalc`VertexFunctions`Private`v, LeafCount -> 1000] /. 
      Momentum -> FeynCalc`VertexFunctions`Private`momf /. 
     FeynCalc`VertexFunctions`Private`momf -> Momentum
 
FeynCalc`VertexFunctions`Private`momf[
     FeynCalc`VertexFunctions`Private`y_FeynCalc`VertexFunctions`Private`momf\
, ___] := FeynCalc`VertexFunctions`Private`y
 
CouplingConstant /: CouplingConstant::usage = "CouplingConstant is an option \
for several Feynman rule functions and for\nCovariantD and FieldStrength. In \
the convention of the add-on PHI,\nCouplingConstant is also the head of \
coupling constants.  CouplingConstant\ntakes three extra optional arguments, \
with heads RenormalizationState,\nRenormalizationScheme and ExpansionState \
respectively.  E.g.\nCouplingConstant[QED[1]] is the unit charge, \
CouplingConstant[ChPT2[4],1] is\nthe first of the coupling constants of the \
Lagrangian ChPT2[4].  \n\nCouplingConstant[a_,b_,c___][i_] \
:=\nCouplingConstant[a,b,RenormalizationState[i],c]."
 
GluonPropagator[FeynCalc`PropagatorFunctions`Private`a_, 
     FeynCalc`PropagatorFunctions`Private`b_, 
     FeynCalc`PropagatorFunctions`Private`c_, 
     FeynCalc`PropagatorFunctions`Private`d_, 
     FeynCalc`PropagatorFunctions`Private`e_, 
     FeynCalc`PropagatorFunctions`Private`opt:OptionsPattern[]] := 
    GluonPropagator[FeynCalc`PropagatorFunctions`Private`a, 
      {FeynCalc`PropagatorFunctions`Private`b, 
       FeynCalc`PropagatorFunctions`Private`c}, 
      {FeynCalc`PropagatorFunctions`Private`d, 
       FeynCalc`PropagatorFunctions`Private`e}, 
      FeynCalc`PropagatorFunctions`Private`opt] /; 
     FreeQ[{FeynCalc`PropagatorFunctions`Private`a, 
       FeynCalc`PropagatorFunctions`Private`b, 
       FeynCalc`PropagatorFunctions`Private`c, 
       FeynCalc`PropagatorFunctions`Private`d, 
       FeynCalc`PropagatorFunctions`Private`e}, Rule]
 
GluonPropagator[FeynCalc`PropagatorFunctions`Private`q_, 
     {FeynCalc`PropagatorFunctions`Private`li_}, 
     {FeynCalc`PropagatorFunctions`Private`mu_}, 
     FeynCalc`PropagatorFunctions`Private`opt:OptionsPattern[]] := 
    GluonPropagator[-FeynCalc`PropagatorFunctions`Private`q, 
      {FeynCalc`PropagatorFunctions`Private`li}, 
      {FeynCalc`PropagatorFunctions`Private`mu}, 
      FeynCalc`PropagatorFunctions`Private`opt] /; 
     NumericalFactor[FeynCalc`PropagatorFunctions`Private`q] === -1
 
GluonPropagator[FeynCalc`PropagatorFunctions`Private`pi_, 
     FeynCalc`PropagatorFunctions`Private`mu_, 
     FeynCalc`PropagatorFunctions`Private`nu_, 
     FeynCalc`PropagatorFunctions`Private`opt:OptionsPattern[]] := 
    GluonPropagator[FeynCalc`PropagatorFunctions`Private`pi, 
      {FeynCalc`PropagatorFunctions`Private`mu}, 
      {FeynCalc`PropagatorFunctions`Private`nu}, 
      FeynCalc`PropagatorFunctions`Private`opt] /; 
      !MemberQ[{Rule, List}, 
        Head[FeynCalc`PropagatorFunctions`Private`mu]] && 
       !MemberQ[{Rule, List}, Head[FeynCalc`PropagatorFunctions`Private`nu]]
 
GluonPropagator[FeynCalc`PropagatorFunctions`Private`pi_, 
     {FeynCalc`PropagatorFunctions`Private`mui_, 
      FeynCalc`PropagatorFunctions`Private`ai___}, 
     {FeynCalc`PropagatorFunctions`Private`nui_, 
      FeynCalc`PropagatorFunctions`Private`bi___}, OptionsPattern[]] := 
    Block[{FeynCalc`PropagatorFunctions`Private`gauge, 
       FeynCalc`PropagatorFunctions`Private`gluemass, 
       FeynCalc`PropagatorFunctions`Private`dim, 
       FeynCalc`PropagatorFunctions`Private`p, 
       FeynCalc`PropagatorFunctions`Private`mu, 
       FeynCalc`PropagatorFunctions`Private`nu, 
       FeynCalc`PropagatorFunctions`Private`a, 
       FeynCalc`PropagatorFunctions`Private`b, 
       FeynCalc`PropagatorFunctions`Private`glp, 
       FeynCalc`PropagatorFunctions`Private`n, 
       FeynCalc`PropagatorFunctions`Private`ope, 
       FeynCalc`PropagatorFunctions`Private`opepart, 
       FeynCalc`PropagatorFunctions`Private`mud, 
       FeynCalc`PropagatorFunctions`Private`nud, 
       FeynCalc`PropagatorFunctions`Private`ad, 
       FeynCalc`PropagatorFunctions`Private`bd, 
       FeynCalc`PropagatorFunctions`Private`sundelta, 
       FeynCalc`PropagatorFunctions`Private`p2, 
       FeynCalc`PropagatorFunctions`Private`cou, 
       FeynCalc`PropagatorFunctions`Private`gst, 
       FeynCalc`PropagatorFunctions`Private`gmunu, 
       FeynCalc`PropagatorFunctions`Private`pmu, 
       FeynCalc`PropagatorFunctions`Private`pnu}, 
      FeynCalc`PropagatorFunctions`Private`gauge = OptionValue[Gauge]; 
       FeynCalc`PropagatorFunctions`Private`dim = OptionValue[Dimension]; 
       FeynCalc`PropagatorFunctions`Private`gst = OptionValue[
         CouplingConstant]; FeynCalc`PropagatorFunctions`Private`mu = 
        LorentzIndex[FeynCalc`PropagatorFunctions`Private`mui, 
         FeynCalc`PropagatorFunctions`Private`dim]; 
       FeynCalc`PropagatorFunctions`Private`nu = LorentzIndex[
         FeynCalc`PropagatorFunctions`Private`nui, 
         FeynCalc`PropagatorFunctions`Private`dim]; 
       If[Head[FeynCalc`PropagatorFunctions`Private`pi] === List, 
        FeynCalc`PropagatorFunctions`Private`p = Momentum[
           FeynCalc`PropagatorFunctions`Private`pi[[1]], 
           FeynCalc`PropagatorFunctions`Private`dim]; 
         FeynCalc`PropagatorFunctions`Private`gluemass = 
          FeynCalc`PropagatorFunctions`Private`pi[[2]], 
        FeynCalc`PropagatorFunctions`Private`p = Momentum[
           FeynCalc`PropagatorFunctions`Private`pi, 
           FeynCalc`PropagatorFunctions`Private`dim]; 
         FeynCalc`PropagatorFunctions`Private`gluemass = 0; ]; 
       If[Length[{FeynCalc`PropagatorFunctions`Private`ai}] === 
         Length[{FeynCalc`PropagatorFunctions`Private`bi}] === 1, 
        FeynCalc`PropagatorFunctions`Private`sundelta = 
         SUNDelta[SUNIndex[FeynCalc`PropagatorFunctions`Private`ai], 
          SUNIndex[FeynCalc`PropagatorFunctions`Private`bi]], 
        FeynCalc`PropagatorFunctions`Private`sundelta = 1]; 
       If[Head[FeynCalc`PropagatorFunctions`Private`gauge] === List, 
        FeynCalc`PropagatorFunctions`Private`n = 
          FeynCalc`PropagatorFunctions`Private`gauge[[1]]; 
         If[FreeQ[FeynCalc`PropagatorFunctions`Private`n, Momentum], 
          FeynCalc`PropagatorFunctions`Private`n = Momentum[
            FeynCalc`PropagatorFunctions`Private`n, 
            FeynCalc`PropagatorFunctions`Private`dim]]; 
         FeynCalc`PropagatorFunctions`Private`glp = 
          I*FeynAmpDenominator[PD[FeynCalc`PropagatorFunctions`Private`p, 
             FeynCalc`PropagatorFunctions`Private`gluemass]]*
           FeynCalc`PropagatorFunctions`Private`sundelta*
           (-Pair[FeynCalc`PropagatorFunctions`Private`mu, 
              FeynCalc`PropagatorFunctions`Private`nu] + 
            (Pair[FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`mu]*Pair[
                FeynCalc`PropagatorFunctions`Private`p, 
                FeynCalc`PropagatorFunctions`Private`nu] + 
              Pair[FeynCalc`PropagatorFunctions`Private`p, 
                FeynCalc`PropagatorFunctions`Private`mu]*Pair[
                FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`nu])*FeynAmpDenominator[
              StandardPropagatorDenominator[0, Pair[
                FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`p], 0, {1, 1}]] - 
            (Pair[FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`n]*Pair[
                FeynCalc`PropagatorFunctions`Private`p, 
                FeynCalc`PropagatorFunctions`Private`mu]*Pair[
                FeynCalc`PropagatorFunctions`Private`p, 
                FeynCalc`PropagatorFunctions`Private`nu] - 
              FeynCalc`PropagatorFunctions`Private`gauge[[2]]*Pair[
                FeynCalc`PropagatorFunctions`Private`p, 
                FeynCalc`PropagatorFunctions`Private`p]*Pair[
                FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`mu]*Pair[
                FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`nu])*FeynAmpDenominator[
              StandardPropagatorDenominator[0, Pair[
                FeynCalc`PropagatorFunctions`Private`n, 
                FeynCalc`PropagatorFunctions`Private`p], 0, {2, 1}]]), 
        FeynCalc`PropagatorFunctions`Private`glp = 
          I*FeynAmpDenominator[PD[FeynCalc`PropagatorFunctions`Private`p, 
             FeynCalc`PropagatorFunctions`Private`gluemass]]*
           FeynCalc`PropagatorFunctions`Private`sundelta*
           (-Pair[FeynCalc`PropagatorFunctions`Private`mu, 
              FeynCalc`PropagatorFunctions`Private`nu] + 
            (1 - FeynCalc`PropagatorFunctions`Private`gauge)*
             Pair[FeynCalc`PropagatorFunctions`Private`p, 
              FeynCalc`PropagatorFunctions`Private`mu]*
             Pair[FeynCalc`PropagatorFunctions`Private`p, 
              FeynCalc`PropagatorFunctions`Private`nu]*FeynAmpDenominator[
              PD[MomentumExpand[FeynCalc`PropagatorFunctions`Private`p], 
               FeynCalc`PropagatorFunctions`Private`gluemass]]); ]; 
       FeynCalc`PropagatorFunctions`Private`glp] /; OptionValue[Explicit]
 
GluonPropagator /: MakeBoxes[GluonPropagator[
       FeynCalc`PropagatorFunctions`Private`p_, 
       {FeynCalc`PropagatorFunctions`Private`mu_, 
        FeynCalc`PropagatorFunctions`Private`a_}, 
       {FeynCalc`PropagatorFunctions`Private`nu_, 
        FeynCalc`PropagatorFunctions`Private`b_}, OptionsPattern[]], 
      TraditionalForm] := RowBox[{SubsuperscriptBox["\[CapitalPi]", 
        TBox[FeynCalc`PropagatorFunctions`Private`a, 
         FeynCalc`PropagatorFunctions`Private`b], 
        TBox[FeynCalc`PropagatorFunctions`Private`mu, 
         FeynCalc`PropagatorFunctions`Private`nu]], "(", 
       TBox[FeynCalc`PropagatorFunctions`Private`p], ")"}]
 
GluonPropagator /: MakeBoxes[GluonPropagator[
       FeynCalc`PropagatorFunctions`Private`p_, 
       {FeynCalc`PropagatorFunctions`Private`mu_}, 
       {FeynCalc`PropagatorFunctions`Private`nu_}, OptionsPattern[]], 
      TraditionalForm] := RowBox[{SubsuperscriptBox["\[CapitalPi]", "g", 
        TBox[FeynCalc`PropagatorFunctions`Private`mu, 
         FeynCalc`PropagatorFunctions`Private`nu]], "(", 
       TBox[FeynCalc`PropagatorFunctions`Private`p], ")"}]
 
Options[GluonPropagator] = {CouplingConstant -> SMP["g_s"], Dimension -> D, 
     Explicit -> False, Gauge -> 1}
 
GluonPropagator /: GluonPropagator::usage = "GluonPropagator[p, {mu, a}, {nu, \
b}] or GluonPropagator[p, mu, a, nu, b]\nyields the gluon \
propagator.\n\nGluonPropagator[p, {mu}, {nu}] or GluonPropagator[p, mu, nu] \
omits the\nSUNDelta.\n\nGP can be used as an abbreviation of \
GluonPropagator.\n\nThe gauge and the dimension are determined by the options \
Gauge and Dimension.\nThe following settings of Gauge are possible:\n\n- 1 \
for the Feynman gauge\n- alpha for the general covariant gauge\n- \
{Momentum[n] ,1} for the axial gauge"
 
Gauge /: Gauge::usage = "Gauge is an option for GluonPropagator. If set to 1 \
the 't Hooft Feynman gauge\nis used."
 
GhostPropagator[FeynCalc`PropagatorFunctions`Private`pi_, 
     OptionsPattern[]] := Block[{FeynCalc`PropagatorFunctions`Private`p, 
       FeynCalc`PropagatorFunctions`Private`glp}, 
      FeynCalc`PropagatorFunctions`Private`p = 
        Momentum[FeynCalc`PropagatorFunctions`Private`pi, 
         OptionValue[Dimension]]; FeynCalc`PropagatorFunctions`Private`glp = 
        I*FeynAmpDenominator[PropagatorDenominator[
           FeynCalc`PropagatorFunctions`Private`p, 0]]; 
       QCDFeynmanRuleConvention[GhostPropagator]*
        FeynCalc`PropagatorFunctions`Private`glp] /; OptionValue[Explicit]
 
GhostPropagator[FeynCalc`PropagatorFunctions`Private`pi_, 
     FeynCalc`PropagatorFunctions`Private`ai_, 
     FeynCalc`PropagatorFunctions`Private`bi_, OptionsPattern[]] := 
    Block[{FeynCalc`PropagatorFunctions`Private`p, 
       FeynCalc`PropagatorFunctions`Private`a, 
       FeynCalc`PropagatorFunctions`Private`b, 
       FeynCalc`PropagatorFunctions`Private`glp}, 
      FeynCalc`PropagatorFunctions`Private`p = 
        Momentum[FeynCalc`PropagatorFunctions`Private`pi, 
         OptionValue[Dimension]]; FeynCalc`PropagatorFunctions`Private`a = 
        SUNIndex[FeynCalc`PropagatorFunctions`Private`ai]; 
       FeynCalc`PropagatorFunctions`Private`b = 
        SUNIndex[FeynCalc`PropagatorFunctions`Private`bi]; 
       FeynCalc`PropagatorFunctions`Private`glp = 
        I*FeynAmpDenominator[PropagatorDenominator[
           FeynCalc`PropagatorFunctions`Private`p, 0]]*
         SUNDelta[FeynCalc`PropagatorFunctions`Private`a, 
          FeynCalc`PropagatorFunctions`Private`b]; 
       QCDFeynmanRuleConvention[GhostPropagator]*
        FeynCalc`PropagatorFunctions`Private`glp] /; OptionValue[Explicit]
 
GhostPropagator /: MakeBoxes[GhostPropagator[
       FeynCalc`PropagatorFunctions`Private`p_, 
       FeynCalc`PropagatorFunctions`Private`a_, 
       FeynCalc`PropagatorFunctions`Private`b_], TraditionalForm] := 
     RowBox[{SubscriptBox["\[CapitalPi]", 
        TBox[FeynCalc`PropagatorFunctions`Private`a, 
         FeynCalc`PropagatorFunctions`Private`b]], "(", 
       TBox[FeynCalc`PropagatorFunctions`Private`p], ")"}]
 
GhostPropagator /: MakeBoxes[GhostPropagator[
       FeynCalc`PropagatorFunctions`Private`p_], TraditionalForm] := 
     RowBox[{SubscriptBox["\[CapitalPi]", "u"], "(", 
       TBox[FeynCalc`PropagatorFunctions`Private`p], ")"}]
 
Options[GhostPropagator] = {Dimension -> D, Explicit -> False}
 
GhostPropagator /: GhostPropagator::usage = "GhostPropagator[p, a, b] gives \
the ghost propagator where a and b are the\ncolor \
indices.\n\nGhostPropagator[p] omits the $\\delta _{ab}$.\n\nGHP can be used \
as an abbreviation of GhostPropagator."
 
QCDFeynmanRuleConvention[GhostPropagator] = 1
 
QCDFeynmanRuleConvention[GluonGhostVertex] = 1
 
QCDFeynmanRuleConvention /: QCDFeynmanRuleConvention::usage = "QCDFeynmanRule\
Convention fixes the sign convention in the QCD Feynman rules\nfor the ghost \
propagator and the ghost-gluon vertex.This is done by setting\nthe value of \
QCDFeynmanRuleConvention[GhostPropagator] \
and\nQCDFeynmanRuleConvention[GluonGhostVertex].\n\nThe default values are 1 \
for both, which corresponds to the convention used in\nmost books. Setting \
them to -1 enforces the convention that can be found e.g.\nin the book \
\"Applications of Perturbative QCD\" by R. Field."
 
GluonGhostVertex[{_, FeynCalc`VertexFunctions`Private`ai_}, 
     {FeynCalc`VertexFunctions`Private`bi_}, 
     {FeynCalc`VertexFunctions`Private`ki_, 
      FeynCalc`VertexFunctions`Private`ci_}, 
     FeynCalc`VertexFunctions`Private`opt:OptionsPattern[]] := 
    GluonGhostVertex[{FCGV["x"], FCGV["y"], 
       FeynCalc`VertexFunctions`Private`ai}, {FCGV["z"], FCGV["h"], 
       FeynCalc`VertexFunctions`Private`bi}, 
      {FeynCalc`VertexFunctions`Private`ki, FCGV["l"], 
       FeynCalc`VertexFunctions`Private`ci}, 
      FeynCalc`VertexFunctions`Private`opt] /; OptionValue[Explicit]
 
GluonGhostVertex[FeynCalc`VertexFunctions`Private`a_, 
     FeynCalc`VertexFunctions`Private`b_, 
     FeynCalc`VertexFunctions`Private`c_, 
     FeynCalc`VertexFunctions`Private`d_, 
     FeynCalc`VertexFunctions`Private`e_, 
     FeynCalc`VertexFunctions`Private`f_, 
     FeynCalc`VertexFunctions`Private`g_, 
     FeynCalc`VertexFunctions`Private`h_, 
     FeynCalc`VertexFunctions`Private`i_, 
     FeynCalc`VertexFunctions`Private`opt:OptionsPattern[]] := 
    GluonGhostVertex[{FeynCalc`VertexFunctions`Private`a, 
       FeynCalc`VertexFunctions`Private`b, 
       FeynCalc`VertexFunctions`Private`c}, 
      {FeynCalc`VertexFunctions`Private`d, 
       FeynCalc`VertexFunctions`Private`e, 
       FeynCalc`VertexFunctions`Private`f}, 
      {FeynCalc`VertexFunctions`Private`g, 
       FeynCalc`VertexFunctions`Private`h, 
       FeynCalc`VertexFunctions`Private`i}, 
      FeynCalc`VertexFunctions`Private`opt] /; 
     FreeQ[Head /@ {FeynCalc`VertexFunctions`Private`a, 
        FeynCalc`VertexFunctions`Private`b, 
        FeynCalc`VertexFunctions`Private`c, 
        FeynCalc`VertexFunctions`Private`d, 
        FeynCalc`VertexFunctions`Private`e, 
        FeynCalc`VertexFunctions`Private`f, 
        FeynCalc`VertexFunctions`Private`g, 
        FeynCalc`VertexFunctions`Private`h, 
        FeynCalc`VertexFunctions`Private`i}, Integer | Rule | RuleDelayed | 
       List, Heads -> False]
 
GluonGhostVertex[{_, FeynCalc`VertexFunctions`Private`mui_, 
      FeynCalc`VertexFunctions`Private`ai_}, 
     {___, FeynCalc`VertexFunctions`Private`bi_}, 
     {FeynCalc`VertexFunctions`Private`ki_, ___, 
      FeynCalc`VertexFunctions`Private`ci_}, 
     FeynCalc`VertexFunctions`Private`opt:OptionsPattern[]] := 
    SUNF[SUNIndex[FeynCalc`VertexFunctions`Private`ai], 
      SUNIndex[FeynCalc`VertexFunctions`Private`bi], 
      SUNIndex[FeynCalc`VertexFunctions`Private`ci]]*
     GluonGhostVertex[FeynCalc`VertexFunctions`Private`ki, 
      FeynCalc`VertexFunctions`Private`mui, 
      FeynCalc`VertexFunctions`Private`opt]
 
GluonGhostVertex[FeynCalc`VertexFunctions`Private`ki_, 
     FeynCalc`VertexFunctions`Private`mui_, OptionsPattern[]] := 
    Block[{FeynCalc`VertexFunctions`Private`dim, 
       FeynCalc`VertexFunctions`Private`k, 
       FeynCalc`VertexFunctions`Private`mu, 
       FeynCalc`VertexFunctions`Private`re}, 
      FeynCalc`VertexFunctions`Private`dim = OptionValue[Dimension]; 
       FeynCalc`VertexFunctions`Private`k = Momentum[
         FeynCalc`VertexFunctions`Private`ki, 
         FeynCalc`VertexFunctions`Private`dim]; 
       FeynCalc`VertexFunctions`Private`mu = LorentzIndex[
         FeynCalc`VertexFunctions`Private`mui, 
         FeynCalc`VertexFunctions`Private`dim]; 
       FeynCalc`VertexFunctions`Private`re = (-OptionValue[CouplingConstant])*
         Pair[FeynCalc`VertexFunctions`Private`k, 
          FeynCalc`VertexFunctions`Private`mu]; 
       FeynCalc`VertexFunctions`Private`re = QCDFeynmanRuleConvention[
          GluonGhostVertex]*FeynCalc`VertexFunctions`Private`re; 
       FeynCalc`VertexFunctions`Private`re] /; OptionValue[Explicit]
 
GluonGhostVertex /: MakeBoxes[GluonGhostVertex[
       FeynCalc`VertexFunctions`Private`p3_, 
       FeynCalc`VertexFunctions`Private`mu3_], TraditionalForm] := 
     RowBox[{SuperscriptBox[OverscriptBox["\[CapitalLambda]", "~"], 
        TBox[FeynCalc`VertexFunctions`Private`mu3]], "(", 
       TBox[FeynCalc`VertexFunctions`Private`p3], ")"}]
 
GluonGhostVertex /: MakeBoxes[GluonGhostVertex[{_, _}, {_, _}, 
       {FeynCalc`VertexFunctions`Private`p3_, 
        FeynCalc`VertexFunctions`Private`mu3_}], TraditionalForm] := 
     RowBox[{SuperscriptBox[OverscriptBox["\[CapitalLambda]", "~"], 
        TBox[FeynCalc`VertexFunctions`Private`mu3]], "(", 
       TBox[FeynCalc`VertexFunctions`Private`p3], ")"}]
 
Options[GluonGhostVertex] = {CouplingConstant -> SMP["g_s"], Dimension -> D, 
     Explicit -> False}
 
GluonGhostVertex /: GluonGhostVertex::usage = "GluonGhostVertex[{p, mu, a}, \
{q, nu, b}, {k, rho, c}] or GluonGhostVertex[ p,\nmu, a , q, nu, b , k, rho, \
c] yields the Gluon-Ghost vertex. The first\nargument represents the gluon \
and the third argument the outgoing ghost field\n(but incoming \
4-momentum).\n\nGGV can be used as an abbreviation of GluonGhostVertex.The \
dimension and the\nname of the coupling constant are determined by the \
options Dimension and\nCouplingConstant."
 
QuarkPropagator[FeynCalc`PropagatorFunctions`Private`pi:Except[_?OptionQ], 
     FeynCalc`PropagatorFunctions`Private`opt:OptionsPattern[]] := 
    QuarkPropagator[{FeynCalc`PropagatorFunctions`Private`pi, 0}, 
      FeynCalc`PropagatorFunctions`Private`opt] /; 
     Head[FeynCalc`PropagatorFunctions`Private`pi] =!= List
 
QuarkPropagator[{FeynCalc`PropagatorFunctions`Private`pi_, 
      FeynCalc`PropagatorFunctions`Private`m_}, OptionsPattern[]] := 
    Block[{FeynCalc`PropagatorFunctions`Private`dim, 
       FeynCalc`PropagatorFunctions`Private`re, 
       FeynCalc`PropagatorFunctions`Private`ope, 
       FeynCalc`PropagatorFunctions`Private`pol, 
       FeynCalc`PropagatorFunctions`Private`cou, 
       FeynCalc`PropagatorFunctions`Private`cop, 
       FeynCalc`PropagatorFunctions`Private`loo}, 
      FeynCalc`PropagatorFunctions`Private`dim = OptionValue[Dimension]; 
       FeynCalc`PropagatorFunctions`Private`re = 
        I*(DiracGamma[Momentum[FeynCalc`PropagatorFunctions`Private`pi, 
            FeynCalc`PropagatorFunctions`Private`dim], 
           FeynCalc`PropagatorFunctions`Private`dim] + 
          FeynCalc`PropagatorFunctions`Private`m)*FeynAmpDenominator[
          PropagatorDenominator[MomentumExpand[Momentum[
             FeynCalc`PropagatorFunctions`Private`pi, 
             FeynCalc`PropagatorFunctions`Private`dim]], 
           FeynCalc`PropagatorFunctions`Private`m]]; 
       FeynCalc`PropagatorFunctions`Private`re] /; OptionValue[Explicit]
 
QuarkPropagator /: MakeBoxes[QuarkPropagator[
       {FeynCalc`PropagatorFunctions`Private`p_, _}, OptionsPattern[]], 
      TraditionalForm] := RowBox[{SubscriptBox["\[CapitalPi]", "q"], "(", 
       TBox[FeynCalc`PropagatorFunctions`Private`p], ")"}]
 
Options[QuarkPropagator] = {Dimension -> D, Explicit -> False}
 
QuarkPropagator /: QuarkPropagator::usage = "QuarkPropagator[p] is the \
massless quark propagator.\n\nQuarkPropagator[{p, m}] gives the quark \
propagator with mass $m$.\n\nQP can be used as an abbreviation of \
QuarkPropagator."
 
QuarkGluonVertex[FeynCalc`VertexFunctions`Private`x1_, 
     FeynCalc`VertexFunctions`Private`x2_, 
     FeynCalc`VertexFunctions`Private`x3_, 
     FeynCalc`VertexFunctions`Private`x4_, 
     FeynCalc`VertexFunctions`Private`x5_, 
     FeynCalc`VertexFunctions`Private`x6_, 
     FeynCalc`VertexFunctions`Private`x7_, 
     FeynCalc`VertexFunctions`Private`x8_, 
     FeynCalc`VertexFunctions`Private`x9_, FeynCalc`VertexFunctions`Private`y:
      OptionsPattern[]] := QuarkGluonVertex[
      {FeynCalc`VertexFunctions`Private`x1, 
       FeynCalc`VertexFunctions`Private`x2, 
       FeynCalc`VertexFunctions`Private`x3}, 
      {FeynCalc`VertexFunctions`Private`x4, 
       FeynCalc`VertexFunctions`Private`x5, 
       FeynCalc`VertexFunctions`Private`x6}, 
      {FeynCalc`VertexFunctions`Private`x7, 
       FeynCalc`VertexFunctions`Private`x8, 
       FeynCalc`VertexFunctions`Private`x9}, 
      FeynCalc`VertexFunctions`Private`y] /; 
     FreeQ[Union[Head /@ {FeynCalc`VertexFunctions`Private`x1, 
         FeynCalc`VertexFunctions`Private`x2, 
