         FeynCalc`VertexFunctions`Private`x4, 
         FeynCalc`VertexFunctions`Private`x5, 
         FeynCalc`VertexFunctions`Private`x6, 
         FeynCalc`VertexFunctions`Private`x7, 
         FeynCalc`VertexFunctions`Private`x8, 
         FeynCalc`VertexFunctions`Private`x9}], Integer | Rule]
 
QuarkGluonVertex[FeynCalc`VertexFunctions`Private`mui_, 
     FeynCalc`VertexFunctions`Private`ai_ /; 
      Head[FeynCalc`VertexFunctions`Private`ai] =!= Rule, 
     FeynCalc`VertexFunctions`Private`opt:OptionsPattern[]] := 
    QuarkGluonVertex[{Null, FeynCalc`VertexFunctions`Private`mui, 
       FeynCalc`VertexFunctions`Private`ai}, {Null, Null, Null}, 
      {Null, Null, Null}, FeynCalc`VertexFunctions`Private`opt] /; 
     FreeQ[Union[Head /@ {FeynCalc`VertexFunctions`Private`mui, 
         FeynCalc`VertexFunctions`Private`ai}], Integer]
 
QuarkGluonVertex[{FeynCalc`VertexFunctions`Private`p_, 
      FeynCalc`VertexFunctions`Private`mui_, 
      FeynCalc`VertexFunctions`Private`ai_}, 
     {FeynCalc`VertexFunctions`Private`q_, ___}, 
     {FeynCalc`VertexFunctions`Private`k_, ___}, OptionsPattern[]] := 
    Block[{FeynCalc`VertexFunctions`Private`gauge, 
       FeynCalc`VertexFunctions`Private`dim, 
       FeynCalc`VertexFunctions`Private`mu, 
       FeynCalc`VertexFunctions`Private`a, 
       FeynCalc`VertexFunctions`Private`gl3v, 
       FeynCalc`VertexFunctions`Private`coun, 
       FeynCalc`VertexFunctions`Private`coup, 
       FeynCalc`VertexFunctions`Private`ope, 
       FeynCalc`VertexFunctions`Private`pol}, 
      FeynCalc`VertexFunctions`Private`coup = OptionValue[CouplingConstant]; 
       FeynCalc`VertexFunctions`Private`dim = OptionValue[Dimension]; 
       FeynCalc`VertexFunctions`Private`pol = OptionValue[Polarization]; 
       FeynCalc`VertexFunctions`Private`mu = LorentzIndex[
         FeynCalc`VertexFunctions`Private`mui, 
         FeynCalc`VertexFunctions`Private`dim]; 
       FeynCalc`VertexFunctions`Private`a = SUNIndex[
         FeynCalc`VertexFunctions`Private`ai]; 
       FeynCalc`VertexFunctions`Private`gl3v = 
        I*FeynCalc`VertexFunctions`Private`coup*
         DOT[SUNT[FeynCalc`VertexFunctions`Private`a], 
          DiracGamma[FeynCalc`VertexFunctions`Private`mu, 
           FeynCalc`VertexFunctions`Private`dim]]; 
       FeynCalc`VertexFunctions`Private`gl3v] /; OptionValue[Explicit] && 
      FreeQ[Union[Head /@ {FeynCalc`VertexFunctions`Private`mui, 
          FeynCalc`VertexFunctions`Private`ai}], Integer]
 
QuarkGluonVertex[FeynCalc`VertexFunctions`Private`mui_, OptionsPattern[]] := 
    Block[{FeynCalc`VertexFunctions`Private`gauge, 
       FeynCalc`VertexFunctions`Private`dim, 
       FeynCalc`VertexFunctions`Private`mu, 
       FeynCalc`VertexFunctions`Private`a, 
       FeynCalc`VertexFunctions`Private`gl3v, 
       FeynCalc`VertexFunctions`Private`coun, 
       FeynCalc`VertexFunctions`Private`coup, 
       FeynCalc`VertexFunctions`Private`ope, 
       FeynCalc`VertexFunctions`Private`pol}, 
      FeynCalc`VertexFunctions`Private`coup = OptionValue[CouplingConstant]; 
       FeynCalc`VertexFunctions`Private`dim = OptionValue[Dimension]; 
       FeynCalc`VertexFunctions`Private`pol = OptionValue[Polarization]; 
       FeynCalc`VertexFunctions`Private`mu = LorentzIndex[
         FeynCalc`VertexFunctions`Private`mui, 
         FeynCalc`VertexFunctions`Private`dim]; 
       FeynCalc`VertexFunctions`Private`gl3v = 
        I*FeynCalc`VertexFunctions`Private`coup*DiracGamma[
          FeynCalc`VertexFunctions`Private`mu, 
          FeynCalc`VertexFunctions`Private`dim]; 
       FeynCalc`VertexFunctions`Private`gl3v] /; OptionValue[Explicit] && 
      FreeQ[Union[Head /@ {FeynCalc`VertexFunctions`Private`mui}], Integer]
 
QuarkGluonVertex /: MakeBoxes[QuarkGluonVertex[
       FeynCalc`VertexFunctions`Private`mu1_], TraditionalForm] := 
     SuperscriptBox["Q", TBox[FeynCalc`VertexFunctions`Private`mu1]]
 
QuarkGluonVertex /: MakeBoxes[QuarkGluonVertex[
       {_, FeynCalc`VertexFunctions`Private`mu1_, 
        FeynCalc`VertexFunctions`Private`a_}, {__}, {__}, OptionsPattern[]], 
      TraditionalForm] := SubsuperscriptBox["Q", 
      TBox[FeynCalc`VertexFunctions`Private`a], 
      TBox[FeynCalc`VertexFunctions`Private`mu1]]
 
Options[QuarkGluonVertex] = {CouplingConstant -> SMP["g_s"], Dimension -> D, 
     Explicit -> False, Polarization -> 0}
 
QuarkGluonVertex /: QuarkGluonVertex::usage = "QuarkGluonVertex[mu, a] gives \
the Feynman rule for the quark-gluon vertex.\n\nQGV can be used as an \
abbreviation of QuarkGluonVertex.\n\nThe dimension and the name of the \
coupling constant are determined by the\noptions Dimension and \
CouplingConstant."
 
FieldStrength[FeynCalc`FieldStrength`Private`mu_, 
     FeynCalc`FieldStrength`Private`nu_, OptionsPattern[]] := 
    QuantumField[FCPartialD[LorentzIndex[FeynCalc`FieldStrength`Private`mu]], 
       OptionValue[QuantumField], LorentzIndex[
        FeynCalc`FieldStrength`Private`nu]] - QuantumField[
       FCPartialD[LorentzIndex[FeynCalc`FieldStrength`Private`nu]], 
       OptionValue[QuantumField], LorentzIndex[
        FeynCalc`FieldStrength`Private`mu]] /; OptionValue[Explicit]
 
FieldStrength[FeynCalc`FieldStrength`Private`mu_, 
     FeynCalc`FieldStrength`Private`nu_, FeynCalc`FieldStrength`Private`a_, 
     {FeynCalc`FieldStrength`Private`aA_, FeynCalc`FieldStrength`Private`b_, 
      FeynCalc`FieldStrength`Private`c_}, 
     FeynCalc`FieldStrength`Private`g_ /; 
      Head[FeynCalc`FieldStrength`Private`g] =!= Rule, OptionsPattern[]] := 
    QuantumField[FCPartialD[LorentzIndex[FeynCalc`FieldStrength`Private`mu]], 
       FeynCalc`FieldStrength`Private`aA, LorentzIndex[
        FeynCalc`FieldStrength`Private`nu], 
       SUNIndex[FeynCalc`FieldStrength`Private`a]] - 
      QuantumField[FCPartialD[LorentzIndex[
         FeynCalc`FieldStrength`Private`nu]], 
       FeynCalc`FieldStrength`Private`aA, LorentzIndex[
        FeynCalc`FieldStrength`Private`mu], 
       SUNIndex[FeynCalc`FieldStrength`Private`a]] + 
      FeynCalc`FieldStrength`Private`g*SUNF[FeynCalc`FieldStrength`Private`a, 
        FeynCalc`FieldStrength`Private`b, FeynCalc`FieldStrength`Private`c]*
       DOT[QuantumField[FeynCalc`FieldStrength`Private`aA, 
         LorentzIndex[FeynCalc`FieldStrength`Private`mu], 
         SUNIndex[FeynCalc`FieldStrength`Private`b]], 
        QuantumField[FeynCalc`FieldStrength`Private`aA, 
         LorentzIndex[FeynCalc`FieldStrength`Private`nu], 
         SUNIndex[FeynCalc`FieldStrength`Private`c]]] /; OptionValue[Explicit]
 
FieldStrength[FeynCalc`FieldStrength`Private`mu_, 
     FeynCalc`FieldStrength`Private`nu_, FeynCalc`FieldStrength`Private`a_, 
     FeynCalc`FieldStrength`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`FieldStrength`Private`g, 
       FeynCalc`FieldStrength`Private`b, FeynCalc`FieldStrength`Private`c}, 
      FeynCalc`FieldStrength`Private`b = Unique["b"]; 
       FeynCalc`FieldStrength`Private`c = Unique["c"]; 
       FieldStrength[FeynCalc`FieldStrength`Private`mu, 
        FeynCalc`FieldStrength`Private`nu, FeynCalc`FieldStrength`Private`a, 
        {OptionValue[QuantumField], FeynCalc`FieldStrength`Private`b, 
         FeynCalc`FieldStrength`Private`c}, OptionValue[CouplingConstant], 
        FeynCalc`FieldStrength`Private`opts]] /; OptionValue[Explicit]
 
Options[FieldStrength] = {CouplingConstant -> SMP["g_s"], Explicit -> False, 
     IndexPosition -> {0, 0}, Symbol -> "F", QuantumField -> GaugeField}
 
FieldStrength /: FieldStrength::usage = "FieldStrength[mu, nu, a] is the \
field strength tensor $\\partial _{\\mu } A_{\\nu\n}^a - \\partial _{\\nu } \
A_{\\mu }^a + g_s A_{\\mu }^b A_{\\nu }^c f^{abc}$.\n\nFieldStrength[mu, nu] \
is the field strength tensor $(\\partial _{\\mu } A_{\\nu}-\n\\partial_{\\nu \
} A_{\\mu})$.\n\nThe name of the field ($A$) and the coupling constant ($g$) \
can be set through\nthe options or by additional arguments. The first two \
indices are interpreted\nas type LorentzIndex."
 
IndexPosition /: IndexPosition::usage = 
     "IndexPosition is an option for FieldStrength."
 
GaugeField /: MakeBoxes[GaugeField, TraditionalForm] := "A"
 
GaugeField /: GaugeField::usage = "GaugeField is just a name. No functional \
properties are associated with it.\nGaugeField is used as default setting for \
the option QuantumField of\nFieldStrength."
 
Attributes[FCClausen] = {NumericFunction}
 
FCClausen[FeynCalc`FCClausen`Private`n_, FeynCalc`FCClausen`Private`x_, 
     OptionsPattern[]] := (1/2)*I*(PolyLog[FeynCalc`FCClausen`Private`n, 
        Exp[(-I)*FeynCalc`FCClausen`Private`x]] - 
       PolyLog[FeynCalc`FCClausen`Private`n, 
        Exp[I*FeynCalc`FCClausen`Private`x]]) /; OptionValue[Explicit]
 
N[FCClausen[FeynCalc`FCClausen`Private`n_, FeynCalc`FCClausen`Private`x_, 
      OptionsPattern[]], FeynCalc`FCClausen`Private`pr___] := 
    N[(1/2)*I*(PolyLog[FeynCalc`FCClausen`Private`n, 
        Exp[(-I)*FeynCalc`FCClausen`Private`x]] - 
       PolyLog[FeynCalc`FCClausen`Private`n, 
        Exp[I*FeynCalc`FCClausen`Private`x]]), FeynCalc`FCClausen`Private`pr]
 
FCClausen /: MakeBoxes[FCClausen[FeynCalc`FCClausen`Private`n_, 
       FeynCalc`FCClausen`Private`x_, OptionsPattern[]], TraditionalForm] := 
     RowBox[{SubscriptBox["Cl", TBox[FeynCalc`FCClausen`Private`n]], "(", 
       TBox[FeynCalc`FCClausen`Private`x], ")"}]
 
Options[FCClausen] = {Explicit -> False}
 
FCClausen /: FCClausen::usage = 
     "FCClausen[x,y] gives the Clausen function with arguments x and y."
 
FeynCalc`FeynCalcInternal`Private`tosunf[
     FeynCalc`FeynCalcInternal`Private`a_, 
     FeynCalc`FeynCalcInternal`Private`b_, 
     FeynCalc`FeynCalcInternal`Private`c_] := 
    SUNF @@ SUNIndex /@ ({FeynCalc`FeynCalcInternal`Private`a, 
        FeynCalc`FeynCalcInternal`Private`b, 
        FeynCalc`FeynCalcInternal`Private`c} /. SUNIndex -> Identity)
 
MetricTensor[FeynCalc`LegacyObjects`Private`a_, 
     FeynCalc`LegacyObjects`Private`b_, OptionsPattern[]] := 
    Pair[LorentzIndex[FeynCalc`LegacyObjects`Private`a, 
       OptionValue[Dimension]], LorentzIndex[
       FeynCalc`LegacyObjects`Private`b, OptionValue[Dimension]]] /; 
     OptionValue[FCI]
 
MetricTensor /: MakeBoxes[MetricTensor[FeynCalc`LegacyObjects`Private`a_, 
       FeynCalc`LegacyObjects`Private`b_, FeynCalc`LegacyObjects`Private`opts:
        OptionsPattern[]], TraditionalForm] := 
     ToBoxes[Pair[LorentzIndex[FeynCalc`LegacyObjects`Private`a, 
         OptionValue[{FeynCalc`LegacyObjects`Private`opts}, Dimension]], 
        LorentzIndex[FeynCalc`LegacyObjects`Private`b, 
         OptionValue[{FeynCalc`LegacyObjects`Private`opts}, Dimension]]], 
       TraditionalForm] /;  !OptionValue[
        {FeynCalc`LegacyObjects`Private`opts}, FCI]
 
Options[MetricTensor] = {Dimension -> 4, FeynCalcInternal -> True}
 
MetricTensor /: MetricTensor::usage = "MetricTensor[mu, nu] is the metric \
tensor. The default dimension is $4$.\n\nThe shortcut MetricTensor is \
deprecated, please use MT instead!"
 
FeynCalc`FeynCalcInternal`Private`metricT[
     FeynCalc`FeynCalcInternal`Private`x_, 
     FeynCalc`FeynCalcInternal`Private`x_, 
     FeynCalc`FeynCalcInternal`Private`op_:{}] := 
    Dimension /. FeynCalc`FeynCalcInternal`Private`op /. Options[MetricTensor]
 
FeynCalc`FeynCalcInternal`Private`metricT[
     FeynCalc`FeynCalcInternal`Private`x_, 
     FeynCalc`FeynCalcInternal`Private`y_, 
