      FeynCalc`DiracTrick`Private`holdDOT[FeynCalc`DiracTrick`Private`b, 
       FeynCalc`DiracTrick`Private`dg, DiracGamma[
        FeynCalc`DiracTrick`Private`h2], FeynCalc`DiracTrick`Private`c]] /; 
     FeynCalc`DiracTrick`Private`h1 =!= FeynCalc`DiracTrick`Private`h2
 
FeynCalc`DiracTrick`Private`diracTrickEvalFast[
     FeynCalc`DiracTrick`Private`holdDOT[FeynCalc`DiracTrick`Private`b___, 
      DiracGamma[FeynCalc`DiracTrick`Private`h1:6 | 7], 
      FeynCalc`DiracTrick`Private`dg:DiracGamma[_[__]], 
      FeynCalc`DiracTrick`Private`xy:DiracGamma[_[_]].., 
      DiracGamma[FeynCalc`DiracTrick`Private`h2:6 | 7], 
      FeynCalc`DiracTrick`Private`c___]] := 
    FeynCalc`DiracTrick`Private`diracTrickEvalFast[
      FeynCalc`DiracTrick`Private`holdDOT[FeynCalc`DiracTrick`Private`b, 
       FeynCalc`DiracTrick`Private`dg, FeynCalc`DiracTrick`Private`xy, 
       DiracGamma[FeynCalc`DiracTrick`Private`h2], 
       FeynCalc`DiracTrick`Private`c]] /; 
     EvenQ[Length[{FeynCalc`DiracTrick`Private`xy}]] && 
      FeynCalc`DiracTrick`Private`h1 =!= FeynCalc`DiracTrick`Private`h2
 
FeynCalc`DiracTrick`Private`diracTrickEvalFast[
     FeynCalc`DiracTrick`Private`holdDOT[___, 
      DiracGamma[FeynCalc`DiracTrick`Private`h:6 | 7], DiracGamma[_[__]], 
      FeynCalc`DiracTrick`Private`xy:DiracGamma[_[_]].., 
      DiracGamma[FeynCalc`DiracTrick`Private`h:6 | 7], ___]] := 
    0 /; EvenQ[Length[{FeynCalc`DiracTrick`Private`xy}]]
 
FeynCalc`DiracTrick`Private`diracTrickEvalFast[
     FeynCalc`DiracTrick`Private`holdDOT[___, 
      DiracGamma[FeynCalc`DiracTrick`Private`h1:6 | 7], DiracGamma[_[__]], 
      FeynCalc`DiracTrick`Private`xy:DiracGamma[_[__]].., 
      DiracGamma[FeynCalc`DiracTrick`Private`h2:6 | 7], ___]] := 
    0 /; OddQ[Length[{FeynCalc`DiracTrick`Private`xy}]] && 
      FeynCalc`DiracTrick`Private`h1 =!= FeynCalc`DiracTrick`Private`h2
 
FeynCalc`DiracTrick`Private`diracTrickEvalFast[
     FeynCalc`DiracTrick`Private`holdDOT[FeynCalc`DiracTrick`Private`b___, 
      DiracGamma[FeynCalc`DiracTrick`Private`h:6 | 7], 
      FeynCalc`DiracTrick`Private`dg:DiracGamma[_[__]], 
      FeynCalc`DiracTrick`Private`xy:DiracGamma[_[__]].., 
      DiracGamma[FeynCalc`DiracTrick`Private`h:6 | 7], 
      FeynCalc`DiracTrick`Private`c___]] := 
    FeynCalc`DiracTrick`Private`diracTrickEvalFast[
      FeynCalc`DiracTrick`Private`holdDOT[FeynCalc`DiracTrick`Private`b, 
       FeynCalc`DiracTrick`Private`dg, FeynCalc`DiracTrick`Private`xy, 
       DiracGamma[FeynCalc`DiracTrick`Private`h], 
       FeynCalc`DiracTrick`Private`c]] /; 
     OddQ[Length[{FeynCalc`DiracTrick`Private`xy}]]
 
FeynCalc`DiracTrick`Private`holdDOT /: 
    FeynCalc`DiracTrick`Private`holdDOT::usage = ""
 
FeynCalc`DiracTrick`Private`diracOrder /: 
    FeynCalc`DiracTrick`Private`diracOrder::usage = ""
 
FeynCalc`DiracTrick`Private`ga67MatSign[5, 6] = 1
 
FeynCalc`DiracTrick`Private`ga67MatSign[5, 7] = -1
 
FeynCalc`DiracTrick`Private`ga67MatSign[6, 5] = 1
 
FeynCalc`DiracTrick`Private`ga67MatSign[6, 7] = 0
 
FeynCalc`DiracTrick`Private`ga67MatSign[7, 5] = -1
 
FeynCalc`DiracTrick`Private`ga67MatSign[7, 6] = 0
 
FeynCalc`DiracTrick`Private`ga67Mat[5, 6] = DiracGamma[6]
 
FeynCalc`DiracTrick`Private`ga67Mat[5, 7] = DiracGamma[7]
 
FeynCalc`DiracTrick`Private`ga67Mat[6, 5] = DiracGamma[6]
 
FeynCalc`DiracTrick`Private`ga67Mat[6, 7] = 0
 
FeynCalc`DiracTrick`Private`ga67Mat[7, 5] = DiracGamma[7]
 
FeynCalc`DiracTrick`Private`ga67Mat[7, 6] = 0
 
FeynCalc`DiracTrick`Private`ga67Val1[6] = 1
 
FeynCalc`DiracTrick`Private`ga67Val1[7] = -1
 
FeynCalc`DiracTrick`Private`ga67Val2[6, 6] = 1
 
FeynCalc`DiracTrick`Private`ga67Val2[6, 7] = 0
 
FeynCalc`DiracTrick`Private`ga67Val2[7, 6] = 0
 
FeynCalc`DiracTrick`Private`ga67Val2[7, 7] = 1
 
FeynCalc`DiracTrick`Private`ga67Switch1[6] = 7
 
FeynCalc`DiracTrick`Private`ga67Switch1[7] = 6
 
FeynCalc`DiracTrace`Private`diracTraceEvaluate[
     FeynCalc`DiracTrace`Private`expr_ /; 
      FreeQ[FeynCalc`DiracTrace`Private`expr, DiracGamma], 
     OptionsPattern[]] := FeynCalc`DiracTrace`Private`unitMatrixTrace*
     FeynCalc`DiracTrace`Private`expr
 
FeynCalc`DiracTrace`Private`diracTraceEvaluate[
     FeynCalc`DiracTrace`Private`expr_ /; 
       !FreeQ[FeynCalc`DiracTrace`Private`expr, DiracGamma], 
     FeynCalc`DiracTrace`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`DiracTrace`Private`diractrres, 
      FeynCalc`DiracTrace`Private`tmp = FeynCalc`DiracTrace`Private`expr, 
      FeynCalc`DiracTrace`Private`diractrfact, 
      FeynCalc`DiracTrace`Private`diractrcoll, 
      FeynCalc`DiracTrace`Private`dtmp, FeynCalc`DiracTrace`Private`dWrap, 
      FeynCalc`DiracTrace`Private`wrapRule, 
      FeynCalc`DiracTrace`Private`prepSpur, FeynCalc`DiracTrace`Private`time, 
      FeynCalc`DiracTrace`Private`time2, 
      FeynCalc`DiracTrace`Private`contract, 
      FeynCalc`DiracTrace`Private`spurHeadList, 
      FeynCalc`DiracTrace`Private`spurHeadListChiral, 
      FeynCalc`DiracTrace`Private`spurHeadListNonChiral, 
      FeynCalc`DiracTrace`Private`gammaFree, 
      FeynCalc`DiracTrace`Private`gammaPart, 
      FeynCalc`DiracTrace`Private`traceListChiral, 
      FeynCalc`DiracTrace`Private`traceListNonChiral, 
      FeynCalc`DiracTrace`Private`repRule, FeynCalc`DiracTrace`Private`null1, 
      FeynCalc`DiracTrace`Private`null2, 
      FeynCalc`DiracTrace`Private`dummyIndexFreeQ, 
      FeynCalc`DiracTrace`Private`epsEvaluate, 
      FeynCalc`DiracTrace`Private`numGamma5 = 0}, 
     FeynCalc`DiracTrace`Private`wrapRule = 
       {FeynCalc`DiracTrace`Private`dWrap[5] -> 0, 
        FeynCalc`DiracTrace`Private`dWrap[6] -> 1/2, 
        FeynCalc`DiracTrace`Private`dWrap[7] -> 1/2, 
        FeynCalc`DiracTrace`Private`dWrap[LorentzIndex[_, _:4], ___] -> 0, 
        FeynCalc`DiracTrace`Private`dWrap[(_.)*Momentum[_, _:4] + (_:0), 
          ___] -> 0}; FeynCalc`DiracTrace`Private`diractrfact = 
       OptionValue[DiracTrace, {FeynCalc`DiracTrace`Private`opts}, 
        Factoring]; FeynCalc`DiracTrace`Private`diractrcoll = 
       OptionValue[DiracTrace, {FeynCalc`DiracTrace`Private`opts}, 
        PairCollect]; FeynCalc`DiracTrace`Private`contract = 
       OptionValue[DiracTrace, {FeynCalc`DiracTrace`Private`opts}, Contract]; 
      FeynCalc`DiracTrace`Private`epsEvaluate = OptionValue[DiracTrace, 
        {FeynCalc`DiracTrace`Private`opts}, EpsEvaluate]; 
      FeynCalc`DiracTrace`Private`west = OptionValue[DiracTrace, 
        {FeynCalc`DiracTrace`Private`opts}, West]; 
      FeynCalc`DiracTrace`Private`larinMVV = OptionValue[DiracTrace, 
        {FeynCalc`DiracTrace`Private`opts}, LarinMVV]; 
      If[FeynCalc`DiracTrace`Private`diractrfact === Automatic, 
       FeynCalc`DiracTrace`Private`diractrfact = 
         Function[FeynCalc`DiracTrace`Private`x, 
          If[LeafCount[FeynCalc`DiracTrace`Private`x] < 5000, 
           Factor[FeynCalc`DiracTrace`Private`x], 
           FeynCalc`DiracTrace`Private`x]]; ]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Entering", 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FCPrint[3, "DiracTrace: diracTraceEvaluate: Entering with: ", 
       FeynCalc`DiracTrace`Private`expr, FCDoControl -> 
        FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Checking if there are \
indices that need to be contracted. ", FCDoControl -> 
        FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`dummyIndexFreeQ = DummyIndexFreeQ[
        FeynCalc`DiracTrace`Private`tmp, {LorentzIndex, CartesianIndex}]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Check done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Applying DiracTrick.", 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`holdEpsQ = False; 
      If[TrueQ[FeynCalc`Package`DiracGammaScheme === "Larin" && 
          !FreeQ2[FeynCalc`DiracTrace`Private`tmp, {DiracGamma[5], 
            DiracGamma[6], DiracGamma[7]}]], 
       FeynCalc`DiracTrace`Private`numGamma5 = 
         Count[FeynCalc`DiracTrace`Private`tmp, DiracGamma[5] | 
           DiracGamma[6] | DiracGamma[7], Infinity]; 
        FCPrint[1, "DiracTrace: numGamma5: ", 
         FeynCalc`DiracTrace`Private`numGamma5, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[ !MatchQ[FeynCalc`DiracTrace`Private`numGamma5, 
           _Integer?NonNegative], Message[DiracTrace::failmsg, 
           "Failed to determine the number of g^5 in the trace."]; Abort[]]; 
        If[FeynCalc`DiracTrace`Private`numGamma5 > 2, 
         Message[DiracTrace::larinmultiple]; 
          FeynCalc`DiracTrace`Private`holdEpsQ = True], 
       FeynCalc`DiracTrace`Private`holdEpsQ = False]; 
      FeynCalc`DiracTrace`Private`tmp = DiracTrick[
        FeynCalc`DiracTrace`Private`tmp, FCI -> True, InsideDiracTrace -> 
         True, FCDiracIsolate -> FeynCalc`Package`containsNestedDOTsQ[
          FeynCalc`DiracTrace`Private`tmp]]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: DiracTrick done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FCPrint[3, "DiracTrace: diracTraceEvaluate: After DiracTrick: ", 
       FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
        FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
      If[ !FreeQ[FeynCalc`DiracTrace`Private`tmp, DiracGamma], 
       FCPrint[1, "DiracTrace: diracTraceEvaluate: Calculating the trace.", 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Applying Dotsimplify.", 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = DotSimplify[
          FeynCalc`DiracTrace`Private`tmp, Expanding -> True]; 
        FCPrint[1, 
         "DiracTrace: diracTraceEvaluate: Dotsimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: After Dotsimplify: ", 
         FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Applying DiracTrick.", 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = DiracTrick[
          FeynCalc`DiracTrace`Private`tmp, FCI -> True, InsideDiracTrace -> 
           True, FCJoinDOTs -> False]; FCPrint[1, 
         "DiracTrace: diracTraceEvaluate: DiracTrick done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: After DiracTrick: ", 
         FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = FeynCalc`DiracTrace`Private`tmp /. 
           {DiracGamma -> FeynCalc`DiracTrace`Private`dWrap} /. 
          DOT -> FeynCalc`DiracTrace`Private`prepSpur; 
        FeynCalc`DiracTrace`Private`tmp = FeynCalc`DiracTrace`Private`tmp /. 
          FeynCalc`DiracTrace`Private`prepSpur[
            FeynCalc`DiracTrace`Private`zzz__] :> 
           FeynCalc`DiracTrace`Private`spurHead @@ 
            ({FeynCalc`DiracTrace`Private`zzz} /. 
             {FeynCalc`DiracTrace`Private`dWrap -> DiracGamma}); 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: Wrapped in spurHead: ", 
         FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = FeynCalc`DiracTrace`Private`tmp /. 
          FeynCalc`DiracTrace`Private`spurHead[
             FeynCalc`DiracTrace`Private`x__] /; 
             !NonCommFreeQ[{FeynCalc`DiracTrace`Private`x} /. DiracGamma -> 
                FeynCalc`DiracTrace`Private`null1] :> 
           FeynCalc`DiracTrace`Private`noSpur[FeynCalc`DiracTrace`Private`x]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: Trace contains unknown \
non-commutative objects: ",  !FreeQ[FeynCalc`DiracTrace`Private`tmp, 
           FeynCalc`DiracTrace`Private`noSpur], FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = FeynCalc`DiracTrace`Private`tmp /. 
           {FeynCalc`DiracTrace`Private`spurHead[
              FeynCalc`DiracTrace`Private`x___, DiracGamma[6]] :> 
             (1/2)*FeynCalc`DiracTrace`Private`spurHead[
                FeynCalc`DiracTrace`Private`x] + (1/2)*
               FeynCalc`DiracTrace`Private`spurHead[
                FeynCalc`DiracTrace`Private`x, DiracGamma[5]], 
            FeynCalc`DiracTrace`Private`spurHead[
              FeynCalc`DiracTrace`Private`x___, DiracGamma[7]] :> 
             (1/2)*FeynCalc`DiracTrace`Private`spurHead[
                FeynCalc`DiracTrace`Private`x] - (1/2)*
               FeynCalc`DiracTrace`Private`spurHead[
                FeynCalc`DiracTrace`Private`x, DiracGamma[5]]} /. 
          FeynCalc`DiracTrace`Private`spurHead[] -> 1; 
        FCPrint[3, 
         "DiracTrace: diracTraceEvaluate: Chiral projectors splitted: ", 
         FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[ !FreeQ2[FeynCalc`DiracTrace`Private`tmp /. 
            FeynCalc`DiracTrace`Private`noSpur[___] :> 1, 
           {DiracGamma[6], DiracGamma[7]}], Message[DiracTrace::failmsg, 
           "Trace still contains chiral projectors."]; Abort[]]; 
        If[FeynCalc`DiracTrace`Private`optSort, 
         FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
          FCPrint[1, "DiracTrace: diracTraceEvaluate: Applying the cyclicity \
of the trace to sort the matrices lexicographically.", FCDoControl -> 
            FeynCalc`DiracTrace`Private`diTrVerbose]; 
          FeynCalc`DiracTrace`Private`tmp = 
           FeynCalc`DiracTrace`Private`tmp /. 
            FeynCalc`DiracTrace`Private`spurHead[
               FeynCalc`DiracTrace`Private`x__] /; FCGetDimensions[
                {FeynCalc`DiracTrace`Private`x}, ChangeDimension -> True] === 
               {4} -> FeynCalc`DiracTrace`Private`orderSpurHead[
              FeynCalc`DiracTrace`Private`x]; 
          If[ !FreeQ[FeynCalc`DiracTrace`Private`tmp, 
             FeynCalc`DiracTrace`Private`orderSpurHead], 
           Message[DiracTrace::failmsg, 
             "Sorting matrices inside Dirac traces failed."]; Abort[]]; 
          FCPrint[1, "DiracTrace: diracTraceEvaluate: Done sorting matrices \
lexicographically, timing:", N[AbsoluteTime[] - 
             FeynCalc`DiracTrace`Private`time2, 4], FCDoControl -> 
            FeynCalc`DiracTrace`Private`diTrVerbose]; FCPrint[3, "DiracTrace: \
diracTraceEvaluate: After sorting matrices lexicographically: ", 
           FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
            FeynCalc`DiracTrace`Private`diTrVerbose]]; 
        {FeynCalc`DiracTrace`Private`gammaFree, 
          FeynCalc`DiracTrace`Private`gammaPart} = 
         FCSplit[FeynCalc`DiracTrace`Private`tmp, 
          {FeynCalc`DiracTrace`Private`spurHead}]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: gammaFree: ", 
         FeynCalc`DiracTrace`Private`gammaFree, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: gammaPart: ", 
         FeynCalc`DiracTrace`Private`gammaPart, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[FeynCalc`DiracTrace`Private`gammaPart =!= 0, 
         Scan[If[ !MatchQ[#1, (FeynCalc`DiracTrace`Private`a_.)*
                 FeynCalc`DiracTrace`Private`spurHead[
                  FeynCalc`DiracTrace`Private`b__] /; 
                FreeQ[{FeynCalc`DiracTrace`Private`a, 
                   FeynCalc`DiracTrace`Private`b}, 
                  FeynCalc`DiracTrace`Private`spurHead] && 
                  !FreeQ[{FeynCalc`DiracTrace`Private`b}, DiracGamma]], 
             Message[DiracTrace::failmsg, "Irregular trace structure in ", 
               ToString[#1, InputForm]]; Abort[]] & , 
           FeynCalc`DiracTrace`Private`gammaPart + 
            FeynCalc`DiracTrace`Private`spurHead[DiracGamma]]; ]; 
        FeynCalc`DiracTrace`Private`spurHeadList = 
         Union[Cases[FeynCalc`DiracTrace`Private`gammaPart + 
            FeynCalc`DiracTrace`Private`null1 + 
            FeynCalc`DiracTrace`Private`null2, 
           FeynCalc`DiracTrace`Private`spurHead[__], Infinity]]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: spurHeadList: ", 
         FeynCalc`DiracTrace`Private`spurHeadList, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`spurHeadListChiral = 
         Select[FeynCalc`DiracTrace`Private`spurHeadList, 
           !FreeQ[#1, DiracGamma[5]] & ]; 
        FeynCalc`DiracTrace`Private`spurHeadListNonChiral = 
         Complement[FeynCalc`DiracTrace`Private`spurHeadList, 
          FeynCalc`DiracTrace`Private`spurHeadListChiral]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: spurHeadListChiral: ", 
         FeynCalc`DiracTrace`Private`spurHeadListChiral, 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: spurHeadListNonChiral: ", 
         FeynCalc`DiracTrace`Private`spurHeadListNonChiral, 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[FeynCalc`DiracTrace`Private`spurHeadList =!= 
          Union[Join[FeynCalc`DiracTrace`Private`spurHeadListChiral, 
            FeynCalc`DiracTrace`Private`spurHeadListNonChiral]], 
         Message[DiracTrace::failmsg, 
           "Splitting between chiral and non-chiral traces failed"]; 
          Abort[]]; If[FeynCalc`Package`DiracGammaScheme =!= "BMHV", 
         Scan[If[Length[FCGetDimensions[#1, FreeQ -> {DiracGamma[5]}, 
               ChangeDimension -> True]] =!= 1, Message[DiracTrace::mixmsg]; 
             Abort[]] & , FeynCalc`DiracTrace`Private`spurHeadListChiral]]; 
        Scan[If[ !MatchQ[#1, FeynCalc`DiracTrace`Private`spurHead[
              DiracGamma[_[_, ___], ___]..., DiracGamma[5]]], 
           Message[DiracTrace::failmsg, 
             "Chiral traces are not in the proper form."]; Abort[]] & , 
         FeynCalc`DiracTrace`Private`spurHeadListChiral]; 
        FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Calculating ", 
         Length[FeynCalc`DiracTrace`Private`spurHeadListChiral], 
         " nonchiral traces.", FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`traceListNonChiral = 
         FeynCalc`DiracTrace`Private`spurHeadListNonChiral /. 
          FeynCalc`DiracTrace`Private`spurHead -> 
           FeynCalc`DiracTrace`Private`spurNo5; FCPrint[1, "DiracTrace: \
diracTraceEvaluate: Done calculating non-chiral traces, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: traceListNonChiral", 
         FeynCalc`DiracTrace`Private`traceListNonChiral, 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[ !FreeQ2[FeynCalc`DiracTrace`Private`traceListNonChiral, 
           {FeynCalc`DiracTrace`Private`spurHead, DiracGamma}], 
         Message[DiracTrace::failmsg, 
           "Not all non-chiral traces were evaluated."]; Abort[]]; 
        FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Calculating ", 
         Length[FeynCalc`DiracTrace`Private`spurHeadListChiral], 
         " chiral traces.", FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`traceListChiral = 
         FeynCalc`DiracTrace`Private`spurHeadListChiral /. 
          FeynCalc`DiracTrace`Private`spurHead[
             FeynCalc`DiracTrace`Private`x__] /; 
            FCGetDimensions[{FeynCalc`DiracTrace`Private`x}, 
              ChangeDimension -> True] === {4} :> 
           FeynCalc`DiracTrace`Private`spur5In4Dim[
            FeynCalc`DiracTrace`Private`x]; 
        If[ !FreeQ[FeynCalc`DiracTrace`Private`traceListChiral, 
           FeynCalc`DiracTrace`Private`spurHead], 
         Switch[FeynCalc`Package`DiracGammaScheme, "NDR", 
          FCPrint[2, "DiracTrace: diracTraceEvaluate: Chiral traces will be \
left untouched (NDR scheme).", FCDoControl -> 
             FeynCalc`DiracTrace`Private`diTrVerbose]; 
           FeynCalc`DiracTrace`Private`traceListChiral = 
            FeynCalc`DiracTrace`Private`traceListChiral /. 
             FeynCalc`DiracTrace`Private`spurHead -> 
              FeynCalc`DiracTrace`Private`noSpur, "NDR-Discard", 
          FCPrint[2, "DiracTrace: diracTraceEvaluate: Chiral traces are set \
to zero (NDR-Discard scheme).", FCDoControl -> 
             FeynCalc`DiracTrace`Private`diTrVerbose]; 
           FeynCalc`DiracTrace`Private`traceListChiral = ConstantArray[0, 
             Length[FeynCalc`DiracTrace`Private`traceListChiral]], "Larin", 
          FCPrint[2, "DiracTrace: diracTraceEvaluate: Chiral traces will be \
computed using Larin scheme.", FCDoControl -> 
             FeynCalc`DiracTrace`Private`diTrVerbose]; 
           If[FeynCalc`DiracTrace`Private`larinMVV, 
            FCPrint[2, 
              "DiracTrace: diracTraceEvaluate: Using the MVV trace formula.", 
              FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
             FeynCalc`DiracTrace`Private`traceListChiral = 
              FeynCalc`DiracTrace`Private`traceListChiral /. 
               FeynCalc`DiracTrace`Private`spurHead -> 
                FeynCalc`DiracTrace`Private`spur5LarinMVV, 
            FCPrint[2, "DiracTrace: diracTraceEvaluate: Using the standard \
slow trace formula.", FCDoControl -> 
               FeynCalc`DiracTrace`Private`diTrVerbose]; 
             FeynCalc`DiracTrace`Private`traceListChiral = 
              FeynCalc`DiracTrace`Private`traceListChiral /. 
               FeynCalc`DiracTrace`Private`spurHead -> 
                FeynCalc`DiracTrace`Private`spur5Larin], "BMHV", 
          FCPrint[3, "DiracTrace: diracTraceEvaluate: Chiral traces will be \
computed using BMHV scheme", FCDoControl -> 
             FeynCalc`DiracTrace`Private`diTrVerbose]; 
           If[FeynCalc`DiracTrace`Private`west, 
            FeynCalc`DiracTrace`Private`traceListChiral = 
             FeynCalc`DiracTrace`Private`traceListChiral /. 
              FeynCalc`DiracTrace`Private`spurHead -> 
               FeynCalc`DiracTrace`Private`spur5BMHVWest, 
            FeynCalc`DiracTrace`Private`traceListChiral = 
             FeynCalc`DiracTrace`Private`traceListChiral /. 
              FeynCalc`DiracTrace`Private`spurHead -> 
               FeynCalc`DiracTrace`Private`spur5BMHVNoWest], _, 
          Message[DiracTrace::failmsg, "Unknown scheme for handling Dirac \
matrices in dimensional regularization."]; Abort[]]]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Done calculating chiral \
traces, timing: ", N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: traceListChiral", 
         FeynCalc`DiracTrace`Private`traceListChiral, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[ !FreeQ2[FeynCalc`DiracTrace`Private`traceListChiral /. 
            _FeynCalc`DiracTrace`Private`noSpur :> 1, 
           {FeynCalc`DiracTrace`Private`spurHead, DiracGamma, 
            FeynCalc`DiracTrace`Private`trace5}], 
         Print[FeynCalc`DiracTrace`Private`traceListChiral]; 
          Message[DiracTrace::failmsg, 
           "Not all chiral traces were evaluated."]; Abort[]]; 
        FeynCalc`DiracTrace`Private`traceListChiral = 
         FeynCalc`DiracTrace`Private`traceListChiral /. 
          FeynCalc`DiracTrace`Private`leviCivitaSign -> $LeviCivitaSign; 
        If[OptionValue[DiracTrace, {FeynCalc`DiracTrace`Private`opts}, 
           Expand] &&  !FreeQ[
            {FeynCalc`DiracTrace`Private`traceListNonChiral, 
             FeynCalc`DiracTrace`Private`traceListChiral, 
             FeynCalc`DiracTrace`Private`gammaFree, 
             FeynCalc`DiracTrace`Private`gammaPart}, Momentum], 
         FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
          FCPrint[1, 
           "DiracTrace: diracTraceEvaluate: Expanding scalar products", 
           FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
          FeynCalc`DiracTrace`Private`traceListNonChiral = 
           (ExpandScalarProduct[#1, FCI -> True] & ) /@ 
            FeynCalc`DiracTrace`Private`traceListNonChiral; 
          FeynCalc`DiracTrace`Private`traceListChiral = 
           (ExpandScalarProduct[#1, FCI -> True] & ) /@ 
            FeynCalc`DiracTrace`Private`traceListChiral; 
          FeynCalc`DiracTrace`Private`gammaFree = ExpandScalarProduct[
            FeynCalc`DiracTrace`Private`gammaFree, FCI -> True]; 
          FeynCalc`DiracTrace`Private`gammaPart = ExpandScalarProduct[
            FeynCalc`DiracTrace`Private`gammaPart, FCI -> True]; 
          FCPrint[1, "DiracTrace: diracTraceEvaluate: Done expanding the \
result, timing: ", N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time2, 4], 
           FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]]; 
        FeynCalc`DiracTrace`Private`time2 = AbsoluteTime[]; 
        FCPrint[1, 
         "DiracTrace: diracTraceEvaluate: Rebuilding the full result.", 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`repRule = 
         Thread[FeynCalc`DiracTrace`Private`spurHeadListChiral -> 
           FeynCalc`DiracTrace`Private`traceListChiral]; 
        FeynCalc`DiracTrace`Private`repRule = 
         Join[FeynCalc`DiracTrace`Private`repRule, 
          Thread[FeynCalc`DiracTrace`Private`spurHeadListNonChiral -> 
            FeynCalc`DiracTrace`Private`traceListNonChiral]]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: repRule: ", 
         FeynCalc`DiracTrace`Private`traceListChiral, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = 
         (FeynCalc`DiracTrace`Private`gammaFree /. 
           FeynCalc`DiracTrace`Private`wrapRule) + 
          (FeynCalc`DiracTrace`Private`gammaPart /. 
           Dispatch[FeynCalc`DiracTrace`Private`repRule]); 
        FCPrint[1, 
         "DiracTrace: diracTraceEvaluate: Full result ready, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time2, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: tmp: ", 
         FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        If[ !FreeQ2[FeynCalc`DiracTrace`Private`tmp /. 
            _FeynCalc`DiracTrace`Private`noSpur :> 1, 
           {FeynCalc`DiracTrace`Private`spurHead, DiracGamma}], 
         Message[DiracTrace::failmsg, 
           "Something went wrong while substituting trace results."]; 
          Abort[]]; ]; FCPrint[1, 
       "DiracTrace: diracTraceEvaluate: Main part finished, timing: ", 
       N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      If[ !FreeQ[FeynCalc`DiracTrace`Private`tmp /. 
          _FeynCalc`DiracTrace`Private`noSpur :> 1, DiracGamma], 
       Message[DiracTrace::failmsg, 
         "The output still contains Dirac matrices"]; Abort[]]; 
      If[FeynCalc`DiracTrace`Private`contract === True && 
         !FeynCalc`DiracTrace`Private`dummyIndexFreeQ, 
       FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "DiracTrace: diracTraceEvaluate: Contracting Lorentz indices. ", 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = Contract[
          FeynCalc`DiracTrace`Private`tmp, FCI -> True]; 
        FCPrint[3, "DiracTrace: diracTraceEvaluate: After Contract: ", 
         FeynCalc`DiracTrace`Private`tmp, FCDoControl -> 
          FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Contract done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]]; 
      If[ !FreeQ[FeynCalc`DiracTrace`Private`tmp, Eps] && 
        FeynCalc`DiracTrace`Private`epsEvaluate, 
       FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Treating Eps tensors.", 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`tmp = Expand[EpsEvaluate[
           FeynCalc`DiracTrace`Private`tmp, FCI -> True, 
           EpsExpand -> OptionValue[DiracTrace, 
             {FeynCalc`DiracTrace`Private`opts}, EpsExpand]]]; 
        If[FeynCalc`DiracTrace`Private`contract === True || 
          (NumberQ[FeynCalc`DiracTrace`Private`contract] && 
           LeafCount[FeynCalc`DiracTrace`Private`tmp] < 
            FeynCalc`DiracTrace`Private`contract), 
         FeynCalc`DiracTrace`Private`tmp = Contract[
            FeynCalc`DiracTrace`Private`tmp, EpsContract -> 
             OptionValue[DiracTrace, {FeynCalc`DiracTrace`Private`opts}, 
              EpsContract], Expanding -> False, FCI -> True, 
            EpsExpand -> OptionValue[DiracTrace, 
              {FeynCalc`DiracTrace`Private`opts}, EpsExpand]]; ]; ]; 
      FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Factoring the result.", 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      If[FeynCalc`DiracTrace`Private`diractrfact === True, 
       FeynCalc`DiracTrace`Private`diractrres = 
        Factor2[FeynCalc`DiracTrace`Private`unitMatrixTrace*
          FeynCalc`DiracTrace`Private`tmp], 
       If[FeynCalc`DiracTrace`Private`diractrfact === False, 
        FeynCalc`DiracTrace`Private`diractrres = 
         FeynCalc`DiracTrace`Private`unitMatrixTrace*
          FeynCalc`DiracTrace`Private`tmp, 
        FeynCalc`DiracTrace`Private`diractrres = 
         FeynCalc`DiracTrace`Private`diractrfact[
          FeynCalc`DiracTrace`Private`unitMatrixTrace*
           FeynCalc`DiracTrace`Private`tmp]]]; 
      FCPrint[3, "DiracTrace: diracTraceEvaluate: After factoring: ", 
       FeynCalc`DiracTrace`Private`diractrres, FCDoControl -> 
        FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Factoring done, timing: ", 
       N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`diractrpc[
        FeynCalc`DiracTrace`Private`x__] := 
       Plus[FeynCalc`DiracTrace`Private`x] /; 
        FreeQ[{FeynCalc`DiracTrace`Private`x}, Pair]; 
      If[FeynCalc`DiracTrace`Private`diractrcoll === True, 
       FeynCalc`DiracTrace`Private`time = AbsoluteTime[]; 
        FCPrint[1, 
         "DiracTrace: diracTraceEvaluate: Collecting the result w.r.t Pairs."\
, FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
        FeynCalc`DiracTrace`Private`diractrpc[
          FeynCalc`DiracTrace`Private`x__] := Collect2[
          Plus[FeynCalc`DiracTrace`Private`x], Pair, Factoring -> False]; 
        FeynCalc`DiracTrace`Private`diractrres = 
         FeynCalc`DiracTrace`Private`diractrres /. 
          Plus -> FeynCalc`DiracTrace`Private`diractrpc; 
        FCPrint[1, "DiracTrace: diracTraceEvaluate: Collecting done, timing", 
         N[AbsoluteTime[] - FeynCalc`DiracTrace`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; ]; 
      FCPrint[1, "DiracTrace: diracTraceEvaluate: Leaving.", 
       FCDoControl -> FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FCPrint[3, "DiracTrace: diracTraceEvaluate: Leaving with: ", 
       FeynCalc`DiracTrace`Private`diractrres, FCDoControl -> 
        FeynCalc`DiracTrace`Private`diTrVerbose]; 
      FeynCalc`DiracTrace`Private`diractrres]
 
FeynCalc`DiracTrace`Private`west /: FeynCalc`DiracTrace`Private`west::usage = 
     ""
 
West /: West::usage = "West is an option for DiracTrace and several other \
functions that deal with\ntraces of Dirac matrices. The option applies only \
to the computation of\n$D$-dimensional traces with an odd number of $\\gamma \
^5$ in the\nBreitenlohner-Maison-t'Hooft-Veltman (BMHV) scheme. With West -> \
True (default\nsetting), such traces are computed according to formula  (A.5) \
from Comp.\nPhys. Comm 77 (1993) 286-298, which is also known as West's \
formula. For more\ndetails, see the documentation of DiracTrace."
 
FeynCalc`DiracTrace`Private`larinMVV /: 
    FeynCalc`DiracTrace`Private`larinMVV::usage = ""
 
LarinMVV /: LarinMVV::usage = "LarinMVV is an option for DiracTrace and \
several other functions that deal\nwith traces of Dirac matrices. The option \
applies only to the computation of\n$D$-dimensional traces with a single \
$\\gamma ^5$ in the Larin scheme. With\nLarinMVV -> True (default setting), \
such traces are computed according to Eq.\n(10) \
from\n[arXiv:1506.04517](https://arxiv.org/pdf/1506.04517.pdf) by S. Moch, J. \
A. M.\nVermaseren and A. Vogt."
 
FeynCalc`DiracTrace`Private`holdEpsQ /: 
    FeynCalc`DiracTrace`Private`holdEpsQ::usage = ""
 
DiracTrick[FeynCalc`DiracTrick`Private`expr_, OptionsPattern[]] := 
    Block[{FeynCalc`DiracTrick`Private`res, FeynCalc`DiracTrick`Private`tmp, 
      FeynCalc`DiracTrick`Private`ex, FeynCalc`DiracTrick`Private`null1, 
      FeynCalc`DiracTrick`Private`null2, FeynCalc`DiracTrick`Private`holdDOT, 
      FeynCalc`DiracTrick`Private`freePart, 
      FeynCalc`DiracTrick`Private`dsPart, 
      FeynCalc`DiracTrick`Private`diracObjects, 
      FeynCalc`DiracTrick`Private`diracObjectsEval, 
      FeynCalc`DiracTrick`Private`repRule, FeynCalc`DiracTrick`Private`time, 
      FeynCalc`DiracTrick`Private`dsHead, 
      FeynCalc`DiracTrick`Private`optFCDiracIsolate}, 
     If[OptionValue[FCVerbose] === False, 
       FeynCalc`DiracTrick`Private`diTrVerbose = $VeryVerbose, 
       If[MatchQ[OptionValue[FCVerbose], _Integer], 
         FeynCalc`DiracTrick`Private`diTrVerbose = OptionValue[
           FCVerbose]]; ]; FeynCalc`DiracTrick`Private`optJoin = 
       OptionValue[FCJoinDOTs]; 
      FeynCalc`DiracTrick`Private`optFCDiracIsolate = 
       OptionValue[FCDiracIsolate]; 
      FeynCalc`DiracTrick`Private`insideDiracTrace = 
       OptionValue[InsideDiracTrace]; FCPrint[1, "DiracTrick. Entering.", 
       FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
      FCPrint[3, "DiracTrick: Entering with ", 
       FeynCalc`DiracTrick`Private`expr, FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; If[OptionValue[FCI], 
       FeynCalc`DiracTrick`Private`ex = FeynCalc`DiracTrick`Private`expr, 
       FeynCalc`DiracTrick`Private`ex = 
        FCI[FeynCalc`DiracTrick`Private`expr]]; 
      If[FreeQ2[FeynCalc`DiracTrick`Private`ex, 
        FeynCalc`Package`DiracHeadsList], 
       Return[FeynCalc`DiracTrick`Private`ex]]; 
      If[FeynCalc`DiracTrick`Private`optFCDiracIsolate === True || 
        Head[FeynCalc`DiracTrick`Private`optFCDiracIsolate] === List, 
       FCPrint[1, "DiracTrick: Normal mode.", FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FCPrint[1, "DiracTrick: Extracting Dirac objects.", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        If[TrueQ[Head[FeynCalc`DiracTrick`Private`optFCDiracIsolate] === 
           List], FeynCalc`DiracTrick`Private`ex = FCDiracIsolate[
           FeynCalc`DiracTrick`Private`ex, FCI -> True, 
           Head -> FeynCalc`DiracTrick`Private`dsHead, 
           FeynCalc`DiracTrick`Private`optFCDiracIsolate, 
           "ExpandNestedDOTs" -> True], FeynCalc`DiracTrick`Private`ex = 
           FCDiracIsolate[FeynCalc`DiracTrick`Private`ex, FCI -> True, 
            Head -> FeynCalc`DiracTrick`Private`dsHead, DotSimplify -> True, 
            DiracGammaCombine -> OptionValue[DiracGammaCombine], 
            FCJoinDOTs -> FeynCalc`DiracTrick`Private`optJoin, 
            LorentzIndex -> True, ToDiracGamma67 -> OptionValue[
              ToDiracGamma67], DiracChain -> OptionValue[DiracChain], 
            "ExpandNestedDOTs" -> True]; ]; 
        {FeynCalc`DiracTrick`Private`freePart, 
          FeynCalc`DiracTrick`Private`dsPart} = 
         FCSplit[FeynCalc`DiracTrick`Private`ex, 
          {FeynCalc`DiracTrick`Private`dsHead}]; FCPrint[3, 
         "DiracTrick: dsPart: ", FeynCalc`DiracTrick`Private`dsPart, 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrick: freePart: ", 
         FeynCalc`DiracTrick`Private`freePart, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[1, "DiracTrick: Done extracting Dirac objects, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`diracObjects = 
         Union[Cases[FeynCalc`DiracTrick`Private`dsPart + 
            FeynCalc`DiracTrick`Private`null1 + 
            FeynCalc`DiracTrick`Private`null2, 
           FeynCalc`DiracTrick`Private`dsHead[_], Infinity]]; 
        FCPrint[3, "DiracTrick: diracObjects: ", 
         FeynCalc`DiracTrick`Private`diracObjects, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FCPrint[1, "DiracTrick: Applying diracTrickEvalFast", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`diracObjectsEval = 
         FeynCalc`DiracTrick`Private`diracTrickEvalFast /@ 
          (FeynCalc`DiracTrick`Private`diracObjects /. 
            DOT -> FeynCalc`DiracTrick`Private`holdDOT /. 
           FeynCalc`DiracTrick`Private`dsHead -> Identity); 
        FCPrint[1, "DiracTrick: diracTrickEvalFast done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrick: After diracTrickEvalFast: ", 
         FeynCalc`DiracTrick`Private`diracObjectsEval, 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FCPrint[1, "DiracTrick: Doing contractions", FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        If[ !FreeQ[FeynCalc`DiracTrick`Private`diracObjectsEval, Pair], 
         FeynCalc`DiracTrick`Private`diracObjectsEval = 
          FeynCalc`DiracTrick`Private`diracObjectsEval /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             FeynCalc`DiracTrick`Private`zzz_] :> 
            FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             Expand2[FeynCalc`DiracTrick`Private`zzz, Pair] /. Pair -> 
                PairContract /. PairContract -> Pair]]; 
        If[ !FreeQ[FeynCalc`DiracTrick`Private`diracObjectsEval, 
           CartesianPair], FeynCalc`DiracTrick`Private`diracObjectsEval = 
          FeynCalc`DiracTrick`Private`diracObjectsEval /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             FeynCalc`DiracTrick`Private`zzz_] :> 
            FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             Expand2[FeynCalc`DiracTrick`Private`zzz, CartesianPair] /. 
               CartesianPair -> CartesianPairContract /. 
              CartesianPairContract -> CartesianPair]]; 
        FCPrint[1, "DiracTrick: Contractions done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrick: After contractions: ", 
         FeynCalc`DiracTrick`Private`diracObjectsEval, 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FCPrint[1, "DiracTrick: Applying diracTrickEval", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        If[OptionValue[Evaluate], 
         FeynCalc`DiracTrick`Private`diracObjectsEval = 
          FeynCalc`DiracTrick`Private`diracObjectsEval /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast -> 
            FeynCalc`DiracTrick`Private`diracTrickEval, 
         FeynCalc`DiracTrick`Private`diracObjectsEval = 
          FeynCalc`DiracTrick`Private`diracObjectsEval /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast -> Identity]; 
        FeynCalc`DiracTrick`Private`diracObjectsEval = 
         FeynCalc`DiracTrick`Private`diracObjectsEval /. 
          FeynCalc`DiracTrick`Private`holdDOT -> DOT; 
        FCPrint[3, "DiracTrick: After diracTrickEval: ", 
         FeynCalc`DiracTrick`Private`diracObjectsEval, 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[1, "DiracTrick: diracTrickEval done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        If[ !FreeQ2[FeynCalc`DiracTrick`Private`diracObjectsEval, 
           {FeynCalc`DiracTrick`Private`diracTrickEvalFast, 
            FeynCalc`DiracTrick`Private`diracTrickEval, 
            FeynCalc`DiracTrick`Private`holdDOT}], 
         Message[DiracTrick::failmsg, 
           "Evaluation of isolated objects failed."]; Abort[]]; 
        FCPrint[1, "DiracTrick: Inserting Dirac objects back.", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FeynCalc`DiracTrick`Private`repRule = 
         Thread[FeynCalc`DiracTrick`Private`diracObjects -> 
           FeynCalc`DiracTrick`Private`diracObjectsEval]; 
        FCPrint[3, "DiracTrick: repRule: ", 
         FeynCalc`DiracTrick`Private`repRule, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`res = 
         FeynCalc`DiracTrick`Private`freePart + 
          (FeynCalc`DiracTrick`Private`dsPart /. Dispatch[
            FeynCalc`DiracTrick`Private`repRule]); 
        FCPrint[1, "DiracTrick: Done inserting Dirac objects back, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose], 
       FCPrint[1, "DiracTrick: Fast mode.", FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`res = 
         FeynCalc`DiracTrick`Private`diracTrickEvalFast[
          FeynCalc`DiracTrick`Private`ex]; 
        If[ !FreeQ[FeynCalc`DiracTrick`Private`diracObjectsEval, Pair], 
         FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`res /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             FeynCalc`DiracTrick`Private`zzz_] :> 
            FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             Expand2[FeynCalc`DiracTrick`Private`zzz, Pair] /. Pair -> 
                PairContract /. PairContract -> Pair]]; 
        If[ !FreeQ[FeynCalc`DiracTrick`Private`diracObjectsEval, 
           CartesianPair], FeynCalc`DiracTrick`Private`res = 
          FeynCalc`DiracTrick`Private`res /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             FeynCalc`DiracTrick`Private`zzz_] :> 
            FeynCalc`DiracTrick`Private`diracTrickEvalFast[
             Expand2[FeynCalc`DiracTrick`Private`zzz, CartesianPair] /. 
               CartesianPair -> CartesianPairContract /. 
              CartesianPairContract -> CartesianPair]]; 
        FCPrint[3, "DiracTrick: After diracTrickEvalFast: ", 
         FeynCalc`DiracTrick`Private`res, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        If[OptionValue[ToDiracGamma67], FeynCalc`DiracTrick`Private`res = 
          FeynCalc`DiracTrick`Private`res /. 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast[
              FeynCalc`DiracTrick`Private`zzz_] /; 
              !FreeQ[{FeynCalc`DiracTrick`Private`zzz}, DiracGamma[5]] :> 
            FeynCalc`DiracTrick`Private`diracTrickEvalFast[ToDiracGamma67[
              FeynCalc`DiracTrick`Private`zzz, FCI -> True]]]; 
        If[ !FreeQ[FeynCalc`DiracTrick`Private`res, 
           FeynCalc`DiracTrick`Private`diracTrickEvalFast], 
         FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`res /. 
            FeynCalc`DiracTrick`Private`diracTrickEvalFast -> 
             FeynCalc`DiracTrick`Private`diracTrickEval; 
          FCPrint[3, "DiracTrick: After diracTrickEval: ", 
           FeynCalc`DiracTrick`Private`res, FCDoControl -> 
            FeynCalc`DiracTrick`Private`diTrVerbose]]; 
        If[ !FreeQ2[FeynCalc`DiracTrick`Private`res, 
           {FeynCalc`DiracTrick`Private`diracTrickEvalFast, 
            FeynCalc`DiracTrick`Private`diracTrickEval, 
            FeynCalc`DiracTrick`Private`holdDOT}], 
         Message[DiracTrick::failmsg, 
           "Evaluation of isolated objects failed."]; Abort[]]]; 
      If[OptionValue[Expanding], FeynCalc`DiracTrick`Private`time = 
         AbsoluteTime[]; FCPrint[1, "DiracTrick: Expanding the result.", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`res = 
         Expand[FeynCalc`DiracTrick`Private`res]; 
        FCPrint[1, "DiracTrick: Expanding done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrick: After expanding: ", 
         FeynCalc`DiracTrick`Private`res, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]]; 
      If[OptionValue[FCE], FeynCalc`DiracTrick`Private`res = 
        FCE[FeynCalc`DiracTrick`Private`res]]; 
      FCPrint[1, "DiracTrick. Leaving.", FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; 
      FCPrint[3, "DiracTrick: Leaving with ", 
       FeynCalc`DiracTrick`Private`res, FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; 
      FeynCalc`DiracTrick`Private`res]
 
Options[DiracTrick] = {Evaluate -> True, DiracChain -> True, 
     DiracGammaCombine -> False, Expanding -> False, FCDiracIsolate -> True, 
     FeynCalcExternal -> False, FeynCalcInternal -> False, 
     FCJoinDOTs -> False, FCVerbose -> False, InsideDiracTrace -> False, 
     ToDiracGamma67 -> True}
 
DiracTrick /: DiracTrick::failmsg = "Error! DiracTrick has encountered a \
fatal problem and must abort the computation. The problem reads: `1`"
 
DiracTrick /: DiracTrick::usage = "DiracTrick[exp] contracts Dirac matrices \
with each other and performs several\nsimplifications but no expansions.There \
are not many cases when a user will\nneed to call this function directly. Use \
DiracSimplify to achieve maximal\nsimplification of Dirac matrix chains. \
Regarding the treatment of $\\gamma^5$\nin $D$-dimensional expressions or the \
evaluation of expressions with tensors\nliving in different dimensions, see \
the explanations on the help pages for\nDiracSimplify and DiracTrace."
 
FeynCalc`DiracTrick`Private`diTrVerbose /: 
    FeynCalc`DiracTrick`Private`diTrVerbose::usage = ""
 
FeynCalc`DiracTrick`Private`optJoin /: 
    FeynCalc`DiracTrick`Private`optJoin::usage = ""
 
InsideDiracTrace /: InsideDiracTrace::usage = "InsideDiracTrace is an option \
of DiracSimplify and some other functions\ndealing with Dirac algebra. If set \
to True, the function assumes to operate\ninside a Dirac trace, i.e., \
products of an odd number of Dirac matrices are\ndiscarded. For more details, \
see the documentation for DiracSimplify."
 
FeynCalc`DiracTrick`Private`diracTrickEval[0] := 0
 
FeynCalc`DiracTrick`Private`diracTrickEval[
     FeynCalc`DiracTrick`Private`ex_DiracGamma] := 
    FeynCalc`DiracTrick`Private`ex /; 
      !FeynCalc`DiracTrick`Private`insideDiracTrace
 
FeynCalc`DiracTrick`Private`diracTrickEval[
     FeynCalc`DiracTrick`Private`ex_DiracGamma] := 
    0 /; FeynCalc`DiracTrick`Private`insideDiracTrace && 
       !MatchQ[FeynCalc`DiracTrick`Private`ex, DiracGamma[6 | 7]]
 
FeynCalc`DiracTrick`Private`diracTrickEval[
     FeynCalc`DiracTrick`Private`ex_DiracGamma] := 
    1/2 /; FeynCalc`DiracTrick`Private`insideDiracTrace && 
      MatchQ[FeynCalc`DiracTrick`Private`ex, DiracGamma[6 | 7]]
 
FeynCalc`DiracTrick`Private`diracTrickEval[FeynCalc`DiracTrick`Private`ex_ /; 
      Head[FeynCalc`DiracTrick`Private`ex] =!= DiracGamma] := 
    Which[MemberQ[{"NDR", "NDR-Discard"}, 
        FeynCalc`Package`DiracGammaScheme] && 
       FeynCalc`DiracTrick`Private`insideDiracTrace, 
      FCPrint[2, "DiracTrick: Calling: diracTrickEvalCachedNDRInsideTrace", 
        FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
       FeynCalc`DiracTrick`Private`diracTrickEvalCachedNDRInsideTrace[
        FeynCalc`DiracTrick`Private`ex], 
      FeynCalc`Package`DiracGammaScheme === "Larin" && 
       FeynCalc`DiracTrick`Private`insideDiracTrace, 
      FCPrint[2, "DiracTrick: Calling: diracTrickEvalCachedLarinInsideTrace", 
        FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
       FeynCalc`DiracTrick`Private`diracTrickEvalCachedLarinInsideTrace[
        FeynCalc`DiracTrick`Private`ex], 
      FeynCalc`Package`DiracGammaScheme === "BMHV" && 
       FeynCalc`DiracTrick`Private`insideDiracTrace, 
      FCPrint[2, "DiracTrick: Calling: diracTrickEvalCachedBMHVInsideTrace", 
        FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
       FeynCalc`DiracTrick`Private`diracTrickEvalCachedBMHVInsideTrace[
        FeynCalc`DiracTrick`Private`ex], MemberQ[{"NDR", "NDR-Discard"}, 
       FeynCalc`Package`DiracGammaScheme], 
      FCPrint[2, "DiracTrick: Calling: diracTrickEvalCachedNDR", 
        FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
       FeynCalc`DiracTrick`Private`diracTrickEvalCachedNDR[
        FeynCalc`DiracTrick`Private`ex], 
      FeynCalc`Package`DiracGammaScheme === "Larin", 
      FCPrint[2, "DiracTrick: Calling: diracTrickEvalCachedLarin", 
        FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
       FeynCalc`DiracTrick`Private`diracTrickEvalCachedLarin[
        FeynCalc`DiracTrick`Private`ex], 
      FeynCalc`Package`DiracGammaScheme === "BMHV", 
      FCPrint[2, "DiracTrick: Calling: diracTrickEvalCachedBMHV", 
        FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
       FeynCalc`DiracTrick`Private`diracTrickEvalCachedBMHV[
        FeynCalc`DiracTrick`Private`ex], True, Message[DiracTrace::mixmsg]; 
       Abort[]] /; FeynCalc`DiracTrick`Private`ex =!= 0
 
FeynCalc`DiracTrick`Private`diracTrickEvalCachedNDRInsideTrace[
     FeynCalc`DiracTrick`Private`x_] := 
    FeynCalc`DiracTrick`Private`diracTrickEvalInternal[
     FeynCalc`DiracTrick`Private`x]
 
FeynCalc`DiracTrick`Private`diracTrickEvalInternal[
     FeynCalc`DiracTrick`Private`ex_ /; 
      Head[FeynCalc`DiracTrick`Private`ex] =!= DiracGamma] := 
    Block[{FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`ex, 
      FeynCalc`DiracTrick`Private`holdDOT, FeynCalc`DiracTrick`Private`time, 
      FeynCalc`DiracTrick`Private`dim, 
      FeynCalc`DiracTrick`Private`gamma5Present, 
      FeynCalc`DiracTrick`Private`noncommPresent, 
      FeynCalc`DiracTrick`Private`null1, FeynCalc`DiracTrick`Private`null2, 
      FeynCalc`DiracTrick`Private`dsHead}, 
     FCPrint[2, "DiracTrick: diracTrickEval: Entering.", 
       FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
      FCPrint[3, "DiracTrick: diracTrickEval: Entering with: ", 
       FeynCalc`DiracTrick`Private`ex, FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; 
      FeynCalc`DiracTrick`Private`gamma5Present = 
        !FreeQ2[FeynCalc`DiracTrick`Private`ex, {DiracGamma[5], 
          DiracGamma[6], DiracGamma[7]}]; 
      FeynCalc`DiracTrick`Private`noncommPresent = 
        !NonCommFreeQ[FeynCalc`DiracTrick`Private`ex /. 
          DiracGamma -> FeynCalc`DiracTrick`Private`diga]; 
      FCPrint[3, "DiracTrick: diracTrickEval: g^5 present: ", 
       FeynCalc`DiracTrick`Private`gamma5Present, FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; FCPrint[3, "DiracTrick: \
diracTrickEval: unknown non-commutative objects present: ", 
       FeynCalc`DiracTrick`Private`noncommPresent, FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; 
      FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`res /. 
        DOT -> FeynCalc`DiracTrick`Private`holdDOT; 
      If[FeynCalc`Package`containsNestedDOTsQ[
        FeynCalc`DiracTrick`Private`res, 
        FeynCalc`DiracTrick`Private`holdDOT], 
       Message[DiracTrick::failmsg, "Unexpanded nested DOTs detected!"]; 
        Abort[]]; If[FeynCalc`DiracTrick`Private`gamma5Present, 
       FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`res /. 
           FeynCalc`DiracTrick`Private`holdDOT -> 
            FeynCalc`DiracTrick`Private`commonGamma5Properties /. 
          FeynCalc`DiracTrick`Private`commonGamma5Properties -> 
           FeynCalc`DiracTrick`Private`holdDOT; 
        FeynCalc`DiracTrick`Private`gamma5Present = 
          !FreeQ2[FeynCalc`DiracTrick`Private`res, {DiracGamma[5], 
            DiracGamma[6], DiracGamma[7]}]; FCPrint[3, "DiracTrick: \
diracTrickEval: after applying simplifications related to g^5: ", 
         FeynCalc`DiracTrick`Private`res, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; ]; 
      If[FreeQ2[FeynCalc`DiracTrick`Private`res, 
        FeynCalc`Package`DiracHeadsList], 
       Return[FeynCalc`DiracTrick`Private`res]]; 
      If[FeynCalc`DiracTrick`Private`insideDiracTrace, 
       FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FCPrint[2, 
         "DiracTrick: diracTrickEval: Applying diracTraceSimplify ", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`res = 
         FeynCalc`DiracTrick`Private`diracTraceSimplify[
              FeynCalc`DiracTrick`Private`res] /. DOT -> 
              FeynCalc`DiracTrick`Private`holdDOT /. 
            FeynCalc`DiracTrick`Private`diracTraceSimplify[
              FeynCalc`DiracTrick`Private`holdDOT[
               FeynCalc`DiracTrick`Private`x__]] :> 
             FeynCalc`DiracTrick`Private`diracTraceSimplify[
              FeynCalc`DiracTrick`Private`x] /. 
           FeynCalc`DiracTrick`Private`diracTraceSimplify -> 
            FeynCalc`DiracTrick`Private`commonGamma5Properties /. 
          FeynCalc`DiracTrick`Private`commonGamma5Properties -> 
           FeynCalc`DiracTrick`Private`holdDOT; FCPrint[1, 
         "DiracTrick: diracTrickEval: diracTraceSimplify done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrick: diracTrickEval: After diracTraceSimplify ", 
         FeynCalc`DiracTrick`Private`res, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose], 
       FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`res /. 
          DOT -> FeynCalc`DiracTrick`Private`holdDOT; ]; 
      If[ !FreeQ[FeynCalc`DiracTrick`Private`res, Pair], 
       FeynCalc`DiracTrick`Private`res = 
         Expand2[FeynCalc`DiracTrick`Private`res, Pair] /. 
           Pair -> PairContract /. PairContract -> Pair; ]; 
      If[ !FreeQ[FeynCalc`DiracTrick`Private`res, CartesianPair], 
       FeynCalc`DiracTrick`Private`res = 
         Expand2[FeynCalc`DiracTrick`Private`res, CartesianPair] /. 
           CartesianPair -> CartesianPairContract /. CartesianPairContract -> 
           CartesianPair; ]; If[FreeQ2[FeynCalc`DiracTrick`Private`res, 
        FeynCalc`Package`DiracHeadsList], 
       Return[FeynCalc`DiracTrick`Private`res]]; 
      FeynCalc`DiracTrick`Private`dim = FCGetDimensions[
        FeynCalc`DiracTrick`Private`res, FreeQ -> {DiracGamma[5], 
          DiracGamma[6], DiracGamma[7]}, ChangeDimension -> True]; 
      FeynCalc`DiracTrick`Private`noncommPresent = 
        !NonCommFreeQ[FeynCalc`DiracTrick`Private`res /. 
          DiracGamma -> FeynCalc`DiracTrick`Private`diga]; 
      FCPrint[3, "DiracTrick: diracTrickEval: Dimensions: ", 
       FeynCalc`DiracTrick`Private`dim, FCDoControl -> 
        FeynCalc`DiracTrick`Private`diTrVerbose]; 
      If[FeynCalc`DiracTrick`Private`gamma5Present, 
       FeynCalc`DiracTrick`Private`time = AbsoluteTime[]; 
        FCPrint[2, "DiracTrick: diracTrickEval: Applying chiralTrick ", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        Which[MatchQ[FeynCalc`DiracTrick`Private`dim, {4}], 
         FCPrint[2, "DiracTrick: diracTrickEval: Purely 4-dim.", 
           FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
          FeynCalc`DiracTrick`Private`res = 
           FeynCalc`DiracTrick`Private`res /. 
            FeynCalc`DiracTrick`Private`holdDOT -> 
             FeynCalc`DiracTrick`Private`chiralTrickAnticommuting4DimRight; 
          FeynCalc`DiracTrick`Private`res = FixedPoint[
            #1 /. 
               FeynCalc`DiracTrick`Private`chiralTrickAnticommuting4DimRight \
-> FeynCalc`DiracTrick`Private`commonGamma5Properties /. 
              FeynCalc`DiracTrick`Private`commonGamma5Properties -> 
               FeynCalc`DiracTrick`Private`chiralTrickAnticommuting4DimRight \
& , FeynCalc`DiracTrick`Private`res]; FeynCalc`DiracTrick`Private`res = 
           FeynCalc`DiracTrick`Private`res /. 
            FeynCalc`DiracTrick`Private`chiralTrickAnticommuting4DimRight -> 
             FeynCalc`DiracTrick`Private`holdDOT, 
         MatchQ[FeynCalc`DiracTrick`Private`dim, {_Symbol}] && 
          MemberQ[{"NDR", "NDR-Discard"}, FeynCalc`Package`DiracGammaScheme], 
         FCPrint[2, "DiracTrick: diracTrickEval: Purely D-dim, NDR.", 
           FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
          FeynCalc`DiracTrick`Private`res = 
           FeynCalc`DiracTrick`Private`res /. 
            FeynCalc`DiracTrick`Private`holdDOT -> 
             FeynCalc`DiracTrick`Private`chiralTrickAnticommutingDDimRight; 
          FeynCalc`DiracTrick`Private`res = FixedPoint[
            #1 /. 
               FeynCalc`DiracTrick`Private`chiralTrickAnticommutingDDimRight \
-> FeynCalc`DiracTrick`Private`commonGamma5Properties /. 
              FeynCalc`DiracTrick`Private`commonGamma5Properties -> 
               FeynCalc`DiracTrick`Private`chiralTrickAnticommutingDDimRight \
& , FeynCalc`DiracTrick`Private`res]; FeynCalc`DiracTrick`Private`res = 
           FeynCalc`DiracTrick`Private`res /. 
            FeynCalc`DiracTrick`Private`chiralTrickAnticommutingDDimRight -> 
             FeynCalc`DiracTrick`Private`holdDOT, 
         MatchQ[FeynCalc`DiracTrick`Private`dim, {_Symbol}] && 
          FeynCalc`Package`DiracGammaScheme === "BMHV", 
         FCPrint[2, "DiracTrick: diracTrickEval: Purely D-dim and BMHV.", 
           FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; , 
         MatchQ[FeynCalc`DiracTrick`Private`dim, {_Symbol}] && 
          FeynCalc`Package`DiracGammaScheme === "Larin", 
         FCPrint[2, "DiracTrick: diracTrickEval: Purely D-dim and Larin.", 
           FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
          FeynCalc`DiracTrick`Private`res = 
           FeynCalc`DiracTrick`Private`res /. 
             FeynCalc`DiracTrick`Private`holdDOT -> 
              FeynCalc`DiracTrick`Private`chiralTrickLarin /. 
            FeynCalc`DiracTrick`Private`chiralTrickLarin -> 
             FeynCalc`DiracTrick`Private`holdDOT, 
         FeynCalc`DiracTrick`Private`dim =!= {} && 
          FeynCalc`Package`DiracGammaScheme === "BMHV", 
         FCPrint[1, "DiracTrick: diracTrickEval: Mixed and BMHV.", 
          FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose], 
         FeynCalc`DiracTrick`Private`dim === {} && 
           !FreeQ2[FeynCalc`DiracTrick`Private`res, {DiracGamma[5], 
             DiracGamma[6], DiracGamma[7], DiracGamma[ExplicitLorentzIndex[
               0]]}] && FreeQ[FeynCalc`DiracTrick`Private`res /. 
            DiracGamma[5 | 6 | 7 | ExplicitLorentzIndex[0]] :> 
             FeynCalc`DiracTrick`Private`diga, DiracGamma], 
         FCPrint[2, "DiracTrick: diracTrickEval: Chiral or g^0 only.", 
          FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose], True, 
         Message[DiracTrace::mixmsg]; Abort[]]; FCPrint[2, 
         "DiracTrick: diracTrickEval: chiralTrick done, timing: ", 
         N[AbsoluteTime[] - FeynCalc`DiracTrick`Private`time, 4], 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[3, "DiracTrick: diracTrickEval: After chiralTrick ", 
         FeynCalc`DiracTrick`Private`res, FCDoControl -> 
          FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`gamma5Present = 
          !FreeQ2[FeynCalc`DiracTrick`Private`res, {DiracGamma[5], 
            DiracGamma[6], DiracGamma[7]}]]; FCPrint[2, "DiracTrick: \
diracTrickEval: Doing simplifications unrelated to g^5.", 
       FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
      Which[MatchQ[FeynCalc`DiracTrick`Private`dim, {4}], 
       FCPrint[2, "DiracTrick: diracTrickEval: Purely 4-dim.", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FCPrint[2, "DiracTrick: diracTrickEval: Applying diracology4Dim.", 
         FCDoControl -> FeynCalc`DiracTrick`Private`diTrVerbose]; 
        FeynCalc`DiracTrick`Private`res = FeynCalc`DiracTrick`Private`res /. 
          FeynCalc`DiracTrick`Private`holdDOT -> 
