FeynCalc`DiracTrace`Private`traceEpsNo5[FeynCalc`DiracTrace`Private`mu_, 
     FeynCalc`DiracTrace`Private`nu_, FeynCalc`DiracTrace`Private`rho_, 
     FeynCalc`DiracTrace`Private`SI2__] := 
    Block[{FeynCalc`DiracTrace`Private`head, FeynCalc`DiracTrace`Private`s = 
       -1, FeynCalc`DiracTrace`Private`res}, 
     FeynCalc`DiracTrace`Private`res = Plus @@ MapIndexed[
         (FeynCalc`DiracTrace`Private`s = -FeynCalc`DiracTrace`Private`s)*
           Eps[FeynCalc`DiracTrace`Private`mu, 
            FeynCalc`DiracTrace`Private`nu, FeynCalc`DiracTrace`Private`rho, 
            #1]*Drop[FeynCalc`DiracTrace`Private`head[
             FeynCalc`DiracTrace`Private`SI2], #2] & , 
         {FeynCalc`DiracTrace`Private`SI2}]; 
      FeynCalc`DiracTrace`Private`res = FeynCalc`DiracTrace`Private`res /. 
        FeynCalc`DiracTrace`Private`head -> 
         FeynCalc`DiracTrace`Private`traceNo5Wrap; 
      FeynCalc`DiracTrace`Private`res]
 
FeynCalc`DiracTrace`Private`spur5LarinMVV[
     FeynCalc`DiracTrace`Private`x__DiracGamma, FeynCalc`DiracTrace`Private`y:
      DiracGamma[_[_, FeynCalc`DiracTrace`Private`dim_], 
       FeynCalc`DiracTrace`Private`dim_], DiracGamma[5]] := 
    Block[{FeynCalc`DiracTrace`Private`inds, 
       FeynCalc`DiracTrace`Private`epsInds, 
       FeynCalc`DiracTrace`Private`gInds, 
       FeynCalc`DiracTrace`Private`indPartitions, 
       FeynCalc`DiracTrace`Private`res, FeynCalc`DiracTrace`Private`signs, 
       FeynCalc`DiracTrace`Private`eps}, 
      If[TrueQ[FeynCalc`DiracTrace`Private`holdEpsQ], 
        FeynCalc`DiracTrace`Private`eps = Hold[Eps], 
        FeynCalc`DiracTrace`Private`eps = Eps]; 
       FeynCalc`DiracTrace`Private`inds = First /@ 
         {FeynCalc`DiracTrace`Private`x, FeynCalc`DiracTrace`Private`y}; 
       FeynCalc`DiracTrace`Private`epsInds = 
        Subsets[FeynCalc`DiracTrace`Private`inds, {4}]; 
       FeynCalc`DiracTrace`Private`gInds = 
        (SelectFree[FeynCalc`DiracTrace`Private`inds, #1] & ) /@ 
         FeynCalc`DiracTrace`Private`epsInds; 
       FeynCalc`DiracTrace`Private`indPartitions = MapThread[Join[#1, #2] & , 
         {FeynCalc`DiracTrace`Private`gInds, 
          FeynCalc`DiracTrace`Private`epsInds}]; 
       FeynCalc`DiracTrace`Private`signs = Signature /@ 
         (FeynCalc`DiracTrace`Private`indPartitions /. 
          Thread[FeynCalc`DiracTrace`Private`inds -> 
            Range[Length[FeynCalc`DiracTrace`Private`inds]]]); 
       FeynCalc`DiracTrace`Private`res = 
        Total[MapThread[$LeviCivitaSign*I*#2*
            FeynCalc`DiracTrace`Private`traceNo5Wrap @@ #1[[1 ;; -5]]*
            FeynCalc`DiracTrace`Private`eps @@ #1[[-4 ;; All]] & , 
          {FeynCalc`DiracTrace`Private`indPartitions, 
           FeynCalc`DiracTrace`Private`signs}]]; 
       FeynCalc`DiracTrace`Private`fastExpand[
        FeynCalc`DiracTrace`Private`res]] /; 
     EvenQ[Length[{FeynCalc`DiracTrace`Private`x, 
         FeynCalc`DiracTrace`Private`y}]] && 
      Length[{FeynCalc`DiracTrace`Private`x, 
         FeynCalc`DiracTrace`Private`y}] >= 4
 
FeynCalc`DiracTrace`Private`spur5Larin[
     FeynCalc`DiracTrace`Private`x__DiracGamma, FeynCalc`DiracTrace`Private`y:
      DiracGamma[_[_, FeynCalc`DiracTrace`Private`dim_], 
       FeynCalc`DiracTrace`Private`dim_], DiracGamma[5]] := 
    Block[{FeynCalc`DiracTrace`Private`li1, FeynCalc`DiracTrace`Private`li2, 
       FeynCalc`DiracTrace`Private`li3, FeynCalc`DiracTrace`Private`res}, 
      {FeynCalc`DiracTrace`Private`li1, FeynCalc`DiracTrace`Private`li2, 
         FeynCalc`DiracTrace`Private`li3} = 
        (LorentzIndex[#1, FeynCalc`DiracTrace`Private`dim] & ) /@ 
         Unique[{"larLia", "larLib", "larLic"}]; 
       If[FCGetDimensions[{FeynCalc`DiracTrace`Private`x}, 
          ChangeDimension -> True] =!= {FeynCalc`DiracTrace`Private`dim}, 
        Message[DiracTrace::mixmsg]; Abort[]]; 
       FeynCalc`DiracTrace`Private`res = 
        (I/6)*FeynCalc`DiracTrace`Private`leviCivitaSign*
         Eps[FeynCalc`DiracTrace`Private`y[[1]], 
          FeynCalc`DiracTrace`Private`li1, FeynCalc`DiracTrace`Private`li2, 
          FeynCalc`DiracTrace`Private`li3]*
         FeynCalc`DiracTrace`Private`spurNo5[FeynCalc`DiracTrace`Private`x, 
          DiracGamma[FeynCalc`DiracTrace`Private`li1, 
           FeynCalc`DiracTrace`Private`dim], DiracGamma[
           FeynCalc`DiracTrace`Private`li2, FeynCalc`DiracTrace`Private`dim], 
          DiracGamma[FeynCalc`DiracTrace`Private`li3, 
           FeynCalc`DiracTrace`Private`dim]]; 
       If[FCGetDimensions[{FeynCalc`DiracTrace`Private`res}, 
          ChangeDimension -> True] =!= {FeynCalc`DiracTrace`Private`dim}, 
        Message[DiracTrace::failmsg, 
          "Something went wrong while computing trace in Larin's scheme."]; 
         Abort[]]; FeynCalc`DiracTrace`Private`res] /; 
     EvenQ[Length[{FeynCalc`DiracTrace`Private`x, 
        FeynCalc`DiracTrace`Private`y}]]
 
FeynCalc`DiracTrace`Private`spur5BMHVWest[
     FeynCalc`DiracTrace`Private`x__DiracGamma, DiracGamma[5]] := 
    Block[{FeynCalc`DiracTrace`Private`spx = {FeynCalc`DiracTrace`Private`x, 
         DiracGamma[5]}, FeynCalc`DiracTrace`Private`spt, 
       FeynCalc`DiracTrace`Private`res}, FeynCalc`DiracTrace`Private`res = 
        (2/(Length[FeynCalc`DiracTrace`Private`spx] - 5))*
         Sum[(-1)^(FeynCalc`DiracTrace`Private`i + 
             FeynCalc`DiracTrace`Private`j + 1)*FCUseCache[
            ExpandScalarProduct, {Pair[FeynCalc`DiracTrace`Private`spx[[
                FeynCalc`DiracTrace`Private`i]][[1]], 
              FeynCalc`DiracTrace`Private`spx[[
                FeynCalc`DiracTrace`Private`j]][[1]]]}, {FCI -> False}]*
           FeynCalc`DiracTrace`Private`spt @@ Delete[
             FeynCalc`DiracTrace`Private`spx, 
             {{FeynCalc`DiracTrace`Private`j}, 
              {FeynCalc`DiracTrace`Private`i}}], 
          {FeynCalc`DiracTrace`Private`i, 2, 
           Length[FeynCalc`DiracTrace`Private`spx] - 1}, 
          {FeynCalc`DiracTrace`Private`j, 1, FeynCalc`DiracTrace`Private`i - 
            1}]; FeynCalc`DiracTrace`Private`res = 
        Expand[FeynCalc`DiracTrace`Private`res] /. 
         FeynCalc`DiracTrace`Private`spt -> 
          FeynCalc`DiracTrace`Private`spur5BMHVWest; 
       FeynCalc`DiracTrace`Private`res] /; 
     EvenQ[Length[{FeynCalc`DiracTrace`Private`x}]] && 
      Length[{FeynCalc`DiracTrace`Private`x}] > 4
 
FeynCalc`DiracTrace`Private`spur5BMHVWest[
     DiracGamma[FeynCalc`DiracTrace`Private`x_, ___], 
     DiracGamma[FeynCalc`DiracTrace`Private`y_, ___], 
     DiracGamma[FeynCalc`DiracTrace`Private`r_, ___], 
     DiracGamma[FeynCalc`DiracTrace`Private`z_, ___], DiracGamma[5]] := 
