       Eps[Take[FeynCalc`DiracTrace`Private`x, 1], 
        Take[FeynCalc`DiracTrace`Private`y, 1], 
        Take[FeynCalc`DiracTrace`Private`r, 1], 
        Take[FeynCalc`DiracTrace`Private`z, 1]], FCI -> True] /; 
      !MatchQ[FCGetDimensions[{FeynCalc`DiracTrace`Private`x, 
         FeynCalc`DiracTrace`Private`y, FeynCalc`DiracTrace`Private`r, 
         FeynCalc`DiracTrace`Private`z}, ChangeDimension -> True], 
       {___, _Symbol - 4, ___}]
 
FeynCalc`DiracTrace`Private`spur5BMHVWest[
     DiracGamma[FeynCalc`DiracTrace`Private`x_, ___], 
     DiracGamma[FeynCalc`DiracTrace`Private`y_, ___], 
     DiracGamma[FeynCalc`DiracTrace`Private`r_, ___], 
     DiracGamma[FeynCalc`DiracTrace`Private`z_, ___], DiracGamma[5]] := 
    0 /; MatchQ[FCGetDimensions[{FeynCalc`DiracTrace`Private`x, 
        FeynCalc`DiracTrace`Private`y, FeynCalc`DiracTrace`Private`r, 
        FeynCalc`DiracTrace`Private`z}, ChangeDimension -> True], 
      {___, _Symbol - 4, ___}]
 
FeynCalc`DiracTrace`Private`spur5BMHVNoWest[
     FeynCalc`DiracTrace`Private`x__DiracGamma, DiracGamma[5]] := 
    Block[{FeynCalc`DiracTrace`Private`li1, FeynCalc`DiracTrace`Private`li2, 
       FeynCalc`DiracTrace`Private`li3, FeynCalc`DiracTrace`Private`li4, 
       FeynCalc`DiracTrace`Private`res}, 
      {FeynCalc`DiracTrace`Private`li1, FeynCalc`DiracTrace`Private`li2, 
         FeynCalc`DiracTrace`Private`li3, FeynCalc`DiracTrace`Private`li4} = 
        LorentzIndex /@ Unique[{"bmLia", "bmLib", "bmLic", "bmLid"}]; 
       FeynCalc`DiracTrace`Private`res = FeynCalc`Package`FCFastContract[
         (I/24)*FeynCalc`DiracTrace`Private`leviCivitaSign*
          Expand2[Eps[FeynCalc`DiracTrace`Private`li1, 
             FeynCalc`DiracTrace`Private`li2, 
             FeynCalc`DiracTrace`Private`li3, 
             FeynCalc`DiracTrace`Private`li4]*
            FeynCalc`DiracTrace`Private`spurNo5[
             FeynCalc`DiracTrace`Private`x, DiracGamma[
              FeynCalc`DiracTrace`Private`li1], DiracGamma[
              FeynCalc`DiracTrace`Private`li2], DiracGamma[
              FeynCalc`DiracTrace`Private`li3], DiracGamma[
              FeynCalc`DiracTrace`Private`li4]], LorentzIndex]]; 
       FeynCalc`DiracTrace`Private`res] /; 
     EvenQ[Length[{FeynCalc`DiracTrace`Private`x}]]
 
