       FeynCalc`CovariantD`Private`cC, FeynCalc`CovariantD`Private`res, 
       FeynCalc`CovariantD`Private`partial, FeynCalc`CovariantD`Private`qf}, 
      FeynCalc`CovariantD`Private`aA = OptionValue[QuantumField]; 
       FeynCalc`CovariantD`Private`g = OptionValue[CouplingConstant]; 
       FeynCalc`CovariantD`Private`partial = OptionValue[FCPartialD]; 
       FeynCalc`CovariantD`Private`cC = Unique["c"]; 
       If[TrueQ[Head[FeynCalc`CovariantD`Private`al] === Momentum], 
        FeynCalc`CovariantD`Private`qf = QuantumField[
          FeynCalc`CovariantD`Private`aA, Momentum[
           FeynCalc`CovariantD`Private`al], SUNIndex[
           FeynCalc`CovariantD`Private`cC]], FeynCalc`CovariantD`Private`qf = 
         QuantumField[FeynCalc`CovariantD`Private`aA, LorentzIndex[
           FeynCalc`CovariantD`Private`al], SUNIndex[
           FeynCalc`CovariantD`Private`cC]]]; 
       FeynCalc`CovariantD`Private`partial[FeynCalc`CovariantD`Private`al] - 
        FeynCalc`CovariantD`Private`g*I*
         DOT[SUNT[SUNIndex[FeynCalc`CovariantD`Private`cC]], 
          FeynCalc`CovariantD`Private`qf]] /; OptionValue[Explicit]
 
CovariantD[FeynCalc`CovariantD`Private`al_, FeynCalc`CovariantD`Private`a_, 
     FeynCalc`CovariantD`Private`b_ /; 
       !OptionQ[{FeynCalc`CovariantD`Private`b}], OptionsPattern[]] := 
    Block[{FeynCalc`CovariantD`Private`aA, FeynCalc`CovariantD`Private`g, 
       FeynCalc`CovariantD`Private`cC, FeynCalc`CovariantD`Private`partial, 
       FeynCalc`CovariantD`Private`qf}, FeynCalc`CovariantD`Private`aA = 
        OptionValue[QuantumField]; FeynCalc`CovariantD`Private`g = 
        OptionValue[CouplingConstant]; FeynCalc`CovariantD`Private`partial = 
        OptionValue[FCPartialD]; FeynCalc`CovariantD`Private`cC = 
        Unique["c"]; If[TrueQ[Head[FeynCalc`CovariantD`Private`al] === 
          Momentum], FeynCalc`CovariantD`Private`qf = 
         QuantumField[FeynCalc`CovariantD`Private`aA, 
          Momentum[FeynCalc`CovariantD`Private`al], 
          SUNIndex[FeynCalc`CovariantD`Private`cC]], 
        FeynCalc`CovariantD`Private`qf = QuantumField[
          FeynCalc`CovariantD`Private`aA, LorentzIndex[
           FeynCalc`CovariantD`Private`al], SUNIndex[
           FeynCalc`CovariantD`Private`cC]]]; 
       SUNDelta[FeynCalc`CovariantD`Private`a, FeynCalc`CovariantD`Private`b]*
         FeynCalc`CovariantD`Private`partial[
          FeynCalc`CovariantD`Private`al] - FeynCalc`CovariantD`Private`g*
         SUNF[FeynCalc`CovariantD`Private`a, FeynCalc`CovariantD`Private`b, 
          FeynCalc`CovariantD`Private`cC]*FeynCalc`CovariantD`Private`qf] /; 
     OptionValue[Explicit] && Head[FeynCalc`CovariantD`Private`a] =!= 
       SUNFIndex
 
CovariantD[FeynCalc`CovariantD`Private`al_, 
     FeynCalc`CovariantD`Private`a_SUNFIndex, 
     FeynCalc`CovariantD`Private`b_SUNFIndex, OptionsPattern[]] := 
    Block[{FeynCalc`CovariantD`Private`aA, FeynCalc`CovariantD`Private`cC, 
       FeynCalc`CovariantD`Private`du, FeynCalc`CovariantD`Private`partial, 
       FeynCalc`CovariantD`Private`g, FeynCalc`CovariantD`Private`qf}, 
      FeynCalc`CovariantD`Private`aA = OptionValue[QuantumField]; 
       FeynCalc`CovariantD`Private`g = OptionValue[CouplingConstant]; 
       FeynCalc`CovariantD`Private`partial = OptionValue[FCPartialD]; 
       FeynCalc`CovariantD`Private`cC = Unique["c"]; 
       If[TrueQ[Head[FeynCalc`CovariantD`Private`al] === Momentum], 
        FeynCalc`CovariantD`Private`qf = QuantumField[
          FeynCalc`CovariantD`Private`aA, Momentum[
           FeynCalc`CovariantD`Private`al], SUNIndex[
           FeynCalc`CovariantD`Private`cC]], FeynCalc`CovariantD`Private`qf = 
         QuantumField[FeynCalc`CovariantD`Private`aA, LorentzIndex[
           FeynCalc`CovariantD`Private`al], SUNIndex[
           FeynCalc`CovariantD`Private`cC]]]; 
       SUNFDelta[FeynCalc`CovariantD`Private`a, 
          FeynCalc`CovariantD`Private`b]*FeynCalc`CovariantD`Private`partial[
          FeynCalc`CovariantD`Private`al] - I*FeynCalc`CovariantD`Private`g*
         SUNTF[FeynCalc`CovariantD`Private`cC, FeynCalc`CovariantD`Private`a, 
          FeynCalc`CovariantD`Private`b]*FeynCalc`CovariantD`Private`qf] /; 
     OptionValue[Explicit]
 
CovariantD /: MakeBoxes[CovariantD[FeynCalc`CovariantD`Private`mud_], 
      TraditionalForm] := RowBox[{SubscriptBox["D", 
        TBox[FeynCalc`CovariantD`Private`mud]]}]
 
CovariantD /: MakeBoxes[CovariantD[FeynCalc`CovariantD`Private`mud_, 
       FeynCalc`CovariantD`Private`a_, FeynCalc`CovariantD`Private`b_], 
      TraditionalForm] := SubsuperscriptBox["D", 
       TBox[FeynCalc`CovariantD`Private`mud], 
       TBox[FeynCalc`CovariantD`Private`a, FeynCalc`CovariantD`Private`b]] /; 
      Head[FeynCalc`CovariantD`Private`mud] =!= List
 
CovariantD /: MakeBoxes[CovariantD[FeynCalc`CovariantD`Private`x_, 
       LorentzIndex[FeynCalc`CovariantD`Private`mu__]], TraditionalForm] := 
     RowBox[{"\[PartialD]", "/", "D", SuperscriptBox[
        ToBoxes[FeynCalc`CovariantD`Private`x, TraditionalForm], 
        ToBoxes[LorentzIndex[FeynCalc`CovariantD`Private`mu], 
         TraditionalForm]]}]
 
Options[CovariantD] = {CouplingConstant -> SMP["g_s"], Explicit -> False, 
     FCPartialD -> RightPartialD, QuantumField -> GaugeField}
 
CovariantD /: CovariantD::usage = "CovariantD[mu] is a generic covariant \
derivative with Lorentz index $\\mu$.\n\nCovariantD[x, mu] is a generic \
covariant derivative with respect to $x^{\\mu\n}$.\n\nCovariantD[mu, a, b] is \
a covariant derivative for a bosonic field that acts\non QuantumField[f, {}, \
{a, b}], where f is some field name and a and b are two\n$SU(N)$ indices in \
the adjoint representation."
 
FeynCalc`FCChargeConjugateTransposed`Private`fcctVerbose /: 
    FeynCalc`FCChargeConjugateTransposed`Private`fcctVerbose::usage = ""
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
     FeynCalc`FCChargeConjugateTransposed`Private`d_DiracSigma] := 
    -FeynCalc`FCChargeConjugateTransposed`Private`d /; 
     FreeQ2[FeynCalc`FCChargeConjugateTransposed`Private`d, 
      {DiracGamma[5], DiracGamma[6], DiracGamma[7]}]
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
     FeynCalc`FCChargeConjugateTransposed`Private`d_DiracGamma] := 
    -FeynCalc`FCChargeConjugateTransposed`Private`d /; 
      !MatchQ[FeynCalc`FCChargeConjugateTransposed`Private`d, 
       DiracGamma[5 | 6 | 7]]
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
     FeynCalc`FCChargeConjugateTransposed`Private`d:DiracGamma[5 | 6 | 7]] := 
    FeynCalc`FCChargeConjugateTransposed`Private`d
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
     (FeynCalc`FCChargeConjugateTransposed`Private`c2_:0) + 
      (FeynCalc`FCChargeConjugateTransposed`Private`c1_.)*
       (FeynCalc`FCChargeConjugateTransposed`Private`d_DiracGamma)] := 
    (-FeynCalc`FCChargeConjugateTransposed`Private`c1)*
       FeynCalc`FCChargeConjugateTransposed`Private`d + 
      FeynCalc`FCChargeConjugateTransposed`Private`c2 /; 
     NonCommFreeQ[{FeynCalc`FCChargeConjugateTransposed`Private`c1, 
        FeynCalc`FCChargeConjugateTransposed`Private`c2}] && 
      FreeQ[{FeynCalc`FCChargeConjugateTransposed`Private`c1, 
        FeynCalc`FCChargeConjugateTransposed`Private`c2}, 
       FeynCalc`FCChargeConjugateTransposed`Private`dotHold] && 
       !MatchQ[FeynCalc`FCChargeConjugateTransposed`Private`d, 
        DiracGamma[5 | 6 | 7]]
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
     (FeynCalc`FCChargeConjugateTransposed`Private`c_)*
      (
       FeynCalc`FCChargeConjugateTransposed`Private`d_FeynCalc`FCChargeConjug\
ateTransposed`Private`dotHold)] := 
    FeynCalc`FCChargeConjugateTransposed`Private`c*
      FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
       FeynCalc`FCChargeConjugateTransposed`Private`d] /; 
     NonCommFreeQ[FeynCalc`FCChargeConjugateTransposed`Private`c]
 
FeynCalc`FCChargeConjugateTransposed`Private`dotHold[] := 1
 
FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
     FeynCalc`FCChargeConjugateTransposed`Private`a___, 
     FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateMultiple[1], 
     FeynCalc`FCChargeConjugateTransposed`Private`b___] := 
    FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
     FeynCalc`FCChargeConjugateTransposed`Private`a, 
     FeynCalc`FCChargeConjugateTransposed`Private`b]
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateMultiple[
     FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
      FeynCalc`FCChargeConjugateTransposed`Private`a_]] := 
    FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle[
     FeynCalc`FCChargeConjugateTransposed`Private`a]
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateMultiple[
     FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
      FeynCalc`FCChargeConjugateTransposed`Private`rest1___, 
      Longest[FeynCalc`FCChargeConjugateTransposed`Private`d:
        DiracGamma[__]..], 
      FeynCalc`FCChargeConjugateTransposed`Private`rest2___]] := 
    (-1)^Length[{FeynCalc`FCChargeConjugateTransposed`Private`d}]*
      FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
       FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateMultiple[
        FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
         FeynCalc`FCChargeConjugateTransposed`Private`rest1]], 
       FeynCalc`FCChargeConjugateTransposed`Private`d, 
       FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateMultiple[
        FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
         FeynCalc`FCChargeConjugateTransposed`Private`rest2]]] /; 
     Length[{FeynCalc`FCChargeConjugateTransposed`Private`d}] > 1 && 
      FreeQ2[{FeynCalc`FCChargeConjugateTransposed`Private`d}, 
       {DiracGamma[5], DiracGamma[6], DiracGamma[7]}]
 
FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSplit[
     FeynCalc`FCChargeConjugateTransposed`Private`dotHold[
      FeynCalc`FCChargeConjugateTransposed`Private`a__]] := 
    FeynCalc`FCChargeConjugateTransposed`Private`dotHold @@ 
     FeynCalc`FCChargeConjugateTransposed`Private`cctEvaluateSingle /@ 
      {FeynCalc`FCChargeConjugateTransposed`Private`a}
 
FeynCalc`DataType`Private`set /: FeynCalc`DataType`Private`set::usage = ""
 
FeynCalc`DataType`Private`setDataTypeFCTensor[FeynCalc`DataType`Private`exp_, 
     FeynCalc`DataType`Private`bool_] := 
    Block[{FeynCalc`DataType`Private`ndt, FeynCalc`DataType`Private`ndf, 
      FeynCalc`DataType`Private`dt, FeynCalc`DataType`Private`ncq, 
      FeynCalc`DataType`Private`nnn, FeynCalc`DataType`Private`nnt, 
      FeynCalc`DataType`Private`set, FeynCalc`DataType`Private`downvalues, 
      FeynCalc`DataType`Private`hp}, If[FeynCalc`DataType`Private`bool, 
       If[ !MemberQ[$FCTensorList, FeynCalc`DataType`Private`exp], 
        AppendTo[$FCTensorList, FeynCalc`DataType`Private`exp]], 
       If[MemberQ[$FCTensorList, FeynCalc`DataType`Private`exp], 
        $FCTensorList = SelectFree[$FCTensorList, 
           FeynCalc`DataType`Private`exp]; ]]; 
      FeynCalc`DataType`Private`ndt = 
       RuleDelayed @@ {HoldPattern @@ {FeynCalc`DataType`Private`dt[
             FeynCalc`DataType`Private`exp, FCTensor]}, True} /. 
        FeynCalc`DataType`Private`dt -> DataType; 
      FeynCalc`DataType`Private`ndf = 
       RuleDelayed @@ {HoldPattern @@ {FeynCalc`DataType`Private`dt[
             FeynCalc`DataType`Private`exp, FCTensor]}, False} /. 
        FeynCalc`DataType`Private`dt -> DataType; 
      If[FeynCalc`DataType`Private`bool, If[FreeQ[DownValues[DataType], 
         FeynCalc`DataType`Private`ndt], DownValues[DataType] = 
         Prepend[SelectFree[DownValues[DataType] /. 
             {DataType -> FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}, 
            FeynCalc`DataType`Private`ndf /. {DataType -> 
               FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}] /. 
           {FeynCalc`DataType`Private`dt -> DataType, 
            FeynCalc`DataType`Private`hp -> HoldPattern}, 
          FeynCalc`DataType`Private`ndt]], If[FreeQ[DownValues[DataType], 
         FeynCalc`DataType`Private`ndf], DownValues[DataType] = 
         Prepend[SelectFree[DownValues[DataType] /. 
             {DataType -> FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}, 
            FeynCalc`DataType`Private`ndt /. {DataType -> 
               FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}] /. 
           {FeynCalc`DataType`Private`dt -> DataType, 
            FeynCalc`DataType`Private`hp -> HoldPattern}, 
          FeynCalc`DataType`Private`ndf]]]; 
      If[$ParallelizeFeynCalc && $KernelID === 0, 
       If[ !FCValuesSynchronizedQ[{DataType}, DownValues], 
        Message[ScalarProduct::notsync]]]; FeynCalc`DataType`Private`bool]
 
FeynCalc`DataType`Private`setDataType[FeynCalc`DataType`Private`exp_, 
     FeynCalc`DataType`Private`type_, FeynCalc`DataType`Private`bool_] := 
    Block[{FeynCalc`DataType`Private`ndt, FeynCalc`DataType`Private`ndf, 
      FeynCalc`DataType`Private`dt, FeynCalc`DataType`Private`hp}, 
     FeynCalc`DataType`Private`ndt = 
       RuleDelayed @@ {HoldPattern @@ {FeynCalc`DataType`Private`dt[
             FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`type]}, 
          True} /. FeynCalc`DataType`Private`dt -> DataType; 
      FeynCalc`DataType`Private`ndf = 
       RuleDelayed @@ {HoldPattern @@ {FeynCalc`DataType`Private`dt[
             FeynCalc`DataType`Private`exp, FeynCalc`DataType`Private`type]}, 
          False} /. FeynCalc`DataType`Private`dt -> DataType; 
      If[FeynCalc`DataType`Private`bool, If[FreeQ[DownValues[DataType], 
         FeynCalc`DataType`Private`ndt], DownValues[DataType] = 
         Prepend[SelectFree[DownValues[DataType] /. 
             {DataType -> FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}, 
            FeynCalc`DataType`Private`ndf /. {DataType -> 
               FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}] /. 
           {FeynCalc`DataType`Private`dt -> DataType, 
            FeynCalc`DataType`Private`hp -> HoldPattern}, 
          FeynCalc`DataType`Private`ndt]], If[FreeQ[DownValues[DataType], 
         FeynCalc`DataType`Private`ndf], DownValues[DataType] = 
         Prepend[SelectFree[DownValues[DataType] /. 
             {DataType -> FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}, 
            FeynCalc`DataType`Private`ndt /. {DataType -> 
               FeynCalc`DataType`Private`dt, HoldPattern -> 
               FeynCalc`DataType`Private`hp}] /. 
           {FeynCalc`DataType`Private`dt -> DataType, 
            FeynCalc`DataType`Private`hp -> HoldPattern}, 
          FeynCalc`DataType`Private`ndf]]]; 
      If[$ParallelizeFeynCalc && $KernelID === 0, 
       If[ !FCValuesSynchronizedQ[{DataType}, DownValues], 
        Message[DataType::notsync]]]; ]
 
FeynCalc`SharedObjectsTypesetting`Private`polarizationRep[
     FeynCalc`SharedObjectsTypesetting`Private`pol_, 
     FeynCalc`SharedObjectsTypesetting`Private`dim_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, 1] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim === 4, 
     OverscriptBox["\[CurlyEpsilon]", $TypesettingDim4], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, 1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol], 
     If[$TypesettingDimD === "", ToBoxes["\[CurlyEpsilon]", TraditionalForm], 
      OverscriptBox["\[CurlyEpsilon]", $TypesettingDimD]], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, 1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 4], 
     OverscriptBox["\[CurlyEpsilon]", $TypesettingDimE], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, -1] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim === 4, 
     SuperscriptBox[OverscriptBox["\[CurlyEpsilon]", $TypesettingDim4], "*"], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, -1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol], 
     If[$TypesettingDimD === "", SuperscriptBox[ToBoxes["\[CurlyEpsilon]", 
        TraditionalForm], "*"], SuperscriptBox[OverscriptBox[
        "\[CurlyEpsilon]", $TypesettingDimD], "*"]], 
     FeynCalc`SharedObjectsTypesetting`Private`pol === Complex[0, -1] && 
      MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 4], 
     SuperscriptBox[OverscriptBox["\[CurlyEpsilon]", $TypesettingDimE], "*"], 
     True, SuperscriptBox["\[CurlyEpsilon]", 
      TBox[FeynCalc`SharedObjectsTypesetting`Private`pol, 
       FeynCalc`SharedObjectsTypesetting`Private`dim]]]
 
FeynCalc`SharedObjectsTypesetting`Private`momentumRep[
     FeynCalc`SharedObjectsTypesetting`Private`p_, 
     FeynCalc`SharedObjectsTypesetting`Private`dim_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`dim === 4, 
     OverscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
       TraditionalForm], $TypesettingDim4], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol], 
     If[$TypesettingDimD === "", ToBoxes[
       FeynCalc`SharedObjectsTypesetting`Private`p, TraditionalForm], 
      OverscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
        TraditionalForm], $TypesettingDimD]], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, _Symbol - 4], 
     OverscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
       TraditionalForm], $TypesettingDimE], True, 
     SubscriptBox[ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`p, 
       TraditionalForm], ToBoxes[
       FeynCalc`SharedObjectsTypesetting`Private`dim, TraditionalForm]]]
 
TypesettingExplicitLorentzIndex = Function[FeynCalc`SharedObjects`Private`x, 
     FeynCalc`SharedObjects`Private`x]
 
TypesettingExplicitLorentzIndex /: TypesettingExplicitLorentzIndex::usage = "\
TypesettingExplicitLorentzIndex determines the TraditionalForm typesetting \
of\nexplicit Lorentz indices."
 
FeynCalc`SharedObjectsTypesetting`Private`metricRep[
     FeynCalc`SharedObjectsTypesetting`Private`dim_] := 
    Which[FeynCalc`SharedObjectsTypesetting`Private`dim === {4, 4}, 
     OverscriptBox["g", $TypesettingDim4], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, 
       {_Symbol, _Symbol}] && FeynCalc`SharedObjectsTypesetting`Private`dim[[
        1]] === FeynCalc`SharedObjectsTypesetting`Private`dim[[2]], 
     If[$TypesettingDimD === "", "g", OverscriptBox["g", $TypesettingDimD]], 
     MatchQ[FeynCalc`SharedObjectsTypesetting`Private`dim, 
       {_Symbol - 4, _Symbol - 4}] && 
      FeynCalc`SharedObjectsTypesetting`Private`dim[[1]] === 
       FeynCalc`SharedObjectsTypesetting`Private`dim[[2]], 
     OverscriptBox["g", $TypesettingDimE], True, SubscriptBox["g", 
      ToBoxes[FeynCalc`SharedObjectsTypesetting`Private`dim, 
       TraditionalForm]]]
 
