FeynCalc`PaVeReduce`Private`pavitp[FeynCalc`PaVeReduce`Private`xXX_PaVe, 
     FeynCalc`PaVeReduce`Private`dir_, FeynCalc`PaVeReduce`Private`opts:
      OptionsPattern[]] := Block[{FeynCalc`PaVeReduce`Private`nx, 
      Removed["file"], FeynCalc`PaVeReduce`Private`temp, 
      FeynCalc`PaVeReduce`Private`set, FeynCalc`PaVeReduce`Private`xxx, 
      FeynCalc`PaVeReduce`Private`a, FeynCalc`PaVeReduce`Private`abbs, 
      FeynCalc`PaVeReduce`Private`abbstr, FeynCalc`PaVeReduce`Private`dir1}, 
     FeynCalc`PaVeReduce`Private`paV[FeynCalc`PaVeReduce`Private`xy__, 
        FeynCalc`PaVeReduce`Private`p_List, 
        FeynCalc`PaVeReduce`Private`m_List, 
        FeynCalc`PaVeReduce`Private`paveopts:OptionsPattern[]] := 
       PaVe[FeynCalc`PaVeReduce`Private`xy, C, FeynCalc`PaVeReduce`Private`p, 
        C, FeynCalc`PaVeReduce`Private`m, 
        FeynCalc`PaVeReduce`Private`paveopts]; 
      FeynCalc`PaVeReduce`Private`xxx = FeynCalc`PaVeReduce`Private`paV @@ 
        FeynCalc`PaVeReduce`Private`xXX; FeynCalc`PaVeReduce`Private`nx = 
       StringJoin[FeynCalc`PaVeReduce`Private`dir, 
        FeynCalc`PaVeReduce`Private`nx, ".s"]; FCPrint[2, "nx  =", 
       FeynCalc`PaVeReduce`Private`nx, FCDoControl -> 
        FeynCalc`PaVeReduce`Private`pvrVerbose]; 
      If[Streams[FeynCalc`PaVeReduce`Private`nx] === {}, 
       Removed["file"] = FileType[FeynCalc`PaVeReduce`Private`nx]; 
        If[Removed["file"] === File, FCPrint[2, "file  =", Removed["file"]]; 
          FeynCalc`PaVeReduce`Private`temp = PaVeOrder[
            Get @@ {FeynCalc`PaVeReduce`Private`nx}]; 
          If[Head[FeynCalc`PaVeReduce`Private`temp] =!= Plus, 
           Removed["file"] = {}]]; If[Removed["file"] =!= File && 
          Removed["file"] =!= Directory, FeynCalc`PaVeReduce`Private`temp = 
           PaVeOrder[FixedPoint[ReleaseHold, PaVeReduce[
              FeynCalc`PaVeReduce`Private`xXX, WriteOutPaVe -> False, 
              FeynCalc`PaVeReduce`Private`opts]]]; FCPrint[2, 
           "writing result to ", FeynCalc`PaVeReduce`Private`nx, 
           FCDoControl -> FeynCalc`PaVeReduce`Private`pvrVerbose]; 
          OpenWrite @@ {FeynCalc`PaVeReduce`Private`nx, FormatType -> 
             InputForm}; WriteString @@ {FeynCalc`PaVeReduce`Private`nx, 
            "( "}; Write @@ {FeynCalc`PaVeReduce`Private`nx, 
            FeynCalc`PaVeReduce`Private`temp}; WriteString @@ 
           {FeynCalc`PaVeReduce`Private`nx, "  ) "}; 
          Close @@ {FeynCalc`PaVeReduce`Private`nx}; ], 
       FeynCalc`PaVeReduce`Private`temp = PaVeOrder[PaVeReduce[
           FeynCalc`PaVeReduce`Private`xXX, WriteOutPaVe -> False, 
           FeynCalc`PaVeReduce`Private`opts]]; ]; 
      FeynCalc`PaVeReduce`Private`temp]
 
FeynCalc`PaVeReduce`Private`pavereduce[FeynCalc`PaVeReduce`Private`exp_, 
     OptionsPattern[]] := FeynCalc`PaVeReduce`Private`exp /; 
     FreeQ2[FeynCalc`PaVeReduce`Private`exp, FeynCalc`Package`PaVeHeadsList]
 
FeynCalc`PaVeReduce`Private`pavereduce[FeynCalc`PaVeReduce`Private`w_, 
     FeynCalc`PaVeReduce`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`PaVeReduce`Private`mpa, FeynCalc`PaVeReduce`Private`nw, 
       FeynCalc`PaVeReduce`Private`nn, FeynCalc`PaVeReduce`Private`pre, 
       FeynCalc`PaVeReduce`Private`re = 0}, 
      FCPrint[3, "PaVeReduce: pavereduce: Entering with: ", 
        FeynCalc`PaVeReduce`Private`w, FCDoControl -> 
         FeynCalc`PaVeReduce`Private`pvrVerbose]; 
       FeynCalc`PaVeReduce`Private`mpa = FeynCalc`PaVeReduce`Private`w /. 
         StandardMatrixElement[__] -> 0; FeynCalc`PaVeReduce`Private`nw = 
        FeynCalc`PaVeReduce`Private`w - FeynCalc`PaVeReduce`Private`mpa; 
       FeynCalc`PaVeReduce`Private`re = 
        FeynCalc`PaVeReduce`Private`pavereduce[
         FeynCalc`PaVeReduce`Private`mpa, FeynCalc`PaVeReduce`Private`opts]; 
       If[Head[FeynCalc`PaVeReduce`Private`nw] === Plus, 
        FeynCalc`PaVeReduce`Private`nn = 
         Length[FeynCalc`PaVeReduce`Private`nw], 
        FeynCalc`PaVeReduce`Private`nn = 1]; 
       For[FeynCalc`PaVeReduce`Private`i = 1, 
        FeynCalc`PaVeReduce`Private`i <= FeynCalc`PaVeReduce`Private`nn, 
        FeynCalc`PaVeReduce`Private`i++, FCPrint[2, "breaking down # ", 
          FeynCalc`PaVeReduce`Private`i, " / ", 
          FeynCalc`PaVeReduce`Private`nn]; 
         If[FeynCalc`PaVeReduce`Private`nn === 1, 
          FeynCalc`PaVeReduce`Private`pre = FCSplit[
            FeynCalc`PaVeReduce`Private`nw, {StandardMatrixElement}], 
          FeynCalc`PaVeReduce`Private`pre = FCSplit[
            FeynCalc`PaVeReduce`Private`nw[[FeynCalc`PaVeReduce`Private`i]], 
            {StandardMatrixElement}]]; FeynCalc`PaVeReduce`Private`re = 
          FeynCalc`PaVeReduce`Private`re + FeynCalc`PaVeReduce`Private`pre[[
             2]]*FeynCalc`PaVeReduce`Private`pavereduce[
             FeynCalc`PaVeReduce`Private`pre[[1]], 
             FeynCalc`PaVeReduce`Private`opts]]; 
       FeynCalc`PaVeReduce`Private`re] /; 
      !FreeQ[FeynCalc`PaVeReduce`Private`w, StandardMatrixElement]
 
FeynCalc`PaVeReduce`Private`pavereduce[FeynCalc`PaVeReduce`Private`pvli_List, 
     FeynCalc`PaVeReduce`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`PaVeReduce`Private`i, FeynCalc`PaVeReduce`Private`set, 
      FeynCalc`PaVeReduce`Private`le = 
       Length[FeynCalc`PaVeReduce`Private`pvli], 
      FeynCalc`PaVeReduce`Private`npvli}, 
     FeynCalc`PaVeReduce`Private`npvli = {}; 
      FCPrint[3, "PaVeReduce: pavereduce: Entering with: ", 
       FeynCalc`PaVeReduce`Private`pvli, FCDoControl -> 
        FeynCalc`PaVeReduce`Private`pvrVerbose]; 
      Do[FCPrint[2, " Working with # ", FeynCalc`PaVeReduce`Private`i, 
         " out of ", FeynCalc`PaVeReduce`Private`le]; 
        FeynCalc`PaVeReduce`Private`npvli = 
         Append[FeynCalc`PaVeReduce`Private`npvli, 
          FeynCalc`PaVeReduce`Private`pavereduce[
           FeynCalc`PaVeReduce`Private`pvli[[FeynCalc`PaVeReduce`Private`i]], 
           FeynCalc`PaVeReduce`Private`opts]], 
       {FeynCalc`PaVeReduce`Private`i, FeynCalc`PaVeReduce`Private`le}]; 
      FeynCalc`PaVeReduce`Private`npvli]
 
FeynCalc`PaVeReduce`Private`pavereduce[FeynCalc`PaVeReduce`Private`brex_, 
     FeynCalc`PaVeReduce`Private`opts:OptionsPattern[]] := 
    Block[{FeynCalc`PaVeReduce`Private`t, FeynCalc`PaVeReduce`Private`mand, 
       FeynCalc`PaVeReduce`Private`result, FeynCalc`PaVeReduce`Private`ij, 
