       FeynCalc`PaVeReduce`Private`paveorderli, 
       FeynCalc`PaVeReduce`Private`breakx, 
       FeynCalc`PaVeReduce`Private`cofun2, FeynCalc`PaVeReduce`Private`cofun, 
       FeynCalc`PaVeReduce`Private`tvarS, 
       FeynCalc`PaVeReduce`Private`paveProtect}, 
      FCPrint[3, "PaVeReduce: pavereduce: Entering with: ", 
        FeynCalc`PaVeReduce`Private`brex, FCDoControl -> 
         FeynCalc`PaVeReduce`Private`pvrVerbose]; 
       FeynCalc`PaVeReduce`Private`paveorderli = OptionValue[PaVeReduce, 
         {FeynCalc`PaVeReduce`Private`opts}, PaVeOrderList]; 
       FeynCalc`PaVeReduce`Private`mand = OptionValue[PaVeReduce, 
         {FeynCalc`PaVeReduce`Private`opts}, Mandelstam]; 
       FeynCalc`PaVeReduce`Private`isok = OptionValue[PaVeReduce, 
         {FeynCalc`PaVeReduce`Private`opts}, IsolateNames]; 
       FeynCalc`PaVeReduce`Private`dimen = OptionValue[PaVeReduce, 
         {FeynCalc`PaVeReduce`Private`opts}, Dimension]; 
       If[FeynCalc`PaVeReduce`Private`dimen =!= True && $LimitTo4 =!= True, 
        FeynCalc`PaVeReduce`Private`$dIM = FeynCalc`PaVeReduce`Private`dimen, 
        FeynCalc`PaVeReduce`Private`$dIM = D]; 
       If[ !FreeQ[FeynCalc`PaVeReduce`Private`brex, PaVe], 
        FeynCalc`PaVeReduce`Private`breakx = 
         Collect[FeynCalc`PaVeReduce`Private`brex, PaVe[__]], 
        FeynCalc`PaVeReduce`Private`breakx = 
         FeynCalc`PaVeReduce`Private`brex]; 
       FeynCalc`PaVeReduce`Private`isolateP[
         FeynCalc`PaVeReduce`Private`x__] := 
        Isolate[FeynCalc`PaVeReduce`Private`x, IsolateNames -> 
          FeynCalc`PaVeReduce`Private`isok]; FeynCalc`PaVeReduce`Private`tri[
         (FeynCalc`PaVeReduce`Private`x_)*
          (FeynCalc`PaVeReduce`Private`y_)] := 
        FeynCalc`PaVeReduce`Private`tri[FeynCalc`PaVeReduce`Private`x]*
         FeynCalc`PaVeReduce`Private`tri[FeynCalc`PaVeReduce`Private`y]; 
       FeynCalc`PaVeReduce`Private`tri[(FeynCalc`PaVeReduce`Private`a_)*
          (FeynCalc`PaVeReduce`Private`x_)] := 
        FeynCalc`PaVeReduce`Private`a*FeynCalc`PaVeReduce`Private`tri[
           FeynCalc`PaVeReduce`Private`x] /; 
